/// Default minimum number of `vec4<u32>` slots in a statically-sized uniform CBV (`cb0`, `cb1`, ...).
/// Tightly sized to `1` (`16` bytes) so small Xbox Series CBVs (e.g. 48 B / 96 B) are never
/// over-declared as 256 B uniform blocks in WebGPU.
pub const DEFAULT_MIN_CBV_VEC4_COUNT: u32 = 1;

/// Minimum number of `vec4<u32>` slots (`256` bytes) emitted for a CBV that uses a dynamic/unknown
/// `soffset` where no upper bound is statically known.
pub const DEFAULT_DYNAMIC_CBV_VEC4_COUNT: u32 = 16;

/// Upper bound on `vec4<u32>` slots in a single CBV (1024 * 16B = 16 KiB, within WebGPU 64 KiB baseline).
pub const MAX_CBV_VEC4_COUNT: u32 = 1024;

/// Maximum inter-stage location count under WebGPU baseline limits.
const MAX_WEBGPU_LOCATIONS: u8 = 16;

/// Maximum user inter-stage `@location(N)` slots shared by VS/Mesh outputs and PS inputs
/// (`0..=14`, reserving 1 slot under `MAX_WEBGPU_LOCATIONS` for `@builtin(position)` / fragment
/// built-ins, matching `MAX_MESH_ATTRIBUTES = 15`).
const MAX_INTER_STAGE_LOCATIONS: u8 = MAX_WEBGPU_LOCATIONS - 1;

/// Maximum color attachment count under WebGPU baseline limits.
const MAX_WEBGPU_MRTS: u8 = 8;

/// WebGPU texture format enum code for `rgba8unorm` (`pso::WgpuTextureFormat::Rgba8Unorm`,
/// `docs/gpu_commands.md` / `runtime/gpu/stage_reflection.h`).
pub const WGPU_STORAGE_FORMAT_RGBA8_UNORM: u8 = 22;

/// Binding number offset applied to v3-sidecar-eligible fragment-stage bindings in `@group(0)` so
/// independently translated vertex (`0..127`) and fragment (`128..`) stages never collide on the
/// same `@group(0) @binding(N)` with different descriptor-table sources during `join_pipeline_layout`.
/// Runtime-owned `RT_ARENA` (`@group(3) @binding(16..21)`) and mesh output (`@group(3) @binding(0)`)
/// live in `@group(3)`, so `@group(0) @binding(128..)` has zero conflicts and clears real vertex
/// stages allocating up to `@binding(80)`.
const FRAGMENT_REFLECTED_BINDING_OFFSET: u32 = 128;

/// First extra binding index (`cb1`, `tex1`, `samp1`, `sbuf*`, `uav_tex*`) for unreflected
/// fragment stages, kept disjoint from vertex extra bindings (`3..15`) so `layout:'auto'`
/// never hits a vertex-vs-fragment binding type mismatch (e.g. buffer vs texture at `@binding(4)`).
const FRAGMENT_EXTRA_BINDING_BASE: u32 = 16;

/// Returns `true` iff `f` can be emitted directly as a WGSL `Literal::F32` without
/// risking Naga decimal rounding overflow past `f32::MAX` (which Chrome/Dawn Tint
/// rejects as unrepresentable), losing `-0.0`, or emitting subnormals / NaN / Inf.
///
/// Naga prints `f32::MAX` (`0x7f7fffff`, `3.4028234663852886e38`) rounded up to
/// `340282350000000000000000000000000000000f` (`3.4028235e38 > f32::MAX`), which
/// Tint rejects. Any finite float with `|f| >= 3.4e38` (including `f32::MAX`,
/// `-f32::MAX`, `0x7f7ffffe`, etc.) routes through `pg6_u32_bits_to_float(bits)`
/// for an exact IEEE-754 bitcast that Tint accepts unconditionally.
#[inline]
fn is_safe_wgsl_f32_literal(f: f32) -> bool {
    f.to_bits() == 0 || (f.is_finite() && f.is_normal() && f.abs() < 3.4e38_f32)
}

/// Pack-key XOR salt for mesh shaders translated to WebGPU compute (`"MSCS"`, matching
/// `runtime/gpu/state_bridge.h` `bridge::kMeshComputeKeySalt`).
pub const MESH_COMPUTE_KEY_SALT: u64 = 0x4d53_4353_0000_0000;

/// Compute the WGPK v1 / sidecar pack key of a mesh stage's compute translation
/// (`ms_key ^ MESH_COMPUTE_KEY_SALT`, matching `bridge::mesh_compute_pack_key`).
#[inline]
pub const fn mesh_compute_pack_key(mesh_stage_key: u64) -> u64 {
    mesh_stage_key ^ MESH_COMPUTE_KEY_SALT
}

/// Maximum vertices per mesh workgroup supported by the runtime contract (`state_bridge.h`).
pub const MAX_MESH_VERTICES: u32 = 256;

/// Maximum triangle primitives per mesh workgroup supported by the runtime contract (`state_bridge.h`).
pub const MAX_MESH_PRIMITIVES: u32 = 256;

/// Maximum per-vertex `vec4<f32>` attribute locations after `SV_Position` (`bridge::kMaxMeshAttributes`).
pub const MAX_MESH_ATTRIBUTES: u32 = 15;

/// Runtime-owned bind group reserved for the mesh output buffer (`bridge::kMeshOutputGroup`).
pub const MESH_OUTPUT_GROUP: u32 = 3;

/// Per-group output record layout for a mesh stage translated to compute (`state_bridge.h`
/// `bridge::MeshOutputLayout`, `stage_reflection.cpp` `"mesh_output"`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MeshOutputLayout {
    pub max_vertices: u32,
    pub max_primitives: u32,
    pub vertex_words: u32,
}

impl MeshOutputLayout {
    /// Validate bounds matching `bridge::valid_mesh_output_layout` (`state_bridge.cpp`).
    #[inline]
    pub const fn is_valid(self) -> bool {
        self.max_vertices >= 1
            && self.max_vertices <= MAX_MESH_VERTICES
            && self.max_primitives >= 1
            && self.max_primitives <= MAX_MESH_PRIMITIVES
            && self.vertex_words >= 4
            && self.vertex_words.is_multiple_of(4)
            && self.vertex_words <= 4 + 4 * MAX_MESH_ATTRIBUTES
    }

    /// Total `u32` words in one mesh group's output record (`bridge::mesh_group_record_words`).
    #[inline]
    pub const fn group_record_words(self) -> u32 {
        4 + self.max_vertices * self.vertex_words + self.max_primitives * 3
    }

    /// Word offset of the triangle index table within a group record (`INDEX_BASE`).
    #[inline]
    pub const fn index_base_words(self) -> u32 {
        4 + self.max_vertices * self.vertex_words
    }

    /// Number of `vec4<f32>` attribute locations carried after `SV_Position` (`0..=15`).
    #[inline]
    pub const fn attribute_count(self) -> u32 {
        if self.vertex_words >= 4 {
            (self.vertex_words - 4) / 4
        } else {
            0
        }
    }
}

/// Write a `MeshOutputLayout` as compact JSON matching `stage_reflection.cpp` `"mesh_output"`.
pub(crate) fn write_mesh_output_json(out: &mut String, layout: MeshOutputLayout) {
    let _ = write!(
        out,
        "{{\"max_vertices\": {}, \"max_primitives\": {}, \"vertex_words\": {}}}",
        layout.max_vertices, layout.max_primitives, layout.vertex_words
    );
}

/// Stage override option for [`translate_rdna2_to_wgsl`].
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum Rdna2StageOverride {
    #[default]
    Auto,
    Vertex,
    Pixel,
    Compute,
    Mesh,
}

impl Rdna2StageOverride {
    /// Parse a CLI stage flag value (`auto`, `vertex`, `pixel`, `fragment`, `compute`, `mesh`).
    pub fn parse_str(value: &str) -> Result<Self, String> {
        match value.to_ascii_lowercase().as_str() {
            "auto" => Ok(Self::Auto),
            "vertex" | "vs" => Ok(Self::Vertex),
            "pixel" | "fragment" | "ps" | "fs" => Ok(Self::Pixel),
            "compute" | "cs" => Ok(Self::Compute),
            "mesh" | "ms" => Ok(Self::Mesh),
            other => Err(format!(
                "invalid --stage value '{other}' (expected 'auto', 'vertex', 'pixel', 'compute', or 'mesh')"
            )),
        }
    }

    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Auto => "auto",
            Self::Vertex => "vertex",
            Self::Pixel => "pixel",
            Self::Compute => "compute",
            Self::Mesh => "mesh",
        }
    }
}

impl fmt::Display for Rdna2StageOverride {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

/// Default compute workgroup dimensions (`@workgroup_size(64, 1, 1)`).
pub const DEFAULT_COMPUTE_WORKGROUP_SIZE: [u32; 3] = [64, 1, 1];

/// LDS workgroup shared memory size in 32-bit dwords (`4096 * 4 = 16 KiB`).
const LDS_WORKGROUP_DWORDS: u32 = 4096;

/// Mask applied to LDS dword indices (`4095 = 0x0FFF`) so workgroup memory accesses never trap.
const LDS_WORKGROUP_INDEX_MASK: u32 = LDS_WORKGROUP_DWORDS - 1;

/// One vertex input element entry parsed from an Xbox Series `FSSM` VS metadata table
/// (`vs_rec + 0x54 + 0x24`, 5 bytes/entry, count at `vs_rec + 0x54 + 0xc4`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct FssmVertexInput {
    /// DXBC `ISG1` input signature register index (`rec[1]`).
    pub semantic_reg: u8,
    /// 4-bit active component bitmask (`rec[2]`, e.g. `0x7` = xyz, `0xf` = xyzw, `0x3` = xy).
    pub mask: u8,
    /// Starting VGPR populated by the driver-generated fetch shader (`rec[3]`, e.g. `4`, `8`, `12`).
    pub base_vgpr: u8,
    /// Highest active component index `0..=3` (`rec[4]`).
    pub max_comp: u8,
}

/// Inter-stage parameter semantic mapping entry extracted from Xbox Series `FSSM` stage metadata
/// (used for `OSG1` <-> `ISG1` / `SPI_PS_INPUT_CNTL` `@location` remapping).
///
/// * On a vertex stage (`vs_outputs`): maps `OSG1` `semantic_reg` -> `exp param<location>`.
/// * On a fragment stage (`ps_inputs`): maps `ISG1` `semantic_reg` -> `v_interp attr<location>`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct WgslStageParamInfo {
    pub semantic_reg: u8,
    pub location: u32,
    pub mask: Option<u8>,
}

/// Parsed Xbox Series `FSSM` stage metadata (from a `.meta` sidecar or embedded native blob).
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct FssmStageMetadata {
    /// FSSM VS fetch-shader input assignments (`s_swappc_b64`).
    pub vs_inputs: Vec<FssmVertexInput>,
    /// FSSM VS output parameter semantic map (`OSG1` `semantic_reg` -> `exp param<location>`).
    pub vs_outputs: Vec<WgslStageParamInfo>,
    /// FSSM PS input parameter semantic map (`ISG1` `semantic_reg` -> `v_interp attr<location>`).
    pub ps_inputs: Vec<WgslStageParamInfo>,
}

/// Parse an Xbox Series `FSSM` (`version == 0x101`) metadata blob into [`FssmStageMetadata`].
///
/// Strictly bounds-checked and panic-free on arbitrary, truncated, or non-FSSM inputs; returns
/// `None` if the bytes do not form a valid `FSSM` v0x101 container.
pub fn parse_fssm_stage_metadata(bytes: &[u8]) -> Option<FssmStageMetadata> {
    const FSSM_HEADER: usize = 0x10;
    const FSSM_VERSION: u32 = 0x101;
    const FSSM_GRAPHICS_SLOTS: u64 = 6;
    const FSSM_ABSENT: u64 = 0xDEAD_BEEF_DEAD_BEEF;
    const FSSM_RECORD_BYTES: usize = 0x54;
    const FSSM_MAX_TABLE_ENTRIES: usize = 32;

    let read_u32 = |buf: &[u8], off: usize| -> Option<u32> {
        let slice = buf.get(off..off.checked_add(4)?)?;
        Some(u32::from_le_bytes([slice[0], slice[1], slice[2], slice[3]]))
    };
    let read_u64 = |buf: &[u8], off: usize| -> Option<u64> {
        let slice = buf.get(off..off.checked_add(8)?)?;
        Some(u64::from_le_bytes([
            slice[0], slice[1], slice[2], slice[3], slice[4], slice[5], slice[6], slice[7],
        ]))
    };

    if bytes.len() < FSSM_HEADER + 0x68 || bytes.get(0..4)? != b"FSSM" {
        return None;
    }
    if read_u32(bytes, 4)? != FSSM_VERSION {
        return None;
    }
    let pl = bytes.get(FSSM_HEADER..)?;
    if read_u64(bytes, 8)? != pl.len() as u64 {
        return None;
    }
    if read_u64(pl, 0)? != FSSM_GRAPHICS_SLOTS {
        return None;
    }

    let mut meta = FssmStageMetadata::default();

    // VS slot at pl + 0x28
    let vs_rec_u64 = read_u64(pl, 0x28)?;
    if vs_rec_u64 != FSSM_ABSENT
        && let Ok(vs_rec) = usize::try_from(vs_rec_u64)
        && let Some(ext) = vs_rec.checked_add(FSSM_RECORD_BYTES)
    {
        if let Some(in_cnt_raw) = read_u32(pl, ext.checked_add(0xc4)?) {
            let in_cnt = (in_cnt_raw as usize).min(FSSM_MAX_TABLE_ENTRIES);
            if let Some(table_start) = ext.checked_add(0x24)
                && let Some(table_end) = table_start.checked_add(in_cnt * 5)
                && let Some(table) = pl.get(table_start..table_end)
            {
                for chunk in table.chunks_exact(5) {
                    let mask = chunk[2] & 0x0F;
                    if chunk[0] == 0 && mask == 0 {
                        continue;
                    }
                    meta.vs_inputs.push(FssmVertexInput {
                        semantic_reg: chunk[1],
                        mask,
                        base_vgpr: chunk[3],
                        max_comp: chunk[4].min(3),
                    });
                }
            }
        }
        if let Some(out_cnt_raw) = read_u32(pl, ext.checked_add(0x188)?) {
            let out_cnt = (out_cnt_raw as usize).min(FSSM_MAX_TABLE_ENTRIES);
            if let Some(table_start) = ext.checked_add(0xc8)
                && let Some(table_end) = table_start.checked_add(out_cnt * 6)
                && let Some(table) = pl.get(table_start..table_end)
            {
                for chunk in table.chunks_exact(6) {
                    if chunk[0] == 0 {
                        continue;
                    }
                    meta.vs_outputs.push(WgslStageParamInfo {
                        semantic_reg: chunk[1],
                        location: u32::from(chunk[2]),
                        mask: None,
                    });
                }
            }
        }
    }

    // PS slot at pl + 0x30
    let ps_rec_u64 = read_u64(pl, 0x30)?;
    if ps_rec_u64 != FSSM_ABSENT
        && let Ok(ps_rec) = usize::try_from(ps_rec_u64)
        && let Some(ext) = ps_rec.checked_add(FSSM_RECORD_BYTES)
        && let Some(in_cnt_raw) = read_u32(pl, ext.checked_add(0x124)?)
    {
        let in_cnt = (in_cnt_raw as usize).min(FSSM_MAX_TABLE_ENTRIES);
        if let Some(table_start) = ext.checked_add(0x24)
            && let Some(table_end) = table_start.checked_add(in_cnt * 8)
            && let Some(table) = pl.get(table_start..table_end)
        {
            for chunk in table.chunks_exact(8) {
                if chunk[0] == 0 {
                    continue;
                }
                meta.ps_inputs.push(WgslStageParamInfo {
                    semantic_reg: chunk[1],
                    location: u32::from(chunk[3]),
                    mask: Some(chunk[2] & 0x0F),
                });
            }
        }
    }

    Some(meta)
}

/// Options controlling RDNA2 -> WGSL translation.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Rdna2TranslateOptions {
    /// Pipeline stage selection (`Auto` infers from `EXP`/`VINTRP`/memory instructions).
    pub stage: Rdna2StageOverride,
    /// Optional explicit WGSL entry-point name (defaults to `vs_main`/`fs_main`/`cs_main`).
    pub entry_point: Option<String>,
    /// Minimum number of `vec4<u32>` entries emitted when `cb0` uniform buffer is needed.
    pub min_cbv_vec4_count: u32,
    /// Workgroup size `(X, Y, Z)` for `ShaderStage::Compute` (defaults to `[64, 1, 1]`).
    pub workgroup_size: [u32; 3],
    /// Optional base SGPR index for seeding `(wg_id.x, wg_id.y, wg_id.z)` in compute shaders.
    /// When `None`, defaults to `s0`/`s1`/`s2` for SGPRs read before being written.
    pub workgroup_id_sgpr_base: Option<u8>,
    /// Preserve per-attribute RDNA2 `v_interp_*` interpolation qualifiers (`@interpolate(flat)`,
    /// `linear`, `centroid`) on `FragIn` `vec4<f32>` inputs.
    ///
    /// Defaults to `false` for WebGPU `CreateRenderPipeline` compatibility: RDNA2 vertex shaders
    /// carry no interpolation metadata, so independently translated `VsOut` (and mesh draw VS)
    /// always emits default `perspective, center` interpolation. Emitting non-default `@interpolate`
    /// on `FragIn` causes Dawn/Tint to reject the VS↔PS pipeline interface.
    pub preserve_fragment_interpolation: bool,
    /// Optional parsed Xbox Series `FSSM` stage metadata (from a `.meta` sidecar) supplying exact
    /// `s_swappc_b64` vertex fetch VGPR assignments and inter-stage `OSG1`/`ISG1` semantic maps.
    pub fssm_meta: Option<FssmStageMetadata>,
    /// Wave lowering mode for RDNA2 cross-lane operations (`#2178`).
    ///
    /// Defaults to [`WaveEmulMode::WorkgroupLds`] so baseline WebGPU adapters without the
    /// optional `subgroups` feature remain 100% supported.
    pub wave_emul_mode: WaveEmulMode,
}

impl Default for Rdna2TranslateOptions {
    fn default() -> Self {
        Self {
            stage: Rdna2StageOverride::Auto,
            entry_point: None,
            min_cbv_vec4_count: DEFAULT_MIN_CBV_VEC4_COUNT,
            workgroup_size: DEFAULT_COMPUTE_WORKGROUP_SIZE,
            workgroup_id_sgpr_base: None,
            preserve_fragment_interpolation: false,
            fssm_meta: None,
            wave_emul_mode: WaveEmulMode::WorkgroupLds,
        }
    }
}

/// Maximum descriptor-window size for per-lane bindless heap reflection (`stage_reflection.h`
/// `kMaxLaneIndexedWindow`, `stage_reflection_sidecar.py` `MAX_LANE_INDEXED_WINDOW`).
pub const MAX_LANE_INDEXED_WINDOW: u32 = 256;

/// Conservative default descriptor-window size when a per-lane VGPR heap index has no statically
/// inferable bitmask/clamp upper bound (strictly within `1..=MAX_LANE_INDEXED_WINDOW`).
pub const DEFAULT_LANE_INDEXED_WINDOW: u32 = 64;

/// Constant-buffer origin holding a 32-bit bindless descriptor-heap index dword
/// (`cbv_indexed_resource_heap` / `cbv_indexed_sampler_heap`, G62 / #482 / #1383).
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum CbvRefSource {
    /// 64-bit Root CBV GPU VA starting at `user_sgpr`.
    RootDescriptor { user_sgpr: u32 },
    /// CBV V# in a CBV_SRV_UAV descriptor table at `user_sgpr` + `table_byte_offset` (multiple of 32).
    Table {
        user_sgpr: u32,
        table_byte_offset: u32,
    },
    /// Root constants starting at `user_sgpr`.
    RootConstants { user_sgpr: u32 },
}

/// Constant-buffer 32-bit dword origin (`(dword_at(cbv, byte_offset) >> bit_offset) & mask`),
/// used as the optional `window_base` of [`LaneIndexedHeapSource`] (G62 / S63 / #482 / #1394).
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct CbvDwordSource {
    pub cbv: CbvRefSource,
    pub byte_offset: u32,
    pub bit_offset: u32,
    pub mask: u32,
}

/// SM 6.6 CB-indexed descriptor-heap binding origin (`#482` / `#1383`).
///
/// The runtime computes the 32-bit wrapping heap byte offset as
/// `((dword_at(cbv, byte_offset) >> bit_offset) & mask) << shift`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct CbvIndexedHeapSource {
    pub cbv: CbvRefSource,
    pub byte_offset: u32,
    pub shift: u32,
    pub bit_offset: u32,
    pub mask: u32,
    pub stride: u32,
}

/// SM 6.6 per-lane (VGPR / `v_readfirstlane_b32` waterfall) descriptor-heap binding origin
/// (`lane_indexed_resource_heap` / `lane_indexed_sampler_heap`, G62 / S63 / #482 / #1394).
///
/// Element `k` of the window (`0 <= k < max_count`) is the descriptor at byte offset
/// `(window_base + k) << shift` of the bound heap (`window_base = 0` when `None`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct LaneIndexedHeapSource {
    pub max_count: u32,
    pub shift: u32,
    pub stride: u32,
    pub window_base: Option<CbvDwordSource>,
}

/// Origin of a reflected binding in console user-data SGPRs or static samplers
/// (`runtime/gpu/stage_reflection.h` / `tools/stage_reflection_sidecar.py`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum WgslBindingSource {
    /// Descriptor loaded from a descriptor table whose 32-bit pointer lives in `user_sgpr`
    /// (s8+ for graphics, s4+ for compute) at `table_byte_offset` bytes into the table.
    Table {
        user_sgpr: u32,
        table_byte_offset: u32,
    },
    /// Root constants starting at `user_sgpr`.
    RootConstants { user_sgpr: u32 },
    /// Root CBV/SRV/UAV descriptor (64-bit GPU VA) starting at `user_sgpr`, with optional
    /// v2 `table_byte_offset` (multiple of 32) when the user SGPR is a 32-bit descriptor-table
    /// pointer loading a specific table slot (#482 / #1471).
    RootDescriptor {
        user_sgpr: u32,
        table_byte_offset: Option<u32>,
    },
    /// Inline static sampler S# materialized directly in SGPRs (0-based index in stage order;
    /// fallback when any of the 4 S# descriptor words is not statically known).
    StaticSampler { index: u32 },
    /// Inline GFX10 S# sampler whose 4 descriptor dwords are statically known constants (#482 / #950).
    InlineSampler { sdwords: [u32; 4] },
    /// SM 6.6 `SamplerDescriptorHeap[index]` (`SAMPLER_HEAP_DIRECTLY_INDEXED`, 0x800):
    /// 16-byte S# loaded from heap base in `base_user_sgpr` at byte offset derived from `index_user_sgpr`.
    SamplerHeap {
        base_user_sgpr: u32,
        stride: u32,
        index_user_sgpr: u32,
        index_shift: u32,
    },
    /// SM 6.6 `ResourceDescriptorHeap[index]` (`CBV_SRV_UAV_HEAP_DIRECTLY_INDEXED`, 0x400):
    /// V#/T# loaded from heap base in `base_user_sgpr` at byte offset derived from `index_user_sgpr`.
    ResourceHeap {
        base_user_sgpr: u32,
        stride: u32,
        index_user_sgpr: u32,
        index_shift: u32,
    },
    /// SM 6.6 `ResourceDescriptorHeap[cb[byte_offset]]` (G62 / #482 / #1383).
    CbvIndexedResourceHeap(CbvIndexedHeapSource),
    /// SM 6.6 `SamplerDescriptorHeap[cb[byte_offset]]` (G62 / #482 / #1383).
    CbvIndexedSamplerHeap(CbvIndexedHeapSource),
    /// SM 6.6 `ResourceDescriptorHeap[NonUniformResourceIndex(i)]` (G62 / S63 / #482 / #1394).
    LaneIndexedResourceHeap(LaneIndexedHeapSource),
    /// SM 6.6 `SamplerDescriptorHeap[NonUniformResourceIndex(i)]` (G62 / S63 / #482 / #1394).
    LaneIndexedSamplerHeap(LaneIndexedHeapSource),
}

/// Reflected vertex input attribute fetched by a vertex stage (`stage_reflection.h`).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct WgslVertexInputInfo {
    pub location: u32,
    pub vb_slot: u32,
    pub byte_offset: u32,
    pub components: u8,
    pub component_type: &'static str,
    pub fetch_format: Option<&'static str>,
}

/// Explicit WebGPU `@group(group) @binding(binding)` resource declaration emitted in a
/// translated WGSL module.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct WgslBindingInfo {
    pub group: u32,
    pub binding: u32,
    pub kind: &'static str,
    pub name: String,
    /// Texture view dimension (`"2d"`, `"2d-array"`, etc.) for texture/storage-texture bindings.
    pub view_dimension: Option<&'static str>,
    /// WebGPU texture format enum code for storage textures (e.g. `22` = `rgba8unorm`).
    pub storage_format: Option<u8>,
    /// Minimum WebGPU uniform buffer binding size in bytes (`Some(N * 16)` for `"uniform"`
    /// bindings, `None` for non-buffer bindings such as textures and samplers).
    pub min_binding_size_bytes: Option<u32>,
    /// Highest `vec4` index statically read from this uniform CBV (`Some(max_vec4_index)` for
    /// `"uniform"` bindings, `None` for non-buffer bindings).
    pub highest_vec4_offset: Option<u32>,
    /// Descriptor origin in console user-data SGPRs or static samplers when statically known.
    pub source: Option<WgslBindingSource>,
}

fn write_cbv_ref_json(out: &mut String, cbv: CbvRefSource) {
    match cbv {
        CbvRefSource::RootDescriptor { user_sgpr } => {
            let _ = write!(
                out,
                "{{\"user_sgpr\": {user_sgpr}, \"root_descriptor\": true}}"
            );
        }
        CbvRefSource::Table {
            user_sgpr,
            table_byte_offset,
        } => {
            let _ = write!(
                out,
                "{{\"user_sgpr\": {user_sgpr}, \"table_byte_offset\": {table_byte_offset}}}"
            );
        }
        CbvRefSource::RootConstants { user_sgpr } => {
            let _ = write!(
                out,
                "{{\"user_sgpr\": {user_sgpr}, \"root_constants\": true}}"
            );
        }
    }
}

/// Write a JSON array of [`WgslBindingInfo`] entries with the given leading indentation.
pub(crate) fn write_wgsl_bindings_json(
    out: &mut String,
    bindings: &[WgslBindingInfo],
    indent: &str,
) {
    if bindings.is_empty() {
        out.push_str("[]");
        return;
    }
    out.push_str("[\n");
    for (i, b) in bindings.iter().enumerate() {
        let _ = write!(
            out,
            "{indent}  {{\"group\": {}, \"binding\": {}, \"kind\": ",
            b.group, b.binding
        );
        write_json_string(out, b.kind);
        out.push_str(", \"name\": ");
        write_json_string(out, &b.name);
        if let Some(dim) = b.view_dimension {
            out.push_str(", \"view_dimension\": ");
            write_json_string(out, dim);
        }
        if let Some(fmt) = b.storage_format {
            let _ = write!(out, ", \"storage_format\": {fmt}");
        }
        if let Some(min_bytes) = b.min_binding_size_bytes {
            let _ = write!(out, ", \"min_binding_size_bytes\": {min_bytes}");
        }
        if let Some(highest_vec4) = b.highest_vec4_offset {
            let _ = write!(out, ", \"highest_vec4_offset\": {highest_vec4}");
        }
        if let Some(src) = b.source {
            out.push_str(", \"source\": ");
            match src {
                WgslBindingSource::Table {
                    user_sgpr,
                    table_byte_offset,
                } => {
                    let _ = write!(
                        out,
                        "{{\"user_sgpr\": {user_sgpr}, \"table_byte_offset\": {table_byte_offset}}}"
                    );
                }
                WgslBindingSource::RootConstants { user_sgpr } => {
                    let _ = write!(
                        out,
                        "{{\"user_sgpr\": {user_sgpr}, \"root_constants\": true}}"
                    );
                }
                WgslBindingSource::RootDescriptor {
                    user_sgpr,
                    table_byte_offset,
                } => {
                    if let Some(off) = table_byte_offset {
                        let _ = write!(
                            out,
                            "{{\"user_sgpr\": {user_sgpr}, \"root_descriptor\": true, \"table_byte_offset\": {off}}}"
                        );
                    } else {
                        let _ = write!(
                            out,
                            "{{\"user_sgpr\": {user_sgpr}, \"root_descriptor\": true}}"
                        );
                    }
                }
                WgslBindingSource::StaticSampler { index } => {
                    let _ = write!(out, "{{\"static_sampler\": {index}}}");
                }
                WgslBindingSource::InlineSampler { sdwords } => {
                    let _ = write!(
                        out,
                        "{{\"inline_sampler\": {{\"sdwords\": [{}, {}, {}, {}]}}}}",
                        sdwords[0], sdwords[1], sdwords[2], sdwords[3]
                    );
                }
                WgslBindingSource::SamplerHeap {
                    base_user_sgpr,
                    stride,
                    index_user_sgpr,
                    index_shift,
                } => {
                    let _ = write!(
                        out,
                        "{{\"sampler_heap\": {{\"base_user_sgpr\": {base_user_sgpr}, \"stride\": {stride}, \"index\": {{\"user_sgpr\": {index_user_sgpr}, \"shift\": {index_shift}}}}}}}"
                    );
                }
                WgslBindingSource::ResourceHeap {
                    base_user_sgpr,
                    stride,
                    index_user_sgpr,
                    index_shift,
                } => {
                    let _ = write!(
                        out,
                        "{{\"resource_heap\": {{\"base_user_sgpr\": {base_user_sgpr}, \"stride\": {stride}, \"index\": {{\"user_sgpr\": {index_user_sgpr}, \"shift\": {index_shift}}}}}}}"
                    );
                }
                WgslBindingSource::CbvIndexedResourceHeap(h)
                | WgslBindingSource::CbvIndexedSamplerHeap(h) => {
                    let key_name = if matches!(src, WgslBindingSource::CbvIndexedSamplerHeap(_)) {
                        "cbv_indexed_sampler_heap"
                    } else {
                        "cbv_indexed_resource_heap"
                    };
                    let _ = write!(out, "{{\"{key_name}\": {{\"cbv\": ");
                    write_cbv_ref_json(out, h.cbv);
                    let _ = write!(
                        out,
                        ", \"byte_offset\": {}, \"shift\": {}",
                        h.byte_offset, h.shift
                    );
                    if h.bit_offset != 0 {
                        let _ = write!(out, ", \"bit_offset\": {}", h.bit_offset);
                    }
                    if h.mask != u32::MAX {
                        let _ = write!(out, ", \"mask\": {}", h.mask);
                    }
                    if h.stride != 0 {
                        let _ = write!(out, ", \"stride\": {}", h.stride);
                    }
                    out.push_str("}}");
                }
                WgslBindingSource::LaneIndexedResourceHeap(h)
                | WgslBindingSource::LaneIndexedSamplerHeap(h) => {
                    let key_name = if matches!(src, WgslBindingSource::LaneIndexedSamplerHeap(_)) {
                        "lane_indexed_sampler_heap"
                    } else {
                        "lane_indexed_resource_heap"
                    };
                    let _ = write!(
                        out,
                        "{{\"{key_name}\": {{\"max_count\": {}, \"shift\": {}",
                        h.max_count, h.shift
                    );
                    if h.stride != 0 {
                        let _ = write!(out, ", \"stride\": {}", h.stride);
                    }
                    if let Some(base) = h.window_base {
                        out.push_str(", \"window_base\": {\"cbv\": ");
                        write_cbv_ref_json(out, base.cbv);
                        let _ = write!(out, ", \"byte_offset\": {}", base.byte_offset);
                        if base.bit_offset != 0 {
                            let _ = write!(out, ", \"bit_offset\": {}", base.bit_offset);
                        }
                        if base.mask != u32::MAX {
                            let _ = write!(out, ", \"mask\": {}", base.mask);
                        }
                        out.push('}');
                    }
                    out.push_str("}}");
                }
            }
        }
        out.push('}');
        if i + 1 < bindings.len() {
            out.push(',');
        }
        out.push('\n');
    }
    out.push_str(indent);
    out.push(']');
}

/// Write a JSON array of [`WgslVertexInputInfo`] entries with the given leading indentation.
pub(crate) fn write_wgsl_vertex_inputs_json(
    out: &mut String,
    inputs: &[WgslVertexInputInfo],
    indent: &str,
) {
    if inputs.is_empty() {
        out.push_str("[]");
        return;
    }
    out.push_str("[\n");
    for (i, v) in inputs.iter().enumerate() {
        let _ = write!(
            out,
            "{indent}  {{\"location\": {}, \"vb_slot\": {}, \"byte_offset\": {}, \"components\": {}, \"component_type\": ",
            v.location, v.vb_slot, v.byte_offset, v.components
        );
        write_json_string(out, v.component_type);
        if let Some(fmt) = v.fetch_format {
            out.push_str(", \"fetch_format\": ");
            write_json_string(out, fmt);
        }
        out.push('}');
        if i + 1 < inputs.len() {
            out.push(',');
        }
        out.push('\n');
    }
    out.push_str(indent);
    out.push(']');
}

/// Write a JSON array of [`WgslStageParamInfo`] entries with the given leading indentation.
pub(crate) fn write_wgsl_stage_params_json(
    out: &mut String,
    params: &[WgslStageParamInfo],
    indent: &str,
) {
    if params.is_empty() {
        out.push_str("[]");
        return;
    }
    out.push_str("[\n");
    for (i, p) in params.iter().enumerate() {
        let _ = write!(
            out,
            "{indent}  {{\"semantic_reg\": {}, \"location\": {}",
            p.semantic_reg, p.location
        );
        if let Some(mask) = p.mask {
            let _ = write!(out, ", \"mask\": {mask}");
        }
        out.push('}');
        if i + 1 < params.len() {
            out.push(',');
        }
        out.push('\n');
    }
    out.push_str(indent);
    out.push(']');
}

/// Summary of WebGPU bindings and stage I/O synthesized for a translated RDNA2 shader.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct Rdna2BindingSummary {
    pub has_cbv: bool,
    pub cbv_vec4_count: u32,
    pub has_texture_2d: bool,
    pub has_sampler: bool,
    pub has_storage_buffer: bool,
    pub has_storage_texture: bool,
    pub has_lds: bool,
    pub vertex_input_mode: String,
    pub fragment_input_locations: Vec<u32>,
    pub output_locations: Vec<u32>,
    pub exports_position: bool,
    pub exports_depth: bool,
}

/// Runtime-owned RT WGSL prelude contract version (`runtime/gpu/rt_bvh.h::kPreludeVersion`).
pub const RT_PRELUDE_VERSION: u32 = 1;

/// Result of translating an RDNA2 binary shader into validated WebGPU WGSL.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Rdna2WgslOutput {
    pub wgsl: String,
    pub stage: ShaderStage,
    pub entry_point: String,
    pub hash_fnv1a64: u64,
    pub translated_op_count: usize,
    pub unsupported_op_count: usize,
    pub naga_validated: bool,
    pub bindings: Vec<WgslBindingInfo>,
    pub vertex_inputs: Vec<WgslVertexInputInfo>,
    /// Optional VS inter-stage output semantic mapping (`OSG1` `semantic_reg` -> `@location(N)`).
    pub vs_outputs: Vec<WgslStageParamInfo>,
    /// Optional PS inter-stage input semantic mapping (`ISG1` `semantic_reg` -> `@location(N)`).
    pub ps_inputs: Vec<WgslStageParamInfo>,
    pub mesh_output: Option<MeshOutputLayout>,
    pub rt_arena: bool,
    pub rt_prelude_version: Option<u32>,
    pub bvh_ops: u32,
    pub raw_address: bool,
    pub atomic64: bool,
    /// `true` when hardware WebGPU `subgroups` (`enable subgroups;`) operations were emitted.
    pub uses_subgroups: bool,
    pub binding_summary: Rdna2BindingSummary,
    pub binding_pack: BindingPackStats,
    pub ir_opt: IrOptStats,
}

impl Rdna2WgslOutput {
    /// Render a strictly sanitized deterministic JSON summary (zero host paths, zero raw bytes).
    pub fn to_json(&self) -> String {
        self.to_json_with_source(None)
    }

    /// Render a strictly sanitized deterministic JSON summary with an optional sanitized source basename.
    pub fn to_json_with_source(&self, source_name: Option<&str>) -> String {
        let mut out = String::new();
        out.push_str("{\n");
        out.push_str("  \"isa\": \"rdna2_gfx10_3\",\n");
        if let Some(src) = source_name {
            out.push_str("  \"source\": ");
            write_json_string(&mut out, src);
            out.push_str(",\n");
        }
        out.push_str("  \"hash_fnv1a64\": ");
        write_json_string(&mut out, &format_shader_hash(self.hash_fnv1a64));
        out.push_str(",\n");
        out.push_str("  \"stage\": ");
        write_json_string(&mut out, self.stage.as_str());
        out.push_str(",\n");
        out.push_str("  \"entry_point\": ");
        write_json_string(&mut out, &self.entry_point);
        out.push_str(",\n");
        let _ = writeln!(
            out,
            "  \"translated_op_count\": {},",
            self.translated_op_count
        );
        let _ = writeln!(
            out,
            "  \"unsupported_op_count\": {},",
            self.unsupported_op_count
        );
        let _ = writeln!(out, "  \"naga_validated\": {},", self.naga_validated);
        let _ = writeln!(out, "  \"wgsl_byte_len\": {},", self.wgsl.len());

        // Explicit WGSL @group/@binding map
        out.push_str("  \"bindings\": ");
        write_wgsl_bindings_json(&mut out, &self.bindings, "  ");
        out.push_str(",\n");

        if !self.vertex_inputs.is_empty() {
            out.push_str("  \"vertex_inputs\": ");
            write_wgsl_vertex_inputs_json(&mut out, &self.vertex_inputs, "  ");
            out.push_str(",\n");
        }
        if !self.vs_outputs.is_empty() {
            out.push_str("  \"vs_outputs\": ");
            write_wgsl_stage_params_json(&mut out, &self.vs_outputs, "  ");
            out.push_str(",\n");
        }
        if !self.ps_inputs.is_empty() {
            out.push_str("  \"ps_inputs\": ");
            write_wgsl_stage_params_json(&mut out, &self.ps_inputs, "  ");
            out.push_str(",\n");
        }

        if let Some(mesh_output) = self.mesh_output {
            out.push_str("  \"mesh_output\": ");
            write_mesh_output_json(&mut out, mesh_output);
            out.push_str(",\n");
        }
        if self.rt_arena {
            out.push_str("  \"rt_arena\": true,\n");
        }
        if let Some(ver) = self.rt_prelude_version {
            let _ = writeln!(out, "  \"rt_prelude_version\": {ver},");
        }
        if self.bvh_ops > 0 {
            let _ = writeln!(out, "  \"bvh_ops\": {},", self.bvh_ops);
        }
        if self.raw_address {
            out.push_str("  \"raw_address\": true,\n");
        }
        if self.atomic64 {
            out.push_str("  \"atomic64\": true,\n");
        }
        if self.uses_subgroups {
            out.push_str("  \"uses_subgroups\": true,\n");
        }
        if !self.binding_pack.is_zero() {
            let bp = self.binding_pack;
            let _ = writeln!(
                out,
                "  \"binding_pack\": {{\"dead_bindings_pruned\": {}, \"duplicate_bindings_folded\": {}, \"cbv_merged_into_storage\": {}, \"uniform_promoted_to_storage\": {}}},",
                bp.dead_bindings_pruned,
                bp.duplicate_bindings_folded,
                bp.cbv_merged_into_storage,
                bp.uniform_promoted_to_storage
            );
        }
        if !self.ir_opt.is_zero() {
            let opt = self.ir_opt;
            let _ = writeln!(
                out,
                "  \"ir_opt\": {{\"bitcasts_cancelled\": {}, \"constants_folded\": {}, \"identities_simplified\": {}, \"strength_reductions\": {}, \"vector_extracts_folded\": {}, \"dead_branches_folded\": {}, \"locals_forwarded\": {}, \"cse_eliminated\": {}, \"readonly_loads_cse\": {}, \"dead_locals_removed\": {}, \"dead_emits_trimmed\": {}}},",
                opt.bitcasts_cancelled,
                opt.constants_folded,
                opt.identities_simplified,
                opt.strength_reductions,
                opt.vector_extracts_folded,
                opt.dead_branches_folded,
                opt.locals_forwarded,
                opt.cse_eliminated,
                opt.readonly_loads_cse,
                opt.dead_locals_removed,
                opt.dead_emits_trimmed
            );
        }

        // binding_summary
        let bs = &self.binding_summary;
        out.push_str("  \"binding_summary\": {\n");
        let _ = writeln!(out, "    \"has_cbv\": {},", bs.has_cbv);
        let _ = writeln!(out, "    \"cbv_vec4_count\": {},", bs.cbv_vec4_count);
        let _ = writeln!(out, "    \"has_texture_2d\": {},", bs.has_texture_2d);
        let _ = writeln!(out, "    \"has_sampler\": {},", bs.has_sampler);
        let _ = writeln!(out, "    \"has_storage_buffer\": {},", bs.has_storage_buffer);
        let _ = writeln!(
            out,
            "    \"has_storage_texture\": {},",
            bs.has_storage_texture
        );
        let _ = writeln!(out, "    \"has_lds\": {},", bs.has_lds);
        out.push_str("    \"vertex_input_mode\": ");
        write_json_string(&mut out, &bs.vertex_input_mode);
        out.push_str(",\n");

        out.push_str("    \"fragment_input_locations\": [");
        for (i, loc) in bs.fragment_input_locations.iter().enumerate() {
            if i > 0 {
                out.push_str(", ");
            }
            let _ = write!(out, "{loc}");
        }
        out.push_str("],\n");

        out.push_str("    \"output_locations\": [");
        for (i, loc) in bs.output_locations.iter().enumerate() {
            if i > 0 {
                out.push_str(", ");
            }
            let _ = write!(out, "{loc}");
        }
        out.push_str("],\n");

        let _ = writeln!(out, "    \"exports_position\": {},", bs.exports_position);
        let _ = writeln!(out, "    \"exports_depth\": {}", bs.exports_depth);
        out.push_str("  }\n");
        out.push_str("}\n");
        out
    }
}

/// Errors produced during RDNA2 -> WGSL translation or Naga verification.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Rdna2TranslateError {
    NagaValidation(String),
    WgslEmit(String),
    WgslParse(String),
}

impl fmt::Display for Rdna2TranslateError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::NagaValidation(msg) => write!(f, "Naga WGSL validation failed: {msg}"),
            Self::WgslEmit(msg) => write!(f, "Naga WGSL emission failed: {msg}"),
            Self::WgslParse(msg) => write!(f, "Naga WGSL parse check failed: {msg}"),
        }
    }
}

impl std::error::Error for Rdna2TranslateError {}

// ---------------------------------------------------------------------------
// Pre-pass program planning
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum VertexInputMode {
    None,
    VertexIndex,
    Attributes,
}

impl VertexInputMode {
    const fn as_str(self) -> &'static str {
        match self {
            Self::None => "none",
            Self::VertexIndex => "vertex_index",
            Self::Attributes => "attributes",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct VertexInputAttr {
    /// Vertex-buffer slot index (`vb_slot`, 0 for single-VB shaders).
    vb_slot: u32,
    /// Byte offset inside the vertex buffer for MUBUF/MTBUF fetches (`None` for legacy synthetic attributes).
    byte_offset: Option<u16>,
    location: u32,
    name: String,
    /// Vector component width (`1` -> scalar, `2` -> `vec2`, `3` -> `vec3`, `4` -> `vec4`).
    components: u8,
    /// WGSL / WebGPU attribute scalar type (`"f32"`, `"u32"`, or `"i32"`).
    component_type: &'static str,
    /// Explicit WebGPU vertex format name when decoded from GFX10.3 `MTBUF` `format`.
    fetch_format: Option<&'static str>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct VertexFetchPlan {
    components: u8,
    component_type: &'static str,
    fetch_format: Option<&'static str>,
}

/// Synthesized vertex fetch attribute populated at an unlinked Xbox `FSSM` `s_swappc_b64`
/// fetch-shader call site in a vertex shader.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct SwappcFetchAttr {
    location: u32,
    base_vgpr: u8,
    mask: u8,
    components: u8,
    component_type: &'static str,
}

/// Packed byte stride for conventional RAGE / Scaleform `FSSM` vertex attributes:
/// 1-comp (`u32`/`f32`/`R8G8B8A8_UINT` batch idx) = 4B, 2-comp (`float2`) = 8B,
/// 3-comp (`float3`) = 12B, 4-comp (`R8G8B8A8_UNORM` color) = 4B.
#[inline]
const fn fssm_attr_packed_byte_stride(components: u8) -> u16 {
    match components {
        1 => 4,
        2 => 8,
        3 => 12,
        _ => 4,
    }
}

/// Scan vertex-shader instructions starting after `swappc_idx` to classify VGPRs read before
/// being written (`reg >= 4`) by float vs unsigned-int vs signed-int usage.
fn classify_swappc_vgpr_reads(
    active: &[Rdna2Instruction],
    swappc_idx: usize,
) -> (BTreeSet<u8>, BTreeSet<u8>, BTreeSet<u8>, BTreeSet<u8>) {
    #[derive(Clone, Copy)]
    enum ReadKind {
        Float,
        Uint,
        Sint,
        Neutral,
    }

    let mut written: BTreeSet<u8> = BTreeSet::new();
    let mut rbw: BTreeSet<u8> = BTreeSet::new();
    let mut as_float: BTreeSet<u8> = BTreeSet::new();
    let mut as_uint: BTreeSet<u8> = BTreeSet::new();
    let mut as_sint: BTreeSet<u8> = BTreeSet::new();

    let mut note_read = |written: &BTreeSet<u8>, src: u16, kind: ReadKind| {
        if (256..=511).contains(&src) {
            let reg = (src - 256) as u8;
            if reg >= 4 && !written.contains(&reg) {
                rbw.insert(reg);
                match kind {
                    ReadKind::Float => {
                        as_float.insert(reg);
                    }
                    ReadKind::Uint => {
                        as_uint.insert(reg);
                    }
                    ReadKind::Sint => {
                        as_sint.insert(reg);
                    }
                    ReadKind::Neutral => {}
                }
            }
        }
    };

    for inst in active.iter().skip(swappc_idx.saturating_add(1)) {
        if inst.truncated {
            continue;
        }
        match &inst.detail {
            Rdna2Detail::Vop1 { op, vdst, src0, .. } => {
                if matches!(op, 0x00 | 0x1B | 0x41) {
                    continue;
                }
                let kind = match *op {
                    0x01 => ReadKind::Neutral, // v_mov_b32
                    0x02 | 0x06 => ReadKind::Uint, // v_readfirstlane_b32 / v_cvt_f32_u32
                    0x05 => ReadKind::Sint, // v_cvt_f32_i32
                    0x07..=0x11 | 0x1E..=0x35 => ReadKind::Float,
                    0x65 => ReadKind::Neutral, // v_swap_b32
                    _ => ReadKind::Neutral,
                };
                note_read(&written, *src0, kind);
                if *op == 0x65 {
                    note_read(&written, 256 + u16::from(*vdst), ReadKind::Neutral);
                    written.insert(*vdst);
                    if (256..=511).contains(src0) {
                        written.insert((*src0 - 256) as u8);
                    }
                } else if *op != 0x02 {
                    written.insert(*vdst);
                }
            }
            Rdna2Detail::Vopc { op, vsrc1, src0, .. } => {
                let kind = match *op {
                    0x40..=0x5F | 0xC0..=0xDF => ReadKind::Float,
                    0x80..=0x8F => ReadKind::Sint,
                    0x90..=0x9F => ReadKind::Uint,
                    _ => ReadKind::Neutral,
                };
                note_read(&written, *src0, kind);
                note_read(&written, 256 + u16::from(*vsrc1), kind);
            }
            Rdna2Detail::Vop2 {
                op,
                vdst,
                vsrc1,
                src0,
                ..
            } => {
                let kind = match *op {
                    0x00 | 0x01 => ReadKind::Neutral, // v_cndmask_b32
                    0x03..=0x08 | 0x0F..=0x10 | 0x1F | 0x2B..=0x38 | 0x3B..=0x3D => ReadKind::Float,
                    0x11..=0x12 | 0x18 => ReadKind::Sint,
                    0x13..=0x17 | 0x1A..=0x1E | 0x25..=0x26 | 0x28..=0x2A => ReadKind::Uint,
                    _ => ReadKind::Neutral,
                };
                note_read(&written, *src0, kind);
                note_read(&written, 256 + u16::from(*vsrc1), kind);
                if matches!(op, 0x02 | 0x06 | 0x1F | 0x2B | 0x36 | 0x3C) {
                    note_read(&written, 256 + u16::from(*vdst), kind);
                }
                written.insert(*vdst);
            }
            Rdna2Detail::Vop3 {
                op,
                vdst,
                src0,
                src1,
                src2,
                ..
            } => {
                if matches!(*op, 0x180 | 0x19B | 0x1C1) {
                    continue;
                }
                let kind = match *op {
                    0x100 | 0x101 | 0x181 | 0x1E5 => ReadKind::Neutral,
                    0x103..=0x108
                    | 0x10F..=0x110
                    | 0x11F
                    | 0x12B..=0x138
                    | 0x13B..=0x13D
                    | 0x140..=0x141
                    | 0x144..=0x147
                    | 0x14B..=0x14C
                    | 0x150..=0x151
                    | 0x154
                    | 0x157
                    | 0x15E..=0x164
                    | 0x187..=0x191
                    | 0x19E..=0x1B5
                    | 0x34B
                    | 0x364
                    | 0x367..=0x368 => ReadKind::Float,
                    0x111..=0x112
                    | 0x118
                    | 0x142
                    | 0x149
                    | 0x152
                    | 0x155
                    | 0x158
                    | 0x16C
                    | 0x171
                    | 0x185
                    | 0x301
                    | 0x35E => ReadKind::Sint,
                    0x113..=0x117
                    | 0x11A..=0x11E
                    | 0x125..=0x126
                    | 0x128..=0x12A
                    | 0x143
                    | 0x148
                    | 0x14A
                    | 0x14D..=0x14F
                    | 0x153
                    | 0x156
                    | 0x159..=0x15D
                    | 0x165
                    | 0x169..=0x16A
                    | 0x170
                    | 0x178
                    | 0x182
                    | 0x186
                    | 0x2FF..=0x300
                    | 0x30F..=0x319
                    | 0x340
                    | 0x344..=0x347
                    | 0x360
                    | 0x36D..=0x372 => ReadKind::Uint,
                    _ => ReadKind::Neutral,
                };
                note_read(&written, *src0, kind);
                if !(0x180..=0x1FF).contains(op) {
                    note_read(&written, *src1, kind);
                }
                if matches!(
                    *op,
                    0x100
                        | 0x101
                        | 0x128..=0x12A
                        | 0x140..=0x165
                        | 0x16D..=0x171
                        | 0x178
                        | 0x340..=0x35F
                        | 0x36D..=0x372
                        | 0x377
                        | 0x378
                ) {
                    note_read(&written, *src2, kind);
                }
                if matches!(*op, 0x102 | 0x106 | 0x11F | 0x12B | 0x136 | 0x13C | 0x1E5) {
                    note_read(&written, 256 + u16::from(*vdst), kind);
                }
                if *op > 0xFF && *op != 0x360 && *op != 0x182 {
                    written.insert(*vdst);
                    if *op == 0x1E5 && (256..=511).contains(src0) {
                        written.insert((*src0 - 256) as u8);
                    }
                    if matches!(*op, 0x2FF..=0x301 | 0x364) && *vdst < 255 {
                        written.insert(*vdst + 1);
                    }
                }
            }
            Rdna2Detail::Vop3P {
                op,
                vdst,
                src0,
                src1,
                src2,
                ..
            } => {
                note_read(&written, *src0, ReadKind::Neutral);
                note_read(&written, *src1, ReadKind::Neutral);
                if vop3p_is_ternary(*op) {
                    note_read(&written, *src2, ReadKind::Neutral);
                }
                written.insert(*vdst);
            }
            Rdna2Detail::Mubuf {
                op,
                offen,
                idxen,
                vaddr,
                vdata,
                ..
            } => {
                if *offen || *idxen {
                    note_read(&written, 256 + u16::from(*vaddr), ReadKind::Uint);
                }
                if *offen
                    && *idxen
                    && let Some(v1) = checked_vgpr_reg(*vaddr, 1)
                {
                    note_read(&written, 256 + u16::from(v1), ReadKind::Uint);
                }
                if let Some(buf_op) = mubuf_storage_op(*op) {
                    let cnt = buf_op.vdata_count();
                    if buf_op.is_store() {
                        for d in 0..cnt {
                            if let Some(reg) = checked_vgpr_reg(*vdata, d) {
                                note_read(&written, 256 + u16::from(reg), ReadKind::Neutral);
                            }
                        }
                    } else {
                        for d in 0..cnt {
                            if let Some(reg) = checked_vgpr_reg(*vdata, d) {
                                written.insert(reg);
                            }
                        }
                    }
                }
            }
            Rdna2Detail::Mtbuf {
                op,
                offen,
                idxen,
                vaddr,
                vdata,
                ..
            } => {
                if *offen || *idxen {
                    note_read(&written, 256 + u16::from(*vaddr), ReadKind::Uint);
                }
                if *offen
                    && *idxen
                    && let Some(v1) = checked_vgpr_reg(*vaddr, 1)
                {
                    note_read(&written, 256 + u16::from(v1), ReadKind::Uint);
                }
                if let Some(buf_op) = mtbuf_storage_op(*op) {
                    let cnt = buf_op.vdata_count();
                    if buf_op.is_store() {
                        for d in 0..cnt {
                            if let Some(reg) = checked_vgpr_reg(*vdata, d) {
                                note_read(&written, 256 + u16::from(reg), ReadKind::Neutral);
                            }
                        }
                    } else {
                        for d in 0..cnt {
                            if let Some(reg) = checked_vgpr_reg(*vdata, d) {
                                written.insert(reg);
                            }
                        }
                    }
                }
            }
            Rdna2Detail::Mimg {
                op,
                dmask,
                dim,
                d16,
                nsize,
                vaddr,
                nsa_vaddrs,
                vdata,
                ..
            } => {
                if let Some(layout) = mimg_addr_layout(*op) {
                    let eff_mask = if *dmask == 0 { 0xF } else { *dmask };
                    let comp_cnt = if layout.is_gather4 {
                        4
                    } else {
                        eff_mask.count_ones()
                    };
                    let data_vgprs = if *d16 { comp_cnt.div_ceil(2) } else { comp_cnt } as u8;
                    let tex_dim = if layout.is_store || layout.is_load {
                        TexDim::from_storage_mimg_dim(*dim)
                    } else {
                        TexDim::from_mimg_dim(*dim)
                    };
                    let extra_grad = if layout.grad_off.is_some() && tex_dim.has_3d_grad() {
                        2u8
                    } else {
                        0u8
                    };
                    let addr_vgprs = layout
                        .total_vgprs
                        .saturating_add(extra_grad)
                        .saturating_add(tex_dim.extra_coord_vgprs());
                    let addr_kind = if layout.is_load || layout.is_store {
                        ReadKind::Uint
                    } else {
                        ReadKind::Float
                    };
                    for a in 0..addr_vgprs {
                        if let Some(reg) = mimg_addr_vgpr(*vaddr, *nsize, nsa_vaddrs, a) {
                            note_read(&written, 256 + u16::from(reg), addr_kind);
                        }
                    }
                    if !layout.is_store {
                        for d in 0..data_vgprs {
                            if let Some(reg) = checked_vgpr_reg(*vdata, d) {
                                written.insert(reg);
                            }
                        }
                    }
                }
            }
            Rdna2Detail::Exp {
                en, compr, vsrc, ..
            } => {
                if *compr {
                    if (*en & 0b0001) != 0 {
                        note_read(&written, 256 + u16::from(vsrc[0]), ReadKind::Float);
                    }
                    if (*en & 0b0100) != 0 {
                        note_read(&written, 256 + u16::from(vsrc[1]), ReadKind::Float);
                    }
                } else {
                    for (idx, &reg) in vsrc.iter().enumerate() {
                        if (*en & (1 << idx)) != 0 {
                            note_read(&written, 256 + u16::from(reg), ReadKind::Float);
                        }
                    }
                }
            }
            _ => {}
        }
    }

    (rbw, as_float, as_uint, as_sint)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
struct DynamicHeapOrigin {
    base_user_sgpr: u32,
    stride: u32,
    index_user_sgpr: u32,
    index_shift: u32,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
struct CbvKey {
    /// Base SGPR pair index (raw `sbase` for unreflected direct/indirect SMEM loads;
    /// normalized to `0` when `user_sgpr`, `dynamic_heap`, `cbv_indexed_heap`, or
    /// `lane_indexed_heap` uniquely identifies the CBV).
    base_sbase: u8,
    /// Known console user-data SGPR when sourced from a descriptor table or root descriptor.
    user_sgpr: Option<u32>,
    /// `Some(table_offset)` for a coalesced descriptor-table V# / CBV-ptr entry,
    /// `None` for direct SMEM or dynamic heap CBVs.
    table_offset: Option<i32>,
    /// `Some(origin)` for a coalesced SM 6.6 `ResourceDescriptorHeap` V# CBV entry.
    dynamic_heap: Option<DynamicHeapOrigin>,
    /// `Some(origin)` for a coalesced SM 6.6 CB-indexed `ResourceDescriptorHeap` V# CBV entry (#1383).
    cbv_indexed_heap: Option<CbvIndexedHeapSource>,
    /// `Some(origin)` for a coalesced SM 6.6 lane-indexed `ResourceDescriptorHeap` V# CBV entry (#1394).
    lane_indexed_heap: Option<LaneIndexedHeapSource>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct CbvUsage {
    max_vec4_index: u32,
    has_dynamic_offset: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct CbvSlotPlan {
    key: CbvKey,
    vec4_count: u32,
    highest_vec4_offset: u32,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum ResourceKey {
    Table {
        user_sgpr: u32,
        table_byte_offset: u32,
    },
    RootDescriptor {
        user_sgpr: u32,
        table_byte_offset: Option<u32>,
    },
    StaticSampler(u32),
    InlineSampler([u32; 4]),
    SamplerHeap {
        base_user_sgpr: u32,
        stride: u32,
        index_user_sgpr: u32,
        index_shift: u32,
    },
    ResourceHeap {
        base_user_sgpr: u32,
        stride: u32,
        index_user_sgpr: u32,
        index_shift: u32,
    },
    CbvIndexedSamplerHeap(CbvIndexedHeapSource),
    CbvIndexedResourceHeap(CbvIndexedHeapSource),
    LaneIndexedSamplerHeap(LaneIndexedHeapSource),
    LaneIndexedResourceHeap(LaneIndexedHeapSource),
    RawSlot(u8),
}

impl ResourceKey {
    fn to_source(self) -> Option<WgslBindingSource> {
        match self {
            Self::Table {
                user_sgpr,
                table_byte_offset,
            } => Some(WgslBindingSource::Table {
                user_sgpr,
                table_byte_offset,
            }),
            Self::RootDescriptor {
                user_sgpr,
                table_byte_offset,
            } => Some(WgslBindingSource::RootDescriptor {
                user_sgpr,
                table_byte_offset,
            }),
            Self::StaticSampler(index) => Some(WgslBindingSource::StaticSampler { index }),
            Self::InlineSampler(sdwords) => Some(WgslBindingSource::InlineSampler { sdwords }),
            Self::SamplerHeap {
                base_user_sgpr,
                stride,
                index_user_sgpr,
                index_shift,
            } => Some(WgslBindingSource::SamplerHeap {
                base_user_sgpr,
                stride,
                index_user_sgpr,
                index_shift,
            }),
            Self::ResourceHeap {
                base_user_sgpr,
                stride,
                index_user_sgpr,
                index_shift,
            } => Some(WgslBindingSource::ResourceHeap {
                base_user_sgpr,
                stride,
                index_user_sgpr,
                index_shift,
            }),
            Self::CbvIndexedSamplerHeap(h) => Some(WgslBindingSource::CbvIndexedSamplerHeap(h)),
            Self::CbvIndexedResourceHeap(h) => Some(WgslBindingSource::CbvIndexedResourceHeap(h)),
            Self::LaneIndexedSamplerHeap(h) => Some(WgslBindingSource::LaneIndexedSamplerHeap(h)),
            Self::LaneIndexedResourceHeap(h) => Some(WgslBindingSource::LaneIndexedResourceHeap(h)),
            Self::RawSlot(_) => None,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TexDim {
    D2,
    D2Array,
    D3,
    Cube,
    CubeArray,
}

impl TexDim {
    fn from_mimg_dim(dim: u8) -> Self {
        match dim {
            2 => Self::D3,
            3 => Self::Cube,
            5 => Self::D2Array,
            7 => Self::CubeArray,
            _ => Self::D2,
        }
    }

    fn from_storage_mimg_dim(dim: u8) -> Self {
        match dim {
            2 => Self::D3,
            3 | 5 | 7 => Self::D2Array,
            _ => Self::D2,
        }
    }

    fn view_dimension_name(self) -> &'static str {
        match self {
            Self::D2 => "2d",
            Self::D2Array => "2d-array",
            Self::D3 => "3d",
            Self::Cube => "cube",
            Self::CubeArray => "cube-array",
        }
    }

    fn extra_coord_vgprs(self) -> u8 {
        match self {
            Self::D2 => 0,
            Self::D2Array | Self::D3 | Self::Cube => 1,
            Self::CubeArray => 2,
        }
    }

    const fn has_3d_grad(self) -> bool {
        matches!(self, Self::D3 | Self::Cube | Self::CubeArray)
    }

    const fn supports_depth(self) -> bool {
        matches!(self, Self::D2 | Self::D2Array | Self::Cube | Self::CubeArray)
    }

    const fn supports_gather(self) -> bool {
        matches!(self, Self::D2 | Self::D2Array | Self::Cube | Self::CubeArray)
    }

    const fn supports_texel_offset(self) -> bool {
        matches!(self, Self::D2 | Self::D2Array | Self::D3)
    }

    fn merge(self, other: Self) -> Self {
        match (self, other) {
            (Self::D2, o) => o,
            (s, Self::D2) => s,
            (Self::Cube, Self::CubeArray) | (Self::CubeArray, Self::Cube) => Self::CubeArray,
            (s, _) => s,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct FragAttrInterp {
    interpolation: Interpolation,
    sampling: Option<Sampling>,
}

impl Default for FragAttrInterp {
    fn default() -> Self {
        Self {
            interpolation: Interpolation::Perspective,
            sampling: Some(Sampling::Center),
        }
    }
}

fn classify_vintrp_barycentric(vsrc: u8) -> FragAttrInterp {
    // AMD GFX10.3 SPI_PS_INPUT_ADDR canonical barycentric VGPR pair mapping:
    //   v0/v1 -> PERSP_CENTER
    //   v2/v3 -> PERSP_CENTROID
    //   v4/v5 -> LINEAR_CENTER (noperspective)
    //   v6/v7 -> LINEAR_CENTROID (noperspective centroid)
    match vsrc {
        2 | 3 => FragAttrInterp {
            interpolation: Interpolation::Perspective,
            sampling: Some(Sampling::Centroid),
        },
        4 | 5 => FragAttrInterp {
            interpolation: Interpolation::Linear,
            sampling: Some(Sampling::Center),
        },
        6 | 7 => FragAttrInterp {
            interpolation: Interpolation::Linear,
            sampling: Some(Sampling::Centroid),
        },
        _ => FragAttrInterp::default(),
    }
}

fn merge_frag_attr_interp(
    map: &mut BTreeMap<u8, FragAttrInterp>,
    attr: u8,
    incoming: FragAttrInterp,
) {
    map.entry(attr)
        .and_modify(|cur| {
            // Smooth interpolation (Perspective/Linear) overrides Flat if mixed on one vec4 attr;
            // more specific modes (Linear or Centroid) override the Perspective/Center default.
            if cur.interpolation == Interpolation::Flat {
                if incoming.interpolation != Interpolation::Flat {
                    *cur = incoming;
                }
            } else if incoming.interpolation != Interpolation::Flat
                && *cur == FragAttrInterp::default()
                && incoming != FragAttrInterp::default()
            {
                *cur = incoming;
            }
        })
        .or_insert(incoming);
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct StorageBufSlotPlan {
    key: ResourceKey,
    writable: bool,
}

#[derive(Debug, Clone)]
enum StorageDispatch {
    /// 2-way CFG diamond selecting between two static descriptor-table slots (`sel_id` is written
    /// with `0u` / `1u` at the defining `s_load_dwordx4/x8` instructions).
    TwoWayChoice {
        choice_id: usize,
        keys: [ResourceKey; 2],
    },
    /// Bounded `0..keys.len()` dynamic CBV index array feeding an SM 6.6 resource-heap `image_store`
    /// (`sel_id` captures the bounded index SGPR at the dynamic `s_buffer_load_dword` instruction).
    BoundedIndexed {
        choice_id: usize,
        keys: Vec<ResourceKey>,
    },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ChoiceWrite {
    Const(u32),
    CopySgpr(u8),
}

/// GFX10.3 `VOP_SDWAB` (64-bit VOPC with `src0 == 0xF9`): when `w1[15]` (`sd`) is set and the
/// instruction is not `v_cmpx_*`, the comparison mask is written to `sdst = w1[14:8]` instead of
/// `vcc` (`106`).
#[inline]
fn vopc_sdwab_sdst(op: u8, src0: u16, literal: Option<u32>) -> Option<u8> {
    if (op & 0x10) == 0
        && src0 == 0xF9
        && let Some(w1) = literal
        && ((w1 >> 15) & 1) != 0
    {
        return Some(((w1 >> 8) & 0x7F) as u8);
    }
    None
}

struct ProgramPlan {
    stage: ShaderStage,
    entry_point: String,
    workgroup_size: [u32; 3],
    compute_seed_wg_sgprs: Vec<(u8, u32)>,
    active_inst_count: usize,
    vertex_input_mode: VertexInputMode,
    vertex_attrs: Vec<VertexInputAttr>,
    swappc_fetch_attrs: Vec<SwappcFetchAttr>,
    has_buffer_fetch: bool,
    legacy_uv_attr_index: Option<usize>,
    vsharp_fetch_insts: BTreeSet<usize>,
    indirect_smem_cbv_keys: BTreeMap<usize, CbvKey>,
    cbv_sources: BTreeMap<CbvKey, WgslBindingSource>,
    inst_tex_keys: BTreeMap<usize, ResourceKey>,
    inst_samp_keys: BTreeMap<usize, ResourceKey>,
    inst_storage_buf_keys: BTreeMap<usize, ResourceKey>,
    inst_storage_tex_keys: BTreeMap<usize, ResourceKey>,
    inst_storage_buf_dispatches: BTreeMap<usize, StorageDispatch>,
    inst_storage_tex_dispatches: BTreeMap<usize, StorageDispatch>,
    choice_def_writes: BTreeMap<usize, Vec<(usize, ChoiceWrite)>>,
    choice_count: usize,
    tex_dims: BTreeMap<ResourceKey, TexDim>,
    tex_is_depth: BTreeSet<ResourceKey>,
    samp_is_comparison: BTreeSet<ResourceKey>,
    storage_tex_dims: BTreeMap<ResourceKey, TexDim>,
    vertex_storage_buf_insts: BTreeSet<usize>,
    vertex_fetch_vb_slots: BTreeMap<usize, u32>,
    cbv_slots: Vec<CbvSlotPlan>,
    tex_slots: Vec<ResourceKey>,
    samp_slots: Vec<ResourceKey>,
    storage_buf_slots: Vec<StorageBufSlotPlan>,
    storage_tex_slots: Vec<ResourceKey>,
    uses_lds: bool,
    uses_lds_atomics: bool,
    uses_wave_lds: bool,
    wave_emul_mode: WaveEmulMode,
    is_wave32: bool,
    frag_attrs: Vec<u8>,
    frag_attr_interp: BTreeMap<u8, FragAttrInterp>,
    /// Fragment `(clamped_attr, attrchan)` channels read with `high = true` by `v_interp_*_f16`,
    /// indicating the 32-bit attribute channel carries a packed `fp16x2` pair.
    frag_attr_f16_high_channels: BTreeSet<(u8, u8)>,
    vs_params: Vec<u8>,
    ps_mrts: Vec<u8>,
    ps_exports_depth: bool,
    vgprs: BTreeSet<u8>,
    sgprs: BTreeSet<u8>,
    /// Dedicated `(vgpr, lane)` local spill slots written by constant-lane `v_writelane_b32`.
    lane_spill_slots: BTreeSet<(u8, u8)>,
    needs_vcc: bool,
    needs_scc: bool,
    /// Single-lane `exec_mask` model is required (exec-mask SOP1 ops, `exec` SOP1/SOP2
    /// destinations, or `s_cbranch_execz/execnz`).
    needs_exec: bool,
    /// Dedicated `m0: u32` local is required (`m0` register 124 read/written, or mesh stage).
    needs_m0: bool,
    /// Mesh-to-compute output layout (`Some(...)` when `Rdna2StageOverride::Mesh`).
    mesh_output: Option<MeshOutputLayout>,
    /// `true` when the emitted WGSL calls runtime-owned RT prelude helpers (`pg6_load32` /
    /// `pg6_bvh_intersect`) and requires the runtime to prepend `prelude_wgsl()` and bind group 3.
    rt_arena: bool,
    /// Number of GFX10.3 BVH MIMG instructions (`0xE6` / `0xE7`) in the active program.
    bvh_ops: u32,
    /// `true` when the active program contains FLAT/GLOBAL raw-address memory instructions.
    raw_address: bool,
    /// `true` when the active program contains 64-bit FLAT/GLOBAL atomic instructions (`0x50..=0x5F`).
    atomic64: bool,
    /// Storage-buffer keys whose only references in `plan_program` came from unlowered
    /// `buffer_atomic_*` instructions (kept when within D3D12 limits; pruned if over-limit).
    atomic_only_storage_keys: BTreeSet<ResourceKey>,
    /// Number of duplicate/aliased bindings folded during `plan_program` canonicalization.
    duplicate_bindings_folded: usize,
}

fn resolve_stage(inferred: Rdna2InferredStage, override_stage: Rdna2StageOverride) -> ShaderStage {
    match override_stage {
        Rdna2StageOverride::Vertex => ShaderStage::Vertex,
        Rdna2StageOverride::Pixel => ShaderStage::Fragment,
        Rdna2StageOverride::Compute | Rdna2StageOverride::Mesh => ShaderStage::Compute,
        Rdna2StageOverride::Auto => match inferred {
            Rdna2InferredStage::Vertex => ShaderStage::Vertex,
            Rdna2InferredStage::Pixel => ShaderStage::Fragment,
            Rdna2InferredStage::Compute
            | Rdna2InferredStage::Mesh
            | Rdna2InferredStage::Unknown => ShaderStage::Compute,
        },
    }
}

fn default_entry_point(stage: ShaderStage) -> &'static str {
    match stage {
        ShaderStage::Vertex => "vs_main",
        ShaderStage::Fragment => "fs_main",
        ShaderStage::Compute => "cs_main",
    }
}

/// Highest architectural SGPR index in GFX10.3 (`s0..=s105`).
const MAX_SGPR_INDEX: u8 = 105;

/// Checked VGPR index calculation (`base + offset <= 255`), returning `None` on overflow.
#[inline]
fn checked_vgpr_reg(base: u8, offset: u8) -> Option<u8> {
    base.checked_add(offset)
}

/// Checked architectural SGPR index calculation (`base + offset <= 105`), returning `None`
/// when out of range or overflowing `u8`.
#[inline]
fn checked_sgpr_reg(base: u8, offset: u8) -> Option<u8> {
    base.checked_add(offset)
        .filter(|&reg| reg <= MAX_SGPR_INDEX)
}

/// Checked tracked-SGPR index calculation (`base + offset <= MAX_TRACKED_SGPR`), covering
/// `s0..=s105` plus `vcc_lo (106)` and `vcc_hi (107)`.
#[inline]
fn checked_tracked_sgpr_reg(base: u8, offset: u8) -> Option<u8> {
    base.checked_add(offset)
        .filter(|&reg| reg <= MAX_TRACKED_SGPR)
}

/// Checked descriptor base SGPR calculation (`slot * stride <= MAX_TRACKED_SGPR`), preventing
/// `u8` multiplication overflow or out-of-range descriptor indices.
#[inline]
fn checked_descriptor_sgpr(slot: u8, stride: u8) -> Option<u8> {
    slot.checked_mul(stride)
        .filter(|&reg| reg <= MAX_TRACKED_SGPR)
}

/// Returns `true` if `ident` is a WGSL keyword, predeclared scalar/vector/resource type,
/// or collides with a translator-generated module-scope symbol.
fn is_wgsl_reserved_or_builtin_ident(ident: &str) -> bool {
    matches!(
        ident,
        "alias"
            | "array"
            | "atomic"
            | "bitcast"
            | "bool"
            | "break"
            | "case"
            | "const"
            | "const_assert"
            | "continue"
            | "continuing"
            | "default"
            | "diagnostic"
            | "discard"
            | "else"
            | "enable"
            | "f16"
            | "f32"
            | "false"
            | "fn"
            | "for"
            | "i32"
            | "if"
            | "let"
            | "loop"
            | "mat2x2"
            | "mat2x3"
            | "mat2x4"
            | "mat3x2"
            | "mat3x3"
            | "mat3x4"
            | "mat4x2"
            | "mat4x3"
            | "mat4x4"
            | "override"
            | "ptr"
            | "requires"
            | "return"
            | "sampler"
            | "sampler_comparison"
            | "struct"
            | "switch"
            | "texture_1d"
            | "texture_2d"
            | "texture_2d_array"
            | "texture_3d"
            | "texture_cube"
            | "texture_cube_array"
            | "texture_depth_2d"
            | "texture_depth_2d_array"
            | "texture_depth_cube"
            | "texture_depth_cube_array"
            | "texture_depth_multisampled_2d"
            | "texture_multisampled_2d"
            | "texture_storage_1d"
            | "texture_storage_2d"
            | "texture_storage_2d_array"
            | "texture_storage_3d"
            | "true"
            | "u32"
            | "var"
            | "vec2"
            | "vec3"
            | "vec4"
            | "while"
            | "Rdna2Cbv"
            | "VsIn"
            | "VsOut"
            | "FragIn"
            | "PsOut"
            | "lds"
            | "cb0"
            | "tex0"
            | "samp0"
            | "pg6_u32_bits_to_float"
            | "pg6_unpack2x16float"
            | "pg6_pack2x16float"
            | "pg6_rt_f32"
            | "pg6_rt_u32"
            | "pg6_rt_i32"
            | "pg6_rt_vec2_f32"
    )
}

fn sanitize_wgsl_ident(raw: &str, fallback: &str) -> String {
    if raw.starts_with("__") {
        return fallback.to_string();
    }
    let mut out = String::new();
    for ch in raw.chars() {
        let valid = if out.is_empty() {
            ch.is_ascii_alphabetic()
        } else {
            ch.is_ascii_alphanumeric() || ch == '_'
        };
        if valid {
            if ch == '_' && out.ends_with('_') {
                continue;
            }
            out.push(ch);
        } else if !out.is_empty() && !out.ends_with('_') {
            out.push('_');
        }
    }
    while out.ends_with('_') {
        out.pop();
    }
    if out.is_empty()
        || out.starts_with("__")
        || is_wgsl_reserved_or_builtin_ident(&out)
    {
        fallback.to_string()
    } else {
        out
    }
}

fn smem_load_dword_count(op: u8) -> Option<u8> {
    match op {
        0x00 | 0x08 => Some(1),
        0x01 | 0x09 => Some(2),
        0x02 | 0x0A => Some(4),
        0x03 | 0x0B => Some(8),
        0x04 | 0x0C => Some(16),
        _ => None,
    }
}

#[derive(Debug, Clone, Copy)]
struct MimgAddrLayout {
    total_vgprs: u8,
    offset_off: Option<u8>,
    bias_off: Option<u8>,
    compare_off: Option<u8>,
    grad_off: Option<u8>,
    uv_off: u8,
    lod_off: Option<u8>,
    #[allow(dead_code)]
    clamp_off: Option<u8>,
    is_zero_lod: bool,
    is_gather4: bool,
    is_load: bool,
    is_store: bool,
    is_get_lod: bool,
}

fn build_mimg_sample_layout(
    has_offset: bool,
    has_bias: bool,
    has_compare: bool,
    has_grad: bool,
    has_lod: bool,
    has_clamp: bool,
    is_zero_lod: bool,
    is_gather4: bool,
) -> MimgAddrLayout {
    // GFX10.3 MIMG address VGPR ordering (base 2D; extra_grad and extra_coord are added per dim):
    //   [offset], [bias], [z_compare], [grad (4 for 2D / 6 for 3D/Cube)], u, v, [w/slice], [lod], [clamp]
    let mut cursor = 0u8;
    let offset_off = if has_offset {
        let o = cursor;
        cursor += 1;
        Some(o)
    } else {
        None
    };
    let bias_off = if has_bias {
        let o = cursor;
        cursor += 1;
        Some(o)
    } else {
        None
    };
    let compare_off = if has_compare {
        let o = cursor;
        cursor += 1;
        Some(o)
    } else {
        None
    };
    let grad_off = if has_grad {
        let o = cursor;
        cursor += 4;
        Some(o)
    } else {
        None
    };
    let uv_off = cursor;
    cursor += 2;
    let lod_off = if has_lod {
        let o = cursor;
        cursor += 1;
        Some(o)
    } else {
        None
    };
    let clamp_off = if has_clamp {
        let o = cursor;
        cursor += 1;
        Some(o)
    } else {
        None
    };
    MimgAddrLayout {
        total_vgprs: cursor,
        offset_off,
        bias_off,
        compare_off,
        grad_off,
        uv_off,
        lod_off,
        clamp_off,
        is_zero_lod,
        is_gather4,
        is_load: false,
        is_store: false,
        is_get_lod: false,
    }
}

/// Decode GFX10.3 2D MIMG address VGPR layout (`[offset], [bias], [z_compare], [grad], u, v, [lod/clamp]`).
fn mimg_addr_layout(op: u8) -> Option<MimgAddrLayout> {
    let base = MimgAddrLayout {
        total_vgprs: 2,
        offset_off: None,
        bias_off: None,
        compare_off: None,
        grad_off: None,
        uv_off: 0,
        lod_off: None,
        clamp_off: None,
        is_zero_lod: false,
        is_gather4: false,
        is_load: false,
        is_store: false,
        is_get_lod: false,
    };
    match op {
        // image_load / image_load_pck / image_load_pck_sgn: (x, y)
        0x00 | 0x02 | 0x03 => Some(MimgAddrLayout {
            is_load: true,
            ..base
        }),
        // image_load_mip / image_load_mip_pck / image_load_mip_pck_sgn: (x, y, mip)
        0x01 | 0x04 | 0x05 => Some(MimgAddrLayout {
            total_vgprs: 3,
            lod_off: Some(2),
            is_load: true,
            ..base
        }),
        // image_store / image_store_pck: (x, y)
        0x08 | 0x0A => Some(MimgAddrLayout {
            is_store: true,
            ..base
        }),
        // image_store_mip / image_store_mip_pck: (x, y, mip)
        0x09 | 0x0B => Some(MimgAddrLayout {
            total_vgprs: 3,
            lod_off: Some(2),
            is_store: true,
            ..base
        }),
        // image_sample* (0x20..=0x3F): regular GFX10.3 bitfield
        //   bit 4 (0x10) = _o (offset)
        //   bit 3 (0x08) = _c (compare)
        //   bits [2:0]: 0=base, 1=_cl, 2=_d, 3=_d_cl, 4=_l, 5=_b, 6=_b_cl, 7=_lz
        0x20..=0x3F => {
            let has_offset = (op & 0x10) != 0;
            let has_compare = (op & 0x08) != 0;
            let mode = op & 0x07;
            let has_clamp = matches!(mode, 1 | 3 | 6);
            let has_grad = matches!(mode, 2 | 3);
            let has_lod = mode == 4;
            let has_bias = matches!(mode, 5 | 6);
            let is_zero_lod = mode == 7;
            Some(build_mimg_sample_layout(
                has_offset,
                has_bias,
                has_compare,
                has_grad,
                has_lod,
                has_clamp,
                is_zero_lod,
                false,
            ))
        }
        // image_gather4* (0x40..=0x5F): same bitfield without _d (modes 2 & 3 are unused)
        0x40..=0x5F => {
            let mode = op & 0x07;
            if matches!(mode, 2 | 3) {
                return None;
            }
            let has_offset = (op & 0x10) != 0;
            let has_compare = (op & 0x08) != 0;
            let has_clamp = matches!(mode, 1 | 6);
            let has_lod = mode == 4;
            let has_bias = matches!(mode, 5 | 6);
            let is_zero_lod = mode == 7;
            Some(build_mimg_sample_layout(
                has_offset,
                has_bias,
                has_compare,
                false,
                has_lod,
                has_clamp,
                is_zero_lod,
                true,
            ))
        }
        // image_get_lod: (u, v) -> mip levels (safe WGSL mip 0.0 fallback)
        0x60 => Some(MimgAddrLayout {
            is_get_lod: true,
            ..base
        }),
        // image_sample_cd* (0x68..=0x6F): coarse-derivative variants
        0x68..=0x6F => {
            let has_offset = (op & 0x04) != 0;
            let has_compare = (op & 0x02) != 0;
            let has_clamp = (op & 0x01) != 0;
            Some(build_mimg_sample_layout(
                has_offset,
                false,
                has_compare,
                true,
                false,
                has_clamp,
                false,
                false,
            ))
        }
        _ => None,
    }
}

fn gather_component_from_dmask(dmask: u8) -> SwizzleComponent {
    if (dmask & 0x1) != 0 {
        SwizzleComponent::X
    } else if (dmask & 0x2) != 0 {
        SwizzleComponent::Y
    } else if (dmask & 0x4) != 0 {
        SwizzleComponent::Z
    } else if (dmask & 0x8) != 0 {
        SwizzleComponent::W
    } else {
        SwizzleComponent::X
    }
}

fn vop3p_is_ternary(op: u8) -> bool {
    !matches!(op, 0x01..=0x08 | 0x0A..=0x0D | 0x0F..=0x12)
}

fn mubuf_load_components(op: u8) -> Option<u8> {
    match op {
        0x00 | 0x0C => Some(1),
        0x01 | 0x0D => Some(2),
        0x02 | 0x0F => Some(3),
        0x03 | 0x0E => Some(4),
        _ => None,
    }
}

fn mtbuf_load_components(op: u8) -> Option<u8> {
    match op {
        0x00 => Some(1),
        0x01 => Some(2),
        0x02 => Some(3),
        0x03 => Some(4),
        _ => None,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum StorageBufOpKind {
    LoadUbyte,
    LoadSbyte,
    LoadUshort,
    LoadSshort,
    LoadDwords(u8),
    StoreDwords(u8),
}

impl StorageBufOpKind {
    const fn is_store(self) -> bool {
        matches!(self, Self::StoreDwords(_))
    }

    const fn vdata_count(self) -> u8 {
        match self {
            Self::LoadUbyte | Self::LoadSbyte | Self::LoadUshort | Self::LoadSshort => 1,
            Self::LoadDwords(n) | Self::StoreDwords(n) => n,
        }
    }

    const fn elem_stride_bytes(self) -> u32 {
        match self {
            Self::LoadUbyte | Self::LoadSbyte => 1,
            Self::LoadUshort | Self::LoadSshort => 2,
            Self::LoadDwords(n) | Self::StoreDwords(n) => (n as u32) * 4,
        }
    }
}

fn mubuf_storage_op(op: u8) -> Option<StorageBufOpKind> {
    match op {
        0x00 | 0x0C => Some(StorageBufOpKind::LoadDwords(1)),
        0x01 | 0x0D => Some(StorageBufOpKind::LoadDwords(2)),
        0x02 | 0x0F => Some(StorageBufOpKind::LoadDwords(3)),
        0x03 | 0x0E => Some(StorageBufOpKind::LoadDwords(4)),
        0x08 => Some(StorageBufOpKind::LoadUbyte),
        0x09 => Some(StorageBufOpKind::LoadSbyte),
        0x0A => Some(StorageBufOpKind::LoadUshort),
        0x0B => Some(StorageBufOpKind::LoadSshort),
        0x04 | 0x1C => Some(StorageBufOpKind::StoreDwords(1)),
        0x05 | 0x1D => Some(StorageBufOpKind::StoreDwords(2)),
        0x06 | 0x1F => Some(StorageBufOpKind::StoreDwords(3)),
        0x07 | 0x1E => Some(StorageBufOpKind::StoreDwords(4)),
        _ => None,
    }
}

const fn mubuf_is_atomic(op: u8) -> bool {
    matches!(op, 0x32..=0x3A)
}

fn mtbuf_storage_op(op: u8) -> Option<StorageBufOpKind> {
    match op {
        0x00 => Some(StorageBufOpKind::LoadDwords(1)),
        0x01 => Some(StorageBufOpKind::LoadDwords(2)),
        0x02 => Some(StorageBufOpKind::LoadDwords(3)),
        0x03 => Some(StorageBufOpKind::LoadDwords(4)),
        0x04 => Some(StorageBufOpKind::StoreDwords(1)),
        0x05 => Some(StorageBufOpKind::StoreDwords(2)),
        0x06 => Some(StorageBufOpKind::StoreDwords(3)),
        0x07 => Some(StorageBufOpKind::StoreDwords(4)),
        _ => None,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DsAtomicOp {
    Add,
    Sub,
    UMin,
    UMax,
    And,
    Or,
    Xor,
    Swap,
    Inc,
    Dec,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DsLdsOp {
    ReadContiguous(u8),
    WriteContiguous(u8),
    Read2 { stride_bytes: u32 },
    Write2 { stride_bytes: u32 },
    Atomic { op: DsAtomicOp, returns_value: bool },
    Swizzle,
    Permute,
    BPermute,
}

fn ds_lds_op(op: u8) -> Option<DsLdsOp> {
    match op {
        // Non-returning 32-bit LDS atomics
        0x00 => Some(DsLdsOp::Atomic { op: DsAtomicOp::Add, returns_value: false }),
        0x01 => Some(DsLdsOp::Atomic { op: DsAtomicOp::Sub, returns_value: false }),
        0x03 => Some(DsLdsOp::Atomic { op: DsAtomicOp::Inc, returns_value: false }),
        0x04 => Some(DsLdsOp::Atomic { op: DsAtomicOp::Dec, returns_value: false }),
        0x05 | 0x07 => Some(DsLdsOp::Atomic { op: DsAtomicOp::UMin, returns_value: false }),
        0x06 | 0x08 => Some(DsLdsOp::Atomic { op: DsAtomicOp::UMax, returns_value: false }),
        0x09 => Some(DsLdsOp::Atomic { op: DsAtomicOp::And, returns_value: false }),
        0x0A => Some(DsLdsOp::Atomic { op: DsAtomicOp::Or, returns_value: false }),
        0x0B => Some(DsLdsOp::Atomic { op: DsAtomicOp::Xor, returns_value: false }),
        // Standard LDS reads & writes
        0x0D => Some(DsLdsOp::WriteContiguous(1)),
        0x0E => Some(DsLdsOp::Write2 { stride_bytes: 4 }),
        0x0F => Some(DsLdsOp::Write2 { stride_bytes: 256 }),
        0x1E | 0x1F => Some(DsLdsOp::WriteContiguous(1)),
        // Returning 32-bit LDS atomics
        0x20 => Some(DsLdsOp::Atomic { op: DsAtomicOp::Add, returns_value: true }),
        0x21 => Some(DsLdsOp::Atomic { op: DsAtomicOp::Sub, returns_value: true }),
        0x23 => Some(DsLdsOp::Atomic { op: DsAtomicOp::Inc, returns_value: true }),
        0x24 => Some(DsLdsOp::Atomic { op: DsAtomicOp::Dec, returns_value: true }),
        0x25 | 0x27 => Some(DsLdsOp::Atomic { op: DsAtomicOp::UMin, returns_value: true }),
        0x26 | 0x28 => Some(DsLdsOp::Atomic { op: DsAtomicOp::UMax, returns_value: true }),
        0x29 => Some(DsLdsOp::Atomic { op: DsAtomicOp::And, returns_value: true }),
        0x2A => Some(DsLdsOp::Atomic { op: DsAtomicOp::Or, returns_value: true }),
        0x2B => Some(DsLdsOp::Atomic { op: DsAtomicOp::Xor, returns_value: true }),
        0x2D => Some(DsLdsOp::Atomic { op: DsAtomicOp::Swap, returns_value: true }),
        // Cross-lane wave DS ops
        0x35 => Some(DsLdsOp::Swizzle),
        0xB2 => Some(DsLdsOp::Permute),
        0xB3 => Some(DsLdsOp::BPermute),
        // Standard LDS reads & wide transfers
        0x36 => Some(DsLdsOp::ReadContiguous(1)),
        0x37 => Some(DsLdsOp::Read2 { stride_bytes: 4 }),
        0x38 => Some(DsLdsOp::Read2 { stride_bytes: 256 }),
        0x39..=0x3C => Some(DsLdsOp::ReadContiguous(1)),
        0x4D => Some(DsLdsOp::WriteContiguous(2)),
        0x76 => Some(DsLdsOp::ReadContiguous(2)),
        0xDE => Some(DsLdsOp::WriteContiguous(3)),
        0xDF => Some(DsLdsOp::WriteContiguous(4)),
        0xFE => Some(DsLdsOp::ReadContiguous(3)),
        0xFF => Some(DsLdsOp::ReadContiguous(4)),
        _ => None,
    }
}

#[allow(clippy::too_many_arguments)]
/// 64-bit shift flavour emitted on `(lo, hi)` u32 register pairs.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Shift64Kind {
    Left,
    LogicalRight,
    ArithmeticRight,
}

fn record_src_usage(
    src: u16,
    vgprs: &mut BTreeSet<u8>,
    sgprs: &mut BTreeSet<u8>,
    written_vgprs: &BTreeSet<u8>,
    read_before_write_vgprs: &mut BTreeSet<u8>,
    written_sgprs: &BTreeSet<u8>,
    read_before_write_sgprs: &mut BTreeSet<u8>,
    needs_vcc: &mut bool,
    needs_scc: &mut bool,
) {
    match src {
        0..=105 => {
            let s = src as u8;
            sgprs.insert(s);
            if !written_sgprs.contains(&s) {
                read_before_write_sgprs.insert(s);
            }
        }
        106 => {
            *needs_vcc = true;
        }
        251 => {
            *needs_vcc = true;
        }
        253 => {
            *needs_scc = true;
        }
        256..=511 => {
            let v = (src - 256) as u8;
            vgprs.insert(v);
            if !written_vgprs.contains(&v) {
                read_before_write_vgprs.insert(v);
            }
        }
        _ => {}
    }
}

/// Number of tracked scalar registers in origin analysis: `s0..=s105` plus `106 = vcc_lo` and
/// `107 = vcc_hi`, since GFX10.3 descriptor quads/octets (`s[104:107]`, `s[100:107]`) and inline
/// S# samplers (`s_bfm_b64 s[104:105]`, `s_mov_b64 vcc, ...`) span `s104..=vcc_hi`.
const TRACKED_SGPR_COUNT: usize = 108;
const MAX_TRACKED_SGPR: u8 = 107;
const MAX_TRACKED_SGPR_PAIR: u8 = 106;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PatchedDescBase {
    Table {
        user_sgpr: u32,
        table_byte_offset: u32,
    },
    RootDescriptor {
        user_sgpr: u32,
    },
    DynamicHeap(DynamicHeapOrigin),
    CbvIndexedHeap(CbvIndexedHeapSource),
    LaneIndexedHeap(LaneIndexedHeapSource),
    Vb {
        vb_slot: u32,
    },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SgprOrigin {
    /// Lattice bottom: scratch SGPR/VGPR not yet written on this path.
    Unwritten,
    /// Lattice top: overwritten with a non-tracked/dynamic value or conflicting origins.
    Unknown,
    /// Stale non-descriptor scratch value carried exclusively along an `s_cbranch_execz` bypass
    /// edge into a merge block (`exec == 0` path): joins cleanly with a `TableDesc` loaded on the
    /// active path, and drops to `Unknown` against any other origin.
    ExeczScratch,
    /// 48-bit aligned GPU VA packed into a 32-bit SGPR via `s_lshr_b64 s[dst], s[ptr], shift`
    /// (`shift` in `1..=16`). Never consumed directly; unwrapped ONLY by a matching `s_lshl_b64`
    /// with the exact same `shift` and zero high word.
    RightShiftedPtr {
        def_inst_idx: usize,
        user_sgpr: u32,
        table_byte_offset: Option<u32>,
        shift: u8,
    },
    /// 2-way CFG diamond joining two distinct static 32-byte-aligned `TableDesc` slots from the
    /// same `user_sgpr` (`offsets[0] < offsets[1]`). Lowered to a predicated 2-way store with both
    /// static `Table` bindings preserved (never collapsed or arbitrarily picked).
    TableDescChoice {
        user_sgpr: u32,
        offsets: [u32; 2],
        def_insts: [usize; 2],
    },
    /// Bounded dynamic CBV byte offset `idx * 4 + base_byte_offset` where `idx_sgpr < max_elems`
    /// (`max_elems` in `1..=8`, statically proven by a dominating `s_cmp_*` + `s_cbranch_scc*`).
    BoundedByteOffset {
        idx_sgpr: u8,
        base_byte_offset: u32,
        max_elems: u8,
    },
    /// Heap index dword loaded via `s_buffer_load_dword` from a known CBV at a `BoundedByteOffset`.
    BoundedCbvDword {
        load_inst_idx: usize,
        idx_sgpr: u8,
        cbv: CbvRefSource,
        base_byte_offset: u32,
        max_elems: u8,
    },
    /// Shifted `BoundedCbvDword` (`<< shift`, e.g. `<< 5` for 32-byte T# stride).
    BoundedScaledCbvDword {
        load_inst_idx: usize,
        idx_sgpr: u8,
        cbv: CbvRefSource,
        base_byte_offset: u32,
        max_elems: u8,
        shift: u8,
    },
    /// Descriptor loaded from an SM 6.6 heap via `BoundedScaledCbvDword`, lowered to a bounded
    /// `switch` over `max_elems` `CbvIndexedResourceHeap` bindings.
    BoundedCbvIndexedHeapDesc {
        def_inst_idx: usize,
        load_inst_idx: usize,
        idx_sgpr: u8,
        cbv: CbvRefSource,
        base_byte_offset: u32,
        max_elems: u8,
        shift: u8,
    },
    /// Hardware vertex-buffer table pointer (`s[0:1]` in vertex stages), optionally offset by bytes.
    VbTablePtr { byte_offset: i32 },
    /// Console user-data SGPR (`s8+` for graphics, `s4+` for compute), optionally offset by bytes.
    UserTable { user_sgpr: u32, byte_offset: i32 },
    /// Console user-data SGPR with high flag bit(s) masked off (e.g. `s_and_b32 s13, s14, 0x7fffffff`),
    /// promoted to `ScaledUserSgpr` once shifted left enough that every cleared bit is shifted out,
    /// or to `ScaledCbvDword` (`RootConstants`) if non-shifted mask bits remain.
    MaskedUserSgpr { user_sgpr: u32, mask: u32 },
    /// Shifted/scaled console user-data SGPR (`s_lshl_b32`, `s_mul_i32`, `s_mulk_i32`,
    /// `s_lshl{1..4}_add_u32`), used as a dynamic descriptor-heap byte offset.
    ScaledUserSgpr {
        user_sgpr: u32,
        stride: u32,
        shift: u32,
    },
    /// 32-bit GPUVA pointer formed by adding a heap base user SGPR and a scaled index user SGPR
    /// (`s_add_u32` / `s_add_i32` / `s_lshl{1..4}_add_u32`).
    DynamicHeapPtr(DynamicHeapOrigin),
    /// 32-bit scalar dword loaded from a known CBV or extracted/masked from root constants
    /// (`((dword_at(cbv, byte_offset) >> bit_offset) & mask)`), used to index SM 6.6 bindless
    /// descriptor heaps (`cbv_indexed_resource_heap` / `cbv_indexed_sampler_heap`, #1383).
    CbvDword {
        cbv: CbvRefSource,
        byte_offset: u32,
        bit_offset: u32,
        mask: u32,
    },
    /// Shifted/scaled `CbvDword` (`((dword >> bit_offset) & mask) << shift`), ready to serve as a
    /// dynamic descriptor-heap byte offset.
    ScaledCbvDword(CbvIndexedHeapSource),
    /// 32-bit GPUVA pointer formed by adding a descriptor-heap base and a `ScaledCbvDword`.
    CbvIndexedHeapPtr(CbvIndexedHeapSource),
    /// Per-lane VGPR-sourced index (`v_readfirstlane_b32` waterfall loop or bounded/offset VGPR),
    /// optionally bounded by a static bitmask/clamp (`max_count` in `1..=MAX_LANE_INDEXED_WINDOW`)
    /// and/or offset by a CBV-loaded `window_base` (S63 / #482 / #1394).
    LaneIndex {
        max_count: Option<u32>,
        window_base: Option<CbvDwordSource>,
    },
    /// Shifted/scaled per-lane heap index (`(window_base + lane_idx) << shift` or `* stride`),
    /// ready to serve as a dynamic descriptor-heap byte offset (S63 / #482 / #1394).
    ScaledLaneIndex(LaneIndexedHeapSource),
    /// 32-bit GPUVA pointer formed by adding a descriptor-heap base and a `ScaledLaneIndex`.
    LaneIndexedHeapPtr(LaneIndexedHeapSource),
    /// Descriptor dword (or nested table / CBV pointer) loaded from a user-data descriptor table
    /// via `s_load_dword*`.
    TableDesc {
        def_inst_idx: usize,
        user_sgpr: u32,
        table_byte_offset: u32,
        /// Additional constant byte offset applied to this loaded pointer via SALU.
        addr_offset: i32,
        /// Optional CBV dword identity `(cbv, byte_offset)` when this `s_load_dword*` read from a
        /// root CBV (`UserTable`) or 2-level table CBV pointer (`TableDesc` at a 32-byte slot).
        cbv_dword: Option<(CbvRefSource, u32)>,
    },
    /// Descriptor dword loaded from an SM 6.6 dynamic sampler/resource heap via `s_load_dword*`.
    DynamicHeapDesc {
        def_inst_idx: usize,
        origin: DynamicHeapOrigin,
    },
    /// Descriptor dword loaded from an SM 6.6 CB-indexed sampler/resource heap via `s_load_dword*`.
    CbvIndexedHeapDesc {
        def_inst_idx: usize,
        origin: CbvIndexedHeapSource,
    },
    /// Descriptor dword loaded from an SM 6.6 per-lane bindless sampler/resource heap via `s_load_dword*`.
    LaneIndexedHeapDesc {
        def_inst_idx: usize,
        origin: LaneIndexedHeapSource,
    },
    /// Descriptor dword loaded from an unknown/legacy table `sbase` (e.g. `s[0:1]` in pixel/compute),
    /// kept so unreflected indirect V# coalescing and spurious-CBV suppression survive copies/branches.
    RawTableDesc {
        def_inst_idx: usize,
        table_sbase: u8,
        table_offset: i32,
        is_dynamic: bool,
    },
    /// Vertex-buffer V# descriptor loaded from the hardware VB table (`s[0:1]`).
    VbDesc {
        def_inst_idx: usize,
        vb_slot: u32,
    },
    /// Descriptor word (e.g. GFX10.3 structured-buffer V# word 1/3) whose hardware attribute
    /// bits were masked/OR'd in-place (`s_and_b32 w1, 0xc000ffff`, `s_and_b32 w3, 0xcfffffff`,
    /// `s_or_b32 w3, 0x30000000`). Never treated as a dereferenceable `sbase` pointer; used only
    /// to recover the enclosing V# descriptor when word 0 was dynamically offset or reassembled.
    PatchedDescWord {
        def_inst_idx: usize,
        base: PatchedDescBase,
    },
    /// Materialized from immediate/literal constants (tracks exact `u32` value when statically known,
    /// and `def_inst_idx` to detect inline static sampler S#).
    ConstImmediate {
        def_inst_idx: usize,
        value: Option<u32>,
    },
    /// Merged/divergent descriptor-load origin whose exact static binding could not be uniquely
    /// resolved across divergent CFG branches or scalar selects (e.g. `if/else` loading two
    /// different sampler/resource offsets, 3+ branch choices, or mixing a table descriptor with
    /// an inline/dynamic/unknown origin).
    ///
    /// Preserves a representative `def_inst_idx` (with all merged reaching `s_load_dword*` defs
    /// linked via `divergent_def_aliases`) so downstream hardware descriptor consumers (`MIMG`
    /// T#/S#, `MUBUF`/`MTBUF` V#, `s_buffer_load_*` V#) still suppress the reaching descriptor
    /// loads instead of leaking bogus `RootDescriptor` CBVs, while `tainted_defs` continues to
    /// protect genuine non-descriptor CBV loads consumed by VALU/SALU arithmetic.
    DivergentDesc {
        def_inst_idx: usize,
    },
}

#[derive(Debug, Default)]
struct DescriptorAnalysis {
    vsharp_fetch_insts: BTreeSet<usize>,
    indirect_smem_cbv_keys: BTreeMap<usize, CbvKey>,
    cbv_sources: BTreeMap<CbvKey, WgslBindingSource>,
    inst_tex_keys: BTreeMap<usize, ResourceKey>,
    inst_samp_keys: BTreeMap<usize, ResourceKey>,
    inst_storage_buf_keys: BTreeMap<usize, ResourceKey>,
    inst_storage_tex_keys: BTreeMap<usize, ResourceKey>,
    inst_storage_buf_dispatches: BTreeMap<usize, StorageDispatch>,
    inst_storage_tex_dispatches: BTreeMap<usize, StorageDispatch>,
    choice_def_writes: BTreeMap<usize, Vec<(usize, ChoiceWrite)>>,
    choice_count: usize,
    vertex_storage_buf_insts: BTreeSet<usize>,
    vertex_fetch_vb_slots: BTreeMap<usize, u32>,
}

/// Maximum element count expanded for a statically-bounded dynamic CBV index array -> heap UAV.
const MAX_BOUNDED_CBV_HEAP_ELEMS: u8 = 8;

#[derive(Clone, PartialEq, Eq)]
struct OriginState {
    origins: [SgprOrigin; TRACKED_SGPR_COUNT],
    lane_origins: BTreeMap<(u8, u8), SgprOrigin>,
    vgpr_uniform_origins: [SgprOrigin; 256],
    /// Per-SGPR statically proven exclusive upper bound (`1..=MAX_BOUNDED_CBV_HEAP_ELEMS`, or `0`
    /// when unbounded) established by a dominating `s_cmp_*` + `s_cbranch_scc*` guard.
    bounded_sgprs: [u8; TRACKED_SGPR_COUNT],
    /// Upper-bound comparison `(sgpr, max_elems, in_bounds_when_scc1)` produced by the most recent
    /// `SOPC` / `SOPK` compare before an `s_cbranch_scc0/scc1`; cleared by any other SCC write.
    last_scc_bound: Option<(u8, u8, bool)>,
    /// Tracks an in-progress 32-bit 3-XOR in-place register swap (`s_xor_b32 a, a, b;
    /// s_xor_b32 b, a, b; s_xor_b32 a, a, b`) by remembering `(reg, orig_a, orig_b)` while
    /// `reg` holds `a ^ b`.
    pending_xor: Option<(u8, SgprOrigin, SgprOrigin)>,
    /// Tracks an in-progress 64-bit 3-XOR in-place register pair swap (`s_xor_b64 a, a, b;
    /// s_xor_b64 b, a, b; s_xor_b64 a, a, b`) by remembering `(pair_lo, orig_a, orig_b)` while
    /// `s[pair_lo:pair_lo+1]` holds `a ^ b`.
    pending_xor_pair: Option<(u8, (SgprOrigin, SgprOrigin), (SgprOrigin, SgprOrigin))>,
    /// Low SGPR written by the most recent 32-bit scalar add/sub (`s_add_u32`/`s_sub_u32`/etc.)
    /// that produced `SCC` carry/borrow; cleared by any other SCC-writing op so subsequent
    /// `s_addc_u32` / `s_subb_u32` / `s_add_u32 ..., src_scc` on `lo + 1` is provably high-word
    /// carry propagation.
    last_carry_lo_reg: Option<u8>,
}

impl OriginState {
    #[inline]
    fn sgpr_origin(&self, reg: u8) -> SgprOrigin {
        self.origins
            .get(usize::from(reg))
            .copied()
            .unwrap_or(SgprOrigin::Unknown)
    }

    #[inline]
    fn set_sgpr_origin(&mut self, reg: u8, origin: SgprOrigin) {
        if let Some(slot) = self.origins.get_mut(usize::from(reg)) {
            *slot = origin;
        }
        if let Some(b) = self.bounded_sgprs.get_mut(usize::from(reg)) {
            *b = 0;
        }
    }

    #[inline]
    fn sgpr_bound(&self, reg: u8) -> u8 {
        self.bounded_sgprs.get(usize::from(reg)).copied().unwrap_or(0)
    }

    #[inline]
    fn set_sgpr_bound(&mut self, reg: u8, max_elems: u8) {
        if let Some(b) = self.bounded_sgprs.get_mut(usize::from(reg)) {
            *b = max_elems;
        }
    }

    #[inline]
    fn vgpr_origin(&self, reg: u8) -> SgprOrigin {
        self.vgpr_uniform_origins
            .get(usize::from(reg))
            .copied()
            .unwrap_or(SgprOrigin::Unknown)
    }

    #[inline]
    fn set_vgpr_origin(&mut self, reg: u8, origin: SgprOrigin) {
        if let Some(slot) = self.vgpr_uniform_origins.get_mut(usize::from(reg)) {
            *slot = origin;
        }
    }

    fn initial(
        stage: ShaderStage,
        is_mesh: bool,
        unreferenced_user_sgprs: &[bool; MAX_USER_DATA_SGPR_LIMIT],
    ) -> Self {
        let mut origins = [SgprOrigin::Unwritten; TRACKED_SGPR_COUNT];
        // Seed console ABI initial SGPR origins:
        //   Mesh (lowered to compute):
        //             NGG/mesh system SGPRs in s0..s15, user data starts at s16..s47 (up to 32
        //             GFX10.3 SPI_SHADER_USER_DATA_GS_0..31 dwords, matching
        //             `runtime/gpu/stage_reflection.h` `kMeshUserDataBase = 16`).
        //   Graphics (vertex / fragment):
        //             system SGPRs in s0..s7 (vertex hardware VB table ptr in s[0:1]),
        //             user data starts at s8..s31; scratch SGPRs s32..s105 & vcc start Unwritten.
        //   Compute:  system SGPRs in s0..s3, user data starts at s4..s31; s32..s105 & vcc Unwritten.
        // Any register in user_base..user_limit that is not live-on-entry (never read, or
        // unconditionally written before any read along every path from entry) stays Unwritten so
        // CFG merges across guarded descriptor loads do not lose provenance.
        let user_base = initial_user_sgpr_base(stage, is_mesh);
        let user_limit = initial_user_sgpr_limit(is_mesh);
        for slot in origins.iter_mut().take(user_base) {
            *slot = SgprOrigin::Unknown;
        }
        if stage == ShaderStage::Vertex {
            origins[0] = SgprOrigin::VbTablePtr { byte_offset: 0 };
        }
        for (sgpr, slot) in origins.iter_mut().enumerate().take(user_limit).skip(user_base) {
            if !unreferenced_user_sgprs[sgpr] {
                *slot = SgprOrigin::UserTable {
                    user_sgpr: sgpr as u32,
                    byte_offset: 0,
                };
            }
        }
        Self {
            origins,
            lane_origins: BTreeMap::new(),
            vgpr_uniform_origins: [SgprOrigin::Unwritten; 256],
            bounded_sgprs: [0; TRACKED_SGPR_COUNT],
            last_scc_bound: None,
            pending_xor: None,
            pending_xor_pair: None,
            last_carry_lo_reg: None,
        }
    }

    /// Monotonic CFG dataflow join. Returns `true` if `self` changed.
    fn join_from(
        &mut self,
        other: &Self,
        def_aliases: &mut BTreeMap<usize, BTreeSet<usize>>,
        divergent_def_aliases: &mut BTreeMap<usize, BTreeSet<usize>>,
    ) -> bool {
        let mut changed = false;
        let prev_self_vgprs = self.vgpr_uniform_origins;
        for (dst, &src) in self.origins.iter_mut().zip(other.origins.iter()) {
            let joined = join_cfg_origin(*dst, src, Some(def_aliases), Some(divergent_def_aliases));
            if joined != *dst {
                *dst = joined;
                changed = true;
            }
        }
        for (dst, &src) in self
            .vgpr_uniform_origins
            .iter_mut()
            .zip(other.vgpr_uniform_origins.iter())
        {
            let joined = join_cfg_origin(*dst, src, Some(def_aliases), Some(divergent_def_aliases));
            if joined != *dst {
                *dst = joined;
                changed = true;
            }
        }
        if !self.lane_origins.is_empty() || !other.lane_origins.is_empty() {
            let mut to_remove = Vec::new();
            for (&k, dst) in &mut self.lane_origins {
                let src = other
                    .lane_origins
                    .get(&k)
                    .copied()
                    .unwrap_or_else(|| other.vgpr_origin(k.0));
                let joined =
                    join_cfg_origin(*dst, src, Some(def_aliases), Some(divergent_def_aliases));
                if matches!(joined, SgprOrigin::Unknown | SgprOrigin::Unwritten) {
                    to_remove.push(k);
                } else if joined != *dst {
                    *dst = joined;
                    changed = true;
                }
            }
            if !to_remove.is_empty() {
                for k in to_remove {
                    self.lane_origins.remove(&k);
                }
                changed = true;
            }
            for (&k, &src) in &other.lane_origins {
                if !self.lane_origins.contains_key(&k) {
                    let self_default = prev_self_vgprs
                        .get(usize::from(k.0))
                        .copied()
                        .unwrap_or(SgprOrigin::Unknown);
                    let joined = join_cfg_origin(
                        self_default,
                        src,
                        Some(def_aliases),
                        Some(divergent_def_aliases),
                    );
                    if !matches!(joined, SgprOrigin::Unknown | SgprOrigin::Unwritten) {
                        self.lane_origins.insert(k, joined);
                        changed = true;
                    }
                }
            }
        }
        for (dst_b, &src_b) in self
            .bounded_sgprs
            .iter_mut()
            .zip(other.bounded_sgprs.iter())
        {
            let joined = if *dst_b == 0 || src_b == 0 {
                0
            } else {
                (*dst_b).max(src_b)
            };
            if joined != *dst_b {
                *dst_b = joined;
                changed = true;
            }
        }
        if self.last_scc_bound != other.last_scc_bound && self.last_scc_bound.is_some() {
            self.last_scc_bound = None;
            changed = true;
        }
        if self.pending_xor != other.pending_xor && self.pending_xor.is_some() {
            self.pending_xor = None;
            changed = true;
        }
        if self.pending_xor_pair != other.pending_xor_pair && self.pending_xor_pair.is_some() {
            self.pending_xor_pair = None;
            changed = true;
        }
        if self.last_carry_lo_reg != other.last_carry_lo_reg && self.last_carry_lo_reg.is_some() {
            self.last_carry_lo_reg = None;
            changed = true;
        }
        changed
    }
}

struct BufferLoadUse {
    inst_idx: usize,
    def_inst_idx: usize,
    cbv_key: Option<CbvKey>,
    source: Option<WgslBindingSource>,
}

struct CbvPtrLoad {
    inst_idx: usize,
    ptr_def: usize,
    cbv_key: CbvKey,
    source: WgslBindingSource,
}

struct DirectRootCbvLoad {
    inst_idx: usize,
    user_sgpr: u32,
    /// `true` when `sbase` high word is a `ConstImmediate` (32-bit descriptor-table pointer
    /// idiom `s_mov_b32 s_hi, 0`) rather than `UserTable(user_sgpr + 1)` (64-bit Root VA).
    is_32bit_table_ptr: bool,
    /// Constant total byte offset (`ptr_byte_offset + offset + const_soffset`) for `s_load_dword*`.
    const_byte_offset: Option<i32>,
    /// Explicit SALU pointer offset (`UserTable.byte_offset`).
    ptr_byte_offset: i32,
    /// Loaded dword count for `s_load_dword*` (`0` for `s_buffer_load_*`).
    load_dwords: u8,
}

#[derive(Default)]
struct AnalysisCollector {
    out: DescriptorAnalysis,
    tainted_defs: BTreeSet<usize>,
    def_parents: BTreeMap<usize, usize>,
    def_aliases: BTreeMap<usize, BTreeSet<usize>>,
    divergent_def_aliases: BTreeMap<usize, BTreeSet<usize>>,
    direct_descriptor_defs: BTreeSet<usize>,
    raw_descriptor_defs: BTreeSet<usize>,
    divergent_descriptor_defs: BTreeSet<usize>,
    buffer_load_uses: Vec<BufferLoadUse>,
    cbv_ptr_loads: Vec<CbvPtrLoad>,
    direct_root_cbvs: Vec<DirectRootCbvLoad>,
    next_static_sampler_index: u32,
    static_sampler_by_def: BTreeMap<usize, u32>,
    two_way_choice_ids: BTreeMap<(u32, [u32; 2], [usize; 2]), usize>,
    bounded_choice_ids: BTreeMap<(usize, u8), usize>,
}

impl AnalysisCollector {
    fn alloc_two_way_choice(
        &mut self,
        user_sgpr: u32,
        offsets: [u32; 2],
        def_insts: [usize; 2],
    ) -> usize {
        let key = (user_sgpr, offsets, def_insts);
        if let Some(&id) = self.two_way_choice_ids.get(&key) {
            return id;
        }
        let id = self.out.choice_count;
        self.out.choice_count += 1;
        self.two_way_choice_ids.insert(key, id);
        self.direct_descriptor_defs.insert(def_insts[0]);
        self.direct_descriptor_defs.insert(def_insts[1]);
        for (arm, root_def) in [(0u32, def_insts[0]), (1u32, def_insts[1])] {
            let mut visited = BTreeSet::new();
            let mut stack = vec![root_def];
            while let Some(d) = stack.pop() {
                if !visited.insert(d) {
                    continue;
                }
                let entry = self.out.choice_def_writes.entry(d).or_default();
                let write = (id, ChoiceWrite::Const(arm));
                if !entry.contains(&write) {
                    entry.push(write);
                }
                if let Some(aliases) = self.def_aliases.get(&d) {
                    for &a in aliases {
                        if !visited.contains(&a) {
                            stack.push(a);
                        }
                    }
                }
            }
        }
        id
    }

    fn alloc_bounded_choice(&mut self, load_inst_idx: usize, idx_sgpr: u8) -> usize {
        let key = (load_inst_idx, idx_sgpr);
        if let Some(&id) = self.bounded_choice_ids.get(&key) {
            return id;
        }
        let id = self.out.choice_count;
        self.out.choice_count += 1;
        self.bounded_choice_ids.insert(key, id);
        let entry = self.out.choice_def_writes.entry(load_inst_idx).or_default();
        let write = (id, ChoiceWrite::CopySgpr(idx_sgpr));
        if !entry.contains(&write) {
            entry.push(write);
        }
        id
    }
}

fn decode_inline_u32_src(src: u16, literal: Option<u32>) -> Option<i32> {
    if src == 255 {
        literal.map(|v| v as i32)
    } else if (128..=192).contains(&src) {
        Some((src - 128) as i32)
    } else if (193..=208).contains(&src) {
        Some(-(src as i32 - 192))
    } else {
        None
    }
}

/// Exact IEEE-754 `f32` bit pattern for GFX10.3 inline float constants (`240..=248`).
fn decode_inline_float_u32(src: u16) -> Option<u32> {
    match src {
        240 => Some(0.5f32.to_bits()),
        241 => Some((-0.5f32).to_bits()),
        242 => Some(1.0f32.to_bits()),
        243 => Some((-1.0f32).to_bits()),
        244 => Some(2.0f32.to_bits()),
        245 => Some((-2.0f32).to_bits()),
        246 => Some(4.0f32.to_bits()),
        247 => Some((-4.0f32).to_bits()),
        248 => Some(0x3E22_F983), // 1 / (2 * pi)
        _ => None,
    }
}

/// Exact IEEE-754 `f64` bit pattern for GFX10.3 64-bit inline float constants (`240..=248`).
fn decode_inline_float_u64(src: u16) -> Option<u64> {
    match src {
        240 => Some(0.5f64.to_bits()),
        241 => Some((-0.5f64).to_bits()),
        242 => Some(1.0f64.to_bits()),
        243 => Some((-1.0f64).to_bits()),
        244 => Some(2.0f64.to_bits()),
        245 => Some((-2.0f64).to_bits()),
        246 => Some(4.0f64.to_bits()),
        247 => Some((-4.0f64).to_bits()),
        248 => Some(0x3FC4_5F30_6DC9_C883), // 1 / (2 * pi) in IEEE-754 binary64
        _ => None,
    }
}

/// Decode a static wave lane index (`0..=63`) from `v_readlane_b32` / `v_writelane_b32` `src1`.
/// Returns `None` when `src1` is a dynamic register (SGPR, `m0`, etc.).
fn decode_const_lane_index(src1: u16, literal: Option<u32>) -> Option<u8> {
    decode_inline_u32_src(src1, literal).map(|v| (v as u32 & 63) as u8)
}

#[inline]
fn origin_at(origins: &[SgprOrigin; TRACKED_SGPR_COUNT], idx: usize) -> SgprOrigin {
    origins.get(idx).copied().unwrap_or(SgprOrigin::Unknown)
}

fn resolve_const_u32(
    src: u8,
    literal: Option<u32>,
    origins: &[SgprOrigin; TRACKED_SGPR_COUNT],
) -> Option<u32> {
    if let Some(v) = decode_inline_u32_src(u16::from(src), literal) {
        Some(v as u32)
    } else if let Some(bits) = decode_inline_float_u32(u16::from(src)) {
        Some(bits)
    } else if src <= MAX_TRACKED_SGPR
        && let SgprOrigin::ConstImmediate { value: Some(v), .. } =
            origin_at(origins, usize::from(src))
    {
        Some(v)
    } else {
        None
    }
}

fn resolve_const_lane_index(
    src1: u16,
    literal: Option<u32>,
    origins: &[SgprOrigin; TRACKED_SGPR_COUNT],
) -> Option<u8> {
    if let Some(lane) = decode_const_lane_index(src1, literal) {
        Some(lane)
    } else if src1 <= u16::from(MAX_TRACKED_SGPR)
        && let SgprOrigin::ConstImmediate { value: Some(v), .. } =
            origin_at(origins, usize::from(src1))
    {
        Some((v & 63) as u8)
    } else {
        None
    }
}

fn is_const_src(src: u8, origins: &[SgprOrigin; TRACKED_SGPR_COUNT]) -> bool {
    src >= 128
        || (src <= MAX_TRACKED_SGPR
            && matches!(
                origin_at(origins, usize::from(src)),
                SgprOrigin::ConstImmediate { .. }
            ))
}

fn normalize_read_origin(o: SgprOrigin) -> SgprOrigin {
    if o == SgprOrigin::Unwritten {
        SgprOrigin::Unknown
    } else {
        o
    }
}

fn record_def_alias(
    def_aliases: Option<&mut BTreeMap<usize, BTreeSet<usize>>>,
    d1: usize,
    d2: usize,
) {
    if d1 != d2
        && let Some(aliases) = def_aliases
    {
        aliases.entry(d1.min(d2)).or_default().insert(d1.max(d2));
    }
}

fn resolve_src_origin_u8(
    src: u8,
    literal: Option<u32>,
    inst_idx: usize,
    origins: &[SgprOrigin; TRACKED_SGPR_COUNT],
) -> SgprOrigin {
    if src <= MAX_TRACKED_SGPR {
        normalize_read_origin(origin_at(origins, usize::from(src)))
    } else if let Some(v) = decode_inline_u32_src(u16::from(src), literal) {
        SgprOrigin::ConstImmediate {
            def_inst_idx: inst_idx,
            value: Some(v as u32),
        }
    } else if let Some(bits) = decode_inline_float_u32(u16::from(src)) {
        SgprOrigin::ConstImmediate {
            def_inst_idx: inst_idx,
            value: Some(bits),
        }
    } else if src >= 128 {
        SgprOrigin::ConstImmediate {
            def_inst_idx: inst_idx,
            value: None,
        }
    } else {
        SgprOrigin::Unknown
    }
}

fn resolve_src_pair_origins(
    src: u8,
    literal: Option<u32>,
    inst_idx: usize,
    origins: &[SgprOrigin; TRACKED_SGPR_COUNT],
) -> (SgprOrigin, SgprOrigin) {
    if src <= MAX_TRACKED_SGPR {
        let lo = normalize_read_origin(origin_at(origins, usize::from(src)));
        let hi = if let Some(hi_reg) = checked_tracked_sgpr_reg(src, 1) {
            normalize_read_origin(origin_at(origins, usize::from(hi_reg)))
        } else {
            SgprOrigin::Unknown
        };
        (lo, hi)
    } else if let Some(v) = decode_inline_u32_src(u16::from(src), literal) {
        let hi_val = if src == 0xFF {
            0
        } else if v < 0 {
            u32::MAX
        } else {
            0
        };
        (
            SgprOrigin::ConstImmediate {
                def_inst_idx: inst_idx,
                value: Some(v as u32),
            },
            SgprOrigin::ConstImmediate {
                def_inst_idx: inst_idx,
                value: Some(hi_val),
            },
        )
    } else if let Some(bits) = decode_inline_float_u64(u16::from(src)) {
        (
            SgprOrigin::ConstImmediate {
                def_inst_idx: inst_idx,
                value: Some(bits as u32),
            },
            SgprOrigin::ConstImmediate {
                def_inst_idx: inst_idx,
                value: Some((bits >> 32) as u32),
            },
        )
    } else if src >= 128 {
        let c = SgprOrigin::ConstImmediate {
            def_inst_idx: inst_idx,
            value: None,
        };
        (c, c)
    } else {
        (SgprOrigin::Unknown, SgprOrigin::Unknown)
    }
}

/// Extract all 4 statically known GFX10 S# descriptor dwords from `s[samp_sgpr .. samp_sgpr+3]`
/// when every register in the quad holds `ConstImmediate { value: Some(d), .. }`.
fn resolve_inline_sampler_sdwords(
    origins: &[SgprOrigin; TRACKED_SGPR_COUNT],
    samp_sgpr: u8,
) -> Option<[u32; 4]> {
    let base = usize::from(samp_sgpr);
    let mut sdwords = [0u32; 4];
    for (i, slot) in sdwords.iter_mut().enumerate() {
        let idx = base.checked_add(i)?;
        match origins.get(idx).copied()? {
            SgprOrigin::ConstImmediate { value: Some(v), .. } => *slot = v,
            _ => return None,
        }
    }
    Some(sdwords)
}

fn is_known_descriptor_or_table(o: SgprOrigin) -> bool {
    matches!(
        o,
        SgprOrigin::VbTablePtr { .. }
            | SgprOrigin::UserTable { .. }
            | SgprOrigin::MaskedUserSgpr { .. }
            | SgprOrigin::ScaledUserSgpr { .. }
            | SgprOrigin::DynamicHeapPtr(_)
            | SgprOrigin::CbvDword { .. }
            | SgprOrigin::ScaledCbvDword(_)
            | SgprOrigin::CbvIndexedHeapPtr(_)
            | SgprOrigin::LaneIndex { .. }
            | SgprOrigin::ScaledLaneIndex(_)
            | SgprOrigin::LaneIndexedHeapPtr(_)
            | SgprOrigin::TableDesc { .. }
            | SgprOrigin::TableDescChoice { .. }
            | SgprOrigin::RightShiftedPtr { .. }
            | SgprOrigin::BoundedCbvIndexedHeapDesc { .. }
            | SgprOrigin::DynamicHeapDesc { .. }
            | SgprOrigin::CbvIndexedHeapDesc { .. }
            | SgprOrigin::LaneIndexedHeapDesc { .. }
            | SgprOrigin::VbDesc { .. }
            | SgprOrigin::RawTableDesc { .. }
            | SgprOrigin::PatchedDescWord { .. }
            | SgprOrigin::DivergentDesc { .. }
    )
}

/// Extract reaching `s_load_dword*` descriptor-definition instruction index(es) carried by an
/// `SgprOrigin`. Excludes non-SMEM origins (such as `ConstImmediate` and synthesized
/// `PatchedDescBase::RootDescriptor` SALU words).
fn loaded_desc_defs(origin: SgprOrigin) -> Option<(usize, Option<usize>)> {
    match origin {
        SgprOrigin::TableDesc { def_inst_idx, .. }
        | SgprOrigin::DynamicHeapDesc { def_inst_idx, .. }
        | SgprOrigin::CbvIndexedHeapDesc { def_inst_idx, .. }
        | SgprOrigin::LaneIndexedHeapDesc { def_inst_idx, .. }
        | SgprOrigin::BoundedCbvIndexedHeapDesc { def_inst_idx, .. }
        | SgprOrigin::RawTableDesc { def_inst_idx, .. }
        | SgprOrigin::VbDesc { def_inst_idx, .. }
        | SgprOrigin::DivergentDesc { def_inst_idx } => Some((def_inst_idx, None)),
        SgprOrigin::TableDescChoice { def_insts, .. } => Some((def_insts[0], Some(def_insts[1]))),
        SgprOrigin::PatchedDescWord {
            def_inst_idx,
            base,
        } if !matches!(base, PatchedDescBase::RootDescriptor { .. }) => Some((def_inst_idx, None)),
        _ => None,
    }
}

/// Collapse two non-unifiable origins while preserving any reaching descriptor-load `def_inst_idx`
/// values in `SgprOrigin::DivergentDesc` and linking them in `divergent_def_aliases`.
/// Returns `SgprOrigin::Unknown` when neither side carries a loaded descriptor def.
fn merge_divergent_desc(
    a: SgprOrigin,
    b: SgprOrigin,
    mut divergent_def_aliases: Option<&mut BTreeMap<usize, BTreeSet<usize>>>,
) -> SgprOrigin {
    let mut min_def: Option<usize> = None;
    let mut add_def = |d: usize| {
        if let Some(cur) = min_def {
            record_def_alias(divergent_def_aliases.as_deref_mut(), cur, d);
            min_def = Some(cur.min(d));
        } else {
            min_def = Some(d);
        }
    };
    if let Some((d0, d1)) = loaded_desc_defs(a) {
        add_def(d0);
        if let Some(d) = d1 {
            add_def(d);
        }
    }
    if let Some((d0, d1)) = loaded_desc_defs(b) {
        add_def(d0);
        if let Some(d) = d1 {
            add_def(d);
        }
    }
    match min_def {
        Some(def_inst_idx) => SgprOrigin::DivergentDesc { def_inst_idx },
        None => SgprOrigin::Unknown,
    }
}

fn patched_desc_word_of(origin: SgprOrigin) -> Option<(usize, PatchedDescBase)> {
    match origin {
        SgprOrigin::TableDesc {
            def_inst_idx,
            user_sgpr,
            table_byte_offset,
            ..
        } => Some((
            def_inst_idx,
            PatchedDescBase::Table {
                user_sgpr,
                table_byte_offset,
            },
        )),
        SgprOrigin::DynamicHeapDesc {
            def_inst_idx,
            origin,
        } => Some((def_inst_idx, PatchedDescBase::DynamicHeap(origin))),
        SgprOrigin::CbvIndexedHeapDesc {
            def_inst_idx,
            origin,
        } => Some((def_inst_idx, PatchedDescBase::CbvIndexedHeap(origin))),
        SgprOrigin::LaneIndexedHeapDesc {
            def_inst_idx,
            origin,
        } => Some((def_inst_idx, PatchedDescBase::LaneIndexedHeap(origin))),
        SgprOrigin::VbDesc {
            def_inst_idx,
            vb_slot,
        } => Some((def_inst_idx, PatchedDescBase::Vb { vb_slot })),
        SgprOrigin::PatchedDescWord { def_inst_idx, base } => Some((def_inst_idx, base)),
        _ => None,
    }
}

#[inline]
fn lane_bound_from_upper_inclusive(upper_inclusive: u32) -> u32 {
    if upper_inclusive < MAX_LANE_INDEXED_WINDOW {
        upper_inclusive + 1
    } else {
        MAX_LANE_INDEXED_WINDOW
    }
}

#[inline]
fn tighten_lane_max_count(prev: Option<u32>, bound: u32) -> u32 {
    let clamped = bound.clamp(1, MAX_LANE_INDEXED_WINDOW);
    prev.map_or(clamped, |p| p.min(clamped).clamp(1, MAX_LANE_INDEXED_WINDOW))
}

#[inline]
fn finalize_lane_max_count(max_count: Option<u32>) -> u32 {
    max_count
        .unwrap_or(DEFAULT_LANE_INDEXED_WINDOW)
        .clamp(1, MAX_LANE_INDEXED_WINDOW)
}

#[inline]
fn is_lane_origin(o: SgprOrigin) -> bool {
    matches!(
        o,
        SgprOrigin::LaneIndex { .. }
            | SgprOrigin::ScaledLaneIndex(_)
            | SgprOrigin::LaneIndexedHeapPtr(_)
    )
}

fn cbv_dword_from_origin(origin: SgprOrigin) -> Option<CbvDwordSource> {
    match origin {
        SgprOrigin::CbvDword {
            cbv,
            byte_offset,
            bit_offset,
            mask,
        } if byte_offset.is_multiple_of(4) && bit_offset < 32 && mask != 0 => {
            Some(CbvDwordSource {
                cbv,
                byte_offset,
                bit_offset,
                mask,
            })
        }
        SgprOrigin::TableDesc {
            cbv_dword: Some((cbv, byte_offset)),
            addr_offset: 0,
            ..
        } if byte_offset.is_multiple_of(4) => Some(CbvDwordSource {
            cbv,
            byte_offset,
            bit_offset: 0,
            mask: u32::MAX,
        }),
        SgprOrigin::MaskedUserSgpr { user_sgpr, mask } if mask != 0 => Some(CbvDwordSource {
            cbv: CbvRefSource::RootConstants { user_sgpr },
            byte_offset: 0,
            bit_offset: 0,
            mask,
        }),
        _ => None,
    }
}

fn apply_min_const(origin: SgprOrigin, limit: u32, signed: bool) -> SgprOrigin {
    if signed && (limit as i32) < 0 {
        return SgprOrigin::Unknown;
    }
    match origin {
        SgprOrigin::LaneIndex {
            max_count,
            window_base: None,
        } => SgprOrigin::LaneIndex {
            max_count: Some(tighten_lane_max_count(
                max_count,
                lane_bound_from_upper_inclusive(limit),
            )),
            window_base: None,
        },
        SgprOrigin::LaneIndex {
            max_count,
            window_base: Some(wb),
        } => {
            if limit < MAX_LANE_INDEXED_WINDOW {
                SgprOrigin::LaneIndex {
                    max_count: Some(limit + 1),
                    window_base: None,
                }
            } else {
                SgprOrigin::LaneIndex {
                    max_count,
                    window_base: Some(wb),
                }
            }
        }
        _ => SgprOrigin::Unknown,
    }
}

fn combine_add_lane_origins(a: SgprOrigin, b: SgprOrigin) -> Option<SgprOrigin> {
    match (a, b) {
        (
            SgprOrigin::LaneIndex {
                max_count,
                window_base: None,
            },
            other,
        )
        | (
            other,
            SgprOrigin::LaneIndex {
                max_count,
                window_base: None,
            },
        ) => {
            if let Some(wb) = cbv_dword_from_origin(other) {
                Some(SgprOrigin::LaneIndex {
                    max_count,
                    window_base: Some(wb),
                })
            } else if let SgprOrigin::UserTable {
                user_sgpr,
                byte_offset: 0,
            } = other
            {
                Some(SgprOrigin::LaneIndex {
                    max_count,
                    window_base: Some(CbvDwordSource {
                        cbv: CbvRefSource::RootConstants { user_sgpr },
                        byte_offset: 0,
                        bit_offset: 0,
                        mask: u32::MAX,
                    }),
                })
            } else {
                None
            }
        }
        (
            SgprOrigin::LaneIndex {
                max_count,
                window_base,
            },
            SgprOrigin::UserTable { byte_offset: 0, .. },
        )
        | (
            SgprOrigin::UserTable { byte_offset: 0, .. },
            SgprOrigin::LaneIndex {
                max_count,
                window_base,
            },
        ) => Some(SgprOrigin::LaneIndexedHeapPtr(LaneIndexedHeapSource {
            max_count: finalize_lane_max_count(max_count),
            shift: 0,
            stride: 0,
            window_base,
        })),
        (SgprOrigin::ScaledLaneIndex(h), SgprOrigin::UserTable { byte_offset: 0, .. })
        | (SgprOrigin::UserTable { byte_offset: 0, .. }, SgprOrigin::ScaledLaneIndex(h)) => {
            Some(SgprOrigin::LaneIndexedHeapPtr(h))
        }
        (SgprOrigin::ScaledLaneIndex(h), SgprOrigin::Unknown | SgprOrigin::TableDesc { .. })
        | (SgprOrigin::Unknown | SgprOrigin::TableDesc { .. }, SgprOrigin::ScaledLaneIndex(h))
            if h.shift > 0 || h.stride > 1 =>
        {
            Some(SgprOrigin::LaneIndexedHeapPtr(h))
        }
        (SgprOrigin::ScaledLaneIndex(mut h), SgprOrigin::ScaledCbvDword(c))
        | (SgprOrigin::ScaledCbvDword(c), SgprOrigin::ScaledLaneIndex(mut h))
            if h.window_base.is_none()
                && h.shift == c.shift
                && h.stride == c.stride
                && c.byte_offset.is_multiple_of(4)
                && c.bit_offset < 32
                && c.mask != 0 =>
        {
            h.window_base = Some(CbvDwordSource {
                cbv: c.cbv,
                byte_offset: c.byte_offset,
                bit_offset: c.bit_offset,
                mask: c.mask,
            });
            Some(SgprOrigin::ScaledLaneIndex(h))
        }
        (
            SgprOrigin::ScaledLaneIndex(mut h),
            SgprOrigin::ScaledUserSgpr {
                user_sgpr,
                stride,
                shift,
            },
        )
        | (
            SgprOrigin::ScaledUserSgpr {
                user_sgpr,
                stride,
                shift,
            },
            SgprOrigin::ScaledLaneIndex(mut h),
        ) if h.window_base.is_none() && h.shift == shift && h.stride == stride => {
            h.window_base = Some(CbvDwordSource {
                cbv: CbvRefSource::RootConstants { user_sgpr },
                byte_offset: 0,
                bit_offset: 0,
                mask: u32::MAX,
            });
            Some(SgprOrigin::ScaledLaneIndex(h))
        }
        _ => None,
    }
}

fn combine_add_origins(a: SgprOrigin, b: SgprOrigin) -> Option<SgprOrigin> {
    match (a, b) {
        (
            SgprOrigin::UserTable {
                user_sgpr: base_user_sgpr,
                byte_offset: 0,
            },
            SgprOrigin::ScaledUserSgpr {
                user_sgpr: index_user_sgpr,
                stride,
                shift: index_shift,
            },
        )
        | (
            SgprOrigin::ScaledUserSgpr {
                user_sgpr: index_user_sgpr,
                stride,
                shift: index_shift,
            },
            SgprOrigin::UserTable {
                user_sgpr: base_user_sgpr,
                byte_offset: 0,
            },
        ) => {
            if base_user_sgpr == index_user_sgpr {
                stride
                    .checked_add(1)
                    .map(|new_stride| make_scaled_user_sgpr(index_user_sgpr, new_stride))
            } else {
                Some(SgprOrigin::DynamicHeapPtr(DynamicHeapOrigin {
                    base_user_sgpr,
                    stride,
                    index_user_sgpr,
                    index_shift,
                }))
            }
        }
        (
            SgprOrigin::ScaledUserSgpr {
                user_sgpr,
                stride,
                shift,
            },
            SgprOrigin::TableDesc { .. },
        )
        | (
            SgprOrigin::TableDesc { .. },
            SgprOrigin::ScaledUserSgpr {
                user_sgpr,
                stride,
                shift,
            },
        ) if shift > 0 && stride == (1u32 << shift) => {
            Some(SgprOrigin::CbvIndexedHeapPtr(CbvIndexedHeapSource {
                cbv: CbvRefSource::RootConstants { user_sgpr },
                byte_offset: 0,
                shift,
                bit_offset: 0,
                mask: u32::MAX,
                stride,
            }))
        }
        (
            SgprOrigin::ScaledUserSgpr {
                user_sgpr,
                stride,
                shift,
            },
            SgprOrigin::Unknown,
        )
        | (
            SgprOrigin::Unknown,
            SgprOrigin::ScaledUserSgpr {
                user_sgpr,
                stride,
                shift,
            },
        ) if shift >= 4 && stride == (1u32 << shift) => {
            Some(SgprOrigin::CbvIndexedHeapPtr(CbvIndexedHeapSource {
                cbv: CbvRefSource::RootConstants { user_sgpr },
                byte_offset: 0,
                shift,
                bit_offset: 0,
                mask: u32::MAX,
                stride,
            }))
        }
        (SgprOrigin::UserTable { byte_offset: 0, .. }, SgprOrigin::ScaledCbvDword(h))
        | (SgprOrigin::ScaledCbvDword(h), SgprOrigin::UserTable { byte_offset: 0, .. }) => {
            Some(SgprOrigin::CbvIndexedHeapPtr(h))
        }
        (SgprOrigin::Unknown | SgprOrigin::TableDesc { .. }, SgprOrigin::ScaledCbvDword(h))
        | (SgprOrigin::ScaledCbvDword(h), SgprOrigin::Unknown | SgprOrigin::TableDesc { .. })
            if h.shift > 0 =>
        {
            Some(SgprOrigin::CbvIndexedHeapPtr(h))
        }
        (
            SgprOrigin::UserTable { byte_offset: 0, .. },
            SgprOrigin::CbvDword {
                cbv,
                byte_offset,
                bit_offset,
                mask,
            },
        )
        | (
            SgprOrigin::CbvDword {
                cbv,
                byte_offset,
                bit_offset,
                mask,
            },
            SgprOrigin::UserTable { byte_offset: 0, .. },
        ) => Some(SgprOrigin::CbvIndexedHeapPtr(CbvIndexedHeapSource {
            cbv,
            byte_offset,
            shift: 0,
            bit_offset,
            mask,
            stride: 0,
        })),
        _ => {
            if let Some(lane_combined) = combine_add_lane_origins(a, b) {
                Some(lane_combined)
            } else if let (Some((u0, s0)), Some((u1, s1))) =
                (scaled_user_sgpr_stride(a), scaled_user_sgpr_stride(b))
                && u0 == u1
                && let Some(new_stride) = s0.checked_add(s1)
            {
                Some(make_scaled_user_sgpr(u0, new_stride))
            } else {
                None
            }
        }
    }
}

fn is_const_zero(o: SgprOrigin) -> bool {
    matches!(o, SgprOrigin::ConstImmediate { value: Some(0), .. })
}

/// Monotonic lattice join for CFG block merges:
/// `Unwritten (Bottom) < ConstZero < { NonZeroConst | KnownTable/Desc } < TableDescChoice < Unknown < DivergentDesc (Top)`.
fn join_cfg_origin(
    a: SgprOrigin,
    b: SgprOrigin,
    mut def_aliases: Option<&mut BTreeMap<usize, BTreeSet<usize>>>,
    divergent_def_aliases: Option<&mut BTreeMap<usize, BTreeSet<usize>>>,
) -> SgprOrigin {
    if a == b {
        return a;
    }
    match (a, b) {
        (SgprOrigin::Unwritten, other) | (other, SgprOrigin::Unwritten) => other,
        (SgprOrigin::Unknown, other) | (other, SgprOrigin::Unknown) => {
            merge_divergent_desc(SgprOrigin::Unknown, other, divergent_def_aliases)
        }
        (
            SgprOrigin::ExeczScratch,
            td @ (SgprOrigin::TableDesc { .. } | SgprOrigin::TableDescChoice { .. }),
        )
        | (
            td @ (SgprOrigin::TableDesc { .. } | SgprOrigin::TableDescChoice { .. }),
            SgprOrigin::ExeczScratch,
        ) => td,
        (SgprOrigin::ExeczScratch, other) | (other, SgprOrigin::ExeczScratch) => {
            merge_divergent_desc(SgprOrigin::ExeczScratch, other, divergent_def_aliases)
        }
        (
            SgprOrigin::RightShiftedPtr {
                def_inst_idx: d1,
                user_sgpr: u1,
                table_byte_offset: o1,
                shift: sh1,
            },
            SgprOrigin::RightShiftedPtr {
                def_inst_idx: d2,
                user_sgpr: u2,
                table_byte_offset: o2,
                shift: sh2,
            },
        ) if u1 == u2 && o1 == o2 && sh1 == sh2 => {
            record_def_alias(def_aliases, d1, d2);
            SgprOrigin::RightShiftedPtr {
                def_inst_idx: d1.min(d2),
                user_sgpr: u1,
                table_byte_offset: o1,
                shift: sh1,
            }
        }
        (
            SgprOrigin::TableDesc {
                def_inst_idx: d1,
                user_sgpr: u1,
                table_byte_offset: o1,
                addr_offset: ao1,
                cbv_dword: c1,
            },
            SgprOrigin::TableDesc {
                def_inst_idx: d2,
                user_sgpr: u2,
                table_byte_offset: o2,
                addr_offset: ao2,
                cbv_dword: c2,
            },
        ) if u1 == u2 && o1 == o2 && ao1 == ao2 => {
            record_def_alias(def_aliases, d1, d2);
            SgprOrigin::TableDesc {
                def_inst_idx: d1.min(d2),
                user_sgpr: u1,
                table_byte_offset: o1,
                addr_offset: ao1,
                cbv_dword: if c1 == c2 { c1 } else { None },
            }
        }
        (
            SgprOrigin::TableDesc {
                def_inst_idx: d1,
                user_sgpr: u1,
                table_byte_offset: o1,
                addr_offset: 0,
                ..
            },
            SgprOrigin::TableDesc {
                def_inst_idx: d2,
                user_sgpr: u2,
                table_byte_offset: o2,
                addr_offset: 0,
                ..
            },
        ) if u1 == u2 && o1 != o2 && o1 % 32 == 0 && o2 % 32 == 0 => {
            if o1 < o2 {
                SgprOrigin::TableDescChoice {
                    user_sgpr: u1,
                    offsets: [o1, o2],
                    def_insts: [d1, d2],
                }
            } else {
                SgprOrigin::TableDescChoice {
                    user_sgpr: u1,
                    offsets: [o2, o1],
                    def_insts: [d2, d1],
                }
            }
        }
        (
            SgprOrigin::TableDescChoice {
                user_sgpr: u1,
                offsets,
                def_insts,
            },
            SgprOrigin::TableDesc {
                def_inst_idx: d2,
                user_sgpr: u2,
                table_byte_offset: o2,
                addr_offset: 0,
                ..
            },
        )
        | (
            SgprOrigin::TableDesc {
                def_inst_idx: d2,
                user_sgpr: u2,
                table_byte_offset: o2,
                addr_offset: 0,
                ..
            },
            SgprOrigin::TableDescChoice {
                user_sgpr: u1,
                offsets,
                def_insts,
            },
        ) if u1 == u2 && (o2 == offsets[0] || o2 == offsets[1]) => {
            let mut next_defs = def_insts;
            let slot = usize::from(o2 == offsets[1]);
            record_def_alias(def_aliases, next_defs[slot], d2);
            next_defs[slot] = next_defs[slot].min(d2);
            SgprOrigin::TableDescChoice {
                user_sgpr: u1,
                offsets,
                def_insts: next_defs,
            }
        }
        (
            SgprOrigin::TableDescChoice {
                user_sgpr: u1,
                offsets: off1,
                def_insts: d1,
            },
            SgprOrigin::TableDescChoice {
                user_sgpr: u2,
                offsets: off2,
                def_insts: d2,
            },
        ) if u1 == u2 && off1 == off2 => {
            record_def_alias(def_aliases.as_deref_mut(), d1[0], d2[0]);
            record_def_alias(def_aliases, d1[1], d2[1]);
            SgprOrigin::TableDescChoice {
                user_sgpr: u1,
                offsets: off1,
                def_insts: [d1[0].min(d2[0]), d1[1].min(d2[1])],
            }
        }
        (
            SgprOrigin::DynamicHeapDesc {
                def_inst_idx: d1,
                origin: h1,
            },
            SgprOrigin::DynamicHeapDesc {
                def_inst_idx: d2,
                origin: h2,
            },
        ) if h1 == h2 => {
            record_def_alias(def_aliases, d1, d2);
            SgprOrigin::DynamicHeapDesc {
                def_inst_idx: d1.min(d2),
                origin: h1,
            }
        }
        (
            SgprOrigin::CbvIndexedHeapDesc {
                def_inst_idx: d1,
                origin: h1,
            },
            SgprOrigin::CbvIndexedHeapDesc {
                def_inst_idx: d2,
                origin: h2,
            },
        ) if h1 == h2 => {
            record_def_alias(def_aliases, d1, d2);
            SgprOrigin::CbvIndexedHeapDesc {
                def_inst_idx: d1.min(d2),
                origin: h1,
            }
        }
        (
            SgprOrigin::LaneIndex {
                max_count: m1,
                window_base: w1,
            },
            SgprOrigin::LaneIndex {
                max_count: m2,
                window_base: w2,
            },
        ) if w1 == w2 => SgprOrigin::LaneIndex {
            max_count: m1.zip(m2).map(|(a, b)| a.max(b)),
            window_base: w1,
        },
        (SgprOrigin::ScaledLaneIndex(h1), SgprOrigin::ScaledLaneIndex(h2))
            if h1.shift == h2.shift && h1.stride == h2.stride && h1.window_base == h2.window_base =>
        {
            SgprOrigin::ScaledLaneIndex(LaneIndexedHeapSource {
                max_count: h1.max_count.max(h2.max_count),
                ..h1
            })
        }
        (SgprOrigin::LaneIndexedHeapPtr(h1), SgprOrigin::LaneIndexedHeapPtr(h2))
            if h1.shift == h2.shift && h1.stride == h2.stride && h1.window_base == h2.window_base =>
        {
            SgprOrigin::LaneIndexedHeapPtr(LaneIndexedHeapSource {
                max_count: h1.max_count.max(h2.max_count),
                ..h1
            })
        }
        (
            SgprOrigin::LaneIndexedHeapDesc {
                def_inst_idx: d1,
                origin: h1,
            },
            SgprOrigin::LaneIndexedHeapDesc {
                def_inst_idx: d2,
                origin: h2,
            },
        ) if h1.shift == h2.shift && h1.stride == h2.stride && h1.window_base == h2.window_base => {
            record_def_alias(def_aliases, d1, d2);
            SgprOrigin::LaneIndexedHeapDesc {
                def_inst_idx: d1.min(d2),
                origin: LaneIndexedHeapSource {
                    max_count: h1.max_count.max(h2.max_count),
                    ..h1
                },
            }
        }
        (
            SgprOrigin::VbDesc {
                def_inst_idx: d1,
                vb_slot: v1,
            },
            SgprOrigin::VbDesc {
                def_inst_idx: d2,
                vb_slot: v2,
            },
        ) if v1 == v2 => {
            record_def_alias(def_aliases, d1, d2);
            SgprOrigin::VbDesc {
                def_inst_idx: d1.min(d2),
                vb_slot: v1,
            }
        }
        (
            SgprOrigin::RawTableDesc {
                def_inst_idx: d1,
                table_sbase: b1,
                table_offset: o1,
                is_dynamic: dyn1,
            },
            SgprOrigin::RawTableDesc {
                def_inst_idx: d2,
                table_sbase: b2,
                table_offset: o2,
                is_dynamic: dyn2,
            },
        ) if b1 == b2 && o1 == o2 && dyn1 == dyn2 => {
            record_def_alias(def_aliases, d1, d2);
            SgprOrigin::RawTableDesc {
                def_inst_idx: d1.min(d2),
                table_sbase: b1,
                table_offset: o1,
                is_dynamic: dyn1,
            }
        }
        (
            SgprOrigin::PatchedDescWord {
                def_inst_idx: d1,
                base: b1,
            },
            other,
        )
        | (
            other,
            SgprOrigin::PatchedDescWord {
                def_inst_idx: d1,
                base: b1,
            },
        ) if patched_desc_word_of(other).is_some_and(|(_, b2)| b1 == b2) => {
            if let Some((d2, _)) = patched_desc_word_of(other) {
                record_def_alias(def_aliases, d1, d2);
                SgprOrigin::PatchedDescWord {
                    def_inst_idx: d1.min(d2),
                    base: b1,
                }
            } else {
                SgprOrigin::Unknown
            }
        }
        (
            SgprOrigin::ConstImmediate {
                def_inst_idx: d1,
                value: v1,
            },
            SgprOrigin::ConstImmediate {
                def_inst_idx: d2,
                value: v2,
            },
        ) => SgprOrigin::ConstImmediate {
            def_inst_idx: d1.min(d2),
            value: if v1 == v2 { v1 } else { None },
        },
        // Zero-init / null-pointer fallback (`0`) promotes to the non-null table/descriptor origin.
        (z, known) | (known, z) if is_const_zero(z) && is_known_descriptor_or_table(known) => known,
        _ => merge_divergent_desc(a, b, divergent_def_aliases),
    }
}

/// Merge two branch origins for `s_cmov_b32/b64`, `s_cmovk_i32`, `s_cselect_b32/b64`.
/// Preserves the origin when both branches agree or when one branch is a known table/descriptor
/// origin and the other is `Unknown`, `Unwritten`, or a constant fallback (e.g. null-pointer guard).
fn merge_select_origin(
    a: SgprOrigin,
    b: SgprOrigin,
    inst_idx: usize,
    def_aliases: Option<&mut BTreeMap<usize, BTreeSet<usize>>>,
    divergent_def_aliases: Option<&mut BTreeMap<usize, BTreeSet<usize>>>,
) -> SgprOrigin {
    if a == b {
        return a;
    }
    match (a, b) {
        (SgprOrigin::Unwritten, other) | (other, SgprOrigin::Unwritten) => other,
        (
            SgprOrigin::TableDesc {
                def_inst_idx: d1,
                user_sgpr: u1,
                table_byte_offset: o1,
                addr_offset: ao1,
                cbv_dword: c1,
            },
            SgprOrigin::TableDesc {
                def_inst_idx: d2,
                user_sgpr: u2,
                table_byte_offset: o2,
                addr_offset: ao2,
                cbv_dword: c2,
            },
        ) if u1 == u2 && o1 == o2 && ao1 == ao2 => {
            record_def_alias(def_aliases, d1, d2);
            SgprOrigin::TableDesc {
                def_inst_idx: d1.min(d2),
                user_sgpr: u1,
                table_byte_offset: o1,
                addr_offset: ao1,
                cbv_dword: if c1 == c2 { c1 } else { None },
            }
        }
        (
            SgprOrigin::DynamicHeapDesc {
                def_inst_idx: d1,
                origin: h1,
            },
            SgprOrigin::DynamicHeapDesc {
                def_inst_idx: d2,
                origin: h2,
            },
        ) if h1 == h2 => {
            record_def_alias(def_aliases, d1, d2);
            SgprOrigin::DynamicHeapDesc {
                def_inst_idx: d1.min(d2),
                origin: h1,
            }
        }
        (
            SgprOrigin::CbvIndexedHeapDesc {
                def_inst_idx: d1,
                origin: h1,
            },
            SgprOrigin::CbvIndexedHeapDesc {
                def_inst_idx: d2,
                origin: h2,
            },
        ) if h1 == h2 => {
            record_def_alias(def_aliases, d1, d2);
            SgprOrigin::CbvIndexedHeapDesc {
                def_inst_idx: d1.min(d2),
                origin: h1,
            }
        }
        (
            SgprOrigin::LaneIndex {
                max_count: m1,
                window_base: w1,
            },
            SgprOrigin::LaneIndex {
                max_count: m2,
                window_base: w2,
            },
        ) if w1 == w2 => SgprOrigin::LaneIndex {
            max_count: m1.zip(m2).map(|(a, b)| a.max(b)),
            window_base: w1,
        },
        (SgprOrigin::ScaledLaneIndex(h1), SgprOrigin::ScaledLaneIndex(h2))
            if h1.shift == h2.shift && h1.stride == h2.stride && h1.window_base == h2.window_base =>
        {
            SgprOrigin::ScaledLaneIndex(LaneIndexedHeapSource {
                max_count: h1.max_count.max(h2.max_count),
                ..h1
            })
        }
        (SgprOrigin::LaneIndexedHeapPtr(h1), SgprOrigin::LaneIndexedHeapPtr(h2))
            if h1.shift == h2.shift && h1.stride == h2.stride && h1.window_base == h2.window_base =>
        {
            SgprOrigin::LaneIndexedHeapPtr(LaneIndexedHeapSource {
                max_count: h1.max_count.max(h2.max_count),
                ..h1
            })
        }
        (
            SgprOrigin::LaneIndexedHeapDesc {
                def_inst_idx: d1,
                origin: h1,
            },
            SgprOrigin::LaneIndexedHeapDesc {
                def_inst_idx: d2,
                origin: h2,
            },
        ) if h1.shift == h2.shift && h1.stride == h2.stride && h1.window_base == h2.window_base => {
            record_def_alias(def_aliases, d1, d2);
            SgprOrigin::LaneIndexedHeapDesc {
                def_inst_idx: d1.min(d2),
                origin: LaneIndexedHeapSource {
                    max_count: h1.max_count.max(h2.max_count),
                    ..h1
                },
            }
        }
        (
            SgprOrigin::VbDesc {
                def_inst_idx: d1,
                vb_slot: v1,
            },
            SgprOrigin::VbDesc {
                def_inst_idx: d2,
                vb_slot: v2,
            },
        ) if v1 == v2 => {
            record_def_alias(def_aliases, d1, d2);
            SgprOrigin::VbDesc {
                def_inst_idx: d1.min(d2),
                vb_slot: v1,
            }
        }
        (
            SgprOrigin::RawTableDesc {
                def_inst_idx: d1,
                table_sbase: b1,
                table_offset: o1,
                is_dynamic: dyn1,
            },
            SgprOrigin::RawTableDesc {
                def_inst_idx: d2,
                table_sbase: b2,
                table_offset: o2,
                is_dynamic: dyn2,
            },
        ) if b1 == b2 && o1 == o2 && dyn1 == dyn2 => {
            record_def_alias(def_aliases, d1, d2);
            SgprOrigin::RawTableDesc {
                def_inst_idx: d1.min(d2),
                table_sbase: b1,
                table_offset: o1,
                is_dynamic: dyn1,
            }
        }
        (
            SgprOrigin::PatchedDescWord {
                def_inst_idx: d1,
                base: b1,
            },
            other,
        )
        | (
            other,
            SgprOrigin::PatchedDescWord {
                def_inst_idx: d1,
                base: b1,
            },
        ) if patched_desc_word_of(other).is_some_and(|(_, b2)| b1 == b2) => {
            if let Some((d2, _)) = patched_desc_word_of(other) {
                record_def_alias(def_aliases, d1, d2);
                SgprOrigin::PatchedDescWord {
                    def_inst_idx: d1.min(d2),
                    base: b1,
                }
            } else {
                SgprOrigin::Unknown
            }
        }
        (
            SgprOrigin::ConstImmediate { value: v1, .. },
            SgprOrigin::ConstImmediate { value: v2, .. },
        ) => SgprOrigin::ConstImmediate {
            def_inst_idx: inst_idx,
            value: if v1 == v2 { v1 } else { None },
        },
        (known, SgprOrigin::Unknown | SgprOrigin::ConstImmediate { .. })
        | (SgprOrigin::Unknown | SgprOrigin::ConstImmediate { .. }, known)
            if is_known_descriptor_or_table(known) =>
        {
            known
        }
        _ => merge_divergent_desc(a, b, divergent_def_aliases),
    }
}

/// Returns `true` for low-bit pointer alignment masks `& ~((1 << k) - 1)` for `k in 0..=6`
/// (e.g., `0xFFFFFFFF`, `0xFFFFFFFC`, `0xFFFFFFF8`, `0xFFFFFFF0`, `0xFFFFFFE0`, `0xFFFFFFC0`).
fn is_pointer_align_mask(mask: u32) -> bool {
    let cleared = !mask;
    cleared <= 63 && cleared.wrapping_add(1).is_power_of_two()
}

fn apply_const_offset(origin: SgprOrigin, delta: i32) -> SgprOrigin {
    if delta.unsigned_abs() > 0x0100_0000 {
        return SgprOrigin::Unknown;
    }
    match origin {
        SgprOrigin::UserTable {
            user_sgpr,
            byte_offset,
        } => SgprOrigin::UserTable {
            user_sgpr,
            byte_offset: byte_offset.saturating_add(delta),
        },
        SgprOrigin::VbTablePtr { byte_offset } => SgprOrigin::VbTablePtr {
            byte_offset: byte_offset.saturating_add(delta),
        },
        SgprOrigin::TableDesc {
            def_inst_idx,
            user_sgpr,
            table_byte_offset,
            addr_offset,
            cbv_dword,
        } => SgprOrigin::TableDesc {
            def_inst_idx,
            user_sgpr,
            table_byte_offset,
            addr_offset: addr_offset.saturating_add(delta),
            cbv_dword: if delta == 0 { cbv_dword } else { None },
        },
        SgprOrigin::BoundedByteOffset {
            idx_sgpr,
            base_byte_offset,
            max_elems,
        } if delta >= 0 && delta % 4 == 0 => {
            if let Some(next_off) = base_byte_offset.checked_add(delta as u32) {
                SgprOrigin::BoundedByteOffset {
                    idx_sgpr,
                    base_byte_offset: next_off,
                    max_elems,
                }
            } else {
                SgprOrigin::Unknown
            }
        }
        SgprOrigin::MaskedUserSgpr { .. } if delta == 0 => origin,
        SgprOrigin::ScaledUserSgpr { .. } if delta == 0 => origin,
        SgprOrigin::DynamicHeapPtr(_) if delta == 0 => origin,
        SgprOrigin::CbvDword { .. } if delta == 0 => origin,
        SgprOrigin::ScaledCbvDword(_) if delta == 0 => origin,
        SgprOrigin::CbvIndexedHeapPtr(_) if delta == 0 => origin,
        SgprOrigin::LaneIndex {
            max_count,
            window_base,
        } => {
            if delta == 0 {
                origin
            } else if delta > 0 && (delta as u32) < MAX_LANE_INDEXED_WINDOW {
                SgprOrigin::LaneIndex {
                    max_count: max_count
                        .map(|m| m.saturating_add(delta as u32).min(MAX_LANE_INDEXED_WINDOW)),
                    window_base,
                }
            } else {
                SgprOrigin::Unknown
            }
        }
        SgprOrigin::ScaledLaneIndex(_) if delta == 0 => origin,
        SgprOrigin::LaneIndexedHeapPtr(_) if delta == 0 => origin,
        // Adding a constant byte offset to a loaded DynamicHeapDesc / CbvIndexedHeapDesc /
        // LaneIndexedHeapDesc V# base address (or 2-level CBV VA) still references the exact same
        // heap binding.
        SgprOrigin::DynamicHeapDesc { .. }
        | SgprOrigin::CbvIndexedHeapDesc { .. }
        | SgprOrigin::LaneIndexedHeapDesc { .. }
        | SgprOrigin::DivergentDesc { .. } => origin,
        SgprOrigin::VbDesc { .. } if delta == 0 => origin,
        SgprOrigin::RawTableDesc { .. } if delta == 0 => origin,
        SgprOrigin::PatchedDescWord {
            base: PatchedDescBase::RootDescriptor { .. },
            ..
        } => origin,
        SgprOrigin::PatchedDescWord { .. } if delta == 0 => origin,
        _ => SgprOrigin::Unknown,
    }
}

fn apply_or_const(origin: SgprOrigin, imm: u32, inst_idx: usize) -> SgprOrigin {
    if imm == 0 {
        return origin;
    }
    if imm == u32::MAX {
        return SgprOrigin::ConstImmediate {
            def_inst_idx: inst_idx,
            value: Some(u32::MAX),
        };
    }
    match origin {
        SgprOrigin::ConstImmediate { value, .. } => SgprOrigin::ConstImmediate {
            def_inst_idx: inst_idx,
            value: value.map(|v| v | imm),
        },
        // LLVM `or disjoint` optimization on aligned descriptor-table pointers:
        // `(table_base + off) | imm == table_base + (off + imm)` when `off & imm == 0`.
        SgprOrigin::UserTable {
            user_sgpr,
            byte_offset,
        } if imm < 0x0010_0000 && byte_offset >= 0 && ((byte_offset as u32) & imm) == 0 => {
            SgprOrigin::UserTable {
                user_sgpr,
                byte_offset: byte_offset.saturating_add(imm as i32),
            }
        }
        // GFX10.3 synthesized root V# word-1 attribute/stride patching (e.g. `s_or_b32 w1, w1, stride<<16`).
        SgprOrigin::UserTable { user_sgpr, .. }
        | SgprOrigin::MaskedUserSgpr { user_sgpr, .. }
        | SgprOrigin::CbvDword {
            cbv: CbvRefSource::RootConstants { user_sgpr },
            byte_offset: 0,
            bit_offset: 0,
            ..
        } => SgprOrigin::PatchedDescWord {
            def_inst_idx: inst_idx,
            base: PatchedDescBase::RootDescriptor { user_sgpr },
        },
        SgprOrigin::VbTablePtr { byte_offset }
            if imm < 0x0010_0000 && byte_offset >= 0 && ((byte_offset as u32) & imm) == 0 =>
        {
            SgprOrigin::VbTablePtr {
                byte_offset: byte_offset.saturating_add(imm as i32),
            }
        }
        SgprOrigin::TableDesc {
            def_inst_idx,
            user_sgpr,
            table_byte_offset,
            addr_offset,
            ..
        } if imm < 0x0010_0000 && addr_offset >= 0 && ((addr_offset as u32) & imm) == 0 => {
            SgprOrigin::TableDesc {
                def_inst_idx,
                user_sgpr,
                table_byte_offset,
                addr_offset: addr_offset.saturating_add(imm as i32),
                cbv_dword: None,
            }
        }
        SgprOrigin::DynamicHeapDesc { .. }
        | SgprOrigin::CbvIndexedHeapDesc { .. }
        | SgprOrigin::LaneIndexedHeapDesc { .. }
            if imm < 0x0010_0000 =>
        {
            origin
        }
        SgprOrigin::DivergentDesc { .. } => origin,
        // GFX10.3 V#/T# in-place descriptor word patching (e.g. OOB_SELECT, format/type/mip/DCC/stride).
        other => {
            if let Some((def_inst_idx, base)) = patched_desc_word_of(other) {
                SgprOrigin::PatchedDescWord { def_inst_idx, base }
            } else {
                SgprOrigin::Unknown
            }
        }
    }
}

fn apply_and_const(origin: SgprOrigin, mask: u32, inst_idx: usize) -> SgprOrigin {
    if mask == u32::MAX {
        return origin;
    }
    if mask == 0 {
        return SgprOrigin::ConstImmediate {
            def_inst_idx: inst_idx,
            value: Some(0),
        };
    }
    match origin {
        SgprOrigin::ConstImmediate { value, .. } => SgprOrigin::ConstImmediate {
            def_inst_idx: inst_idx,
            value: value.map(|v| v & mask),
        },
        SgprOrigin::UserTable {
            user_sgpr,
            byte_offset,
        } if is_pointer_align_mask(mask) => SgprOrigin::UserTable {
            user_sgpr,
            byte_offset: if byte_offset >= 0 {
                ((byte_offset as u32) & mask) as i32
            } else {
                byte_offset
            },
        },
        SgprOrigin::UserTable {
            user_sgpr,
            byte_offset: 0,
        } if mask != 0 && mask.wrapping_add(1).is_power_of_two() && mask >= 0x00FF_FFFF => {
            SgprOrigin::MaskedUserSgpr { user_sgpr, mask }
        }
        SgprOrigin::UserTable {
            user_sgpr,
            byte_offset: 0,
        } => SgprOrigin::CbvDword {
            cbv: CbvRefSource::RootConstants { user_sgpr },
            byte_offset: 0,
            bit_offset: 0,
            mask,
        },
        SgprOrigin::MaskedUserSgpr {
            user_sgpr,
            mask: prev_mask,
        } => {
            let combined = prev_mask & mask;
            if combined == 0 {
                SgprOrigin::ConstImmediate {
                    def_inst_idx: inst_idx,
                    value: Some(0),
                }
            } else if combined.wrapping_add(1).is_power_of_two() && combined >= 0x00FF_FFFF {
                SgprOrigin::MaskedUserSgpr {
                    user_sgpr,
                    mask: combined,
                }
            } else {
                SgprOrigin::CbvDword {
                    cbv: CbvRefSource::RootConstants { user_sgpr },
                    byte_offset: 0,
                    bit_offset: 0,
                    mask: combined,
                }
            }
        }
        SgprOrigin::CbvDword {
            cbv,
            byte_offset,
            bit_offset,
            mask: prev_mask,
        } => {
            let combined = prev_mask & mask;
            if combined == 0 {
                SgprOrigin::ConstImmediate {
                    def_inst_idx: inst_idx,
                    value: Some(0),
                }
            } else {
                SgprOrigin::CbvDword {
                    cbv,
                    byte_offset,
                    bit_offset,
                    mask: combined,
                }
            }
        }
        SgprOrigin::ScaledCbvDword(mut h) => {
            if is_pointer_align_mask(mask) && (h.stride & !mask) == 0 {
                SgprOrigin::ScaledCbvDword(h)
            } else if h.shift < 32 && (mask & ((1u32 << h.shift).wrapping_sub(1))) == 0 {
                let combined = h.mask & (mask >> h.shift);
                if combined == 0 {
                    SgprOrigin::ConstImmediate {
                        def_inst_idx: inst_idx,
                        value: Some(0),
                    }
                } else {
                    h.mask = combined;
                    SgprOrigin::ScaledCbvDword(h)
                }
            } else {
                SgprOrigin::Unknown
            }
        }
        SgprOrigin::VbTablePtr { byte_offset } if is_pointer_align_mask(mask) => {
            SgprOrigin::VbTablePtr {
                byte_offset: if byte_offset >= 0 {
                    ((byte_offset as u32) & mask) as i32
                } else {
                    byte_offset
                },
            }
        }
        SgprOrigin::DynamicHeapPtr(origin) if is_pointer_align_mask(mask) => {
            SgprOrigin::DynamicHeapPtr(origin)
        }
        SgprOrigin::CbvIndexedHeapPtr(origin) if is_pointer_align_mask(mask) => {
            SgprOrigin::CbvIndexedHeapPtr(origin)
        }
        SgprOrigin::LaneIndex {
            max_count,
            window_base,
        } => {
            let bound = lane_bound_from_upper_inclusive(mask);
            match window_base {
                None => SgprOrigin::LaneIndex {
                    max_count: Some(tighten_lane_max_count(max_count, bound)),
                    window_base: None,
                },
                Some(wb) if mask >= 0x00FF_FFFF => SgprOrigin::LaneIndex {
                    max_count,
                    window_base: Some(wb),
                },
                Some(_) => SgprOrigin::LaneIndex {
                    max_count: Some(bound),
                    window_base: None,
                },
            }
        }
        SgprOrigin::ScaledLaneIndex(mut h) => {
            if is_pointer_align_mask(mask) && (h.stride & !mask) == 0 {
                SgprOrigin::ScaledLaneIndex(h)
            } else if h.shift < 32 && (mask & ((1u32 << h.shift).wrapping_sub(1))) == 0 {
                let unshifted = mask >> h.shift;
                if unshifted == 0 {
                    SgprOrigin::ConstImmediate {
                        def_inst_idx: inst_idx,
                        value: Some(0),
                    }
                } else {
                    let bound = lane_bound_from_upper_inclusive(unshifted);
                    if h.window_base.is_none() {
                        h.max_count = h.max_count.min(bound).clamp(1, MAX_LANE_INDEXED_WINDOW);
                        SgprOrigin::ScaledLaneIndex(h)
                    } else if unshifted >= 0x00FF_FFFF {
                        SgprOrigin::ScaledLaneIndex(h)
                    } else {
                        h.window_base = None;
                        h.max_count = bound;
                        SgprOrigin::ScaledLaneIndex(h)
                    }
                }
            } else {
                SgprOrigin::Unknown
            }
        }
        SgprOrigin::LaneIndexedHeapPtr(origin) if is_pointer_align_mask(mask) => {
            SgprOrigin::LaneIndexedHeapPtr(origin)
        }
        SgprOrigin::DynamicHeapDesc { .. }
        | SgprOrigin::CbvIndexedHeapDesc { .. }
        | SgprOrigin::LaneIndexedHeapDesc { .. }
            if is_pointer_align_mask(mask) =>
        {
            origin
        }
        SgprOrigin::DivergentDesc { .. } => origin,
        SgprOrigin::ScaledUserSgpr {
            user_sgpr,
            stride,
            shift,
        } if is_pointer_align_mask(mask) && (stride & !mask) == 0 => SgprOrigin::ScaledUserSgpr {
            user_sgpr,
            stride,
            shift,
        },
        SgprOrigin::TableDesc {
            def_inst_idx,
            user_sgpr,
            table_byte_offset,
            addr_offset,
            cbv_dword,
        } if is_pointer_align_mask(mask) => SgprOrigin::TableDesc {
            def_inst_idx,
            user_sgpr,
            table_byte_offset,
            addr_offset: if addr_offset >= 0 {
                ((addr_offset as u32) & mask) as i32
            } else {
                addr_offset
            },
            cbv_dword,
        },
        // GFX10.3 structured-buffer V# word-1 stride clear (`0xc000ffff`) and word-3 OOB_SELECT
        // clear (`0xcfffffff`), preserving descriptor provenance strictly for V#/T# recovery.
        other if matches!(mask, 0xC000_FFFF | 0xCFFF_FFFF) => {
            if let Some((def_inst_idx, base)) = patched_desc_word_of(other) {
                SgprOrigin::PatchedDescWord { def_inst_idx, base }
            } else {
                SgprOrigin::Unknown
            }
        }
        SgprOrigin::TableDesc {
            cbv_dword: Some((cbv, byte_offset)),
            addr_offset: 0,
            ..
        } => SgprOrigin::CbvDword {
            cbv,
            byte_offset,
            bit_offset: 0,
            mask,
        },
        // Non-CBV-dword descriptor words (loaded heap V#/T#/S#, VbDesc, already-patched words,
        // or non-CBV-dword TableDesc) masked in place retain `PatchedDescWord` for V#/T# recovery.
        other => {
            if let Some((def_inst_idx, base)) = patched_desc_word_of(other) {
                SgprOrigin::PatchedDescWord { def_inst_idx, base }
            } else {
                SgprOrigin::Unknown
            }
        }
    }
}

fn apply_lshr_const(origin: SgprOrigin, shr: u32, inst_idx: usize) -> SgprOrigin {
    if shr >= 32 {
        return SgprOrigin::Unknown;
    }
    if shr == 0 {
        return origin;
    }
    match origin {
        SgprOrigin::CbvDword {
            cbv,
            byte_offset,
            bit_offset,
            mask,
        } => {
            let new_mask = mask >> shr;
            if new_mask == 0 {
                SgprOrigin::ConstImmediate {
                    def_inst_idx: inst_idx,
                    value: Some(0),
                }
            } else if let Some(new_bit) = bit_offset.checked_add(shr)
                && new_bit < 32
            {
                SgprOrigin::CbvDword {
                    cbv,
                    byte_offset,
                    bit_offset: new_bit,
                    mask: new_mask,
                }
            } else {
                SgprOrigin::Unknown
            }
        }
        SgprOrigin::TableDesc {
            cbv_dword: Some((cbv, byte_offset)),
            addr_offset: 0,
            ..
        } => SgprOrigin::CbvDword {
            cbv,
            byte_offset,
            bit_offset: shr,
            mask: u32::MAX >> shr,
        },
        SgprOrigin::UserTable {
            user_sgpr,
            byte_offset: 0,
        } => SgprOrigin::CbvDword {
            cbv: CbvRefSource::RootConstants { user_sgpr },
            byte_offset: 0,
            bit_offset: shr,
            mask: u32::MAX >> shr,
        },
        SgprOrigin::MaskedUserSgpr { user_sgpr, mask } => {
            let new_mask = mask >> shr;
            if new_mask == 0 {
                SgprOrigin::ConstImmediate {
                    def_inst_idx: inst_idx,
                    value: Some(0),
                }
            } else {
                SgprOrigin::CbvDword {
                    cbv: CbvRefSource::RootConstants { user_sgpr },
                    byte_offset: 0,
                    bit_offset: shr,
                    mask: new_mask,
                }
            }
        }
        SgprOrigin::ScaledCbvDword(h) if h.shift < 32 => {
            let eff_mask = h.mask & (u32::MAX >> h.shift);
            if eff_mask == 0 {
                SgprOrigin::ConstImmediate {
                    def_inst_idx: inst_idx,
                    value: Some(0),
                }
            } else if shr <= h.shift {
                let new_shift = h.shift - shr;
                SgprOrigin::ScaledCbvDword(CbvIndexedHeapSource {
                    shift: new_shift,
                    mask: eff_mask,
                    stride: 1u32 << new_shift,
                    ..h
                })
            } else {
                let extra = shr - h.shift;
                let new_mask = eff_mask >> extra;
                if new_mask == 0 {
                    SgprOrigin::ConstImmediate {
                        def_inst_idx: inst_idx,
                        value: Some(0),
                    }
                } else if let Some(new_bit) = h.bit_offset.checked_add(extra)
                    && new_bit < 32
                {
                    SgprOrigin::CbvDword {
                        cbv: h.cbv,
                        byte_offset: h.byte_offset,
                        bit_offset: new_bit,
                        mask: new_mask,
                    }
                } else {
                    SgprOrigin::Unknown
                }
            }
        }
        SgprOrigin::LaneIndex {
            max_count,
            window_base: None,
        } => {
            let shifted_prev = max_count.map(|m| (((m - 1) >> shr) + 1).clamp(1, MAX_LANE_INDEXED_WINDOW));
            let shifted_type = if shr >= 24 {
                Some((1u32 << (32 - shr)).min(MAX_LANE_INDEXED_WINDOW))
            } else {
                None
            };
            let next_max = match (shifted_prev, shifted_type) {
                (Some(a), Some(b)) => Some(a.min(b)),
                (Some(a), None) | (None, Some(a)) => Some(a),
                (None, None) => None,
            };
            SgprOrigin::LaneIndex {
                max_count: next_max,
                window_base: None,
            }
        }
        SgprOrigin::ScaledLaneIndex(h) if h.shift < 32 && shr <= h.shift => {
            let new_shift = h.shift - shr;
            if new_shift == 0 && (h.stride == 0 || h.stride == (1u32 << h.shift)) {
                SgprOrigin::LaneIndex {
                    max_count: Some(h.max_count),
                    window_base: h.window_base,
                }
            } else {
                let new_stride = if h.stride != 0 {
                    h.stride >> shr
                } else {
                    1u32 << new_shift
                };
                SgprOrigin::ScaledLaneIndex(LaneIndexedHeapSource {
                    shift: new_shift,
                    stride: new_stride,
                    ..h
                })
            }
        }
        _ => SgprOrigin::Unknown,
    }
}

fn apply_bfe_u32_const(origin: SgprOrigin, param: u32, inst_idx: usize) -> SgprOrigin {
    let off = param & 31;
    let width = (param >> 16) & 0x7F;
    if width == 0 {
        return SgprOrigin::ConstImmediate {
            def_inst_idx: inst_idx,
            value: Some(0),
        };
    }
    if let SgprOrigin::LaneIndex {
        max_count,
        window_base,
    } = origin
    {
        let bfe_bound = if width < 8 {
            1u32 << width
        } else {
            MAX_LANE_INDEXED_WINDOW
        };
        let next_max = if off == 0 && window_base.is_none() {
            tighten_lane_max_count(max_count, bfe_bound)
        } else {
            bfe_bound
        };
        return SgprOrigin::LaneIndex {
            max_count: Some(next_max),
            window_base: None,
        };
    }
    let bfe_mask = if width >= 32 {
        u32::MAX
    } else {
        (1u32 << width) - 1
    };
    if matches!(
        origin,
        SgprOrigin::ScaledCbvDword(_) | SgprOrigin::ScaledLaneIndex(_)
    ) {
        let shifted = apply_lshr_const(origin, off, inst_idx);
        return apply_and_const(shifted, bfe_mask, inst_idx);
    }
    let (cbv, byte_offset, prev_bit, prev_mask) = match origin {
        SgprOrigin::CbvDword {
            cbv,
            byte_offset,
            bit_offset,
            mask,
        } => (cbv, byte_offset, bit_offset, mask),
        SgprOrigin::TableDesc {
            cbv_dword: Some((cbv, byte_offset)),
            addr_offset: 0,
            ..
        } => (cbv, byte_offset, 0, u32::MAX),
        SgprOrigin::UserTable {
            user_sgpr,
            byte_offset: 0,
        } => (CbvRefSource::RootConstants { user_sgpr }, 0, 0, u32::MAX),
        SgprOrigin::MaskedUserSgpr { user_sgpr, mask } => {
            (CbvRefSource::RootConstants { user_sgpr }, 0, 0, mask)
        }
        _ => return SgprOrigin::Unknown,
    };
    let Some(new_bit) = prev_bit.checked_add(off) else {
        return SgprOrigin::Unknown;
    };
    if new_bit >= 32 {
        return SgprOrigin::Unknown;
    }
    let new_mask = (prev_mask >> off) & bfe_mask;
    if new_mask == 0 {
        SgprOrigin::ConstImmediate {
            def_inst_idx: inst_idx,
            value: Some(0),
        }
    } else {
        SgprOrigin::CbvDword {
            cbv,
            byte_offset,
            bit_offset: new_bit,
            mask: new_mask,
        }
    }
}

fn scaled_user_sgpr_stride(origin: SgprOrigin) -> Option<(u32, u32)> {
    match origin {
        SgprOrigin::UserTable {
            user_sgpr,
            byte_offset: 0,
        } => Some((user_sgpr, 1)),
        SgprOrigin::ScaledUserSgpr {
            user_sgpr, stride, ..
        } => Some((user_sgpr, stride)),
        _ => None,
    }
}

fn make_scaled_user_sgpr(user_sgpr: u32, stride: u32) -> SgprOrigin {
    if stride == 0 {
        return SgprOrigin::Unknown;
    }
    SgprOrigin::ScaledUserSgpr {
        user_sgpr,
        stride,
        shift: if stride.is_power_of_two() {
            stride.trailing_zeros()
        } else {
            0
        },
    }
}

fn scale_user_sgpr_by_shift(origin: SgprOrigin, shift: u32) -> SgprOrigin {
    if shift >= 32 {
        return SgprOrigin::Unknown;
    }
    let mult = 1u32 << shift;
    match origin {
        SgprOrigin::UserTable {
            user_sgpr,
            byte_offset: 0,
        } => SgprOrigin::ScaledUserSgpr {
            user_sgpr,
            stride: mult,
            shift,
        },
        SgprOrigin::MaskedUserSgpr { user_sgpr, mask }
            if shift > 0 && (!mask).wrapping_shl(shift) == 0 =>
        {
            SgprOrigin::ScaledUserSgpr {
                user_sgpr,
                stride: mult,
                shift,
            }
        }
        SgprOrigin::MaskedUserSgpr { user_sgpr, mask } if mask != 0 => {
            SgprOrigin::ScaledCbvDword(CbvIndexedHeapSource {
                cbv: CbvRefSource::RootConstants { user_sgpr },
                byte_offset: 0,
                shift,
                bit_offset: 0,
                mask,
                stride: mult,
            })
        }
        SgprOrigin::ScaledUserSgpr {
            user_sgpr, stride, ..
        } => match stride.checked_mul(mult) {
            Some(new_stride) if new_stride > 0 => make_scaled_user_sgpr(user_sgpr, new_stride),
            _ => SgprOrigin::Unknown,
        },
        SgprOrigin::CbvDword {
            cbv,
            byte_offset,
            bit_offset,
            mask,
        } => SgprOrigin::ScaledCbvDword(CbvIndexedHeapSource {
            cbv,
            byte_offset,
            shift,
            bit_offset,
            mask,
            stride: mult,
        }),
        SgprOrigin::BoundedCbvDword {
            load_inst_idx,
            idx_sgpr,
            cbv,
            base_byte_offset,
            max_elems,
        } if shift > 0 => SgprOrigin::BoundedScaledCbvDword {
            load_inst_idx,
            idx_sgpr,
            cbv,
            base_byte_offset,
            max_elems,
            shift: shift as u8,
        },
        SgprOrigin::TableDesc {
            cbv_dword: Some((cbv, byte_offset)),
            addr_offset: 0,
            ..
        } => SgprOrigin::ScaledCbvDword(CbvIndexedHeapSource {
            cbv,
            byte_offset,
            shift,
            bit_offset: 0,
            mask: u32::MAX,
            stride: mult,
        }),
        SgprOrigin::ScaledCbvDword(h) => match h.shift.checked_add(shift) {
            Some(new_shift) if new_shift < 32 => SgprOrigin::ScaledCbvDword(CbvIndexedHeapSource {
                shift: new_shift,
                stride: 1u32 << new_shift,
                ..h
            }),
            _ => SgprOrigin::Unknown,
        },
        SgprOrigin::LaneIndex {
            max_count,
            window_base,
        } => {
            if shift == 0 {
                origin
            } else {
                SgprOrigin::ScaledLaneIndex(LaneIndexedHeapSource {
                    max_count: finalize_lane_max_count(max_count),
                    shift,
                    stride: mult,
                    window_base,
                })
            }
        }
        SgprOrigin::ScaledLaneIndex(h) => {
            if shift == 0 {
                SgprOrigin::ScaledLaneIndex(h)
            } else if h.stride == 0 || h.stride == (1u32 << h.shift) {
                match h.shift.checked_add(shift) {
                    Some(new_shift) if new_shift < 32 => {
                        SgprOrigin::ScaledLaneIndex(LaneIndexedHeapSource {
                            shift: new_shift,
                            stride: 1u32 << new_shift,
                            ..h
                        })
                    }
                    _ => SgprOrigin::Unknown,
                }
            } else {
                match h.stride.checked_mul(mult) {
                    Some(new_stride) if new_stride > 0 => {
                        SgprOrigin::ScaledLaneIndex(LaneIndexedHeapSource {
                            shift: 0,
                            stride: new_stride,
                            ..h
                        })
                    }
                    _ => SgprOrigin::Unknown,
                }
            }
        }
        _ => SgprOrigin::Unknown,
    }
}

fn scale_user_sgpr_by_mul(origin: SgprOrigin, factor: i32) -> SgprOrigin {
    if factor <= 0 {
        return SgprOrigin::Unknown;
    }
    let f = factor as u32;
    match origin {
        SgprOrigin::UserTable {
            user_sgpr,
            byte_offset: 0,
        } => make_scaled_user_sgpr(user_sgpr, f),
        SgprOrigin::ScaledUserSgpr {
            user_sgpr, stride, ..
        } => match stride.checked_mul(f) {
            Some(new_stride) if new_stride > 0 => make_scaled_user_sgpr(user_sgpr, new_stride),
            _ => SgprOrigin::Unknown,
        },
        SgprOrigin::MaskedUserSgpr { .. }
        | SgprOrigin::CbvDword { .. }
        | SgprOrigin::TableDesc {
            cbv_dword: Some(_),
            addr_offset: 0,
            ..
        }
        | SgprOrigin::ScaledCbvDword(_)
            if f.is_power_of_two() =>
        {
            scale_user_sgpr_by_shift(origin, f.trailing_zeros())
        }
        SgprOrigin::LaneIndex {
            max_count,
            window_base,
        } => {
            if f == 1 {
                origin
            } else if f.is_power_of_two() {
                scale_user_sgpr_by_shift(origin, f.trailing_zeros())
            } else {
                SgprOrigin::ScaledLaneIndex(LaneIndexedHeapSource {
                    max_count: finalize_lane_max_count(max_count),
                    shift: 0,
                    stride: f,
                    window_base,
                })
            }
        }
        SgprOrigin::ScaledLaneIndex(h) => {
            if f == 1 {
                SgprOrigin::ScaledLaneIndex(h)
            } else if f.is_power_of_two() && (h.stride == 0 || h.stride == (1u32 << h.shift)) {
                scale_user_sgpr_by_shift(origin, f.trailing_zeros())
            } else {
                let base_stride = if h.stride != 0 {
                    h.stride
                } else {
                    1u32 << h.shift
                };
                match base_stride.checked_mul(f) {
                    Some(new_stride) if new_stride > 0 => {
                        let new_shift = if new_stride.is_power_of_two() {
                            new_stride.trailing_zeros()
                        } else {
                            0
                        };
                        SgprOrigin::ScaledLaneIndex(LaneIndexedHeapSource {
                            shift: new_shift,
                            stride: new_stride,
                            ..h
                        })
                    }
                    _ => SgprOrigin::Unknown,
                }
            }
        }
        _ => SgprOrigin::Unknown,
    }
}

fn sop1_writes_pair(op: u8) -> bool {
    matches!(
        op,
        0x04 | 0x06
            | 0x08
            | 0x0A
            | 0x0C
            | 0x1C
            | 0x1E
            | 0x1F
            | 0x21
            | 0x24..=0x2B
            | 0x2D
            | 0x2F
            | 0x31
            | 0x37..=0x3B
    )
}

fn sop1_reads_pair(op: u8) -> bool {
    matches!(
        op,
        0x04 | 0x06
            | 0x08
            | 0x0A
            | 0x0C
            | 0x0E
            | 0x10
            | 0x12
            | 0x14
            | 0x16
            | 0x18
            | 0x20
            | 0x22
            | 0x24..=0x2B
            | 0x2D
            | 0x2F
            | 0x31
            | 0x37..=0x3A
    )
}

fn taint_def_and_aliases(
    tainted_defs: &mut BTreeSet<usize>,
    def_aliases: &BTreeMap<usize, BTreeSet<usize>>,
    divergent_def_aliases: Option<&BTreeMap<usize, BTreeSet<usize>>>,
    start_def: usize,
) {
    let mut visited: BTreeSet<usize> = BTreeSet::new();
    let mut stack: Vec<usize> = vec![start_def];
    while let Some(cur) = stack.pop() {
        if visited.len() >= 128 || !visited.insert(cur) {
            continue;
        }
        tainted_defs.insert(cur);
        if let Some(aliases) = def_aliases.get(&cur) {
            for &alias in aliases {
                if !visited.contains(&alias) {
                    stack.push(alias);
                }
            }
        }
        if let Some(div_aliases) = divergent_def_aliases.and_then(|m| m.get(&cur)) {
            for &alias in div_aliases {
                if !visited.contains(&alias) {
                    stack.push(alias);
                }
            }
        }
    }
}

/// Returns `true` when a `v_cmp(x)_eq_{i32,i64,u32,u64}` compares a `v_readfirstlane_b32`-extracted
/// descriptor SGPR against the VGPR holding the exact same loaded descriptor origin (the standard
/// RDNA2 non-uniform descriptor waterfall loop predicate: `v_readfirstlane_b32 s_d, v_d;
/// v_cmp_eq_u64 mask, s_d, v_d; s_and_saveexec; image_sample/buffer_load ... s_d`).
/// Such lane-equality predicates do not consume loaded CBV data and must not taint descriptor defs.
fn is_waterfall_desc_cmp(state: &OriginState, vopc_op: u16, src0: u16, src1: u16) -> bool {
    if !matches!(vopc_op, 0x82 | 0x92 | 0xA2 | 0xB2 | 0xC2 | 0xD2 | 0xE2 | 0xF2) {
        return false;
    }
    let (s_reg, v_reg) = if src0 <= u16::from(MAX_TRACKED_SGPR) && (256..=511).contains(&src1) {
        (src0 as u8, (src1 - 256) as u8)
    } else if src1 <= u16::from(MAX_TRACKED_SGPR) && (256..=511).contains(&src0) {
        (src1 as u8, (src0 - 256) as u8)
    } else {
        return false;
    };
    let s_defs = loaded_desc_defs(state.sgpr_origin(s_reg));
    if s_defs.is_none() {
        return false;
    }
    let v_orig = state
        .lane_origins
        .get(&(v_reg, 0))
        .copied()
        .unwrap_or_else(|| state.vgpr_origin(v_reg));
    loaded_desc_defs(v_orig) == s_defs
}

fn taint_sgpr_if_loaded(
    collector: &mut Option<&mut AnalysisCollector>,
    origins: &[SgprOrigin; TRACKED_SGPR_COUNT],
    src: u16,
) {
    if let Some(col) = collector.as_deref_mut()
        && src <= u16::from(MAX_TRACKED_SGPR)
    {
        match origin_at(origins, usize::from(src)) {
            SgprOrigin::TableDesc { def_inst_idx, .. }
            | SgprOrigin::DynamicHeapDesc { def_inst_idx, .. }
            | SgprOrigin::CbvIndexedHeapDesc { def_inst_idx, .. }
            | SgprOrigin::LaneIndexedHeapDesc { def_inst_idx, .. }
            | SgprOrigin::BoundedCbvIndexedHeapDesc { def_inst_idx, .. }
            | SgprOrigin::RawTableDesc { def_inst_idx, .. }
            | SgprOrigin::VbDesc { def_inst_idx, .. }
            | SgprOrigin::PatchedDescWord { def_inst_idx, .. } => {
                col.tainted_defs.insert(def_inst_idx);
            }
            SgprOrigin::TableDescChoice { def_insts, .. } => {
                taint_def_and_aliases(&mut col.tainted_defs, &col.def_aliases, None, def_insts[0]);
                taint_def_and_aliases(&mut col.tainted_defs, &col.def_aliases, None, def_insts[1]);
            }
            SgprOrigin::DivergentDesc { def_inst_idx } => {
                taint_def_and_aliases(
                    &mut col.tainted_defs,
                    &col.def_aliases,
                    Some(&col.divergent_def_aliases),
                    def_inst_idx,
                );
            }
            _ => {}
        }
    }
}

fn clear_vgpr_origins(state: &mut OriginState, vdst: u8) {
    state.set_vgpr_origin(vdst, SgprOrigin::Unknown);
    if !state.lane_origins.is_empty() {
        state.lane_origins.retain(|&(v, _), _| v != vdst);
    }
}

fn copy_vgpr_origins(state: &mut OriginState, vdst: u8, vsrc: u8) {
    if vdst == vsrc {
        return;
    }
    let src_origin = state.vgpr_origin(vsrc);
    state.set_vgpr_origin(vdst, src_origin);
    if !state.lane_origins.is_empty() {
        state.lane_origins.retain(|&(v, _), _| v != vdst);
        let copied: Vec<(u8, SgprOrigin)> = state
            .lane_origins
            .range((vsrc, 0)..=(vsrc, u8::MAX))
            .map(|(&(_, lane), &orig)| (lane, orig))
            .collect();
        for (lane, orig) in copied {
            state.lane_origins.insert((vdst, lane), orig);
        }
    }
}

fn swap_vgpr_origins(state: &mut OriginState, va: u8, vb: u8) {
    if va == vb {
        return;
    }
    let orig_a = state.vgpr_origin(va);
    let orig_b = state.vgpr_origin(vb);
    state.set_vgpr_origin(va, orig_b);
    state.set_vgpr_origin(vb, orig_a);
    if !state.lane_origins.is_empty() {
        let a_lanes: Vec<(u8, SgprOrigin)> = state
            .lane_origins
            .range((va, 0)..=(va, u8::MAX))
            .map(|(&(_, lane), &orig)| (lane, orig))
            .collect();
        let b_lanes: Vec<(u8, SgprOrigin)> = state
            .lane_origins
            .range((vb, 0)..=(vb, u8::MAX))
            .map(|(&(_, lane), &orig)| (lane, orig))
            .collect();
        state.lane_origins.retain(|&(v, _), _| v != va && v != vb);
        for (lane, orig) in a_lanes {
            state.lane_origins.insert((vb, lane), orig);
        }
        for (lane, orig) in b_lanes {
            state.lane_origins.insert((va, lane), orig);
        }
    }
}

fn is_synthesized_root_vsharp(
    origins: &[SgprOrigin; TRACKED_SGPR_COUNT],
    rsrc_sgpr: u8,
) -> bool {
    let idx = usize::from(rsrc_sgpr);
    let Some(w2) = idx.checked_add(2).and_then(|i| origins.get(i)) else {
        return false;
    };
    let Some(w3) = idx.checked_add(3).and_then(|i| origins.get(i)) else {
        return false;
    };
    matches!(w2, SgprOrigin::ConstImmediate { .. })
        || matches!(w3, SgprOrigin::ConstImmediate { .. })
}

/// Returns `true` when word 1 of a synthesized root-descriptor V# matches the high 32-bit word
/// of a 64-bit Root Descriptor VA (`user_sgpr + 1`, optionally masked/OR'd with stride/swizzle
/// bits) or a 32-bit constant high address word.
fn is_root_vsharp_hi_word(w1: SgprOrigin, lo_user_sgpr: u32) -> bool {
    let hi_user_sgpr = lo_user_sgpr.saturating_add(1);
    match w1 {
        SgprOrigin::UserTable { user_sgpr, .. }
        | SgprOrigin::MaskedUserSgpr { user_sgpr, .. }
        | SgprOrigin::CbvDword {
            cbv: CbvRefSource::RootConstants { user_sgpr },
            byte_offset: 0,
            bit_offset: 0,
            ..
        }
        | SgprOrigin::PatchedDescWord {
            base: PatchedDescBase::RootDescriptor { user_sgpr },
            ..
        } => user_sgpr == hi_user_sgpr,
        SgprOrigin::ConstImmediate { .. } => true,
        _ => false,
    }
}

fn recover_desc_origin_from_word_pair(
    origins: &[SgprOrigin; TRACKED_SGPR_COUNT],
    idx: usize,
    wi: usize,
    wj: usize,
) -> Option<SgprOrigin> {
    let byte_delta_i = (wi * 4) as u32;
    let byte_delta_diff = ((wj - wi) * 4) as u32;
    let (di, bi) = patched_desc_word_of(origin_at(origins, idx + wi))?;
    let (dj, bj) = patched_desc_word_of(origin_at(origins, idx + wj))?;
    if di != dj {
        return None;
    }
    match (bi, bj) {
        (
            PatchedDescBase::Table {
                user_sgpr: ui,
                table_byte_offset: oi,
            },
            PatchedDescBase::Table {
                user_sgpr: uj,
                table_byte_offset: oj,
            },
        ) if ui == uj
            && oi >= byte_delta_i
            && oj == oi.saturating_add(byte_delta_diff) =>
        {
            Some(SgprOrigin::TableDesc {
                def_inst_idx: di,
                user_sgpr: ui,
                table_byte_offset: oi - byte_delta_i,
                addr_offset: 0,
                cbv_dword: None,
            })
        }
        (PatchedDescBase::DynamicHeap(hi), PatchedDescBase::DynamicHeap(hj)) if hi == hj => {
            Some(SgprOrigin::DynamicHeapDesc {
                def_inst_idx: di,
                origin: hi,
            })
        }
        (PatchedDescBase::CbvIndexedHeap(hi), PatchedDescBase::CbvIndexedHeap(hj)) if hi == hj => {
            Some(SgprOrigin::CbvIndexedHeapDesc {
                def_inst_idx: di,
                origin: hi,
            })
        }
        (PatchedDescBase::LaneIndexedHeap(hi), PatchedDescBase::LaneIndexedHeap(hj))
            if hi == hj =>
        {
            Some(SgprOrigin::LaneIndexedHeapDesc {
                def_inst_idx: di,
                origin: hi,
            })
        }
        (PatchedDescBase::Vb { vb_slot: vi }, PatchedDescBase::Vb { vb_slot: vj }) if vi == vj => {
            Some(SgprOrigin::VbDesc {
                def_inst_idx: di,
                vb_slot: vi,
            })
        }
        _ => None,
    }
}

/// Resolve the 4-SGPR V# or S# descriptor origin at `s[rsrc_sgpr .. rsrc_sgpr+3]`.
///
/// Checks word 0 (`origins[rsrc_sgpr]`) first; when word 0 is `Unknown`/`Unwritten`/`PatchedDescWord`
/// (e.g. after dynamic base-address arithmetic or partial self-overwrite across a CFG merge), falls
/// back to synthesized root-descriptor verification or matching descriptor word pairs (including
/// GFX10.3 `PatchedDescWord` words) from the same defining instruction.
fn resolve_vsharp_origin(origins: &[SgprOrigin; TRACKED_SGPR_COUNT], rsrc_sgpr: u8) -> SgprOrigin {
    let idx = usize::from(rsrc_sgpr);
    let Some(&w0) = origins.get(idx) else {
        return SgprOrigin::Unknown;
    };
    if !matches!(
        w0,
        SgprOrigin::Unknown
            | SgprOrigin::ExeczScratch
            | SgprOrigin::Unwritten
            | SgprOrigin::PatchedDescWord { .. }
            | SgprOrigin::CbvDword { .. }
            | SgprOrigin::ScaledCbvDword(_)
            | SgprOrigin::LaneIndex { .. }
            | SgprOrigin::ScaledLaneIndex(_)
            | SgprOrigin::MaskedUserSgpr { .. }
            | SgprOrigin::ScaledUserSgpr { .. }
            | SgprOrigin::RightShiftedPtr { .. }
            | SgprOrigin::BoundedByteOffset { .. }
            | SgprOrigin::BoundedCbvDword { .. }
            | SgprOrigin::BoundedScaledCbvDword { .. }
    ) {
        return w0;
    }
    if idx.checked_add(3).is_some_and(|end| end < origins.len()) {
        if let SgprOrigin::PatchedDescWord {
            base: PatchedDescBase::RootDescriptor { user_sgpr },
            ..
        } = w0
            && is_synthesized_root_vsharp(origins, rsrc_sgpr)
            && is_root_vsharp_hi_word(origin_at(origins, idx + 1), user_sgpr)
        {
            return SgprOrigin::UserTable {
                user_sgpr,
                byte_offset: 0,
            };
        }
        for (wi, wj) in [(2usize, 3usize), (1, 3), (1, 2), (0, 1), (0, 2), (0, 3)] {
            if let Some(recovered) = recover_desc_origin_from_word_pair(origins, idx, wi, wj) {
                return recovered;
            }
        }
        for (wi, wj) in [(2usize, 3usize), (1, 3), (1, 2), (0, 1), (0, 2), (0, 3)] {
            if let (
                SgprOrigin::DivergentDesc { def_inst_idx: di },
                SgprOrigin::DivergentDesc { def_inst_idx: dj },
            ) = (origin_at(origins, idx + wi), origin_at(origins, idx + wj))
                && di == dj
            {
                return SgprOrigin::DivergentDesc { def_inst_idx: di };
            }
        }
    }
    w0
}

/// Resolve the 8-SGPR (or 4-SGPR when `r128 == true`) T# image descriptor origin at
/// `s[rsrc_sgpr .. rsrc_sgpr + word_count]`.
///
/// Checks word 0 first; if word 0 was overwritten/patched/clobbered, recovers from any matching
/// pair of intact or `PatchedDescWord` words within the T# from the same defining instruction.
fn resolve_tsharp_origin(
    origins: &[SgprOrigin; TRACKED_SGPR_COUNT],
    rsrc_sgpr: u8,
    r128: bool,
) -> SgprOrigin {
    let idx = usize::from(rsrc_sgpr);
    let Some(&w0) = origins.get(idx) else {
        return SgprOrigin::Unknown;
    };
    if !matches!(
        w0,
        SgprOrigin::Unknown
            | SgprOrigin::ExeczScratch
            | SgprOrigin::Unwritten
            | SgprOrigin::PatchedDescWord { .. }
            | SgprOrigin::CbvDword { .. }
            | SgprOrigin::ScaledCbvDword(_)
            | SgprOrigin::LaneIndex { .. }
            | SgprOrigin::ScaledLaneIndex(_)
            | SgprOrigin::MaskedUserSgpr { .. }
            | SgprOrigin::ScaledUserSgpr { .. }
            | SgprOrigin::RightShiftedPtr { .. }
            | SgprOrigin::BoundedByteOffset { .. }
            | SgprOrigin::BoundedCbvDword { .. }
            | SgprOrigin::BoundedScaledCbvDword { .. }
    ) {
        return w0;
    }
    let word_count = if r128 { 4usize } else { 8usize };
    if idx
        .checked_add(word_count - 1)
        .is_some_and(|end| end < origins.len())
    {
        for wi in 0..word_count {
            for wj in (wi + 1)..word_count {
                if let Some(recovered) = recover_desc_origin_from_word_pair(origins, idx, wi, wj) {
                    return recovered;
                }
            }
        }
        for wi in 0..word_count {
            for wj in (wi + 1)..word_count {
                if let (
                    SgprOrigin::DivergentDesc { def_inst_idx: di },
                    SgprOrigin::DivergentDesc { def_inst_idx: dj },
                ) = (origin_at(origins, idx + wi), origin_at(origins, idx + wj))
                    && di == dj
                {
                    return SgprOrigin::DivergentDesc { def_inst_idx: di };
                }
            }
        }
    }
    w0
}

/// Detect whether the decoded GFX10.3 instruction stream executes in Wave32 mode.
///
/// In Wave32, `v_cmp_*` and VOP3 carry-out `sdst` write a single 32-bit SGPR rather than a 64-bit
/// SGPR pair, so we must not clobber `sd + 1` (which often holds a live descriptor or table ptr).
fn detect_wave32_program(active: &[Rdna2Instruction]) -> bool {
    let mut has_wave32 = false;
    let mut has_wave64 = false;
    for inst in active {
        if inst.truncated {
            continue;
        }
        match &inst.detail {
            Rdna2Detail::Sop1 {
                op, sdst, ssrc0, ..
            } => {
                if matches!(*op, 0x09 | 0x2C | 0x3C..=0x47)
                    || (matches!(*op, 0x03 | 0x05) && (*sdst == 126 || *ssrc0 == 126))
                {
                    has_wave32 = true;
                } else if matches!(*op, 0x0A | 0x24..=0x2B | 0x2D | 0x37..=0x3A)
                    || (matches!(*op, 0x04 | 0x06) && (*sdst == 126 || *ssrc0 == 126))
                {
                    has_wave64 = true;
                }
            }
            Rdna2Detail::Sop2 {
                op,
                sdst,
                ssrc0,
                ssrc1,
                ..
            } => {
                if *sdst == 126 || *ssrc0 == 126 || *ssrc1 == 126 {
                    if matches!(
                        *op,
                        0x0A | 0x0E | 0x10 | 0x12 | 0x14 | 0x16 | 0x18 | 0x1A | 0x1C
                    ) {
                        has_wave32 = true;
                    } else if matches!(
                        *op,
                        0x0B | 0x0F | 0x11 | 0x13 | 0x15 | 0x17 | 0x19 | 0x1B | 0x1D
                    ) {
                        has_wave64 = true;
                    }
                }
            }
            Rdna2Detail::Vop3 { op, vdst, sdst, .. } => {
                if let Some(sd) = sdst {
                    let sd7 = *sd & 0x7F;
                    if sd7 <= 105 && sd7 % 2 == 1 {
                        has_wave32 = true;
                    }
                }
                if *op <= 0xFF && (*op & 0x10) == 0 {
                    let sd = *vdst & 0x7F;
                    if sd <= 105 && sd % 2 == 1 {
                        has_wave32 = true;
                    }
                }
            }
            _ => {}
        }
    }
    has_wave32 && !has_wave64
}

fn clear_pending_xor_if(state: &mut OriginState, reg: u8) {
    if let Some((r, _, _)) = state.pending_xor
        && r == reg
    {
        state.pending_xor = None;
    }
    if let Some((r, _, _)) = state.pending_xor_pair
        && (reg == r || reg == r.saturating_add(1))
    {
        state.pending_xor_pair = None;
    }
}

/// Returns `true` when `s_addc_u32` / `s_subb_u32` / `s_add_u32 ..., src_scc` writing `sdst`
/// from `origin` is provably carry/borrow propagation into the high 32-bit word of a 64-bit
/// pointer or descriptor VA (never a 1-byte mutation of a low 32-bit pointer word).
fn is_valid_carry_hi(sdst: u8, origin: SgprOrigin, last_carry_lo_reg: Option<u8>) -> bool {
    if !is_known_descriptor_or_table(origin) {
        return false;
    }
    if sdst > 0 && last_carry_lo_reg == Some(sdst - 1) {
        return true;
    }
    matches!(
        origin,
        SgprOrigin::TableDesc {
            table_byte_offset,
            ..
        } if table_byte_offset % 8 == 4
    ) || matches!(
        origin,
        SgprOrigin::DynamicHeapDesc { .. }
            | SgprOrigin::CbvIndexedHeapDesc { .. }
            | SgprOrigin::LaneIndexedHeapDesc { .. }
            | SgprOrigin::VbDesc { .. }
            | SgprOrigin::PatchedDescWord { .. }
            | SgprOrigin::DivergentDesc { .. }
    )
}

fn is_swappable_origin(o: SgprOrigin) -> bool {
    is_known_descriptor_or_table(o) || matches!(o, SgprOrigin::ConstImmediate { .. })
}

fn resolve_readfirstlane_origin(state: &OriginState, src0: u16) -> SgprOrigin {
    if (256..=511).contains(&src0) {
        let vsrc = (src0 - 256) as u8;
        if let Some(&lane0) = state.lane_origins.get(&(vsrc, 0)) {
            return normalize_read_origin(lane0);
        }
        let restored = normalize_read_origin(state.vgpr_origin(vsrc));
        if restored == SgprOrigin::Unknown {
            // Genuine per-lane VGPR value (not a uniform SGPR spill or constant):
            // candidate for SM 6.6 per-lane waterfall descriptor-heap indexing (#482 / #1394).
            SgprOrigin::LaneIndex {
                max_count: None,
                window_base: None,
            }
        } else {
            restored
        }
    } else if src0 <= u16::from(MAX_TRACKED_SGPR) {
        normalize_read_origin(state.sgpr_origin(src0 as u8))
    } else {
        SgprOrigin::Unknown
    }
}

fn resolve_valu_const_u32(src: u16, literal: Option<u32>, state: &OriginState) -> Option<u32> {
    if src <= u16::from(MAX_TRACKED_SGPR) {
        if let SgprOrigin::ConstImmediate { value: Some(v), .. } = state.sgpr_origin(src as u8) {
            Some(v)
        } else {
            None
        }
    } else if (256..=511).contains(&src) {
        if let SgprOrigin::ConstImmediate { value: Some(v), .. } =
            state.vgpr_origin((src - 256) as u8)
        {
            Some(v)
        } else {
            None
        }
    } else if let Some(v) = decode_inline_u32_src(src, literal) {
        Some(v as u32)
    } else {
        decode_inline_float_u32(src)
    }
}

fn resolve_valu_lane_operand(
    src: u16,
    literal: Option<u32>,
    inst_idx: usize,
    state: &OriginState,
) -> SgprOrigin {
    if src <= u16::from(MAX_TRACKED_SGPR) {
        normalize_read_origin(state.sgpr_origin(src as u8))
    } else if (256..=511).contains(&src) {
        let v = (src - 256) as u8;
        let o = normalize_read_origin(state.vgpr_origin(v));
        if o == SgprOrigin::Unknown {
            SgprOrigin::LaneIndex {
                max_count: None,
                window_base: None,
            }
        } else {
            o
        }
    } else if let Some(v) = decode_inline_u32_src(src, literal) {
        SgprOrigin::ConstImmediate {
            def_inst_idx: inst_idx,
            value: Some(v as u32),
        }
    } else if let Some(bits) = decode_inline_float_u32(src) {
        SgprOrigin::ConstImmediate {
            def_inst_idx: inst_idx,
            value: Some(bits),
        }
    } else {
        SgprOrigin::Unknown
    }
}

#[inline]
fn is_trackable_valu_origin(o: SgprOrigin) -> bool {
    !matches!(o, SgprOrigin::Unknown | SgprOrigin::Unwritten)
}

fn eval_valu_add_origins(
    o0: SgprOrigin,
    o1: SgprOrigin,
    c0: Option<u32>,
    c1: Option<u32>,
    inst_idx: usize,
) -> SgprOrigin {
    if let (Some(v0), Some(v1)) = (c0, c1) {
        SgprOrigin::ConstImmediate {
            def_inst_idx: inst_idx,
            value: Some(v0.wrapping_add(v1)),
        }
    } else if let Some(imm) = c0 {
        apply_const_offset(o1, imm as i32)
    } else if let Some(imm) = c1 {
        apply_const_offset(o0, imm as i32)
    } else {
        combine_add_origins(o0, o1).unwrap_or(SgprOrigin::Unknown)
    }
}

fn eval_valu_lane_origin_vop2_like(
    state: &OriginState,
    vop2_op: u8,
    src0: u16,
    src1: u16,
    literal: Option<u32>,
    inst_idx: usize,
) -> Option<SgprOrigin> {
    let o0 = resolve_valu_lane_operand(src0, literal, inst_idx, state);
    let o1 = resolve_valu_lane_operand(src1, literal, inst_idx, state);
    let c0 = resolve_valu_const_u32(src0, literal, state);
    let c1 = resolve_valu_const_u32(src1, literal, state);
    let res = match vop2_op {
        // v_cndmask_b32: preserve identical proven origin or 0-clamped lane origin
        0x00 | 0x01 => {
            if o0 == o1 {
                o0
            } else if is_const_zero(o0) && is_lane_origin(o1) {
                o1
            } else if is_const_zero(o1) && is_lane_origin(o0) {
                o0
            } else {
                SgprOrigin::Unknown
            }
        }
        // v_mul_i32_i24 / v_mul_u32_u24 (RDNA2 full-rate 24-bit integer multiply for heap strides)
        0x09 | 0x0B => {
            let mask24 = |v: u32| -> i32 {
                if vop2_op == 0x09 {
                    ((v << 8) as i32) >> 8
                } else {
                    (v & 0x00FF_FFFF) as i32
                }
            };
            if let (Some(v0), Some(v1)) = (c0, c1) {
                SgprOrigin::ConstImmediate {
                    def_inst_idx: inst_idx,
                    value: Some(mask24(v0).wrapping_mul(mask24(v1)) as u32),
                }
            } else if let Some(v0) = c0 {
                scale_user_sgpr_by_mul(o1, mask24(v0))
            } else if let Some(v1) = c1 {
                scale_user_sgpr_by_mul(o0, mask24(v1))
            } else {
                SgprOrigin::Unknown
            }
        }
        // v_min_i32 / v_min_u32
        0x11 | 0x13 => {
            let signed = vop2_op == 0x11;
            if let (Some(v0), Some(v1)) = (c0, c1) {
                let folded = if signed {
                    (v0 as i32).min(v1 as i32) as u32
                } else {
                    v0.min(v1)
                };
                SgprOrigin::ConstImmediate {
                    def_inst_idx: inst_idx,
                    value: Some(folded),
                }
            } else if src0 == src1 {
                o0
            } else if let Some(lim) = c0 {
                apply_min_const(o1, lim, signed)
            } else if let Some(lim) = c1 {
                apply_min_const(o0, lim, signed)
            } else {
                SgprOrigin::Unknown
            }
        }
        // v_max_i32 / v_max_u32
        0x12 | 0x14 => {
            let signed = vop2_op == 0x12;
            if let (Some(v0), Some(v1)) = (c0, c1) {
                let folded = if signed {
                    (v0 as i32).max(v1 as i32) as u32
                } else {
                    v0.max(v1)
                };
                SgprOrigin::ConstImmediate {
                    def_inst_idx: inst_idx,
                    value: Some(folded),
                }
            } else if src0 == src1 {
                o0
            } else if c0 == Some(0) && matches!(o1, SgprOrigin::LaneIndex { .. }) {
                o1
            } else if c1 == Some(0) && matches!(o0, SgprOrigin::LaneIndex { .. }) {
                o0
            } else {
                SgprOrigin::Unknown
            }
        }
        // v_lshrrev_b32: src1 >> (src0 & 31)
        0x16 => {
            if let (Some(sh), Some(v1)) = (c0, c1) {
                SgprOrigin::ConstImmediate {
                    def_inst_idx: inst_idx,
                    value: Some(v1.wrapping_shr(sh & 31)),
                }
            } else if let Some(sh) = c0 {
                apply_lshr_const(o1, sh & 31, inst_idx)
            } else {
                SgprOrigin::Unknown
            }
        }
        // v_ashrrev_i32: (src1 as i32) >> (src0 & 31)
        0x18 => {
            if let (Some(sh), Some(v1)) = (c0, c1) {
                SgprOrigin::ConstImmediate {
                    def_inst_idx: inst_idx,
                    value: Some(((v1 as i32).wrapping_shr(sh & 31)) as u32),
                }
            } else {
                SgprOrigin::Unknown
            }
        }
        // v_lshlrev_b32: src1 << (src0 & 31)
        0x1A => {
            if let (Some(sh), Some(v1)) = (c0, c1) {
                SgprOrigin::ConstImmediate {
                    def_inst_idx: inst_idx,
                    value: Some(v1.wrapping_shl(sh & 31)),
                }
            } else if let Some(sh) = c0 {
                scale_user_sgpr_by_shift(o1, sh & 31)
            } else {
                SgprOrigin::Unknown
            }
        }
        // v_and_b32
        0x1B => {
            if let (Some(v0), Some(v1)) = (c0, c1) {
                SgprOrigin::ConstImmediate {
                    def_inst_idx: inst_idx,
                    value: Some(v0 & v1),
                }
            } else if src0 == src1 {
                o0
            } else if let Some(m) = c0 {
                apply_and_const(o1, m, inst_idx)
            } else if let Some(m) = c1 {
                apply_and_const(o0, m, inst_idx)
            } else {
                SgprOrigin::Unknown
            }
        }
        // v_or_b32
        0x1C => {
            if let (Some(v0), Some(v1)) = (c0, c1) {
                SgprOrigin::ConstImmediate {
                    def_inst_idx: inst_idx,
                    value: Some(v0 | v1),
                }
            } else if src0 == src1 {
                o0
            } else if let Some(imm) = c0 {
                apply_or_const(o1, imm, inst_idx)
            } else if let Some(imm) = c1 {
                apply_or_const(o0, imm, inst_idx)
            } else {
                SgprOrigin::Unknown
            }
        }
        // v_xor_b32
        0x1D => {
            if let (Some(v0), Some(v1)) = (c0, c1) {
                SgprOrigin::ConstImmediate {
                    def_inst_idx: inst_idx,
                    value: Some(v0 ^ v1),
                }
            } else if src0 == src1 {
                SgprOrigin::ConstImmediate {
                    def_inst_idx: inst_idx,
                    value: Some(0),
                }
            } else {
                SgprOrigin::Unknown
            }
        }
        // v_add_nc_u32
        0x25 => eval_valu_add_origins(o0, o1, c0, c1, inst_idx),
        // v_sub_nc_u32: src0 - src1
        0x26 => {
            if let (Some(v0), Some(v1)) = (c0, c1) {
                SgprOrigin::ConstImmediate {
                    def_inst_idx: inst_idx,
                    value: Some(v0.wrapping_sub(v1)),
                }
            } else if src0 == src1 {
                SgprOrigin::ConstImmediate {
                    def_inst_idx: inst_idx,
                    value: Some(0),
                }
            } else if let Some(imm) = c1 {
                apply_const_offset(o0, (imm as i32).wrapping_neg())
            } else {
                SgprOrigin::Unknown
            }
        }
        // v_subrev_nc_u32: src1 - src0
        0x27 => {
            if let (Some(v0), Some(v1)) = (c0, c1) {
                SgprOrigin::ConstImmediate {
                    def_inst_idx: inst_idx,
                    value: Some(v1.wrapping_sub(v0)),
                }
            } else if src0 == src1 {
                SgprOrigin::ConstImmediate {
                    def_inst_idx: inst_idx,
                    value: Some(0),
                }
            } else if let Some(imm) = c0 {
                apply_const_offset(o1, (imm as i32).wrapping_neg())
            } else {
                SgprOrigin::Unknown
            }
        }
        _ => SgprOrigin::Unknown,
    };
    is_trackable_valu_origin(res).then_some(res)
}

fn eval_valu_lane_origin_vop3(
    state: &OriginState,
    op: u16,
    src0: u16,
    src1: u16,
    src2: u16,
    literal: Option<u32>,
    inst_idx: usize,
) -> Option<SgprOrigin> {
    if (0x100..=0x13F).contains(&op) {
        return eval_valu_lane_origin_vop2_like(
            state,
            (op - 0x100) as u8,
            src0,
            src1,
            literal,
            inst_idx,
        );
    }
    let res = match op {
        // v_mad_i32_i24 / v_mad_u32_u24: src0 * src1 + src2 (common RDNA2 heap_base + idx * stride)
        0x142 | 0x143 => {
            let mask24 = |v: u32| -> i32 {
                if op == 0x142 {
                    ((v << 8) as i32) >> 8
                } else {
                    (v & 0x00FF_FFFF) as i32
                }
            };
            let o0 = resolve_valu_lane_operand(src0, literal, inst_idx, state);
            let o1 = resolve_valu_lane_operand(src1, literal, inst_idx, state);
            let o2 = resolve_valu_lane_operand(src2, literal, inst_idx, state);
            let c0 = resolve_valu_const_u32(src0, literal, state);
            let c1 = resolve_valu_const_u32(src1, literal, state);
            let c2 = resolve_valu_const_u32(src2, literal, state);
            let (prod, prod_c) = if let (Some(v0), Some(v1)) = (c0, c1) {
                let p = mask24(v0).wrapping_mul(mask24(v1)) as u32;
                (
                    SgprOrigin::ConstImmediate {
                        def_inst_idx: inst_idx,
                        value: Some(p),
                    },
                    Some(p),
                )
            } else if let Some(v0) = c0 {
                (scale_user_sgpr_by_mul(o1, mask24(v0)), None)
            } else if let Some(v1) = c1 {
                (scale_user_sgpr_by_mul(o0, mask24(v1)), None)
            } else {
                (SgprOrigin::Unknown, None)
            };
            eval_valu_add_origins(prod, o2, prod_c, c2, inst_idx)
        }
        // v_bfe_u32 vdst, src0, off(src1), width(src2)
        0x148 => {
            let o0 = resolve_valu_lane_operand(src0, literal, inst_idx, state);
            if let (Some(off), Some(width)) = (
                resolve_valu_const_u32(src1, literal, state),
                resolve_valu_const_u32(src2, literal, state),
            ) {
                if let Some(v0) = resolve_valu_const_u32(src0, literal, state) {
                    let o = off & 31;
                    let w = width & 0x7F;
                    let folded = if w == 0 {
                        0
                    } else if w >= 32 {
                        v0.wrapping_shr(o)
                    } else {
                        v0.wrapping_shr(o) & ((1u32 << w) - 1)
                    };
                    SgprOrigin::ConstImmediate {
                        def_inst_idx: inst_idx,
                        value: Some(folded),
                    }
                } else {
                    let param = (off & 31) | ((width & 0x7F) << 16);
                    apply_bfe_u32_const(o0, param, inst_idx)
                }
            } else {
                SgprOrigin::Unknown
            }
        }
        // v_min3_i32 / v_min3_u32
        0x152 | 0x153 => {
            let signed = op == 0x152;
            let o0 = resolve_valu_lane_operand(src0, literal, inst_idx, state);
            let o1 = resolve_valu_lane_operand(src1, literal, inst_idx, state);
            let o2 = resolve_valu_lane_operand(src2, literal, inst_idx, state);
            let c0 = resolve_valu_const_u32(src0, literal, state);
            let c1 = resolve_valu_const_u32(src1, literal, state);
            let c2 = resolve_valu_const_u32(src2, literal, state);
            let non_const: Vec<SgprOrigin> = [(o0, c0), (o1, c1), (o2, c2)]
                .into_iter()
                .filter_map(|(o, c)| c.is_none().then_some(o))
                .collect();
            let consts: Vec<u32> = [c0, c1, c2].into_iter().flatten().collect();
            if non_const.is_empty() && consts.len() == 3 {
                let folded = if signed {
                    (consts[0] as i32)
                        .min(consts[1] as i32)
                        .min(consts[2] as i32) as u32
                } else {
                    consts[0].min(consts[1]).min(consts[2])
                };
                SgprOrigin::ConstImmediate {
                    def_inst_idx: inst_idx,
                    value: Some(folded),
                }
            } else if non_const.len() == 1 && !consts.is_empty() {
                let mut cur = non_const[0];
                for lim in consts {
                    cur = apply_min_const(cur, lim, signed);
                }
                cur
            } else {
                SgprOrigin::Unknown
            }
        }
        // v_med3_i32 / v_med3_u32: HLSL `clamp(x, 0, lim)` lowers to `v_med3_u32/i32(x, 0, lim)`
        0x158 | 0x159 => {
            let signed = op == 0x158;
            let o0 = resolve_valu_lane_operand(src0, literal, inst_idx, state);
            let o1 = resolve_valu_lane_operand(src1, literal, inst_idx, state);
            let o2 = resolve_valu_lane_operand(src2, literal, inst_idx, state);
            let c0 = resolve_valu_const_u32(src0, literal, state);
            let c1 = resolve_valu_const_u32(src1, literal, state);
            let c2 = resolve_valu_const_u32(src2, literal, state);
            let non_const: Vec<SgprOrigin> = [(o0, c0), (o1, c1), (o2, c2)]
                .into_iter()
                .filter_map(|(o, c)| c.is_none().then_some(o))
                .collect();
            let consts: Vec<u32> = [c0, c1, c2].into_iter().flatten().collect();
            if non_const.len() == 1 && consts.len() == 2 {
                let (lo, hi) = if signed {
                    let a = consts[0] as i32;
                    let b = consts[1] as i32;
                    if a <= b { (a, b) } else { (b, a) }
                } else {
                    let a = consts[0];
                    let b = consts[1];
                    if a <= b {
                        (a as i32, b as i32)
                    } else {
                        (b as i32, a as i32)
                    }
                };
                if (!signed && lo == 0) || (signed && lo >= 0 && hi >= lo) {
                    apply_min_const(non_const[0], hi as u32, signed)
                } else {
                    SgprOrigin::Unknown
                }
            } else {
                SgprOrigin::Unknown
            }
        }
        // v_mul_lo_u32 vdst, src0, src1
        0x169 => {
            let o0 = resolve_valu_lane_operand(src0, literal, inst_idx, state);
            let o1 = resolve_valu_lane_operand(src1, literal, inst_idx, state);
            let c0 = resolve_valu_const_u32(src0, literal, state);
            let c1 = resolve_valu_const_u32(src1, literal, state);
            if let (Some(v0), Some(v1)) = (c0, c1) {
                SgprOrigin::ConstImmediate {
                    def_inst_idx: inst_idx,
                    value: Some(v0.wrapping_mul(v1)),
                }
            } else if let Some(f) = c1 {
                scale_user_sgpr_by_mul(o0, f as i32)
            } else if let Some(f) = c0 {
                scale_user_sgpr_by_mul(o1, f as i32)
            } else {
                SgprOrigin::Unknown
            }
        }
        // v_lshlrev_b64 v[vdst:vdst+1], shift(src0), src1_pair: low word shift
        0x2FF => {
            if let Some(raw_sh) = resolve_valu_const_u32(src0, literal, state) {
                let sh = raw_sh & 63;
                if sh < 32 {
                    let o1 = resolve_valu_lane_operand(src1, literal, inst_idx, state);
                    if let Some(v1) = resolve_valu_const_u32(src1, literal, state) {
                        SgprOrigin::ConstImmediate {
                            def_inst_idx: inst_idx,
                            value: Some(v1.wrapping_shl(sh)),
                        }
                    } else {
                        scale_user_sgpr_by_shift(o1, sh)
                    }
                } else {
                    SgprOrigin::Unknown
                }
            } else {
                SgprOrigin::Unknown
            }
        }
        // v_add_co_u32 / v_sub_co_u32 / v_subrev_co_u32
        0x30F => {
            return eval_valu_lane_origin_vop2_like(state, 0x25, src0, src1, literal, inst_idx);
        }
        0x310 => {
            return eval_valu_lane_origin_vop2_like(state, 0x26, src0, src1, literal, inst_idx);
        }
        0x319 => {
            return eval_valu_lane_origin_vop2_like(state, 0x27, src0, src1, literal, inst_idx);
        }
        // v_lshl_add_u32 vdst, src0, shift(src1), src2: (src0 << shift) + src2
        0x346 => {
            if let Some(sh) = resolve_valu_const_u32(src1, literal, state) {
                let sh = sh & 31;
                let o0 = resolve_valu_lane_operand(src0, literal, inst_idx, state);
                let o2 = resolve_valu_lane_operand(src2, literal, inst_idx, state);
                let c0 = resolve_valu_const_u32(src0, literal, state);
                let c2 = resolve_valu_const_u32(src2, literal, state);
                let (scaled, scaled_c) = if let Some(v0) = c0 {
                    let s = v0.wrapping_shl(sh);
                    (
                        SgprOrigin::ConstImmediate {
                            def_inst_idx: inst_idx,
                            value: Some(s),
                        },
                        Some(s),
                    )
                } else {
                    (scale_user_sgpr_by_shift(o0, sh), None)
                };
                eval_valu_add_origins(scaled, o2, scaled_c, c2, inst_idx)
            } else {
                SgprOrigin::Unknown
            }
        }
        // v_add_lshl_u32 vdst, src0, src1, shift(src2): (src0 + src1) << shift
        0x347 => {
            if let Some(sh) = resolve_valu_const_u32(src2, literal, state) {
                let sh = sh & 31;
                let o0 = resolve_valu_lane_operand(src0, literal, inst_idx, state);
                let o1 = resolve_valu_lane_operand(src1, literal, inst_idx, state);
                let c0 = resolve_valu_const_u32(src0, literal, state);
                let c1 = resolve_valu_const_u32(src1, literal, state);
                let sum = eval_valu_add_origins(o0, o1, c0, c1, inst_idx);
                if let SgprOrigin::ConstImmediate { value: Some(v), .. } = sum {
                    SgprOrigin::ConstImmediate {
                        def_inst_idx: inst_idx,
                        value: Some(v.wrapping_shl(sh)),
                    }
                } else {
                    scale_user_sgpr_by_shift(sum, sh)
                }
            } else {
                SgprOrigin::Unknown
            }
        }
        // v_add3_u32: src0 + src1 + src2
        0x36D => {
            let o0 = resolve_valu_lane_operand(src0, literal, inst_idx, state);
            let o1 = resolve_valu_lane_operand(src1, literal, inst_idx, state);
            let o2 = resolve_valu_lane_operand(src2, literal, inst_idx, state);
            let c0 = resolve_valu_const_u32(src0, literal, state);
            let c1 = resolve_valu_const_u32(src1, literal, state);
            let c2 = resolve_valu_const_u32(src2, literal, state);
            let s01 = eval_valu_add_origins(o0, o1, c0, c1, inst_idx);
            let c01 = match s01 {
                SgprOrigin::ConstImmediate { value, .. } => value,
                _ => None,
            };
            eval_valu_add_origins(s01, o2, c01, c2, inst_idx)
        }
        // v_lshl_or_b32: (src0 << (src1 & 31)) | src2
        0x36E => {
            if let Some(sh) = resolve_valu_const_u32(src1, literal, state) {
                let sh = sh & 31;
                let o0 = resolve_valu_lane_operand(src0, literal, inst_idx, state);
                let c0 = resolve_valu_const_u32(src0, literal, state);
                let c2 = resolve_valu_const_u32(src2, literal, state);
                let scaled = if let Some(v0) = c0 {
                    SgprOrigin::ConstImmediate {
                        def_inst_idx: inst_idx,
                        value: Some(v0.wrapping_shl(sh)),
                    }
                } else {
                    scale_user_sgpr_by_shift(o0, sh)
                };
                if let Some(imm) = c2 {
                    apply_or_const(scaled, imm, inst_idx)
                } else {
                    SgprOrigin::Unknown
                }
            } else {
                SgprOrigin::Unknown
            }
        }
        // v_and_or_b32: (src0 & src1) | src2
        0x36F | 0x371 => {
            let o0 = resolve_valu_lane_operand(src0, literal, inst_idx, state);
            let o1 = resolve_valu_lane_operand(src1, literal, inst_idx, state);
            let c0 = resolve_valu_const_u32(src0, literal, state);
            let c1 = resolve_valu_const_u32(src1, literal, state);
            let c2 = resolve_valu_const_u32(src2, literal, state);
            let masked = if let (Some(v0), Some(v1)) = (c0, c1) {
                SgprOrigin::ConstImmediate {
                    def_inst_idx: inst_idx,
                    value: Some(v0 & v1),
                }
            } else if let Some(m) = c0 {
                apply_and_const(o1, m, inst_idx)
            } else if let Some(m) = c1 {
                apply_and_const(o0, m, inst_idx)
            } else {
                SgprOrigin::Unknown
            };
            if let Some(imm) = c2 {
                apply_or_const(masked, imm, inst_idx)
            } else {
                SgprOrigin::Unknown
            }
        }
        _ => SgprOrigin::Unknown,
    };
    is_trackable_valu_origin(res).then_some(res)
}

fn step_origin_state(
    state: &mut OriginState,
    inst_idx: usize,
    inst: &Rdna2Instruction,
    stage: ShaderStage,
    is_wave32: bool,
    mut collector: Option<&mut AnalysisCollector>,
) {
    if inst.truncated {
        return;
    }
    match &inst.detail {
        Rdna2Detail::Sopc {
            op,
            ssrc0,
            ssrc1,
            literal,
        } => {
            state.last_carry_lo_reg = None;
            state.last_scc_bound = {
                let c0 = resolve_const_u32(*ssrc0, *literal, &state.origins);
                let c1 = resolve_const_u32(*ssrc1, *literal, &state.origins);
                let max_cap = u32::from(MAX_BOUNDED_CBV_HEAP_ELEMS);
                if *ssrc0 <= MAX_TRACKED_SGPR
                    && let Some(k) = c1
                {
                    match *op {
                        // s_cmp_lt_i32 / s_cmp_lt_u32: ssrc0 < K -> in-bounds when scc == 1
                        0x04 | 0x0A if (1..=max_cap).contains(&k) => Some((*ssrc0, k as u8, true)),
                        // s_cmp_le_i32 / s_cmp_le_u32: ssrc0 <= K -> in-bounds when scc == 1
                        0x05 | 0x0B if k < max_cap => Some((*ssrc0, (k + 1) as u8, true)),
                        // s_cmp_gt_i32 / s_cmp_gt_u32: !(ssrc0 > K) => ssrc0 <= K when scc == 0
                        0x02 | 0x08 if k < max_cap => Some((*ssrc0, (k + 1) as u8, false)),
                        // s_cmp_ge_i32 / s_cmp_ge_u32: !(ssrc0 >= K) => ssrc0 < K when scc == 0
                        0x03 | 0x09 if (1..=max_cap).contains(&k) => Some((*ssrc0, k as u8, false)),
                        _ => None,
                    }
                } else if *ssrc1 <= MAX_TRACKED_SGPR
                    && let Some(k) = c0
                {
                    match *op {
                        // s_cmp_gt_i32 / s_cmp_gt_u32: K > ssrc1 => ssrc1 < K when scc == 1
                        0x02 | 0x08 if (1..=max_cap).contains(&k) => Some((*ssrc1, k as u8, true)),
                        // s_cmp_ge_i32 / s_cmp_ge_u32: K >= ssrc1 => ssrc1 <= K when scc == 1
                        0x03 | 0x09 if k < max_cap => Some((*ssrc1, (k + 1) as u8, true)),
                        // s_cmp_lt_i32 / s_cmp_lt_u32: !(K < ssrc1) => ssrc1 <= K when scc == 0
                        0x04 | 0x0A if k < max_cap => Some((*ssrc1, (k + 1) as u8, false)),
                        // s_cmp_le_i32 / s_cmp_le_u32: !(K <= ssrc1) => ssrc1 < K when scc == 0
                        0x05 | 0x0B if (1..=max_cap).contains(&k) => Some((*ssrc1, k as u8, false)),
                        _ => None,
                    }
                } else {
                    None
                }
            };
            taint_sgpr_if_loaded(&mut collector, &state.origins, u16::from(*ssrc0));
            taint_sgpr_if_loaded(&mut collector, &state.origins, u16::from(*ssrc1));
            let (pair0, pair1) = sopc_src_pair_widths(*op);
            if pair0 && *ssrc0 <= MAX_TRACKED_SGPR_PAIR {
                taint_sgpr_if_loaded(&mut collector, &state.origins, u16::from(*ssrc0 + 1));
            }
            if pair1 && *ssrc1 <= MAX_TRACKED_SGPR_PAIR {
                taint_sgpr_if_loaded(&mut collector, &state.origins, u16::from(*ssrc1 + 1));
            }
        }
        Rdna2Detail::Sop1 {
            op,
            sdst,
            ssrc0,
            literal,
        } => {
            // Pure moves/cmovs and PC control ops leave SCC untouched; other SOP1 ops overwrite SCC.
            if !matches!(*op, 0x03..=0x06 | 0x1F..=0x22) {
                state.last_carry_lo_reg = None;
                state.last_scc_bound = None;
            }
            // Pure register copies & conditional moves never taint descriptor provenance.
            let is_copy_or_cmov = matches!(*op, 0x03 | 0x04 | 0x05 | 0x06);
            if !is_copy_or_cmov {
                taint_sgpr_if_loaded(&mut collector, &state.origins, u16::from(*ssrc0));
                if sop1_reads_pair(*op) && *ssrc0 <= MAX_TRACKED_SGPR_PAIR {
                    taint_sgpr_if_loaded(&mut collector, &state.origins, u16::from(*ssrc0 + 1));
                }
                if matches!(*op, 0x1B..=0x1E) {
                    taint_sgpr_if_loaded(&mut collector, &state.origins, u16::from(*sdst));
                    if matches!(*op, 0x1C | 0x1E) && *sdst <= MAX_TRACKED_SGPR_PAIR {
                        taint_sgpr_if_loaded(&mut collector, &state.origins, u16::from(*sdst + 1));
                    }
                }
            }
            if sop1_writes_pair(*op) {
                if *sdst <= MAX_TRACKED_SGPR_PAIR {
                    let (new_lo, new_hi) = match *op {
                        0x04 => {
                            // s_mov_b64
                            resolve_src_pair_origins(*ssrc0, *literal, inst_idx, &state.origins)
                        }
                        0x06 => {
                            // s_cmov_b64
                            let (src_lo, src_hi) =
                                resolve_src_pair_origins(*ssrc0, *literal, inst_idx, &state.origins);
                            let dst_lo = state.sgpr_origin(*sdst);
                            let dst_hi = state.sgpr_origin(sdst.saturating_add(1));
                            let (da, dda) = match collector.as_deref_mut() {
                                Some(c) => (Some(&mut c.def_aliases), Some(&mut c.divergent_def_aliases)),
                                None => (None, None),
                            };
                            let lo = merge_select_origin(dst_lo, src_lo, inst_idx, da, dda);
                            let (da, dda) = match collector.as_deref_mut() {
                                Some(c) => (Some(&mut c.def_aliases), Some(&mut c.divergent_def_aliases)),
                                None => (None, None),
                            };
                            let hi = merge_select_origin(dst_hi, src_hi, inst_idx, da, dda);
                            (lo, hi)
                        }
                        0x08 => {
                            // s_not_b64
                            let (src_lo, src_hi) =
                                resolve_src_pair_origins(*ssrc0, *literal, inst_idx, &state.origins);
                            match (src_lo, src_hi) {
                                (
                                    SgprOrigin::ConstImmediate { value: lo, .. },
                                    SgprOrigin::ConstImmediate { value: hi, .. },
                                ) => (
                                    SgprOrigin::ConstImmediate {
                                        def_inst_idx: inst_idx,
                                        value: lo.map(|v| !v),
                                    },
                                    SgprOrigin::ConstImmediate {
                                        def_inst_idx: inst_idx,
                                        value: hi.map(|v| !v),
                                    },
                                ),
                                _ => (SgprOrigin::Unknown, SgprOrigin::Unknown),
                            }
                        }
                        0x0C => {
                            // s_brev_b64
                            let (src_lo, src_hi) =
                                resolve_src_pair_origins(*ssrc0, *literal, inst_idx, &state.origins);
                            match (src_lo, src_hi) {
                                (
                                    SgprOrigin::ConstImmediate { value: lo, .. },
                                    SgprOrigin::ConstImmediate { value: hi, .. },
                                ) => {
                                    let rev = lo.zip(hi).map(|(l, h)| {
                                        ((u64::from(h) << 32) | u64::from(l)).reverse_bits()
                                    });
                                    (
                                        SgprOrigin::ConstImmediate {
                                            def_inst_idx: inst_idx,
                                            value: rev.map(|v| v as u32),
                                        },
                                        SgprOrigin::ConstImmediate {
                                            def_inst_idx: inst_idx,
                                            value: rev.map(|v| (v >> 32) as u32),
                                        },
                                    )
                                }
                                _ => (SgprOrigin::Unknown, SgprOrigin::Unknown),
                            }
                        }
                        0x1C | 0x1E => {
                            // s_bitset0_b64 / s_bitset1_b64
                            let dst_lo = state.sgpr_origin(*sdst);
                            let dst_hi = state.sgpr_origin(sdst.saturating_add(1));
                            if let (
                                SgprOrigin::ConstImmediate { value: lo_v, .. },
                                SgprOrigin::ConstImmediate { value: hi_v, .. },
                            ) = (dst_lo, dst_hi)
                                && is_const_src(*ssrc0, &state.origins)
                            {
                                let bit = resolve_const_u32(*ssrc0, *literal, &state.origins);
                                let val64 = lo_v.zip(hi_v).zip(bit).map(|((l, h), b)| {
                                    let cur = (u64::from(h) << 32) | u64::from(l);
                                    let mask = 1u64 << (b & 63);
                                    if *op == 0x1C { cur & !mask } else { cur | mask }
                                });
                                (
                                    SgprOrigin::ConstImmediate {
                                        def_inst_idx: inst_idx,
                                        value: val64.map(|v| v as u32),
                                    },
                                    SgprOrigin::ConstImmediate {
                                        def_inst_idx: inst_idx,
                                        value: val64.map(|v| (v >> 32) as u32),
                                    },
                                )
                            } else {
                                let lo = patched_desc_word_of(dst_lo).map_or(
                                    SgprOrigin::Unknown,
                                    |(def_inst_idx, base)| SgprOrigin::PatchedDescWord {
                                        def_inst_idx,
                                        base,
                                    },
                                );
                                let hi = patched_desc_word_of(dst_hi).map_or(
                                    SgprOrigin::Unknown,
                                    |(def_inst_idx, base)| SgprOrigin::PatchedDescWord {
                                        def_inst_idx,
                                        base,
                                    },
                                );
                                (lo, hi)
                            }
                        }
                        0x3B => {
                            // s_bitreplicate_b64_b32: replicate each bit i into bits (2i, 2i+1)
                            if is_const_src(*ssrc0, &state.origins) {
                                let val64 = resolve_const_u32(*ssrc0, *literal, &state.origins)
                                    .map(|v| {
                                        let mut out = 0u64;
                                        for i in 0..32u32 {
                                            if ((v >> i) & 1) != 0 {
                                                out |= 3u64 << (i * 2);
                                            }
                                        }
                                        out
                                    });
                                (
                                    SgprOrigin::ConstImmediate {
                                        def_inst_idx: inst_idx,
                                        value: val64.map(|v| v as u32),
                                    },
                                    SgprOrigin::ConstImmediate {
                                        def_inst_idx: inst_idx,
                                        value: val64.map(|v| (v >> 32) as u32),
                                    },
                                )
                            } else {
                                (SgprOrigin::Unknown, SgprOrigin::Unknown)
                            }
                        }
                        _ => (SgprOrigin::Unknown, SgprOrigin::Unknown),
                    };
                    state.set_sgpr_origin(*sdst, new_lo);
                    if let Some(hi_reg) = checked_tracked_sgpr_reg(*sdst, 1) {
                        state.set_sgpr_origin(hi_reg, new_hi);
                        clear_pending_xor_if(state, hi_reg);
                    }
                    clear_pending_xor_if(state, *sdst);
                } else if *sdst == MAX_TRACKED_SGPR {
                    state.set_sgpr_origin(MAX_TRACKED_SGPR, SgprOrigin::Unknown);
                    clear_pending_xor_if(state, MAX_TRACKED_SGPR);
                }
            } else if *sdst <= MAX_TRACKED_SGPR {
                let prev = state.sgpr_origin(*sdst);
                let next = match *op {
                    0x03 => {
                        // s_mov_b32
                        resolve_src_origin_u8(*ssrc0, *literal, inst_idx, &state.origins)
                    }
                    0x05 => {
                        // s_cmov_b32
                        let src = resolve_src_origin_u8(*ssrc0, *literal, inst_idx, &state.origins);
                        let (da, dda) = match collector.as_deref_mut() {
                            Some(c) => (Some(&mut c.def_aliases), Some(&mut c.divergent_def_aliases)),
                            None => (None, None),
                        };
                        merge_select_origin(prev, src, inst_idx, da, dda)
                    }
                    0x07 => {
                        // s_not_b32
                        if let Some(v) = resolve_const_u32(*ssrc0, *literal, &state.origins) {
                            SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: Some(!v),
                            }
                        } else if is_const_src(*ssrc0, &state.origins) {
                            SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: None,
                            }
                        } else {
                            SgprOrigin::Unknown
                        }
                    }
                    0x0B => {
                        // s_brev_b32
                        resolve_const_u32(*ssrc0, *literal, &state.origins).map_or(
                            SgprOrigin::Unknown,
                            |v| SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: Some(v.reverse_bits()),
                            },
                        )
                    }
                    0x19 => {
                        // s_sext_i32_i8
                        resolve_const_u32(*ssrc0, *literal, &state.origins).map_or(
                            SgprOrigin::Unknown,
                            |v| SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: Some(i32::from(v as i8) as u32),
                            },
                        )
                    }
                    0x1A => {
                        // s_sext_i32_i16
                        resolve_const_u32(*ssrc0, *literal, &state.origins).map_or(
                            SgprOrigin::Unknown,
                            |v| SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: Some(i32::from(v as i16) as u32),
                            },
                        )
                    }
                    0x1B => {
                        // s_bitset0_b32
                        if let SgprOrigin::ConstImmediate { value, .. } = prev
                            && is_const_src(*ssrc0, &state.origins)
                        {
                            let bit = resolve_const_u32(*ssrc0, *literal, &state.origins);
                            SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: value
                                    .zip(bit)
                                    .map(|(v, b)| v & !(1u32 << (b & 31))),
                            }
                        } else if let Some((def_inst_idx, base)) = patched_desc_word_of(prev) {
                            SgprOrigin::PatchedDescWord { def_inst_idx, base }
                        } else {
                            SgprOrigin::Unknown
                        }
                    }
                    0x1D => {
                        // s_bitset1_b32
                        if let SgprOrigin::ConstImmediate { value, .. } = prev
                            && is_const_src(*ssrc0, &state.origins)
                        {
                            let bit = resolve_const_u32(*ssrc0, *literal, &state.origins);
                            SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: value
                                    .zip(bit)
                                    .map(|(v, b)| v | (1u32 << (b & 31))),
                            }
                        } else if let Some((def_inst_idx, base)) = patched_desc_word_of(prev) {
                            SgprOrigin::PatchedDescWord { def_inst_idx, base }
                        } else {
                            SgprOrigin::Unknown
                        }
                    }
                    0x34 => {
                        // s_abs_i32
                        resolve_const_u32(*ssrc0, *literal, &state.origins).map_or(
                            SgprOrigin::Unknown,
                            |v| SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: Some((v as i32).wrapping_abs() as u32),
                            },
                        )
                    }
                    _ => SgprOrigin::Unknown,
                };
                let propagated_bound = if *op == 0x03 && *ssrc0 <= MAX_TRACKED_SGPR {
                    state.sgpr_bound(*ssrc0)
                } else {
                    0
                };
                state.set_sgpr_origin(*sdst, next);
                if propagated_bound > 0 {
                    state.set_sgpr_bound(*sdst, propagated_bound);
                }
                clear_pending_xor_if(state, *sdst);
            }
        }
        Rdna2Detail::Sopk {
            op, sdst, simm16, ..
        } => {
            if *op == 0x0F && *sdst <= MAX_TRACKED_SGPR_PAIR {
                state.last_carry_lo_reg = Some(*sdst);
                state.last_scc_bound = None;
            } else if matches!(*op, 0x03..=0x0E | 0x10) {
                state.last_carry_lo_reg = None;
                let max_cap = i32::from(MAX_BOUNDED_CBV_HEAP_ELEMS);
                let simm_i = i32::from(*simm16 as i16);
                let simm_u = i32::from(*simm16);
                state.last_scc_bound = if *sdst <= MAX_TRACKED_SGPR {
                    match *op {
                        // s_cmpk_lt_i32 (0x07) / s_cmpk_lt_u32 (0x0D)
                        0x07 if (1..=max_cap).contains(&simm_i) => {
                            Some((*sdst, simm_i as u8, true))
                        }
                        0x0D if (1..=max_cap).contains(&simm_u) => {
                            Some((*sdst, simm_u as u8, true))
                        }
                        // s_cmpk_le_i32 (0x08) / s_cmpk_le_u32 (0x0E)
                        0x08 if (0..max_cap).contains(&simm_i) => {
                            Some((*sdst, (simm_i + 1) as u8, true))
                        }
                        0x0E if (0..max_cap).contains(&simm_u) => {
                            Some((*sdst, (simm_u + 1) as u8, true))
                        }
                        // s_cmpk_gt_i32 (0x05) / s_cmpk_gt_u32 (0x0B): !(sdst > K) => sdst <= K
                        0x05 if (0..max_cap).contains(&simm_i) => {
                            Some((*sdst, (simm_i + 1) as u8, false))
                        }
                        0x0B if (0..max_cap).contains(&simm_u) => {
                            Some((*sdst, (simm_u + 1) as u8, false))
                        }
                        // s_cmpk_ge_i32 (0x06) / s_cmpk_ge_u32 (0x0C): !(sdst >= K) => sdst < K
                        0x06 if (1..=max_cap).contains(&simm_i) => {
                            Some((*sdst, simm_i as u8, false))
                        }
                        0x0C if (1..=max_cap).contains(&simm_u) => {
                            Some((*sdst, simm_u as u8, false))
                        }
                        _ => None,
                    }
                } else {
                    None
                };
            }
            if matches!(*op, 0x03..=0x0E | 0x10) {
                taint_sgpr_if_loaded(&mut collector, &state.origins, u16::from(*sdst));
            }
            if !matches!(*op, 0x03..=0x0E | 0x17..=0x1A) && *sdst <= MAX_TRACKED_SGPR {
                let prev_origin = state.sgpr_origin(*sdst);
                let imm = i32::from(*simm16 as i16);
                let next_sopk = match *op {
                    0x00 => {
                        // s_movk_i32
                        SgprOrigin::ConstImmediate {
                            def_inst_idx: inst_idx,
                            value: Some(imm as u32),
                        }
                    }
                    0x02 => {
                        // s_cmovk_i32
                        let (da, dda) = match collector.as_deref_mut() {
                            Some(c) => (Some(&mut c.def_aliases), Some(&mut c.divergent_def_aliases)),
                            None => (None, None),
                        };
                        merge_select_origin(
                            prev_origin,
                            SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: Some(imm as u32),
                            },
                            inst_idx,
                            da,
                            dda,
                        )
                    }
                    0x0F => {
                        // s_addk_i32
                        if let SgprOrigin::ConstImmediate { value, .. } = prev_origin {
                            SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: value.map(|v| v.wrapping_add(imm as u32)),
                            }
                        } else {
                            apply_const_offset(prev_origin, imm)
                        }
                    }
                    0x10 => {
                        // s_mulk_i32
                        if let SgprOrigin::ConstImmediate { value, .. } = prev_origin {
                            SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: value.map(|v| v.wrapping_mul(imm as u32)),
                            }
                        } else {
                            scale_user_sgpr_by_mul(prev_origin, imm)
                        }
                    }
                    _ => SgprOrigin::Unknown,
                };
                state.set_sgpr_origin(*sdst, next_sopk);
                clear_pending_xor_if(state, *sdst);
            }
        }
        Rdna2Detail::Sop2 {
            op,
            sdst,
            ssrc0,
            ssrc1,
            literal,
        } => {
            state.last_scc_bound = None;
            let (pair0, pair1) = sop2_src_pair_widths(*op);
            // Address arithmetic, selects, and alignment masks on pointers do not taint loaded
            // descriptors (if the result is later consumed by math/compare/VALU, that taints it).
            let is_addr_or_select_op = matches!(
                *op,
                0x00..=0x05
                    | 0x0A
                    | 0x0B
                    | 0x0E
                    | 0x0F
                    | 0x10
                    | 0x11
                    | 0x14
                    | 0x15
                    | 0x2E..=0x31
            );
            if !is_addr_or_select_op {
                taint_sgpr_if_loaded(&mut collector, &state.origins, u16::from(*ssrc0));
                taint_sgpr_if_loaded(&mut collector, &state.origins, u16::from(*ssrc1));
                if pair0 && *ssrc0 <= MAX_TRACKED_SGPR_PAIR {
                    taint_sgpr_if_loaded(&mut collector, &state.origins, u16::from(*ssrc0 + 1));
                }
                if pair1 && *ssrc1 <= MAX_TRACKED_SGPR_PAIR {
                    taint_sgpr_if_loaded(&mut collector, &state.origins, u16::from(*ssrc1 + 1));
                }
            }
            if *op == 0x25 && *sdst <= MAX_TRACKED_SGPR_PAIR {
                // s_bfm_b64 writes a 64-bit SGPR pair from two 32-bit operands (frequently
                // used to materialize inline static sampler S# descriptors).
                let (lo_orig, hi_orig) = if is_const_src(*ssrc0, &state.origins)
                    && is_const_src(*ssrc1, &state.origins)
                {
                    let val64 = resolve_const_u32(*ssrc0, *literal, &state.origins)
                        .zip(resolve_const_u32(*ssrc1, *literal, &state.origins))
                        .map(|(w, o)| {
                            let width = w & 63;
                            let off = o & 63;
                            let mask = if width == 0 {
                                0u64
                            } else {
                                (1u64 << width).wrapping_sub(1)
                            };
                            mask.wrapping_shl(off)
                        });
                    (
                        SgprOrigin::ConstImmediate {
                            def_inst_idx: inst_idx,
                            value: val64.map(|v| v as u32),
                        },
                        SgprOrigin::ConstImmediate {
                            def_inst_idx: inst_idx,
                            value: val64.map(|v| (v >> 32) as u32),
                        },
                    )
                } else {
                    (SgprOrigin::Unknown, SgprOrigin::Unknown)
                };
                state.set_sgpr_origin(*sdst, lo_orig);
                if let Some(hi_reg) = checked_tracked_sgpr_reg(*sdst, 1) {
                    state.set_sgpr_origin(hi_reg, hi_orig);
                    clear_pending_xor_if(state, hi_reg);
                }
                clear_pending_xor_if(state, *sdst);
            } else if pair0 && *sdst <= MAX_TRACKED_SGPR_PAIR {
                let (s0_lo, s0_hi) =
                    resolve_src_pair_origins(*ssrc0, *literal, inst_idx, &state.origins);
                let (s1_lo, s1_hi) = if pair1 {
                    resolve_src_pair_origins(*ssrc1, *literal, inst_idx, &state.origins)
                } else {
                    let s1 = resolve_src_origin_u8(*ssrc1, *literal, inst_idx, &state.origins);
                    (s1, SgprOrigin::Unknown)
                };
                let mut next_pending_xor_pair = state.pending_xor_pair;
                if let Some((r, _, _)) = next_pending_xor_pair
                    && (*sdst == r
                        || *sdst == r.saturating_add(1)
                        || sdst.saturating_add(1) == r)
                {
                    next_pending_xor_pair = None;
                }
                let (new_lo, new_hi) = match *op {
                    0x0B => {
                        // s_cselect_b64
                        let (da, dda) = match collector.as_deref_mut() {
                            Some(c) => (Some(&mut c.def_aliases), Some(&mut c.divergent_def_aliases)),
                            None => (None, None),
                        };
                        let lo = merge_select_origin(s0_lo, s1_lo, inst_idx, da, dda);
                        let (da, dda) = match collector.as_deref_mut() {
                            Some(c) => (Some(&mut c.def_aliases), Some(&mut c.divergent_def_aliases)),
                            None => (None, None),
                        };
                        let hi = merge_select_origin(s0_hi, s1_hi, inst_idx, da, dda);
                        (lo, hi)
                    }
                    0x0F => {
                        // s_and_b64
                        if *ssrc0 == *ssrc1 && *ssrc0 <= MAX_TRACKED_SGPR_PAIR {
                            (s0_lo, s0_hi)
                        } else {
                            let lo = match (s0_lo, s1_lo) {
                                (SgprOrigin::ConstImmediate { value: Some(m), .. }, other)
                                | (other, SgprOrigin::ConstImmediate { value: Some(m), .. }) => {
                                    apply_and_const(other, m, inst_idx)
                                }
                                (
                                    SgprOrigin::ConstImmediate { .. },
                                    SgprOrigin::ConstImmediate { .. },
                                ) => SgprOrigin::ConstImmediate {
                                    def_inst_idx: inst_idx,
                                    value: None,
                                },
                                _ => SgprOrigin::Unknown,
                            };
                            let hi = match (s0_hi, s1_hi) {
                                (SgprOrigin::ConstImmediate { value: Some(m), .. }, other)
                                | (other, SgprOrigin::ConstImmediate { value: Some(m), .. }) => {
                                    apply_and_const(other, m, inst_idx)
                                }
                                (
                                    SgprOrigin::ConstImmediate { .. },
                                    SgprOrigin::ConstImmediate { .. },
                                ) => SgprOrigin::ConstImmediate {
                                    def_inst_idx: inst_idx,
                                    value: None,
                                },
                                _ => SgprOrigin::Unknown,
                            };
                            (lo, hi)
                        }
                    }
                    0x11 => {
                        // s_or_b64
                        if *ssrc0 == *ssrc1 && *ssrc0 <= MAX_TRACKED_SGPR_PAIR {
                            (s0_lo, s0_hi)
                        } else {
                            let lo = match (s0_lo, s1_lo) {
                                (SgprOrigin::ConstImmediate { value: Some(m), .. }, other)
                                | (other, SgprOrigin::ConstImmediate { value: Some(m), .. }) => {
                                    apply_or_const(other, m, inst_idx)
                                }
                                (
                                    SgprOrigin::ConstImmediate { .. },
                                    SgprOrigin::ConstImmediate { .. },
                                ) => SgprOrigin::ConstImmediate {
                                    def_inst_idx: inst_idx,
                                    value: None,
                                },
                                _ => SgprOrigin::Unknown,
                            };
                            let hi = match (s0_hi, s1_hi) {
                                (SgprOrigin::ConstImmediate { value: Some(m), .. }, other)
                                | (other, SgprOrigin::ConstImmediate { value: Some(m), .. }) => {
                                    apply_or_const(other, m, inst_idx)
                                }
                                (
                                    SgprOrigin::ConstImmediate { .. },
                                    SgprOrigin::ConstImmediate { .. },
                                ) => SgprOrigin::ConstImmediate {
                                    def_inst_idx: inst_idx,
                                    value: None,
                                },
                                _ => SgprOrigin::Unknown,
                            };
                            (lo, hi)
                        }
                    }
                    0x15 => {
                        // s_andn2_b64: ssrc0 & !ssrc1
                        let lo = match s1_lo {
                            SgprOrigin::ConstImmediate { value: Some(m), .. } => {
                                apply_and_const(s0_lo, !m, inst_idx)
                            }
                            SgprOrigin::ConstImmediate { .. }
                                if matches!(s0_lo, SgprOrigin::ConstImmediate { .. }) =>
                            {
                                SgprOrigin::ConstImmediate {
                                    def_inst_idx: inst_idx,
                                    value: None,
                                }
                            }
                            _ => SgprOrigin::Unknown,
                        };
                        let hi = match s1_hi {
                            SgprOrigin::ConstImmediate { value: Some(m), .. } => {
                                apply_and_const(s0_hi, !m, inst_idx)
                            }
                            SgprOrigin::ConstImmediate { .. }
                                if matches!(s0_hi, SgprOrigin::ConstImmediate { .. }) =>
                            {
                                SgprOrigin::ConstImmediate {
                                    def_inst_idx: inst_idx,
                                    value: None,
                                }
                            }
                            _ => SgprOrigin::Unknown,
                        };
                        (lo, hi)
                    }
                    0x1F => {
                        // s_lshl_b64: 64-bit heap-index shift `(u64(idx) << shift)`.
                        if let Some(raw_sh) = resolve_const_u32(*ssrc1, *literal, &state.origins) {
                            let sh = raw_sh & 63;
                            if let (
                                SgprOrigin::ConstImmediate { value: lo_v, .. },
                                SgprOrigin::ConstImmediate { value: hi_v, .. },
                            ) = (s0_lo, s0_hi)
                            {
                                let val64 = lo_v.zip(hi_v).map(|(l, h)| {
                                    ((u64::from(h) << 32) | u64::from(l)).wrapping_shl(sh)
                                });
                                (
                                    SgprOrigin::ConstImmediate {
                                        def_inst_idx: inst_idx,
                                        value: val64.map(|v| v as u32),
                                    },
                                    SgprOrigin::ConstImmediate {
                                        def_inst_idx: inst_idx,
                                        value: val64.map(|v| (v >> 32) as u32),
                                    },
                                )
                            } else if let (
                                SgprOrigin::RightShiftedPtr {
                                    def_inst_idx: ptr_def,
                                    user_sgpr,
                                    table_byte_offset,
                                    shift: packed_sh,
                                },
                                true,
                            ) = (
                                s0_lo,
                                (1..=16).contains(&sh)
                                    && matches!(
                                        s0_hi,
                                        SgprOrigin::ConstImmediate { value: Some(0), .. }
                                            | SgprOrigin::RightShiftedPtr { .. }
                                    ),
                            ) && u32::from(packed_sh) == sh
                            {
                                let restored = match table_byte_offset {
                                    Some(off) => SgprOrigin::TableDesc {
                                        def_inst_idx: ptr_def,
                                        user_sgpr,
                                        table_byte_offset: off,
                                        addr_offset: 0,
                                        cbv_dword: None,
                                    },
                                    None => SgprOrigin::UserTable {
                                        user_sgpr,
                                        byte_offset: 0,
                                    },
                                };
                                (restored, restored)
                            } else if sh < 32 {
                                (
                                    scale_user_sgpr_by_shift(s0_lo, sh),
                                    SgprOrigin::Unknown,
                                )
                            } else {
                                (SgprOrigin::Unknown, SgprOrigin::Unknown)
                            }
                        } else {
                            (SgprOrigin::Unknown, SgprOrigin::Unknown)
                        }
                    }
                    0x13 | 0x17 | 0x19 | 0x1B | 0x1D => {
                        // 64-bit bitwise ops: s_xor_b64, s_orn2_b64, s_nand_b64, s_nor_b64, s_xnor_b64
                        if *op == 0x13 && *ssrc0 == *ssrc1 && *ssrc0 <= MAX_TRACKED_SGPR_PAIR {
                            let z = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: Some(0),
                            };
                            (z, z)
                        } else if let (
                            SgprOrigin::ConstImmediate { value: lo0, .. },
                            SgprOrigin::ConstImmediate { value: hi0, .. },
                            SgprOrigin::ConstImmediate { value: lo1, .. },
                            SgprOrigin::ConstImmediate { value: hi1, .. },
                        ) = (s0_lo, s0_hi, s1_lo, s1_hi)
                        {
                            let fold32 = |a: u32, b: u32| match *op {
                                0x13 => a ^ b,
                                0x17 => a | !b,
                                0x19 => !(a & b),
                                0x1B => !(a | b),
                                _ => !(a ^ b),
                            };
                            (
                                SgprOrigin::ConstImmediate {
                                    def_inst_idx: inst_idx,
                                    value: lo0.zip(lo1).map(|(a, b)| fold32(a, b)),
                                },
                                SgprOrigin::ConstImmediate {
                                    def_inst_idx: inst_idx,
                                    value: hi0.zip(hi1).map(|(a, b)| fold32(a, b)),
                                },
                            )
                        } else if *op == 0x13
                            && *ssrc0 <= MAX_TRACKED_SGPR_PAIR
                            && *ssrc1 <= MAX_TRACKED_SGPR_PAIR
                            && *ssrc0 != *ssrc1
                        {
                            // Recognize 64-bit 3-XOR in-place SGPR pair swap
                            // (`s_xor_b64 a, a, b; s_xor_b64 b, a, b; s_xor_b64 a, a, b`),
                            // used by the console compiler to reorder 8-SGPR T# descriptors in place.
                            if let Some((xr, pa, pb)) = state.pending_xor_pair {
                                let other_pair = if *ssrc0 == xr {
                                    Some((s1_lo, s1_hi))
                                } else if *ssrc1 == xr {
                                    Some((s0_lo, s0_hi))
                                } else {
                                    None
                                };
                                if let Some(op_pair) = other_pair {
                                    if op_pair == pb {
                                        pa
                                    } else if op_pair == pa {
                                        pb
                                    } else {
                                        (SgprOrigin::Unknown, SgprOrigin::Unknown)
                                    }
                                } else {
                                    (SgprOrigin::Unknown, SgprOrigin::Unknown)
                                }
                            } else if (*sdst == *ssrc0 || *sdst == *ssrc1)
                                && (is_swappable_origin(s0_lo)
                                    || is_swappable_origin(s0_hi)
                                    || is_swappable_origin(s1_lo)
                                    || is_swappable_origin(s1_hi))
                            {
                                next_pending_xor_pair =
                                    Some((*sdst, (s0_lo, s0_hi), (s1_lo, s1_hi)));
                                (SgprOrigin::Unknown, SgprOrigin::Unknown)
                            } else {
                                (SgprOrigin::Unknown, SgprOrigin::Unknown)
                            }
                        } else {
                            (SgprOrigin::Unknown, SgprOrigin::Unknown)
                        }
                    }
                    0x21 | 0x23 | 0x29 | 0x2A => {
                        // s_lshr_b64, s_ashr_i64, s_bfe_u64, s_bfe_i64
                        if let (
                            SgprOrigin::ConstImmediate { value: lo0, .. },
                            SgprOrigin::ConstImmediate { value: hi0, .. },
                            SgprOrigin::ConstImmediate { value: s1_v, .. },
                        ) = (s0_lo, s0_hi, s1_lo)
                        {
                            let val64 = lo0.zip(hi0).zip(s1_v).map(|((l, h), s1)| {
                                let x = (u64::from(h) << 32) | u64::from(l);
                                match *op {
                                    0x21 => x.wrapping_shr(s1 & 63),
                                    0x23 => ((x as i64).wrapping_shr(s1 & 63)) as u64,
                                    0x29 => {
                                        let off = s1 & 63;
                                        let width = (s1 >> 16) & 0x7F;
                                        if width == 0 {
                                            0
                                        } else if width >= 64 {
                                            x.wrapping_shr(off)
                                        } else {
                                            x.wrapping_shr(off) & ((1u64 << width) - 1)
                                        }
                                    }
                                    _ => {
                                        // 0x2A: s_bfe_i64
                                        let off = s1 & 63;
                                        let width = (s1 >> 16) & 0x7F;
                                        if width == 0 {
                                            0
                                        } else if width >= 64 {
                                            ((x as i64).wrapping_shr(off)) as u64
                                        } else {
                                            let sh = 64 - width;
                                            let ext = x.wrapping_shr(off);
                                            (((ext.wrapping_shl(sh)) as i64).wrapping_shr(sh)) as u64
                                        }
                                    }
                                }
                            });
                            (
                                SgprOrigin::ConstImmediate {
                                    def_inst_idx: inst_idx,
                                    value: val64.map(|v| v as u32),
                                },
                                SgprOrigin::ConstImmediate {
                                    def_inst_idx: inst_idx,
                                    value: val64.map(|v| (v >> 32) as u32),
                                },
                            )
                        } else if *op == 0x21
                            && let Some(raw_sh) = resolve_const_u32(*ssrc1, *literal, &state.origins)
                            && (1..=16).contains(&(raw_sh & 63))
                        {
                            // Pack 48-bit aligned GPU VA into 32-bit SGPR via `s_lshr_b64 ptr, k`
                            // (`k` in 1..=16, e.g. `k = 8` for 256B-aligned CBV VA).
                            let sh = (raw_sh & 63) as u8;
                            match s0_lo {
                                SgprOrigin::TableDesc {
                                    def_inst_idx: ptr_def,
                                    user_sgpr,
                                    table_byte_offset,
                                    addr_offset: 0,
                                    ..
                                } => (
                                    SgprOrigin::RightShiftedPtr {
                                        def_inst_idx: ptr_def,
                                        user_sgpr,
                                        table_byte_offset: Some(table_byte_offset),
                                        shift: sh,
                                    },
                                    SgprOrigin::Unknown,
                                ),
                                SgprOrigin::UserTable {
                                    user_sgpr,
                                    byte_offset: 0,
                                } => (
                                    SgprOrigin::RightShiftedPtr {
                                        def_inst_idx: inst_idx,
                                        user_sgpr,
                                        table_byte_offset: None,
                                        shift: sh,
                                    },
                                    SgprOrigin::Unknown,
                                ),
                                _ => (SgprOrigin::Unknown, SgprOrigin::Unknown),
                            }
                        } else {
                            (SgprOrigin::Unknown, SgprOrigin::Unknown)
                        }
                    }
                    _ => (SgprOrigin::Unknown, SgprOrigin::Unknown),
                };
                state.set_sgpr_origin(*sdst, new_lo);
                if let Some(hi_reg) = checked_tracked_sgpr_reg(*sdst, 1) {
                    state.set_sgpr_origin(hi_reg, new_hi);
                    clear_pending_xor_if(state, hi_reg);
                }
                clear_pending_xor_if(state, *sdst);
                state.pending_xor_pair = next_pending_xor_pair;
                if *op != 0x0B {
                    state.last_carry_lo_reg = None;
                }
            } else if *sdst <= MAX_TRACKED_SGPR {
                let src0_origin = state.sgpr_origin(*ssrc0);
                let src1_origin = state.sgpr_origin(*ssrc1);
                let c0 = resolve_const_u32(*ssrc0, *literal, &state.origins);
                let c1 = resolve_const_u32(*ssrc1, *literal, &state.origins);
                let mut next_origin = SgprOrigin::Unknown;
                let mut next_pending_xor = state.pending_xor;
                if let Some((r, _, _)) = next_pending_xor
                    && r == *sdst
                {
                    next_pending_xor = None;
                }
                let prev_carry_lo = state.last_carry_lo_reg;
                let next_carry_lo = match *op {
                    0x00..=0x03 | 0x2E..=0x31 if *sdst <= MAX_TRACKED_SGPR_PAIR => Some(*sdst),
                    0x0A | 0x26 | 0x32..=0x36 => prev_carry_lo,
                    _ => None,
                };
                match *op {
                    // s_add_u32 / s_add_i32: constant fold, table pointer + offset,
                    // heap base + scaled index, index doubling (`idx + idx`), high-word carry
                    // propagation (`s_add_u32 s_hi, s_hi, src_scc`), or dynamic VA base offset
                    // preserving `PatchedDescWord` strictly for V#/T# recovery.
                    0x00 | 0x02 => {
                        if let (Some(v0), Some(v1)) = (c0, c1) {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: Some(v0.wrapping_add(v1)),
                            };
                        } else if is_const_src(*ssrc0, &state.origins)
                            && is_const_src(*ssrc1, &state.origins)
                        {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: None,
                            };
                        } else if let Some(imm) = c1 {
                            next_origin = apply_const_offset(src0_origin, imm as i32);
                        } else if let Some(imm) = c0 {
                            next_origin = apply_const_offset(src1_origin, imm as i32);
                        } else if *ssrc1 == 253
                            && is_valid_carry_hi(*sdst, src0_origin, prev_carry_lo)
                        {
                            next_origin = src0_origin;
                        } else if *ssrc0 == 253
                            && is_valid_carry_hi(*sdst, src1_origin, prev_carry_lo)
                        {
                            next_origin = src1_origin;
                        } else if let Some(combined) = combine_add_origins(src0_origin, src1_origin)
                        {
                            next_origin = combined;
                        } else if let Some((def_inst_idx, base)) =
                            patched_desc_word_of(src0_origin)
                                .or_else(|| patched_desc_word_of(src1_origin))
                        {
                            next_origin = SgprOrigin::PatchedDescWord { def_inst_idx, base };
                        } else if let SgprOrigin::UserTable { user_sgpr, .. } = src0_origin {
                            next_origin = SgprOrigin::PatchedDescWord {
                                def_inst_idx: inst_idx,
                                base: PatchedDescBase::RootDescriptor { user_sgpr },
                            };
                        } else if let SgprOrigin::UserTable { user_sgpr, .. } = src1_origin {
                            next_origin = SgprOrigin::PatchedDescWord {
                                def_inst_idx: inst_idx,
                                base: PatchedDescBase::RootDescriptor { user_sgpr },
                            };
                        }
                    }
                    // s_sub_u32 / s_sub_i32: constant fold, self-sub zero, table pointer - offset,
                    // or dynamic VA base offset preserving `PatchedDescWord`.
                    0x01 | 0x03 => {
                        if let (Some(v0), Some(v1)) = (c0, c1) {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: Some(v0.wrapping_sub(v1)),
                            };
                        } else if is_const_src(*ssrc0, &state.origins)
                            && is_const_src(*ssrc1, &state.origins)
                        {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: None,
                            };
                        } else if *ssrc0 == *ssrc1 && *ssrc0 <= MAX_TRACKED_SGPR {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: Some(0),
                            };
                        } else if let Some(imm) = c1 {
                            next_origin = apply_const_offset(src0_origin, (imm as i32).wrapping_neg());
                        } else if *ssrc1 == 253
                            && is_valid_carry_hi(*sdst, src0_origin, prev_carry_lo)
                        {
                            next_origin = src0_origin;
                        } else if let Some((def_inst_idx, base)) =
                            patched_desc_word_of(src0_origin)
                        {
                            next_origin = SgprOrigin::PatchedDescWord { def_inst_idx, base };
                        } else if let SgprOrigin::UserTable { user_sgpr, .. } = src0_origin {
                            next_origin = SgprOrigin::PatchedDescWord {
                                def_inst_idx: inst_idx,
                                base: PatchedDescBase::RootDescriptor { user_sgpr },
                            };
                        }
                    }
                    // s_addc_u32: 64-bit pointer high-word carry propagation (`s_hi + 0/-1/hi + SCC`)
                    // or constant-with-carry (value stays `None` because SCC is dynamic).
                    0x04 => {
                        if is_const_src(*ssrc0, &state.origins)
                            && is_const_src(*ssrc1, &state.origins)
                        {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: None,
                            };
                        } else if matches!(c1, Some(0) | Some(u32::MAX))
                            && is_valid_carry_hi(*sdst, src0_origin, prev_carry_lo)
                        {
                            next_origin = src0_origin;
                        } else if matches!(c0, Some(0) | Some(u32::MAX))
                            && is_valid_carry_hi(*sdst, src1_origin, prev_carry_lo)
                        {
                            next_origin = src1_origin;
                        } else if is_valid_carry_hi(*sdst, src0_origin, prev_carry_lo) {
                            if let Some((def_inst_idx, base)) = patched_desc_word_of(src0_origin) {
                                next_origin = SgprOrigin::PatchedDescWord { def_inst_idx, base };
                            } else if let SgprOrigin::UserTable { user_sgpr, .. } = src0_origin {
                                next_origin = SgprOrigin::PatchedDescWord {
                                    def_inst_idx: inst_idx,
                                    base: PatchedDescBase::RootDescriptor { user_sgpr },
                                };
                            }
                        } else if is_valid_carry_hi(*sdst, src1_origin, prev_carry_lo) {
                            if let Some((def_inst_idx, base)) = patched_desc_word_of(src1_origin) {
                                next_origin = SgprOrigin::PatchedDescWord { def_inst_idx, base };
                            } else if let SgprOrigin::UserTable { user_sgpr, .. } = src1_origin {
                                next_origin = SgprOrigin::PatchedDescWord {
                                    def_inst_idx: inst_idx,
                                    base: PatchedDescBase::RootDescriptor { user_sgpr },
                                };
                            }
                        }
                    }
                    // s_subb_u32: 64-bit pointer high-word borrow propagation (`s_hi - 0/hi - SCC`)
                    // or constant-with-borrow.
                    0x05 => {
                        if is_const_src(*ssrc0, &state.origins)
                            && is_const_src(*ssrc1, &state.origins)
                        {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: None,
                            };
                        } else if c1 == Some(0)
                            && is_valid_carry_hi(*sdst, src0_origin, prev_carry_lo)
                        {
                            next_origin = src0_origin;
                        } else if is_valid_carry_hi(*sdst, src0_origin, prev_carry_lo) {
                            if let Some((def_inst_idx, base)) = patched_desc_word_of(src0_origin) {
                                next_origin = SgprOrigin::PatchedDescWord { def_inst_idx, base };
                            } else if let SgprOrigin::UserTable { user_sgpr, .. } = src0_origin {
                                next_origin = SgprOrigin::PatchedDescWord {
                                    def_inst_idx: inst_idx,
                                    base: PatchedDescBase::RootDescriptor { user_sgpr },
                                };
                            }
                        }
                    }
                    // s_min_i32 / s_min_u32 / s_max_i32 / s_max_u32
                    0x06..=0x09 => {
                        if let (Some(v0), Some(v1)) = (c0, c1) {
                            let folded = match *op {
                                0x06 => (v0 as i32).min(v1 as i32) as u32,
                                0x07 => v0.min(v1),
                                0x08 => (v0 as i32).max(v1 as i32) as u32,
                                _ => v0.max(v1),
                            };
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: Some(folded),
                            };
                        } else if *ssrc0 == *ssrc1 && *ssrc0 <= MAX_TRACKED_SGPR {
                            next_origin = normalize_read_origin(src0_origin);
                        } else if matches!(*op, 0x06 | 0x07) {
                            let signed = *op == 0x06;
                            if let Some(lim) = c1 {
                                next_origin = apply_min_const(src0_origin, lim, signed);
                            } else if let Some(lim) = c0 {
                                next_origin = apply_min_const(src1_origin, lim, signed);
                            }
                        } else if matches!(*op, 0x08 | 0x09) {
                            if c1 == Some(0) && matches!(src0_origin, SgprOrigin::LaneIndex { .. }) {
                                next_origin = src0_origin;
                            } else if c0 == Some(0)
                                && matches!(src1_origin, SgprOrigin::LaneIndex { .. })
                            {
                                next_origin = src1_origin;
                            }
                        }
                    }
                    // s_cselect_b32
                    0x0A => {
                        let s0 = resolve_src_origin_u8(*ssrc0, *literal, inst_idx, &state.origins);
                        let s1 = resolve_src_origin_u8(*ssrc1, *literal, inst_idx, &state.origins);
                        let (da, dda) = match collector.as_deref_mut() {
                            Some(c) => (Some(&mut c.def_aliases), Some(&mut c.divergent_def_aliases)),
                            None => (None, None),
                        };
                        next_origin = merge_select_origin(s0, s1, inst_idx, da, dda);
                    }
                    // s_and_b32
                    0x0E => {
                        if let (Some(v0), Some(v1)) = (c0, c1) {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: Some(v0 & v1),
                            };
                        } else if *ssrc0 == *ssrc1 && *ssrc0 <= MAX_TRACKED_SGPR {
                            next_origin = normalize_read_origin(src0_origin);
                        } else if let Some(m) = c1 {
                            next_origin = apply_and_const(src0_origin, m, inst_idx);
                        } else if let Some(m) = c0 {
                            next_origin = apply_and_const(src1_origin, m, inst_idx);
                        } else if is_const_src(*ssrc0, &state.origins)
                            && is_const_src(*ssrc1, &state.origins)
                        {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: None,
                            };
                        }
                    }
                    // s_andn2_b32: `ssrc0 & !ssrc1` (e.g. `s_andn2_b32 s12, s8, 3` == `s8 & ~3`).
                    0x14 => {
                        if let (Some(v0), Some(v1)) = (c0, c1) {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: Some(v0 & !v1),
                            };
                        } else if let Some(m) = c1 {
                            next_origin = apply_and_const(src0_origin, !m, inst_idx);
                        } else if is_const_src(*ssrc0, &state.origins)
                            && is_const_src(*ssrc1, &state.origins)
                        {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: None,
                            };
                        }
                    }
                    // s_or_b32: constant fold, self-OR copy, or `or disjoint` table-offset addition.
                    0x10 => {
                        if let (Some(v0), Some(v1)) = (c0, c1) {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: Some(v0 | v1),
                            };
                        } else if *ssrc0 == *ssrc1 && *ssrc0 <= MAX_TRACKED_SGPR {
                            next_origin = normalize_read_origin(src0_origin);
                        } else if let Some(imm) = c1 {
                            next_origin = apply_or_const(src0_origin, imm, inst_idx);
                        } else if let Some(imm) = c0 {
                            next_origin = apply_or_const(src1_origin, imm, inst_idx);
                        } else if is_const_src(*ssrc0, &state.origins)
                            && is_const_src(*ssrc1, &state.origins)
                        {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: None,
                            };
                        }
                    }
                    // Other bitwise ops on constants (inline static sampler construction).
                    0x12 | 0x16 | 0x18 | 0x1A | 0x1C => {
                        if let (Some(v0), Some(v1)) = (c0, c1) {
                            let folded = match *op {
                                0x12 => v0 ^ v1,
                                0x16 => v0 | !v1,
                                0x18 => !(v0 & v1),
                                0x1A => !(v0 | v1),
                                _ => !(v0 ^ v1),
                            };
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: Some(folded),
                            };
                        } else if *op == 0x12 && *ssrc0 == *ssrc1 && *ssrc0 <= MAX_TRACKED_SGPR {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: Some(0),
                            };
                        } else if *op == 0x12
                            && *ssrc0 <= MAX_TRACKED_SGPR
                            && *ssrc1 <= MAX_TRACKED_SGPR
                            && *ssrc0 != *ssrc1
                        {
                            // Recognize 3-XOR in-place register swap (`a ^= b; b ^= a; a ^= b`),
                            // used by the console shader compiler to reorder 64-bit root descriptor
                            // SGPR pairs (e.g. `s13 = s11; xor s13,s13,s12; xor s12,s13,s12; xor s13,s13,s12`).
                            if let Some((xr, oa, ob)) = state.pending_xor {
                                let other_orig = if *ssrc0 == xr {
                                    Some(src1_origin)
                                } else if *ssrc1 == xr {
                                    Some(src0_origin)
                                } else {
                                    None
                                };
                                if let Some(oo) = other_orig {
                                    if oo == ob {
                                        next_origin = oa;
                                    } else if oo == oa {
                                        next_origin = ob;
                                    }
                                }
                            } else if (*sdst == *ssrc0 || *sdst == *ssrc1)
                                && (is_swappable_origin(src0_origin)
                                    || is_swappable_origin(src1_origin))
                            {
                                next_pending_xor = Some((*sdst, src0_origin, src1_origin));
                            }
                        } else if is_const_src(*ssrc0, &state.origins)
                            && is_const_src(*ssrc1, &state.origins)
                        {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: None,
                            };
                        }
                    }
                    // s_lshl_b32: constant fold or scale user SGPR index by `1 << shift`.
                    0x1E => {
                        if let (Some(v0), Some(v1)) = (c0, c1) {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: Some(v0.wrapping_shl(v1 & 31)),
                            };
                        } else if is_const_src(*ssrc0, &state.origins)
                            && is_const_src(*ssrc1, &state.origins)
                        {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: None,
                            };
                        } else if let Some(raw_shift) = c1 {
                            let sh = raw_shift & 31;
                            next_origin = scale_user_sgpr_by_shift(src0_origin, sh);
                            if sh == 2
                                && matches!(next_origin, SgprOrigin::Unknown)
                                && *ssrc0 <= MAX_TRACKED_SGPR
                                && state.sgpr_bound(*ssrc0) > 0
                            {
                                next_origin = SgprOrigin::BoundedByteOffset {
                                    idx_sgpr: *ssrc0,
                                    base_byte_offset: 0,
                                    max_elems: state.sgpr_bound(*ssrc0),
                                };
                            }
                        }
                    }
                    // s_lshr_b32: constant fold or bit-extract shift on CBV/root-constant index
                    0x20 => {
                        if let (Some(v0), Some(v1)) = (c0, c1) {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: Some(v0.wrapping_shr(v1 & 31)),
                            };
                        } else if is_const_src(*ssrc0, &state.origins)
                            && is_const_src(*ssrc1, &state.origins)
                        {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: None,
                            };
                        } else if let Some(raw_sh) = c1 {
                            next_origin = apply_lshr_const(src0_origin, raw_sh & 31, inst_idx);
                        }
                    }
                    0x22 => {
                        if let (Some(v0), Some(v1)) = (c0, c1) {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: Some(((v0 as i32).wrapping_shr(v1 & 31)) as u32),
                            };
                        } else if is_const_src(*ssrc0, &state.origins)
                            && is_const_src(*ssrc1, &state.origins)
                        {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: None,
                            };
                        }
                    }
                    // s_bfm_b32 with constant operands (common in inline static sampler S#).
                    0x24 if is_const_src(*ssrc0, &state.origins)
                        && is_const_src(*ssrc1, &state.origins) =>
                    {
                        let folded = c0.zip(c1).map(|(w, o)| {
                            let width = w & 31;
                            let off = o & 31;
                            let mask = if width == 0 {
                                0u32
                            } else {
                                (1u32 << width).wrapping_sub(1)
                            };
                            mask.wrapping_shl(off)
                        });
                        next_origin = SgprOrigin::ConstImmediate {
                            def_inst_idx: inst_idx,
                            value: folded,
                        };
                    }
                    // s_mul_i32: constant fold or scale user SGPR index by constant stride.
                    0x26 => {
                        if let (Some(v0), Some(v1)) = (c0, c1) {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: Some(v0.wrapping_mul(v1)),
                            };
                        } else if is_const_src(*ssrc0, &state.origins)
                            && is_const_src(*ssrc1, &state.origins)
                        {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: None,
                            };
                        } else if let Some(imm) = c1 {
                            next_origin = scale_user_sgpr_by_mul(src0_origin, imm as i32);
                        } else if let Some(imm) = c0 {
                            next_origin = scale_user_sgpr_by_mul(src1_origin, imm as i32);
                        }
                    }
                    // s_lshl{1,2,3,4}_add_u32: `(ssrc0 << k) + ssrc1`.
                    // Covers both SM 6.6 heap addressing (`(idx << k) + base`), shift-add stride
                    // scaling (`(idx << k) + idx`), and compact table-offset adds (`(imm << k) + base`,
                    // e.g. `s_lshl4_add_u32 s12, 6, s8` for `s8 + 96` or `8, s8` for `s8 + 128`).
                    0x2E..=0x31 => {
                        let shift = u32::from(*op - 0x2D);
                        if let (Some(v0), Some(v1)) = (c0, c1) {
                            next_origin = SgprOrigin::ConstImmediate {
                                def_inst_idx: inst_idx,
                                value: Some(v0.wrapping_shl(shift).wrapping_add(v1)),
                            };
                        } else if let Some(v0) = c0 {
                            let delta = (v0 as i32).wrapping_shl(shift);
                            next_origin = apply_const_offset(src1_origin, delta);
                        } else {
                            let scaled = scale_user_sgpr_by_shift(src0_origin, shift);
                            if let SgprOrigin::ScaledLaneIndex(h) = scaled
                                && *ssrc0 == *ssrc1
                                && *ssrc0 <= MAX_TRACKED_SGPR
                                && matches!(src0_origin, SgprOrigin::LaneIndex { .. })
                            {
                                let stride = (1u32 << shift).saturating_add(1);
                                next_origin = SgprOrigin::ScaledLaneIndex(LaneIndexedHeapSource {
                                    shift: 0,
                                    stride,
                                    ..h
                                });
                            } else if c1 == Some(0)
                                && matches!(
                                    scaled,
                                    SgprOrigin::ScaledUserSgpr { .. }
                                        | SgprOrigin::ScaledCbvDword(_)
                                        | SgprOrigin::ScaledLaneIndex(_)
                                )
                            {
                                next_origin = scaled;
                            } else if let Some(combined) = combine_add_origins(scaled, src1_origin)
                            {
                                next_origin = combined;
                            } else if shift == 2
                                && *ssrc0 <= MAX_TRACKED_SGPR
                                && state.sgpr_bound(*ssrc0) > 0
                                && let Some(base) = c1
                                && base % 4 == 0
                            {
                                next_origin = SgprOrigin::BoundedByteOffset {
                                    idx_sgpr: *ssrc0,
                                    base_byte_offset: base,
                                    max_elems: state.sgpr_bound(*ssrc0),
                                };
                            }
                        }
                    }
                    // s_bfe_u32 on CBV / root-constant heap index (packed bitfields, #1383).
                    0x27 if !is_const_src(*ssrc0, &state.origins) && c1.is_some() => {
                        if let Some(param) = c1 {
                            next_origin = apply_bfe_u32_const(src0_origin, param, inst_idx);
                        }
                    }
                    // Bitfield extract / pack / absdiff / mul_hi on constants (inline S# sampler).
                    0x27 | 0x28 | 0x2C | 0x32..=0x36
                        if is_const_src(*ssrc0, &state.origins)
                            && is_const_src(*ssrc1, &state.origins) =>
                    {
                        let folded = c0.zip(c1).map(|(v0, v1)| match *op {
                            0x27 => {
                                // s_bfe_u32: offset = s1[4:0], width = s1[22:16]
                                let off = v1 & 31;
                                let width = (v1 >> 16) & 0x7F;
                                if width == 0 {
                                    0
                                } else if width >= 32 {
                                    v0.wrapping_shr(off)
                                } else {
                                    v0.wrapping_shr(off) & ((1u32 << width) - 1)
                                }
                            }
                            0x28 => {
                                // s_bfe_i32: signed bitfield extract
                                let off = v1 & 31;
                                let width = (v1 >> 16) & 0x7F;
                                if width == 0 {
                                    0
                                } else if width >= 32 {
                                    ((v0 as i32).wrapping_shr(off)) as u32
                                } else {
                                    let sh = 32 - width;
                                    let ext = v0.wrapping_shr(off);
                                    (((ext.wrapping_shl(sh)) as i32).wrapping_shr(sh)) as u32
                                }
                            }
                            0x2C => {
                                // s_absdiff_i32
                                (v0 as i32).wrapping_sub(v1 as i32).wrapping_abs() as u32
                            }
                            0x32 => {
                                // s_pack_ll_b32_b16: (v0[15:0]) | (v1[15:0] << 16)
                                (v0 & 0x0000_FFFF) | ((v1 & 0x0000_FFFF) << 16)
                            }
                            0x33 => {
                                // s_pack_lh_b32_b16: (v0[15:0]) | (v1[31:16] << 16)
                                (v0 & 0x0000_FFFF) | (v1 & 0xFFFF_0000)
                            }
                            0x34 => {
                                // s_pack_hh_b32_b16: (v0[31:16]) | (v1[31:16] << 16)
                                (v0 >> 16) | (v1 & 0xFFFF_0000)
                            }
                            0x35 => {
                                // s_mul_hi_u32
                                ((u64::from(v0) * u64::from(v1)) >> 32) as u32
                            }
                            _ => {
                                // 0x36: s_mul_hi_i32
                                ((i64::from(v0 as i32) * i64::from(v1 as i32)) >> 32) as u32
                            }
                        });
                        next_origin = SgprOrigin::ConstImmediate {
                            def_inst_idx: inst_idx,
                            value: folded,
                        };
                    }
                    // Non-constant `s_pack_ll/lh/hh_b32_b16` with a zero upper half:
                    //   s_pack_ll_b32_b16 dst, src, 0  == src & 0xFFFF
                    //   s_pack_lh_b32_b16 dst, src, 0  == src & 0xFFFF  (when src1[31:16] == 0)
                    //   s_pack_hh_b32_b16 dst, src, 0  == src >> 16     (when src1[31:16] == 0)
                    0x32 if c1.is_some_and(|v| (v & 0x0000_FFFF) == 0) => {
                        next_origin = apply_and_const(src0_origin, 0x0000_FFFF, inst_idx);
                    }
                    0x33 if c1.is_some_and(|v| (v & 0xFFFF_0000) == 0) => {
                        next_origin = apply_and_const(src0_origin, 0x0000_FFFF, inst_idx);
                    }
                    0x34 if c1.is_some_and(|v| (v & 0xFFFF_0000) == 0) => {
                        next_origin = apply_lshr_const(src0_origin, 16, inst_idx);
                    }
                    _ => {}
                }
                state.set_sgpr_origin(*sdst, next_origin);
                clear_pending_xor_if(state, *sdst);
                state.pending_xor = next_pending_xor;
                state.last_carry_lo_reg = next_carry_lo;
            } else {
                if !matches!(*op, 0x0A | 0x0B | 0x26 | 0x32..=0x36) {
                    state.last_carry_lo_reg = None;
                }
            }
        }
        Rdna2Detail::Smem {
            op,
            sdata,
            sbase,
            soffset,
            offset,
            ..
        } => {
            let const_soffset: Option<i32> = if *soffset == 0x7D {
                Some(0)
            } else if let Some(v) = decode_inline_u32_src(u16::from(*soffset), None) {
                Some(v)
            } else if *soffset <= MAX_TRACKED_SGPR
                && let SgprOrigin::ConstImmediate { value: Some(v), .. } =
                    state.sgpr_origin(*soffset)
            {
                Some(v as i32)
            } else {
                None
            };
            let is_dynamic = const_soffset.is_none();
            let sbase_sgpr = checked_descriptor_sgpr(*sbase, 2);

            // Snapshot base & dynamic-offset origins BEFORE overwriting sdata (since sdata can
            // alias sbase_sgpr and/or soffset, e.g. `s_load_dwordx4 s[8:11], s[8:9], s10`).
            let raw_base_w0 = sbase_sgpr.map_or(SgprOrigin::Unknown, |sgpr| state.sgpr_origin(sgpr));
            let base_origin = match sbase_sgpr {
                Some(sgpr) if matches!(*op, 0x08..=0x0C) => {
                    resolve_vsharp_origin(&state.origins, sgpr)
                }
                Some(_) => raw_base_w0,
                None => SgprOrigin::Unknown,
            };
            let base_hi_is_const = sbase_sgpr
                .and_then(|sgpr| checked_tracked_sgpr_reg(sgpr, 1))
                .is_some_and(|hi_reg| {
                    matches!(state.sgpr_origin(hi_reg), SgprOrigin::ConstImmediate { .. })
                });
            let soffset_origin = if is_dynamic {
                state.sgpr_origin(*soffset)
            } else {
                SgprOrigin::Unknown
            };

            if matches!(*op, 0x08..=0x0C) {
                // s_buffer_load_* consuming a V# in s[sbase_sgpr .. sbase_sgpr+3]
                if is_dynamic {
                    taint_sgpr_if_loaded(&mut collector, &state.origins, u16::from(*soffset));
                }
                if let Some(col) = collector.as_deref_mut() {
                    match base_origin {
                        SgprOrigin::TableDesc {
                            def_inst_idx,
                            user_sgpr,
                            table_byte_offset,
                            ..
                        } => {
                            let key = CbvKey {
                                base_sbase: 0,
                                user_sgpr: Some(user_sgpr),
                                table_offset: Some(table_byte_offset as i32),
                                dynamic_heap: None,
                                cbv_indexed_heap: None,
                                lane_indexed_heap: None,
                            };
                            col.buffer_load_uses.push(BufferLoadUse {
                                inst_idx,
                                def_inst_idx,
                                cbv_key: Some(key),
                                source: Some(WgslBindingSource::Table {
                                    user_sgpr,
                                    table_byte_offset,
                                }),
                            });
                        }
                        SgprOrigin::DynamicHeapDesc {
                            def_inst_idx,
                            origin: heap,
                        } => {
                            let key = CbvKey {
                                base_sbase: 0,
                                user_sgpr: None,
                                table_offset: None,
                                dynamic_heap: Some(heap),
                                cbv_indexed_heap: None,
                                lane_indexed_heap: None,
                            };
                            col.buffer_load_uses.push(BufferLoadUse {
                                inst_idx,
                                def_inst_idx,
                                cbv_key: Some(key),
                                source: Some(WgslBindingSource::ResourceHeap {
                                    base_user_sgpr: heap.base_user_sgpr,
                                    stride: heap.stride,
                                    index_user_sgpr: heap.index_user_sgpr,
                                    index_shift: heap.index_shift,
                                }),
                            });
                        }
                        SgprOrigin::CbvIndexedHeapDesc {
                            def_inst_idx,
                            origin: heap,
                        } => {
                            let key = CbvKey {
                                base_sbase: 0,
                                user_sgpr: None,
                                table_offset: None,
                                dynamic_heap: None,
                                cbv_indexed_heap: Some(heap),
                                lane_indexed_heap: None,
                            };
                            col.buffer_load_uses.push(BufferLoadUse {
                                inst_idx,
                                def_inst_idx,
                                cbv_key: Some(key),
                                source: Some(WgslBindingSource::CbvIndexedResourceHeap(heap)),
                            });
                        }
                        SgprOrigin::LaneIndexedHeapDesc {
                            def_inst_idx,
                            origin: heap,
                        } => {
                            let key = CbvKey {
                                base_sbase: 0,
                                user_sgpr: None,
                                table_offset: None,
                                dynamic_heap: None,
                                cbv_indexed_heap: None,
                                lane_indexed_heap: Some(heap),
                            };
                            col.buffer_load_uses.push(BufferLoadUse {
                                inst_idx,
                                def_inst_idx,
                                cbv_key: Some(key),
                                source: Some(WgslBindingSource::LaneIndexedResourceHeap(heap)),
                            });
                        }
                        SgprOrigin::RawTableDesc {
                            def_inst_idx,
                            table_sbase,
                            table_offset,
                            is_dynamic: raw_dyn,
                        } => {
                            let cbv_key = if raw_dyn {
                                None
                            } else {
                                Some(CbvKey {
                                    base_sbase: table_sbase,
                                    user_sgpr: None,
                                    table_offset: Some(table_offset),
                                    dynamic_heap: None,
                                    cbv_indexed_heap: None,
                                    lane_indexed_heap: None,
                                })
                            };
                            col.buffer_load_uses.push(BufferLoadUse {
                                inst_idx,
                                def_inst_idx,
                                cbv_key,
                                source: None,
                            });
                        }
                        SgprOrigin::TableDescChoice { def_insts, .. } => {
                            col.raw_descriptor_defs.insert(def_insts[0]);
                            col.raw_descriptor_defs.insert(def_insts[1]);
                        }
                        SgprOrigin::BoundedCbvIndexedHeapDesc { def_inst_idx, .. } => {
                            col.direct_descriptor_defs.insert(def_inst_idx);
                        }
                        SgprOrigin::DivergentDesc { def_inst_idx } => {
                            col.divergent_descriptor_defs.insert(def_inst_idx);
                        }
                        SgprOrigin::UserTable {
                            user_sgpr,
                            byte_offset,
                        } => {
                            col.direct_root_cbvs.push(DirectRootCbvLoad {
                                inst_idx,
                                user_sgpr,
                                is_32bit_table_ptr: base_hi_is_const,
                                const_byte_offset: None,
                                ptr_byte_offset: byte_offset,
                                load_dwords: 0,
                            });
                        }
                        _ => {}
                    }
                }
                if let Some(count) = smem_load_dword_count(*op) {
                    // Track loaded CBV dwords for SM 6.6 CB-indexed descriptor heaps (#1383).
                    let resolved_cbv_base = match base_origin {
                        SgprOrigin::TableDesc {
                            user_sgpr,
                            table_byte_offset,
                            addr_offset: 0,
                            ..
                        } if table_byte_offset % 32 == 0 => Some((
                            CbvRefSource::Table {
                                user_sgpr,
                                table_byte_offset,
                            },
                            0i32,
                        )),
                        SgprOrigin::UserTable {
                            user_sgpr,
                            byte_offset,
                        } if !matches!(raw_base_w0, SgprOrigin::PatchedDescWord { .. }) => {
                            Some((CbvRefSource::RootDescriptor { user_sgpr }, byte_offset))
                        }
                        _ => None,
                    };
                    let loaded_cbv = if let Some(s_off) = const_soffset {
                        let raw_off = offset.saturating_add(s_off);
                        resolved_cbv_base.map(|(cbv, base_off)| (cbv, base_off.saturating_add(raw_off)))
                    } else {
                        None
                    };
                    let bounded_cbv = if loaded_cbv.is_none()
                        && count == 1
                        && let Some((cbv, base_off)) = resolved_cbv_base
                        && let SgprOrigin::BoundedByteOffset {
                            idx_sgpr,
                            base_byte_offset,
                            max_elems,
                        } = soffset_origin
                    {
                        let eff_base = base_off.saturating_add(*offset);
                        if eff_base >= 0 && eff_base % 4 == 0 {
                            base_byte_offset.checked_add(eff_base as u32).map(|total_base| {
                                SgprOrigin::BoundedCbvDword {
                                    load_inst_idx: inst_idx,
                                    idx_sgpr,
                                    cbv,
                                    base_byte_offset: total_base,
                                    max_elems,
                                }
                            })
                        } else {
                            None
                        }
                    } else {
                        None
                    };
                    for k in 0..count {
                        if let Some(reg) = checked_tracked_sgpr_reg(*sdata, k) {
                            let next_orig = if let Some((cbv, base_off)) = loaded_cbv {
                                let eff = base_off.saturating_add(i32::from(k) * 4);
                                if eff >= 0 && eff % 4 == 0 {
                                    SgprOrigin::CbvDword {
                                        cbv,
                                        byte_offset: eff as u32,
                                        bit_offset: 0,
                                        mask: u32::MAX,
                                    }
                                } else {
                                    SgprOrigin::Unknown
                                }
                            } else if let Some(b_orig) = bounded_cbv {
                                b_orig
                            } else {
                                SgprOrigin::Unknown
                            };
                            state.set_sgpr_origin(reg, next_orig);
                            clear_pending_xor_if(state, reg);
                        }
                    }
                }
            } else if let Some(count) = smem_load_dword_count(*op) {
                // s_load_dword / x2 / x4 / x8 / x16
                let dynamic_heap_from_soffset = if is_dynamic {
                    match (base_origin, soffset_origin) {
                        (
                            SgprOrigin::UserTable {
                                user_sgpr: base_user_sgpr,
                                byte_offset: 0,
                            },
                            SgprOrigin::ScaledUserSgpr {
                                user_sgpr: index_user_sgpr,
                                stride,
                                shift: index_shift,
                            },
                        ) => Some(DynamicHeapOrigin {
                            base_user_sgpr,
                            stride,
                            index_user_sgpr,
                            index_shift,
                        }),
                        (
                            SgprOrigin::UserTable {
                                user_sgpr: base_user_sgpr,
                                byte_offset: 0,
                            },
                            SgprOrigin::UserTable {
                                user_sgpr: index_user_sgpr,
                                byte_offset: 0,
                            },
                        ) => Some(DynamicHeapOrigin {
                            base_user_sgpr,
                            stride: 1,
                            index_user_sgpr,
                            index_shift: 0,
                        }),
                        _ => None,
                    }
                } else {
                    None
                };
                let cbv_heap_from_soffset = if is_dynamic
                    && dynamic_heap_from_soffset.is_none()
                    && *offset == 0
                    && !matches!(base_origin, SgprOrigin::VbTablePtr { .. })
                {
                    match soffset_origin {
                        SgprOrigin::ScaledCbvDword(h) => Some(h),
                        SgprOrigin::ScaledUserSgpr {
                            user_sgpr,
                            stride,
                            shift,
                        } if shift > 0
                            && stride == (1u32 << shift)
                            && (matches!(base_origin, SgprOrigin::TableDesc { .. })
                                || shift >= 4) =>
                        {
                            Some(CbvIndexedHeapSource {
                                cbv: CbvRefSource::RootConstants { user_sgpr },
                                byte_offset: 0,
                                shift,
                                bit_offset: 0,
                                mask: u32::MAX,
                                stride,
                            })
                        }
                        SgprOrigin::CbvDword {
                            cbv,
                            byte_offset,
                            bit_offset,
                            mask,
                        } if matches!(base_origin, SgprOrigin::UserTable { byte_offset: 0, .. }) => {
                            Some(CbvIndexedHeapSource {
                                cbv,
                                byte_offset,
                                shift: 0,
                                bit_offset,
                                mask,
                                stride: 0,
                            })
                        }
                        SgprOrigin::TableDesc {
                            cbv_dword: Some((cbv, byte_offset)),
                            addr_offset: 0,
                            ..
                        } if matches!(base_origin, SgprOrigin::UserTable { byte_offset: 0, .. }) => {
                            Some(CbvIndexedHeapSource {
                                cbv,
                                byte_offset,
                                shift: 0,
                                bit_offset: 0,
                                mask: u32::MAX,
                                stride: 0,
                            })
                        }
                        _ => None,
                    }
                } else {
                    None
                };
                let lane_heap_from_soffset = if is_dynamic
                    && dynamic_heap_from_soffset.is_none()
                    && cbv_heap_from_soffset.is_none()
                    && *offset == 0
                    && !matches!(base_origin, SgprOrigin::VbTablePtr { .. })
                {
                    match soffset_origin {
                        SgprOrigin::ScaledLaneIndex(h) => Some(h),
                        SgprOrigin::LaneIndex {
                            max_count,
                            window_base,
                        } if matches!(base_origin, SgprOrigin::UserTable { byte_offset: 0, .. }) => {
                            Some(LaneIndexedHeapSource {
                                max_count: finalize_lane_max_count(max_count),
                                shift: 0,
                                stride: 0,
                                window_base,
                            })
                        }
                        _ => None,
                    }
                } else {
                    None
                };
                if is_dynamic
                    && dynamic_heap_from_soffset.is_none()
                    && cbv_heap_from_soffset.is_none()
                    && lane_heap_from_soffset.is_none()
                {
                    taint_sgpr_if_loaded(&mut collector, &state.origins, u16::from(*soffset));
                }

                if let Some(col) = collector.as_deref_mut() {
                    match base_origin {
                        SgprOrigin::UserTable {
                            user_sgpr,
                            byte_offset,
                        } => {
                            col.direct_root_cbvs.push(DirectRootCbvLoad {
                                inst_idx,
                                user_sgpr,
                                is_32bit_table_ptr: base_hi_is_const,
                                const_byte_offset: const_soffset
                                    .map(|s_off| byte_offset.saturating_add(offset.saturating_add(s_off))),
                                ptr_byte_offset: byte_offset,
                                load_dwords: count,
                            });
                        }
                        SgprOrigin::TableDesc {
                            def_inst_idx: ptr_def,
                            user_sgpr,
                            table_byte_offset,
                            ..
                        } => {
                            col.def_parents.insert(inst_idx, ptr_def);
                            let key = CbvKey {
                                base_sbase: 0,
                                user_sgpr: Some(user_sgpr),
                                table_offset: Some(table_byte_offset as i32),
                                dynamic_heap: None,
                                cbv_indexed_heap: None,
                                lane_indexed_heap: None,
                            };
                            col.cbv_ptr_loads.push(CbvPtrLoad {
                                inst_idx,
                                ptr_def,
                                cbv_key: key,
                                source: WgslBindingSource::Table {
                                    user_sgpr,
                                    table_byte_offset,
                                },
                            });
                        }
                        SgprOrigin::DynamicHeapDesc {
                            def_inst_idx: ptr_def,
                            origin: heap,
                        } => {
                            col.def_parents.insert(inst_idx, ptr_def);
                            let key = CbvKey {
                                base_sbase: 0,
                                user_sgpr: None,
                                table_offset: None,
                                dynamic_heap: Some(heap),
                                cbv_indexed_heap: None,
                                lane_indexed_heap: None,
                            };
                            col.cbv_ptr_loads.push(CbvPtrLoad {
                                inst_idx,
                                ptr_def,
                                cbv_key: key,
                                source: WgslBindingSource::ResourceHeap {
                                    base_user_sgpr: heap.base_user_sgpr,
                                    stride: heap.stride,
                                    index_user_sgpr: heap.index_user_sgpr,
                                    index_shift: heap.index_shift,
                                },
                            });
                        }
                        SgprOrigin::CbvIndexedHeapDesc {
                            def_inst_idx: ptr_def,
                            origin: heap,
                        } => {
                            col.def_parents.insert(inst_idx, ptr_def);
                            let key = CbvKey {
                                base_sbase: 0,
                                user_sgpr: None,
                                table_offset: None,
                                dynamic_heap: None,
                                cbv_indexed_heap: Some(heap),
                                lane_indexed_heap: None,
                            };
                            col.cbv_ptr_loads.push(CbvPtrLoad {
                                inst_idx,
                                ptr_def,
                                cbv_key: key,
                                source: WgslBindingSource::CbvIndexedResourceHeap(heap),
                            });
                        }
                        SgprOrigin::LaneIndexedHeapDesc {
                            def_inst_idx: ptr_def,
                            origin: heap,
                        } => {
                            col.def_parents.insert(inst_idx, ptr_def);
                            let key = CbvKey {
                                base_sbase: 0,
                                user_sgpr: None,
                                table_offset: None,
                                dynamic_heap: None,
                                cbv_indexed_heap: None,
                                lane_indexed_heap: Some(heap),
                            };
                            col.cbv_ptr_loads.push(CbvPtrLoad {
                                inst_idx,
                                ptr_def,
                                cbv_key: key,
                                source: WgslBindingSource::LaneIndexedResourceHeap(heap),
                            });
                        }
                        SgprOrigin::RawTableDesc {
                            def_inst_idx: ptr_def,
                            ..
                        }
                        | SgprOrigin::DivergentDesc {
                            def_inst_idx: ptr_def,
                        } => {
                            col.def_parents.insert(inst_idx, ptr_def);
                        }
                        SgprOrigin::TableDescChoice { def_insts, .. } => {
                            let rep = def_insts[0].min(def_insts[1]);
                            record_def_alias(
                                Some(&mut col.divergent_def_aliases),
                                def_insts[0],
                                def_insts[1],
                            );
                            col.def_parents.insert(inst_idx, rep);
                        }
                        _ => {}
                    }
                }

                // Clear destination origins before populating derived descriptor/pointer origins.
                for k in 0..count {
                    if let Some(reg) = checked_tracked_sgpr_reg(*sdata, k) {
                        state.set_sgpr_origin(reg, SgprOrigin::Unknown);
                        clear_pending_xor_if(state, reg);
                    }
                }

                // Track descriptor & nested-table-pointer loads (`s_load_dword` / `x2` / `x4` /
                // `x8` / `x16`), including SM 6.6 dynamic & CB-indexed heap fetches, 2-level table
                // chains, and descriptors spanning `s104..=vcc_hi` (`s[104:107]`, `s[100:107]`).
                if *sdata <= MAX_TRACKED_SGPR {
                    if let Some(s_off) = const_soffset {
                        let raw_off = offset.saturating_add(s_off);
                        match base_origin {
                            SgprOrigin::DynamicHeapPtr(heap)
                            | SgprOrigin::DynamicHeapDesc { origin: heap, .. } => {
                                for k in 0..count {
                                    if let Some(reg) = checked_tracked_sgpr_reg(*sdata, k) {
                                        state.set_sgpr_origin(
                                            reg,
                                            SgprOrigin::DynamicHeapDesc {
                                                def_inst_idx: inst_idx,
                                                origin: heap,
                                            },
                                        );
                                    }
                                }
                            }
                            SgprOrigin::CbvIndexedHeapPtr(heap) if raw_off == 0 => {
                                for k in 0..count {
                                    if let Some(reg) = checked_tracked_sgpr_reg(*sdata, k) {
                                        state.set_sgpr_origin(
                                            reg,
                                            SgprOrigin::CbvIndexedHeapDesc {
                                                def_inst_idx: inst_idx,
                                                origin: heap,
                                            },
                                        );
                                    }
                                }
                            }
                            SgprOrigin::CbvIndexedHeapDesc { origin: heap, .. } => {
                                for k in 0..count {
                                    if let Some(reg) = checked_tracked_sgpr_reg(*sdata, k) {
                                        state.set_sgpr_origin(
                                            reg,
                                            SgprOrigin::CbvIndexedHeapDesc {
                                                def_inst_idx: inst_idx,
                                                origin: heap,
                                            },
                                        );
                                    }
                                }
                            }
                            SgprOrigin::LaneIndexedHeapPtr(heap) if raw_off == 0 => {
                                for k in 0..count {
                                    if let Some(reg) = checked_tracked_sgpr_reg(*sdata, k) {
                                        state.set_sgpr_origin(
                                            reg,
                                            SgprOrigin::LaneIndexedHeapDesc {
                                                def_inst_idx: inst_idx,
                                                origin: heap,
                                            },
                                        );
                                    }
                                }
                            }
                            SgprOrigin::LaneIndex {
                                max_count,
                                window_base:
                                    Some(CbvDwordSource {
                                        cbv: CbvRefSource::RootConstants { .. },
                                        byte_offset: 0,
                                        bit_offset: 0,
                                        mask: u32::MAX,
                                    }),
                            } if raw_off == 0 => {
                                let heap = LaneIndexedHeapSource {
                                    max_count: finalize_lane_max_count(max_count),
                                    shift: 0,
                                    stride: 0,
                                    window_base: None,
                                };
                                for k in 0..count {
                                    if let Some(reg) = checked_tracked_sgpr_reg(*sdata, k) {
                                        state.set_sgpr_origin(
                                            reg,
                                            SgprOrigin::LaneIndexedHeapDesc {
                                                def_inst_idx: inst_idx,
                                                origin: heap,
                                            },
                                        );
                                    }
                                }
                            }
                            SgprOrigin::LaneIndexedHeapDesc { origin: heap, .. } => {
                                for k in 0..count {
                                    if let Some(reg) = checked_tracked_sgpr_reg(*sdata, k) {
                                        state.set_sgpr_origin(
                                            reg,
                                            SgprOrigin::LaneIndexedHeapDesc {
                                                def_inst_idx: inst_idx,
                                                origin: heap,
                                            },
                                        );
                                    }
                                }
                            }
                            SgprOrigin::VbTablePtr { byte_offset } => {
                                let eff = byte_offset.saturating_add(raw_off);
                                for k in 0..count {
                                    if let Some(reg) = checked_tracked_sgpr_reg(*sdata, k) {
                                        let vb_slot = (eff.saturating_add(i32::from(k) * 4)).max(0)
                                            as u32
                                            / 16;
                                        state.set_sgpr_origin(
                                            reg,
                                            SgprOrigin::VbDesc {
                                                def_inst_idx: inst_idx,
                                                vb_slot,
                                            },
                                        );
                                    }
                                }
                            }
                            SgprOrigin::UserTable {
                                user_sgpr,
                                byte_offset,
                            } => {
                                let eff = byte_offset.saturating_add(raw_off);
                                for k in 0..count {
                                    if let Some(reg) = checked_tracked_sgpr_reg(*sdata, k) {
                                        let eff_k = eff.saturating_add(i32::from(k) * 4);
                                        let byte_off = eff_k.max(0) as u32;
                                        let cbv_dword = if eff_k >= 0 && eff_k % 4 == 0 {
                                            Some((
                                                CbvRefSource::RootDescriptor { user_sgpr },
                                                eff_k as u32,
                                            ))
                                        } else {
                                            None
                                        };
                                        state.set_sgpr_origin(
                                            reg,
                                            SgprOrigin::TableDesc {
                                                def_inst_idx: inst_idx,
                                                user_sgpr,
                                                table_byte_offset: byte_off,
                                                addr_offset: 0,
                                                cbv_dword,
                                            },
                                        );
                                    }
                                }
                            }
                            SgprOrigin::TableDesc {
                                user_sgpr,
                                table_byte_offset,
                                addr_offset,
                                ..
                            } => {
                                // 2-level nested descriptor-table load: accumulate outer table
                                // offset + pointer SALU offset + inner SMEM offset, and also record
                                // the `(Table(user_sgpr, outer_off), inner_off)` CBV dword identity
                                // for SM 6.6 CB-indexed descriptor heaps (#1383).
                                let eff = (table_byte_offset as i32)
                                    .saturating_add(addr_offset)
                                    .saturating_add(raw_off);
                                let inner_base = addr_offset.saturating_add(raw_off);
                                for k in 0..count {
                                    if let Some(reg) = checked_tracked_sgpr_reg(*sdata, k) {
                                        let byte_off =
                                            (eff.saturating_add(i32::from(k) * 4)).max(0) as u32;
                                        let inner_k = inner_base.saturating_add(i32::from(k) * 4);
                                        let cbv_dword = if table_byte_offset % 32 == 0
                                            && inner_k >= 0
                                            && inner_k % 4 == 0
                                        {
                                            Some((
                                                CbvRefSource::Table {
                                                    user_sgpr,
                                                    table_byte_offset,
                                                },
                                                inner_k as u32,
                                            ))
                                        } else {
                                            None
                                        };
                                        state.set_sgpr_origin(
                                            reg,
                                            SgprOrigin::TableDesc {
                                                def_inst_idx: inst_idx,
                                                user_sgpr,
                                                table_byte_offset: byte_off,
                                                addr_offset: 0,
                                                cbv_dword,
                                            },
                                        );
                                    }
                                }
                            }
                            SgprOrigin::DivergentDesc { .. }
                            | SgprOrigin::TableDescChoice { .. } => {
                                if matches!(*op, 0x02 | 0x03 | 0x04) && (*sdata % 2 == 0) {
                                    for k in 0..count {
                                        if let Some(reg) = checked_tracked_sgpr_reg(*sdata, k) {
                                            state.set_sgpr_origin(
                                                reg,
                                                SgprOrigin::DivergentDesc {
                                                    def_inst_idx: inst_idx,
                                                },
                                            );
                                        }
                                    }
                                }
                            }
                            _ => {
                                if matches!(*op, 0x02 | 0x03 | 0x04) && (*sdata % 2 == 0) {
                                    for k in 0..count {
                                        if let Some(reg) = checked_tracked_sgpr_reg(*sdata, k) {
                                            state.set_sgpr_origin(
                                                reg,
                                                SgprOrigin::RawTableDesc {
                                                    def_inst_idx: inst_idx,
                                                    table_sbase: *sbase,
                                                    table_offset: raw_off
                                                        .saturating_add(i32::from(k) * 4),
                                                    is_dynamic: false,
                                                },
                                            );
                                        }
                                    }
                                }
                            }
                        }
                    } else if let Some(heap) = dynamic_heap_from_soffset {
                        for k in 0..count {
                            if let Some(reg) = checked_tracked_sgpr_reg(*sdata, k) {
                                state.set_sgpr_origin(
                                    reg,
                                    SgprOrigin::DynamicHeapDesc {
                                        def_inst_idx: inst_idx,
                                        origin: heap,
                                    },
                                );
                            }
                        }
                    } else if let Some(heap) = cbv_heap_from_soffset {
                        for k in 0..count {
                            if let Some(reg) = checked_tracked_sgpr_reg(*sdata, k) {
                                state.set_sgpr_origin(
                                    reg,
                                    SgprOrigin::CbvIndexedHeapDesc {
                                        def_inst_idx: inst_idx,
                                        origin: heap,
                                    },
                                );
                            }
                        }
                    } else if let Some(heap) = lane_heap_from_soffset {
                        for k in 0..count {
                            if let Some(reg) = checked_tracked_sgpr_reg(*sdata, k) {
                                state.set_sgpr_origin(
                                    reg,
                                    SgprOrigin::LaneIndexedHeapDesc {
                                        def_inst_idx: inst_idx,
                                        origin: heap,
                                    },
                                );
                            }
                        }
                    } else if matches!(*op, 0x02 | 0x03)
                        && *offset == 0
                        && matches!(base_origin, SgprOrigin::UserTable { byte_offset: 0, .. })
                        && let SgprOrigin::BoundedScaledCbvDword {
                            load_inst_idx,
                            idx_sgpr,
                            cbv,
                            base_byte_offset,
                            max_elems,
                            shift,
                        } = soffset_origin
                    {
                        for k in 0..count {
                            if let Some(reg) = checked_tracked_sgpr_reg(*sdata, k) {
                                state.set_sgpr_origin(
                                    reg,
                                    SgprOrigin::BoundedCbvIndexedHeapDesc {
                                        def_inst_idx: inst_idx,
                                        load_inst_idx,
                                        idx_sgpr,
                                        cbv,
                                        base_byte_offset,
                                        max_elems,
                                        shift,
                                    },
                                );
                            }
                        }
                    } else if matches!(*op, 0x02 | 0x03 | 0x04) && (*sdata % 2 == 0) {
                        for k in 0..count {
                            if let Some(reg) = checked_tracked_sgpr_reg(*sdata, k) {
                                state.set_sgpr_origin(
                                    reg,
                                    SgprOrigin::RawTableDesc {
                                        def_inst_idx: inst_idx,
                                        table_sbase: *sbase,
                                        table_offset: 0,
                                        is_dynamic: true,
                                    },
                                );
                            }
                        }
                    }
                }
            }
        }
        Rdna2Detail::Vop1 {
            op,
            vdst,
            src0,
            literal,
        } => {
            if !matches!(op, 0x00 | 0x1B | 0x41) {
                match *op {
                    0x01 => {
                        // v_mov_b32: preserve uniform SGPR/VGPR origin (e.g. uniform SGPR spill).
                        if *src0 <= u16::from(MAX_TRACKED_SGPR) {
                            clear_vgpr_origins(state, *vdst);
                            let s0 = state.sgpr_origin(*src0 as u8);
                            state.set_vgpr_origin(*vdst, s0);
                        } else if (256..=511).contains(src0) {
                            copy_vgpr_origins(state, *vdst, (*src0 - 256) as u8);
                        } else if let Some(v) = decode_inline_u32_src(*src0, *literal) {
                            clear_vgpr_origins(state, *vdst);
                            state.set_vgpr_origin(
                                *vdst,
                                SgprOrigin::ConstImmediate {
                                    def_inst_idx: inst_idx,
                                    value: Some(v as u32),
                                },
                            );
                        } else if let Some(bits) = decode_inline_float_u32(*src0) {
                            clear_vgpr_origins(state, *vdst);
                            state.set_vgpr_origin(
                                *vdst,
                                SgprOrigin::ConstImmediate {
                                    def_inst_idx: inst_idx,
                                    value: Some(bits),
                                },
                            );
                        } else {
                            clear_vgpr_origins(state, *vdst);
                        }
                    }
                    0x02 => {
                        // v_readfirstlane_b32 sdst, src0: restore lane 0 / uniform VGPR spill, or
                        // tag a genuine per-lane VGPR as a `LaneIndex` candidate (#482 / #1394).
                        let sd = *vdst & 0x7F;
                        if sd <= MAX_TRACKED_SGPR {
                            let restored = resolve_readfirstlane_origin(state, *src0);
                            state.set_sgpr_origin(sd, restored);
                            clear_pending_xor_if(state, sd);
                        }
                    }
                    0x65 => {
                        // v_swap_b32 vdst, vsrc0: preserve & swap both uniform and per-lane origins.
                        if (256..=511).contains(src0) {
                            swap_vgpr_origins(state, *vdst, (*src0 - 256) as u8);
                        } else {
                            clear_vgpr_origins(state, *vdst);
                        }
                    }
                    _ => {
                        taint_sgpr_if_loaded(&mut collector, &state.origins, *src0);
                        clear_vgpr_origins(state, *vdst);
                    }
                }
            }
        }
        Rdna2Detail::Vopc {
            op,
            vsrc1,
            src0,
            literal,
        } => {
            if !is_waterfall_desc_cmp(state, u16::from(*op), *src0, 256 + u16::from(*vsrc1)) {
                taint_sgpr_if_loaded(&mut collector, &state.origins, *src0);
            }
            if (*op & 0x10) == 0 {
                // GFX10.3 `VOP_SDWAB` (`src0 == 0xF9`, `w1[15] == 1`) writes `sdst = w1[14:8]`
                // instead of `vcc`; standard VOPC writes `vcc` (`106` in Wave32, `106..=107` Wave64).
                let dst = vopc_sdwab_sdst(*op, *src0, *literal).unwrap_or(106);
                if dst <= MAX_TRACKED_SGPR {
                    state.set_sgpr_origin(dst, SgprOrigin::Unknown);
                    clear_pending_xor_if(state, dst);
                    if !is_wave32
                        && dst <= MAX_TRACKED_SGPR_PAIR
                        && dst % 2 == 0
                        && let Some(hi) = checked_tracked_sgpr_reg(dst, 1)
                    {
                        state.set_sgpr_origin(hi, SgprOrigin::Unknown);
                        clear_pending_xor_if(state, hi);
                    }
                }
            }
        }
        Rdna2Detail::Vop2 {
            op,
            vdst,
            vsrc1,
            src0,
            literal,
        } => {
            taint_sgpr_if_loaded(&mut collector, &state.origins, *src0);
            let next_lane_origin = eval_valu_lane_origin_vop2_like(
                state,
                *op,
                *src0,
                256 + u16::from(*vsrc1),
                *literal,
                inst_idx,
            );
            clear_vgpr_origins(state, *vdst);
            if let Some(orig) = next_lane_origin {
                state.set_vgpr_origin(*vdst, orig);
            }
            if vop2_is_co_ci(*op) {
                state.set_sgpr_origin(106, SgprOrigin::Unknown);
                clear_pending_xor_if(state, 106);
                if !is_wave32 {
                    state.set_sgpr_origin(107, SgprOrigin::Unknown);
                    clear_pending_xor_if(state, 107);
                }
            }
        }
        Rdna2Detail::Vop3 {
            op,
            vdst,
            sdst,
            src0,
            src1,
            src2,
            literal,
            ..
        } => {
            let is_interp_f16 = vop3_is_interp_f16(*op);
            let is_spill_or_move = matches!(*op, 0x181 | 0x182 | 0x1E5 | 0x360 | 0x361);
            let is_waterfall_cmp = is_waterfall_desc_cmp(state, *op, *src0, *src1);
            if !is_interp_f16 && !is_spill_or_move && !is_waterfall_cmp {
                taint_sgpr_if_loaded(&mut collector, &state.origins, *src0);
            }
            let is_unary = (0x180..=0x1FF).contains(op);
            if !is_unary && !is_spill_or_move && !is_waterfall_cmp {
                taint_sgpr_if_loaded(&mut collector, &state.origins, *src1);
            }
            if matches!(*op, 0x2FF..=0x301) && *src1 <= u16::from(MAX_TRACKED_SGPR_PAIR) {
                taint_sgpr_if_loaded(&mut collector, &state.origins, *src1 + 1);
            }
            if *op == 0x364 {
                if *src0 <= u16::from(MAX_TRACKED_SGPR_PAIR) {
                    taint_sgpr_if_loaded(&mut collector, &state.origins, *src0 + 1);
                }
                if *src1 <= u16::from(MAX_TRACKED_SGPR_PAIR) {
                    taint_sgpr_if_loaded(&mut collector, &state.origins, *src1 + 1);
                }
            }
            let is_ternary = *op != 0x342
                && matches!(
                    *op,
                    0x100
                        | 0x101
                        | 0x128..=0x12A
                        | 0x140..=0x165
                        | 0x16D..=0x171
                        | 0x178
                        | 0x340..=0x35F
                        | 0x36D..=0x372
                        | 0x377
                        | 0x378
                );
            if is_ternary {
                taint_sgpr_if_loaded(&mut collector, &state.origins, *src2);
            }
            if let Some(sd) = sdst {
                let sd7 = *sd & 0x7F;
                if sd7 <= MAX_TRACKED_SGPR {
                    state.set_sgpr_origin(sd7, SgprOrigin::Unknown);
                    clear_pending_xor_if(state, sd7);
                    if !is_wave32
                        && sd7 % 2 == 0
                        && let Some(hi) = checked_tracked_sgpr_reg(sd7, 1)
                    {
                        state.set_sgpr_origin(hi, SgprOrigin::Unknown);
                        clear_pending_xor_if(state, hi);
                    }
                }
            }
            if *op <= 0xFF {
                if (*op & 0x10) == 0 {
                    let sd = *vdst & 0x7F;
                    if sd <= MAX_TRACKED_SGPR {
                        state.set_sgpr_origin(sd, SgprOrigin::Unknown);
                        clear_pending_xor_if(state, sd);
                        if !is_wave32
                            && sd % 2 == 0
                            && let Some(hi) = checked_tracked_sgpr_reg(sd, 1)
                        {
                            state.set_sgpr_origin(hi, SgprOrigin::Unknown);
                            clear_pending_xor_if(state, hi);
                        }
                    }
                }
            } else if *op == 0x181 {
                // v_mov_b32_e64
                if *src0 <= u16::from(MAX_TRACKED_SGPR) {
                    clear_vgpr_origins(state, *vdst);
                    let s0 = state.sgpr_origin(*src0 as u8);
                    state.set_vgpr_origin(*vdst, s0);
                } else if (256..=511).contains(src0) {
                    copy_vgpr_origins(state, *vdst, (*src0 - 256) as u8);
                } else if let Some(v) = decode_inline_u32_src(*src0, *literal) {
                    clear_vgpr_origins(state, *vdst);
                    state.set_vgpr_origin(
                        *vdst,
                        SgprOrigin::ConstImmediate {
                            def_inst_idx: inst_idx,
                            value: Some(v as u32),
                        },
                    );
                } else if let Some(bits) = decode_inline_float_u32(*src0) {
                    clear_vgpr_origins(state, *vdst);
                    state.set_vgpr_origin(
                        *vdst,
                        SgprOrigin::ConstImmediate {
                            def_inst_idx: inst_idx,
                            value: Some(bits),
                        },
                    );
                } else {
                    clear_vgpr_origins(state, *vdst);
                }
            } else if *op == 0x182 {
                // v_readfirstlane_b32_e64
                let sd = *vdst & 0x7F;
                if sd <= MAX_TRACKED_SGPR {
                    let restored = resolve_readfirstlane_origin(state, *src0);
                    state.set_sgpr_origin(sd, restored);
                    clear_pending_xor_if(state, sd);
                }
            } else if *op == 0x1E5 {
                // v_swap_b32_e64
                if (256..=511).contains(src0) {
                    swap_vgpr_origins(state, *vdst, (*src0 - 256) as u8);
                } else {
                    clear_vgpr_origins(state, *vdst);
                }
            } else if *op == 0x361 {
                // v_writelane_b32 vdst, ssrc0, lane: preserve spilled SGPR origin per (vgpr, lane)
                if let Some(lane) = resolve_const_lane_index(*src1, *literal, &state.origins) {
                    let val_origin = if *src0 <= u16::from(MAX_TRACKED_SGPR) {
                        state.sgpr_origin(*src0 as u8)
                    } else if let Some(v) = decode_inline_u32_src(*src0, *literal) {
                        SgprOrigin::ConstImmediate {
                            def_inst_idx: inst_idx,
                            value: Some(v as u32),
                        }
                    } else if let Some(bits) = decode_inline_float_u32(*src0) {
                        SgprOrigin::ConstImmediate {
                            def_inst_idx: inst_idx,
                            value: Some(bits),
                        }
                    } else if *src0 >= 128 && *src0 < 256 {
                        SgprOrigin::ConstImmediate {
                            def_inst_idx: inst_idx,
                            value: None,
                        }
                    } else {
                        SgprOrigin::Unknown
                    };
                    state.set_vgpr_origin(*vdst, SgprOrigin::Unknown);
                    state.lane_origins.insert((*vdst, lane), val_origin);
                } else {
                    clear_vgpr_origins(state, *vdst);
                }
            } else if *op == 0x360 {
                // v_readlane_b32 sdst, vsrc0, lane: restore spilled SGPR origin from (vsrc0, lane)
                // or from uniform VGPR spill.
                let sd = *vdst & 0x7F;
                if sd <= MAX_TRACKED_SGPR {
                    let restored = if (256..=511).contains(src0) {
                        let vsrc = (*src0 - 256) as u8;
                        let raw = if let Some(lane) =
                            resolve_const_lane_index(*src1, *literal, &state.origins)
                        {
                            state
                                .lane_origins
                                .get(&(vsrc, lane))
                                .copied()
                                .unwrap_or_else(|| state.vgpr_origin(vsrc))
                        } else {
                            state.vgpr_origin(vsrc)
                        };
                        normalize_read_origin(raw)
                    } else {
                        SgprOrigin::Unknown
                    };
                    state.set_sgpr_origin(sd, restored);
                    clear_pending_xor_if(state, sd);
                }
            } else {
                let next_lane_origin = eval_valu_lane_origin_vop3(
                    state, *op, *src0, *src1, *src2, *literal, inst_idx,
                );
                clear_vgpr_origins(state, *vdst);
                if let Some(orig) = next_lane_origin {
                    state.set_vgpr_origin(*vdst, orig);
                }
                if (matches!(*op, 0x2FF..=0x301) || *op == 0x364)
                    && let Some(hi_v) = checked_vgpr_reg(*vdst, 1)
                {
                    clear_vgpr_origins(state, hi_v);
                }
            }
        }
        Rdna2Detail::Vop3P {
            op,
            vdst,
            src0,
            src1,
            src2,
            ..
        } => {
            taint_sgpr_if_loaded(&mut collector, &state.origins, *src0);
            taint_sgpr_if_loaded(&mut collector, &state.origins, *src1);
            if vop3p_is_ternary(*op) {
                taint_sgpr_if_loaded(&mut collector, &state.origins, *src2);
            }
            clear_vgpr_origins(state, *vdst);
        }
        Rdna2Detail::Mimg {
            op,
            r128,
            srsrc,
            ssamp,
            vdata,
            dmask,
            d16,
            ..
        } => {
            if let Some(layout) = mimg_addr_layout(*op) {
                if !layout.is_store {
                    let eff_mask = if *dmask == 0 { 0xF } else { *dmask };
                    let comp_cnt = if layout.is_gather4 {
                        4
                    } else {
                        eff_mask.count_ones()
                    };
                    let out_cnt = if *d16 { comp_cnt.div_ceil(2) } else { comp_cnt } as u8;
                    for d in 0..out_cnt {
                        if let Some(reg) = checked_vgpr_reg(*vdata, d) {
                            clear_vgpr_origins(state, reg);
                        }
                    }
                }
                if let Some(col) = collector.as_deref_mut() {
                    let tsharp_origin = checked_descriptor_sgpr(*srsrc, 4)
                        .map_or(SgprOrigin::Unknown, |rsrc_sgpr| {
                            resolve_tsharp_origin(&state.origins, rsrc_sgpr, *r128)
                        });
                    match tsharp_origin {
                        SgprOrigin::TableDesc {
                            def_inst_idx,
                            user_sgpr,
                            table_byte_offset,
                            ..
                        } => {
                            col.direct_descriptor_defs.insert(def_inst_idx);
                            let key = ResourceKey::Table {
                                user_sgpr,
                                table_byte_offset,
                            };
                            if layout.is_store {
                                col.out.inst_storage_tex_keys.insert(inst_idx, key);
                            } else if !layout.is_get_lod {
                                col.out.inst_tex_keys.insert(inst_idx, key);
                            }
                        }
                        SgprOrigin::DynamicHeapDesc {
                            def_inst_idx,
                            origin,
                        } => {
                            col.direct_descriptor_defs.insert(def_inst_idx);
                            let key = ResourceKey::ResourceHeap {
                                base_user_sgpr: origin.base_user_sgpr,
                                stride: origin.stride,
                                index_user_sgpr: origin.index_user_sgpr,
                                index_shift: origin.index_shift,
                            };
                            if layout.is_store {
                                col.out.inst_storage_tex_keys.insert(inst_idx, key);
                            } else if !layout.is_get_lod {
                                col.out.inst_tex_keys.insert(inst_idx, key);
                            }
                        }
                        SgprOrigin::CbvIndexedHeapDesc {
                            def_inst_idx,
                            origin,
                        } => {
                            col.direct_descriptor_defs.insert(def_inst_idx);
                            let key = ResourceKey::CbvIndexedResourceHeap(origin);
                            if layout.is_store {
                                col.out.inst_storage_tex_keys.insert(inst_idx, key);
                            } else if !layout.is_get_lod {
                                col.out.inst_tex_keys.insert(inst_idx, key);
                            }
                        }
                        SgprOrigin::LaneIndexedHeapDesc {
                            def_inst_idx,
                            origin,
                        } => {
                            col.direct_descriptor_defs.insert(def_inst_idx);
                            let key = ResourceKey::LaneIndexedResourceHeap(origin);
                            if layout.is_store {
                                col.out.inst_storage_tex_keys.insert(inst_idx, key);
                            } else if !layout.is_get_lod {
                                col.out.inst_tex_keys.insert(inst_idx, key);
                            }
                        }
                        SgprOrigin::TableDescChoice {
                            user_sgpr,
                            offsets,
                            def_insts,
                        } if layout.is_store => {
                            let choice_id = col.alloc_two_way_choice(user_sgpr, offsets, def_insts);
                            let keys = [
                                ResourceKey::Table {
                                    user_sgpr,
                                    table_byte_offset: offsets[0],
                                },
                                ResourceKey::Table {
                                    user_sgpr,
                                    table_byte_offset: offsets[1],
                                },
                            ];
                            col.out.inst_storage_tex_dispatches.insert(
                                inst_idx,
                                StorageDispatch::TwoWayChoice { choice_id, keys },
                            );
                        }
                        SgprOrigin::BoundedCbvIndexedHeapDesc {
                            def_inst_idx,
                            load_inst_idx,
                            idx_sgpr,
                            cbv,
                            base_byte_offset,
                            max_elems,
                            shift,
                        } if layout.is_store
                            && (1..=MAX_BOUNDED_CBV_HEAP_ELEMS).contains(&max_elems)
                            && shift < 32 =>
                        {
                            col.direct_descriptor_defs.insert(def_inst_idx);
                            let choice_id = col.alloc_bounded_choice(load_inst_idx, idx_sgpr);
                            let stride = 1u32 << shift;
                            let mut keys = Vec::with_capacity(usize::from(max_elems));
                            for k in 0..u32::from(max_elems) {
                                keys.push(ResourceKey::CbvIndexedResourceHeap(
                                    CbvIndexedHeapSource {
                                        cbv,
                                        byte_offset: base_byte_offset.saturating_add(k * 4),
                                        shift: u32::from(shift),
                                        bit_offset: 0,
                                        mask: u32::MAX,
                                        stride,
                                    },
                                ));
                            }
                            col.out.inst_storage_tex_dispatches.insert(
                                inst_idx,
                                StorageDispatch::BoundedIndexed { choice_id, keys },
                            );
                        }
                        SgprOrigin::TableDescChoice { def_insts, .. } => {
                            col.raw_descriptor_defs.insert(def_insts[0]);
                            col.raw_descriptor_defs.insert(def_insts[1]);
                        }
                        SgprOrigin::BoundedCbvIndexedHeapDesc { def_inst_idx, .. } => {
                            col.direct_descriptor_defs.insert(def_inst_idx);
                        }
                        SgprOrigin::DivergentDesc { def_inst_idx } => {
                            col.divergent_descriptor_defs.insert(def_inst_idx);
                        }
                        SgprOrigin::RawTableDesc {
                            def_inst_idx,
                            is_dynamic: true,
                            ..
                        } => {
                            col.raw_descriptor_defs.insert(def_inst_idx);
                        }
                        _ => {}
                    }
                    if !layout.is_load && !layout.is_store {
                        let samp_sgpr_opt = checked_descriptor_sgpr(*ssamp, 4);
                        let samp_origin = samp_sgpr_opt.map_or(SgprOrigin::Unknown, |samp_sgpr| {
                            resolve_vsharp_origin(&state.origins, samp_sgpr)
                        });
                        match samp_origin {
                            SgprOrigin::TableDesc {
                                def_inst_idx,
                                user_sgpr,
                                table_byte_offset,
                                ..
                            } => {
                                col.direct_descriptor_defs.insert(def_inst_idx);
                                if !layout.is_get_lod {
                                    col.out.inst_samp_keys.insert(
                                        inst_idx,
                                        ResourceKey::Table {
                                            user_sgpr,
                                            table_byte_offset,
                                        },
                                    );
                                }
                            }
                            SgprOrigin::DynamicHeapDesc {
                                def_inst_idx,
                                origin,
                            } => {
                                col.direct_descriptor_defs.insert(def_inst_idx);
                                if !layout.is_get_lod {
                                    col.out.inst_samp_keys.insert(
                                        inst_idx,
                                        ResourceKey::SamplerHeap {
                                            base_user_sgpr: origin.base_user_sgpr,
                                            stride: origin.stride,
                                            index_user_sgpr: origin.index_user_sgpr,
                                            index_shift: origin.index_shift,
                                        },
                                    );
                                }
                            }
                            SgprOrigin::CbvIndexedHeapDesc {
                                def_inst_idx,
                                origin,
                            } => {
                                col.direct_descriptor_defs.insert(def_inst_idx);
                                if !layout.is_get_lod {
                                    col.out.inst_samp_keys.insert(
                                        inst_idx,
                                        ResourceKey::CbvIndexedSamplerHeap(origin),
                                    );
                                }
                            }
                            SgprOrigin::LaneIndexedHeapDesc {
                                def_inst_idx,
                                origin,
                            } => {
                                col.direct_descriptor_defs.insert(def_inst_idx);
                                if !layout.is_get_lod {
                                    col.out.inst_samp_keys.insert(
                                        inst_idx,
                                        ResourceKey::LaneIndexedSamplerHeap(origin),
                                    );
                                }
                            }
                            SgprOrigin::TableDescChoice { def_insts, .. } => {
                                col.raw_descriptor_defs.insert(def_insts[0]);
                                col.raw_descriptor_defs.insert(def_insts[1]);
                            }
                            SgprOrigin::BoundedCbvIndexedHeapDesc { def_inst_idx, .. } => {
                                col.direct_descriptor_defs.insert(def_inst_idx);
                            }
                            SgprOrigin::DivergentDesc { def_inst_idx } => {
                                col.divergent_descriptor_defs.insert(def_inst_idx);
                            }
                            SgprOrigin::ConstImmediate { def_inst_idx, .. } => {
                                if !layout.is_get_lod {
                                    let key = if let Some(sdwords) = samp_sgpr_opt.and_then(|s| {
                                        resolve_inline_sampler_sdwords(&state.origins, s)
                                    }) {
                                        ResourceKey::InlineSampler(sdwords)
                                    } else {
                                        let idx = *col
                                            .static_sampler_by_def
                                            .entry(def_inst_idx)
                                            .or_insert_with(|| {
                                                let i = col.next_static_sampler_index;
                                                col.next_static_sampler_index += 1;
                                                i
                                            });
                                        ResourceKey::StaticSampler(idx)
                                    };
                                    col.out.inst_samp_keys.insert(inst_idx, key);
                                }
                            }
                            SgprOrigin::RawTableDesc {
                                def_inst_idx,
                                is_dynamic: true,
                                ..
                            } => {
                                col.raw_descriptor_defs.insert(def_inst_idx);
                            }
                            _ => {}
                        }
                    }
                }
            }
        }
        Rdna2Detail::Mubuf {
            op,
            idxen,
            glc,
            srsrc,
            soffset,
            vdata,
            ..
        } => {
            taint_sgpr_if_loaded(&mut collector, &state.origins, u16::from(*soffset));
            if let Some(buf_op) = mubuf_storage_op(*op)
                && !buf_op.is_store()
            {
                for d in 0..buf_op.vdata_count() {
                    if let Some(reg) = checked_vgpr_reg(*vdata, d) {
                        clear_vgpr_origins(state, reg);
                    }
                }
            } else if mubuf_is_atomic(*op) && *glc {
                clear_vgpr_origins(state, *vdata);
            }
            if let Some(col) = collector.as_deref_mut() {
                let rsrc_sgpr_opt = checked_descriptor_sgpr(*srsrc, 4);
                let origin = rsrc_sgpr_opt.map_or(SgprOrigin::Unknown, |rsrc_sgpr| {
                    resolve_vsharp_origin(&state.origins, rsrc_sgpr)
                });
                match origin {
                    SgprOrigin::VbDesc {
                        def_inst_idx,
                        vb_slot,
                    } if stage == ShaderStage::Vertex && mubuf_load_components(*op).is_some() => {
                        col.direct_descriptor_defs.insert(def_inst_idx);
                        col.out.vertex_fetch_vb_slots.insert(inst_idx, vb_slot);
                    }
                    SgprOrigin::TableDesc {
                        def_inst_idx,
                        user_sgpr,
                        table_byte_offset,
                        ..
                    } => {
                        col.direct_descriptor_defs.insert(def_inst_idx);
                        col.out.inst_storage_buf_keys.insert(
                            inst_idx,
                            ResourceKey::Table {
                                user_sgpr,
                                table_byte_offset,
                            },
                        );
                        if stage == ShaderStage::Vertex && mubuf_storage_op(*op).is_some() {
                            col.out.vertex_storage_buf_insts.insert(inst_idx);
                        }
                    }
                    SgprOrigin::DynamicHeapDesc {
                        def_inst_idx,
                        origin,
                    } => {
                        col.direct_descriptor_defs.insert(def_inst_idx);
                        col.out.inst_storage_buf_keys.insert(
                            inst_idx,
                            ResourceKey::ResourceHeap {
                                base_user_sgpr: origin.base_user_sgpr,
                                stride: origin.stride,
                                index_user_sgpr: origin.index_user_sgpr,
                                index_shift: origin.index_shift,
                            },
                        );
                        if stage == ShaderStage::Vertex && mubuf_storage_op(*op).is_some() {
                            col.out.vertex_storage_buf_insts.insert(inst_idx);
                        }
                    }
                    SgprOrigin::CbvIndexedHeapDesc {
                        def_inst_idx,
                        origin,
                    } => {
                        col.direct_descriptor_defs.insert(def_inst_idx);
                        col.out.inst_storage_buf_keys.insert(
                            inst_idx,
                            ResourceKey::CbvIndexedResourceHeap(origin),
                        );
                        if stage == ShaderStage::Vertex && mubuf_storage_op(*op).is_some() {
                            col.out.vertex_storage_buf_insts.insert(inst_idx);
                        }
                    }
                    SgprOrigin::LaneIndexedHeapDesc {
                        def_inst_idx,
                        origin,
                    } => {
                        col.direct_descriptor_defs.insert(def_inst_idx);
                        col.out.inst_storage_buf_keys.insert(
                            inst_idx,
                            ResourceKey::LaneIndexedResourceHeap(origin),
                        );
                        if stage == ShaderStage::Vertex && mubuf_storage_op(*op).is_some() {
                            col.out.vertex_storage_buf_insts.insert(inst_idx);
                        }
                    }
                    SgprOrigin::TableDescChoice {
                        user_sgpr,
                        offsets,
                        def_insts,
                    } if stage != ShaderStage::Vertex
                        && (mubuf_storage_op(*op).is_some_and(StorageBufOpKind::is_store)
                            || mubuf_is_atomic(*op)) =>
                    {
                        let choice_id = col.alloc_two_way_choice(user_sgpr, offsets, def_insts);
                        let keys = [
                            ResourceKey::Table {
                                user_sgpr,
                                table_byte_offset: offsets[0],
                            },
                            ResourceKey::Table {
                                user_sgpr,
                                table_byte_offset: offsets[1],
                            },
                        ];
                        col.out.inst_storage_buf_dispatches.insert(
                            inst_idx,
                            StorageDispatch::TwoWayChoice { choice_id, keys },
                        );
                    }
                    SgprOrigin::TableDescChoice { def_insts, .. } => {
                        col.raw_descriptor_defs.insert(def_insts[0]);
                        col.raw_descriptor_defs.insert(def_insts[1]);
                    }
                    SgprOrigin::BoundedCbvIndexedHeapDesc { def_inst_idx, .. } => {
                        col.direct_descriptor_defs.insert(def_inst_idx);
                    }
                    SgprOrigin::DivergentDesc { def_inst_idx } => {
                        col.divergent_descriptor_defs.insert(def_inst_idx);
                    }
                    SgprOrigin::UserTable { user_sgpr, .. }
                        if (stage != ShaderStage::Vertex || !*idxen)
                            && rsrc_sgpr_opt.is_some_and(|rsrc_sgpr| {
                                is_synthesized_root_vsharp(&state.origins, rsrc_sgpr)
                            }) =>
                    {
                        col.out.inst_storage_buf_keys.insert(
                            inst_idx,
                            ResourceKey::RootDescriptor {
                                user_sgpr,
                                table_byte_offset: None,
                            },
                        );
                        if stage == ShaderStage::Vertex && mubuf_storage_op(*op).is_some() {
                            col.out.vertex_storage_buf_insts.insert(inst_idx);
                        }
                    }
                    SgprOrigin::RawTableDesc { def_inst_idx, .. } => {
                        col.raw_descriptor_defs.insert(def_inst_idx);
                    }
                    _ => {}
                }
            }
        }
        Rdna2Detail::Mtbuf {
            op,
            idxen,
            srsrc,
            soffset,
            vdata,
            ..
        } => {
            taint_sgpr_if_loaded(&mut collector, &state.origins, u16::from(*soffset));
            if let Some(buf_op) = mtbuf_storage_op(*op)
                && !buf_op.is_store()
            {
                for d in 0..buf_op.vdata_count() {
                    if let Some(reg) = checked_vgpr_reg(*vdata, d) {
                        clear_vgpr_origins(state, reg);
                    }
                }
            }
            if let Some(col) = collector.as_deref_mut() {
                let rsrc_sgpr_opt = checked_descriptor_sgpr(*srsrc, 4);
                let origin = rsrc_sgpr_opt.map_or(SgprOrigin::Unknown, |rsrc_sgpr| {
                    resolve_vsharp_origin(&state.origins, rsrc_sgpr)
                });
                match origin {
                    SgprOrigin::VbDesc {
                        def_inst_idx,
                        vb_slot,
                    } if stage == ShaderStage::Vertex && mtbuf_load_components(*op).is_some() => {
                        col.direct_descriptor_defs.insert(def_inst_idx);
                        col.out.vertex_fetch_vb_slots.insert(inst_idx, vb_slot);
                    }
                    SgprOrigin::TableDesc {
                        def_inst_idx,
                        user_sgpr,
                        table_byte_offset,
                        ..
                    } => {
                        col.direct_descriptor_defs.insert(def_inst_idx);
                        col.out.inst_storage_buf_keys.insert(
                            inst_idx,
                            ResourceKey::Table {
                                user_sgpr,
                                table_byte_offset,
                            },
                        );
                        if stage == ShaderStage::Vertex && mtbuf_storage_op(*op).is_some() {
                            col.out.vertex_storage_buf_insts.insert(inst_idx);
                        }
                    }
                    SgprOrigin::DynamicHeapDesc {
                        def_inst_idx,
                        origin,
                    } => {
                        col.direct_descriptor_defs.insert(def_inst_idx);
                        col.out.inst_storage_buf_keys.insert(
                            inst_idx,
                            ResourceKey::ResourceHeap {
                                base_user_sgpr: origin.base_user_sgpr,
                                stride: origin.stride,
                                index_user_sgpr: origin.index_user_sgpr,
                                index_shift: origin.index_shift,
                            },
                        );
                        if stage == ShaderStage::Vertex && mtbuf_storage_op(*op).is_some() {
                            col.out.vertex_storage_buf_insts.insert(inst_idx);
                        }
                    }
                    SgprOrigin::CbvIndexedHeapDesc {
                        def_inst_idx,
                        origin,
                    } => {
                        col.direct_descriptor_defs.insert(def_inst_idx);
                        col.out.inst_storage_buf_keys.insert(
                            inst_idx,
                            ResourceKey::CbvIndexedResourceHeap(origin),
                        );
                        if stage == ShaderStage::Vertex && mtbuf_storage_op(*op).is_some() {
                            col.out.vertex_storage_buf_insts.insert(inst_idx);
                        }
                    }
                    SgprOrigin::LaneIndexedHeapDesc {
                        def_inst_idx,
                        origin,
                    } => {
                        col.direct_descriptor_defs.insert(def_inst_idx);
                        col.out.inst_storage_buf_keys.insert(
                            inst_idx,
                            ResourceKey::LaneIndexedResourceHeap(origin),
                        );
                        if stage == ShaderStage::Vertex && mtbuf_storage_op(*op).is_some() {
                            col.out.vertex_storage_buf_insts.insert(inst_idx);
                        }
                    }
                    SgprOrigin::TableDescChoice {
                        user_sgpr,
                        offsets,
                        def_insts,
                    } if stage != ShaderStage::Vertex
                        && mtbuf_storage_op(*op).is_some_and(StorageBufOpKind::is_store) =>
                    {
                        let choice_id = col.alloc_two_way_choice(user_sgpr, offsets, def_insts);
                        let keys = [
                            ResourceKey::Table {
                                user_sgpr,
                                table_byte_offset: offsets[0],
                            },
                            ResourceKey::Table {
                                user_sgpr,
                                table_byte_offset: offsets[1],
                            },
                        ];
                        col.out.inst_storage_buf_dispatches.insert(
                            inst_idx,
                            StorageDispatch::TwoWayChoice { choice_id, keys },
                        );
                    }
                    SgprOrigin::TableDescChoice { def_insts, .. } => {
                        col.raw_descriptor_defs.insert(def_insts[0]);
                        col.raw_descriptor_defs.insert(def_insts[1]);
                    }
                    SgprOrigin::BoundedCbvIndexedHeapDesc { def_inst_idx, .. } => {
                        col.direct_descriptor_defs.insert(def_inst_idx);
                    }
                    SgprOrigin::DivergentDesc { def_inst_idx } => {
                        col.divergent_descriptor_defs.insert(def_inst_idx);
                    }
                    SgprOrigin::UserTable { user_sgpr, .. }
                        if (stage != ShaderStage::Vertex || !*idxen)
                            && rsrc_sgpr_opt.is_some_and(|rsrc_sgpr| {
                                is_synthesized_root_vsharp(&state.origins, rsrc_sgpr)
                            }) =>
                    {
                        col.out.inst_storage_buf_keys.insert(
                            inst_idx,
                            ResourceKey::RootDescriptor {
                                user_sgpr,
                                table_byte_offset: None,
                            },
                        );
                        if stage == ShaderStage::Vertex && mtbuf_storage_op(*op).is_some() {
                            col.out.vertex_storage_buf_insts.insert(inst_idx);
                        }
                    }
                    SgprOrigin::RawTableDesc { def_inst_idx, .. } => {
                        col.raw_descriptor_defs.insert(def_inst_idx);
                    }
                    _ => {}
                }
            }
        }
        Rdna2Detail::Flat { saddr, vdst, .. } => {
            taint_sgpr_if_loaded(&mut collector, &state.origins, u16::from(*saddr));
            if *saddr <= MAX_TRACKED_SGPR_PAIR {
                taint_sgpr_if_loaded(&mut collector, &state.origins, u16::from(*saddr + 1));
            }
            clear_vgpr_origins(state, *vdst);
        }
        Rdna2Detail::Vintrp { vdst, .. } => {
            clear_vgpr_origins(state, *vdst);
        }
        Rdna2Detail::Ds { op, vdst, .. } => {
            if let Some(lds_op) = ds_lds_op(*op) {
                match lds_op {
                    DsLdsOp::ReadContiguous(n) => {
                        for k in 0..n {
                            clear_vgpr_origins(state, vdst.saturating_add(k));
                        }
                    }
                    DsLdsOp::Read2 { .. } => {
                        clear_vgpr_origins(state, *vdst);
                        clear_vgpr_origins(state, vdst.saturating_add(1));
                    }
                    DsLdsOp::Atomic {
                        returns_value: true,
                        ..
                    }
                    | DsLdsOp::Swizzle
                    | DsLdsOp::Permute
                    | DsLdsOp::BPermute => {
                        clear_vgpr_origins(state, *vdst);
                    }
                    _ => {}
                }
            }
        }
        Rdna2Detail::Sopp { .. } | Rdna2Detail::Exp { .. } | Rdna2Detail::Unknown { .. } => {}
    }
}

fn mark_untainted_def_and_parents(
    start_def: usize,
    force_start: bool,
    def_parents: &BTreeMap<usize, usize>,
    def_aliases: &BTreeMap<usize, BTreeSet<usize>>,
    divergent_def_aliases: Option<&BTreeMap<usize, BTreeSet<usize>>>,
    tainted_defs: &BTreeSet<usize>,
    vsharp_fetch_insts: &mut BTreeSet<usize>,
) {
    let mut visited: BTreeSet<usize> = BTreeSet::new();
    let mut stack: Vec<(usize, bool)> = vec![(start_def, force_start)];
    while let Some((cur, forced)) = stack.pop() {
        if visited.len() >= 128 || !visited.insert(cur) {
            continue;
        }
        let suppressed = forced || !tainted_defs.contains(&cur);
        if suppressed {
            vsharp_fetch_insts.insert(cur);
        }
        if let Some(aliases) = def_aliases.get(&cur) {
            for &alias in aliases {
                if !visited.contains(&alias) {
                    stack.push((alias, forced));
                }
            }
        }
        if let Some(div_aliases) = divergent_def_aliases.and_then(|m| m.get(&cur)) {
            for &alias in div_aliases {
                if !visited.contains(&alias) {
                    stack.push((alias, false));
                }
            }
        }
        if suppressed
            && let Some(&parent) = def_parents.get(&cur)
            && !visited.contains(&parent)
        {
            stack.push((parent, false));
        }
    }
}

/// Upper SGPR bound (exclusive) tracked for console initial user-data SGPRs.
/// Mesh stages begin at `s16` (`kMeshUserDataBase = 16`) and can carry up to 32 user-data dwords
/// (`s16..s47`, including SM 6.6 trailing implicit heap SGPRs when root signatures exceed 16 dwords).
const MAX_USER_DATA_SGPR_LIMIT: usize = 48;

/// Exclusive upper SGPR index for initial user-data seeding (`s48` for mesh `s16..s47`,
/// `s32` for graphics `s8..s31` and compute `s4..s31`).
#[inline]
const fn initial_user_sgpr_limit(is_mesh: bool) -> usize {
    if is_mesh {
        MAX_USER_DATA_SGPR_LIMIT
    } else {
        32
    }
}

/// First SGPR holding console root-argument user data for the given stage.
///
/// Matches `runtime/gpu/stage_reflection.h`:
/// - Mesh stages (lowered to compute): `s16` (`kMeshUserDataBase = 16`, `s8..s15` are NGG/mesh sys).
/// - Regular compute stages: `s4`.
/// - Graphics stages (vertex / fragment): `s8`.
#[inline]
const fn initial_user_sgpr_base(stage: ShaderStage, is_mesh: bool) -> usize {
    if is_mesh {
        16
    } else if matches!(stage, ShaderStage::Compute) {
        4
    } else {
        8
    }
}

/// Identify SGPRs in `user_base..user_limit` that are NOT live-on-entry (either never read as
/// scalar/pointer user-data inputs, or unconditionally written before any read along every CFG
/// path from entry). Seeding those registers as `Unwritten` instead of `UserTable` prevents
/// scratch SGPRs (e.g. `s12`/`s14`/`s16`/`s19`/`s32+`) and guarded CFG joins from clobbering
/// proven descriptor origins.
fn compute_unreferenced_initial_user_sgprs(
    active: &[Rdna2Instruction],
    cfg: &ControlFlowGraph,
    stage: ShaderStage,
    is_mesh: bool,
    is_wave32: bool,
) -> [bool; MAX_USER_DATA_SGPR_LIMIT] {
    let user_base = initial_user_sgpr_base(stage, is_mesh);
    let user_limit = initial_user_sgpr_limit(is_mesh);
    let Some(entry) = cfg.entry() else {
        return [false; MAX_USER_DATA_SGPR_LIMIT];
    };

    #[inline]
    fn bit_u16(reg: u16, limit: usize) -> u64 {
        if usize::from(reg) < limit {
            1u64 << reg
        } else {
            0
        }
    }
    #[inline]
    fn pair_bits_u16(reg: u16, limit: usize) -> u64 {
        let mut mask = bit_u16(reg, limit);
        if let Some(hi) = reg.checked_add(1) {
            mask |= bit_u16(hi, limit);
        }
        mask
    }
    #[inline]
    fn bit_u8(reg: u8, limit: usize) -> u64 {
        if usize::from(reg) < limit {
            1u64 << reg
        } else {
            0
        }
    }
    #[inline]
    fn range_bits_u8(base: u8, count: u8, limit: usize) -> u64 {
        let mut mask = 0u64;
        for k in 0..count {
            if let Some(r) = base.checked_add(k) {
                mask |= bit_u8(r, limit);
            }
        }
        mask
    }

    // Track non-SMEM scalar writes across the program to recognize in-place synthesized root V#s
    // at `s[r..r+3]` where words 2/3 are filled via SALU while words 0/1 come from initial user SGPRs.
    let mut non_smem_written_mask = 0u64;
    for inst in active {
        if inst.truncated {
            continue;
        }
        match &inst.detail {
            Rdna2Detail::Sop1 { op, sdst, .. } if !matches!(*op, 0x20 | 0x22) => {
                non_smem_written_mask |= if sop1_writes_pair(*op) {
                    range_bits_u8(*sdst, 2, user_limit)
                } else {
                    bit_u8(*sdst, user_limit)
                };
            }
            Rdna2Detail::Sopk { op, sdst, .. }
                if !matches!(*op, 0x03..=0x0E | 0x12 | 0x13 | 0x17..=0x1A) =>
            {
                non_smem_written_mask |= bit_u8(*sdst, user_limit);
            }
            Rdna2Detail::Sop2 { op, sdst, .. } => {
                let (p0, _) = sop2_src_pair_widths(*op);
                non_smem_written_mask |= if p0 || *op == 0x25 {
                    range_bits_u8(*sdst, 2, user_limit)
                } else {
                    bit_u8(*sdst, user_limit)
                };
            }
            Rdna2Detail::Vop1 { op, vdst, .. } if *op == 0x02 => {
                non_smem_written_mask |= bit_u8(*vdst & 0x7F, user_limit);
            }
            Rdna2Detail::Vop3 { op, vdst, .. } if matches!(*op, 0x182 | 0x360) => {
                non_smem_written_mask |= bit_u8(*vdst & 0x7F, user_limit);
            }
            _ => {}
        }
    }

    let inst_reads_writes = |inst: &Rdna2Instruction| -> (u64, u64) {
        if inst.truncated {
            return (0, 0);
        }
        let mut reads = 0u64;
        let mut writes = 0u64;
        match &inst.detail {
            Rdna2Detail::Sopc {
                op, ssrc0, ssrc1, ..
            } => {
                let (p0, p1) = sopc_src_pair_widths(*op);
                reads |= if p0 {
                    pair_bits_u16(u16::from(*ssrc0), user_limit)
                } else {
                    bit_u16(u16::from(*ssrc0), user_limit)
                };
                reads |= if p1 {
                    pair_bits_u16(u16::from(*ssrc1), user_limit)
                } else {
                    bit_u16(u16::from(*ssrc1), user_limit)
                };
            }
            Rdna2Detail::Sop1 {
                op, sdst, ssrc0, ..
            } => {
                reads |= if sop1_reads_pair(*op) {
                    pair_bits_u16(u16::from(*ssrc0), user_limit)
                } else {
                    bit_u16(u16::from(*ssrc0), user_limit)
                };
                if matches!(*op, 0x05 | 0x1B | 0x1D) {
                    reads |= bit_u16(u16::from(*sdst), user_limit);
                } else if matches!(*op, 0x06 | 0x1C | 0x1E) {
                    reads |= pair_bits_u16(u16::from(*sdst), user_limit);
                }
                if !matches!(*op, 0x20 | 0x22) {
                    writes |= if sop1_writes_pair(*op) {
                        range_bits_u8(*sdst, 2, user_limit)
                    } else {
                        bit_u8(*sdst, user_limit)
                    };
                }
            }
            Rdna2Detail::Sopk { op, sdst, .. } => {
                if matches!(*op, 0x02..=0x10 | 0x12) {
                    reads |= bit_u16(u16::from(*sdst), user_limit);
                }
                if !matches!(*op, 0x03..=0x0E | 0x12 | 0x13 | 0x17..=0x1A) {
                    writes |= bit_u8(*sdst, user_limit);
                }
            }
            Rdna2Detail::Sop2 {
                op,
                sdst,
                ssrc0,
                ssrc1,
                ..
            } => {
                let (p0, p1) = sop2_src_pair_widths(*op);
                reads |= if p0 {
                    pair_bits_u16(u16::from(*ssrc0), user_limit)
                } else {
                    bit_u16(u16::from(*ssrc0), user_limit)
                };
                reads |= if p1 {
                    pair_bits_u16(u16::from(*ssrc1), user_limit)
                } else {
                    bit_u16(u16::from(*ssrc1), user_limit)
                };
                writes |= if p0 || *op == 0x25 {
                    range_bits_u8(*sdst, 2, user_limit)
                } else {
                    bit_u8(*sdst, user_limit)
                };
            }
            Rdna2Detail::Smem {
                op,
                sdata,
                sbase,
                soffset,
                ..
            } => {
                let base_count: u8 = if matches!(*op, 0x08..=0x0C | 0x18..=0x1B) {
                    4
                } else {
                    2
                };
                if let Some(sgpr) = checked_descriptor_sgpr(*sbase, 2) {
                    reads |= range_bits_u8(sgpr, base_count, user_limit);
                }
                if *soffset != 0x7D {
                    reads |= bit_u16(u16::from(*soffset), user_limit);
                }
                if let Some(count) = smem_load_dword_count(*op) {
                    writes |= range_bits_u8(*sdata, count, user_limit);
                } else {
                    let store_count: u8 = match *op {
                        0x10 | 0x18 => 1,
                        0x11 | 0x19 => 2,
                        0x12 | 0x1A => 4,
                        0x13 | 0x1B => 8,
                        _ => 0,
                    };
                    if store_count > 0 {
                        reads |= range_bits_u8(*sdata, store_count, user_limit);
                    }
                }
            }
            Rdna2Detail::Vop1 { op, vdst, src0, .. } => {
                reads |= bit_u16(*src0, user_limit);
                if *op == 0x02 {
                    writes |= bit_u8(*vdst & 0x7F, user_limit);
                }
            }
            Rdna2Detail::Vopc {
                op, src0, literal, ..
            } => {
                reads |= bit_u16(*src0, user_limit);
                if let Some(sd) = vopc_sdwab_sdst(*op, *src0, *literal) {
                    if !is_wave32 && sd % 2 == 0 {
                        writes |= pair_bits_u16(u16::from(sd), user_limit);
                    } else {
                        writes |= bit_u8(sd, user_limit);
                    }
                }
            }
            Rdna2Detail::Vop2 { src0, .. } => {
                reads |= bit_u16(*src0, user_limit);
            }
            Rdna2Detail::Vop3 {
                op,
                vdst,
                sdst,
                src0,
                src1,
                src2,
                ..
            } => {
                if !vop3_is_interp_f16(*op) {
                    reads |= bit_u16(*src0, user_limit);
                }
                if !(0x180..=0x1FF).contains(op) {
                    if matches!(*op, 0x2FF..=0x301) || *op == 0x364 {
                        reads |= pair_bits_u16(*src1, user_limit);
                    } else {
                        reads |= bit_u16(*src1, user_limit);
                    }
                }
                if *op == 0x364 {
                    reads |= pair_bits_u16(*src0, user_limit);
                }
                if *op != 0x342
                    && matches!(
                        *op,
                        0x100
                            | 0x101
                            | 0x128..=0x12A
                            | 0x140..=0x165
                            | 0x16D..=0x171
                            | 0x178
                            | 0x340..=0x35F
                            | 0x36D..=0x372
                            | 0x377
                            | 0x378
                    )
                {
                    reads |= bit_u16(*src2, user_limit);
                }
                if let Some(sd) = sdst {
                    let sd7 = *sd & 0x7F;
                    writes |= if !is_wave32 && sd7 % 2 == 0 {
                        range_bits_u8(sd7, 2, user_limit)
                    } else {
                        bit_u8(sd7, user_limit)
                    };
                }
                if *op <= 0xFF && (*op & 0x10) == 0 {
                    let sd = *vdst & 0x7F;
                    writes |= if !is_wave32 && sd % 2 == 0 {
                        range_bits_u8(sd, 2, user_limit)
                    } else {
                        bit_u8(sd, user_limit)
                    };
                } else if matches!(*op, 0x182 | 0x360) {
                    writes |= bit_u8(*vdst & 0x7F, user_limit);
                }
            }
            Rdna2Detail::Vop3P {
                op,
                src0,
                src1,
                src2,
                ..
            } => {
                reads |= bit_u16(*src0, user_limit) | bit_u16(*src1, user_limit);
                if vop3p_is_ternary(*op) {
                    reads |= bit_u16(*src2, user_limit);
                }
            }
            Rdna2Detail::Flat { saddr, .. } => {
                reads |= pair_bits_u16(u16::from(*saddr), user_limit);
            }
            Rdna2Detail::Mubuf { srsrc, soffset, .. }
            | Rdna2Detail::Mtbuf { srsrc, soffset, .. } => {
                reads |= bit_u16(u16::from(*soffset), user_limit);
                // If a MUBUF/MTBUF consumes an in-place synthesized root V# at s[r..r+3] whose
                // words 2/3 were written by non-SMEM scalar ops, treat `s[r..r+1]` as read here
                // so they stay live-on-entry unless overwritten beforehand.
                if let Some(r) = checked_descriptor_sgpr(*srsrc, 4)
                    && (r as usize) + 3 < user_limit
                    && (non_smem_written_mask & range_bits_u8(r + 2, 2, user_limit)) != 0
                {
                    reads |= range_bits_u8(r, 2, user_limit);
                }
            }
            Rdna2Detail::Mimg { .. }
            | Rdna2Detail::Vintrp { .. }
            | Rdna2Detail::Ds { .. }
            | Rdna2Detail::Sopp { .. }
            | Rdna2Detail::Exp { .. }
            | Rdna2Detail::Unknown { .. } => {}
        }
        (reads, writes)
    };

    let num_blocks = cfg.blocks.len();
    let mut block_gen = vec![0u64; num_blocks];
    let mut block_kill = vec![0u64; num_blocks];
    for (bid, block) in cfg.blocks.iter().enumerate() {
        if block.synthetic_exit {
            continue;
        }
        let mut use_mask = 0u64;
        let mut kill = 0u64;
        for inst_idx in block.instr_range.clone() {
            if let Some(inst) = active.get(inst_idx) {
                let (reads, writes) = inst_reads_writes(inst);
                use_mask |= reads & !kill;
                kill |= writes;
            }
        }
        block_gen[bid] = use_mask;
        block_kill[bid] = kill;
    }

    // Standard backward dataflow fixpoint: `live_in[b] = gen[b] | (union(live_in[succ]) & !kill[b])`.
    // Monotonic on a 48-bit lattice, so guaranteed to converge in at most 48 * num_blocks steps.
    let mut live_in = block_gen.clone();
    loop {
        let mut changed = false;
        for bid in (0..num_blocks).rev() {
            let block = &cfg.blocks[bid];
            if block.synthetic_exit {
                continue;
            }
            let mut live_out = 0u64;
            for succ in block.terminator.successors() {
                if let Some(&succ_in) = live_in.get(succ) {
                    live_out |= succ_in;
                }
            }
            let next_in = block_gen[bid] | (live_out & !block_kill[bid]);
            if next_in != live_in[bid] {
                live_in[bid] = next_in;
                changed = true;
            }
        }
        if !changed {
            break;
        }
    }

    let live_at_entry = live_in[entry];
    let mut unreferenced = [false; MAX_USER_DATA_SGPR_LIMIT];
    for (sgpr, slot) in unreferenced
        .iter_mut()
        .enumerate()
        .take(user_limit)
        .skip(user_base)
    {
        *slot = (live_at_entry & (1u64 << sgpr)) == 0;
    }
    unreferenced
}

/// Detect descriptor-table V#/T#/S# indirections (`s_load_dword*`) and track console user-data
/// SGPR provenance (`s8+` graphics, `s4+` compute, `s16+` mesh) across CFG basic blocks, SALU
/// address derivation, 2-level nested table pointers, VGPR lane/uniform spills, hardware VB-table
/// (`s[0:1]`), SM 6.6 dynamic descriptor heaps, and inline static-sampler S# origins
/// for `<pack>.reflect.json` (S31 / #662, S34 / #733, S40 / #890, S41 / #917).
fn analyze_vsharp_indirections(
    active: &[Rdna2Instruction],
    stage: ShaderStage,
    is_mesh: bool,
) -> DescriptorAnalysis {
    if active.is_empty() {
        return DescriptorAnalysis::default();
    }

    let is_wave32 = detect_wave32_program(active);
    let cfg = ControlFlowGraph::from_instructions(active);
    let unreferenced_user_sgprs =
        compute_unreferenced_initial_user_sgprs(active, &cfg, stage, is_mesh, is_wave32);
    let num_blocks = cfg.blocks.len();
    let mut pred_counts: Vec<usize> = vec![0; num_blocks];
    for block in &cfg.blocks {
        if block.synthetic_exit {
            continue;
        }
        for succ in block.terminator.successors() {
            if let Some(c) = pred_counts.get_mut(succ) {
                *c += 1;
            }
        }
    }

    // Pass 1: Monotonic forward dataflow fixpoint over CFG basic blocks so clobbers on one
    // branch (e.g. before `s_branch` / early `s_endpgm`) never pollute sibling blocks.
    // Use an ordered `BTreeSet` worklist (lowest block ID first = near-RPO, deduplicated) so
    // chained `if/else` diamonds converge linearly without burning the per-block visit budget.
    let mut block_in: Vec<Option<OriginState>> = vec![None; num_blocks];
    let mut visits: Vec<u8> = vec![0; num_blocks];
    let mut worklist: BTreeSet<BlockId> = BTreeSet::new();
    let mut pass1_def_aliases: BTreeMap<usize, BTreeSet<usize>> = BTreeMap::new();
    let mut pass1_divergent_def_aliases: BTreeMap<usize, BTreeSet<usize>> = BTreeMap::new();
    let entry_state = OriginState::initial(stage, is_mesh, &unreferenced_user_sgprs);
    let Some(entry) = cfg.entry() else {
        return DescriptorAnalysis::default();
    };
    if let Some(slot) = block_in.get_mut(entry) {
        *slot = Some(entry_state.clone());
        worklist.insert(entry);
    }

    while let Some(bid) = worklist.pop_first() {
        let Some(visit_count) = visits.get_mut(bid) else {
            continue;
        };
        if *visit_count >= 32 {
            continue;
        }
        *visit_count += 1;
        let Some(block) = cfg.blocks.get(bid) else {
            continue;
        };
        if block.synthetic_exit {
            continue;
        }
        let Some(mut state) = block_in.get(bid).and_then(Option::as_ref).cloned() else {
            continue;
        };
        for inst_idx in block.instr_range.clone() {
            let Some(inst) = active.get(inst_idx) else {
                continue;
            };
            step_origin_state(
                &mut state,
                inst_idx,
                inst,
                stage,
                is_wave32,
                None,
            );
        }
        let scc_bound_edge = match (block.terminator, state.last_scc_bound) {
            (
                Terminator::CondBranch {
                    kind: kind @ (BranchKind::Scc0 | BranchKind::Scc1),
                    target,
                    fallthrough,
                },
                Some((idx_sgpr, max_elems, in_bounds_when_scc1)),
            ) => {
                let in_bounds_succ = if (kind == BranchKind::Scc1) == in_bounds_when_scc1 {
                    target
                } else {
                    fallthrough
                };
                Some((in_bounds_succ, idx_sgpr, max_elems))
            }
            _ => None,
        };
        let execz_bypass_target = match block.terminator {
            Terminator::CondBranch {
                kind: BranchKind::Execz,
                target,
                ..
            } => Some(target),
            _ => None,
        };
        for succ in block.terminator.successors() {
            if cfg.blocks.get(succ).is_none_or(|b| b.synthetic_exit) {
                continue;
            }
            let Some(succ_in) = block_in.get_mut(succ) else {
                continue;
            };
            let is_execz_merge = execz_bypass_target == Some(succ)
                && pred_counts.get(succ).copied().unwrap_or(0) >= 2;
            let bound_override = scc_bound_edge
                .filter(|&(in_succ, _, _)| in_succ == succ)
                .map(|(_, reg, max_e)| (reg, max_e));
            let edge_state_owned;
            let edge_state = if is_execz_merge || bound_override.is_some() {
                edge_state_owned = {
                    let mut s = state.clone();
                    if is_execz_merge {
                        for orig in &mut s.origins {
                            if matches!(orig, SgprOrigin::Unknown | SgprOrigin::CbvDword { .. }) {
                                *orig = SgprOrigin::ExeczScratch;
                            }
                        }
                    }
                    if let Some((reg, max_e)) = bound_override {
                        let prev = s.sgpr_bound(reg);
                        let tight = if prev == 0 { max_e } else { prev.min(max_e) };
                        s.set_sgpr_bound(reg, tight);
                    }
                    s
                };
                &edge_state_owned
            } else {
                &state
            };
            match succ_in {
                None => {
                    *succ_in = Some(edge_state.clone());
                    worklist.insert(succ);
                }
                Some(existing) => {
                    if existing.join_from(
                        edge_state,
                        &mut pass1_def_aliases,
                        &mut pass1_divergent_def_aliases,
                    ) {
                        worklist.insert(succ);
                    }
                }
            }
        }
    }

    // Pass 2: Single pass over every non-synthetic block using converged incoming origins to
    // record descriptor uses, tainting, nested pointer chains, and CBV sources.
    let mut collector = AnalysisCollector {
        def_aliases: pass1_def_aliases,
        divergent_def_aliases: pass1_divergent_def_aliases,
        ..AnalysisCollector::default()
    };
    for (bid, block) in cfg.blocks.iter().enumerate() {
        if block.synthetic_exit || block.instr_range.is_empty() {
            continue;
        }
        let mut state = block_in
            .get(bid)
            .and_then(Option::as_ref)
            .cloned()
            .unwrap_or_else(|| entry_state.clone());
        for inst_idx in block.instr_range.clone() {
            let Some(inst) = active.get(inst_idx) else {
                continue;
            };
            step_origin_state(
                &mut state,
                inst_idx,
                inst,
                stage,
                is_wave32,
                Some(&mut collector),
            );
        }
    }

    // Finalize descriptor fetch suppression & CBV source attribution.
    let AnalysisCollector {
        mut out,
        tainted_defs,
        def_parents,
        def_aliases,
        divergent_def_aliases,
        direct_descriptor_defs,
        raw_descriptor_defs,
        divergent_descriptor_defs,
        buffer_load_uses,
        cbv_ptr_loads,
        direct_root_cbvs,
        ..
    } = collector;

    for def_idx in direct_descriptor_defs {
        mark_untainted_def_and_parents(
            def_idx,
            true,
            &def_parents,
            &def_aliases,
            None,
            &tainted_defs,
            &mut out.vsharp_fetch_insts,
        );
    }

    for def_idx in raw_descriptor_defs {
        mark_untainted_def_and_parents(
            def_idx,
            false,
            &def_parents,
            &def_aliases,
            None,
            &tainted_defs,
            &mut out.vsharp_fetch_insts,
        );
    }

    for def_idx in divergent_descriptor_defs {
        mark_untainted_def_and_parents(
            def_idx,
            false,
            &def_parents,
            &def_aliases,
            Some(&divergent_def_aliases),
            &tainted_defs,
            &mut out.vsharp_fetch_insts,
        );
    }

    for buf_use in buffer_load_uses {
        if buf_use.source.is_some() {
            // `s_buffer_load_*` consumes a 128-bit hardware V# descriptor from a known
            // descriptor table or dynamic heap. Always suppress its V# load(s) and attribute
            // the CBV read even if a V# word (e.g. `num_records` / stride) or a copied SGPR
            // pair was also inspected by scalar/vector ALU or comparisons (S41 / #917).
            mark_untainted_def_and_parents(
                buf_use.def_inst_idx,
                true,
                &def_parents,
                &def_aliases,
                None,
                &tainted_defs,
                &mut out.vsharp_fetch_insts,
            );
            if let Some(key) = buf_use.cbv_key {
                out.indirect_smem_cbv_keys.insert(buf_use.inst_idx, key);
                if let Some(src) = buf_use.source {
                    out.cbv_sources.entry(key).or_insert(src);
                }
            }
        } else if !tainted_defs.contains(&buf_use.def_inst_idx)
            || out.vsharp_fetch_insts.contains(&buf_use.def_inst_idx)
        {
            mark_untainted_def_and_parents(
                buf_use.def_inst_idx,
                false,
                &def_parents,
                &def_aliases,
                None,
                &tainted_defs,
                &mut out.vsharp_fetch_insts,
            );
            if let Some(key) = buf_use.cbv_key {
                out.indirect_smem_cbv_keys.insert(buf_use.inst_idx, key);
            }
        }
    }

    // 2-level CBV pointer loads (`s_load_dwordx2` from table -> `s_load_dword*` reading CBV data):
    // any inner load that was NOT itself a descriptor fetch reads CBV data from its pointer's table slot.
    for ptr_load in cbv_ptr_loads {
        if !out.vsharp_fetch_insts.contains(&ptr_load.inst_idx) {
            if !tainted_defs.contains(&ptr_load.ptr_def) {
                mark_untainted_def_and_parents(
                    ptr_load.ptr_def,
                    false,
                    &def_parents,
                    &def_aliases,
                    None,
                    &tainted_defs,
                    &mut out.vsharp_fetch_insts,
                );
            }
            out.indirect_smem_cbv_keys
                .insert(ptr_load.inst_idx, ptr_load.cbv_key);
            out.cbv_sources
                .entry(ptr_load.cbv_key)
                .or_insert(ptr_load.source);
        }
    }

    // Direct root-descriptor CBV loads (`s_load_dword*` / `s_buffer_load_*` on a `UserTable` SGPR)
    // that were not suppressed as descriptor/pointer fetches.
    // When every remaining load on a `user_sgpr` uses a 32-bit table pointer (`sbase_hi` is a
    // constant) at 32-byte-aligned descriptor-slot boundaries (descriptor-width `s_load_dwordx4/x8`
    // or explicit multiple-of-32 SALU table pointer offset), emit v2 `table_byte_offset` (#1471)
    // for non-zero slots so the runtime joins the exact descriptor slot instead of falling back to 0.
    let mut direct_by_sgpr: BTreeMap<u32, Vec<DirectRootCbvLoad>> = BTreeMap::new();
    for load in direct_root_cbvs {
        if !out.vsharp_fetch_insts.contains(&load.inst_idx)
            && !out.indirect_smem_cbv_keys.contains_key(&load.inst_idx)
        {
            direct_by_sgpr.entry(load.user_sgpr).or_default().push(load);
        }
    }
    for (user_sgpr, loads) in direct_by_sgpr {
        let all_table_slot_loads = loads.iter().all(|l| {
            l.is_32bit_table_ptr
                && l.const_byte_offset.is_some_and(|off| off >= 0 && off % 32 == 0)
                && (l.load_dwords >= 4 || (l.ptr_byte_offset > 0 && l.ptr_byte_offset % 32 == 0))
        });
        if all_table_slot_loads {
            for load in loads {
                let off = load.const_byte_offset.unwrap_or(0) as u32;
                let tbo = if off > 0 { Some(off) } else { None };
                let key = CbvKey {
                    base_sbase: 0,
                    user_sgpr: Some(user_sgpr),
                    table_offset: tbo.map(|v| v as i32),
                    dynamic_heap: None,
                    cbv_indexed_heap: None,
                    lane_indexed_heap: None,
                };
                out.indirect_smem_cbv_keys.insert(load.inst_idx, key);
                out.cbv_sources
                    .entry(key)
                    .or_insert(WgslBindingSource::RootDescriptor {
                        user_sgpr,
                        table_byte_offset: tbo,
                    });
            }
        } else {
            let key = CbvKey {
                base_sbase: 0,
                user_sgpr: Some(user_sgpr),
                table_offset: None,
                dynamic_heap: None,
                cbv_indexed_heap: None,
                lane_indexed_heap: None,
            };
            for load in loads {
                out.indirect_smem_cbv_keys.insert(load.inst_idx, key);
            }
            out.cbv_sources
                .entry(key)
                .or_insert(WgslBindingSource::RootDescriptor {
                    user_sgpr,
                    table_byte_offset: None,
                });
        }
    }

    out
}

/// Map a vertex-shader MUBUF/MTBUF attribute fetch to `(attribute_byte_offset, component_shift)`.
///
/// A 1-component 8-bit `tbuffer_load_format_x` (`BUF_FMT_8_*`, formats 1..=6) at a byte offset
/// that is not dword aligned reads a single channel of a packed 4x8-bit attribute (e.g.
/// `offset:7` on an `R8G8B8A8_UNORM` element at `+4` reads `.w`). Such fetches are folded into
/// the dword-aligned `vec4<f32>` attribute (matching WebGPU `unorm8x4`) with a component shift.
fn vertex_fetch_slot(is_mtbuf: bool, op: u8, format: u8, byte_offset: u16) -> (u16, u8) {
    let sub_dword = (byte_offset % 4) as u8;
    if is_mtbuf && op == 0x00 && (1..=6).contains(&format) && sub_dword != 0 {
        (byte_offset - u16::from(sub_dword), sub_dword)
    } else {
        (byte_offset, 0)
    }
}

/// Decode a GFX10.3 unified `MTBUF` `format` code (`V_008F0C_BUF_FMT_*`, matching
/// `runtime/gpu/gfx10_descriptors.cpp`) into `(component_type, fetch_format)` for stage
/// reflection (`runtime/gpu/stage_reflection.cpp::vertex_format_from_name`).
fn mtbuf_vertex_format_info(format: u8, folded_4x8: bool) -> (&'static str, Option<&'static str>) {
    if folded_4x8 {
        return match format {
            1 | 3 => ("f32", Some("unorm8x4")),
            2 | 4 => ("f32", Some("snorm8x4")),
            5 => ("u32", Some("uint8x4")),
            6 => ("i32", Some("sint8x4")),
            _ => ("f32", Some("unorm8x4")),
        };
    }
    match format {
        1 | 3 => ("f32", Some("unorm8")),
        2 | 4 => ("f32", Some("snorm8")),
        5 => ("u32", Some("uint8")),
        6 => ("i32", Some("sint8")),
        7 | 9 => ("f32", Some("unorm16")),
        8 | 10 => ("f32", Some("snorm16")),
        11 => ("u32", Some("uint16")),
        12 => ("i32", Some("sint16")),
        13 => ("f32", Some("float16")),
        14 | 16 => ("f32", Some("unorm8x2")),
        15 | 17 => ("f32", Some("snorm8x2")),
        18 => ("u32", Some("uint8x2")),
        19 => ("i32", Some("sint8x2")),
        20 => ("u32", Some("uint32")),
        21 => ("i32", Some("sint32")),
        22 => ("f32", Some("float32")),
        23 | 25 => ("f32", Some("unorm16x2")),
        24 | 26 => ("f32", Some("snorm16x2")),
        27 => ("u32", Some("uint16x2")),
        28 => ("i32", Some("sint16x2")),
        29 => ("f32", Some("float16x2")),
        // GFX10.3 `10_10_10_2` (44..49) & `2_10_10_10` (50..55) UNORM/USCALED
        44 | 46 | 50 | 52 => ("f32", Some("unorm10-10-10-2")),
        // GFX10.3 `8_8_8_8` (56..61)
        56 | 58 => ("f32", Some("unorm8x4")),
        57 | 59 => ("f32", Some("snorm8x4")),
        60 => ("u32", Some("uint8x4")),
        61 => ("i32", Some("sint8x4")),
        // GFX10.3 `32_32` (62..64)
        62 => ("u32", Some("uint32x2")),
        63 => ("i32", Some("sint32x2")),
        64 => ("f32", Some("float32x2")),
        // GFX10.3 `16_16_16_16` (65..71)
        65 | 67 => ("f32", Some("unorm16x4")),
        66 | 68 => ("f32", Some("snorm16x4")),
        69 => ("u32", Some("uint16x4")),
        70 => ("i32", Some("sint16x4")),
        71 => ("f32", Some("float16x4")),
        // GFX10.3 `32_32_32` (72..74)
        72 => ("u32", Some("uint32x3")),
        73 => ("i32", Some("sint32x3")),
        74 => ("f32", Some("float32x3")),
        // GFX10.3 `32_32_32_32` (75..77)
        75 => ("u32", Some("uint32x4")),
        76 => ("i32", Some("sint32x4")),
        77 => ("f32", Some("float32x4")),
        _ => ("f32", None),
    }
}

/// Map a raw untyped MUBUF dword load opcode (`buffer_load_dword` / `x2` / `x3` / `x4`) to its
/// WebGPU `fetch_format` string so sub-element vertex loads carry an explicit width in reflection.
/// Returns `None` for formatted loads (`buffer_load_format_*`, `0x00..=0x03`) whose element format
/// is defined by the D3D12 input layout / V# descriptor.
#[inline]
const fn mubuf_raw_dword_fetch_format(op: u8) -> Option<&'static str> {
    match op {
        0x0C => Some("float32"),
        0x0D => Some("float32x2"),
        0x0F => Some("float32x3"),
        0x0E => Some("float32x4"),
        _ => None,
    }
}

/// Returns `true` if `inst` reads or writes the scalar `m0` register (`124`) or sends
/// `MSG_GS_ALLOC_REQ` (which implicitly reads `m0`).
fn inst_uses_m0(inst: &Rdna2Instruction) -> bool {
    if inst.truncated {
        return false;
    }
    match &inst.detail {
        Rdna2Detail::Sopp { op, simm16, .. } => {
            matches!(*op, 0x10 | 0x11) && sendmsg_id(*simm16) == SENDMSG_ID_GS_ALLOC_REQ
        }
        Rdna2Detail::Sopc { ssrc0, ssrc1, .. } => *ssrc0 == 124 || *ssrc1 == 124,
        Rdna2Detail::Sop1 { sdst, ssrc0, .. } => *sdst == 124 || *ssrc0 == 124,
        Rdna2Detail::Sopk { sdst, .. } => *sdst == 124,
        Rdna2Detail::Sop2 {
            sdst, ssrc0, ssrc1, ..
        } => *sdst == 124 || *ssrc0 == 124 || *ssrc1 == 124,
        Rdna2Detail::Smem { sdata, soffset, .. } => *sdata == 124 || *soffset == 124,
        Rdna2Detail::Vop1 { op, vdst, src0, .. } => {
            *src0 == 124 || (*op == 0x02 && (*vdst & 0x7F) == 124)
        }
        Rdna2Detail::Vopc { src0, .. } | Rdna2Detail::Vop2 { src0, .. } => *src0 == 124,
        Rdna2Detail::Vop3 {
            op,
            vdst,
            src0,
            src1,
            src2,
            ..
        } => {
            *src0 == 124
                || *src1 == 124
                || *src2 == 124
                || (*op == 0x360 && (*vdst & 0x7F) == 124)
        }
        Rdna2Detail::Vop3P {
            src0, src1, src2, ..
        } => *src0 == 124 || *src1 == 124 || *src2 == 124,
        _ => false,
    }
}

/// Evaluate a scalar operand if it is a compile-time constant or tracked constant SGPR/`m0`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ConstLat {
    Const(u32),
    Bottom,
}

impl ConstLat {
    #[inline]
    const fn join(self, other: Self) -> Self {
        match (self, other) {
            (Self::Const(a), Self::Const(b)) if a == b => Self::Const(a),
            _ => Self::Bottom,
        }
    }

    #[inline]
    const fn as_const(self) -> Option<u32> {
        match self {
            Self::Const(v) => Some(v),
            Self::Bottom => None,
        }
    }
}

fn eval_const_ssrc(
    src: u8,
    literal: Option<u32>,
    sgpr_consts: &[ConstLat; 106],
    m0: ConstLat,
) -> Option<u32> {
    match src {
        0..=105 => sgpr_consts[usize::from(src)].as_const(),
        124 => m0.as_const(),
        128..=192 => Some(u32::from(src - 128)),
        193..=208 => Some((-(i32::from(src) - 192)) as u32),
        255 => literal,
        _ => None,
    }
}

#[derive(Clone, PartialEq, Eq)]
struct MeshConstState {
    sgprs: [ConstLat; 106],
    m0: ConstLat,
}

impl MeshConstState {
    fn entry() -> Self {
        Self {
            sgprs: [ConstLat::Bottom; 106],
            m0: ConstLat::Bottom,
        }
    }

    fn join_from(&mut self, other: &Self) -> bool {
        let mut changed = false;
        for (dst, &src) in self.sgprs.iter_mut().zip(other.sgprs.iter()) {
            let next = dst.join(src);
            if next != *dst {
                *dst = next;
                changed = true;
            }
        }
        let next_m0 = self.m0.join(other.m0);
        if next_m0 != self.m0 {
            self.m0 = next_m0;
            changed = true;
        }
        changed
    }

    fn set_reg(&mut self, reg: u8, val: ConstLat) {
        if reg <= 105 {
            self.sgprs[usize::from(reg)] = val;
        } else if reg == 124 {
            self.m0 = val;
        }
    }

    fn step(&mut self, inst: &Rdna2Instruction) {
        if inst.truncated {
            return;
        }
        match &inst.detail {
            Rdna2Detail::Sop1 {
                op,
                sdst,
                ssrc0,
                literal,
            } => {
                let c0 = eval_const_ssrc(*ssrc0, *literal, &self.sgprs, self.m0);
                let val = match (*op, c0) {
                    (0x03, Some(v)) => ConstLat::Const(v),
                    (0x07, Some(v)) => ConstLat::Const(!v),
                    (0x0B, Some(v)) => ConstLat::Const(v.reverse_bits()),
                    (0x19, Some(v)) => ConstLat::Const(i32::from(v as i8) as u32),
                    (0x1A, Some(v)) => ConstLat::Const(i32::from(v as i16) as u32),
                    (0x34, Some(v)) => ConstLat::Const((v as i32).wrapping_abs() as u32),
                    _ => ConstLat::Bottom,
                };
                if !matches!(*op, 0x20 | 0x22) {
                    self.set_reg(*sdst, val);
                    if sop1_writes_pair(*op)
                        && let Some(hi) = checked_sgpr_reg(*sdst, 1)
                    {
                        self.set_reg(hi, ConstLat::Bottom);
                    }
                }
            }
            Rdna2Detail::Sopk { op, sdst, simm16, .. } => {
                let imm = (*simm16 as i16 as i32) as u32;
                let prev = eval_const_ssrc(*sdst, None, &self.sgprs, self.m0);
                let val = match (*op, prev) {
                    (0x00, _) => ConstLat::Const(imm),
                    (0x0F, Some(p)) => ConstLat::Const(p.wrapping_add(imm)),
                    (0x10, Some(p)) => ConstLat::Const(p.wrapping_mul(imm)),
                    _ => ConstLat::Bottom,
                };
                if !matches!(*op, 0x03..=0x0E | 0x12 | 0x13 | 0x17..=0x1A) {
                    self.set_reg(*sdst, val);
                }
            }
            Rdna2Detail::Sop2 {
                op,
                sdst,
                ssrc0,
                ssrc1,
                literal,
            } => {
                let a = eval_const_ssrc(*ssrc0, *literal, &self.sgprs, self.m0);
                let b = eval_const_ssrc(*ssrc1, *literal, &self.sgprs, self.m0);
                let val = match (*op, a, b) {
                    (0x00 | 0x02, Some(x), Some(y)) => ConstLat::Const(x.wrapping_add(y)),
                    (0x01 | 0x03, Some(x), Some(y)) => ConstLat::Const(x.wrapping_sub(y)),
                    (0x06, Some(x), Some(y)) => ConstLat::Const((x as i32).min(y as i32) as u32),
                    (0x07, Some(x), Some(y)) => ConstLat::Const(x.min(y)),
                    (0x08, Some(x), Some(y)) => ConstLat::Const((x as i32).max(y as i32) as u32),
                    (0x09, Some(x), Some(y)) => ConstLat::Const(x.max(y)),
                    (0x0E, Some(x), Some(y)) => ConstLat::Const(x & y),
                    (0x10, Some(x), Some(y)) => ConstLat::Const(x | y),
                    (0x12, Some(x), Some(y)) => ConstLat::Const(x ^ y),
                    (0x14, Some(x), Some(y)) => ConstLat::Const(x & !y),
                    (0x1E, Some(x), Some(y)) => ConstLat::Const(x.wrapping_shl(y & 31)),
                    (0x20, Some(x), Some(y)) => ConstLat::Const(x.wrapping_shr(y & 31)),
                    (0x22, Some(x), Some(y)) => {
                        ConstLat::Const(((x as i32).wrapping_shr(y & 31)) as u32)
                    }
                    (0x24, Some(w), Some(o)) => {
                        let width = w & 31;
                        let off = o & 31;
                        let mask = if width == 0 {
                            0u32
                        } else {
                            (1u32 << width).wrapping_sub(1)
                        };
                        ConstLat::Const(mask.wrapping_shl(off))
                    }
                    (0x26, Some(x), Some(y)) => ConstLat::Const(x.wrapping_mul(y)),
                    (0x27, Some(x), Some(p)) => {
                        let off = p & 31;
                        let width = (p >> 16) & 0x7F;
                        let r = if width == 0 {
                            0
                        } else if width >= 32 {
                            x.wrapping_shr(off)
                        } else {
                            x.wrapping_shr(off) & ((1u32 << width) - 1)
                        };
                        ConstLat::Const(r)
                    }
                    (0x2E..=0x31, Some(x), Some(y)) => {
                        let sh = u32::from(*op - 0x2D);
                        ConstLat::Const(x.wrapping_shl(sh).wrapping_add(y))
                    }
                    (0x32, Some(x), Some(y)) => {
                        ConstLat::Const((x & 0xFFFF) | ((y & 0xFFFF) << 16))
                    }
                    (0x33, Some(x), Some(y)) => ConstLat::Const((x & 0xFFFF) | (y & 0xFFFF_0000)),
                    (0x34, Some(x), Some(y)) => ConstLat::Const((x >> 16) | (y & 0xFFFF_0000)),
                    _ => ConstLat::Bottom,
                };
                self.set_reg(*sdst, val);
                let (p0, _) = sop2_src_pair_widths(*op);
                if (p0 || *op == 0x25)
                    && let Some(hi) = checked_sgpr_reg(*sdst, 1)
                {
                    self.set_reg(hi, ConstLat::Bottom);
                }
            }
            Rdna2Detail::Smem { op, sdata, .. } => {
                if let Some(count) = smem_load_dword_count(*op) {
                    for k in 0..count {
                        if let Some(r) = checked_sgpr_reg(*sdata, k) {
                            self.set_reg(r, ConstLat::Bottom);
                        }
                    }
                    if *sdata == 124 {
                        self.m0 = ConstLat::Bottom;
                    }
                }
            }
            Rdna2Detail::Vop1 { op: 0x02, vdst, .. }
            | Rdna2Detail::Vop3 {
                op: 0x182 | 0x360,
                vdst,
                ..
            } => {
                self.set_reg(*vdst & 0x7F, ConstLat::Bottom);
            }
            _ => {}
        }
    }
}

/// CFG-aware static inference of `(max_vertices, max_primitives)` when every reachable
/// `s_sendmsg(MSG_GS_ALLOC_REQ)` site in `active` has a statically known constant `m0`
/// (`verts = m0 & 0x7FF`, `prims = (m0 >> 12) & 0x7FF`) that is either a culled zero-primitive
/// early exit (`m0 == 0`) or within `1..=256`, with at least one non-zero allocation site.
fn infer_static_mesh_counts(active: &[Rdna2Instruction]) -> Option<(u32, u32)> {
    let cfg = ControlFlowGraph::from_instructions(active);
    let entry = cfg.entry()?;
    let num_blocks = cfg.blocks.len();
    let mut block_in: Vec<Option<MeshConstState>> = vec![None; num_blocks];
    let mut visits: Vec<u8> = vec![0; num_blocks];
    let mut worklist: BTreeSet<BlockId> = BTreeSet::new();

    block_in[entry] = Some(MeshConstState::entry());
    worklist.insert(entry);

    while let Some(bid) = worklist.pop_first() {
        if visits[bid] >= 16 {
            continue;
        }
        visits[bid] += 1;
        let block = &cfg.blocks[bid];
        if block.synthetic_exit {
            continue;
        }
        let Some(mut state) = block_in[bid].clone() else {
            continue;
        };
        for inst_idx in block.instr_range.clone() {
            if let Some(inst) = active.get(inst_idx) {
                state.step(inst);
            }
        }
        for succ in block.terminator.successors() {
            if cfg.blocks.get(succ).is_none_or(|b| b.synthetic_exit) {
                continue;
            }
            match &mut block_in[succ] {
                None => {
                    block_in[succ] = Some(state.clone());
                    worklist.insert(succ);
                }
                Some(existing) => {
                    if existing.join_from(&state) {
                        worklist.insert(succ);
                    }
                }
            }
        }
    }

    let mut saw_nonzero = false;
    let mut max_verts: u32 = 0;
    let mut max_prims: u32 = 0;

    for (bid, block) in cfg.blocks.iter().enumerate() {
        if block.synthetic_exit {
            continue;
        }
        let Some(mut state) = block_in[bid].clone() else {
            continue;
        };
        for inst_idx in block.instr_range.clone() {
            let Some(inst) = active.get(inst_idx) else {
                continue;
            };
            if inst.truncated {
                continue;
            }
            if let Rdna2Detail::Sopp { op, simm16, .. } = inst.detail
                && matches!(op, 0x10 | 0x11)
                && sendmsg_id(simm16) == SENDMSG_ID_GS_ALLOC_REQ
            {
                let m0 = state.m0.as_const()?;
                let verts = m0 & 0x7FF;
                let prims = (m0 >> 12) & 0x7FF;
                if verts == 0 && prims == 0 {
                    // Culled zero-primitive early-exit SetMeshOutputCounts(0, 0).
                    continue;
                }
                if !(1..=MAX_MESH_VERTICES).contains(&verts)
                    || !(1..=MAX_MESH_PRIMITIVES).contains(&prims)
                {
                    return None;
                }
                saw_nonzero = true;
                max_verts = max_verts.max(verts);
                max_prims = max_prims.max(prims);
            } else {
                state.step(inst);
            }
        }
    }

    if saw_nonzero {
        Some((max_verts, max_prims))
    } else {
        None
    }
}

fn plan_program(
    summary: &Rdna2ProgramSummary,
    instructions: &[Rdna2Instruction],
    options: &Rdna2TranslateOptions,
) -> ProgramPlan {
    let is_mesh = options.stage == Rdna2StageOverride::Mesh
        || (options.stage == Rdna2StageOverride::Auto
            && summary.inferred_stage == Rdna2InferredStage::Mesh);
    let stage = resolve_stage(summary.inferred_stage, options.stage);
    let entry_point = match &options.entry_point {
        Some(custom) => sanitize_wgsl_ident(custom, default_entry_point(stage)),
        None => default_entry_point(stage).to_string(),
    };

    // Determine effective instruction slice (stop at first s_endpgm if no branch targets past it).
    let max_branch_target = summary
        .branches
        .iter()
        .map(|b| b.target_offset)
        .max()
        .unwrap_or(-1);
    let mut active_inst_count = instructions.len();
    for (idx, inst) in instructions.iter().enumerate() {
        if let Rdna2Detail::Sopp { op, .. } = inst.detail
            && matches!(op, 0x01 | 0x1B | 0x1E)
            && max_branch_target <= inst.offset as i64
        {
            active_inst_count = idx + 1;
            break;
        }
    }

    let active = &instructions[..active_inst_count];
    let desc_analysis = analyze_vsharp_indirections(active, stage, is_mesh);
    let vsharp_fetch_insts = desc_analysis.vsharp_fetch_insts;
    let indirect_smem_cbv_keys = desc_analysis.indirect_smem_cbv_keys;
    let vertex_storage_buf_insts = desc_analysis.vertex_storage_buf_insts;
    let vertex_fetch_vb_slots = desc_analysis.vertex_fetch_vb_slots;

    let mut cbv_usage: BTreeMap<CbvKey, CbvUsage> = BTreeMap::new();
    let mut tex_dims: BTreeMap<ResourceKey, TexDim> = BTreeMap::new();
    let mut tex_has_compare: BTreeSet<ResourceKey> = BTreeSet::new();
    let mut tex_has_non_compare: BTreeSet<ResourceKey> = BTreeSet::new();
    let mut tex_has_load: BTreeSet<ResourceKey> = BTreeSet::new();
    let mut samp_rsrc_set: BTreeSet<ResourceKey> = BTreeSet::new();
    let mut samp_has_compare: BTreeSet<ResourceKey> = BTreeSet::new();
    let mut samp_has_non_compare: BTreeSet<ResourceKey> = BTreeSet::new();
    let mut compare_tex_samp_pairs: BTreeSet<(ResourceKey, ResourceKey)> = BTreeSet::new();
    let mut storage_buf_usage: BTreeMap<ResourceKey, bool> = BTreeMap::new();
    let mut non_atomic_storage_buf_keys: BTreeSet<ResourceKey> = BTreeSet::new();
    let mut atomic_storage_buf_keys: BTreeSet<ResourceKey> = BTreeSet::new();
    let mut storage_tex_dims: BTreeMap<ResourceKey, TexDim> = BTreeMap::new();
    let mut uses_lds = false;
    let mut uses_lds_atomics = false;
    let mut uses_wave_lds = false;
    let is_wave32 = detect_wave32_program(active);
    let subgroups_active = options.wave_emul_mode == WaveEmulMode::Subgroups
        && matches!(stage, ShaderStage::Compute | ShaderStage::Fragment);
    let mut has_buffer_fetch = false;
    let mut first_swappc_idx: Option<usize> = None;
    let mut vertex_buf_fetches: BTreeMap<(u32, u16), VertexFetchPlan> = BTreeMap::new();
    let mut frag_attr_set: BTreeSet<u8> = BTreeSet::new();
    let mut frag_attr_interp: BTreeMap<u8, FragAttrInterp> = BTreeMap::new();
    let mut frag_attr_f16_high_channels: BTreeSet<(u8, u8)> = BTreeSet::new();
    let mut vs_param_set: BTreeSet<u8> = BTreeSet::new();
    let mut ps_mrt_set: BTreeSet<u8> = BTreeSet::new();
    let mut ps_exports_depth = false;

    let mut vgprs: BTreeSet<u8> = BTreeSet::new();
    let mut sgprs: BTreeSet<u8> = BTreeSet::new();
    let mut lane_spill_slots: BTreeSet<(u8, u8)> = BTreeSet::new();
    let mut written_vgprs: BTreeSet<u8> = BTreeSet::new();
    let mut read_before_write_vgprs: BTreeSet<u8> = BTreeSet::new();
    let mut written_sgprs: BTreeSet<u8> = BTreeSet::new();
    let mut read_before_write_sgprs: BTreeSet<u8> = BTreeSet::new();
    let mut needs_vcc = false;
    let mut needs_scc = false;
    let mut needs_exec = false;

    // Record a source operand read (register usage, read-before-write, VCC/SCC needs).
    macro_rules! record_src {
        ($src:expr) => {
            record_src_usage(
                $src,
                &mut vgprs,
                &mut sgprs,
                &written_vgprs,
                &mut read_before_write_vgprs,
                &written_sgprs,
                &mut read_before_write_sgprs,
                &mut needs_vcc,
                &mut needs_scc,
            )
        };
    }
    // Record the high half of a 64-bit SGPR (`s[n:n+1]`) or VGPR (`v[n:n+1]`) pair source.
    macro_rules! record_src_pair_hi {
        ($src:expr) => {{
            let src: u16 = $src;
            if src <= 104 || (256..=510).contains(&src) {
                record_src!(src + 1);
            }
        }};
    }

    for (inst_idx, inst) in active.iter().enumerate() {
        if inst.truncated {
            continue;
        }
        match &inst.detail {
            Rdna2Detail::Sopc {
                op, ssrc0, ssrc1, ..
            } => {
                record_src_usage(
                    u16::from(*ssrc0),
                    &mut vgprs,
                    &mut sgprs,
                    &written_vgprs,
                    &mut read_before_write_vgprs,
                    &written_sgprs,
                    &mut read_before_write_sgprs,
                    &mut needs_vcc,
                    &mut needs_scc,
                );
                record_src_usage(
                    u16::from(*ssrc1),
                    &mut vgprs,
                    &mut sgprs,
                    &written_vgprs,
                    &mut read_before_write_vgprs,
                    &written_sgprs,
                    &mut read_before_write_sgprs,
                    &mut needs_vcc,
                    &mut needs_scc,
                );
                let (pair0, pair1) = sopc_src_pair_widths(*op);
                if pair0 {
                    record_src_pair_hi!(u16::from(*ssrc0));
                }
                if pair1 {
                    record_src_pair_hi!(u16::from(*ssrc1));
                }
                needs_scc = true;
            }
            Rdna2Detail::Sop1 {
                op, sdst, ssrc0, ..
            } => {
                if stage == ShaderStage::Vertex && *op == 0x21 {
                    // `s_swappc_b64`: Xbox FSSM vertex fetch shader call. Handled directly by
                    // synthesized `@location(k)` VsIn attribute loads; do not pollute SGPRs with
                    // the fetch-shader pointer pair (`s[4:5]`).
                    first_swappc_idx.get_or_insert(inst_idx);
                    continue;
                }
                record_src_usage(
                    u16::from(*ssrc0),
                    &mut vgprs,
                    &mut sgprs,
                    &written_vgprs,
                    &mut read_before_write_vgprs,
                    &written_sgprs,
                    &mut read_before_write_sgprs,
                    &mut needs_vcc,
                    &mut needs_scc,
                );
                if *sdst == 126 {
                    // `exec_lo` / `exec` destination (e.g. `s_mov_b64 exec, s[0:1]`).
                    needs_exec = true;
                }
                if let Some(write) = classify_exec_mask_op(inst) {
                    // `s_*_saveexec_*` / `s_andn{1,2}_wrexec_*`: read `exec`, write `exec`,
                    // `sdst` (an SGPR pair for `_b64`) and `scc`.
                    needs_exec = true;
                    needs_scc = true;
                    if write.wave64 {
                        record_src_pair_hi!(u16::from(*ssrc0));
                    }
                    if *sdst <= 105 {
                        sgprs.insert(*sdst);
                        written_sgprs.insert(*sdst);
                        if write.wave64 && *sdst <= 104 {
                            sgprs.insert(*sdst + 1);
                            written_sgprs.insert(*sdst + 1);
                        }
                    } else if *sdst == 106 {
                        needs_vcc = true;
                    }
                } else if sop1_reads_pair(*op) || sop1_writes_pair(*op) {
                    if matches!(*op, 0x06 | 0x08 | 0x0E | 0x10 | 0x2D) {
                        needs_scc = true;
                    }
                    if sop1_reads_pair(*op) && *ssrc0 <= 104 {
                        let hi = *ssrc0 + 1;
                        sgprs.insert(hi);
                        if !written_sgprs.contains(&hi) {
                            read_before_write_sgprs.insert(hi);
                        }
                    }
                    if matches!(*op, 0x06 | 0x1C | 0x1E) {
                        if *sdst <= 105 {
                            sgprs.insert(*sdst);
                            if !written_sgprs.contains(sdst) {
                                read_before_write_sgprs.insert(*sdst);
                            }
                        }
                        if *sdst <= 104 {
                            let hi = *sdst + 1;
                            sgprs.insert(hi);
                            if !written_sgprs.contains(&hi) {
                                read_before_write_sgprs.insert(hi);
                            }
                        }
                    }
                    if sop1_writes_pair(*op) {
                        if *sdst <= 104 {
                            sgprs.insert(*sdst);
                            sgprs.insert(*sdst + 1);
                            written_sgprs.insert(*sdst);
                            written_sgprs.insert(*sdst + 1);
                        } else if *sdst == 105 {
                            sgprs.insert(105);
                            written_sgprs.insert(105);
                        } else if *sdst == 106 {
                            needs_vcc = true;
                        }
                    } else if *sdst <= 105 {
                        sgprs.insert(*sdst);
                        written_sgprs.insert(*sdst);
                    }
                } else {
                    if matches!(*op, 0x05 | 0x1B | 0x1D) {
                        if *op == 0x05 {
                            needs_scc = true;
                        }
                        if *sdst <= 105 {
                            sgprs.insert(*sdst);
                            if !written_sgprs.contains(sdst) {
                                read_before_write_sgprs.insert(*sdst);
                            }
                        }
                    }
                    if *sdst <= 105 {
                        sgprs.insert(*sdst);
                        written_sgprs.insert(*sdst);
                    }
                }
            }
            Rdna2Detail::Sopk { op, sdst, .. } => {
                if matches!(*op, 0x03..=0x0E) {
                    needs_scc = true;
                    record_src!(u16::from(*sdst));
                } else if *sdst <= 105 {
                    if matches!(*op, 0x0F | 0x10) && !written_sgprs.contains(sdst) {
                        read_before_write_sgprs.insert(*sdst);
                    }
                    sgprs.insert(*sdst);
                    written_sgprs.insert(*sdst);
                }
            }
            Rdna2Detail::Sop2 {
                op,
                sdst,
                ssrc0,
                ssrc1,
                ..
            } => {
                record_src_usage(
                    u16::from(*ssrc0),
                    &mut vgprs,
                    &mut sgprs,
                    &written_vgprs,
                    &mut read_before_write_vgprs,
                    &written_sgprs,
                    &mut read_before_write_sgprs,
                    &mut needs_vcc,
                    &mut needs_scc,
                );
                record_src_usage(
                    u16::from(*ssrc1),
                    &mut vgprs,
                    &mut sgprs,
                    &written_vgprs,
                    &mut read_before_write_vgprs,
                    &written_sgprs,
                    &mut read_before_write_sgprs,
                    &mut needs_vcc,
                    &mut needs_scc,
                );
                let (pair0, pair1) = sop2_src_pair_widths(*op);
                if pair0 {
                    record_src_pair_hi!(u16::from(*ssrc0));
                }
                if pair1 {
                    record_src_pair_hi!(u16::from(*ssrc1));
                }
                if matches!(*op, 0x04 | 0x05 | 0x0A | 0x0B) {
                    // s_addc_u32 / s_subb_u32 / s_cselect_b32 / s_cselect_b64 read SCC
                    needs_scc = true;
                }
                if *sdst == 126 {
                    // `exec_lo` / `exec` destination (e.g. `s_or_b32 exec_lo, exec_lo, s0`).
                    needs_exec = true;
                }
                if (pair0 || *op == 0x25) && *sdst <= 104 {
                    // 64-bit SGPR pair destination
                    sgprs.insert(*sdst);
                    sgprs.insert(*sdst + 1);
                    written_sgprs.insert(*sdst);
                    written_sgprs.insert(*sdst + 1);
                } else if *sdst <= 105 {
                    sgprs.insert(*sdst);
                    written_sgprs.insert(*sdst);
                } else if pair0 && *sdst == 106 {
                    needs_vcc = true;
                }
            }
            Rdna2Detail::Smem {
                op,
                sdata,
                sbase,
                soffset,
                offset,
                ..
            } => {
                if vsharp_fetch_insts.contains(&inst_idx) {
                    continue;
                }
                if let Some(count) = smem_load_dword_count(*op) {
                    let is_dynamic = *soffset != 0x7D && *soffset <= 105;
                    if is_dynamic {
                        sgprs.insert(*soffset);
                        if !written_sgprs.contains(soffset) {
                            read_before_write_sgprs.insert(*soffset);
                        }
                    }
                    let base_word = if *offset > 0 {
                        (*offset as u32) / 4
                    } else {
                        0
                    };
                    let loaded_dwords = if *sdata <= 105 {
                        u32::from(count).min(u32::from(106 - *sdata))
                    } else {
                        u32::from(count)
                    }
                    .max(1);
                    let highest_dword = base_word.saturating_add(loaded_dwords - 1);
                    let highest_vec4 = highest_dword / 4;
                    let cbv_key = indirect_smem_cbv_keys
                        .get(&inst_idx)
                        .copied()
                        .unwrap_or(CbvKey {
                            base_sbase: *sbase,
                            user_sgpr: None,
                            table_offset: None,
                            dynamic_heap: None,
                            cbv_indexed_heap: None,
                            lane_indexed_heap: None,
                        });
                    cbv_usage
                        .entry(cbv_key)
                        .and_modify(|usage| {
                            usage.max_vec4_index = usage.max_vec4_index.max(highest_vec4);
                            usage.has_dynamic_offset |= is_dynamic;
                        })
                        .or_insert(CbvUsage {
                            max_vec4_index: highest_vec4,
                            has_dynamic_offset: is_dynamic,
                        });
                    for k in 0..count {
                        if let Some(reg) = checked_sgpr_reg(*sdata, k) {
                            sgprs.insert(reg);
                            written_sgprs.insert(reg);
                        }
                    }
                }
            }
            Rdna2Detail::Vop1 { op, vdst, src0, .. } => {
                if !matches!(op, 0x00 | 0x1B | 0x41) {
                    record_src_usage(
                        *src0,
                        &mut vgprs,
                        &mut sgprs,
                        &written_vgprs,
                        &mut read_before_write_vgprs,
                        &written_sgprs,
                        &mut read_before_write_sgprs,
                        &mut needs_vcc,
                        &mut needs_scc,
                    );
                    if *op == 0x02 {
                        let sd = *vdst & 0x7F;
                        if sd <= 105 {
                            sgprs.insert(sd);
                            written_sgprs.insert(sd);
                        }
                    } else if *op == 0x65 {
                        // v_swap_b32 vdst, vsrc0: reads AND writes both VGPRs
                        record_src!(256 + u16::from(*vdst));
                        vgprs.insert(*vdst);
                        written_vgprs.insert(*vdst);
                        if (256..=511).contains(src0) {
                            let vsrc = (*src0 - 256) as u8;
                            vgprs.insert(vsrc);
                            written_vgprs.insert(vsrc);
                        }
                    } else {
                        vgprs.insert(*vdst);
                        written_vgprs.insert(*vdst);
                    }
                }
            }
            Rdna2Detail::Vopc {
                op,
                vsrc1,
                src0,
                literal,
            } => {
                record_src_usage(
                    *src0,
                    &mut vgprs,
                    &mut sgprs,
                    &written_vgprs,
                    &mut read_before_write_vgprs,
                    &written_sgprs,
                    &mut read_before_write_sgprs,
                    &mut needs_vcc,
                    &mut needs_scc,
                );
                record_src_usage(
                    256 + u16::from(*vsrc1),
                    &mut vgprs,
                    &mut sgprs,
                    &written_vgprs,
                    &mut read_before_write_vgprs,
                    &written_sgprs,
                    &mut read_before_write_sgprs,
                    &mut needs_vcc,
                    &mut needs_scc,
                );
                if (*op & 0x10) != 0 {
                    needs_exec = true;
                } else if let Some(sd) = vopc_sdwab_sdst(*op, *src0, *literal) {
                    if sd <= MAX_SGPR_INDEX {
                        sgprs.insert(sd);
                        written_sgprs.insert(sd);
                    } else if sd == 106 {
                        needs_vcc = true;
                    }
                } else {
                    needs_vcc = true;
                }
            }
            Rdna2Detail::Vop2 {
                op,
                vdst,
                vsrc1,
                src0,
                ..
            } => {
                record_src_usage(
                    *src0,
                    &mut vgprs,
                    &mut sgprs,
                    &written_vgprs,
                    &mut read_before_write_vgprs,
                    &written_sgprs,
                    &mut read_before_write_sgprs,
                    &mut needs_vcc,
                    &mut needs_scc,
                );
                record_src_usage(
                    256 + u16::from(*vsrc1),
                    &mut vgprs,
                    &mut sgprs,
                    &written_vgprs,
                    &mut read_before_write_vgprs,
                    &written_sgprs,
                    &mut read_before_write_sgprs,
                    &mut needs_vcc,
                    &mut needs_scc,
                );
                if matches!(op, 0x02 | 0x06 | 0x1F | 0x2B | 0x36 | 0x3C) {
                    // v_dot2c_f32_f16 / v_fmac* / v_mac_f32 / v_pk_fmac_f16 read vdst as accumulator
                    record_src_usage(
                        256 + u16::from(*vdst),
                        &mut vgprs,
                        &mut sgprs,
                        &written_vgprs,
                        &mut read_before_write_vgprs,
                        &written_sgprs,
                        &mut read_before_write_sgprs,
                        &mut needs_vcc,
                        &mut needs_scc,
                    );
                }
                if matches!(op, 0x00 | 0x01) || vop2_is_co_ci(*op) {
                    // v_cndmask_b32 reads VCC; v_*_co_ci_u32 read carry-in from and write carry-out to VCC
                    needs_vcc = true;
                }
                vgprs.insert(*vdst);
                written_vgprs.insert(*vdst);
            }
            Rdna2Detail::Vop3 {
                op,
                vdst,
                sdst,
                src0,
                src1,
                src2,
                literal,
                ..
            } => {
                if matches!(*op, 0x180 | 0x19B | 0x1C1) {
                    // v_nop / v_pipeflush / v_clrexcp promoted to VOP3 carry no register operands.
                    continue;
                }
                if vop3_is_interp_f16(*op) {
                    let (attr, attrchan, high) = decode_vop3_interp_attr(*src0);
                    if stage == ShaderStage::Fragment {
                        let clamped_attr = attr % MAX_INTER_STAGE_LOCATIONS;
                        frag_attr_set.insert(clamped_attr);
                        if high {
                            frag_attr_f16_high_channels.insert((clamped_attr, attrchan & 0x3));
                        }
                        let interp = if (256..512).contains(src1) {
                            let bary_vgpr = (*src1 - 256) as u8;
                            if !written_vgprs.contains(&bary_vgpr) {
                                classify_vintrp_barycentric(bary_vgpr)
                            } else {
                                FragAttrInterp::default()
                            }
                        } else {
                            FragAttrInterp::default()
                        };
                        merge_frag_attr_interp(&mut frag_attr_interp, clamped_attr, interp);
                    }
                    vgprs.insert(*vdst);
                    written_vgprs.insert(*vdst);
                    continue;
                }
                record_src_usage(
                    *src0,
                    &mut vgprs,
                    &mut sgprs,
                    &written_vgprs,
                    &mut read_before_write_vgprs,
                    &written_sgprs,
                    &mut read_before_write_sgprs,
                    &mut needs_vcc,
                    &mut needs_scc,
                );
                let is_unary = (0x180..=0x1FF).contains(op);
                if !is_unary {
                    record_src_usage(
                        *src1,
                        &mut vgprs,
                        &mut sgprs,
                        &written_vgprs,
                        &mut read_before_write_vgprs,
                        &written_sgprs,
                        &mut read_before_write_sgprs,
                        &mut needs_vcc,
                        &mut needs_scc,
                    );
                }
                let is_ternary = matches!(
                    *op,
                    0x100
                        | 0x101
                        | 0x128..=0x12A
                        | 0x140..=0x165
                        | 0x16D..=0x171
                        | 0x178
                        | 0x340..=0x35F
                        | 0x36D..=0x372
                        | 0x377
                        | 0x378
                );
                if is_ternary {
                    record_src_usage(
                        *src2,
                        &mut vgprs,
                        &mut sgprs,
                        &written_vgprs,
                        &mut read_before_write_vgprs,
                        &written_sgprs,
                        &mut read_before_write_sgprs,
                        &mut needs_vcc,
                        &mut needs_scc,
                    );
                }
                if matches!(*op, 0x102 | 0x106 | 0x11F | 0x12B | 0x136 | 0x13C | 0x1E5) {
                    // VOP3-promoted accumulating VOP2 ops & v_swap_b32 read vdst
                    record_src!(256 + u16::from(*vdst));
                }
                let is_shift64 = matches!(*op, 0x2FF..=0x301);
                if is_shift64 {
                    // v_lshlrev_b64 / v_lshrrev_b64 / v_ashrrev_i64 read a 64-bit src1 pair
                    record_src_pair_hi!(*src1);
                }
                let is_pair_dst = is_shift64 || *op == 0x364;
                // Lane-mask SGPR destinations are written as canonical `(lo = lane bit, hi = 0)` pairs.
                let mut record_lane_mask_dst = |sd7: u8| {
                    if sd7 <= 105 {
                        sgprs.insert(sd7);
                        written_sgprs.insert(sd7);
                        if sd7 <= 104 {
                            sgprs.insert(sd7 + 1);
                            written_sgprs.insert(sd7 + 1);
                        }
                    } else if sd7 == 106 {
                        needs_vcc = true;
                    }
                };
                if let Some(sd) = sdst {
                    record_lane_mask_dst(*sd & 0x7F);
                }
                if *op <= 0xFF {
                    if ((*op as u8) & 0x10) != 0 {
                        needs_exec = true;
                    }
                    record_lane_mask_dst(*vdst & 0x7F);
                } else if matches!(*op, 0x182 | 0x360) {
                    // v_readfirstlane_b32_e64 / v_readlane_b32: writes 32-bit scalar destination sdst
                    let sd = *vdst & 0x7F;
                    if sd <= 105 {
                        sgprs.insert(sd);
                        written_sgprs.insert(sd);
                    } else if sd == 106 {
                        needs_vcc = true;
                    } else if sd == 126 {
                        needs_exec = true;
                    }
                } else if *op == 0x361 {
                    // v_writelane_b32 vdst, ssrc0, ssrc1: reserve per-(vgpr, lane) slot for const lane
                    if let Some(lane) = decode_const_lane_index(*src1, *literal) {
                        lane_spill_slots.insert((*vdst, lane));
                    }
                    vgprs.insert(*vdst);
                    written_vgprs.insert(*vdst);
                } else {
                    vgprs.insert(*vdst);
                    written_vgprs.insert(*vdst);
                    if *op == 0x1E5 && (256..=511).contains(src0) {
                        let vsrc = (*src0 - 256) as u8;
                        vgprs.insert(vsrc);
                        written_vgprs.insert(vsrc);
                    }
                    if matches!(*op, 0x377 | 0x378) && !subgroups_active && stage == ShaderStage::Compute {
                        uses_wave_lds = true;
                    }
                    if is_pair_dst && *vdst < 255 {
                        vgprs.insert(*vdst + 1);
                        written_vgprs.insert(*vdst + 1);
                    }
                }
            }
            Rdna2Detail::Vop3P {
                op,
                vdst,
                src0,
                src1,
                src2,
                ..
            } => {
                record_src_usage(
                    *src0,
                    &mut vgprs,
                    &mut sgprs,
                    &written_vgprs,
                    &mut read_before_write_vgprs,
                    &written_sgprs,
                    &mut read_before_write_sgprs,
                    &mut needs_vcc,
                    &mut needs_scc,
                );
                record_src_usage(
                    *src1,
                    &mut vgprs,
                    &mut sgprs,
                    &written_vgprs,
                    &mut read_before_write_vgprs,
                    &written_sgprs,
                    &mut read_before_write_sgprs,
                    &mut needs_vcc,
                    &mut needs_scc,
                );
                if vop3p_is_ternary(*op) {
                    record_src_usage(
                        *src2,
                        &mut vgprs,
                        &mut sgprs,
                        &written_vgprs,
                        &mut read_before_write_vgprs,
                        &written_sgprs,
                        &mut read_before_write_sgprs,
                        &mut needs_vcc,
                        &mut needs_scc,
                    );
                }
                vgprs.insert(*vdst);
                written_vgprs.insert(*vdst);
            }
            Rdna2Detail::Vintrp {
                op,
                vdst,
                attr,
                vsrc,
                ..
            } => {
                if stage == ShaderStage::Fragment {
                    let clamped_attr = *attr % MAX_INTER_STAGE_LOCATIONS;
                    frag_attr_set.insert(clamped_attr);
                    let interp = if *op == 2 {
                        // v_interp_mov_f32 (p0/p10/p20) -> flat interpolation
                        FragAttrInterp {
                            interpolation: Interpolation::Flat,
                            sampling: None,
                        }
                    } else if !written_vgprs.contains(vsrc) {
                        classify_vintrp_barycentric(*vsrc)
                    } else {
                        FragAttrInterp::default()
                    };
                    merge_frag_attr_interp(&mut frag_attr_interp, clamped_attr, interp);
                }
                vgprs.insert(*vdst);
                written_vgprs.insert(*vdst);
            }
            Rdna2Detail::Mimg {
                op,
                dmask,
                dim,
                a16,
                d16,
                nsize,
                vaddr,
                nsa_vaddrs,
                vdata,
                srsrc,
                ssamp,
                ..
            } => {
                if let Some(addr_count) = mimg_bvh_addr_vgpr_count(*op, *a16) {
                    if stage != ShaderStage::Vertex && !is_mesh {
                        let srsrc_base = srsrc.saturating_mul(4);
                        for k in 0..4u8 {
                            if let Some(reg) = checked_sgpr_reg(srsrc_base, k) {
                                sgprs.insert(reg);
                                if !written_sgprs.contains(&reg) {
                                    read_before_write_sgprs.insert(reg);
                                }
                            }
                        }
                        for a in 0..addr_count {
                            if let Some(reg) = mimg_addr_vgpr(*vaddr, *nsize, nsa_vaddrs, a) {
                                vgprs.insert(reg);
                                if !written_vgprs.contains(&reg) {
                                    read_before_write_vgprs.insert(reg);
                                }
                            }
                        }
                        for d in 0..4u8 {
                            if let Some(reg) = checked_vgpr_reg(*vdata, d) {
                                vgprs.insert(reg);
                                written_vgprs.insert(reg);
                            }
                        }
                    }
                } else if let Some(layout) = mimg_addr_layout(*op) {
                    let eff_mask = if *dmask == 0 { 0xF } else { *dmask };
                    let comp_cnt = if layout.is_gather4 {
                        4
                    } else {
                        eff_mask.count_ones()
                    };
                    let data_vgprs = if *d16 { comp_cnt.div_ceil(2) } else { comp_cnt } as u8;
                    if layout.is_get_lod {
                        for d in 0..data_vgprs {
                            if let Some(reg) = checked_vgpr_reg(*vdata, d) {
                                vgprs.insert(reg);
                                written_vgprs.insert(reg);
                            }
                        }
                        continue;
                    }
                    let tex_dim = if layout.is_store || layout.is_load {
                        TexDim::from_storage_mimg_dim(*dim)
                    } else {
                        TexDim::from_mimg_dim(*dim)
                    };
                    let extra_grad_vgprs = if layout.grad_off.is_some() && tex_dim.has_3d_grad() {
                        2u8
                    } else {
                        0u8
                    };
                    let addr_vgprs = layout
                        .total_vgprs
                        .saturating_add(extra_grad_vgprs)
                        .saturating_add(tex_dim.extra_coord_vgprs());
                    if layout.is_store {
                        if stage != ShaderStage::Vertex {
                            if let Some(dispatch) =
                                desc_analysis.inst_storage_tex_dispatches.get(&inst_idx)
                            {
                                match dispatch {
                                    StorageDispatch::TwoWayChoice { keys, .. } => {
                                        for &k in keys {
                                            storage_tex_dims
                                                .entry(k)
                                                .and_modify(|d| *d = d.merge(tex_dim))
                                                .or_insert(tex_dim);
                                        }
                                    }
                                    StorageDispatch::BoundedIndexed { keys, .. } => {
                                        for &k in keys {
                                            storage_tex_dims
                                                .entry(k)
                                                .and_modify(|d| *d = d.merge(tex_dim))
                                                .or_insert(tex_dim);
                                        }
                                    }
                                }
                            } else {
                                let key = desc_analysis
                                    .inst_storage_tex_keys
                                    .get(&inst_idx)
                                    .copied()
                                    .unwrap_or(ResourceKey::RawSlot(*srsrc));
                                storage_tex_dims
                                    .entry(key)
                                    .and_modify(|d| *d = d.merge(tex_dim))
                                    .or_insert(tex_dim);
                            }
                            for a in 0..addr_vgprs {
                                if let Some(reg) = mimg_addr_vgpr(*vaddr, *nsize, nsa_vaddrs, a) {
                                    vgprs.insert(reg);
                                    if !written_vgprs.contains(&reg) {
                                        read_before_write_vgprs.insert(reg);
                                    }
                                }
                            }
                            for d in 0..data_vgprs {
                                if let Some(reg) = checked_vgpr_reg(*vdata, d) {
                                    vgprs.insert(reg);
                                    if !written_vgprs.contains(&reg) {
                                        read_before_write_vgprs.insert(reg);
                                    }
                                }
                            }
                        }
                    } else {
                        let key = desc_analysis
                            .inst_tex_keys
                            .get(&inst_idx)
                            .copied()
                            .unwrap_or(ResourceKey::RawSlot(*srsrc));
                        tex_dims
                            .entry(key)
                            .and_modify(|d| *d = d.merge(tex_dim))
                            .or_insert(tex_dim);
                        if layout.is_load {
                            tex_has_load.insert(key);
                            tex_has_non_compare.insert(key);
                        } else {
                            let skey = desc_analysis
                                .inst_samp_keys
                                .get(&inst_idx)
                                .copied()
                                .unwrap_or(ResourceKey::RawSlot(*ssamp));
                            samp_rsrc_set.insert(skey);
                            if layout.compare_off.is_some() {
                                tex_has_compare.insert(key);
                                samp_has_compare.insert(skey);
                                compare_tex_samp_pairs.insert((key, skey));
                            } else {
                                tex_has_non_compare.insert(key);
                                samp_has_non_compare.insert(skey);
                            }
                        }
                        for a in 0..addr_vgprs {
                            if let Some(reg) = mimg_addr_vgpr(*vaddr, *nsize, nsa_vaddrs, a) {
                                vgprs.insert(reg);
                                if !written_vgprs.contains(&reg) {
                                    read_before_write_vgprs.insert(reg);
                                }
                            }
                        }
                        for d in 0..data_vgprs {
                            if let Some(reg) = checked_vgpr_reg(*vdata, d) {
                                vgprs.insert(reg);
                                written_vgprs.insert(reg);
                            }
                        }
                    }
                }
            }
            Rdna2Detail::Mubuf {
                op,
                offset,
                offen,
                idxen,
                vaddr,
                vdata,
                srsrc,
                soffset,
                ..
            } => {
                if stage == ShaderStage::Vertex && !vertex_storage_buf_insts.contains(&inst_idx) {
                    if let Some(comps) = mubuf_load_components(*op) {
                        has_buffer_fetch = true;
                        let vb_slot = vertex_fetch_vb_slots.get(&inst_idx).copied().unwrap_or(0);
                        let raw_fetch_fmt = mubuf_raw_dword_fetch_format(*op);
                        vertex_buf_fetches
                            .entry((vb_slot, *offset))
                            .and_modify(|p| {
                                if comps > p.components {
                                    p.components = comps;
                                    if raw_fetch_fmt.is_some() {
                                        p.fetch_format = raw_fetch_fmt;
                                    }
                                } else if p.fetch_format.is_none() && raw_fetch_fmt.is_some() {
                                    p.fetch_format = match p.components {
                                        1 => Some("float32"),
                                        2 => Some("float32x2"),
                                        3 => Some("float32x3"),
                                        4 => Some("float32x4"),
                                        _ => raw_fetch_fmt,
                                    };
                                }
                            })
                            .or_insert(VertexFetchPlan {
                                components: comps,
                                component_type: "f32",
                                fetch_format: raw_fetch_fmt,
                            });
                        for d in 0..comps {
                            if let Some(reg) = checked_vgpr_reg(*vdata, d) {
                                vgprs.insert(reg);
                                written_vgprs.insert(reg);
                            }
                        }
                    }
                } else if let Some(buf_op) = mubuf_storage_op(*op) {
                    let writable = buf_op.is_store() && stage != ShaderStage::Vertex;
                    if writable
                        && let Some(dispatch) =
                            desc_analysis.inst_storage_buf_dispatches.get(&inst_idx)
                    {
                        match dispatch {
                            StorageDispatch::TwoWayChoice { keys, .. } => {
                                for &k in keys {
                                    storage_buf_usage.insert(k, true);
                                    non_atomic_storage_buf_keys.insert(k);
                                }
                            }
                            StorageDispatch::BoundedIndexed { keys, .. } => {
                                for &k in keys {
                                    storage_buf_usage.insert(k, true);
                                    non_atomic_storage_buf_keys.insert(k);
                                }
                            }
                        }
                    } else {
                        let key = desc_analysis
                            .inst_storage_buf_keys
                            .get(&inst_idx)
                            .copied()
                            .unwrap_or(ResourceKey::RawSlot(*srsrc));
                        storage_buf_usage
                            .entry(key)
                            .and_modify(|w| *w |= writable)
                            .or_insert(writable);
                        non_atomic_storage_buf_keys.insert(key);
                    }
                    if *offen || *idxen {
                        vgprs.insert(*vaddr);
                        if !written_vgprs.contains(vaddr) {
                            read_before_write_vgprs.insert(*vaddr);
                        }
                    }
                    if *offen
                        && *idxen
                        && let Some(v1) = checked_vgpr_reg(*vaddr, 1)
                    {
                        vgprs.insert(v1);
                        if !written_vgprs.contains(&v1) {
                            read_before_write_vgprs.insert(v1);
                        }
                    }
                    if *soffset <= 105 {
                        sgprs.insert(*soffset);
                        if !written_sgprs.contains(soffset) {
                            read_before_write_sgprs.insert(*soffset);
                        }
                    }
                    let cnt = buf_op.vdata_count();
                    if buf_op.is_store() {
                        for d in 0..cnt {
                            if let Some(reg) = checked_vgpr_reg(*vdata, d) {
                                vgprs.insert(reg);
                                if !written_vgprs.contains(&reg) {
                                    read_before_write_vgprs.insert(reg);
                                }
                            }
                        }
                    } else {
                        for d in 0..cnt {
                            if let Some(reg) = checked_vgpr_reg(*vdata, d) {
                                vgprs.insert(reg);
                                written_vgprs.insert(reg);
                            }
                        }
                    }
                } else if mubuf_is_atomic(*op) && stage != ShaderStage::Vertex {
                    if let Some(dispatch) =
                        desc_analysis.inst_storage_buf_dispatches.get(&inst_idx)
                    {
                        match dispatch {
                            StorageDispatch::TwoWayChoice { keys, .. } => {
                                for &k in keys {
                                    storage_buf_usage.insert(k, true);
                                    atomic_storage_buf_keys.insert(k);
                                }
                            }
                            StorageDispatch::BoundedIndexed { keys, .. } => {
                                for &k in keys {
                                    storage_buf_usage.insert(k, true);
                                    atomic_storage_buf_keys.insert(k);
                                }
                            }
                        }
                    } else {
                        let key = desc_analysis
                            .inst_storage_buf_keys
                            .get(&inst_idx)
                            .copied()
                            .unwrap_or(ResourceKey::RawSlot(*srsrc));
                        storage_buf_usage.insert(key, true);
                        atomic_storage_buf_keys.insert(key);
                    }
                }
            }
            Rdna2Detail::Mtbuf {
                op,
                format,
                offset,
                offen,
                idxen,
                vaddr,
                vdata,
                srsrc,
                soffset,
                ..
            } => {
                if stage == ShaderStage::Vertex && !vertex_storage_buf_insts.contains(&inst_idx) {
                    if let Some(comps) = mtbuf_load_components(*op) {
                        has_buffer_fetch = true;
                        let vb_slot = vertex_fetch_vb_slots.get(&inst_idx).copied().unwrap_or(0);
                        let (attr_offset, shift) = vertex_fetch_slot(true, *op, *format, *offset);
                        let attr_comps = if shift != 0 { 4 } else { comps };
                        let (comp_ty, fetch_fmt) = mtbuf_vertex_format_info(*format, shift != 0);
                        vertex_buf_fetches
                            .entry((vb_slot, attr_offset))
                            .and_modify(|p| {
                                p.components = p.components.max(attr_comps);
                                if p.fetch_format.is_none() && fetch_fmt.is_some() {
                                    p.component_type = comp_ty;
                                    p.fetch_format = fetch_fmt;
                                }
                            })
                            .or_insert(VertexFetchPlan {
                                components: attr_comps,
                                component_type: comp_ty,
                                fetch_format: fetch_fmt,
                            });
                        for d in 0..comps {
                            if let Some(reg) = checked_vgpr_reg(*vdata, d) {
                                vgprs.insert(reg);
                                written_vgprs.insert(reg);
                            }
                        }
                    }
                } else if let Some(buf_op) = mtbuf_storage_op(*op) {
                    let writable = buf_op.is_store() && stage != ShaderStage::Vertex;
                    if writable
                        && let Some(dispatch) =
                            desc_analysis.inst_storage_buf_dispatches.get(&inst_idx)
                    {
                        match dispatch {
                            StorageDispatch::TwoWayChoice { keys, .. } => {
                                for &k in keys {
                                    storage_buf_usage.insert(k, true);
                                    non_atomic_storage_buf_keys.insert(k);
                                }
                            }
                            StorageDispatch::BoundedIndexed { keys, .. } => {
                                for &k in keys {
                                    storage_buf_usage.insert(k, true);
                                    non_atomic_storage_buf_keys.insert(k);
                                }
                            }
                        }
                    } else {
                        let key = desc_analysis
                            .inst_storage_buf_keys
                            .get(&inst_idx)
                            .copied()
                            .unwrap_or(ResourceKey::RawSlot(*srsrc));
                        storage_buf_usage
                            .entry(key)
                            .and_modify(|w| *w |= writable)
                            .or_insert(writable);
                        non_atomic_storage_buf_keys.insert(key);
                    }
                    if *offen || *idxen {
                        vgprs.insert(*vaddr);
                        if !written_vgprs.contains(vaddr) {
                            read_before_write_vgprs.insert(*vaddr);
                        }
                    }
                    if *offen
                        && *idxen
                        && let Some(v1) = checked_vgpr_reg(*vaddr, 1)
                    {
                        vgprs.insert(v1);
                        if !written_vgprs.contains(&v1) {
                            read_before_write_vgprs.insert(v1);
                        }
                    }
                    if *soffset <= 105 {
                        sgprs.insert(*soffset);
                        if !written_sgprs.contains(soffset) {
                            read_before_write_sgprs.insert(*soffset);
                        }
                    }
                    let cnt = buf_op.vdata_count();
                    if buf_op.is_store() {
                        for d in 0..cnt {
                            if let Some(reg) = checked_vgpr_reg(*vdata, d) {
                                vgprs.insert(reg);
                                if !written_vgprs.contains(&reg) {
                                    read_before_write_vgprs.insert(reg);
                                }
                            }
                        }
                    } else {
                        for d in 0..cnt {
                            if let Some(reg) = checked_vgpr_reg(*vdata, d) {
                                vgprs.insert(reg);
                                written_vgprs.insert(reg);
                            }
                        }
                    }
                }
            }
            Rdna2Detail::Ds {
                op,
                addr,
                data0,
                data1,
                vdst,
                ..
            } => {
                if stage == ShaderStage::Compute
                    && let Some(lds_op) = ds_lds_op(*op)
                {
                    vgprs.insert(*addr);
                    if !written_vgprs.contains(addr) {
                        read_before_write_vgprs.insert(*addr);
                    }
                    match lds_op {
                        DsLdsOp::ReadContiguous(n) => {
                            uses_lds = true;
                            for k in 0..n {
                                if let Some(reg) = checked_vgpr_reg(*vdst, k) {
                                    vgprs.insert(reg);
                                    written_vgprs.insert(reg);
                                }
                            }
                        }
                        DsLdsOp::Read2 { .. } => {
                            uses_lds = true;
                            for k in 0..2u8 {
                                if let Some(reg) = checked_vgpr_reg(*vdst, k) {
                                    vgprs.insert(reg);
                                    written_vgprs.insert(reg);
                                }
                            }
                        }
                        DsLdsOp::WriteContiguous(n) => {
                            uses_lds = true;
                            for k in 0..n {
                                if let Some(reg) = checked_vgpr_reg(*data0, k) {
                                    vgprs.insert(reg);
                                    if !written_vgprs.contains(&reg) {
                                        read_before_write_vgprs.insert(reg);
                                    }
                                }
                            }
                        }
                        DsLdsOp::Write2 { .. } => {
                            uses_lds = true;
                            for &reg in &[data0, data1] {
                                vgprs.insert(*reg);
                                if !written_vgprs.contains(reg) {
                                    read_before_write_vgprs.insert(*reg);
                                }
                            }
                        }
                        DsLdsOp::Atomic { returns_value, .. } => {
                            uses_lds = true;
                            uses_lds_atomics = true;
                            vgprs.insert(*data0);
                            if !written_vgprs.contains(data0) {
                                read_before_write_vgprs.insert(*data0);
                            }
                            if returns_value {
                                vgprs.insert(*vdst);
                                written_vgprs.insert(*vdst);
                            }
                        }
                        DsLdsOp::Swizzle => {
                            if !subgroups_active {
                                uses_wave_lds = true;
                            }
                            vgprs.insert(*vdst);
                            written_vgprs.insert(*vdst);
                        }
                        DsLdsOp::Permute => {
                            uses_wave_lds = true;
                            vgprs.insert(*data0);
                            if !written_vgprs.contains(data0) {
                                read_before_write_vgprs.insert(*data0);
                            }
                            vgprs.insert(*vdst);
                            written_vgprs.insert(*vdst);
                        }
                        DsLdsOp::BPermute => {
                            if !subgroups_active {
                                uses_wave_lds = true;
                            }
                            vgprs.insert(*data0);
                            if !written_vgprs.contains(data0) {
                                read_before_write_vgprs.insert(*data0);
                            }
                            vgprs.insert(*vdst);
                            written_vgprs.insert(*vdst);
                        }
                    }
                }
            }
            Rdna2Detail::Exp {
                target,
                en,
                compr,
                vsrc,
                ..
            } => {
                if *compr {
                    if (*en & 0b0001) != 0 {
                        vgprs.insert(vsrc[0]);
                        if !written_vgprs.contains(&vsrc[0]) {
                            read_before_write_vgprs.insert(vsrc[0]);
                        }
                    }
                    if (*en & 0b0100) != 0 {
                        vgprs.insert(vsrc[1]);
                        if !written_vgprs.contains(&vsrc[1]) {
                            read_before_write_vgprs.insert(vsrc[1]);
                        }
                    }
                } else {
                    for (idx, &reg) in vsrc.iter().enumerate() {
                        if (*en & (1 << idx)) != 0 {
                            vgprs.insert(reg);
                            if !written_vgprs.contains(&reg) {
                                read_before_write_vgprs.insert(reg);
                            }
                        }
                    }
                }
                match target {
                    Rdna2ExportTarget::Param(n) if stage == ShaderStage::Vertex || is_mesh => {
                        // Reserve @builtin(position) + up to 15 param locations.
                        vs_param_set.insert(*n % MAX_INTER_STAGE_LOCATIONS);
                    }
                    Rdna2ExportTarget::Mrt(n) if stage == ShaderStage::Fragment => {
                        if *n < MAX_WEBGPU_MRTS {
                            ps_mrt_set.insert(*n);
                        }
                    }
                    Rdna2ExportTarget::MrtZ if stage == ShaderStage::Fragment => {
                        ps_exports_depth = true;
                    }
                    _ => {}
                }
            }
            Rdna2Detail::Sopp { op, .. } => match BranchKind::from_sopp_op(*op) {
                // Branch conditions lifted by `rdna2_cfg` read SCC / VCC / EXEC.
                Some(BranchKind::Scc0 | BranchKind::Scc1) => needs_scc = true,
                Some(BranchKind::Vccz | BranchKind::Vccnz) => needs_vcc = true,
                Some(BranchKind::Execz | BranchKind::Execnz) => needs_exec = true,
                Some(BranchKind::Unconditional) | None => {}
            },
            Rdna2Detail::Flat {
                seg,
                op,
                lds,
                addr,
                saddr,
                vdst,
                ..
            } => {
                if stage != ShaderStage::Vertex
                    && !is_mesh
                    && !*lds
                    && matches!(*seg, 0 | 2)
                    && matches!(*op, 0x08..=0x0F)
                {
                    if *seg == 2 && *saddr != 0x7F {
                        for k in 0..2u8 {
                            if let Some(reg) = checked_sgpr_reg(*saddr, k) {
                                sgprs.insert(reg);
                                if !written_sgprs.contains(&reg) {
                                    read_before_write_sgprs.insert(reg);
                                }
                            }
                        }
                        vgprs.insert(*addr);
                        if !written_vgprs.contains(addr) {
                            read_before_write_vgprs.insert(*addr);
                        }
                    } else {
                        for k in 0..2u8 {
                            if let Some(reg) = checked_vgpr_reg(*addr, k) {
                                vgprs.insert(reg);
                                if !written_vgprs.contains(&reg) {
                                    read_before_write_vgprs.insert(reg);
                                }
                            }
                        }
                    }
                    let dst_count: u8 = match *op {
                        0x0D => 2,
                        0x0F => 3,
                        0x0E => 4,
                        _ => 1,
                    };
                    for k in 0..dst_count {
                        if let Some(reg) = checked_vgpr_reg(*vdst, k) {
                            vgprs.insert(reg);
                            written_vgprs.insert(reg);
                        }
                    }
                }
            }
            Rdna2Detail::Unknown { .. } => {}
        }
    }

    let mut vertex_attrs: Vec<VertexInputAttr> = Vec::new();
    let mut swappc_fetch_attrs: Vec<SwappcFetchAttr> = Vec::new();
    let mut legacy_uv_attr_index: Option<usize> = None;
    let vertex_input_mode = if stage == ShaderStage::Vertex {
        if has_buffer_fetch && !vertex_buf_fetches.is_empty() {
            // Map MUBUF/MTBUF vertex fetches deterministically by ascending (vb_slot, byte_offset):
            //   (0, 0)  -> @location(0) position: vec3 (3-comp) or vec4
            //   (0, 12) -> @location(1+) color: vec4<f32> (R8G8B8A8_UNORM) or exact integer width
            //   (0, 16) -> @location(2+) uv: vec2<f32> (R32G32_FLOAT at +16B)
            //   any other slot/offset -> deterministic sequential @location(N) attr_<offset>
            let mut next_loc: u32 = 0;
            for (&(vb_slot, byte_offset), &fetch) in &vertex_buf_fetches {
                let max_comps = fetch.components;
                let (location, name, components) = match (vb_slot, byte_offset) {
                    (0, 0) => {
                        let loc = next_loc;
                        next_loc = loc + 1;
                        let comps = if fetch.component_type != "f32" {
                            max_comps.clamp(1, 4)
                        } else if max_comps == 3 {
                            3
                        } else {
                            4
                        };
                        (loc, "position".to_string(), comps)
                    }
                    (0, 12) => {
                        let loc = next_loc.max(1);
                        next_loc = loc + 1;
                        let comps = if fetch.component_type != "f32" {
                            max_comps.clamp(1, 4)
                        } else {
                            4
                        };
                        (loc, "color".to_string(), comps)
                    }
                    (0, 16) => {
                        let loc = next_loc.max(2);
                        next_loc = loc + 1;
                        let comps = if fetch.component_type != "f32" {
                            max_comps.clamp(1, 4)
                        } else {
                            2
                        };
                        (loc, "uv".to_string(), comps)
                    }
                    (0, other) => {
                        let loc = next_loc;
                        next_loc = loc + 1;
                        (loc, format!("attr_{other}"), max_comps.clamp(1, 4))
                    }
                    (slot, other) => {
                        let loc = next_loc;
                        next_loc = loc + 1;
                        (loc, format!("vb{slot}_attr_{other}"), max_comps.clamp(1, 4))
                    }
                };
                if location < u32::from(MAX_WEBGPU_LOCATIONS) {
                    vertex_attrs.push(VertexInputAttr {
                        vb_slot,
                        byte_offset: Some(byte_offset),
                        location,
                        name,
                        components,
                        component_type: fetch.component_type,
                        fetch_format: fetch.fetch_format,
                    });
                }
            }
            // Preserve legacy multi-VGPR v4/v5 UV input when the shader reads v4 or v5
            // before writing and has no explicit offset-16 UV buffer fetch.
            let reads_legacy_uv =
                read_before_write_vgprs.contains(&4) || read_before_write_vgprs.contains(&5);
            if reads_legacy_uv
                && !vertex_buf_fetches.contains_key(&(0, 16))
                && next_loc < u32::from(MAX_WEBGPU_LOCATIONS)
            {
                legacy_uv_attr_index = Some(vertex_attrs.len());
                vertex_attrs.push(VertexInputAttr {
                    vb_slot: 0,
                    byte_offset: None,
                    location: next_loc,
                    name: "uv".to_string(),
                    components: 2,
                    component_type: "f32",
                    fetch_format: None,
                });
            }
            if vertex_attrs.iter().any(|a| a.byte_offset.is_some()) {
                VertexInputMode::Attributes
            } else {
                vertex_attrs.clear();
                legacy_uv_attr_index = None;
                vgprs.insert(0);
                VertexInputMode::VertexIndex
            }
        } else if let Some(swappc_idx) = first_swappc_idx {
            // Unlinked Xbox Series FSSM vertex shader calling driver-generated fetch shader via
            // `s_swappc_b64`. Prefer exact FSSM `.meta` VS input table when supplied; otherwise
            // infer 4-VGPR attribute groups (`v4..v7`, `v8..v11`, ...) from VGPRs read before
            // being written after `s_swappc_b64`.
            let (rbw_after_swappc, as_float, as_uint, as_sint) =
                classify_swappc_vgpr_reads(active, swappc_idx);
            let infer_comp_type = |base_vgpr: u8, mask: u8| -> &'static str {
                let mut saw_float = false;
                let mut saw_uint = false;
                let mut saw_sint = false;
                for lane in 0..4u8 {
                    if (mask & (1u8 << lane)) == 0 {
                        continue;
                    }
                    if let Some(reg) = checked_vgpr_reg(base_vgpr, lane) {
                        saw_float |= as_float.contains(&reg);
                        saw_uint |= as_uint.contains(&reg);
                        saw_sint |= as_sint.contains(&reg);
                    }
                }
                if saw_float {
                    "f32"
                } else if saw_uint {
                    "u32"
                } else if saw_sint {
                    "i32"
                } else {
                    "f32"
                }
            };

            let raw_specs: Vec<(u8, u8, u8)> = if let Some(meta) = options.fssm_meta.as_ref()
                && !meta.vs_inputs.is_empty()
            {
                meta.vs_inputs
                    .iter()
                    .map(|inp| {
                        let mask = if inp.mask == 0 { 0x01 } else { inp.mask & 0x0F };
                        let comps = (inp.max_comp + 1).clamp(1, 4);
                        (inp.base_vgpr, mask, comps)
                    })
                    .collect()
            } else {
                // Fallback heuristic: group read-before-write VGPRs (`reg >= 4`) into 4-VGPR
                // fetch-shader output slots `slot = (reg - 4) / 4` (`v4..v7`, `v8..v11`, ...).
                let mut buckets: BTreeMap<u8, u8> = BTreeMap::new();
                for &reg in &rbw_after_swappc {
                    if reg < 4 {
                        continue;
                    }
                    let slot = (reg - 4) / 4;
                    if u32::from(slot) >= u32::from(MAX_WEBGPU_LOCATIONS) {
                        continue;
                    }
                    let lane = (reg - 4) % 4;
                    *buckets.entry(slot).or_insert(0) |= 1u8 << lane;
                }
                buckets
                    .into_iter()
                    .map(|(slot, mask)| {
                        let base_vgpr = 4u8.saturating_add(slot.saturating_mul(4));
                        let highest_lane = (0..4u8).rev().find(|&c| (mask & (1u8 << c)) != 0).unwrap_or(0);
                        (base_vgpr, mask, highest_lane + 1)
                    })
                    .collect()
            };

            let mut cur_byte_offset: u16 = 0;
            for (loc_idx, (base_vgpr, mask, components)) in raw_specs.into_iter().enumerate() {
                let location = loc_idx as u32;
                if location >= u32::from(MAX_WEBGPU_LOCATIONS) {
                    break;
                }
                let component_type = infer_comp_type(base_vgpr, mask);
                for lane in 0..components {
                    if (mask & (1u8 << lane)) != 0
                        && let Some(reg) = checked_vgpr_reg(base_vgpr, lane)
                    {
                        vgprs.insert(reg);
                    }
                }
                swappc_fetch_attrs.push(SwappcFetchAttr {
                    location,
                    base_vgpr,
                    mask,
                    components,
                    component_type,
                });
                vertex_attrs.push(VertexInputAttr {
                    vb_slot: 0,
                    byte_offset: Some(cur_byte_offset),
                    location,
                    name: format!("attr_{location}"),
                    components,
                    component_type,
                    fetch_format: None,
                });
                cur_byte_offset =
                    cur_byte_offset.saturating_add(fssm_attr_packed_byte_stride(components));
            }

            if !swappc_fetch_attrs.is_empty() {
                VertexInputMode::Attributes
            } else {
                vgprs.insert(0);
                VertexInputMode::VertexIndex
            }
        } else {
            // Buffer-pulling / procedural vertex shaders with zero IA VbDesc vertex fetches
            // use `@builtin(vertex_index)` only and emit `vertex_input_mode: "vertex_index"`
            // with no `@location(...)` inputs (S42 / #949).
            vgprs.insert(0);
            VertexInputMode::VertexIndex
        }
    } else {
        VertexInputMode::None
    };

    let workgroup_size = if is_mesh {
        [options.workgroup_size[0].clamp(1, MAX_MESH_VERTICES), 1, 1]
    } else {
        [
            options.workgroup_size[0].max(1),
            options.workgroup_size[1].max(1),
            options.workgroup_size[2].max(1),
        ]
    };
    let needs_m0 = is_mesh || active.iter().any(inst_uses_m0);
    let mesh_output = if is_mesh {
        let (max_vertices, max_primitives) = infer_static_mesh_counts(active)
            .unwrap_or((workgroup_size[0], workgroup_size[0]));
        let vertex_words = match vs_param_set.iter().next_back() {
            Some(&max_param) => {
                let attrs = (u32::from(max_param) + 1).min(MAX_MESH_ATTRIBUTES);
                4 + 4 * attrs
            }
            None => 4,
        };
        let layout = MeshOutputLayout {
            max_vertices: max_vertices.clamp(1, MAX_MESH_VERTICES),
            max_primitives: max_primitives.clamp(1, MAX_MESH_PRIMITIVES),
            vertex_words,
        };
        debug_assert!(layout.is_valid());
        Some(layout)
    } else {
        None
    };
    let mut compute_seed_wg_sgprs: Vec<(u8, u32)> = Vec::new();
    if stage == ShaderStage::Compute {
        vgprs.insert(0);
        let wg_base = options.workgroup_id_sgpr_base.unwrap_or(0);
        for c in 0..3u8 {
            if let Some(reg) = checked_sgpr_reg(wg_base, c)
                && sgprs.contains(&reg)
                && (options.workgroup_id_sgpr_base.is_some()
                    || read_before_write_sgprs.contains(&reg))
            {
                compute_seed_wg_sgprs.push((reg, u32::from(c)));
            }
        }
    }

    let mut ps_mrts: Vec<u8> = ps_mrt_set.into_iter().collect();
    if stage == ShaderStage::Fragment && ps_mrts.is_empty() && !ps_exports_depth {
        ps_mrts.push(0);
    }

    // Canonicalize duplicate/aliased descriptor keys before finalizing resource slot plans:
    // - Power-of-two `stride == 1 << shift` vs `stride == 0` in CBV/lane-indexed heaps
    // - `RootDescriptor { user_sgpr, table_byte_offset }` vs `Table { user_sgpr, table_byte_offset }`
    //   when `user_sgpr` is proven to be a descriptor table in the same stage.
    // Preserves the first-seen key representation so canonical `stride` fields stay unchanged.
    let mut known_table_sgprs: BTreeSet<u32> = BTreeSet::new();
    for src in desc_analysis.cbv_sources.values() {
        if let WgslBindingSource::Table { user_sgpr, .. } = *src {
            known_table_sgprs.insert(user_sgpr);
        }
    }
    for k in tex_dims
        .keys()
        .chain(samp_rsrc_set.iter())
        .chain(storage_buf_usage.keys())
        .chain(storage_tex_dims.keys())
    {
        if let ResourceKey::Table { user_sgpr, .. } = *k {
            known_table_sgprs.insert(user_sgpr);
        }
    }

    let mut indirect_smem_cbv_keys = indirect_smem_cbv_keys;
    let mut cbv_sources = desc_analysis.cbv_sources;
    let mut inst_tex_keys = desc_analysis.inst_tex_keys;
    let mut inst_samp_keys = desc_analysis.inst_samp_keys;
    let mut inst_storage_buf_keys = desc_analysis.inst_storage_buf_keys;
    let mut inst_storage_tex_keys = desc_analysis.inst_storage_tex_keys;
    let mut inst_storage_buf_dispatches = desc_analysis.inst_storage_buf_dispatches;
    let mut inst_storage_tex_dispatches = desc_analysis.inst_storage_tex_dispatches;
    let mut duplicate_bindings_folded = 0usize;

    // 1. Canonicalize CBV keys sharing an identical canonical `WgslBindingSource`.
    {
        let mut primary_by_src: BTreeMap<WgslBindingSource, CbvKey> = BTreeMap::new();
        let mut cbv_remap: BTreeMap<CbvKey, CbvKey> = BTreeMap::new();
        let mut merged_cbv_usage: BTreeMap<CbvKey, CbvUsage> = BTreeMap::new();
        for (key, usage) in cbv_usage {
            let target = if let Some(&raw_src) = cbv_sources.get(&key) {
                let canon = canonicalize_binding_source(raw_src, &known_table_sgprs);
                if let Some(&primary) = primary_by_src.get(&canon) {
                    if primary != key {
                        cbv_remap.insert(key, primary);
                        duplicate_bindings_folded += 1;
                    }
                    primary
                } else {
                    primary_by_src.insert(canon, key);
                    key
                }
            } else {
                key
            };
            merged_cbv_usage
                .entry(target)
                .and_modify(|u| {
                    u.max_vec4_index = u.max_vec4_index.max(usage.max_vec4_index);
                    u.has_dynamic_offset |= usage.has_dynamic_offset;
                })
                .or_insert(usage);
        }
        cbv_usage = merged_cbv_usage;
        if !cbv_remap.is_empty() {
            for k in indirect_smem_cbv_keys.values_mut() {
                if let Some(&primary) = cbv_remap.get(k) {
                    *k = primary;
                }
            }
            for dup in cbv_remap.keys() {
                cbv_sources.remove(dup);
            }
        }
    }

    // Helper to build a `ResourceKey -> primary ResourceKey` canonicalization map for one class.
    let canonicalize_rsrc_keys = |keys: &[ResourceKey], folded: &mut usize| -> BTreeMap<ResourceKey, ResourceKey> {
        let mut primary_by_src: BTreeMap<WgslBindingSource, ResourceKey> = BTreeMap::new();
        let mut remap: BTreeMap<ResourceKey, ResourceKey> = BTreeMap::new();
        for &k in keys {
            if let Some(raw_src) = k.to_source() {
                let canon = canonicalize_binding_source(raw_src, &known_table_sgprs);
                if let Some(&primary) = primary_by_src.get(&canon) {
                    if primary != k {
                        remap.insert(k, primary);
                        *folded += 1;
                    }
                } else {
                    primary_by_src.insert(canon, k);
                }
            }
        }
        remap
    };

    // 2. Canonicalize sampled textures & samplers.
    let tex_key_list: Vec<ResourceKey> = tex_dims.keys().copied().collect();
    let tex_remap = canonicalize_rsrc_keys(&tex_key_list, &mut duplicate_bindings_folded);
    if !tex_remap.is_empty() {
        let map_t = |k: ResourceKey| tex_remap.get(&k).copied().unwrap_or(k);
        let mut new_dims: BTreeMap<ResourceKey, TexDim> = BTreeMap::new();
        for (k, d) in tex_dims {
            let pk = map_t(k);
            new_dims
                .entry(pk)
                .and_modify(|cur| *cur = cur.merge(d))
                .or_insert(d);
        }
        tex_dims = new_dims;
        tex_has_compare = tex_has_compare.into_iter().map(map_t).collect();
        tex_has_non_compare = tex_has_non_compare.into_iter().map(map_t).collect();
        tex_has_load = tex_has_load.into_iter().map(map_t).collect();
        compare_tex_samp_pairs = compare_tex_samp_pairs
            .into_iter()
            .map(|(tk, sk)| (map_t(tk), sk))
            .collect();
        for tk in inst_tex_keys.values_mut() {
            *tk = map_t(*tk);
        }
    }

    let samp_key_list: Vec<ResourceKey> = samp_rsrc_set.iter().copied().collect();
    let samp_remap = canonicalize_rsrc_keys(&samp_key_list, &mut duplicate_bindings_folded);
    if !samp_remap.is_empty() {
        let map_s = |k: ResourceKey| samp_remap.get(&k).copied().unwrap_or(k);
        samp_rsrc_set = samp_rsrc_set.into_iter().map(map_s).collect();
        samp_has_compare = samp_has_compare.into_iter().map(map_s).collect();
        samp_has_non_compare = samp_has_non_compare.into_iter().map(map_s).collect();
        compare_tex_samp_pairs = compare_tex_samp_pairs
            .into_iter()
            .map(|(tk, sk)| (tk, map_s(sk)))
            .collect();
        for sk in inst_samp_keys.values_mut() {
            *sk = map_s(*sk);
        }
    }

    // 3. Canonicalize storage buffers and collapse trivial identical dispatches.
    let sbuf_key_list: Vec<ResourceKey> = storage_buf_usage.keys().copied().collect();
    let sbuf_remap = canonicalize_rsrc_keys(&sbuf_key_list, &mut duplicate_bindings_folded);
    if !sbuf_remap.is_empty() {
        let map_sb = |k: ResourceKey| sbuf_remap.get(&k).copied().unwrap_or(k);
        let mut new_usage: BTreeMap<ResourceKey, bool> = BTreeMap::new();
        for (k, w) in storage_buf_usage {
            let pk = map_sb(k);
            new_usage.entry(pk).and_modify(|cur| *cur |= w).or_insert(w);
        }
        storage_buf_usage = new_usage;
        non_atomic_storage_buf_keys = non_atomic_storage_buf_keys.into_iter().map(map_sb).collect();
        atomic_storage_buf_keys = atomic_storage_buf_keys.into_iter().map(map_sb).collect();
        for k in inst_storage_buf_keys.values_mut() {
            *k = map_sb(*k);
        }
        let mut collapsed_buf_dispatches = Vec::new();
        for (&inst_idx, disp) in &mut inst_storage_buf_dispatches {
            match disp {
                StorageDispatch::TwoWayChoice { keys, .. } => {
                    keys[0] = map_sb(keys[0]);
                    keys[1] = map_sb(keys[1]);
                    if keys[0] == keys[1] {
                        collapsed_buf_dispatches.push((inst_idx, keys[0]));
                    }
                }
                StorageDispatch::BoundedIndexed { keys, .. } => {
                    for k in keys.iter_mut() {
                        *k = map_sb(*k);
                    }
                    if let Some(&first) = keys.first()
                        && keys.iter().all(|&k| k == first)
                    {
                        collapsed_buf_dispatches.push((inst_idx, first));
                    }
                }
            }
        }
        for (inst_idx, single_key) in collapsed_buf_dispatches {
            inst_storage_buf_dispatches.remove(&inst_idx);
            inst_storage_buf_keys.insert(inst_idx, single_key);
        }
    }

    // 4. Canonicalize storage textures and collapse trivial identical dispatches.
    let stex_key_list: Vec<ResourceKey> = storage_tex_dims.keys().copied().collect();
    let stex_remap = canonicalize_rsrc_keys(&stex_key_list, &mut duplicate_bindings_folded);
    if !stex_remap.is_empty() {
        let map_st = |k: ResourceKey| stex_remap.get(&k).copied().unwrap_or(k);
        let mut new_dims: BTreeMap<ResourceKey, TexDim> = BTreeMap::new();
        for (k, d) in storage_tex_dims {
            let pk = map_st(k);
            new_dims
                .entry(pk)
                .and_modify(|cur| *cur = cur.merge(d))
                .or_insert(d);
        }
        storage_tex_dims = new_dims;
        for k in inst_storage_tex_keys.values_mut() {
            *k = map_st(*k);
        }
        let mut collapsed_tex_dispatches = Vec::new();
        for (&inst_idx, disp) in &mut inst_storage_tex_dispatches {
            match disp {
                StorageDispatch::TwoWayChoice { keys, .. } => {
                    keys[0] = map_st(keys[0]);
                    keys[1] = map_st(keys[1]);
                    if keys[0] == keys[1] {
                        collapsed_tex_dispatches.push((inst_idx, keys[0]));
                    }
                }
                StorageDispatch::BoundedIndexed { keys, .. } => {
                    for k in keys.iter_mut() {
                        *k = map_st(*k);
                    }
                    if let Some(&first) = keys.first()
                        && keys.iter().all(|&k| k == first)
                    {
                        collapsed_tex_dispatches.push((inst_idx, first));
                    }
                }
            }
        }
        for (inst_idx, single_key) in collapsed_tex_dispatches {
            inst_storage_tex_dispatches.remove(&inst_idx);
            inst_storage_tex_keys.insert(inst_idx, single_key);
        }
    }

    let atomic_only_storage_keys: BTreeSet<ResourceKey> = atomic_storage_buf_keys
        .difference(&non_atomic_storage_buf_keys)
        .copied()
        .collect();

    // WGSL forbids `textureLoad` on cube/cube-array textures; downgrade any texture that
    // also executes `image_load` from Cube/CubeArray to D2Array.
    for key in &tex_has_load {
        if let Some(dim) = tex_dims.get_mut(key)
            && matches!(*dim, TexDim::Cube | TexDim::CubeArray)
        {
            *dim = TexDim::D2Array;
        }
    }

    // Promote compare-only textures to `texture_depth_*` and compare-only samplers to
    // `sampler_comparison` iff every compare pair `(tex, samp)` agrees via fixed-point closure.
    let mut tex_is_depth: BTreeSet<ResourceKey> = tex_has_compare
        .iter()
        .copied()
        .filter(|k| {
            !tex_has_non_compare.contains(k)
                && tex_dims.get(k).copied().unwrap_or(TexDim::D2).supports_depth()
        })
        .collect();
    let mut samp_is_comparison: BTreeSet<ResourceKey> = samp_has_compare
        .iter()
        .copied()
        .filter(|k| !samp_has_non_compare.contains(k))
        .collect();
    loop {
        let mut changed = false;
        for &(tk, sk) in &compare_tex_samp_pairs {
            let t_depth = tex_is_depth.contains(&tk);
            let s_cmp = samp_is_comparison.contains(&sk);
            if t_depth && !s_cmp {
                tex_is_depth.remove(&tk);
                changed = true;
            } else if !t_depth && s_cmp {
                samp_is_comparison.remove(&sk);
                changed = true;
            }
        }
        if !changed {
            break;
        }
    }

    let min_vec4s = options.min_cbv_vec4_count.clamp(1, MAX_CBV_VEC4_COUNT);
    let cbv_slots: Vec<CbvSlotPlan> = cbv_usage
        .into_iter()
        .map(|(key, usage)| {
            let static_needed = usage.max_vec4_index.saturating_add(1);
            let floor = if usage.has_dynamic_offset {
                min_vec4s.max(DEFAULT_DYNAMIC_CBV_VEC4_COUNT)
            } else {
                min_vec4s
            };
            let vec4_count = static_needed.max(floor).clamp(1, MAX_CBV_VEC4_COUNT);
            let highest_vec4_offset = usage.max_vec4_index.min(vec4_count - 1);
            CbvSlotPlan {
                key,
                vec4_count,
                highest_vec4_offset,
            }
        })
        .collect();
    let tex_slots: Vec<ResourceKey> = tex_dims.keys().copied().collect();
    let samp_slots: Vec<ResourceKey> = samp_rsrc_set.into_iter().collect();
    let storage_buf_slots: Vec<StorageBufSlotPlan> = storage_buf_usage
        .into_iter()
        .map(|(key, writable)| StorageBufSlotPlan { key, writable })
        .collect();
    let storage_tex_slots: Vec<ResourceKey> = storage_tex_dims.keys().copied().collect();

    let mut bvh_ops: u32 = 0;
    let mut raw_address = false;
    let mut atomic64 = false;
    let mut has_lowered_flat_load = false;
    for inst in active {
        if inst.truncated {
            continue;
        }
        match &inst.detail {
            Rdna2Detail::Mimg { op, .. } if matches!(*op, 0xE6 | 0xE7) => {
                bvh_ops = bvh_ops.saturating_add(1);
            }
            Rdna2Detail::Flat { seg, op, lds, .. } if !*lds && matches!(*seg, 0 | 2) => {
                raw_address = true;
                if matches!(*op, 0x08..=0x0F) {
                    has_lowered_flat_load = true;
                } else if matches!(*op, 0x50..=0x5F) {
                    atomic64 = true;
                }
            }
            _ => {}
        }
    }
    let rt_arena = stage != ShaderStage::Vertex
        && mesh_output.is_none()
        && (bvh_ops > 0 || has_lowered_flat_load);

    for writes in desc_analysis.choice_def_writes.values() {
        for &(_, write) in writes {
            if let ChoiceWrite::CopySgpr(reg) = write
                && reg <= MAX_SGPR_INDEX
            {
                sgprs.insert(reg);
            }
        }
    }

    ProgramPlan {
        stage,
        entry_point,
        workgroup_size,
        compute_seed_wg_sgprs,
        active_inst_count,
        vertex_input_mode,
        vertex_attrs,
        swappc_fetch_attrs,
        has_buffer_fetch,
        legacy_uv_attr_index,
        vsharp_fetch_insts,
        indirect_smem_cbv_keys,
        cbv_sources,
        inst_tex_keys,
        inst_samp_keys,
        inst_storage_buf_keys,
        inst_storage_tex_keys,
        inst_storage_buf_dispatches,
        inst_storage_tex_dispatches,
        choice_def_writes: desc_analysis.choice_def_writes,
        choice_count: desc_analysis.choice_count,
        tex_dims,
        tex_is_depth,
        samp_is_comparison,
        storage_tex_dims,
        vertex_storage_buf_insts,
        vertex_fetch_vb_slots,
        cbv_slots,
        tex_slots,
        samp_slots,
        storage_buf_slots,
        storage_tex_slots,
        uses_lds,
        uses_lds_atomics,
        uses_wave_lds,
        wave_emul_mode: options.wave_emul_mode,
        is_wave32,
        frag_attrs: frag_attr_set.into_iter().collect(),
        frag_attr_interp: if options.preserve_fragment_interpolation {
            frag_attr_interp
        } else {
            BTreeMap::new()
        },
        frag_attr_f16_high_channels,
        vs_params: vs_param_set.into_iter().collect(),
        ps_mrts,
        ps_exports_depth,
        vgprs,
        sgprs,
        lane_spill_slots,
        needs_vcc,
        needs_scc,
        needs_exec,
        needs_m0,
        mesh_output,
        rt_arena,
        bvh_ops,
        raw_address,
        atomic64,
        atomic_only_storage_keys,
        duplicate_bindings_folded,
    }
}

// ---------------------------------------------------------------------------
// Naga IR builder
// ---------------------------------------------------------------------------

struct CommonTypes {
    f32_ty: Handle<Type>,
    u32_ty: Handle<Type>,
    i32_ty: Handle<Type>,
    vec2_f32_ty: Handle<Type>,
    vec2_i32_ty: Handle<Type>,
    vec3_f32_ty: Handle<Type>,
    vec3_i32_ty: Handle<Type>,
    vec4_f32_ty: Handle<Type>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ConstExprType {
    F32,
    U32,
    I32,
    Vec2F32,
}

#[derive(Debug, Clone, Copy)]
enum CbvGlobalTarget {
    Uniform {
        global: Handle<GlobalVariable>,
        vec4_count: u32,
    },
    Storage {
        global: Handle<GlobalVariable>,
    },
}

struct IrEmitter {
    module: Module,
    types: CommonTypes,
    vsharp_fetch_insts: BTreeSet<usize>,
    indirect_smem_cbv_keys: BTreeMap<usize, CbvKey>,
    inst_tex_keys: BTreeMap<usize, ResourceKey>,
    inst_samp_keys: BTreeMap<usize, ResourceKey>,
    inst_storage_buf_keys: BTreeMap<usize, ResourceKey>,
    inst_storage_tex_keys: BTreeMap<usize, ResourceKey>,
    inst_storage_buf_dispatches: BTreeMap<usize, StorageDispatch>,
    inst_storage_tex_dispatches: BTreeMap<usize, StorageDispatch>,
    choice_def_writes: BTreeMap<usize, Vec<(usize, ChoiceWrite)>>,
    choice_sel_locals: Vec<Handle<LocalVariable>>,
    vertex_storage_buf_insts: BTreeSet<usize>,
    vertex_fetch_vb_slots: BTreeMap<usize, u32>,
    cb_globals: BTreeMap<CbvKey, CbvGlobalTarget>,
    tex_globals: BTreeMap<ResourceKey, (Handle<GlobalVariable>, TexDim, bool)>,
    samp_globals: BTreeMap<ResourceKey, (Handle<GlobalVariable>, bool)>,
    storage_buf_globals: BTreeMap<ResourceKey, (Handle<GlobalVariable>, bool)>,
    storage_tex_globals: BTreeMap<ResourceKey, (Handle<GlobalVariable>, TexDim)>,
    lds_global: Option<Handle<GlobalVariable>>,
    wave_lds_global: Option<Handle<GlobalVariable>>,
    wave_emul_mode: WaveEmulMode,
    is_wave32: bool,
    emitted_subgroup_ops: bool,
    subgroup_invocation_id_arg: Option<u32>,
    mesh_out_global: Option<Handle<GlobalVariable>>,
    mesh_output: Option<MeshOutputLayout>,
    emitted_bindings: Vec<WgslBindingInfo>,
    atomic_only_slots: BTreeSet<(u32, u32)>,
    cbv_merged_into_storage: usize,
    uniform_promoted_to_storage: usize,
    stage: ShaderStage,
    workgroup_size: [u32; 3],
    compute_seed_wg_sgprs: Vec<(u8, u32)>,
    func: Function,
    helper_u32_to_f32: Option<Handle<Function>>,
    helper_unpack2x16float: Option<Handle<Function>>,
    helper_pack2x16float: Option<Handle<Function>>,
    helper_perm_b32: Option<Handle<Function>>,
    helper_rt_f32: Option<Handle<Function>>,
    helper_rt_u32: Option<Handle<Function>>,
    helper_rt_i32: Option<Handle<Function>>,
    helper_rt_vec2_f32: Option<Handle<Function>>,
    helper_pg6_load32: Option<Handle<Function>>,
    helper_pg6_bvh_intersect: Option<Handle<Function>>,
    vgpr_locals: BTreeMap<u8, Handle<LocalVariable>>,
    sgpr_locals: BTreeMap<u8, Handle<LocalVariable>>,
    /// Dedicated per-`(vgpr, lane)` `u32` locals for lossless `v_writelane_b32`/`v_readlane_b32` SGPR spills.
    lane_spill_locals: BTreeMap<(u8, u8), Handle<LocalVariable>>,
    /// Reverse index `vgpr -> [(lane, local)]` for syncing VALU overwrites & dynamic-lane reads.
    vgpr_lane_slots: BTreeMap<u8, Vec<(u8, Handle<LocalVariable>)>>,
    vcc_local: Option<Handle<LocalVariable>>,
    scc_local: Option<Handle<LocalVariable>>,
    /// Single-lane `exec_mask: u32` (`1u` = this invocation's lane is active).
    exec_local: Option<Handle<LocalVariable>>,
    /// Scalar `m0: u32` register (`124`), used e.g. by `s_sendmsg(MSG_GS_ALLOC_REQ)`.
    m0_local: Option<Handle<LocalVariable>>,
    /// `true` when the body is lowered through `rdna2_cfg` structured control flow.
    structured_cf: bool,
    /// Nesting depth of structured `if` / `loop` / `switch` bodies currently being lowered.
    cf_depth: usize,
    /// Set once a `return` was emitted inside nested control flow: everything after it at the
    /// top level is non-uniform for WGSL uniformity analysis.
    cf_nonuniform_return: bool,
    /// Counter for unique structured-loop / dispatcher local names.
    cf_local_counter: usize,
    /// `true` when a fragment shader executed an `EXP MRT*/MRTZ` with `vm = true` and `done = false`
    /// along the current control-flow path and still owes an `if (exec_mask == 0u) { discard; }`
    /// check before returning (or on a subsequent `done = true` export).
    ps_pending_vm_discard: bool,
    vs_out_local: Option<Handle<LocalVariable>>,
    vs_param_member_index: BTreeMap<u8, u32>,
    ps_out_local: Option<Handle<LocalVariable>>,
    ps_mrt_member_index: BTreeMap<u8, u32>,
    ps_depth_member_index: Option<u32>,
    frag_in_arg: Option<u32>,
    frag_attr_member_index: BTreeMap<u8, u32>,
    frag_attr_f16_high_channels: BTreeSet<(u8, u8)>,
    vs_in_arg: Option<u32>,
    /// Map from `(vb_slot, vertex buffer byte offset)` -> `(VsIn member_index, attr_components, scalar_kind)`.
    vs_attr_by_offset: BTreeMap<(u32, u16), (u32, u8, ScalarKind)>,
    /// Synthesized `(VsIn member_index, SwappcFetchAttr)` list loaded at `s_swappc_b64` in FSSM VS.
    swappc_fetch_loads: Vec<(u32, SwappcFetchAttr)>,
    has_buffer_fetch: bool,
    legacy_uv_member_index: Option<u32>,
    vertex_input_mode: VertexInputMode,
    translated_op_count: usize,
    unsupported_op_count: usize,
    unsupported_comments: Vec<String>,
    /// Sanitized informational comments for ops translated as deliberate no-ops.
    note_comments: Vec<String>,
}

fn align_up(value: u32, align: u32) -> u32 {
    if align <= 1 {
        return value;
    }
    value.saturating_add(align - 1) & !(align - 1)
}

/// Baseline WebGPU `maxBindGroups` limit (`@group(0)` through `@group(3)`).
const MAX_WEBGPU_BIND_GROUPS: u32 = 4;

/// Allocate a unique `@group(group) @binding(N)` slot starting from `preferred`, advancing
/// deterministically (with safe wrap-around) if `preferred` is already claimed so duplicate
/// bindings can never occur.
fn alloc_group_binding(used: &mut BTreeSet<(u32, u32)>, group: u32, preferred: u32) -> u32 {
    debug_assert!(
        group < MAX_WEBGPU_BIND_GROUPS,
        "WebGPU bind group index {group} exceeds baseline limit {MAX_WEBGPU_BIND_GROUPS}"
    );
    let clamped_group = group.min(MAX_WEBGPU_BIND_GROUPS - 1);
    let mut candidate = preferred;
    while !used.insert((clamped_group, candidate)) {
        candidate = candidate.wrapping_add(1);
    }
    candidate
}

/// Allocate a unique `@group(0) @binding(N)` slot starting from `preferred`, advancing
/// deterministically if `preferred` is already claimed so duplicate bindings cannot occur.
fn alloc_group0_binding(used: &mut BTreeSet<(u32, u32)>, preferred: u32) -> u32 {
    alloc_group_binding(used, 0, preferred)
}

fn insert_type(module: &mut Module, name: Option<String>, inner: TypeInner) -> Handle<Type> {
    module
        .types
        .insert(Type { name, inner }, Span::UNDEFINED)
}

impl IrEmitter {
    fn new(plan: &ProgramPlan) -> Self {
        let mut module = Module::default();
        let f32_ty = insert_type(&mut module, None, TypeInner::Scalar(Scalar::F32));
        let u32_ty = insert_type(&mut module, None, TypeInner::Scalar(Scalar::U32));
        let i32_ty = insert_type(&mut module, None, TypeInner::Scalar(Scalar::I32));
        let bool_ty = insert_type(&mut module, None, TypeInner::Scalar(Scalar::BOOL));
        let vec2_f32_ty = insert_type(
            &mut module,
            None,
            TypeInner::Vector {
                size: VectorSize::Bi,
                scalar: Scalar::F32,
            },
        );
        let vec2_i32_ty = insert_type(
            &mut module,
            None,
            TypeInner::Vector {
                size: VectorSize::Bi,
                scalar: Scalar::I32,
            },
        );
        let vec3_f32_ty = insert_type(
            &mut module,
            None,
            TypeInner::Vector {
                size: VectorSize::Tri,
                scalar: Scalar::F32,
            },
        );
        let vec3_i32_ty = insert_type(
            &mut module,
            None,
            TypeInner::Vector {
                size: VectorSize::Tri,
                scalar: Scalar::I32,
            },
        );
        let vec3_u32_ty = insert_type(
            &mut module,
            None,
            TypeInner::Vector {
                size: VectorSize::Tri,
                scalar: Scalar::U32,
            },
        );
        let vec4_f32_ty = insert_type(
            &mut module,
            None,
            TypeInner::Vector {
                size: VectorSize::Quad,
                scalar: Scalar::F32,
            },
        );
        let vec4_u32_ty = insert_type(
            &mut module,
            None,
            TypeInner::Vector {
                size: VectorSize::Quad,
                scalar: Scalar::U32,
            },
        );

        let types = CommonTypes {
            f32_ty,
            u32_ty,
            i32_ty,
            vec2_f32_ty,
            vec2_i32_ty,
            vec3_f32_ty,
            vec3_i32_ty,
            vec4_f32_ty,
        };

        // Uniform constant buffers:
        //   cb0 -> @group(0) @binding(0)
        //   tex0 -> @group(0) @binding(1)
        //   samp0 -> @group(0) @binding(2)
        //   Additional cb1../tex1../samp1.. -> @group(0) @binding(3+)
        let mut cb_globals: BTreeMap<CbvKey, CbvGlobalTarget> = BTreeMap::new();
        let mut tex_globals: BTreeMap<ResourceKey, (Handle<GlobalVariable>, TexDim, bool)> =
            BTreeMap::new();
        let mut samp_globals: BTreeMap<ResourceKey, (Handle<GlobalVariable>, bool)> =
            BTreeMap::new();
        let mut storage_buf_globals: BTreeMap<ResourceKey, (Handle<GlobalVariable>, bool)> =
            BTreeMap::new();
        let mut storage_tex_globals: BTreeMap<ResourceKey, (Handle<GlobalVariable>, TexDim)> =
            BTreeMap::new();
        let mut used_group0_bindings: BTreeSet<(u32, u32)> = BTreeSet::new();
        let mut emitted_bindings: Vec<WgslBindingInfo> = Vec::new();
        let mut atomic_only_slots: BTreeSet<(u32, u32)> = BTreeSet::new();
        let mut cbv_merged_into_storage: usize = 0;
        let mut uniform_promoted_to_storage: usize = 0;
        let mut u32_runtime_arr_ty_opt: Option<Handle<Type>> = None;
        let has_any_reflected_binding = plan
            .cbv_slots
            .iter()
            .any(|s| plan.cbv_sources.contains_key(&s.key))
            || plan.tex_slots.iter().any(|s| s.to_source().is_some())
            || plan.samp_slots.iter().any(|s| s.to_source().is_some())
            || plan
                .storage_buf_slots
                .iter()
                .any(|s| s.key.to_source().is_some())
            || plan
                .storage_tex_slots
                .iter()
                .any(|s| s.to_source().is_some());
        // Sidecar v3 eligibility (`reflect.rs:3920-3937`, `stage_reflection_sidecar.py:348-354`):
        // read-only bindings without a resolved source are emitted as `{"unresolved": true}`,
        // whereas any sourceless writable (`storage` read_write / `storage-texture`) binding
        // disqualifies the stage from the sidecar. Every v3-eligible fragment stage with at least
        // one reflected binding uses `FRAGMENT_REFLECTED_BINDING_OFFSET` (`64+`) so it never
        // collides with vertex `@group(0) @binding(0..63)` in `join_pipeline_layout`.
        let all_writable_bindings_reflected = plan
            .storage_buf_slots
            .iter()
            .filter(|s| s.writable && plan.stage != ShaderStage::Vertex)
            .all(|s| s.key.to_source().is_some())
            && (plan.stage == ShaderStage::Vertex
                || plan
                    .storage_tex_slots
                    .iter()
                    .all(|s| s.to_source().is_some()));
        let fragment_uses_reflected_offset = plan.stage == ShaderStage::Fragment
            && has_any_reflected_binding
            && all_writable_bindings_reflected;
        let binding_base: u32 = if fragment_uses_reflected_offset {
            FRAGMENT_REFLECTED_BINDING_OFFSET
        } else {
            0
        };
        let mut next_extra_binding: u32 =
            if plan.stage == ShaderStage::Fragment && !fragment_uses_reflected_offset {
                FRAGMENT_EXTRA_BINDING_BASE
            } else {
                3
            };

        // Cross-kind CBV <-> storage-buffer deduplication (#2110):
        // When a stage exceeds D3D12's 12-uniform-buffer-per-stage ceiling, first merge any
        // non-RootConstants CBV that shares the exact same canonical descriptor source as an
        // existing storage buffer directly into that storage buffer (zero extra storage buffer
        // slots consumed, keeping all under-limit stages' legacy cb+sbuf layout untouched).
        let mut known_table_sgprs: BTreeSet<u32> = BTreeSet::new();
        for src in plan.cbv_sources.values() {
            if let WgslBindingSource::Table { user_sgpr, .. } = *src {
                known_table_sgprs.insert(user_sgpr);
            }
        }
        for s in &plan.storage_buf_slots {
            if let Some(WgslBindingSource::Table { user_sgpr, .. }) = s.key.to_source() {
                known_table_sgprs.insert(user_sgpr);
            }
        }
        let mut storage_key_by_canon_src: BTreeMap<WgslBindingSource, ResourceKey> =
            BTreeMap::new();
        for s in &plan.storage_buf_slots {
            if let Some(raw_src) = s.key.to_source() {
                let canon = canonicalize_binding_source(raw_src, &known_table_sgprs);
                storage_key_by_canon_src.entry(canon).or_insert(s.key);
            }
        }
        let mut cbv_merged_to_sbuf: Vec<(CbvKey, ResourceKey)> = Vec::new();
        let mut standalone_cbv_slots: Vec<&CbvSlotPlan> = Vec::with_capacity(plan.cbv_slots.len());
        let needs_uniform_reduction =
            plan.cbv_slots.len() > WEBGPU_D3D12_MAX_UNIFORM_BUFFERS_PER_STAGE;
        for slot in &plan.cbv_slots {
            if needs_uniform_reduction
                && let Some(&raw_src) = plan.cbv_sources.get(&slot.key)
                && !matches!(raw_src, WgslBindingSource::RootConstants { .. })
            {
                let canon = canonicalize_binding_source(raw_src, &known_table_sgprs);
                if let Some(&sbuf_key) = storage_key_by_canon_src.get(&canon) {
                    cbv_merged_to_sbuf.push((slot.key, sbuf_key));
                    continue;
                }
            }
            standalone_cbv_slots.push(slot);
        }

        // Excess uniform buffer spillover (#2110):
        // If standalone CBVs still exceed D3D12's 12-uniform-buffer-per-stage hardware ceiling
        // and the stage has storage-buffer headroom (< 16 including runtime-owned `rt_arena` and
        // `ms_out`), promote highest-index non-RootConstants CBVs to `var<storage, read>`
        // (`stage_reflection.cpp` accepts CBV/SRV/UAV for `read_only_storage`, and all guest
        // D3D12 buffers carry `GpuBufferUsage::Storage`).
        let mut promoted_cbv_keys: BTreeSet<CbvKey> = BTreeSet::new();
        let mut remaining_uniforms = standalone_cbv_slots.len();
        let mut effective_storage_buffers = plan.storage_buf_slots.len()
            + if plan.rt_arena {
                RT_ARENA_STORAGE_BUFFER_COUNT
            } else {
                0
            }
            + if plan.mesh_output.is_some() && plan.stage == ShaderStage::Compute {
                MESH_OUTPUT_STORAGE_BUFFER_COUNT
            } else {
                0
            };
        if remaining_uniforms > WEBGPU_D3D12_MAX_UNIFORM_BUFFERS_PER_STAGE
            && effective_storage_buffers < WEBGPU_D3D12_MAX_STORAGE_BUFFERS_PER_STAGE
        {
            for slot in standalone_cbv_slots.iter().rev() {
                if remaining_uniforms <= WEBGPU_D3D12_MAX_UNIFORM_BUFFERS_PER_STAGE
                    || effective_storage_buffers >= WEBGPU_D3D12_MAX_STORAGE_BUFFERS_PER_STAGE
                {
                    break;
                }
                if matches!(
                    plan.cbv_sources.get(&slot.key),
                    Some(WgslBindingSource::RootConstants { .. })
                ) {
                    continue;
                }
                promoted_cbv_keys.insert(slot.key);
                remaining_uniforms -= 1;
                effective_storage_buffers += 1;
            }
        }

        if !standalone_cbv_slots.is_empty() {
            let mut cbv_struct_by_count: BTreeMap<u32, Handle<Type>> = BTreeMap::new();
            let mut uniform_idx = 0usize;
            for (idx, slot) in standalone_cbv_slots.iter().enumerate() {
                if promoted_cbv_keys.contains(&slot.key) {
                    let arr_ty = *u32_runtime_arr_ty_opt.get_or_insert_with(|| {
                        insert_type(
                            &mut module,
                            None,
                            TypeInner::Array {
                                base: u32_ty,
                                size: ArraySize::Dynamic,
                                stride: 4,
                            },
                        )
                    });
                    let preferred_binding = binding_base.saturating_add(next_extra_binding);
                    next_extra_binding = next_extra_binding.saturating_add(1);
                    let binding_num =
                        alloc_group0_binding(&mut used_group0_bindings, preferred_binding);
                    let name = format!("cb{idx}");
                    let g = module.global_variables.append(
                        GlobalVariable {
                            name: Some(name.clone()),
                            space: AddressSpace::Storage {
                                access: StorageAccess::LOAD,
                            },
                            binding: Some(ResourceBinding {
                                group: 0,
                                binding: binding_num,
                            }),
                            ty: arr_ty,
                            init: None,
                            memory_decorations: MemoryDecorations::empty(),
                        },
                        Span::UNDEFINED,
                    );
                    cb_globals.insert(slot.key, CbvGlobalTarget::Storage { global: g });
                    emitted_bindings.push(WgslBindingInfo {
                        group: 0,
                        binding: binding_num,
                        kind: "read-only-storage",
                        name,
                        view_dimension: None,
                        storage_format: None,
                        min_binding_size_bytes: None,
                        highest_vec4_offset: None,
                        source: plan.cbv_sources.get(&slot.key).copied(),
                    });
                    uniform_promoted_to_storage += 1;
                    continue;
                }
                let count = slot.vec4_count.clamp(1, MAX_CBV_VEC4_COUNT);
                let byte_size = count
                    .checked_mul(16)
                    .unwrap_or(MAX_CBV_VEC4_COUNT * 16);
                let highest_vec4_offset = slot.highest_vec4_offset.min(count - 1);
                let this_uniform_idx = uniform_idx;
                uniform_idx += 1;
                let cbv_struct_ty = *cbv_struct_by_count.entry(count).or_insert_with(|| {
                    let arr_ty = insert_type(
                        &mut module,
                        None,
                        TypeInner::Array {
                            base: vec4_u32_ty,
                            size: ArraySize::Constant(
                                NonZeroU32::new(count).unwrap_or(NonZeroU32::MIN),
                            ),
                            stride: 16,
                        },
                    );
                    let struct_name = if this_uniform_idx == 0 {
                        "Rdna2Cbv".to_string()
                    } else {
                        format!("Rdna2Cbv{this_uniform_idx}")
                    };
                    insert_type(
                        &mut module,
                        Some(struct_name),
                        TypeInner::Struct {
                            members: vec![StructMember {
                                name: Some("data".to_string()),
                                ty: arr_ty,
                                binding: None,
                                offset: 0,
                            }],
                            span: byte_size,
                        },
                    )
                });
                let preferred_binding = binding_base.saturating_add(if this_uniform_idx == 0 {
                    0
                } else {
                    let b = next_extra_binding;
                    next_extra_binding = next_extra_binding.saturating_add(1);
                    b
                });
                let binding_num = alloc_group0_binding(&mut used_group0_bindings, preferred_binding);
                let name = format!("cb{this_uniform_idx}");
                let g = module.global_variables.append(
                    GlobalVariable {
                        name: Some(name.clone()),
                        space: AddressSpace::Uniform,
                        binding: Some(ResourceBinding {
                            group: 0,
                            binding: binding_num,
                        }),
                        ty: cbv_struct_ty,
                        init: None,
                        memory_decorations: MemoryDecorations::empty(),
                    },
                    Span::UNDEFINED,
                );
                cb_globals.insert(
                    slot.key,
                    CbvGlobalTarget::Uniform {
                        global: g,
                        vec4_count: count,
                    },
                );
                emitted_bindings.push(WgslBindingInfo {
                    group: 0,
                    binding: binding_num,
                    kind: "uniform",
                    name,
                    view_dimension: None,
                    storage_format: None,
                    min_binding_size_bytes: Some(byte_size),
                    highest_vec4_offset: Some(highest_vec4_offset),
                    source: plan.cbv_sources.get(&slot.key).copied(),
                });
            }
        }

        if !plan.tex_slots.is_empty() {
            let mut tex_2d_ty: Option<Handle<Type>> = None;
            let mut tex_2d_array_ty: Option<Handle<Type>> = None;
            let mut tex_3d_ty: Option<Handle<Type>> = None;
            let mut tex_cube_ty: Option<Handle<Type>> = None;
            let mut tex_cube_array_ty: Option<Handle<Type>> = None;
            let mut tex_depth_2d_ty: Option<Handle<Type>> = None;
            let mut tex_depth_2d_array_ty: Option<Handle<Type>> = None;
            let mut tex_depth_cube_ty: Option<Handle<Type>> = None;
            let mut tex_depth_cube_array_ty: Option<Handle<Type>> = None;
            let mut samp_ty: Option<Handle<Type>> = None;
            let mut cmp_samp_ty: Option<Handle<Type>> = None;
            for (idx, &key) in plan.tex_slots.iter().enumerate() {
                let tex_dim = plan.tex_dims.get(&key).copied().unwrap_or(TexDim::D2);
                let is_depth = plan.tex_is_depth.contains(&key) && tex_dim.supports_depth();
                let tex_ty = if is_depth {
                    match tex_dim {
                        TexDim::D2Array => *tex_depth_2d_array_ty.get_or_insert_with(|| {
                            insert_type(
                                &mut module,
                                None,
                                TypeInner::Image {
                                    dim: ImageDimension::D2,
                                    arrayed: true,
                                    class: ImageClass::Depth { multi: false },
                                },
                            )
                        }),
                        TexDim::Cube => *tex_depth_cube_ty.get_or_insert_with(|| {
                            insert_type(
                                &mut module,
                                None,
                                TypeInner::Image {
                                    dim: ImageDimension::Cube,
                                    arrayed: false,
                                    class: ImageClass::Depth { multi: false },
                                },
                            )
                        }),
                        TexDim::CubeArray => *tex_depth_cube_array_ty.get_or_insert_with(|| {
                            insert_type(
                                &mut module,
                                None,
                                TypeInner::Image {
                                    dim: ImageDimension::Cube,
                                    arrayed: true,
                                    class: ImageClass::Depth { multi: false },
                                },
                            )
                        }),
                        TexDim::D2 | TexDim::D3 => *tex_depth_2d_ty.get_or_insert_with(|| {
                            insert_type(
                                &mut module,
                                None,
                                TypeInner::Image {
                                    dim: ImageDimension::D2,
                                    arrayed: false,
                                    class: ImageClass::Depth { multi: false },
                                },
                            )
                        }),
                    }
                } else {
                    match tex_dim {
                        TexDim::D2Array => *tex_2d_array_ty.get_or_insert_with(|| {
                            insert_type(
                                &mut module,
                                None,
                                TypeInner::Image {
                                    dim: ImageDimension::D2,
                                    arrayed: true,
                                    class: ImageClass::Sampled {
                                        kind: ScalarKind::Float,
                                        multi: false,
                                    },
                                },
                            )
                        }),
                        TexDim::D3 => *tex_3d_ty.get_or_insert_with(|| {
                            insert_type(
                                &mut module,
                                None,
                                TypeInner::Image {
                                    dim: ImageDimension::D3,
                                    arrayed: false,
                                    class: ImageClass::Sampled {
                                        kind: ScalarKind::Float,
                                        multi: false,
                                    },
                                },
                            )
                        }),
                        TexDim::Cube => *tex_cube_ty.get_or_insert_with(|| {
                            insert_type(
                                &mut module,
                                None,
                                TypeInner::Image {
                                    dim: ImageDimension::Cube,
                                    arrayed: false,
                                    class: ImageClass::Sampled {
                                        kind: ScalarKind::Float,
                                        multi: false,
                                    },
                                },
                            )
                        }),
                        TexDim::CubeArray => *tex_cube_array_ty.get_or_insert_with(|| {
                            insert_type(
                                &mut module,
                                None,
                                TypeInner::Image {
                                    dim: ImageDimension::Cube,
                                    arrayed: true,
                                    class: ImageClass::Sampled {
                                        kind: ScalarKind::Float,
                                        multi: false,
                                    },
                                },
                            )
                        }),
                        TexDim::D2 => *tex_2d_ty.get_or_insert_with(|| {
                            insert_type(
                                &mut module,
                                None,
                                TypeInner::Image {
                                    dim: ImageDimension::D2,
                                    arrayed: false,
                                    class: ImageClass::Sampled {
                                        kind: ScalarKind::Float,
                                        multi: false,
                                    },
                                },
                            )
                        }),
                    }
                };
                let preferred_binding = binding_base.saturating_add(if idx == 0 {
                    1
                } else {
                    let b = next_extra_binding;
                    next_extra_binding = next_extra_binding.saturating_add(1);
                    b
                });
                let binding_num = alloc_group0_binding(&mut used_group0_bindings, preferred_binding);
                let name = format!("tex{idx}");
                let g = module.global_variables.append(
                    GlobalVariable {
                        name: Some(name.clone()),
                        space: AddressSpace::Handle,
                        binding: Some(ResourceBinding {
                            group: 0,
                            binding: binding_num,
                        }),
                        ty: tex_ty,
                        init: None,
                        memory_decorations: MemoryDecorations::empty(),
                    },
                    Span::UNDEFINED,
                );
                tex_globals.insert(key, (g, tex_dim, is_depth));
                emitted_bindings.push(WgslBindingInfo {
                    group: 0,
                    binding: binding_num,
                    kind: "texture_2d",
                    name,
                    view_dimension: Some(tex_dim.view_dimension_name()),
                    storage_format: None,
                    min_binding_size_bytes: None,
                    highest_vec4_offset: None,
                    source: key.to_source(),
                });
            }
            for (idx, &key) in plan.samp_slots.iter().enumerate() {
                let is_cmp = plan.samp_is_comparison.contains(&key);
                let ty = if is_cmp {
                    *cmp_samp_ty.get_or_insert_with(|| {
                        insert_type(
                            &mut module,
                            None,
                            TypeInner::Sampler { comparison: true },
                        )
                    })
                } else {
                    *samp_ty.get_or_insert_with(|| {
                        insert_type(
                            &mut module,
                            None,
                            TypeInner::Sampler { comparison: false },
                        )
                    })
                };
                let preferred_binding = binding_base.saturating_add(if idx == 0 {
                    2
                } else {
                    let b = next_extra_binding;
                    next_extra_binding = next_extra_binding.saturating_add(1);
                    b
                });
                let binding_num = alloc_group0_binding(&mut used_group0_bindings, preferred_binding);
                let name = format!("samp{idx}");
                let g = module.global_variables.append(
                    GlobalVariable {
                        name: Some(name.clone()),
                        space: AddressSpace::Handle,
                        binding: Some(ResourceBinding {
                            group: 0,
                            binding: binding_num,
                        }),
                        ty,
                        init: None,
                        memory_decorations: MemoryDecorations::empty(),
                    },
                    Span::UNDEFINED,
                );
                samp_globals.insert(key, (g, is_cmp));
                emitted_bindings.push(WgslBindingInfo {
                    group: 0,
                    binding: binding_num,
                    kind: if is_cmp {
                        "sampler_comparison"
                    } else {
                        "sampler"
                    },
                    name,
                    view_dimension: None,
                    storage_format: None,
                    min_binding_size_bytes: None,
                    highest_vec4_offset: None,
                    source: key.to_source(),
                });
            }
        }

        if !plan.storage_buf_slots.is_empty() {
            let u32_runtime_arr_ty = *u32_runtime_arr_ty_opt.get_or_insert_with(|| {
                insert_type(
                    &mut module,
                    None,
                    TypeInner::Array {
                        base: u32_ty,
                        size: ArraySize::Dynamic,
                        stride: 4,
                    },
                )
            });
            let mut srv_idx = 0u32;
            let mut uav_idx = 0u32;
            for slot in &plan.storage_buf_slots {
                // WebGPU forbids writable storage buffers (`var<storage, read_write>`) in vertex
                // shaders; clamp `writable` to `false` for `ShaderStage::Vertex`.
                let writable = slot.writable && plan.stage != ShaderStage::Vertex;
                let preferred_binding = binding_base.saturating_add(next_extra_binding);
                next_extra_binding = next_extra_binding.saturating_add(1);
                let binding_num = alloc_group0_binding(&mut used_group0_bindings, preferred_binding);
                let (name, access, kind) = if writable {
                    let n = format!("uav_buf{uav_idx}");
                    uav_idx += 1;
                    (
                        n,
                        StorageAccess::LOAD | StorageAccess::STORE,
                        "storage",
                    )
                } else {
                    let n = format!("sbuf{srv_idx}");
                    srv_idx += 1;
                    (n, StorageAccess::LOAD, "read-only-storage")
                };
                let g = module.global_variables.append(
                    GlobalVariable {
                        name: Some(name.clone()),
                        space: AddressSpace::Storage { access },
                        binding: Some(ResourceBinding {
                            group: 0,
                            binding: binding_num,
                        }),
                        ty: u32_runtime_arr_ty,
                        init: None,
                        memory_decorations: MemoryDecorations::empty(),
                    },
                    Span::UNDEFINED,
                );
                storage_buf_globals.insert(slot.key, (g, writable));
                if plan.atomic_only_storage_keys.contains(&slot.key) {
                    atomic_only_slots.insert((0, binding_num));
                }
                emitted_bindings.push(WgslBindingInfo {
                    group: 0,
                    binding: binding_num,
                    kind,
                    name,
                    view_dimension: None,
                    storage_format: None,
                    min_binding_size_bytes: None,
                    highest_vec4_offset: None,
                    source: slot.key.to_source(),
                });
            }
        }

        // Wire cross-kind CBVs that share the exact same canonical descriptor source as an
        // existing storage buffer directly to that storage buffer's `GlobalVariable`.
        for (cbv_key, sbuf_key) in cbv_merged_to_sbuf {
            if let Some(&(g, _)) = storage_buf_globals.get(&sbuf_key) {
                cb_globals.insert(cbv_key, CbvGlobalTarget::Storage { global: g });
                cbv_merged_into_storage += 1;
            }
        }

        // WebGPU forbids writable storage textures in vertex shaders.
        if !plan.storage_tex_slots.is_empty() && plan.stage != ShaderStage::Vertex {
            let mut storage_tex_2d_ty: Option<Handle<Type>> = None;
            let mut storage_tex_2d_array_ty: Option<Handle<Type>> = None;
            let mut storage_tex_3d_ty: Option<Handle<Type>> = None;
            for (idx, &key) in plan.storage_tex_slots.iter().enumerate() {
                let tex_dim = plan.storage_tex_dims.get(&key).copied().unwrap_or(TexDim::D2);
                let storage_tex_ty = match tex_dim {
                    TexDim::D2Array | TexDim::Cube | TexDim::CubeArray => {
                        *storage_tex_2d_array_ty.get_or_insert_with(|| {
                            insert_type(
                                &mut module,
                                None,
                                TypeInner::Image {
                                    dim: ImageDimension::D2,
                                    arrayed: true,
                                    class: ImageClass::Storage {
                                        format: StorageFormat::Rgba8Unorm,
                                        access: StorageAccess::STORE,
                                    },
                                },
                            )
                        })
                    }
                    TexDim::D3 => *storage_tex_3d_ty.get_or_insert_with(|| {
                        insert_type(
                            &mut module,
                            None,
                            TypeInner::Image {
                                dim: ImageDimension::D3,
                                arrayed: false,
                                class: ImageClass::Storage {
                                    format: StorageFormat::Rgba8Unorm,
                                    access: StorageAccess::STORE,
                                },
                            },
                        )
                    }),
                    TexDim::D2 => *storage_tex_2d_ty.get_or_insert_with(|| {
                        insert_type(
                            &mut module,
                            None,
                            TypeInner::Image {
                                dim: ImageDimension::D2,
                                arrayed: false,
                                class: ImageClass::Storage {
                                    format: StorageFormat::Rgba8Unorm,
                                    access: StorageAccess::STORE,
                                },
                            },
                        )
                    }),
                };
                let preferred_binding = binding_base.saturating_add(next_extra_binding);
                next_extra_binding = next_extra_binding.saturating_add(1);
                let binding_num = alloc_group0_binding(&mut used_group0_bindings, preferred_binding);
                let name = format!("uav_tex{idx}");
                let g = module.global_variables.append(
                    GlobalVariable {
                        name: Some(name.clone()),
                        space: AddressSpace::Handle,
                        binding: Some(ResourceBinding {
                            group: 0,
                            binding: binding_num,
                        }),
                        ty: storage_tex_ty,
                        init: None,
                        memory_decorations: MemoryDecorations::empty(),
                    },
                    Span::UNDEFINED,
                );
                storage_tex_globals.insert(key, (g, tex_dim));
                emitted_bindings.push(WgslBindingInfo {
                    group: 0,
                    binding: binding_num,
                    kind: "storage-texture",
                    name,
                    view_dimension: Some(tex_dim.view_dimension_name()),
                    storage_format: Some(WGPU_STORAGE_FORMAT_RGBA8_UNORM),
                    min_binding_size_bytes: None,
                    highest_vec4_offset: None,
                    source: key.to_source(),
                });
            }
        }

        let lds_is_atomic =
            plan.uses_lds && plan.uses_lds_atomics && plan.stage == ShaderStage::Compute;
        let lds_global = if plan.uses_lds && plan.stage == ShaderStage::Compute {
            let lds_elem_ty = if lds_is_atomic {
                insert_type(&mut module, None, TypeInner::Atomic(Scalar::U32))
            } else {
                u32_ty
            };
            let lds_arr_ty = insert_type(
                &mut module,
                None,
                TypeInner::Array {
                    base: lds_elem_ty,
                    size: ArraySize::Constant(
                        NonZeroU32::new(LDS_WORKGROUP_DWORDS).unwrap_or(NonZeroU32::MIN),
                    ),
                    stride: 4,
                },
            );
            Some(module.global_variables.append(
                GlobalVariable {
                    name: Some("lds".to_string()),
                    space: AddressSpace::WorkGroup,
                    binding: None,
                    ty: lds_arr_ty,
                    init: None,
                    memory_decorations: MemoryDecorations::empty(),
                },
                Span::UNDEFINED,
            ))
        } else {
            None
        };

        let wave_lds_global = if plan.uses_wave_lds && plan.stage == ShaderStage::Compute {
            let wave_arr_ty = insert_type(
                &mut module,
                None,
                TypeInner::Array {
                    base: u32_ty,
                    size: ArraySize::Constant(NonZeroU32::new(256).unwrap_or(NonZeroU32::MIN)),
                    stride: 4,
                },
            );
            Some(module.global_variables.append(
                GlobalVariable {
                    name: Some("pg6_wave_lds".to_string()),
                    space: AddressSpace::WorkGroup,
                    binding: None,
                    ty: wave_arr_ty,
                    init: None,
                    memory_decorations: MemoryDecorations::empty(),
                },
                Span::UNDEFINED,
            ))
        } else {
            None
        };

        // Runtime-owned mesh output buffer at `@group(3) @binding(0)` (`state_bridge.h`
        // `bridge::kMeshOutputGroup`). Intentionally NOT pushed into `emitted_bindings` because
        // `StateBridgeDevice::mesh_layout` appends group 3 itself and requires the stage's own
        // reflection bindings to occupy groups 0..2 only.
        let mesh_out_global = if plan.mesh_output.is_some() && plan.stage == ShaderStage::Compute {
            let mesh_binding = alloc_group_binding(&mut used_group0_bindings, MESH_OUTPUT_GROUP, 0);
            let ms_arr_ty = insert_type(
                &mut module,
                None,
                TypeInner::Array {
                    base: u32_ty,
                    size: ArraySize::Dynamic,
                    stride: 4,
                },
            );
            Some(module.global_variables.append(
                GlobalVariable {
                    name: Some("ms_out".to_string()),
                    space: AddressSpace::Storage {
                        access: StorageAccess::LOAD | StorageAccess::STORE,
                    },
                    binding: Some(ResourceBinding {
                        group: MESH_OUTPUT_GROUP,
                        binding: mesh_binding,
                    }),
                    ty: ms_arr_ty,
                    init: None,
                    memory_decorations: MemoryDecorations::empty(),
                },
                Span::UNDEFINED,
            ))
        } else {
            None
        };

        emitted_bindings.sort_by(|a, b| {
            (a.group, a.binding, a.kind, a.name.as_str()).cmp(&(
                b.group,
                b.binding,
                b.kind,
                b.name.as_str(),
            ))
        });
        debug_assert!(
            validate_emitted_bindings(&emitted_bindings, plan.stage).is_ok(),
            "emitted bindings violated WebGPU invariants: {:?}",
            validate_emitted_bindings(&emitted_bindings, plan.stage)
        );

        let mut func = Function {
            name: Some(plan.entry_point.clone()),
            ..Function::default()
        };

        let mut vs_in_arg = None;
        let mut vs_attr_by_offset: BTreeMap<(u32, u16), (u32, u8, ScalarKind)> = BTreeMap::new();
        let mut swappc_fetch_loads: Vec<(u32, SwappcFetchAttr)> = Vec::new();
        let mut legacy_uv_member_index: Option<u32> = None;
        let mut frag_in_arg = None;
        let mut frag_attr_member_index = BTreeMap::new();
        let mut vs_out_local = None;
        let mut vs_param_member_index = BTreeMap::new();
        let mut ps_out_local = None;
        let mut ps_mrt_member_index = BTreeMap::new();
        let mut ps_depth_member_index = None;

        // Stage inputs and outputs
        match plan.stage {
            ShaderStage::Vertex => {
                match plan.vertex_input_mode {
                    VertexInputMode::VertexIndex => {
                        func.arguments.push(FunctionArgument {
                            name: Some("vertex_index".to_string()),
                            ty: u32_ty,
                            binding: Some(Binding::BuiltIn(BuiltIn::VertexIndex)),
                        });
                        vs_in_arg = Some(0);
                    }
                    VertexInputMode::Attributes => {
                        let mut members = vec![StructMember {
                            name: Some("vertex_index".to_string()),
                            ty: u32_ty,
                            binding: Some(Binding::BuiltIn(BuiltIn::VertexIndex)),
                            offset: 0,
                        }];
                        let mut cur_offset = 4u32;
                        let mut max_align = 4u32;
                        let mut vec2_u32_ty: Option<Handle<Type>> = None;
                        let mut vec4_i32_ty: Option<Handle<Type>> = None;
                        for (attr_idx, attr) in plan.vertex_attrs.iter().enumerate() {
                            let scalar_kind = match attr.component_type {
                                "u32" => ScalarKind::Uint,
                                "i32" => ScalarKind::Sint,
                                _ => ScalarKind::Float,
                            };
                            let (ty, align, size) = match (scalar_kind, attr.components) {
                                (ScalarKind::Uint, 1) => (u32_ty, 4u32, 4u32),
                                (ScalarKind::Uint, 2) => (
                                    *vec2_u32_ty.get_or_insert_with(|| {
                                        insert_type(
                                            &mut module,
                                            None,
                                            TypeInner::Vector {
                                                size: VectorSize::Bi,
                                                scalar: Scalar::U32,
                                            },
                                        )
                                    }),
                                    8u32,
                                    8u32,
                                ),
                                (ScalarKind::Uint, 3) => (vec3_u32_ty, 16u32, 12u32),
                                (ScalarKind::Uint, _) => (vec4_u32_ty, 16u32, 16u32),
                                (ScalarKind::Sint, 1) => (i32_ty, 4u32, 4u32),
                                (ScalarKind::Sint, 2) => (vec2_i32_ty, 8u32, 8u32),
                                (ScalarKind::Sint, 3) => (vec3_i32_ty, 16u32, 12u32),
                                (ScalarKind::Sint, _) => (
                                    *vec4_i32_ty.get_or_insert_with(|| {
                                        insert_type(
                                            &mut module,
                                            None,
                                            TypeInner::Vector {
                                                size: VectorSize::Quad,
                                                scalar: Scalar::I32,
                                            },
                                        )
                                    }),
                                    16u32,
                                    16u32,
                                ),
                                (_, 1) => (f32_ty, 4u32, 4u32),
                                (_, 2) => (vec2_f32_ty, 8u32, 8u32),
                                (_, 3) => (vec3_f32_ty, 16u32, 12u32),
                                (_, _) => (vec4_f32_ty, 16u32, 16u32),
                            };
                            cur_offset = align_up(cur_offset, align);
                            max_align = max_align.max(align);
                            let member_idx = members.len() as u32;
                            if let Some(byte_off) = attr.byte_offset {
                                vs_attr_by_offset.insert(
                                    (attr.vb_slot, byte_off),
                                    (member_idx, attr.components, scalar_kind),
                                );
                            }
                            if let Some(&sw_attr) = plan
                                .swappc_fetch_attrs
                                .iter()
                                .find(|a| a.location == attr.location)
                            {
                                swappc_fetch_loads.push((member_idx, sw_attr));
                            }
                            if plan.legacy_uv_attr_index == Some(attr_idx) {
                                legacy_uv_member_index = Some(member_idx);
                            }
                            members.push(StructMember {
                                name: Some(attr.name.clone()),
                                ty,
                                binding: Some(Binding::Location {
                                    location: attr.location,
                                    interpolation: None,
                                    sampling: None,
                                    blend_src: None,
                                    per_primitive: false,
                                }),
                                offset: cur_offset,
                            });
                            cur_offset = cur_offset.saturating_add(size);
                        }
                        let span = align_up(cur_offset, max_align);
                        let vs_in_ty = insert_type(
                            &mut module,
                            Some("VsIn".to_string()),
                            TypeInner::Struct { members, span },
                        );
                        func.arguments.push(FunctionArgument {
                            name: Some("vs_in".to_string()),
                            ty: vs_in_ty,
                            binding: None,
                        });
                        vs_in_arg = Some(0);
                    }
                    VertexInputMode::None => {}
                }

                let mut out_members = vec![StructMember {
                    name: Some("position".to_string()),
                    ty: vec4_f32_ty,
                    binding: Some(Binding::BuiltIn(BuiltIn::Position { invariant: false })),
                    offset: 0,
                }];
                let mut offset = 16u32;
                for &param_idx in &plan.vs_params {
                    let member_idx = out_members.len() as u32;
                    vs_param_member_index.insert(param_idx, member_idx);
                    out_members.push(StructMember {
                        name: Some(format!("param_{param_idx}")),
                        ty: vec4_f32_ty,
                        binding: Some(Binding::Location {
                            location: u32::from(param_idx),
                            interpolation: Some(Interpolation::Perspective),
                            sampling: Some(Sampling::Center),
                            blend_src: None,
                            per_primitive: false,
                        }),
                        offset,
                    });
                    offset += 16;
                }
                let vs_out_ty = insert_type(
                    &mut module,
                    Some("VsOut".to_string()),
                    TypeInner::Struct {
                        members: out_members,
                        span: offset,
                    },
                );
                func.result = Some(FunctionResult {
                    ty: vs_out_ty,
                    binding: None,
                });
                let out_local = func.local_variables.append(
                    LocalVariable {
                        name: Some("vs_out".to_string()),
                        ty: vs_out_ty,
                        init: None,
                    },
                    Span::UNDEFINED,
                );
                vs_out_local = Some(out_local);
            }
            ShaderStage::Fragment => {
                if !plan.frag_attrs.is_empty() {
                    let mut in_members = Vec::with_capacity(plan.frag_attrs.len());
                    let mut offset = 0u32;
                    for &attr in &plan.frag_attrs {
                        let member_idx = in_members.len() as u32;
                        frag_attr_member_index.insert(attr, member_idx);
                        let interp = plan
                            .frag_attr_interp
                            .get(&attr)
                            .copied()
                            .unwrap_or_default();
                        in_members.push(StructMember {
                            name: Some(format!("attr_{attr}")),
                            ty: vec4_f32_ty,
                            binding: Some(Binding::Location {
                                location: u32::from(attr),
                                interpolation: Some(interp.interpolation),
                                sampling: interp.sampling,
                                blend_src: None,
                                per_primitive: false,
                            }),
                            offset,
                        });
                        offset += 16;
                    }
                    let frag_in_ty = insert_type(
                        &mut module,
                        Some("FragIn".to_string()),
                        TypeInner::Struct {
                            members: in_members,
                            span: offset,
                        },
                    );
                    func.arguments.push(FunctionArgument {
                        name: Some("frag_in".to_string()),
                        ty: frag_in_ty,
                        binding: None,
                    });
                    frag_in_arg = Some(0);
                }

                let mut out_members = Vec::new();
                let mut offset = 0u32;
                for &mrt in &plan.ps_mrts {
                    let member_idx = out_members.len() as u32;
                    ps_mrt_member_index.insert(mrt, member_idx);
                    out_members.push(StructMember {
                        name: Some(format!("mrt_{mrt}")),
                        ty: vec4_f32_ty,
                        binding: Some(Binding::Location {
                            location: u32::from(mrt),
                            interpolation: None,
                            sampling: None,
                            blend_src: None,
                            per_primitive: false,
                        }),
                        offset,
                    });
                    offset += 16;
                }
                if plan.ps_exports_depth {
                    let member_idx = out_members.len() as u32;
                    ps_depth_member_index = Some(member_idx);
                    out_members.push(StructMember {
                        name: Some("frag_depth".to_string()),
                        ty: f32_ty,
                        binding: Some(Binding::BuiltIn(BuiltIn::FragDepth)),
                        offset,
                    });
                    offset += if plan.ps_mrts.is_empty() { 4 } else { 16 };
                }
                let ps_out_ty = insert_type(
                    &mut module,
                    Some("PsOut".to_string()),
                    TypeInner::Struct {
                        members: out_members,
                        span: offset,
                    },
                );
                func.result = Some(FunctionResult {
                    ty: ps_out_ty,
                    binding: None,
                });
                let out_local = func.local_variables.append(
                    LocalVariable {
                        name: Some("ps_out".to_string()),
                        ty: ps_out_ty,
                        init: None,
                    },
                    Span::UNDEFINED,
                );
                ps_out_local = Some(out_local);
            }
            ShaderStage::Compute => {
                func.arguments.push(FunctionArgument {
                    name: Some("local_id".to_string()),
                    ty: vec3_u32_ty,
                    binding: Some(Binding::BuiltIn(BuiltIn::LocalInvocationId)),
                });
                func.arguments.push(FunctionArgument {
                    name: Some("wg_id".to_string()),
                    ty: vec3_u32_ty,
                    binding: Some(Binding::BuiltIn(BuiltIn::WorkGroupId)),
                });
                func.arguments.push(FunctionArgument {
                    name: Some("global_id".to_string()),
                    ty: vec3_u32_ty,
                    binding: Some(Binding::BuiltIn(BuiltIn::GlobalInvocationId)),
                });
                if plan.mesh_output.is_some() {
                    func.arguments.push(FunctionArgument {
                        name: Some("local_idx".to_string()),
                        ty: u32_ty,
                        binding: Some(Binding::BuiltIn(BuiltIn::LocalInvocationIndex)),
                    });
                }
            }
        }

        // Allocate VGPR locals (`var v_i: f32`) and SGPR locals (`var s_i: u32`).
        let mut vgpr_locals = BTreeMap::new();
        for &v in &plan.vgprs {
            let local = func.local_variables.append(
                LocalVariable {
                    name: Some(format!("v_{v}")),
                    ty: f32_ty,
                    init: None,
                },
                Span::UNDEFINED,
            );
            vgpr_locals.insert(v, local);
        }

        let mut sgpr_locals = BTreeMap::new();
        for &s in &plan.sgprs {
            let local = func.local_variables.append(
                LocalVariable {
                    name: Some(format!("s_{s}")),
                    ty: u32_ty,
                    init: None,
                },
                Span::UNDEFINED,
            );
            sgpr_locals.insert(s, local);
        }

        let mut lane_spill_locals = BTreeMap::new();
        let mut vgpr_lane_slots: BTreeMap<u8, Vec<(u8, Handle<LocalVariable>)>> = BTreeMap::new();
        for &(v, lane) in &plan.lane_spill_slots {
            let local = func.local_variables.append(
                LocalVariable {
                    name: Some(format!("lane_v{v}_{lane}")),
                    ty: u32_ty,
                    init: None,
                },
                Span::UNDEFINED,
            );
            lane_spill_locals.insert((v, lane), local);
            vgpr_lane_slots.entry(v).or_default().push((lane, local));
        }

        let vcc_local = if plan.needs_vcc {
            Some(func.local_variables.append(
                LocalVariable {
                    name: Some("vcc".to_string()),
                    ty: bool_ty,
                    init: None,
                },
                Span::UNDEFINED,
            ))
        } else {
            None
        };

        let scc_local = if plan.needs_scc {
            Some(func.local_variables.append(
                LocalVariable {
                    name: Some("scc".to_string()),
                    ty: bool_ty,
                    init: None,
                },
                Span::UNDEFINED,
            ))
        } else {
            None
        };

        let exec_local = if plan.needs_exec {
            Some(func.local_variables.append(
                LocalVariable {
                    name: Some("exec_mask".to_string()),
                    ty: u32_ty,
                    init: None,
                },
                Span::UNDEFINED,
            ))
        } else {
            None
        };

        let m0_local = if plan.needs_m0 {
            Some(func.local_variables.append(
                LocalVariable {
                    name: Some("m0".to_string()),
                    ty: u32_ty,
                    init: None,
                },
                Span::UNDEFINED,
            ))
        } else {
            None
        };

        let mut choice_sel_locals = Vec::with_capacity(plan.choice_count);
        for cid in 0..plan.choice_count {
            let local = func.local_variables.append(
                LocalVariable {
                    name: Some(format!("_pg6_desc_sel{cid}")),
                    ty: u32_ty,
                    init: None,
                },
                Span::UNDEFINED,
            );
            choice_sel_locals.push(local);
        }

        let mut emitter = Self {
            module,
            types,
            vsharp_fetch_insts: plan.vsharp_fetch_insts.clone(),
            indirect_smem_cbv_keys: plan.indirect_smem_cbv_keys.clone(),
            inst_tex_keys: plan.inst_tex_keys.clone(),
            inst_samp_keys: plan.inst_samp_keys.clone(),
            inst_storage_buf_keys: plan.inst_storage_buf_keys.clone(),
            inst_storage_tex_keys: plan.inst_storage_tex_keys.clone(),
            inst_storage_buf_dispatches: plan.inst_storage_buf_dispatches.clone(),
            inst_storage_tex_dispatches: plan.inst_storage_tex_dispatches.clone(),
            choice_def_writes: plan.choice_def_writes.clone(),
            choice_sel_locals,
            vertex_storage_buf_insts: plan.vertex_storage_buf_insts.clone(),
            vertex_fetch_vb_slots: plan.vertex_fetch_vb_slots.clone(),
            cb_globals,
            tex_globals,
            samp_globals,
            storage_buf_globals,
            storage_tex_globals,
            lds_global,
            wave_lds_global,
            wave_emul_mode: plan.wave_emul_mode,
            is_wave32: plan.is_wave32,
            emitted_subgroup_ops: false,
            subgroup_invocation_id_arg: None,
            mesh_out_global,
            mesh_output: plan.mesh_output,
            emitted_bindings,
            atomic_only_slots,
            cbv_merged_into_storage,
            uniform_promoted_to_storage,
            stage: plan.stage,
            workgroup_size: plan.workgroup_size,
            compute_seed_wg_sgprs: plan.compute_seed_wg_sgprs.clone(),
            func,
            helper_u32_to_f32: None,
            helper_unpack2x16float: None,
            helper_pack2x16float: None,
            helper_perm_b32: None,
            helper_rt_f32: None,
            helper_rt_u32: None,
            helper_rt_i32: None,
            helper_rt_vec2_f32: None,
            helper_pg6_load32: None,
            helper_pg6_bvh_intersect: None,
            vgpr_locals,
            sgpr_locals,
            lane_spill_locals,
            vgpr_lane_slots,
            vcc_local,
            scc_local,
            exec_local,
            m0_local,
            structured_cf: false,
            cf_depth: 0,
            cf_nonuniform_return: false,
            cf_local_counter: 0,
            ps_pending_vm_discard: false,
            vs_out_local,
            vs_param_member_index,
            ps_out_local,
            ps_mrt_member_index,
            ps_depth_member_index,
            frag_in_arg,
            frag_attr_member_index,
            frag_attr_f16_high_channels: plan.frag_attr_f16_high_channels.clone(),
            vs_in_arg,
            vs_attr_by_offset,
            swappc_fetch_loads,
            has_buffer_fetch: plan.has_buffer_fetch,
            legacy_uv_member_index,
            vertex_input_mode: plan.vertex_input_mode,
            translated_op_count: 0,
            unsupported_op_count: 0,
            unsupported_comments: Vec::new(),
            note_comments: Vec::new(),
        };

        emitter.emit_prologue();
        emitter
    }

    // -- Expression & statement helpers --

    fn raw_expr(&mut self, expr: Expression) -> Handle<Expression> {
        self.func.expressions.append(expr, Span::UNDEFINED)
    }

    fn emit_expr_raw(&mut self, expr: Expression) -> Handle<Expression> {
        let h = self.func.expressions.append(expr, Span::UNDEFINED);
        self.func
            .body
            .push(Statement::Emit(Range::new_from_bounds(h, h)), Span::UNDEFINED);
        h
    }

    fn is_const_expr(&self, h: Handle<Expression>) -> bool {
        match self.func.expressions[h] {
            Expression::Literal(_) | Expression::ZeroValue(_) => true,
            Expression::Unary { expr, .. } | Expression::As { expr, .. } => {
                self.is_const_expr(expr)
            }
            Expression::Binary { left, right, .. } => {
                self.is_const_expr(left) && self.is_const_expr(right)
            }
            Expression::Select {
                condition,
                accept,
                reject,
            } => {
                self.is_const_expr(condition)
                    && self.is_const_expr(accept)
                    && self.is_const_expr(reject)
            }
            Expression::Splat { value, .. } => self.is_const_expr(value),
            Expression::Swizzle { vector, .. } => self.is_const_expr(vector),
            Expression::AccessIndex { base, .. } => self.is_const_expr(base),
            Expression::Compose { ref components, .. } => {
                components.iter().all(|&c| self.is_const_expr(c))
            }
            Expression::Math {
                arg,
                arg1,
                arg2,
                arg3,
                ..
            } => {
                self.is_const_expr(arg)
                    && arg1.is_none_or(|a| self.is_const_expr(a))
                    && arg2.is_none_or(|a| self.is_const_expr(a))
                    && arg3.is_none_or(|a| self.is_const_expr(a))
            }
            _ => false,
        }
    }

    fn const_expr_type(&self, h: Handle<Expression>) -> Option<ConstExprType> {
        match self.func.expressions[h] {
            Expression::Literal(Literal::F32(_)) => Some(ConstExprType::F32),
            Expression::Literal(Literal::U32(_)) => Some(ConstExprType::U32),
            Expression::Literal(Literal::I32(_)) => Some(ConstExprType::I32),
            Expression::As { kind, .. } => match kind {
                ScalarKind::Float => Some(ConstExprType::F32),
                ScalarKind::Uint => Some(ConstExprType::U32),
                ScalarKind::Sint => Some(ConstExprType::I32),
                _ => None,
            },
            Expression::Compose { ty, .. } if ty == self.types.vec2_f32_ty => {
                Some(ConstExprType::Vec2F32)
            }
            Expression::Splat {
                size: VectorSize::Bi,
                value,
            } if self.const_expr_type(value) == Some(ConstExprType::F32) => {
                Some(ConstExprType::Vec2F32)
            }
            Expression::Swizzle {
                size: VectorSize::Bi,
                vector,
                ..
            } if self.const_expr_type(vector) == Some(ConstExprType::Vec2F32) => {
                Some(ConstExprType::Vec2F32)
            }
            Expression::AccessIndex { base, .. }
                if self.const_expr_type(base) == Some(ConstExprType::Vec2F32) =>
            {
                Some(ConstExprType::F32)
            }
            Expression::Unary { expr, .. } => self.const_expr_type(expr),
            Expression::Binary { op, left, .. } => match op {
                BinaryOperator::Equal
                | BinaryOperator::NotEqual
                | BinaryOperator::Less
                | BinaryOperator::LessEqual
                | BinaryOperator::Greater
                | BinaryOperator::GreaterEqual
                | BinaryOperator::LogicalAnd
                | BinaryOperator::LogicalOr => None,
                _ => self.const_expr_type(left),
            },
            Expression::Select { accept, .. } => self.const_expr_type(accept),
            Expression::Math { fun, arg, .. } => match fun {
                MathFunction::Unpack2x16float => Some(ConstExprType::Vec2F32),
                MathFunction::Pack2x16float => Some(ConstExprType::U32),
                MathFunction::Dot => Some(ConstExprType::F32),
                _ => self.const_expr_type(arg),
            },
            _ => None,
        }
    }

    fn call_helper_1(
        &mut self,
        func_handle: Handle<Function>,
        arg: Handle<Expression>,
    ) -> Handle<Expression> {
        let res = self
            .func
            .expressions
            .append(Expression::CallResult(func_handle), Span::UNDEFINED);
        self.func.body.push(
            Statement::Call {
                function: func_handle,
                arguments: vec![arg],
                result: Some(res),
            },
            Span::UNDEFINED,
        );
        res
    }

    fn ensure_helper_u32_to_f32(&mut self) -> Handle<Function> {
        if let Some(h) = self.helper_u32_to_f32 {
            return h;
        }
        let mut f = Function {
            name: Some("pg6_u32_bits_to_float".to_string()),
            arguments: vec![FunctionArgument {
                name: Some("x".to_string()),
                ty: self.types.u32_ty,
                binding: None,
            }],
            result: Some(FunctionResult {
                ty: self.types.f32_ty,
                binding: None,
            }),
            ..Function::default()
        };
        let arg = f
            .expressions
            .append(Expression::FunctionArgument(0), Span::UNDEFINED);
        let cast = f.expressions.append(
            Expression::As {
                expr: arg,
                kind: ScalarKind::Float,
                convert: None,
            },
            Span::UNDEFINED,
        );
        f.body
            .push(Statement::Emit(Range::new_from_bounds(cast, cast)), Span::UNDEFINED);
        f.body
            .push(Statement::Return { value: Some(cast) }, Span::UNDEFINED);
        let h = self.module.functions.append(f, Span::UNDEFINED);
        self.helper_u32_to_f32 = Some(h);
        h
    }

    fn call_pg6_u32_to_f32(&mut self, arg: Handle<Expression>) -> Handle<Expression> {
        let f = self.ensure_helper_u32_to_f32();
        self.call_helper_1(f, arg)
    }

    fn ensure_helper_unpack2x16float(&mut self) -> Handle<Function> {
        if let Some(h) = self.helper_unpack2x16float {
            return h;
        }
        let mut f = Function {
            name: Some("pg6_unpack_half_pair".to_string()),
            arguments: vec![FunctionArgument {
                name: Some("x".to_string()),
                ty: self.types.u32_ty,
                binding: None,
            }],
            result: Some(FunctionResult {
                ty: self.types.vec2_f32_ty,
                binding: None,
            }),
            ..Function::default()
        };
        let arg = f
            .expressions
            .append(Expression::FunctionArgument(0), Span::UNDEFINED);
        let unpacked = f.expressions.append(
            Expression::Math {
                fun: MathFunction::Unpack2x16float,
                arg,
                arg1: None,
                arg2: None,
                arg3: None,
            },
            Span::UNDEFINED,
        );
        f.body.push(
            Statement::Emit(Range::new_from_bounds(unpacked, unpacked)),
            Span::UNDEFINED,
        );
        f.body.push(
            Statement::Return {
                value: Some(unpacked),
            },
            Span::UNDEFINED,
        );
        let h = self.module.functions.append(f, Span::UNDEFINED);
        self.helper_unpack2x16float = Some(h);
        h
    }

    fn call_pg6_unpack2x16float(&mut self, arg: Handle<Expression>) -> Handle<Expression> {
        let f = self.ensure_helper_unpack2x16float();
        self.call_helper_1(f, arg)
    }

    fn ensure_helper_pack2x16float(&mut self) -> Handle<Function> {
        if let Some(h) = self.helper_pack2x16float {
            return h;
        }
        let mut f = Function {
            name: Some("pg6_pack_half_pair".to_string()),
            arguments: vec![FunctionArgument {
                name: Some("v".to_string()),
                ty: self.types.vec2_f32_ty,
                binding: None,
            }],
            result: Some(FunctionResult {
                ty: self.types.u32_ty,
                binding: None,
            }),
            ..Function::default()
        };
        let arg = f
            .expressions
            .append(Expression::FunctionArgument(0), Span::UNDEFINED);
        let packed = f.expressions.append(
            Expression::Math {
                fun: MathFunction::Pack2x16float,
                arg,
                arg1: None,
                arg2: None,
                arg3: None,
            },
            Span::UNDEFINED,
        );
        f.body.push(
            Statement::Emit(Range::new_from_bounds(packed, packed)),
            Span::UNDEFINED,
        );
        f.body.push(
            Statement::Return {
                value: Some(packed),
            },
            Span::UNDEFINED,
        );
        let h = self.module.functions.append(f, Span::UNDEFINED);
        self.helper_pack2x16float = Some(h);
        h
    }

    fn call_pg6_pack2x16float(&mut self, arg: Handle<Expression>) -> Handle<Expression> {
        let f = self.ensure_helper_pack2x16float();
        self.call_helper_1(f, arg)
    }

    /// Lazily emit a compact WGSL helper `fn pg6_byte_perm(s0: u32, s1: u32, s2: u32) -> u32`
    /// implementing GFX10.3 `v_perm_b32` with a 4-iteration loop instead of unrolling 101 Naga
    /// expressions at every call site.
    fn ensure_helper_perm_b32(&mut self) -> Handle<Function> {
        if let Some(h) = self.helper_perm_b32 {
            return h;
        }
        let u32_ty = self.types.u32_ty;
        let mut f = Function {
            name: Some("pg6_byte_perm".to_string()),
            arguments: vec![
                FunctionArgument {
                    name: Some("s0".to_string()),
                    ty: u32_ty,
                    binding: None,
                },
                FunctionArgument {
                    name: Some("s1".to_string()),
                    ty: u32_ty,
                    binding: None,
                },
                FunctionArgument {
                    name: Some("s2".to_string()),
                    ty: u32_ty,
                    binding: None,
                },
            ],
            result: Some(FunctionResult {
                ty: u32_ty,
                binding: None,
            }),
            ..Function::default()
        };
        let res_local = f.local_variables.append(
            LocalVariable {
                name: Some("res".to_string()),
                ty: u32_ty,
                init: None,
            },
            Span::UNDEFINED,
        );
        let k_local = f.local_variables.append(
            LocalVariable {
                name: Some("k".to_string()),
                ty: u32_ty,
                init: None,
            },
            Span::UNDEFINED,
        );

        let s0 = f
            .expressions
            .append(Expression::FunctionArgument(0), Span::UNDEFINED);
        let s1 = f
            .expressions
            .append(Expression::FunctionArgument(1), Span::UNDEFINED);
        let s2 = f
            .expressions
            .append(Expression::FunctionArgument(2), Span::UNDEFINED);
        let res_ptr = f
            .expressions
            .append(Expression::LocalVariable(res_local), Span::UNDEFINED);
        let k_ptr = f
            .expressions
            .append(Expression::LocalVariable(k_local), Span::UNDEFINED);

        let lit_u32 = |f: &mut Function, v: u32| {
            f.expressions
                .append(Expression::Literal(Literal::U32(v)), Span::UNDEFINED)
        };
        let emit_in = |f: &mut Function, block: &mut naga::Block, expr: Expression| {
            let h = f.expressions.append(expr, Span::UNDEFINED);
            block.push(Statement::Emit(Range::new_from_bounds(h, h)), Span::UNDEFINED);
            h
        };

        let c0 = lit_u32(&mut f, 0);
        let c1 = lit_u32(&mut f, 1);
        let c2 = lit_u32(&mut f, 2);
        let c3 = lit_u32(&mut f, 3);
        let c4 = lit_u32(&mut f, 4);
        let c8 = lit_u32(&mut f, 8);
        let c12 = lit_u32(&mut f, 12);
        let c15 = lit_u32(&mut f, 15);
        let c31 = lit_u32(&mut f, 31);
        let mask_ff = lit_u32(&mut f, 0xFF);

        // res = 0u; k = 0u;
        f.body.push(
            Statement::Store {
                pointer: res_ptr,
                value: c0,
            },
            Span::UNDEFINED,
        );
        f.body.push(
            Statement::Store {
                pointer: k_ptr,
                value: c0,
            },
            Span::UNDEFINED,
        );

        let mut loop_body = naga::Block::new();
        let k_val = emit_in(&mut f, &mut loop_body, Expression::Load { pointer: k_ptr });
        let done = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::GreaterEqual,
                left: k_val,
                right: c4,
            },
        );
        let mut brk = naga::Block::new();
        brk.push(Statement::Break, Span::UNDEFINED);
        loop_body.push(
            Statement::If {
                condition: done,
                accept: brk,
                reject: naga::Block::new(),
            },
            Span::UNDEFINED,
        );

        let k_sh = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::Multiply,
                left: k_val,
                right: c8,
            },
        );
        let s2_sh = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::ShiftRight,
                left: s2,
                right: k_sh,
            },
        );
        let sel = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::And,
                left: s2_sh,
                right: mask_ff,
            },
        );

        // 0..7: byte from s1 (0..3) or s0 (4..7)
        let bit2 = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::And,
                left: sel,
                right: c4,
            },
        );
        let from_s0 = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::NotEqual,
                left: bit2,
                right: c0,
            },
        );
        let src_word = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Select {
                condition: from_s0,
                accept: s0,
                reject: s1,
            },
        );
        let lane = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::And,
                left: sel,
                right: c3,
            },
        );
        let lane_sh = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::ShiftLeft,
                left: lane,
                right: c3,
            },
        );
        let b_sh = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::ShiftRight,
                left: src_word,
                right: lane_sh,
            },
        );
        let b_in = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::And,
                left: b_sh,
                right: mask_ff,
            },
        );

        // 8..11: sign extension of s1[15], s1[31], s0[15], s0[31]
        let sbit1 = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::And,
                left: sel,
                right: c2,
            },
        );
        let sign_from_s0 = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::NotEqual,
                left: sbit1,
                right: c0,
            },
        );
        let sign_word = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Select {
                condition: sign_from_s0,
                accept: s0,
                reject: s1,
            },
        );
        let sbit0 = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::And,
                left: sel,
                right: c1,
            },
        );
        let sign_hi = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::NotEqual,
                left: sbit0,
                right: c0,
            },
        );
        let sign_pos = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Select {
                condition: sign_hi,
                accept: c31,
                reject: c15,
            },
        );
        let sign_sh = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::ShiftRight,
                left: sign_word,
                right: sign_pos,
            },
        );
        let sign_lsb = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::And,
                left: sign_sh,
                right: c1,
            },
        );
        let is_neg = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::NotEqual,
                left: sign_lsb,
                right: c0,
            },
        );
        let b_sign = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Select {
                condition: is_neg,
                accept: mask_ff,
                reject: c0,
            },
        );

        // 12 -> 0x00, >=13 -> 0xFF
        let is_12 = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::Equal,
                left: sel,
                right: c12,
            },
        );
        let b_const = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Select {
                condition: is_12,
                accept: c0,
                reject: mask_ff,
            },
        );

        let lt8 = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::Less,
                left: sel,
                right: c8,
            },
        );
        let lt12 = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::Less,
                left: sel,
                right: c12,
            },
        );
        let b_hi = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Select {
                condition: lt12,
                accept: b_sign,
                reject: b_const,
            },
        );
        let byte_v = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Select {
                condition: lt8,
                accept: b_in,
                reject: b_hi,
            },
        );
        let placed = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::ShiftLeft,
                left: byte_v,
                right: k_sh,
            },
        );
        let cur_res = emit_in(&mut f, &mut loop_body, Expression::Load { pointer: res_ptr });
        let next_res = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::InclusiveOr,
                left: cur_res,
                right: placed,
            },
        );
        loop_body.push(
            Statement::Store {
                pointer: res_ptr,
                value: next_res,
            },
            Span::UNDEFINED,
        );
        let next_k = emit_in(
            &mut f,
            &mut loop_body,
            Expression::Binary {
                op: BinaryOperator::Add,
                left: k_val,
                right: c1,
            },
        );
        loop_body.push(
            Statement::Store {
                pointer: k_ptr,
                value: next_k,
            },
            Span::UNDEFINED,
        );

        f.body.push(
            Statement::Loop {
                body: loop_body,
                continuing: naga::Block::new(),
                break_if: None,
            },
            Span::UNDEFINED,
        );

        let final_res = f
            .expressions
            .append(Expression::Load { pointer: res_ptr }, Span::UNDEFINED);
        f.body.push(
            Statement::Emit(Range::new_from_bounds(final_res, final_res)),
            Span::UNDEFINED,
        );
        f.body.push(
            Statement::Return {
                value: Some(final_res),
            },
            Span::UNDEFINED,
        );

        let h = self.module.functions.append(f, Span::UNDEFINED);
        self.helper_perm_b32 = Some(h);
        h
    }

    fn call_pg6_byte_perm(
        &mut self,
        s0: Handle<Expression>,
        s1: Handle<Expression>,
        s2: Handle<Expression>,
    ) -> Handle<Expression> {
        let f = self.ensure_helper_perm_b32();
        let res = self
            .func
            .expressions
            .append(Expression::CallResult(f), Span::UNDEFINED);
        self.func.body.push(
            Statement::Call {
                function: f,
                arguments: vec![s0, s1, s2],
                result: Some(res),
            },
            Span::UNDEFINED,
        );
        res
    }

    fn ensure_identity_helper(
        module: &mut Module,
        slot: &mut Option<Handle<Function>>,
        name: &str,
        ty: Handle<Type>,
    ) -> Handle<Function> {
        if let Some(h) = *slot {
            return h;
        }
        let mut f = Function {
            name: Some(name.to_string()),
            arguments: vec![FunctionArgument {
                name: Some("x".to_string()),
                ty,
                binding: None,
            }],
            result: Some(FunctionResult { ty, binding: None }),
            ..Function::default()
        };
        let arg = f
            .expressions
            .append(Expression::FunctionArgument(0), Span::UNDEFINED);
        f.body
            .push(Statement::Return { value: Some(arg) }, Span::UNDEFINED);
        let h = module.functions.append(f, Span::UNDEFINED);
        *slot = Some(h);
        h
    }

    fn call_pg6_rt_f32(&mut self, arg: Handle<Expression>) -> Handle<Expression> {
        let f = Self::ensure_identity_helper(
            &mut self.module,
            &mut self.helper_rt_f32,
            "pg6_runtime_float",
            self.types.f32_ty,
        );
        self.call_helper_1(f, arg)
    }

    fn call_pg6_rt_u32(&mut self, arg: Handle<Expression>) -> Handle<Expression> {
        let f = Self::ensure_identity_helper(
            &mut self.module,
            &mut self.helper_rt_u32,
            "pg6_runtime_uint",
            self.types.u32_ty,
        );
        self.call_helper_1(f, arg)
    }

    fn call_pg6_rt_i32(&mut self, arg: Handle<Expression>) -> Handle<Expression> {
        let f = Self::ensure_identity_helper(
            &mut self.module,
            &mut self.helper_rt_i32,
            "pg6_runtime_sint",
            self.types.i32_ty,
        );
        self.call_helper_1(f, arg)
    }

    fn call_pg6_rt_vec2_f32(&mut self, arg: Handle<Expression>) -> Handle<Expression> {
        let f = Self::ensure_identity_helper(
            &mut self.module,
            &mut self.helper_rt_vec2_f32,
            "pg6_runtime_vec2f",
            self.types.vec2_f32_ty,
        );
        self.call_helper_1(f, arg)
    }

    fn wrap_const_runtime(&mut self, arg: Handle<Expression>) -> Handle<Expression> {
        match self.const_expr_type(arg) {
            Some(ConstExprType::F32) => self.call_pg6_rt_f32(arg),
            Some(ConstExprType::U32) => self.call_pg6_rt_u32(arg),
            Some(ConstExprType::I32) => self.call_pg6_rt_i32(arg),
            Some(ConstExprType::Vec2F32) => self.call_pg6_rt_vec2_f32(arg),
            None => arg,
        }
    }

    fn emit_expr(&mut self, expr: Expression) -> Handle<Expression> {
        match expr {
            // Fold integer/boolean constant binary ops in Rust (wrapping semantics) so Tint
            // WGSL const-eval never rejects shift/add/sub/mul overflow on literal operands,
            // and guard non-finite float const-eval operations through runtime helpers.
            Expression::Binary { op, left, right } => {
                match (&self.func.expressions[left], &self.func.expressions[right]) {
                    (
                        Expression::Literal(Literal::U32(a)),
                        Expression::Literal(Literal::U32(b)),
                    ) => {
                        let (a, b) = (*a, *b);
                        match op {
                            BinaryOperator::Add => return self.lit_u32(a.wrapping_add(b)),
                            BinaryOperator::Subtract => return self.lit_u32(a.wrapping_sub(b)),
                            BinaryOperator::Multiply => return self.lit_u32(a.wrapping_mul(b)),
                            BinaryOperator::Divide => {
                                return self.lit_u32(if b == 0 { 0 } else { a / b });
                            }
                            BinaryOperator::Modulo => {
                                return self.lit_u32(if b == 0 { 0 } else { a % b });
                            }
                            BinaryOperator::And => return self.lit_u32(a & b),
                            BinaryOperator::InclusiveOr => return self.lit_u32(a | b),
                            BinaryOperator::ExclusiveOr => return self.lit_u32(a ^ b),
                            BinaryOperator::ShiftLeft => {
                                return self.lit_u32(a.wrapping_shl(b & 31));
                            }
                            BinaryOperator::ShiftRight => {
                                return self.lit_u32(a.wrapping_shr(b & 31));
                            }
                            BinaryOperator::Equal => return self.lit_bool(a == b),
                            BinaryOperator::NotEqual => return self.lit_bool(a != b),
                            BinaryOperator::Less => return self.lit_bool(a < b),
                            BinaryOperator::LessEqual => return self.lit_bool(a <= b),
                            BinaryOperator::Greater => return self.lit_bool(a > b),
                            BinaryOperator::GreaterEqual => return self.lit_bool(a >= b),
                            _ => {}
                        }
                    }
                    (
                        Expression::Literal(Literal::I32(a)),
                        Expression::Literal(Literal::U32(b)),
                    ) => {
                        let (a, b) = (*a, *b);
                        match op {
                            BinaryOperator::ShiftLeft => {
                                return self.lit_i32(a.wrapping_shl(b & 31));
                            }
                            BinaryOperator::ShiftRight => {
                                return self.lit_i32(a.wrapping_shr(b & 31));
                            }
                            _ => {}
                        }
                    }
                    (
                        Expression::Literal(Literal::I32(a)),
                        Expression::Literal(Literal::I32(b)),
                    ) => {
                        let (a, b) = (*a, *b);
                        match op {
                            BinaryOperator::Add => return self.lit_i32(a.wrapping_add(b)),
                            BinaryOperator::Subtract => return self.lit_i32(a.wrapping_sub(b)),
                            BinaryOperator::Multiply => return self.lit_i32(a.wrapping_mul(b)),
                            BinaryOperator::Divide => {
                                return self.lit_i32(if b == 0 { 0 } else { a.wrapping_div(b) });
                            }
                            BinaryOperator::Modulo => {
                                return self.lit_i32(if b == 0 { 0 } else { a.wrapping_rem(b) });
                            }
                            BinaryOperator::And => return self.lit_i32(a & b),
                            BinaryOperator::InclusiveOr => return self.lit_i32(a | b),
                            BinaryOperator::ExclusiveOr => return self.lit_i32(a ^ b),
                            BinaryOperator::Equal => return self.lit_bool(a == b),
                            BinaryOperator::NotEqual => return self.lit_bool(a != b),
                            BinaryOperator::Less => return self.lit_bool(a < b),
                            BinaryOperator::LessEqual => return self.lit_bool(a <= b),
                            BinaryOperator::Greater => return self.lit_bool(a > b),
                            BinaryOperator::GreaterEqual => return self.lit_bool(a >= b),
                            _ => {}
                        }
                    }
                    (
                        Expression::Literal(Literal::Bool(a)),
                        Expression::Literal(Literal::Bool(b)),
                    ) => {
                        let (a, b) = (*a, *b);
                        match op {
                            BinaryOperator::LogicalAnd => return self.lit_bool(a && b),
                            BinaryOperator::LogicalOr => return self.lit_bool(a || b),
                            BinaryOperator::Equal => return self.lit_bool(a == b),
                            BinaryOperator::NotEqual => return self.lit_bool(a != b),
                            _ => {}
                        }
                    }
                    (
                        Expression::Literal(Literal::F32(a)),
                        Expression::Literal(Literal::F32(b)),
                    ) => {
                        let (a, b) = (*a, *b);
                        let unsafe_const = match op {
                            BinaryOperator::Add => !(a + b).is_finite(),
                            BinaryOperator::Subtract => !(a - b).is_finite(),
                            BinaryOperator::Multiply => !(a * b).is_finite(),
                            BinaryOperator::Divide => b == 0.0 || !(a / b).is_finite(),
                            _ => false,
                        };
                        if unsafe_const {
                            let rt_left = self.call_pg6_rt_f32(left);
                            return self.emit_expr_raw(Expression::Binary {
                                op,
                                left: rt_left,
                                right,
                            });
                        }
                    }
                    _ => {
                        if matches!(
                            op,
                            BinaryOperator::Add
                                | BinaryOperator::Subtract
                                | BinaryOperator::Multiply
                                | BinaryOperator::Divide
                                | BinaryOperator::Modulo
                                | BinaryOperator::ShiftLeft
                                | BinaryOperator::ShiftRight
                        ) && self.is_const_expr(left)
                            && self.is_const_expr(right)
                        {
                            let rt_left = self.wrap_const_runtime(left);
                            return self.emit_expr_raw(Expression::Binary {
                                op,
                                left: rt_left,
                                right,
                            });
                        }
                    }
                }
                self.emit_expr_raw(Expression::Binary { op, left, right })
            }
            Expression::Unary { op, expr: inner } => {
                match (op, &self.func.expressions[inner]) {
                    (UnaryOperator::BitwiseNot, Expression::Literal(Literal::U32(a))) => {
                        return self.lit_u32(!*a);
                    }
                    (UnaryOperator::BitwiseNot, Expression::Literal(Literal::I32(a))) => {
                        return self.lit_i32(!*a);
                    }
                    (UnaryOperator::Negate, Expression::Literal(Literal::I32(a))) => {
                        return self.lit_i32((*a).wrapping_neg());
                    }
                    (UnaryOperator::LogicalNot, Expression::Literal(Literal::Bool(a))) => {
                        return self.lit_bool(!*a);
                    }
                    _ => {}
                }
                self.emit_expr_raw(Expression::Unary { op, expr: inner })
            }
            Expression::Select {
                condition,
                accept,
                reject,
            } => {
                if let Expression::Literal(Literal::Bool(c)) = self.func.expressions[condition] {
                    return if c { accept } else { reject };
                }
                self.emit_expr_raw(Expression::Select {
                    condition,
                    accept,
                    reject,
                })
            }
            Expression::As {
                expr: inner,
                kind,
                convert,
            } => {
                match convert {
                    None => {
                        match (&self.func.expressions[inner], kind) {
                            (Expression::Literal(Literal::U32(bits)), ScalarKind::Float) => {
                                let bits = *bits;
                                let f = f32::from_bits(bits);
                                if is_safe_wgsl_f32_literal(f) {
                                    return self.raw_expr(Expression::Literal(Literal::F32(f)));
                                }
                                return self.call_pg6_u32_to_f32(inner);
                            }
                            (Expression::Literal(Literal::I32(val)), ScalarKind::Float) => {
                                let bits = *val as u32;
                                let f = f32::from_bits(bits);
                                if is_safe_wgsl_f32_literal(f) {
                                    return self.raw_expr(Expression::Literal(Literal::F32(f)));
                                }
                                let u = self.lit_u32(bits);
                                return self.call_pg6_u32_to_f32(u);
                            }
                            (Expression::Literal(Literal::U32(val)), ScalarKind::Sint) => {
                                return self.lit_i32(*val as i32);
                            }
                            (Expression::Literal(Literal::I32(val)), ScalarKind::Uint) => {
                                return self.lit_u32(*val as u32);
                            }
                            (Expression::Literal(Literal::F32(f)), ScalarKind::Uint) => {
                                return self.lit_u32(f.to_bits());
                            }
                            (Expression::Literal(Literal::F32(f)), ScalarKind::Sint) => {
                                return self.lit_i32(f.to_bits() as i32);
                            }
                            _ if kind == ScalarKind::Float && self.is_const_expr(inner) => {
                                let u_arg =
                                    if self.const_expr_type(inner) == Some(ConstExprType::I32) {
                                        self.emit_expr_raw(Expression::As {
                                            expr: inner,
                                            kind: ScalarKind::Uint,
                                            convert: None,
                                        })
                                    } else {
                                        inner
                                    };
                                return self.call_pg6_u32_to_f32(u_arg);
                            }
                            _ => {}
                        }
                    }
                    Some(4) => match (&self.func.expressions[inner], kind) {
                        (Expression::Literal(Literal::F32(f)), ScalarKind::Uint)
                            if !(0.0..4_294_967_296.0).contains(f) =>
                        {
                            let rt = self.call_pg6_rt_f32(inner);
                            return self.emit_expr_raw(Expression::As {
                                expr: rt,
                                kind,
                                convert,
                            });
                        }
                        (Expression::Literal(Literal::F32(f)), ScalarKind::Sint)
                            if !(-2_147_483_648.0..2_147_483_648.0).contains(f) =>
                        {
                            let rt = self.call_pg6_rt_f32(inner);
                            return self.emit_expr_raw(Expression::As {
                                expr: rt,
                                kind,
                                convert,
                            });
                        }
                        _ if matches!(kind, ScalarKind::Uint | ScalarKind::Sint)
                            && self.is_const_expr(inner)
                            && self.const_expr_type(inner) == Some(ConstExprType::F32) =>
                        {
                            let rt = self.call_pg6_rt_f32(inner);
                            return self.emit_expr_raw(Expression::As {
                                expr: rt,
                                kind,
                                convert,
                            });
                        }
                        _ => {}
                    },
                    _ => {}
                }
                self.emit_expr_raw(Expression::As {
                    expr: inner,
                    kind,
                    convert,
                })
            }
            Expression::Math {
                fun,
                arg,
                arg1,
                arg2,
                arg3,
            } => {
                match fun {
                    MathFunction::Unpack2x16float => {
                        if let Expression::Literal(Literal::U32(bits)) =
                            self.func.expressions[arg]
                        {
                            let lo_non_finite = (bits & 0x7C00) == 0x7C00;
                            let hi_non_finite = ((bits >> 16) & 0x7C00) == 0x7C00;
                            if lo_non_finite || hi_non_finite {
                                return self.call_pg6_unpack2x16float(arg);
                            }
                        } else if self.is_const_expr(arg) {
                            return self.call_pg6_unpack2x16float(arg);
                        }
                    }
                    MathFunction::Pack2x16float => {
                        if self.is_const_expr(arg) {
                            return self.call_pg6_pack2x16float(arg);
                        }
                    }
                    MathFunction::ReverseBits => {
                        if let Expression::Literal(Literal::U32(a)) = self.func.expressions[arg] {
                            return self.lit_u32(a.reverse_bits());
                        }
                    }
                    MathFunction::CountOneBits => {
                        if let Expression::Literal(Literal::U32(a)) = self.func.expressions[arg] {
                            return self.lit_u32(a.count_ones());
                        }
                    }
                    MathFunction::CountLeadingZeros => {
                        if let Expression::Literal(Literal::U32(a)) = self.func.expressions[arg] {
                            return self.lit_u32(a.leading_zeros());
                        }
                    }
                    MathFunction::CountTrailingZeros => {
                        if let Expression::Literal(Literal::U32(a)) = self.func.expressions[arg] {
                            return self.lit_u32(a.trailing_zeros());
                        }
                    }
                    MathFunction::Abs => {
                        if let Expression::Literal(Literal::I32(a)) = self.func.expressions[arg] {
                            return self.lit_i32(a.wrapping_abs());
                        }
                    }
                    MathFunction::Min | MathFunction::Max => {
                        if let Some(a1) = arg1 {
                            match (&self.func.expressions[arg], &self.func.expressions[a1]) {
                                (
                                    Expression::Literal(Literal::U32(a)),
                                    Expression::Literal(Literal::U32(b)),
                                ) => {
                                    let res = if fun == MathFunction::Min {
                                        (*a).min(*b)
                                    } else {
                                        (*a).max(*b)
                                    };
                                    return self.lit_u32(res);
                                }
                                (
                                    Expression::Literal(Literal::I32(a)),
                                    Expression::Literal(Literal::I32(b)),
                                ) => {
                                    let res = if fun == MathFunction::Min {
                                        (*a).min(*b)
                                    } else {
                                        (*a).max(*b)
                                    };
                                    return self.lit_i32(res);
                                }
                                _ => {}
                            }
                        }
                    }
                    MathFunction::Clamp => {
                        if let (Some(lo_h), Some(hi_h)) = (arg1, arg2) {
                            match (
                                &self.func.expressions[arg],
                                &self.func.expressions[lo_h],
                                &self.func.expressions[hi_h],
                            ) {
                                (
                                    Expression::Literal(Literal::U32(a)),
                                    Expression::Literal(Literal::U32(lo)),
                                    Expression::Literal(Literal::U32(hi)),
                                ) => {
                                    return self.lit_u32((*a).max(*lo).min(*hi));
                                }
                                (
                                    Expression::Literal(Literal::I32(a)),
                                    Expression::Literal(Literal::I32(lo)),
                                    Expression::Literal(Literal::I32(hi)),
                                ) => {
                                    return self.lit_i32((*a).max(*lo).min(*hi));
                                }
                                (
                                    _,
                                    Expression::Literal(Literal::F32(lo)),
                                    Expression::Literal(Literal::F32(hi)),
                                ) if *lo > *hi || !lo.is_finite() || !hi.is_finite() => {
                                    let rt_lo = self.call_pg6_rt_f32(lo_h);
                                    return self.emit_expr_raw(Expression::Math {
                                        fun,
                                        arg,
                                        arg1: Some(rt_lo),
                                        arg2,
                                        arg3,
                                    });
                                }
                                (
                                    _,
                                    Expression::Literal(Literal::U32(lo)),
                                    Expression::Literal(Literal::U32(hi)),
                                ) if *lo > *hi => {
                                    let rt_lo = self.call_pg6_rt_u32(lo_h);
                                    return self.emit_expr_raw(Expression::Math {
                                        fun,
                                        arg,
                                        arg1: Some(rt_lo),
                                        arg2,
                                        arg3,
                                    });
                                }
                                (
                                    _,
                                    Expression::Literal(Literal::I32(lo)),
                                    Expression::Literal(Literal::I32(hi)),
                                ) if *lo > *hi => {
                                    let rt_lo = self.call_pg6_rt_i32(lo_h);
                                    return self.emit_expr_raw(Expression::Math {
                                        fun,
                                        arg,
                                        arg1: Some(rt_lo),
                                        arg2,
                                        arg3,
                                    });
                                }
                                _ if self.is_const_expr(arg)
                                    && self.is_const_expr(lo_h)
                                    && self.is_const_expr(hi_h) =>
                                {
                                    let rt = self.wrap_const_runtime(arg);
                                    return self.emit_expr_raw(Expression::Math {
                                        fun,
                                        arg: rt,
                                        arg1,
                                        arg2,
                                        arg3,
                                    });
                                }
                                _ => {}
                            }
                        }
                    }
                    MathFunction::InverseSqrt | MathFunction::Log2 => {
                        let needs_rt = match self.func.expressions[arg] {
                            Expression::Literal(Literal::F32(x)) => x <= 0.0 || !x.is_finite(),
                            _ => self.is_const_expr(arg),
                        };
                        if needs_rt {
                            let rt = self.wrap_const_runtime(arg);
                            return self.emit_expr_raw(Expression::Math {
                                fun,
                                arg: rt,
                                arg1,
                                arg2,
                                arg3,
                            });
                        }
                    }
                    MathFunction::Sqrt => {
                        let needs_rt = match self.func.expressions[arg] {
                            Expression::Literal(Literal::F32(x)) => x < 0.0 || !x.is_finite(),
                            _ => self.is_const_expr(arg),
                        };
                        if needs_rt {
                            let rt = self.wrap_const_runtime(arg);
                            return self.emit_expr_raw(Expression::Math {
                                fun,
                                arg: rt,
                                arg1,
                                arg2,
                                arg3,
                            });
                        }
                    }
                    MathFunction::Exp2 => {
                        let needs_rt = match self.func.expressions[arg] {
                            Expression::Literal(Literal::F32(x)) => x >= 128.0 || !x.is_finite(),
                            _ => self.is_const_expr(arg),
                        };
                        if needs_rt {
                            let rt = self.wrap_const_runtime(arg);
                            return self.emit_expr_raw(Expression::Math {
                                fun,
                                arg: rt,
                                arg1,
                                arg2,
                                arg3,
                            });
                        }
                    }
                    MathFunction::Fma => {
                        if let (Some(a1), Some(a2)) = (arg1, arg2)
                            && self.is_const_expr(arg)
                            && self.is_const_expr(a1)
                            && self.is_const_expr(a2)
                        {
                            let needs_rt = match (
                                &self.func.expressions[arg],
                                &self.func.expressions[a1],
                                &self.func.expressions[a2],
                            ) {
                                (
                                    Expression::Literal(Literal::F32(a)),
                                    Expression::Literal(Literal::F32(b)),
                                    Expression::Literal(Literal::F32(c)),
                                ) => !a.mul_add(*b, *c).is_finite(),
                                _ => true,
                            };
                            if needs_rt {
                                let rt = self.wrap_const_runtime(arg);
                                return self.emit_expr_raw(Expression::Math {
                                    fun,
                                    arg: rt,
                                    arg1,
                                    arg2,
                                    arg3,
                                });
                            }
                        }
                    }
                    _ => {}
                }
                self.emit_expr_raw(Expression::Math {
                    fun,
                    arg,
                    arg1,
                    arg2,
                    arg3,
                })
            }
            other => self.emit_expr_raw(other),
        }
    }

    fn lit_f32(&mut self, value: f32) -> Handle<Expression> {
        if is_safe_wgsl_f32_literal(value) {
            self.raw_expr(Expression::Literal(Literal::F32(value)))
        } else {
            let bits = self.lit_u32(value.to_bits());
            self.call_pg6_u32_to_f32(bits)
        }
    }

    fn lit_f32_from_bits(&mut self, bits: u32) -> Handle<Expression> {
        let f = f32::from_bits(bits);
        if is_safe_wgsl_f32_literal(f) {
            self.raw_expr(Expression::Literal(Literal::F32(f)))
        } else {
            let u = self.lit_u32(bits);
            self.call_pg6_u32_to_f32(u)
        }
    }

    fn lit_u32(&mut self, value: u32) -> Handle<Expression> {
        self.raw_expr(Expression::Literal(Literal::U32(value)))
    }

    fn lit_i32(&mut self, value: i32) -> Handle<Expression> {
        self.raw_expr(Expression::Literal(Literal::I32(value)))
    }

    fn lit_bool(&mut self, value: bool) -> Handle<Expression> {
        self.raw_expr(Expression::Literal(Literal::Bool(value)))
    }

    fn bitcast_f32_to_u32(&mut self, expr: Handle<Expression>) -> Handle<Expression> {
        self.emit_expr(Expression::As {
            expr,
            kind: ScalarKind::Uint,
            convert: None,
        })
    }

    fn bitcast_f32_to_i32(&mut self, expr: Handle<Expression>) -> Handle<Expression> {
        self.emit_expr(Expression::As {
            expr,
            kind: ScalarKind::Sint,
            convert: None,
        })
    }

    fn bitcast_u32_to_f32(&mut self, expr: Handle<Expression>) -> Handle<Expression> {
        self.emit_expr(Expression::As {
            expr,
            kind: ScalarKind::Float,
            convert: None,
        })
    }

    fn bitcast_u32_to_i32(&mut self, expr: Handle<Expression>) -> Handle<Expression> {
        self.emit_expr(Expression::As {
            expr,
            kind: ScalarKind::Sint,
            convert: None,
        })
    }

    fn bitcast_i32_to_u32(&mut self, expr: Handle<Expression>) -> Handle<Expression> {
        self.emit_expr(Expression::As {
            expr,
            kind: ScalarKind::Uint,
            convert: None,
        })
    }

    fn bitcast_i32_to_f32(&mut self, expr: Handle<Expression>) -> Handle<Expression> {
        self.emit_expr(Expression::As {
            expr,
            kind: ScalarKind::Float,
            convert: None,
        })
    }

    fn store_local(&mut self, local: Handle<LocalVariable>, value: Handle<Expression>) {
        let ptr = self.raw_expr(Expression::LocalVariable(local));
        self.func
            .body
            .push(Statement::Store { pointer: ptr, value }, Span::UNDEFINED);
    }

    fn load_local(&mut self, local: Handle<LocalVariable>) -> Handle<Expression> {
        let ptr = self.raw_expr(Expression::LocalVariable(local));
        self.emit_expr(Expression::Load { pointer: ptr })
    }

    fn load_vgpr_f32(&mut self, reg: u8) -> Handle<Expression> {
        if let Some(&local) = self.vgpr_locals.get(&reg) {
            self.load_local(local)
        } else {
            self.lit_f32(0.0)
        }
    }

    fn store_vgpr_f32(&mut self, reg: u8, val: Handle<Expression>) {
        if let Some(&local) = self.vgpr_locals.get(&reg) {
            self.store_local(local, val);
        }
        if let Some(slots) = self.vgpr_lane_slots.get(&reg).cloned() {
            let u = self.bitcast_f32_to_u32(val);
            for (_, slot_local) in slots {
                self.store_local(slot_local, u);
            }
        }
    }

    fn store_vgpr_u32(&mut self, reg: u8, val: Handle<Expression>) {
        let f = self.bitcast_u32_to_f32(val);
        self.store_vgpr_f32(reg, f);
    }

    fn store_vgpr_i32(&mut self, reg: u8, val: Handle<Expression>) {
        let f = self.bitcast_i32_to_f32(val);
        self.store_vgpr_f32(reg, f);
    }

    /// Checked VGPR load at `base + offset`: returns `0.0` when `base + offset > 255`.
    fn load_vgpr_offset_f32(&mut self, base: u8, offset: u8) -> Handle<Expression> {
        match checked_vgpr_reg(base, offset) {
            Some(reg) => self.load_vgpr_f32(reg),
            None => self.lit_f32(0.0),
        }
    }

    /// Checked VGPR f32 store at `base + offset`: no-op when `base + offset > 255`.
    fn store_vgpr_offset_f32(&mut self, base: u8, offset: u8, val: Handle<Expression>) {
        if let Some(reg) = checked_vgpr_reg(base, offset) {
            self.store_vgpr_f32(reg, val);
        }
    }

    /// Checked VGPR u32 store at `base + offset`: no-op when `base + offset > 255`.
    fn store_vgpr_offset_u32(&mut self, base: u8, offset: u8, val: Handle<Expression>) {
        if let Some(reg) = checked_vgpr_reg(base, offset) {
            self.store_vgpr_u32(reg, val);
        }
    }

    /// Checked VGPR i32 store at `base + offset`: no-op when `base + offset > 255`.
    fn store_vgpr_offset_i32(&mut self, base: u8, offset: u8, val: Handle<Expression>) {
        if let Some(reg) = checked_vgpr_reg(base, offset) {
            self.store_vgpr_i32(reg, val);
        }
    }

    /// Pack an `f32` value into the low 16 bits (`[15:0]`) of `v[reg]` as IEEE-754 `f16`
    /// using core WGSL `pack2x16float`, preserving the upper 16 bits (`[31:16]`).
    fn store_vgpr_f16_lo(&mut self, reg: u8, val_f32: Handle<Expression>) {
        let zero = self.lit_f32(0.0);
        let pair = self.emit_expr(Expression::Compose {
            ty: self.types.vec2_f32_ty,
            components: vec![val_f32, zero],
        });
        let packed = self.emit_expr(Expression::Math {
            fun: MathFunction::Pack2x16float,
            arg: pair,
            arg1: None,
            arg2: None,
            arg3: None,
        });
        let mask_lo = self.lit_u32(0x0000_FFFF);
        let new_lo = self.emit_expr(Expression::Binary {
            op: BinaryOperator::And,
            left: packed,
            right: mask_lo,
        });
        let old_f = self.load_vgpr_f32(reg);
        let old_u = self.bitcast_f32_to_u32(old_f);
        let mask_hi = self.lit_u32(0xFFFF_0000);
        let preserved_hi = self.emit_expr(Expression::Binary {
            op: BinaryOperator::And,
            left: old_u,
            right: mask_hi,
        });
        let combined = self.emit_expr(Expression::Binary {
            op: BinaryOperator::InclusiveOr,
            left: preserved_hi,
            right: new_lo,
        });
        self.store_vgpr_u32(reg, combined);
    }

    /// Pack an `f32` value into the high 16 bits (`[31:16]`) of `v[reg]` as IEEE-754 `f16`
    /// using core WGSL `pack2x16float`, preserving the lower 16 bits (`[15:0]`).
    fn store_vgpr_f16_hi(&mut self, reg: u8, val_f32: Handle<Expression>) {
        let zero = self.lit_f32(0.0);
        let pair = self.emit_expr(Expression::Compose {
            ty: self.types.vec2_f32_ty,
            components: vec![zero, val_f32],
        });
        let packed = self.emit_expr(Expression::Math {
            fun: MathFunction::Pack2x16float,
            arg: pair,
            arg1: None,
            arg2: None,
            arg3: None,
        });
        let mask_hi = self.lit_u32(0xFFFF_0000);
        let new_hi = self.emit_expr(Expression::Binary {
            op: BinaryOperator::And,
            left: packed,
            right: mask_hi,
        });
        let old_f = self.load_vgpr_f32(reg);
        let old_u = self.bitcast_f32_to_u32(old_f);
        let mask_lo = self.lit_u32(0x0000_FFFF);
        let preserved_lo = self.emit_expr(Expression::Binary {
            op: BinaryOperator::And,
            left: old_u,
            right: mask_lo,
        });
        let combined = self.emit_expr(Expression::Binary {
            op: BinaryOperator::InclusiveOr,
            left: preserved_lo,
            right: new_hi,
        });
        self.store_vgpr_u32(reg, combined);
    }

    fn load_sgpr_u32(&mut self, reg: u8) -> Handle<Expression> {
        if let Some(&local) = self.sgpr_locals.get(&reg) {
            self.load_local(local)
        } else if reg == 124 {
            self.load_m0()
        } else if reg == 126 {
            self.load_exec()
        } else {
            self.lit_u32(0)
        }
    }

    fn store_sgpr_u32(&mut self, reg: u8, val: Handle<Expression>) {
        if let Some(&local) = self.sgpr_locals.get(&reg) {
            self.store_local(local, val);
        } else if reg == 124 {
            self.store_m0(val);
        } else if reg == 126 {
            // `exec_lo` destination: keep this lane's bit.
            self.store_exec_lane_bit(val);
        }
    }

    fn load_m0(&mut self) -> Handle<Expression> {
        if let Some(local) = self.m0_local {
            self.load_local(local)
        } else {
            self.lit_u32(0)
        }
    }

    fn store_m0(&mut self, val: Handle<Expression>) {
        if let Some(local) = self.m0_local {
            self.store_local(local, val);
        }
    }

    /// Load the single-lane `exec_mask` (`1u` when the model is inactive: all lanes on).
    fn load_exec(&mut self) -> Handle<Expression> {
        if let Some(local) = self.exec_local {
            self.load_local(local)
        } else {
            self.lit_u32(1)
        }
    }

    /// `exec_mask = (val & 1u)` (no-op when the shader never needs `exec_mask`).
    fn store_exec_lane_bit(&mut self, val: Handle<Expression>) {
        if let Some(local) = self.exec_local {
            let one = self.lit_u32(1);
            let bit = self.emit_bin(BinaryOperator::And, val, one);
            self.store_local(local, bit);
        }
    }

    fn load_vcc(&mut self) -> Handle<Expression> {
        if let Some(local) = self.vcc_local {
            self.load_local(local)
        } else {
            self.lit_bool(false)
        }
    }

    fn store_vcc(&mut self, val: Handle<Expression>) {
        if let Some(local) = self.vcc_local {
            self.store_local(local, val);
        }
    }

    fn load_scc(&mut self) -> Handle<Expression> {
        if let Some(local) = self.scc_local {
            self.load_local(local)
        } else {
            self.lit_bool(false)
        }
    }

    fn store_scc(&mut self, val: Handle<Expression>) {
        if let Some(local) = self.scc_local {
            self.store_local(local, val);
        }
    }

    fn emit_prologue(&mut self) {
        // Zero-initialize all declared VGPRs, SGPRs, VCC, SCC, and stage output structs.
        let vgpr_list: Vec<(u8, Handle<LocalVariable>)> =
            self.vgpr_locals.iter().map(|(&k, &v)| (k, v)).collect();
        for (_, local) in &vgpr_list {
            let z = self.lit_f32(0.0);
            self.store_local(*local, z);
        }
        let sgpr_list: Vec<(u8, Handle<LocalVariable>)> =
            self.sgpr_locals.iter().map(|(&k, &v)| (k, v)).collect();
        for (_, local) in &sgpr_list {
            let z = self.lit_u32(0);
            self.store_local(*local, z);
        }
        let lane_list: Vec<Handle<LocalVariable>> =
            self.lane_spill_locals.values().copied().collect();
        for local in lane_list {
            let z = self.lit_u32(0);
            self.store_local(local, z);
        }
        if let Some(vcc) = self.vcc_local {
            let f = self.lit_bool(false);
            self.store_local(vcc, f);
        }
        if let Some(scc) = self.scc_local {
            let f = self.lit_bool(false);
            self.store_local(scc, f);
        }
        if let Some(exec) = self.exec_local {
            // One WGSL invocation models one active wave lane.
            let one = self.lit_u32(1);
            self.store_local(exec, one);
        }
        if let Some(m0) = self.m0_local {
            let z = self.lit_u32(0);
            self.store_local(m0, z);
        }

        // Stage-specific prologue bindings into VGPRs & default output struct values.
        match self.stage {
            ShaderStage::Vertex => {
                if let Some(out_local) = self.vs_out_local {
                    let out_ty = self.func.local_variables[out_local].ty;
                    let zero_struct = self.raw_expr(Expression::ZeroValue(out_ty));
                    self.store_local(out_local, zero_struct);
                    // Default position = vec4<f32>(0.0, 0.0, 0.0, 1.0)
                    let c0 = self.lit_f32(0.0);
                    let c1 = self.lit_f32(0.0);
                    let c2 = self.lit_f32(0.0);
                    let c3 = self.lit_f32(1.0);
                    let default_pos = self.emit_expr(Expression::Compose {
                        ty: self.types.vec4_f32_ty,
                        components: vec![c0, c1, c2, c3],
                    });
                    let base_ptr = self.raw_expr(Expression::LocalVariable(out_local));
                    let pos_ptr = self.emit_expr(Expression::AccessIndex {
                        base: base_ptr,
                        index: 0,
                    });
                    self.func.body.push(
                        Statement::Store {
                            pointer: pos_ptr,
                            value: default_pos,
                        },
                        Span::UNDEFINED,
                    );
                }

                if let Some(arg_idx) = self.vs_in_arg {
                    match self.vertex_input_mode {
                        VertexInputMode::VertexIndex => {
                            let vi = self.raw_expr(Expression::FunctionArgument(arg_idx));
                            self.store_vgpr_u32(0, vi);
                        }
                        VertexInputMode::Attributes => {
                            let vs_in = self.raw_expr(Expression::FunctionArgument(arg_idx));
                            if self.has_buffer_fetch || !self.swappc_fetch_loads.is_empty() {
                                // Provide SV_VertexID in v0 prior to buffer/fetch-shader attribute loads.
                                if self.vgpr_locals.contains_key(&0) {
                                    let vi = self.emit_expr(Expression::AccessIndex {
                                        base: vs_in,
                                        index: 0,
                                    });
                                    self.store_vgpr_u32(0, vi);
                                }
                            } else {
                                // Legacy multi-VGPR attribute input without MUBUF/MTBUF fetches.
                                let pos = self.emit_expr(Expression::AccessIndex {
                                    base: vs_in,
                                    index: 1,
                                });
                                for c in 0..4u32 {
                                    let reg = c as u8;
                                    if self.vgpr_locals.contains_key(&reg) {
                                        let comp = self.emit_expr(Expression::AccessIndex {
                                            base: pos,
                                            index: c,
                                        });
                                        self.store_vgpr_f32(reg, comp);
                                    }
                                }
                            }
                            if let Some(uv_member_idx) = self.legacy_uv_member_index {
                                let uv = self.emit_expr(Expression::AccessIndex {
                                    base: vs_in,
                                    index: uv_member_idx,
                                });
                                for c in 0..2u32 {
                                    let reg = 4 + c as u8;
                                    if self.vgpr_locals.contains_key(&reg) {
                                        let comp = self.emit_expr(Expression::AccessIndex {
                                            base: uv,
                                            index: c,
                                        });
                                        self.store_vgpr_f32(reg, comp);
                                    }
                                }
                            }
                        }
                        VertexInputMode::None => {}
                    }
                }
            }
            ShaderStage::Fragment => {
                if let Some(out_local) = self.ps_out_local {
                    let out_ty = self.func.local_variables[out_local].ty;
                    let zero_struct = self.raw_expr(Expression::ZeroValue(out_ty));
                    self.store_local(out_local, zero_struct);
                }
            }
            ShaderStage::Compute => {
                // Seed GFX10.3 compute/mesh thread ID VGPRs:
                //   mesh:    v0 = local_invocation_index, v1 = local_id.y, v2 = local_id.z
                //   compute: v0 = local_id.x, v1 = local_id.y, v2 = local_id.z
                let local_id = self.raw_expr(Expression::FunctionArgument(0));
                for c in 0..3u32 {
                    let reg = c as u8;
                    if self.vgpr_locals.contains_key(&reg) {
                        let comp = if c == 0 && self.mesh_output.is_some() {
                            self.raw_expr(Expression::FunctionArgument(3))
                        } else {
                            self.emit_expr(Expression::AccessIndex {
                                base: local_id,
                                index: c,
                            })
                        };
                        self.store_vgpr_u32(reg, comp);
                    }
                }
                // Seed compute/mesh workgroup ID SGPRs (`s0`/`s1`/`s2` or configured base) when not overwritten.
                if !self.compute_seed_wg_sgprs.is_empty() {
                    let wg_id = self.raw_expr(Expression::FunctionArgument(1));
                    let seed_list = self.compute_seed_wg_sgprs.clone();
                    for (reg, comp_idx) in seed_list {
                        if self.sgpr_locals.contains_key(&reg) {
                            let comp = self.emit_expr(Expression::AccessIndex {
                                base: wg_id,
                                index: comp_idx,
                            });
                            self.store_sgpr_u32(reg, comp);
                        }
                    }
                }
                // Mesh-to-compute: initialize this group's 4-word output header to 0 on thread 0
                // so early-exiting / culled meshlets never leave stale counts in the shared buffer.
                if let (Some(layout), Some(ms_global)) = (self.mesh_output, self.mesh_out_global) {
                    let (rec, rec_ok) = self.mesh_record_base_and_ok(layout, ms_global);
                    let local_idx = self.raw_expr(Expression::FunctionArgument(3));
                    let zero = self.lit_u32(0);
                    let is_lane0 = self.emit_bin(BinaryOperator::Equal, local_idx, zero);
                    let cond = self.emit_bin(BinaryOperator::LogicalAnd, is_lane0, rec_ok);
                    let accept = self.lower_nested(|s| {
                        for word_off in 0..4u32 {
                            let off = s.lit_u32(word_off);
                            let idx = s.emit_bin(BinaryOperator::Add, rec, off);
                            let z = s.lit_u32(0);
                            s.emit_mesh_store_u32(ms_global, idx, z);
                        }
                    });
                    self.push_stmt(Statement::If {
                        condition: cond,
                        accept,
                        reject: naga::Block::new(),
                    });
                }
            }
        }
    }

    // -- Operand readers --

    fn inline_float_value(src: u16) -> Option<f32> {
        match src {
            240 => Some(0.5),
            241 => Some(-0.5),
            242 => Some(1.0),
            243 => Some(-1.0),
            244 => Some(2.0),
            245 => Some(-2.0),
            246 => Some(4.0),
            247 => Some(-4.0),
            248 => Some(0.159_154_94),
            _ => None,
        }
    }

    /// Exact IEEE-754 binary16 bit pattern for GFX10.3 inline float constants (`240..=248`).
    fn inline_f16_bits(src: u16) -> Option<u32> {
        match src {
            240 => Some(0x3800), // 0.5
            241 => Some(0xB800), // -0.5
            242 => Some(0x3C00), // 1.0
            243 => Some(0xBC00), // -1.0
            244 => Some(0x4000), // 2.0
            245 => Some(0xC000), // -2.0
            246 => Some(0x4400), // 4.0
            247 => Some(0xC400), // -4.0
            248 => Some(0x3118), // 1/(2*pi)
            _ => None,
        }
    }

    fn read_src_u32(&mut self, src: u16, literal: Option<u32>) -> Handle<Expression> {
        match src {
            0..=105 => self.load_sgpr_u32(src as u8),
            106 => {
                let cond = self.load_vcc();
                if self.subgroups_active() {
                    let ballot = self.emit_wave_ballot(cond);
                    self.emit_expr(Expression::AccessIndex {
                        base: ballot,
                        index: 0,
                    })
                } else {
                    let t = self.lit_u32(1);
                    let f = self.lit_u32(0);
                    self.emit_expr(Expression::Select {
                        condition: cond,
                        accept: t,
                        reject: f,
                    })
                }
            }
            107 if self.subgroups_active() => {
                let cond = self.load_vcc();
                let ballot = self.emit_wave_ballot(cond);
                self.emit_expr(Expression::AccessIndex {
                    base: ballot,
                    index: 1,
                })
            }
            124 => self.load_m0(),
            126 if self.exec_local.is_some() => self.load_exec(),
            127 if self.exec_local.is_some() => self.lit_u32(0),
            126 | 127 => self.lit_u32(0xFFFF_FFFF),
            128..=192 => self.lit_u32(u32::from(src - 128)),
            193..=208 => {
                let neg = -(i32::from(src) - 192);
                self.lit_u32(neg as u32)
            }
            240..=248 => {
                let f = Self::inline_float_value(src).unwrap_or(0.0);
                self.lit_u32(f.to_bits())
            }
            251 => {
                let cond = self.load_vcc();
                let t = self.lit_u32(0);
                let f = self.lit_u32(1);
                self.emit_expr(Expression::Select {
                    condition: cond,
                    accept: t,
                    reject: f,
                })
            }
            253 => {
                let cond = self.load_scc();
                let t = self.lit_u32(1);
                let f = self.lit_u32(0);
                self.emit_expr(Expression::Select {
                    condition: cond,
                    accept: t,
                    reject: f,
                })
            }
            255 => self.lit_u32(literal.unwrap_or(0)),
            256..=511 => {
                let vf = self.load_vgpr_f32((src - 256) as u8);
                self.bitcast_f32_to_u32(vf)
            }
            _ => self.lit_u32(0),
        }
    }

    fn read_src_i32(&mut self, src: u16, literal: Option<u32>) -> Handle<Expression> {
        match src {
            128..=192 => self.lit_i32(i32::from(src - 128)),
            193..=208 => self.lit_i32(-(i32::from(src) - 192)),
            255 => self.lit_i32(literal.unwrap_or(0) as i32),
            _ => {
                let u = self.read_src_u32(src, literal);
                self.bitcast_u32_to_i32(u)
            }
        }
    }

    fn read_src_f32(
        &mut self,
        src: u16,
        literal: Option<u32>,
        abs_mod: bool,
        neg_mod: bool,
    ) -> Handle<Expression> {
        let mut val = match src {
            0..=105 => {
                let u = self.load_sgpr_u32(src as u8);
                self.bitcast_u32_to_f32(u)
            }
            128 => self.lit_f32(0.0),
            129..=208 => {
                let u = self.read_src_u32(src, literal);
                self.bitcast_u32_to_f32(u)
            }
            240..=248 => self.lit_f32(Self::inline_float_value(src).unwrap_or(0.0)),
            255 => self.lit_f32_from_bits(literal.unwrap_or(0)),
            256..=511 => self.load_vgpr_f32((src - 256) as u8),
            _ => {
                let u = self.read_src_u32(src, literal);
                self.bitcast_u32_to_f32(u)
            }
        };

        if abs_mod {
            val = self.emit_expr(Expression::Math {
                fun: MathFunction::Abs,
                arg: val,
                arg1: None,
                arg2: None,
                arg3: None,
            });
        }
        if neg_mod {
            val = self.emit_expr(Expression::Unary {
                op: UnaryOperator::Negate,
                expr: val,
            });
        }
        val
    }

    /// Read an `f16` (low or high 16-bit lane via `unpack2x16float`) or `f32` operand as `f32`,
    /// applying optional `abs` and `neg` modifiers (used by `v_fma_mix*` and scalar `*_f16` ops).
    fn read_src_mixed_f16_or_f32(
        &mut self,
        src: u16,
        literal: Option<u32>,
        is_f16: bool,
        hi_half: bool,
        abs_mod: bool,
        neg_mod: bool,
    ) -> Handle<Expression> {
        let mut val = if !is_f16 {
            self.read_src_f32(src, literal, false, false)
        } else {
            match src {
                128 => self.lit_f32(0.0),
                240..=248 => self.lit_f32(Self::inline_float_value(src).unwrap_or(0.0)),
                _ => {
                    let u = self.read_src_u32(src, literal);
                    let pair = self.emit_expr(Expression::Math {
                        fun: MathFunction::Unpack2x16float,
                        arg: u,
                        arg1: None,
                        arg2: None,
                        arg3: None,
                    });
                    self.emit_expr(Expression::AccessIndex {
                        base: pair,
                        index: if hi_half { 1 } else { 0 },
                    })
                }
            }
        };
        if abs_mod {
            val = self.emit_expr(Expression::Math {
                fun: MathFunction::Abs,
                arg: val,
                arg1: None,
                arg2: None,
                arg3: None,
            });
        }
        if neg_mod {
            val = self.emit_expr(Expression::Unary {
                op: UnaryOperator::Negate,
                expr: val,
            });
        }
        val
    }

    /// Unpack a 16-bit IEEE-754 `f16` literal stored in the low 16 bits of a 32-bit word into `f32`.
    fn lit_f16_from_u32_lo(&mut self, bits: u32) -> Handle<Expression> {
        let u = self.lit_u32(bits & 0xFFFF);
        let pair = self.emit_expr(Expression::Math {
            fun: MathFunction::Unpack2x16float,
            arg: u,
            arg1: None,
            arg2: None,
            arg3: None,
        });
        self.emit_expr(Expression::AccessIndex {
            base: pair,
            index: 0,
        })
    }

    /// Read a packed 2x16-bit `f16` VOP3P operand as `vec2<f32>` via core WGSL `unpack2x16float`
    /// (zero `enable f16;` required), applying exact GFX10.3 `op_sel`, `op_sel_hi`, `neg_lo`,
    /// and `neg_hi` modifiers.
    fn read_src_pk_f16(
        &mut self,
        src: u16,
        literal: Option<u32>,
        op_sel_lo: bool,
        op_sel_hi: bool,
        neg_lo: bool,
        neg_hi: bool,
    ) -> Handle<Expression> {
        let raw = match src {
            128 => {
                let z = self.lit_f32(0.0);
                self.emit_expr(Expression::Splat {
                    size: VectorSize::Bi,
                    value: z,
                })
            }
            240..=248 => {
                // GFX10.3 inline float constants populate the low 16-bit f16 half (0.0 in hi).
                let lo = self.lit_f32(Self::inline_float_value(src).unwrap_or(0.0));
                let hi = self.lit_f32(0.0);
                self.emit_expr(Expression::Compose {
                    ty: self.types.vec2_f32_ty,
                    components: vec![lo, hi],
                })
            }
            _ => {
                let u = self.read_src_u32(src, literal);
                self.emit_expr(Expression::Math {
                    fun: MathFunction::Unpack2x16float,
                    arg: u,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                })
            }
        };

        let selected = match (op_sel_lo, op_sel_hi) {
            (false, true) => raw,
            (false, false) => self.emit_expr(Expression::Swizzle {
                size: VectorSize::Bi,
                vector: raw,
                pattern: [
                    SwizzleComponent::X,
                    SwizzleComponent::X,
                    SwizzleComponent::X,
                    SwizzleComponent::X,
                ],
            }),
            (true, true) => self.emit_expr(Expression::Swizzle {
                size: VectorSize::Bi,
                vector: raw,
                pattern: [
                    SwizzleComponent::Y,
                    SwizzleComponent::Y,
                    SwizzleComponent::X,
                    SwizzleComponent::X,
                ],
            }),
            (true, false) => self.emit_expr(Expression::Swizzle {
                size: VectorSize::Bi,
                vector: raw,
                pattern: [
                    SwizzleComponent::Y,
                    SwizzleComponent::X,
                    SwizzleComponent::X,
                    SwizzleComponent::X,
                ],
            }),
        };

        match (neg_lo, neg_hi) {
            (false, false) => selected,
            (true, true) => self.emit_expr(Expression::Unary {
                op: UnaryOperator::Negate,
                expr: selected,
            }),
            (true, false) => {
                let x = self.emit_expr(Expression::AccessIndex {
                    base: selected,
                    index: 0,
                });
                let nx = self.emit_expr(Expression::Unary {
                    op: UnaryOperator::Negate,
                    expr: x,
                });
                let y = self.emit_expr(Expression::AccessIndex {
                    base: selected,
                    index: 1,
                });
                self.emit_expr(Expression::Compose {
                    ty: self.types.vec2_f32_ty,
                    components: vec![nx, y],
                })
            }
            (false, true) => {
                let x = self.emit_expr(Expression::AccessIndex {
                    base: selected,
                    index: 0,
                });
                let y = self.emit_expr(Expression::AccessIndex {
                    base: selected,
                    index: 1,
                });
                let ny = self.emit_expr(Expression::Unary {
                    op: UnaryOperator::Negate,
                    expr: y,
                });
                self.emit_expr(Expression::Compose {
                    ty: self.types.vec2_f32_ty,
                    components: vec![x, ny],
                })
            }
        }
    }

    fn update_scc_nonzero(&mut self, val_u32: Handle<Expression>) {
        if self.scc_local.is_some() {
            let zero = self.lit_u32(0);
            let nonzero = self.emit_expr(Expression::Binary {
                op: BinaryOperator::NotEqual,
                left: val_u32,
                right: zero,
            });
            self.store_scc(nonzero);
        }
    }

    fn emit_bin(
        &mut self,
        op: BinaryOperator,
        left: Handle<Expression>,
        right: Handle<Expression>,
    ) -> Handle<Expression> {
        self.emit_expr(Expression::Binary { op, left, right })
    }

    fn emit_select(
        &mut self,
        condition: Handle<Expression>,
        accept: Handle<Expression>,
        reject: Handle<Expression>,
    ) -> Handle<Expression> {
        self.emit_expr(Expression::Select {
            condition,
            accept,
            reject,
        })
    }

    fn emit_bit_not(&mut self, expr: Handle<Expression>) -> Handle<Expression> {
        self.emit_expr(Expression::Unary {
            op: UnaryOperator::BitwiseNot,
            expr,
        })
    }

    /// Canonical lane-mask SGPR value for a per-lane boolean (`1u` / `0u`).
    fn bool_to_u32(&mut self, cond: Handle<Expression>) -> Handle<Expression> {
        let t = self.lit_u32(1);
        let f = self.lit_u32(0);
        self.emit_select(cond, t, f)
    }

    /// Returns `true` when hardware WebGPU `subgroups` lowering is active for this shader stage.
    #[inline]
    fn subgroups_active(&self) -> bool {
        self.wave_emul_mode == WaveEmulMode::Subgroups
            && matches!(self.stage, ShaderStage::Compute | ShaderStage::Fragment)
    }

    /// Lazily add `@builtin(subgroup_invocation_id) sg_lane: u32` to the entry point arguments
    /// and return its expression handle.
    fn emit_subgroup_invocation_id(&mut self) -> Handle<Expression> {
        self.emitted_subgroup_ops = true;
        let arg_idx = if let Some(idx) = self.subgroup_invocation_id_arg {
            idx
        } else {
            let idx = self.func.arguments.len() as u32;
            self.func.arguments.push(FunctionArgument {
                name: Some("sg_lane".to_string()),
                ty: self.types.u32_ty,
                binding: Some(Binding::BuiltIn(BuiltIn::SubgroupInvocationId)),
            });
            self.subgroup_invocation_id_arg = Some(idx);
            idx
        };
        self.raw_expr(Expression::FunctionArgument(arg_idx))
    }

    fn emit_wave_broadcast_first(&mut self, value: Handle<Expression>) -> Handle<Expression> {
        self.emitted_subgroup_ops = true;
        emit_subgroup_broadcast_first(&mut self.func, value, self.types.u32_ty)
    }

    fn emit_wave_ballot(&mut self, predicate: Handle<Expression>) -> Handle<Expression> {
        self.emitted_subgroup_ops = true;
        emit_subgroup_ballot(&mut self.func, Some(predicate))
    }

    fn emit_wave_shuffle(
        &mut self,
        value: Handle<Expression>,
        lane: Handle<Expression>,
    ) -> Handle<Expression> {
        self.emitted_subgroup_ops = true;
        emit_subgroup_shuffle(&mut self.func, value, lane, self.types.u32_ty)
    }

    fn emit_wave_shuffle_xor(
        &mut self,
        value: Handle<Expression>,
        mask: Handle<Expression>,
    ) -> Handle<Expression> {
        self.emitted_subgroup_ops = true;
        emit_subgroup_shuffle_xor(&mut self.func, value, mask, self.types.u32_ty)
    }

    /// Store a per-lane boolean into a 64-bit lane-mask destination (`vcc` or `s[n:n+1]`).
    ///
    /// In [`WaveEmulMode::WorkgroupLds`], one WGSL invocation models one wave lane so SGPR lane
    /// masks are canonically `(lo = lane bit, hi = 0)`. In [`WaveEmulMode::Subgroups`], SGPR
    /// destinations receive the hardware `subgroupBallot(cond)` `.xy` 64-bit lane mask directly.
    fn store_lane_mask(&mut self, sdst: u8, cond: Handle<Expression>) {
        let sd7 = sdst & 0x7F;
        if sd7 == 106 {
            self.store_vcc(cond);
        } else if sd7 <= 105 {
            if self.subgroups_active() {
                let ballot = self.emit_wave_ballot(cond);
                let lo = self.emit_expr(Expression::AccessIndex {
                    base: ballot,
                    index: 0,
                });
                self.store_sgpr_u32(sd7, lo);
                if sd7 <= 104 && !self.is_wave32 {
                    let hi = self.emit_expr(Expression::AccessIndex {
                        base: ballot,
                        index: 1,
                    });
                    self.store_sgpr_u32(sd7 + 1, hi);
                } else if sd7 <= 104 {
                    let zero = self.lit_u32(0);
                    self.store_sgpr_u32(sd7 + 1, zero);
                }
            } else {
                let mask_u = self.bool_to_u32(cond);
                self.store_sgpr_u32(sd7, mask_u);
                if sd7 <= 104 {
                    let zero = self.lit_u32(0);
                    self.store_sgpr_u32(sd7 + 1, zero);
                }
            }
        }
    }

    /// Read this lane's bit of a 64-bit lane-mask source.
    fn read_lane_mask_bit(&mut self, src: u16, literal: Option<u32>) -> Handle<Expression> {
        match src {
            106 => self.load_vcc(),
            126 if self.exec_local.is_none() => self.lit_bool(true),
            0..=105 if self.subgroups_active() => {
                let sg_lane = self.emit_subgroup_invocation_id();
                let lo = self.load_sgpr_u32(src as u8);
                let word = if src <= 104 && !self.is_wave32 {
                    let hi = self.load_sgpr_u32((src + 1) as u8);
                    let c32 = self.lit_u32(32);
                    let in_hi = self.emit_bin(BinaryOperator::GreaterEqual, sg_lane, c32);
                    self.emit_select(in_hi, hi, lo)
                } else {
                    lo
                };
                let mask31 = self.lit_u32(31);
                let sh = self.emit_bin(BinaryOperator::And, sg_lane, mask31);
                let shifted = self.emit_bin(BinaryOperator::ShiftRight, word, sh);
                let one = self.lit_u32(1);
                let bit = self.emit_bin(BinaryOperator::And, shifted, one);
                let zero = self.lit_u32(0);
                self.emit_bin(BinaryOperator::NotEqual, bit, zero)
            }
            _ => {
                let v = self.read_src_u32(src, literal);
                let one = self.lit_u32(1);
                let bit = self.emit_bin(BinaryOperator::And, v, one);
                let zero = self.lit_u32(0);
                self.emit_bin(BinaryOperator::NotEqual, bit, zero)
            }
        }
    }

    /// Read a 64-bit scalar source operand as `(lo, hi)` u32 halves.
    ///
    /// SGPR pairs read both registers, `vcc` yields `(lane bit, 0)` (or `subgroupBallot(vcc).xy`
    /// under [`WaveEmulMode::Subgroups`]), `exec` is all ones, integer inline constants are
    /// sign-extended, float inline constants use their `f64` bit pattern, and 32-bit literals are
    /// zero-extended.
    fn read_ssrc_pair(
        &mut self,
        src: u8,
        literal: Option<u32>,
    ) -> (Handle<Expression>, Handle<Expression>) {
        match src {
            0..=104 => (self.load_sgpr_u32(src), self.load_sgpr_u32(src + 1)),
            105 => (self.load_sgpr_u32(105), self.lit_u32(0)),
            106 if self.subgroups_active() => {
                let cond = self.load_vcc();
                let ballot = self.emit_wave_ballot(cond);
                let lo = self.emit_expr(Expression::AccessIndex {
                    base: ballot,
                    index: 0,
                });
                let hi = self.emit_expr(Expression::AccessIndex {
                    base: ballot,
                    index: 1,
                });
                (lo, hi)
            }
            106 => (self.read_src_u32(106, None), self.lit_u32(0)),
            126 if self.exec_local.is_some() => (self.load_exec(), self.lit_u32(0)),
            126 => (self.lit_u32(0xFFFF_FFFF), self.lit_u32(0xFFFF_FFFF)),
            128..=192 => (self.lit_u32(u32::from(src - 128)), self.lit_u32(0)),
            193..=208 => {
                let neg = -(i32::from(src) - 192);
                (self.lit_u32(neg as u32), self.lit_u32(0xFFFF_FFFF))
            }
            240..=248 => {
                let f = f64::from(Self::inline_float_value(u16::from(src)).unwrap_or(0.0));
                let bits = f.to_bits();
                (
                    self.lit_u32((bits & 0xFFFF_FFFF) as u32),
                    self.lit_u32((bits >> 32) as u32),
                )
            }
            255 => (self.lit_u32(literal.unwrap_or(0)), self.lit_u32(0)),
            _ => (self.read_src_u32(u16::from(src), literal), self.lit_u32(0)),
        }
    }

    /// Read a 64-bit vector-ALU source (`v[n:n+1]`, SGPR pair, or constant) as `(lo, hi)`.
    fn read_vsrc_pair(
        &mut self,
        src: u16,
        literal: Option<u32>,
    ) -> (Handle<Expression>, Handle<Expression>) {
        match src {
            0..=255 => self.read_ssrc_pair(src as u8, literal),
            256..=510 => {
                let lo = self.read_src_u32(src, None);
                let hi = self.read_src_u32(src + 1, None);
                (lo, hi)
            }
            _ => (self.read_src_u32(src, literal), self.lit_u32(0)),
        }
    }

    /// Store a 64-bit `(lo, hi)` scalar result into an SGPR pair destination.
    ///
    /// `vcc` receives this lane's bit (bit 0 of `lo`); `exec` / `null` are no-ops.
    fn store_sdst_pair(&mut self, sdst: u8, lo: Handle<Expression>, hi: Handle<Expression>) {
        match sdst {
            0..=104 => {
                self.store_sgpr_u32(sdst, lo);
                self.store_sgpr_u32(sdst + 1, hi);
            }
            105 => self.store_sgpr_u32(105, lo),
            106 => {
                let one = self.lit_u32(1);
                let bit = self.emit_bin(BinaryOperator::And, lo, one);
                let zero = self.lit_u32(0);
                let cond = self.emit_bin(BinaryOperator::NotEqual, bit, zero);
                self.store_vcc(cond);
            }
            126 => self.store_exec_lane_bit(lo),
            _ => {}
        }
    }

    /// `scc = ((lo | hi) != 0u)` for 64-bit scalar results.
    fn update_scc_nonzero_pair(&mut self, lo: Handle<Expression>, hi: Handle<Expression>) {
        if self.scc_local.is_some() {
            let any = self.emit_bin(BinaryOperator::InclusiveOr, lo, hi);
            self.update_scc_nonzero(any);
        }
    }

    /// Exact unsigned `32 x 32 -> hi32` multiply using only `u32` 16-bit half-word products.
    fn emit_mul_hi_u32(
        &mut self,
        a: Handle<Expression>,
        b: Handle<Expression>,
    ) -> Handle<Expression> {
        let m16 = self.lit_u32(0xFFFF);
        let s16 = self.lit_u32(16);
        let a_lo = self.emit_bin(BinaryOperator::And, a, m16);
        let a_hi = self.emit_bin(BinaryOperator::ShiftRight, a, s16);
        let b_lo = self.emit_bin(BinaryOperator::And, b, m16);
        let b_hi = self.emit_bin(BinaryOperator::ShiftRight, b, s16);
        let ll = self.emit_bin(BinaryOperator::Multiply, a_lo, b_lo);
        let lh = self.emit_bin(BinaryOperator::Multiply, a_lo, b_hi);
        let hl = self.emit_bin(BinaryOperator::Multiply, a_hi, b_lo);
        let hh = self.emit_bin(BinaryOperator::Multiply, a_hi, b_hi);
        // mid = (ll >> 16) + lo16(lh) + lo16(hl)  (<= 3 * 0xFFFF, never overflows)
        let ll_hi = self.emit_bin(BinaryOperator::ShiftRight, ll, s16);
        let lh_lo = self.emit_bin(BinaryOperator::And, lh, m16);
        let hl_lo = self.emit_bin(BinaryOperator::And, hl, m16);
        let mid0 = self.emit_bin(BinaryOperator::Add, ll_hi, lh_lo);
        let mid = self.emit_bin(BinaryOperator::Add, mid0, hl_lo);
        // hi = hh + (lh >> 16) + (hl >> 16) + (mid >> 16)
        let lh_hi = self.emit_bin(BinaryOperator::ShiftRight, lh, s16);
        let hl_hi = self.emit_bin(BinaryOperator::ShiftRight, hl, s16);
        let mid_hi = self.emit_bin(BinaryOperator::ShiftRight, mid, s16);
        let r0 = self.emit_bin(BinaryOperator::Add, hh, lh_hi);
        let r1 = self.emit_bin(BinaryOperator::Add, r0, hl_hi);
        self.emit_bin(BinaryOperator::Add, r1, mid_hi)
    }

    /// Exact signed `32 x 32 -> hi32` multiply on `u32` bit patterns:
    /// `mulhi_s(a, b) = mulhi_u(a, b) - (a < 0 ? b : 0) - (b < 0 ? a : 0)` (mod 2^32).
    fn emit_mul_hi_i32(
        &mut self,
        a: Handle<Expression>,
        b: Handle<Expression>,
    ) -> Handle<Expression> {
        let hu = self.emit_mul_hi_u32(a, b);
        let sign = self.lit_u32(0x8000_0000);
        let zero = self.lit_u32(0);
        let a_neg = self.emit_bin(BinaryOperator::GreaterEqual, a, sign);
        let b_neg = self.emit_bin(BinaryOperator::GreaterEqual, b, sign);
        let corr_a = self.emit_select(a_neg, b, zero);
        let corr_b = self.emit_select(b_neg, a, zero);
        let r0 = self.emit_bin(BinaryOperator::Subtract, hu, corr_a);
        self.emit_bin(BinaryOperator::Subtract, r0, corr_b)
    }

    /// 64-bit shift of a `(lo, hi)` u32 pair by `amount & 63`, using only masked (`< 32`)
    /// WGSL shift amounts and `select` for the `>= 32` half-swap.
    fn emit_shift64(
        &mut self,
        kind: Shift64Kind,
        lo: Handle<Expression>,
        hi: Handle<Expression>,
        amount: Handle<Expression>,
    ) -> (Handle<Expression>, Handle<Expression>) {
        let mask63 = self.lit_u32(63);
        let mask31 = self.lit_u32(31);
        let c32 = self.lit_u32(32);
        let zero = self.lit_u32(0);
        let amt = self.emit_bin(BinaryOperator::And, amount, mask63);
        let s5 = self.emit_bin(BinaryOperator::And, amt, mask31);
        let big = self.emit_bin(BinaryOperator::GreaterEqual, amt, c32);
        let s5_nonzero = self.emit_bin(BinaryOperator::NotEqual, s5, zero);
        let inv_raw = self.emit_bin(BinaryOperator::Subtract, c32, s5);
        let inv = self.emit_bin(BinaryOperator::And, inv_raw, mask31);
        let (lo_small, hi_small, lo_big, hi_big) = match kind {
            Shift64Kind::Left => {
                let lo_sh = self.emit_bin(BinaryOperator::ShiftLeft, lo, s5);
                let hi_sh = self.emit_bin(BinaryOperator::ShiftLeft, hi, s5);
                let spill_raw = self.emit_bin(BinaryOperator::ShiftRight, lo, inv);
                let spill = self.emit_select(s5_nonzero, spill_raw, zero);
                let hi_small = self.emit_bin(BinaryOperator::InclusiveOr, hi_sh, spill);
                (lo_sh, hi_small, zero, lo_sh)
            }
            Shift64Kind::LogicalRight | Shift64Kind::ArithmeticRight => {
                let lo_sh = self.emit_bin(BinaryOperator::ShiftRight, lo, s5);
                let spill_raw = self.emit_bin(BinaryOperator::ShiftLeft, hi, inv);
                let spill = self.emit_select(s5_nonzero, spill_raw, zero);
                let lo_small = self.emit_bin(BinaryOperator::InclusiveOr, lo_sh, spill);
                if kind == Shift64Kind::LogicalRight {
                    let hi_sh = self.emit_bin(BinaryOperator::ShiftRight, hi, s5);
                    (lo_small, hi_sh, hi_sh, zero)
                } else {
                    let hi_i = self.bitcast_u32_to_i32(hi);
                    let hi_sar_i = self.emit_bin(BinaryOperator::ShiftRight, hi_i, s5);
                    let hi_sar = self.bitcast_i32_to_u32(hi_sar_i);
                    let c31 = self.lit_u32(31);
                    let sign_i = self.emit_bin(BinaryOperator::ShiftRight, hi_i, c31);
                    let sign = self.bitcast_i32_to_u32(sign_i);
                    (lo_small, hi_sar, hi_sar, sign)
                }
            }
        };
        let out_lo = self.emit_select(big, lo_big, lo_small);
        let out_hi = self.emit_select(big, hi_big, hi_small);
        (out_lo, out_hi)
    }

    /// One 32-bit half of a SOP2 `*_b64` bitwise op (`and`/`or`/`xor`/`andn2`/`orn2`/`nand`/`nor`/`xnor`).
    fn emit_sop2_bitwise_half(
        &mut self,
        op: u8,
        l: Handle<Expression>,
        r: Handle<Expression>,
    ) -> Handle<Expression> {
        let (bin, invert_rhs, invert_result) = match op {
            0x0E | 0x0F => (BinaryOperator::And, false, false),
            0x10 | 0x11 => (BinaryOperator::InclusiveOr, false, false),
            0x12 | 0x13 => (BinaryOperator::ExclusiveOr, false, false),
            0x14 | 0x15 => (BinaryOperator::And, true, false),
            0x16 | 0x17 => (BinaryOperator::InclusiveOr, true, false),
            0x18 | 0x19 => (BinaryOperator::And, false, true),
            0x1A | 0x1B => (BinaryOperator::InclusiveOr, false, true),
            _ => (BinaryOperator::ExclusiveOr, false, true),
        };
        let rhs = if invert_rhs { self.emit_bit_not(r) } else { r };
        let res = self.emit_bin(bin, l, rhs);
        if invert_result {
            self.emit_bit_not(res)
        } else {
            res
        }
    }

    /// IEEE-754 binary32 class test for `v_cmp_class_f32`: returns `true` when the class of
    /// `bits` has its bit set in `mask` (0 sNaN, 1 qNaN, 2 -Inf, 3 -Normal, 4 -Subnormal,
    /// 5 -0, 6 +0, 7 +Subnormal, 8 +Normal, 9 +Inf).
    fn emit_f32_class_test(
        &mut self,
        bits: Handle<Expression>,
        mask: Handle<Expression>,
    ) -> Handle<Expression> {
        let s23 = self.lit_u32(23);
        let s31 = self.lit_u32(31);
        let exp_mask = self.lit_u32(0xFF);
        let mant_mask = self.lit_u32(0x007F_FFFF);
        let quiet_bit = self.lit_u32(0x0040_0000);
        let zero = self.lit_u32(0);
        let one = self.lit_u32(1);
        let exp_sh = self.emit_bin(BinaryOperator::ShiftRight, bits, s23);
        let exp = self.emit_bin(BinaryOperator::And, exp_sh, exp_mask);
        let mant = self.emit_bin(BinaryOperator::And, bits, mant_mask);
        let sign = self.emit_bin(BinaryOperator::ShiftRight, bits, s31);
        let neg = self.emit_bin(BinaryOperator::NotEqual, sign, zero);
        let exp_max = self.emit_bin(BinaryOperator::Equal, exp, exp_mask);
        let exp_zero = self.emit_bin(BinaryOperator::Equal, exp, zero);
        let mant_zero = self.emit_bin(BinaryOperator::Equal, mant, zero);
        let quiet_raw = self.emit_bin(BinaryOperator::And, bits, quiet_bit);
        let quiet = self.emit_bin(BinaryOperator::NotEqual, quiet_raw, zero);

        let idx_snan = self.lit_u32(0);
        let idx_qnan = self.lit_u32(1);
        let idx_ninf = self.lit_u32(2);
        let idx_nnorm = self.lit_u32(3);
        let idx_nsub = self.lit_u32(4);
        let idx_nzero = self.lit_u32(5);
        let idx_pzero = self.lit_u32(6);
        let idx_psub = self.lit_u32(7);
        let idx_pnorm = self.lit_u32(8);
        let idx_pinf = self.lit_u32(9);

        let nan_idx = self.emit_select(quiet, idx_qnan, idx_snan);
        let inf_idx = self.emit_select(neg, idx_ninf, idx_pinf);
        let zero_idx = self.emit_select(neg, idx_nzero, idx_pzero);
        let sub_idx = self.emit_select(neg, idx_nsub, idx_psub);
        let norm_idx = self.emit_select(neg, idx_nnorm, idx_pnorm);
        let special_idx = self.emit_select(mant_zero, inf_idx, nan_idx);
        let tiny_idx = self.emit_select(mant_zero, zero_idx, sub_idx);
        let finite_idx = self.emit_select(exp_zero, tiny_idx, norm_idx);
        let idx = self.emit_select(exp_max, special_idx, finite_idx);

        let shifted = self.emit_bin(BinaryOperator::ShiftRight, mask, idx);
        let bit = self.emit_bin(BinaryOperator::And, shifted, one);
        self.emit_bin(BinaryOperator::NotEqual, bit, zero)
    }

    /// IEEE-754 binary16 class test for `v_cmp_class_f16`: returns `true` when the class of
    /// `bits16` (low 16 bits) has its bit set in `mask` (0 sNaN, 1 qNaN, 2 -Inf, 3 -Normal,
    /// 4 -Subnormal, 5 -0, 6 +0, 7 +Subnormal, 8 +Normal, 9 +Inf).
    fn emit_f16_class_test(
        &mut self,
        bits16: Handle<Expression>,
        mask: Handle<Expression>,
    ) -> Handle<Expression> {
        let s10 = self.lit_u32(10);
        let s15 = self.lit_u32(15);
        let exp_mask = self.lit_u32(0x1F);
        let mant_mask = self.lit_u32(0x03FF);
        let quiet_bit = self.lit_u32(0x0200);
        let zero = self.lit_u32(0);
        let one = self.lit_u32(1);
        let exp_sh = self.emit_bin(BinaryOperator::ShiftRight, bits16, s10);
        let exp = self.emit_bin(BinaryOperator::And, exp_sh, exp_mask);
        let mant = self.emit_bin(BinaryOperator::And, bits16, mant_mask);
        let sign_sh = self.emit_bin(BinaryOperator::ShiftRight, bits16, s15);
        let sign = self.emit_bin(BinaryOperator::And, sign_sh, one);
        let neg = self.emit_bin(BinaryOperator::NotEqual, sign, zero);
        let exp_max = self.emit_bin(BinaryOperator::Equal, exp, exp_mask);
        let exp_zero = self.emit_bin(BinaryOperator::Equal, exp, zero);
        let mant_zero = self.emit_bin(BinaryOperator::Equal, mant, zero);
        let quiet_raw = self.emit_bin(BinaryOperator::And, bits16, quiet_bit);
        let quiet = self.emit_bin(BinaryOperator::NotEqual, quiet_raw, zero);

        let idx_snan = self.lit_u32(0);
        let idx_qnan = self.lit_u32(1);
        let idx_ninf = self.lit_u32(2);
        let idx_nnorm = self.lit_u32(3);
        let idx_nsub = self.lit_u32(4);
        let idx_nzero = self.lit_u32(5);
        let idx_pzero = self.lit_u32(6);
        let idx_psub = self.lit_u32(7);
        let idx_pnorm = self.lit_u32(8);
        let idx_pinf = self.lit_u32(9);

        let nan_idx = self.emit_select(quiet, idx_qnan, idx_snan);
        let inf_idx = self.emit_select(neg, idx_ninf, idx_pinf);
        let zero_idx = self.emit_select(neg, idx_nzero, idx_pzero);
        let sub_idx = self.emit_select(neg, idx_nsub, idx_psub);
        let norm_idx = self.emit_select(neg, idx_nnorm, idx_pnorm);
        let special_idx = self.emit_select(mant_zero, inf_idx, nan_idx);
        let tiny_idx = self.emit_select(mant_zero, zero_idx, sub_idx);
        let finite_idx = self.emit_select(exp_zero, tiny_idx, norm_idx);
        let idx = self.emit_select(exp_max, special_idx, finite_idx);

        let shifted = self.emit_bin(BinaryOperator::ShiftRight, mask, idx);
        let bit = self.emit_bin(BinaryOperator::And, shifted, one);
        self.emit_bin(BinaryOperator::NotEqual, bit, zero)
    }

    fn apply_float_out_mods(
        &mut self,
        mut val: Handle<Expression>,
        omod: u8,
        clamp: bool,
    ) -> Handle<Expression> {
        let scale = match omod {
            1 => Some(2.0f32),
            2 => Some(4.0f32),
            3 => Some(0.5f32),
            _ => None,
        };
        if let Some(s) = scale {
            let factor = self.lit_f32(s);
            val = self.emit_expr(Expression::Binary {
                op: BinaryOperator::Multiply,
                left: val,
                right: factor,
            });
        }
        if clamp {
            let lo = self.lit_f32(0.0);
            let hi = self.lit_f32(1.0);
            val = self.emit_expr(Expression::Math {
                fun: MathFunction::Clamp,
                arg: val,
                arg1: Some(lo),
                arg2: Some(hi),
                arg3: None,
            });
        }
        val
    }

    fn record_unsupported(&mut self, inst: &Rdna2Instruction) {
        self.unsupported_op_count += 1;
        // Strictly sanitized: instruction offset, encoding family, and mnemonic only.
        let suffix = if inst.truncated { " (truncated)" } else { "" };
        self.unsupported_comments.push(format!(
            "// unsupported_op [0x{:04x}] {}: {}{}",
            inst.offset,
            inst.encoding.as_str(),
            inst.mnemonic,
            suffix
        ));
    }

    // -- Instruction dispatch --

    fn translate_instruction(&mut self, inst_idx: usize, inst: &Rdna2Instruction) {
        if inst.truncated {
            self.record_unsupported(inst);
            return;
        }

        let exec_write = classify_exec_mask_op(inst);
        let handled = match &inst.detail {
            Rdna2Detail::Sop1 {
                sdst,
                ssrc0,
                literal,
                ..
            } if exec_write.is_some() => match exec_write {
                Some(write) => self.translate_exec_mask_write(write, *sdst, *ssrc0, *literal),
                None => false,
            },
            Rdna2Detail::Sopp { op, simm16, .. } => self.translate_sopp(*op, *simm16, inst.offset),
            Rdna2Detail::Sopc {
                op,
                ssrc0,
                ssrc1,
                literal,
            } => self.translate_sopc(*op, *ssrc0, *ssrc1, *literal),
            Rdna2Detail::Sop1 {
                op,
                sdst,
                ssrc0,
                literal,
            } => self.translate_sop1(*op, *sdst, *ssrc0, *literal),
            Rdna2Detail::Sopk {
                op, sdst, simm16, ..
            } => self.translate_sopk(*op, *sdst, *simm16),
            Rdna2Detail::Sop2 {
                op,
                sdst,
                ssrc0,
                ssrc1,
                literal,
            } => self.translate_sop2(*op, *sdst, *ssrc0, *ssrc1, *literal),
            Rdna2Detail::Smem {
                op,
                sdata,
                sbase,
                soffset,
                offset,
                ..
            } => self.translate_smem(inst_idx, *op, *sdata, *sbase, *soffset, *offset),
            Rdna2Detail::Vop1 {
                op,
                vdst,
                src0,
                literal,
            } => self.translate_vop1(*op, *vdst, *src0, *literal, 0, false, false, false),
            Rdna2Detail::Vopc {
                op,
                vsrc1,
                src0,
                literal,
            } => self.translate_vopc(
                *op,
                *src0,
                256 + u16::from(*vsrc1),
                *literal,
                0,
                0,
                0,
                vopc_sdwab_sdst(*op, *src0, *literal),
            ),
            Rdna2Detail::Vop2 {
                op,
                vdst,
                vsrc1,
                src0,
                literal,
            } => self.translate_vop2(
                *op,
                *vdst,
                *src0,
                256 + u16::from(*vsrc1),
                None,
                *literal,
                0,
                false,
                0,
                0,
                None,
            ),
            Rdna2Detail::Vop3 {
                op,
                vdst,
                sdst,
                src0,
                src1,
                src2,
                clamp,
                omod,
                abs,
                neg,
                op_sel,
                literal,
            } => self.translate_vop3(
                *op, *vdst, *sdst, *src0, *src1, *src2, *clamp, *omod, *abs, *neg, *op_sel, *literal,
            ),
            Rdna2Detail::Vop3P {
                op,
                vdst,
                src0,
                src1,
                src2,
                clamp,
                op_sel,
                op_sel_hi,
                neg_lo,
                neg_hi,
                literal,
            } => self.translate_vop3p(
                *op,
                *vdst,
                *src0,
                *src1,
                *src2,
                *clamp,
                *op_sel,
                *op_sel_hi,
                *neg_lo,
                *neg_hi,
                *literal,
            ),
            Rdna2Detail::Vintrp {
                op,
                vdst,
                attr,
                attrchan,
                ..
            } => self.translate_vintrp(*op, *vdst, *attr, *attrchan),
            Rdna2Detail::Mimg {
                op,
                dmask,
                dim,
                a16,
                d16,
                nsize,
                vaddr,
                nsa_vaddrs,
                vdata,
                srsrc,
                ssamp,
                ..
            } => {
                if matches!(*op, 0xE6 | 0xE7) {
                    self.translate_bvh_intersect(
                        *op, *a16, *nsize, *vaddr, nsa_vaddrs, *vdata, *srsrc,
                    )
                } else {
                    self.translate_mimg(
                        inst_idx, *op, *dmask, *dim, *d16, *nsize, *vaddr, nsa_vaddrs, *vdata,
                        *srsrc, *ssamp,
                    )
                }
            }
            Rdna2Detail::Mubuf {
                op,
                offset,
                offen,
                idxen,
                vaddr,
                vdata,
                srsrc,
                soffset,
                ..
            } => self.translate_mubuf_or_mtbuf(
                inst_idx, false, *op, 0, *offset, *offen, *idxen, *vaddr, *vdata, *srsrc, *soffset,
            ),
            Rdna2Detail::Mtbuf {
                op,
                format,
                offset,
                offen,
                idxen,
                vaddr,
                vdata,
                srsrc,
                soffset,
                ..
            } => self.translate_mubuf_or_mtbuf(
                inst_idx, true, *op, *format, *offset, *offen, *idxen, *vaddr, *vdata, *srsrc, *soffset,
            ),
            Rdna2Detail::Ds {
                op,
                offset0,
                offset1,
                addr,
                data0,
                data1,
                vdst,
                ..
            } => self.translate_ds(*op, *offset0, *offset1, *addr, *data0, *data1, *vdst),
            Rdna2Detail::Exp {
                target,
                en,
                compr,
                done,
                vm,
                vsrc,
            } => self.translate_exp(*target, *en, *compr, *done, *vm, *vsrc),
            Rdna2Detail::Flat {
                seg,
                op,
                offset,
                lds,
                addr,
                saddr,
                vdst,
                ..
            } => self.translate_flat(*seg, *op, *offset, *lds, *addr, *saddr, *vdst),
            Rdna2Detail::Unknown { .. } => false,
        };

        if handled {
            self.translated_op_count += 1;
        } else {
            self.record_unsupported(inst);
        }
    }

    // -- SOPP / SOPC / SOP1 / SOPK / SOP2 / SMEM --

    fn translate_sopp(&mut self, op: u8, simm16: u16, offset: usize) -> bool {
        match op {
            // s_nop, s_endpgm, s_waitcnt, s_setprio (scheduling priority hint),
            // s_endpgm_saved, s_endpgm_ordered_ps_done, s_code_end,
            // s_inst_prefetch, s_clause, s_wait_idle, s_waitcnt_depctr, s_round_mode
            0x00 | 0x01 | 0x03 | 0x0C | 0x0D | 0x0E | 0x0F | 0x13 | 0x14 | 0x15 | 0x16 | 0x1B
            | 0x1C | 0x1E | 0x1F | 0x20 | 0x21 | 0x22 | 0x23 | 0x24 | 0x25 | 0x28 => {
                true
            }
            // s_branch / s_cbranch_{scc0,scc1,vccz,vccnz,execz,execnz}: lifted into structured
            // WGSL control flow by `rdna2_cfg` (the branch itself emits no statement).
            0x02 | 0x04..=0x09 => self.structured_cf,
            // s_barrier: `workgroupBarrier()` in compute; WGSL/WebGPU forbids it in vertex and
            // fragment stages (no workgroups there), so it lowers to a documented no-op.
            // WGSL also requires barriers in uniform control flow, which lifted RDNA2 branches
            // (conditions on per-invocation `scc` / `vcc` / `exec_mask`) never are.
            0x0A => {
                if self.stage == ShaderStage::Compute && self.in_nonuniform_cf() {
                    self.note_comments.push(format!(
                        "// note [0x{offset:04x}] s_barrier skipped inside structured control flow for WGSL uniformity"
                    ));
                } else if self.stage == ShaderStage::Compute {
                    self.func.body.push(
                        Statement::ControlBarrier(naga::Barrier::WORK_GROUP),
                        Span::UNDEFINED,
                    );
                } else {
                    self.note_comments.push(format!(
                        "// note [0x{offset:04x}] s_barrier: no-op in {} stage (workgroupBarrier is compute-only)",
                        self.stage.as_str()
                    ));
                }
                true
            }
            // s_sendmsg / s_sendmsghalt: GFX10.3 NGG/Mesh SetMeshOutputCounts (`MSG_GS_ALLOC_REQ`)
            // writes `m0[10:0]` (vertex count) and `m0[22:12]` (primitive count) to words 0..1 of
            // the group's record in `ms_out`. `MSG_GS` / `MSG_GS_DONE` are hardware no-ops here.
            0x10 | 0x11 => match sendmsg_id(simm16) {
                SENDMSG_ID_GS_ALLOC_REQ => {
                    if let (Some(layout), Some(ms_global)) = (self.mesh_output, self.mesh_out_global)
                    {
                        let (rec, rec_ok) = self.mesh_record_base_and_ok(layout, ms_global);
                        let local_idx = self.raw_expr(Expression::FunctionArgument(3));
                        let zero = self.lit_u32(0);
                        let is_lane0 = self.emit_bin(BinaryOperator::Equal, local_idx, zero);
                        let mut cond = self.emit_bin(BinaryOperator::LogicalAnd, is_lane0, rec_ok);
                        if self.exec_local.is_some() {
                            let exec = self.load_exec();
                            let active = self.emit_bin(BinaryOperator::NotEqual, exec, zero);
                            cond = self.emit_bin(BinaryOperator::LogicalAnd, cond, active);
                        }
                        let accept = self.lower_nested(|s| {
                            let m0 = s.load_m0();
                            let mask11 = s.lit_u32(0x7FF);
                            let shift12 = s.lit_u32(12);
                            let raw_verts = s.emit_bin(BinaryOperator::And, m0, mask11);
                            let max_v = s.lit_u32(layout.max_vertices);
                            let verts = s.emit_expr(Expression::Math {
                                fun: MathFunction::Min,
                                arg: raw_verts,
                                arg1: Some(max_v),
                                arg2: None,
                                arg3: None,
                            });
                            let shifted = s.emit_bin(BinaryOperator::ShiftRight, m0, shift12);
                            let raw_prims = s.emit_bin(BinaryOperator::And, shifted, mask11);
                            let max_p = s.lit_u32(layout.max_primitives);
                            let prims = s.emit_expr(Expression::Math {
                                fun: MathFunction::Min,
                                arg: raw_prims,
                                arg1: Some(max_p),
                                arg2: None,
                                arg3: None,
                            });
                            let c0 = s.lit_u32(0);
                            let c1 = s.lit_u32(1);
                            let c2 = s.lit_u32(2);
                            let c3 = s.lit_u32(3);
                            let w0 = s.emit_bin(BinaryOperator::Add, rec, c0);
                            let w1 = s.emit_bin(BinaryOperator::Add, rec, c1);
                            let w2 = s.emit_bin(BinaryOperator::Add, rec, c2);
                            let w3 = s.emit_bin(BinaryOperator::Add, rec, c3);
                            let z0 = s.lit_u32(0);
                            let z1 = s.lit_u32(0);
                            s.emit_mesh_store_u32(ms_global, w0, verts);
                            s.emit_mesh_store_u32(ms_global, w1, prims);
                            s.emit_mesh_store_u32(ms_global, w2, z0);
                            s.emit_mesh_store_u32(ms_global, w3, z1);
                        });
                        self.push_stmt(Statement::If {
                            condition: cond,
                            accept,
                            reject: naga::Block::new(),
                        });
                    }
                    true
                }
                SENDMSG_ID_GS | SENDMSG_ID_GS_DONE => true,
                _ => false,
            },
            _ => false,
        }
    }

    fn translate_sopc(&mut self, op: u8, ssrc0: u8, ssrc1: u8, literal: Option<u32>) -> bool {
        match op {
            // s_bitcmp0_b32 / s_bitcmp1_b32: scc = (src0 & (1u << (src1 & 31u))) ==/!= 0u
            0x0C | 0x0D => {
                let v = self.read_src_u32(u16::from(ssrc0), literal);
                let idx_raw = self.read_src_u32(u16::from(ssrc1), literal);
                let mask31 = self.lit_u32(31);
                let idx = self.emit_bin(BinaryOperator::And, idx_raw, mask31);
                let one = self.lit_u32(1);
                let bit_mask = self.emit_bin(BinaryOperator::ShiftLeft, one, idx);
                let bit = self.emit_bin(BinaryOperator::And, v, bit_mask);
                let zero = self.lit_u32(0);
                let cmp_op = if op == 0x0C {
                    BinaryOperator::Equal
                } else {
                    BinaryOperator::NotEqual
                };
                let cmp = self.emit_bin(cmp_op, bit, zero);
                self.store_scc(cmp);
                return true;
            }
            // s_bitcmp0_b64 / s_bitcmp1_b64: test bit (src1 & 63) of the 64-bit src0 pair
            0x0E | 0x0F => {
                let (lo, hi) = self.read_ssrc_pair(ssrc0, literal);
                let idx_raw = self.read_src_u32(u16::from(ssrc1), literal);
                let mask63 = self.lit_u32(63);
                let mask31 = self.lit_u32(31);
                let c32 = self.lit_u32(32);
                let idx = self.emit_bin(BinaryOperator::And, idx_raw, mask63);
                let in_hi = self.emit_bin(BinaryOperator::GreaterEqual, idx, c32);
                let word = self.emit_select(in_hi, hi, lo);
                let sh = self.emit_bin(BinaryOperator::And, idx, mask31);
                let one = self.lit_u32(1);
                let bit_mask = self.emit_bin(BinaryOperator::ShiftLeft, one, sh);
                let bit = self.emit_bin(BinaryOperator::And, word, bit_mask);
                let zero = self.lit_u32(0);
                let cmp_op = if op == 0x0E {
                    BinaryOperator::Equal
                } else {
                    BinaryOperator::NotEqual
                };
                let cmp = self.emit_bin(cmp_op, bit, zero);
                self.store_scc(cmp);
                return true;
            }
            // s_cmp_eq_u64 / s_cmp_lg_u64 on SGPR pairs
            0x12 | 0x13 => {
                let (a_lo, a_hi) = self.read_ssrc_pair(ssrc0, literal);
                let (b_lo, b_hi) = self.read_ssrc_pair(ssrc1, literal);
                let cmp = if op == 0x12 {
                    let eq_lo = self.emit_bin(BinaryOperator::Equal, a_lo, b_lo);
                    let eq_hi = self.emit_bin(BinaryOperator::Equal, a_hi, b_hi);
                    self.emit_bin(BinaryOperator::LogicalAnd, eq_lo, eq_hi)
                } else {
                    let ne_lo = self.emit_bin(BinaryOperator::NotEqual, a_lo, b_lo);
                    let ne_hi = self.emit_bin(BinaryOperator::NotEqual, a_hi, b_hi);
                    self.emit_bin(BinaryOperator::LogicalOr, ne_lo, ne_hi)
                };
                self.store_scc(cmp);
                return true;
            }
            _ => {}
        }
        let bin_op = match op {
            0x00 | 0x06 => BinaryOperator::Equal,
            0x01 | 0x07 => BinaryOperator::NotEqual,
            0x02 | 0x08 => BinaryOperator::Greater,
            0x03 | 0x09 => BinaryOperator::GreaterEqual,
            0x04 | 0x0A => BinaryOperator::Less,
            0x05 | 0x0B => BinaryOperator::LessEqual,
            _ => return false,
        };
        let is_signed = op <= 0x05;
        let (left, right) = if is_signed {
            (
                self.read_src_i32(u16::from(ssrc0), literal),
                self.read_src_i32(u16::from(ssrc1), literal),
            )
        } else {
            (
                self.read_src_u32(u16::from(ssrc0), literal),
                self.read_src_u32(u16::from(ssrc1), literal),
            )
        };
        let cmp = self.emit_expr(Expression::Binary {
            op: bin_op,
            left,
            right,
        });
        self.store_scc(cmp);
        true
    }

    fn translate_sop1(&mut self, op: u8, sdst: u8, ssrc0: u8, literal: Option<u32>) -> bool {
        match op {
            // s_mov_b32 / s_wqm_b32 (whole-quad-mode exec mask setup is identity in WGSL)
            0x03 | 0x09 => {
                let v = self.read_src_u32(u16::from(ssrc0), literal);
                self.store_sgpr_u32(sdst, v);
                if op == 0x09 {
                    self.update_scc_nonzero(v);
                }
                true
            }
            // s_mov_b64 / s_wqm_b64: 64-bit scalar register-pair move (evaluate both halves before storing)
            0x04 | 0x0A => {
                let (lo, hi) = self.read_ssrc_pair(ssrc0, literal);
                match sdst {
                    0..=104 => {
                        self.store_sgpr_u32(sdst, lo);
                        self.store_sgpr_u32(sdst + 1, hi);
                    }
                    105 => {
                        self.store_sgpr_u32(105, lo);
                    }
                    106 => {
                        let combined = self.emit_expr(Expression::Binary {
                            op: BinaryOperator::InclusiveOr,
                            left: lo,
                            right: hi,
                        });
                        let zero = self.lit_u32(0);
                        let cond = self.emit_expr(Expression::Binary {
                            op: BinaryOperator::NotEqual,
                            left: combined,
                            right: zero,
                        });
                        self.store_vcc(cond);
                    }
                    126 => self.store_exec_lane_bit(lo),
                    _ => {}
                }
                true
            }
            // s_cmov_b32
            0x05 => {
                let cond = self.load_scc();
                let accept = self.read_src_u32(u16::from(ssrc0), literal);
                let reject = self.load_sgpr_u32(sdst);
                let res = self.emit_expr(Expression::Select {
                    condition: cond,
                    accept,
                    reject,
                });
                self.store_sgpr_u32(sdst, res);
                true
            }
            // s_cmov_b64: scc ? src0[0:1] : sdst[0:1]
            0x06 => {
                let cond = self.load_scc();
                let (a_lo, a_hi) = self.read_ssrc_pair(ssrc0, literal);
                let (r_lo, r_hi) = self.read_ssrc_pair(sdst, None);
                let lo = self.emit_select(cond, a_lo, r_lo);
                let hi = self.emit_select(cond, a_hi, r_hi);
                self.store_sdst_pair(sdst, lo, hi);
                true
            }
            // s_not_b32
            0x07 => {
                let v = self.read_src_u32(u16::from(ssrc0), literal);
                let res = self.emit_expr(Expression::Unary {
                    op: UnaryOperator::BitwiseNot,
                    expr: v,
                });
                self.store_sgpr_u32(sdst, res);
                self.update_scc_nonzero(res);
                true
            }
            // s_not_b64: 64-bit bitwise NOT on SGPR pair; SCC = ((lo | hi) != 0)
            0x08 => {
                let (lo, hi) = self.read_ssrc_pair(ssrc0, literal);
                let nlo = self.emit_bit_not(lo);
                let nhi = self.emit_bit_not(hi);
                self.store_sdst_pair(sdst, nlo, nhi);
                self.update_scc_nonzero_pair(nlo, nhi);
                true
            }
            // s_brev_b32
            0x0B => {
                let v = self.read_src_u32(u16::from(ssrc0), literal);
                let res = self.emit_expr(Expression::Math {
                    fun: MathFunction::ReverseBits,
                    arg: v,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                self.store_sgpr_u32(sdst, res);
                true
            }
            // s_brev_b64: 64-bit bit-reversal across SGPR pair
            0x0C => {
                let (lo, hi) = self.read_ssrc_pair(ssrc0, literal);
                let rev_lo = self.emit_expr(Expression::Math {
                    fun: MathFunction::ReverseBits,
                    arg: hi,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let rev_hi = self.emit_expr(Expression::Math {
                    fun: MathFunction::ReverseBits,
                    arg: lo,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                self.store_sdst_pair(sdst, rev_lo, rev_hi);
                true
            }
            // s_bcnt0_i32_b32: count zero bits in 32-bit src0; scc = (res != 0)
            0x0D => {
                let v = self.read_src_u32(u16::from(ssrc0), literal);
                let inv = self.emit_bit_not(v);
                let res = self.emit_expr(Expression::Math {
                    fun: MathFunction::CountOneBits,
                    arg: inv,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                self.store_sgpr_u32(sdst, res);
                self.update_scc_nonzero(res);
                true
            }
            // s_bcnt0_i32_b64 (0x0E) / s_bcnt1_i32_b64 (0x10): count 0/1 bits in 64-bit src0; scc = (res != 0)
            0x0E | 0x10 => {
                let (lo_raw, hi_raw) = self.read_ssrc_pair(ssrc0, literal);
                let (lo, hi) = if op == 0x0E {
                    (self.emit_bit_not(lo_raw), self.emit_bit_not(hi_raw))
                } else {
                    (lo_raw, hi_raw)
                };
                let c_lo = self.emit_expr(Expression::Math {
                    fun: MathFunction::CountOneBits,
                    arg: lo,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let c_hi = self.emit_expr(Expression::Math {
                    fun: MathFunction::CountOneBits,
                    arg: hi,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let res = self.emit_bin(BinaryOperator::Add, c_lo, c_hi);
                self.store_sgpr_u32(sdst, res);
                self.update_scc_nonzero(res);
                true
            }
            // s_bcnt1_i32_b32
            0x0F => {
                let v = self.read_src_u32(u16::from(ssrc0), literal);
                let res = self.emit_expr(Expression::Math {
                    fun: MathFunction::CountOneBits,
                    arg: v,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                self.store_sgpr_u32(sdst, res);
                self.update_scc_nonzero(res);
                true
            }
            // s_ff0_i32_b32: find first 0 bit from LSB; returns -1 (0xFFFFFFFF) when src0 == ~0
            0x11 => {
                let v = self.read_src_u32(u16::from(ssrc0), literal);
                let inv = self.emit_bit_not(v);
                let ctz = self.emit_expr(Expression::Math {
                    fun: MathFunction::CountTrailingZeros,
                    arg: inv,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let zero = self.lit_u32(0);
                let is_zero = self.emit_bin(BinaryOperator::Equal, inv, zero);
                let neg_one = self.lit_u32(0xFFFF_FFFF);
                let res = self.emit_select(is_zero, neg_one, ctz);
                self.store_sgpr_u32(sdst, res);
                true
            }
            // s_ff0_i32_b64 (0x12) / s_ff1_i32_b64 (0x14): find first 0/1 bit from LSB in 64-bit src0
            0x12 | 0x14 => {
                let (lo_raw, hi_raw) = self.read_ssrc_pair(ssrc0, literal);
                let (lo, hi) = if op == 0x12 {
                    (self.emit_bit_not(lo_raw), self.emit_bit_not(hi_raw))
                } else {
                    (lo_raw, hi_raw)
                };
                let ctz_lo = self.emit_expr(Expression::Math {
                    fun: MathFunction::CountTrailingZeros,
                    arg: lo,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let ctz_hi = self.emit_expr(Expression::Math {
                    fun: MathFunction::CountTrailingZeros,
                    arg: hi,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let c32 = self.lit_u32(32);
                let hi_pos = self.emit_bin(BinaryOperator::Add, ctz_hi, c32);
                let zero = self.lit_u32(0);
                let neg_one = self.lit_u32(0xFFFF_FFFF);
                let hi_nz = self.emit_bin(BinaryOperator::NotEqual, hi, zero);
                let from_hi = self.emit_select(hi_nz, hi_pos, neg_one);
                let lo_nz = self.emit_bin(BinaryOperator::NotEqual, lo, zero);
                let res = self.emit_select(lo_nz, ctz_lo, from_hi);
                self.store_sgpr_u32(sdst, res);
                true
            }
            // s_ff1_i32_b32: find first 1 bit from LSB; returns -1 (0xFFFFFFFF) when src0 == 0
            0x13 => {
                let v = self.read_src_u32(u16::from(ssrc0), literal);
                let ctz = self.emit_expr(Expression::Math {
                    fun: MathFunction::CountTrailingZeros,
                    arg: v,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let zero = self.lit_u32(0);
                let is_zero = self.emit_bin(BinaryOperator::Equal, v, zero);
                let neg_one = self.lit_u32(0xFFFF_FFFF);
                let res = self.emit_select(is_zero, neg_one, ctz);
                self.store_sgpr_u32(sdst, res);
                true
            }
            // s_flbit_i32_b32: count leading zeros from MSB; returns -1 (0xFFFFFFFF) when src0 == 0
            0x15 => {
                let v = self.read_src_u32(u16::from(ssrc0), literal);
                let clz = self.emit_expr(Expression::Math {
                    fun: MathFunction::CountLeadingZeros,
                    arg: v,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let zero = self.lit_u32(0);
                let is_zero = self.emit_bin(BinaryOperator::Equal, v, zero);
                let neg_one = self.lit_u32(0xFFFF_FFFF);
                let res = self.emit_select(is_zero, neg_one, clz);
                self.store_sgpr_u32(sdst, res);
                true
            }
            // s_flbit_i32_b64: count leading zeros from MSB in 64-bit src0; -1 when 0
            0x16 => {
                let (lo, hi) = self.read_ssrc_pair(ssrc0, literal);
                let clz_hi = self.emit_expr(Expression::Math {
                    fun: MathFunction::CountLeadingZeros,
                    arg: hi,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let clz_lo = self.emit_expr(Expression::Math {
                    fun: MathFunction::CountLeadingZeros,
                    arg: lo,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let c32 = self.lit_u32(32);
                let lo_pos = self.emit_bin(BinaryOperator::Add, clz_lo, c32);
                let zero = self.lit_u32(0);
                let neg_one = self.lit_u32(0xFFFF_FFFF);
                let lo_nz = self.emit_bin(BinaryOperator::NotEqual, lo, zero);
                let from_lo = self.emit_select(lo_nz, lo_pos, neg_one);
                let hi_nz = self.emit_bin(BinaryOperator::NotEqual, hi, zero);
                let res = self.emit_select(hi_nz, clz_hi, from_lo);
                self.store_sgpr_u32(sdst, res);
                true
            }
            // s_flbit_i32: count leading bits matching MSB sign bit; -1 when 0 or -1
            0x17 => {
                let v = self.read_src_u32(u16::from(ssrc0), literal);
                let res = self.emit_ffbh_i32(v);
                self.store_sgpr_u32(sdst, res);
                true
            }
            // s_flbit_i32_i64: count leading bits matching MSB sign bit of 64-bit src0; -1 when 0 or -1
            0x18 => {
                let (lo, hi) = self.read_ssrc_pair(ssrc0, literal);
                let hi_i = self.bitcast_u32_to_i32(hi);
                let sh31 = self.lit_u32(31);
                let sign_i = self.emit_bin(BinaryOperator::ShiftRight, hi_i, sh31);
                let sign_mask = self.bitcast_i32_to_u32(sign_i);
                let x_lo = self.emit_bin(BinaryOperator::ExclusiveOr, lo, sign_mask);
                let x_hi = self.emit_bin(BinaryOperator::ExclusiveOr, hi, sign_mask);
                let clz_hi = self.emit_expr(Expression::Math {
                    fun: MathFunction::CountLeadingZeros,
                    arg: x_hi,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let clz_lo = self.emit_expr(Expression::Math {
                    fun: MathFunction::CountLeadingZeros,
                    arg: x_lo,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let c32 = self.lit_u32(32);
                let lo_pos = self.emit_bin(BinaryOperator::Add, clz_lo, c32);
                let zero = self.lit_u32(0);
                let neg_one = self.lit_u32(0xFFFF_FFFF);
                let lo_nz = self.emit_bin(BinaryOperator::NotEqual, x_lo, zero);
                let from_lo = self.emit_select(lo_nz, lo_pos, neg_one);
                let hi_nz = self.emit_bin(BinaryOperator::NotEqual, x_hi, zero);
                let res = self.emit_select(hi_nz, clz_hi, from_lo);
                self.store_sgpr_u32(sdst, res);
                true
            }
            // s_sext_i32_i8 / s_sext_i32_i16
            0x19 | 0x1A => {
                let v = self.read_src_i32(u16::from(ssrc0), literal);
                let shift_bits = if op == 0x19 { 24u32 } else { 16u32 };
                let sh = self.lit_u32(shift_bits);
                let left = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftLeft,
                    left: v,
                    right: sh,
                });
                let sext = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftRight,
                    left,
                    right: sh,
                });
                let u = self.bitcast_i32_to_u32(sext);
                self.store_sgpr_u32(sdst, u);
                true
            }
            // s_bitset0_b32 (0x1B) / s_bitset1_b32 (0x1D): clear/set bit (src0 & 31) in sdst
            0x1B | 0x1D => {
                let idx_raw = self.read_src_u32(u16::from(ssrc0), literal);
                let mask31 = self.lit_u32(31);
                let idx = self.emit_bin(BinaryOperator::And, idx_raw, mask31);
                let one = self.lit_u32(1);
                let bit = self.emit_bin(BinaryOperator::ShiftLeft, one, idx);
                let cur = self.load_sgpr_u32(sdst);
                let res = if op == 0x1D {
                    self.emit_bin(BinaryOperator::InclusiveOr, cur, bit)
                } else {
                    let nbit = self.emit_bit_not(bit);
                    self.emit_bin(BinaryOperator::And, cur, nbit)
                };
                self.store_sgpr_u32(sdst, res);
                true
            }
            // s_bitset0_b64 (0x1C) / s_bitset1_b64 (0x1E): clear/set bit (src0 & 63) in 64-bit sdst
            0x1C | 0x1E => {
                let idx_raw = self.read_src_u32(u16::from(ssrc0), literal);
                let mask63 = self.lit_u32(63);
                let mask31 = self.lit_u32(31);
                let c32 = self.lit_u32(32);
                let one = self.lit_u32(1);
                let idx = self.emit_bin(BinaryOperator::And, idx_raw, mask63);
                let in_hi = self.emit_bin(BinaryOperator::GreaterEqual, idx, c32);
                let sh = self.emit_bin(BinaryOperator::And, idx, mask31);
                let bit = self.emit_bin(BinaryOperator::ShiftLeft, one, sh);
                let (cur_lo, cur_hi) = self.read_ssrc_pair(sdst, None);
                let (mod_lo, mod_hi) = if op == 0x1E {
                    (
                        self.emit_bin(BinaryOperator::InclusiveOr, cur_lo, bit),
                        self.emit_bin(BinaryOperator::InclusiveOr, cur_hi, bit),
                    )
                } else {
                    let nbit = self.emit_bit_not(bit);
                    (
                        self.emit_bin(BinaryOperator::And, cur_lo, nbit),
                        self.emit_bin(BinaryOperator::And, cur_hi, nbit),
                    )
                };
                let out_lo = self.emit_select(in_hi, cur_lo, mod_lo);
                let out_hi = self.emit_select(in_hi, mod_hi, cur_hi);
                self.store_sdst_pair(sdst, out_lo, out_hi);
                true
            }
            // s_swappc_b64: Xbox FSSM driver-generated vertex fetch shader call.
            // Populate the target VGPRs from synthesized `VsIn` `@location(k)` attributes.
            0x21 if self.stage == ShaderStage::Vertex => {
                if let Some(arg_idx) = self.vs_in_arg
                    && !self.swappc_fetch_loads.is_empty()
                {
                    let vs_in = self.raw_expr(Expression::FunctionArgument(arg_idx));
                    let loads = self.swappc_fetch_loads.clone();
                    for (member_idx, attr) in loads {
                        let attr_val = self.emit_expr(Expression::AccessIndex {
                            base: vs_in,
                            index: member_idx,
                        });
                        if attr.components == 1 {
                            if self.vgpr_locals.contains_key(&attr.base_vgpr) {
                                match attr.component_type {
                                    "u32" => self.store_vgpr_u32(attr.base_vgpr, attr_val),
                                    "i32" => self.store_vgpr_i32(attr.base_vgpr, attr_val),
                                    _ => self.store_vgpr_f32(attr.base_vgpr, attr_val),
                                }
                            }
                        } else {
                            for lane in 0..attr.components {
                                if (attr.mask & (1u8 << lane)) == 0 {
                                    continue;
                                }
                                if let Some(reg) = checked_vgpr_reg(attr.base_vgpr, lane)
                                    && self.vgpr_locals.contains_key(&reg)
                                {
                                    let comp = self.emit_expr(Expression::AccessIndex {
                                        base: attr_val,
                                        index: u32::from(lane),
                                    });
                                    match attr.component_type {
                                        "u32" => self.store_vgpr_u32(reg, comp),
                                        "i32" => self.store_vgpr_i32(reg, comp),
                                        _ => self.store_vgpr_f32(reg, comp),
                                    }
                                }
                            }
                        }
                    }
                }
                true
            }
            // s_quadmask_b32: bit q (0..7) = (any bit in src0[4q+3:4q] != 0); scc = (res != 0)
            0x2C => {
                let v = self.read_src_u32(u16::from(ssrc0), literal);
                let one = self.lit_u32(1);
                let two = self.lit_u32(2);
                let v_r1 = self.emit_bin(BinaryOperator::ShiftRight, v, one);
                let t1 = self.emit_bin(BinaryOperator::InclusiveOr, v, v_r1);
                let t1_r2 = self.emit_bin(BinaryOperator::ShiftRight, t1, two);
                let t2 = self.emit_bin(BinaryOperator::InclusiveOr, t1, t1_r2);
                let mut res = self.emit_bin(BinaryOperator::And, t2, one);
                for q in 1..8u32 {
                    let sh = self.lit_u32(q * 4);
                    let shifted = self.emit_bin(BinaryOperator::ShiftRight, t2, sh);
                    let bit = self.emit_bin(BinaryOperator::And, shifted, one);
                    let q_lit = self.lit_u32(q);
                    let placed = self.emit_bin(BinaryOperator::ShiftLeft, bit, q_lit);
                    res = self.emit_bin(BinaryOperator::InclusiveOr, res, placed);
                }
                self.store_sgpr_u32(sdst, res);
                self.update_scc_nonzero(res);
                true
            }
            // s_quadmask_b64: bit q (0..15) = (any bit in src0[4q+3:4q] != 0); scc = (res != 0)
            0x2D => {
                let (lo, hi) = self.read_ssrc_pair(ssrc0, literal);
                let one = self.lit_u32(1);
                let two = self.lit_u32(2);
                let collapse = |this: &mut Self, word: Handle<Expression>| {
                    let r1 = this.emit_bin(BinaryOperator::ShiftRight, word, one);
                    let t1 = this.emit_bin(BinaryOperator::InclusiveOr, word, r1);
                    let r2 = this.emit_bin(BinaryOperator::ShiftRight, t1, two);
                    let t2 = this.emit_bin(BinaryOperator::InclusiveOr, t1, r2);
                    let mut out = this.emit_bin(BinaryOperator::And, t2, one);
                    for q in 1..8u32 {
                        let sh = this.lit_u32(q * 4);
                        let shifted = this.emit_bin(BinaryOperator::ShiftRight, t2, sh);
                        let bit = this.emit_bin(BinaryOperator::And, shifted, one);
                        let q_lit = this.lit_u32(q);
                        let placed = this.emit_bin(BinaryOperator::ShiftLeft, bit, q_lit);
                        out = this.emit_bin(BinaryOperator::InclusiveOr, out, placed);
                    }
                    out
                };
                let q_lo = collapse(self, lo);
                let q_hi = collapse(self, hi);
                let c8 = self.lit_u32(8);
                let q_hi_sh = self.emit_bin(BinaryOperator::ShiftLeft, q_hi, c8);
                let res_lo = self.emit_bin(BinaryOperator::InclusiveOr, q_lo, q_hi_sh);
                let res_hi = self.lit_u32(0);
                self.store_sdst_pair(sdst, res_lo, res_hi);
                self.update_scc_nonzero_pair(res_lo, res_hi);
                true
            }
            // s_abs_i32
            0x34 => {
                let v = self.read_src_i32(u16::from(ssrc0), literal);
                let a = self.emit_expr(Expression::Math {
                    fun: MathFunction::Abs,
                    arg: v,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let u = self.bitcast_i32_to_u32(a);
                self.store_sgpr_u32(sdst, u);
                true
            }
            _ => false,
        }
    }

    fn translate_sopk(&mut self, op: u8, sdst: u8, simm16: u16) -> bool {
        let imm_u32 = (simm16 as i16 as i32) as u32;
        match op {
            // s_movk_i32
            0x00 => {
                let v = self.lit_u32(imm_u32);
                self.store_sgpr_u32(sdst, v);
                true
            }
            // s_version: ISA version metadata hint (no-op)
            0x01 => true,
            // s_cmovk_i32: scc ? sext16(simm16) : sdst
            0x02 => {
                let cond = self.load_scc();
                let accept = self.lit_u32(imm_u32);
                let reject = self.load_sgpr_u32(sdst);
                let res = self.emit_select(cond, accept, reject);
                self.store_sgpr_u32(sdst, res);
                true
            }
            // s_cmpk_{eq,lg,gt,ge,lt,le}_{i32,u32}: compare sdst against sign/zero-extended simm16 -> SCC
            0x03..=0x0E => {
                let is_signed = op <= 0x08;
                let cc = if is_signed { op - 0x03 } else { op - 0x09 };
                let bin_op = match cc {
                    0 => BinaryOperator::Equal,
                    1 => BinaryOperator::NotEqual,
                    2 => BinaryOperator::Greater,
                    3 => BinaryOperator::GreaterEqual,
                    4 => BinaryOperator::Less,
                    _ => BinaryOperator::LessEqual,
                };
                let (lhs, rhs) = if is_signed {
                    (
                        self.read_src_i32(u16::from(sdst), None),
                        self.lit_i32(i32::from(simm16 as i16)),
                    )
                } else {
                    (
                        self.read_src_u32(u16::from(sdst), None),
                        self.lit_u32(u32::from(simm16)),
                    )
                };
                let cmp = self.emit_bin(bin_op, lhs, rhs);
                self.store_scc(cmp);
                true
            }
            // s_addk_i32
            0x0F => {
                let lhs = self.load_sgpr_u32(sdst);
                let rhs = self.lit_u32(imm_u32);
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Add,
                    left: lhs,
                    right: rhs,
                });
                self.store_sgpr_u32(sdst, res);
                true
            }
            // s_mulk_i32
            0x10 => {
                let lhs = self.load_sgpr_u32(sdst);
                let rhs = self.lit_u32(imm_u32);
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Multiply,
                    left: lhs,
                    right: rhs,
                });
                self.store_sgpr_u32(sdst, res);
                true
            }
            // s_setreg_b32 / s_setreg_imm32_b32 (hardware mode/config hints) &
            // s_waitcnt_vscnt / vmcnt / expcnt / lgkmcnt
            0x12 | 0x15 | 0x17..=0x1A => true,
            _ => false,
        }
    }

    fn translate_sop2(
        &mut self,
        op: u8,
        sdst: u8,
        ssrc0: u8,
        ssrc1: u8,
        literal: Option<u32>,
    ) -> bool {
        let s0_u = || u16::from(ssrc0);
        let s1_u = || u16::from(ssrc1);
        match op {
            // s_add_u32 / s_add_i32
            0x00 | 0x02 => {
                let l = self.read_src_u32(s0_u(), literal);
                let r = self.read_src_u32(s1_u(), literal);
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Add,
                    left: l,
                    right: r,
                });
                self.store_sgpr_u32(sdst, res);
                if op == 0x00 && self.scc_local.is_some() {
                    let carry = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::Less,
                        left: res,
                        right: l,
                    });
                    self.store_scc(carry);
                }
                true
            }
            // s_sub_u32 / s_sub_i32
            0x01 | 0x03 => {
                let l = self.read_src_u32(s0_u(), literal);
                let r = self.read_src_u32(s1_u(), literal);
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Subtract,
                    left: l,
                    right: r,
                });
                self.store_sgpr_u32(sdst, res);
                if op == 0x01 && self.scc_local.is_some() {
                    let borrow = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::Less,
                        left: l,
                        right: r,
                    });
                    self.store_scc(borrow);
                }
                true
            }
            // s_addc_u32: ssrc0 + ssrc1 + scc (sets scc = carry-out)
            0x04 => {
                let l = self.read_src_u32(s0_u(), literal);
                let r = self.read_src_u32(s1_u(), literal);
                let scc_in = self.load_scc();
                let one = self.lit_u32(1);
                let zero = self.lit_u32(0);
                let cin = self.emit_select(scc_in, one, zero);
                let sum1 = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Add,
                    left: l,
                    right: r,
                });
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Add,
                    left: sum1,
                    right: cin,
                });
                self.store_sgpr_u32(sdst, res);
                if self.scc_local.is_some() {
                    let c1 = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::Less,
                        left: sum1,
                        right: l,
                    });
                    let c2 = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::Less,
                        left: res,
                        right: sum1,
                    });
                    let carry = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::LogicalOr,
                        left: c1,
                        right: c2,
                    });
                    self.store_scc(carry);
                }
                true
            }
            // s_subb_u32: ssrc0 - ssrc1 - scc (sets scc = borrow-out)
            0x05 => {
                let l = self.read_src_u32(s0_u(), literal);
                let r = self.read_src_u32(s1_u(), literal);
                let scc_in = self.load_scc();
                let one = self.lit_u32(1);
                let zero = self.lit_u32(0);
                let bin = self.emit_select(scc_in, one, zero);
                let diff1 = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Subtract,
                    left: l,
                    right: r,
                });
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Subtract,
                    left: diff1,
                    right: bin,
                });
                self.store_sgpr_u32(sdst, res);
                if self.scc_local.is_some() {
                    let b1 = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::Less,
                        left: l,
                        right: r,
                    });
                    let b2 = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::Less,
                        left: diff1,
                        right: bin,
                    });
                    let borrow = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::LogicalOr,
                        left: b1,
                        right: b2,
                    });
                    self.store_scc(borrow);
                }
                true
            }
            // s_min_i32 / s_max_i32
            0x06 | 0x08 => {
                let l = self.read_src_i32(s0_u(), literal);
                let r = self.read_src_i32(s1_u(), literal);
                let fun = if op == 0x06 {
                    MathFunction::Min
                } else {
                    MathFunction::Max
                };
                let res = self.emit_expr(Expression::Math {
                    fun,
                    arg: l,
                    arg1: Some(r),
                    arg2: None,
                    arg3: None,
                });
                let u = self.bitcast_i32_to_u32(res);
                self.store_sgpr_u32(sdst, u);
                true
            }
            // s_min_u32 / s_max_u32
            0x07 | 0x09 => {
                let l = self.read_src_u32(s0_u(), literal);
                let r = self.read_src_u32(s1_u(), literal);
                let fun = if op == 0x07 {
                    MathFunction::Min
                } else {
                    MathFunction::Max
                };
                let res = self.emit_expr(Expression::Math {
                    fun,
                    arg: l,
                    arg1: Some(r),
                    arg2: None,
                    arg3: None,
                });
                self.store_sgpr_u32(sdst, res);
                true
            }
            // s_cselect_b32: scc ? ssrc0 : ssrc1
            0x0A => {
                let cond = self.load_scc();
                let accept = self.read_src_u32(s0_u(), literal);
                let reject = self.read_src_u32(s1_u(), literal);
                let res = self.emit_expr(Expression::Select {
                    condition: cond,
                    accept,
                    reject,
                });
                self.store_sgpr_u32(sdst, res);
                true
            }
            // s_cselect_b64: scc ? src0[0:1] : src1[0:1]
            0x0B => {
                let cond = self.load_scc();
                let (a_lo, a_hi) = self.read_ssrc_pair(ssrc0, literal);
                let (b_lo, b_hi) = self.read_ssrc_pair(ssrc1, literal);
                let lo = self.emit_select(cond, a_lo, b_lo);
                let hi = self.emit_select(cond, a_hi, b_hi);
                self.store_sdst_pair(sdst, lo, hi);
                true
            }
            // s_{and,or,xor,andn2,orn2,nand,nor,xnor}_b64 on SGPR pairs; scc = ((lo | hi) != 0u)
            0x0F | 0x11 | 0x13 | 0x15 | 0x17 | 0x19 | 0x1B | 0x1D => {
                let (l_lo, l_hi) = self.read_ssrc_pair(ssrc0, literal);
                let (r_lo, r_hi) = self.read_ssrc_pair(ssrc1, literal);
                let lo = self.emit_sop2_bitwise_half(op, l_lo, r_lo);
                let hi = self.emit_sop2_bitwise_half(op, l_hi, r_hi);
                self.store_sdst_pair(sdst, lo, hi);
                self.update_scc_nonzero_pair(lo, hi);
                true
            }
            // s_lshl_b64 / s_lshr_b64 / s_ashr_i64: 64-bit pair shift by (src1 & 63); scc = result != 0
            0x1F | 0x21 | 0x23 => {
                let (lo, hi) = self.read_ssrc_pair(ssrc0, literal);
                let amount = self.read_src_u32(s1_u(), literal);
                let kind = match op {
                    0x1F => Shift64Kind::Left,
                    0x21 => Shift64Kind::LogicalRight,
                    _ => Shift64Kind::ArithmeticRight,
                };
                let (rlo, rhi) = self.emit_shift64(kind, lo, hi, amount);
                self.store_sdst_pair(sdst, rlo, rhi);
                self.update_scc_nonzero_pair(rlo, rhi);
                true
            }
            // s_mul_hi_u32 / s_mul_hi_i32: exact high 32 bits of the 64-bit product
            0x35 | 0x36 => {
                let l = self.read_src_u32(s0_u(), literal);
                let r = self.read_src_u32(s1_u(), literal);
                let res = if op == 0x35 {
                    self.emit_mul_hi_u32(l, r)
                } else {
                    self.emit_mul_hi_i32(l, r)
                };
                self.store_sgpr_u32(sdst, res);
                true
            }
            // s_and_b32 / s_or_b32 / s_xor_b32
            0x0E | 0x10 | 0x12 => {
                let l = self.read_src_u32(s0_u(), literal);
                let r = self.read_src_u32(s1_u(), literal);
                let bin = match op {
                    0x0E => BinaryOperator::And,
                    0x10 => BinaryOperator::InclusiveOr,
                    _ => BinaryOperator::ExclusiveOr,
                };
                let res = self.emit_expr(Expression::Binary {
                    op: bin,
                    left: l,
                    right: r,
                });
                self.store_sgpr_u32(sdst, res);
                self.update_scc_nonzero(res);
                true
            }
            // s_andn2_b32 / s_orn2_b32: s0 & ~s1 / s0 | ~s1
            0x14 | 0x16 => {
                let l = self.read_src_u32(s0_u(), literal);
                let r = self.read_src_u32(s1_u(), literal);
                let nr = self.emit_expr(Expression::Unary {
                    op: UnaryOperator::BitwiseNot,
                    expr: r,
                });
                let bin = if op == 0x14 {
                    BinaryOperator::And
                } else {
                    BinaryOperator::InclusiveOr
                };
                let res = self.emit_expr(Expression::Binary {
                    op: bin,
                    left: l,
                    right: nr,
                });
                self.store_sgpr_u32(sdst, res);
                self.update_scc_nonzero(res);
                true
            }
            // s_nand_b32 / s_nor_b32 / s_xnor_b32: ~(s0 op s1)
            0x18 | 0x1A | 0x1C => {
                let l = self.read_src_u32(s0_u(), literal);
                let r = self.read_src_u32(s1_u(), literal);
                let bin = match op {
                    0x18 => BinaryOperator::And,
                    0x1A => BinaryOperator::InclusiveOr,
                    _ => BinaryOperator::ExclusiveOr,
                };
                let inner = self.emit_expr(Expression::Binary {
                    op: bin,
                    left: l,
                    right: r,
                });
                let res = self.emit_expr(Expression::Unary {
                    op: UnaryOperator::BitwiseNot,
                    expr: inner,
                });
                self.store_sgpr_u32(sdst, res);
                self.update_scc_nonzero(res);
                true
            }
            // s_lshl_b32 / s_lshr_b32
            0x1E | 0x20 => {
                let l = self.read_src_u32(s0_u(), literal);
                let r = self.read_src_u32(s1_u(), literal);
                let mask = self.lit_u32(31);
                let shift = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: r,
                    right: mask,
                });
                let bin = if op == 0x1E {
                    BinaryOperator::ShiftLeft
                } else {
                    BinaryOperator::ShiftRight
                };
                let res = self.emit_expr(Expression::Binary {
                    op: bin,
                    left: l,
                    right: shift,
                });
                self.store_sgpr_u32(sdst, res);
                self.update_scc_nonzero(res);
                true
            }
            // s_ashr_i32
            0x22 => {
                let l = self.read_src_i32(s0_u(), literal);
                let r = self.read_src_u32(s1_u(), literal);
                let mask = self.lit_u32(31);
                let shift = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: r,
                    right: mask,
                });
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftRight,
                    left: l,
                    right: shift,
                });
                let u = self.bitcast_i32_to_u32(res);
                self.store_sgpr_u32(sdst, u);
                self.update_scc_nonzero(u);
                true
            }
            // s_bfm_b32: ((1u << (s0 & 31)) - 1u) << (s1 & 31)
            0x24 => {
                let l = self.read_src_u32(s0_u(), literal);
                let r = self.read_src_u32(s1_u(), literal);
                let mask31 = self.lit_u32(31);
                let width = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: l,
                    right: mask31,
                });
                let offset = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: r,
                    right: mask31,
                });
                let one = self.lit_u32(1);
                let sh_w = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftLeft,
                    left: one,
                    right: width,
                });
                let base_mask = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Subtract,
                    left: sh_w,
                    right: one,
                });
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftLeft,
                    left: base_mask,
                    right: offset,
                });
                self.store_sgpr_u32(sdst, res);
                true
            }
            // s_bfm_b64: ((1u64 << (s0 & 63)) - 1u64) << (s1 & 63) -> s[sdst:sdst+1]
            0x25 => {
                if let (Some(w_i), Some(o_i)) = (
                    decode_inline_u32_src(s0_u(), literal),
                    decode_inline_u32_src(s1_u(), literal),
                ) {
                    let w = (w_i as u32) & 63;
                    let o = (o_i as u32) & 63;
                    let base: u64 = if w == 0 {
                        0
                    } else if w >= 64 {
                        u64::MAX
                    } else {
                        (1u64 << w) - 1
                    };
                    let val = base.wrapping_shl(o);
                    let lo = self.lit_u32(val as u32);
                    let hi = self.lit_u32((val >> 32) as u32);
                    self.store_sgpr_u32(sdst, lo);
                    if sdst <= 104 {
                        self.store_sgpr_u32(sdst + 1, hi);
                    }
                } else {
                    // Dynamic width/offset: compute 32-bit low half and zero-extended high half.
                    let l = self.read_src_u32(s0_u(), literal);
                    let r = self.read_src_u32(s1_u(), literal);
                    let mask31 = self.lit_u32(31);
                    let width = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::And,
                        left: l,
                        right: mask31,
                    });
                    let offset = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::And,
                        left: r,
                        right: mask31,
                    });
                    let one = self.lit_u32(1);
                    let sh_w = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::ShiftLeft,
                        left: one,
                        right: width,
                    });
                    let base_mask = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::Subtract,
                        left: sh_w,
                        right: one,
                    });
                    let lo = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::ShiftLeft,
                        left: base_mask,
                        right: offset,
                    });
                    let zero = self.lit_u32(0);
                    self.store_sgpr_u32(sdst, lo);
                    if sdst <= 104 {
                        self.store_sgpr_u32(sdst + 1, zero);
                    }
                }
                true
            }
            // s_mul_i32
            0x26 => {
                let l = self.read_src_u32(s0_u(), literal);
                let r = self.read_src_u32(s1_u(), literal);
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Multiply,
                    left: l,
                    right: r,
                });
                self.store_sgpr_u32(sdst, res);
                true
            }
            // s_bfe_u32: unsigned bitfield extract
            //   offset = src1[4:0], width = src1[22:16]
            //   sdst = (width == 0) ? 0 : ((src0 >> offset) & mask(width))
            0x27 => {
                let s0 = self.read_src_u32(s0_u(), literal);
                let s1 = self.read_src_u32(s1_u(), literal);
                let mask31 = self.lit_u32(31);
                let offset = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: s1,
                    right: mask31,
                });
                let shift16 = self.lit_u32(16);
                let s1_hi = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftRight,
                    left: s1,
                    right: shift16,
                });
                let mask7f = self.lit_u32(0x7F);
                let width = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: s1_hi,
                    right: mask7f,
                });
                let shifted = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftRight,
                    left: s0,
                    right: offset,
                });
                let max_shift = self.lit_u32(31);
                let safe_w = self.emit_expr(Expression::Math {
                    fun: MathFunction::Min,
                    arg: width,
                    arg1: Some(max_shift),
                    arg2: None,
                    arg3: None,
                });
                let one = self.lit_u32(1);
                let one_shl = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftLeft,
                    left: one,
                    right: safe_w,
                });
                let narrow_mask = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Subtract,
                    left: one_shl,
                    right: one,
                });
                let lit32 = self.lit_u32(32);
                let wide = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::GreaterEqual,
                    left: width,
                    right: lit32,
                });
                let all_ones = self.lit_u32(0xFFFF_FFFF);
                let eff_mask = self.emit_expr(Expression::Select {
                    condition: wide,
                    accept: all_ones,
                    reject: narrow_mask,
                });
                let extracted = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: shifted,
                    right: eff_mask,
                });
                let zero = self.lit_u32(0);
                let is_zero_w = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Equal,
                    left: width,
                    right: zero,
                });
                let res = self.emit_expr(Expression::Select {
                    condition: is_zero_w,
                    accept: zero,
                    reject: extracted,
                });
                self.store_sgpr_u32(sdst, res);
                let nonzero = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::NotEqual,
                    left: res,
                    right: zero,
                });
                self.store_scc(nonzero);
                true
            }
            // s_bfe_i32: signed bitfield extract (offset = src1[4:0], width = src1[22:16])
            0x28 => {
                let s0_i = self.read_src_i32(s0_u(), literal);
                let s1 = self.read_src_u32(s1_u(), literal);
                let mask31 = self.lit_u32(31);
                let offset = self.emit_bin(BinaryOperator::And, s1, mask31);
                let shift16 = self.lit_u32(16);
                let s1_hi = self.emit_bin(BinaryOperator::ShiftRight, s1, shift16);
                let mask7f = self.lit_u32(0x7F);
                let width = self.emit_bin(BinaryOperator::And, s1_hi, mask7f);
                let res_i = self.emit_bfe_i32(s0_i, offset, width);
                let res_u = self.bitcast_i32_to_u32(res_i);
                self.store_sgpr_u32(sdst, res_u);
                self.update_scc_nonzero(res_u);
                true
            }
            // s_bfe_u64: unsigned 64-bit bitfield extract (offset = src1[5:0], width = src1[22:16])
            0x29 => {
                let (lo, hi) = self.read_ssrc_pair(ssrc0, literal);
                let s1 = self.read_src_u32(s1_u(), literal);
                let mask63 = self.lit_u32(63);
                let mask31 = self.lit_u32(31);
                let mask7f = self.lit_u32(0x7F);
                let shift16 = self.lit_u32(16);
                let c32 = self.lit_u32(32);
                let c64 = self.lit_u32(64);
                let zero = self.lit_u32(0);
                let one = self.lit_u32(1);
                let all_ones = self.lit_u32(0xFFFF_FFFF);
                let offset = self.emit_bin(BinaryOperator::And, s1, mask63);
                let s1_hi = self.emit_bin(BinaryOperator::ShiftRight, s1, shift16);
                let width = self.emit_bin(BinaryOperator::And, s1_hi, mask7f);
                let (s_lo, s_hi) = self.emit_shift64(Shift64Kind::LogicalRight, lo, hi, offset);

                let w_lo_safe = self.emit_bin(BinaryOperator::And, width, mask31);
                let sh_lo = self.emit_bin(BinaryOperator::ShiftLeft, one, w_lo_safe);
                let m_lo_part = self.emit_bin(BinaryOperator::Subtract, sh_lo, one);
                let ge32 = self.emit_bin(BinaryOperator::GreaterEqual, width, c32);
                let mask_lo = self.emit_select(ge32, all_ones, m_lo_part);

                let w_hi_raw = self.emit_bin(BinaryOperator::Subtract, width, c32);
                let w_hi_safe = self.emit_bin(BinaryOperator::And, w_hi_raw, mask31);
                let sh_hi = self.emit_bin(BinaryOperator::ShiftLeft, one, w_hi_safe);
                let m_hi_part = self.emit_bin(BinaryOperator::Subtract, sh_hi, one);
                let le32 = self.emit_bin(BinaryOperator::LessEqual, width, c32);
                let ge64 = self.emit_bin(BinaryOperator::GreaterEqual, width, c64);
                let m_hi_nz = self.emit_select(ge64, all_ones, m_hi_part);
                let mask_hi = self.emit_select(le32, zero, m_hi_nz);

                let r_lo = self.emit_bin(BinaryOperator::And, s_lo, mask_lo);
                let r_hi = self.emit_bin(BinaryOperator::And, s_hi, mask_hi);
                self.store_sdst_pair(sdst, r_lo, r_hi);
                self.update_scc_nonzero_pair(r_lo, r_hi);
                true
            }
            // s_bfe_i64: signed 64-bit bitfield extract (offset = src1[5:0], width = src1[22:16])
            0x2A => {
                let (lo, hi) = self.read_ssrc_pair(ssrc0, literal);
                let s1 = self.read_src_u32(s1_u(), literal);
                let mask63 = self.lit_u32(63);
                let mask7f = self.lit_u32(0x7F);
                let shift16 = self.lit_u32(16);
                let c64 = self.lit_u32(64);
                let zero = self.lit_u32(0);
                let offset = self.emit_bin(BinaryOperator::And, s1, mask63);
                let s1_hi = self.emit_bin(BinaryOperator::ShiftRight, s1, shift16);
                let width = self.emit_bin(BinaryOperator::And, s1_hi, mask7f);
                let sum = self.emit_bin(BinaryOperator::Add, offset, width);
                let is_wide = self.emit_bin(BinaryOperator::GreaterEqual, sum, c64);
                let is_zero = self.emit_bin(BinaryOperator::Equal, width, zero);
                let (w_lo, w_hi) = self.emit_shift64(Shift64Kind::ArithmeticRight, lo, hi, offset);
                let lsh_raw = self.emit_bin(BinaryOperator::Subtract, c64, sum);
                let lsh = self.emit_bin(BinaryOperator::And, lsh_raw, mask63);
                let rsh_raw = self.emit_bin(BinaryOperator::Subtract, c64, width);
                let rsh = self.emit_bin(BinaryOperator::And, rsh_raw, mask63);
                let (t_lo, t_hi) = self.emit_shift64(Shift64Kind::Left, lo, hi, lsh);
                let (n_lo, n_hi) = self.emit_shift64(Shift64Kind::ArithmeticRight, t_lo, t_hi, rsh);
                let nz_lo = self.emit_select(is_wide, w_lo, n_lo);
                let nz_hi = self.emit_select(is_wide, w_hi, n_hi);
                let r_lo = self.emit_select(is_zero, zero, nz_lo);
                let r_hi = self.emit_select(is_zero, zero, nz_hi);
                self.store_sdst_pair(sdst, r_lo, r_hi);
                self.update_scc_nonzero_pair(r_lo, r_hi);
                true
            }
            // s_absdiff_i32: unsigned |i32(src0) - i32(src1)|; scc = (res != 0)
            0x2C => {
                let a_i = self.read_src_i32(s0_u(), literal);
                let b_i = self.read_src_i32(s1_u(), literal);
                let a_u = self.bitcast_i32_to_u32(a_i);
                let b_u = self.bitcast_i32_to_u32(b_i);
                let a_ge_b = self.emit_bin(BinaryOperator::GreaterEqual, a_i, b_i);
                let ab = self.emit_bin(BinaryOperator::Subtract, a_u, b_u);
                let ba = self.emit_bin(BinaryOperator::Subtract, b_u, a_u);
                let res = self.emit_select(a_ge_b, ab, ba);
                self.store_sgpr_u32(sdst, res);
                self.update_scc_nonzero(res);
                true
            }
            // s_lshl{1,2,3,4}_add_u32
            0x2E..=0x31 => {
                let l = self.read_src_u32(s0_u(), literal);
                let r = self.read_src_u32(s1_u(), literal);
                let sh = self.lit_u32(u32::from(op - 0x2D));
                let shifted = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftLeft,
                    left: l,
                    right: sh,
                });
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Add,
                    left: shifted,
                    right: r,
                });
                self.store_sgpr_u32(sdst, res);
                true
            }
            // s_pack_ll_b32_b16 / s_pack_lh_b32_b16 / s_pack_hh_b32_b16
            0x32..=0x34 => {
                let l = self.read_src_u32(s0_u(), literal);
                let r = self.read_src_u32(s1_u(), literal);
                let mask_lo = self.lit_u32(0x0000_FFFF);
                let mask_hi = self.lit_u32(0xFFFF_0000);
                let sh16 = self.lit_u32(16);
                let lo_half = if op == 0x34 {
                    self.emit_expr(Expression::Binary {
                        op: BinaryOperator::ShiftRight,
                        left: l,
                        right: sh16,
                    })
                } else {
                    self.emit_expr(Expression::Binary {
                        op: BinaryOperator::And,
                        left: l,
                        right: mask_lo,
                    })
                };
                let hi_half = if op == 0x32 {
                    self.emit_expr(Expression::Binary {
                        op: BinaryOperator::ShiftLeft,
                        left: r,
                        right: sh16,
                    })
                } else {
                    self.emit_expr(Expression::Binary {
                        op: BinaryOperator::And,
                        left: r,
                        right: mask_hi,
                    })
                };
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::InclusiveOr,
                    left: lo_half,
                    right: hi_half,
                });
                self.store_sgpr_u32(sdst, res);
                true
            }
            _ => false,
        }
    }

    fn translate_smem(
        &mut self,
        inst_idx: usize,
        op: u8,
        sdata: u8,
        sbase: u8,
        soffset: u8,
        byte_offset: i32,
    ) -> bool {
        if let Some(writes) = self.choice_def_writes.get(&inst_idx).cloned() {
            for (choice_id, write) in writes {
                if let Some(&sel_local) = self.choice_sel_locals.get(choice_id) {
                    let val = match write {
                        ChoiceWrite::Const(arm) => self.lit_u32(arm),
                        ChoiceWrite::CopySgpr(reg) => self.load_sgpr_u32(reg),
                    };
                    self.store_local(sel_local, val);
                }
            }
        }
        if self.vsharp_fetch_insts.contains(&inst_idx) {
            return true;
        }
        // s_gl1_inv / s_dcache_inv / s_atc_probe / s_atc_probe_buffer: cache/probe hints (no-op)
        if matches!(op, 0x20 | 0x21 | 0x26 | 0x27) {
            return true;
        }
        let Some(count) = smem_load_dword_count(op) else {
            return false;
        };
        let cbv_key = self
            .indirect_smem_cbv_keys
            .get(&inst_idx)
            .copied()
            .unwrap_or(CbvKey {
                base_sbase: sbase,
                user_sgpr: None,
                table_offset: None,
                dynamic_heap: None,
                cbv_indexed_heap: None,
                lane_indexed_heap: None,
            });
        let Some(&cb_target) = self.cb_globals.get(&cbv_key) else {
            return false;
        };

        let has_dynamic_offset = soffset != 0x7D && soffset <= 105;
        let base_word_dyn = if has_dynamic_offset {
            let s_off = self.load_sgpr_u32(soffset);
            let imm_off = self.lit_u32(byte_offset as u32);
            let byte_sum = self.emit_expr(Expression::Binary {
                op: BinaryOperator::Add,
                left: s_off,
                right: imm_off,
            });
            let two = self.lit_u32(2);
            Some(self.emit_expr(Expression::Binary {
                op: BinaryOperator::ShiftRight,
                left: byte_sum,
                right: two,
            }))
        } else {
            None
        };

        let static_base_word = if byte_offset > 0 {
            (byte_offset as u32) / 4
        } else {
            0
        };

        match cb_target {
            CbvGlobalTarget::Uniform {
                global: cb_global,
                vec4_count: cb_vec4_count,
            } => {
                let total_dwords = cb_vec4_count.max(1).saturating_mul(4);
                let cb_ptr = self.raw_expr(Expression::GlobalVariable(cb_global));
                let data_ptr = self.emit_expr(Expression::AccessIndex {
                    base: cb_ptr,
                    index: 0,
                });
                let mut cached_static_vec: Option<(u32, Handle<Expression>)> = None;

                for k in 0..count {
                    let Some(dst_reg) = checked_sgpr_reg(sdata, k) else {
                        break;
                    };
                    let elem_val = if let Some(base_w) = base_word_dyn {
                        let k_lit = self.lit_u32(u32::from(k));
                        let raw_word = self.emit_expr(Expression::Binary {
                            op: BinaryOperator::Add,
                            left: base_w,
                            right: k_lit,
                        });
                        let total_lit = self.lit_u32(total_dwords);
                        let bounded_word = self.emit_expr(Expression::Binary {
                            op: BinaryOperator::Modulo,
                            left: raw_word,
                            right: total_lit,
                        });
                        let two = self.lit_u32(2);
                        let vec_idx = self.emit_expr(Expression::Binary {
                            op: BinaryOperator::ShiftRight,
                            left: bounded_word,
                            right: two,
                        });
                        let three = self.lit_u32(3);
                        let comp_idx = self.emit_expr(Expression::Binary {
                            op: BinaryOperator::And,
                            left: bounded_word,
                            right: three,
                        });
                        let vec_ptr = self.emit_expr(Expression::Access {
                            base: data_ptr,
                            index: vec_idx,
                        });
                        let vec_val = self.emit_expr(Expression::Load { pointer: vec_ptr });
                        self.emit_expr(Expression::Access {
                            base: vec_val,
                            index: comp_idx,
                        })
                    } else {
                        let word_idx =
                            (static_base_word.saturating_add(u32::from(k))) % total_dwords;
                        let vec_idx = word_idx / 4;
                        let comp_idx = word_idx % 4;
                        let vec_val = match cached_static_vec {
                            Some((cached_idx, handle)) if cached_idx == vec_idx => handle,
                            _ => {
                                let vec_ptr = self.emit_expr(Expression::AccessIndex {
                                    base: data_ptr,
                                    index: vec_idx,
                                });
                                let loaded = self.emit_expr(Expression::Load { pointer: vec_ptr });
                                cached_static_vec = Some((vec_idx, loaded));
                                loaded
                            }
                        };
                        self.emit_expr(Expression::AccessIndex {
                            base: vec_val,
                            index: comp_idx,
                        })
                    };

                    self.store_sgpr_u32(dst_reg, elem_val);
                }
            }
            CbvGlobalTarget::Storage { global: buf_global } => {
                let buf_ptr = self.raw_expr(Expression::GlobalVariable(buf_global));
                let buf_len = self.emit_expr(Expression::ArrayLength(buf_ptr));
                let one = self.lit_u32(1);
                let clamped_len = self.emit_expr(Expression::Math {
                    fun: MathFunction::Max,
                    arg: buf_len,
                    arg1: Some(one),
                    arg2: None,
                    arg3: None,
                });
                let max_idx = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Subtract,
                    left: clamped_len,
                    right: one,
                });

                for k in 0..count {
                    let Some(dst_reg) = checked_sgpr_reg(sdata, k) else {
                        break;
                    };
                    let word_idx = if let Some(base_w) = base_word_dyn {
                        if k == 0 {
                            base_w
                        } else {
                            let k_lit = self.lit_u32(u32::from(k));
                            self.emit_expr(Expression::Binary {
                                op: BinaryOperator::Add,
                                left: base_w,
                                right: k_lit,
                            })
                        }
                    } else {
                        self.lit_u32(static_base_word.saturating_add(u32::from(k)))
                    };
                    let safe_idx = self.emit_expr(Expression::Math {
                        fun: MathFunction::Min,
                        arg: word_idx,
                        arg1: Some(max_idx),
                        arg2: None,
                        arg3: None,
                    });
                    let elem_ptr = self.emit_expr(Expression::Access {
                        base: buf_ptr,
                        index: safe_idx,
                    });
                    let elem_val = self.emit_expr(Expression::Load { pointer: elem_ptr });
                    self.store_sgpr_u32(dst_reg, elem_val);
                }
            }
        }

        true
    }

    // -- VALU: VOP1 / VOPC / VOP2 / VOP3 / VOP3P --

    #[allow(clippy::too_many_arguments)]
    fn translate_vop1(
        &mut self,
        op: u8,
        vdst: u8,
        src0: u16,
        literal: Option<u32>,
        omod: u8,
        clamp: bool,
        abs0: bool,
        neg0: bool,
    ) -> bool {
        match op {
            // v_nop / v_pipeflush / v_clrexcp
            0x00 | 0x1B | 0x41 => true,
            // v_mov_b32
            0x01 => {
                let val = if abs0 || neg0 || omod != 0 || clamp {
                    let f = self.read_src_f32(src0, literal, abs0, neg0);
                    self.apply_float_out_mods(f, omod, clamp)
                } else {
                    self.read_src_f32(src0, literal, false, false)
                };
                self.store_vgpr_f32(vdst, val);
                true
            }
            // v_readfirstlane_b32 sdst, vsrc0
            0x02 => {
                let u = self.read_src_u32(src0, literal);
                let out = if self.subgroups_active() {
                    self.emit_wave_broadcast_first(u)
                } else {
                    u
                };
                self.store_sgpr_u32(vdst & 0x7F, out);
                true
            }
            // v_cvt_f32_i32
            0x05 => {
                let s = self.read_src_i32(src0, literal);
                let f = self.emit_expr(Expression::As {
                    expr: s,
                    kind: ScalarKind::Float,
                    convert: Some(4),
                });
                let out = self.apply_float_out_mods(f, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_cvt_f32_u32
            0x06 => {
                let u = self.read_src_u32(src0, literal);
                let f = self.emit_expr(Expression::As {
                    expr: u,
                    kind: ScalarKind::Float,
                    convert: Some(4),
                });
                let out = self.apply_float_out_mods(f, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_cvt_u32_f32
            0x07 => {
                let f = self.read_src_f32(src0, literal, abs0, neg0);
                let u = self.emit_expr(Expression::As {
                    expr: f,
                    kind: ScalarKind::Uint,
                    convert: Some(4),
                });
                self.store_vgpr_u32(vdst, u);
                true
            }
            // v_cvt_i32_f32
            0x08 => {
                let f = self.read_src_f32(src0, literal, abs0, neg0);
                let i = self.emit_expr(Expression::As {
                    expr: f,
                    kind: ScalarKind::Sint,
                    convert: Some(4),
                });
                self.store_vgpr_i32(vdst, i);
                true
            }
            // v_cvt_f16_f32: convert f32 -> f16 stored in low 16 bits of vdst
            0x0A => {
                let f = self.read_src_f32(src0, literal, abs0, neg0);
                let out = self.apply_float_out_mods(f, omod, clamp);
                self.store_vgpr_f16_lo(vdst, out);
                true
            }
            // v_cvt_f32_f16: convert low 16 bits f16 -> f32
            0x0B => {
                let f = self.read_src_mixed_f16_or_f32(src0, literal, true, false, abs0, neg0);
                let out = self.apply_float_out_mods(f, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_cvt_rpi_i32_f32 / v_cvt_flr_i32_f32
            0x0C | 0x0D => {
                let f = self.read_src_f32(src0, literal, abs0, neg0);
                let shifted = if op == 0x0C {
                    let half = self.lit_f32(0.5);
                    self.emit_expr(Expression::Binary {
                        op: BinaryOperator::Add,
                        left: f,
                        right: half,
                    })
                } else {
                    f
                };
                let floored = self.emit_expr(Expression::Math {
                    fun: MathFunction::Floor,
                    arg: shifted,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let i = self.emit_expr(Expression::As {
                    expr: floored,
                    kind: ScalarKind::Sint,
                    convert: Some(4),
                });
                self.store_vgpr_i32(vdst, i);
                true
            }
            // v_cvt_off_f32_i4: f32(sext4(src0[3:0])) * (1.0 / 16.0)
            0x0E => {
                let raw = self.read_src_i32(src0, literal);
                let sh28 = self.lit_u32(28);
                let shl = self.emit_bin(BinaryOperator::ShiftLeft, raw, sh28);
                let i4 = self.emit_bin(BinaryOperator::ShiftRight, shl, sh28);
                let f = self.emit_expr(Expression::As {
                    expr: i4,
                    kind: ScalarKind::Float,
                    convert: Some(4),
                });
                let scale = self.lit_f32(0.0625);
                let scaled = self.emit_bin(BinaryOperator::Multiply, f, scale);
                let out = self.apply_float_out_mods(scaled, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_cvt_f32_ubyte0..3: extract byte k as f32
            0x11..=0x14 => {
                let u = self.read_src_u32(src0, literal);
                let shift_bits = u32::from(op - 0x11) * 8;
                let shifted = if shift_bits > 0 {
                    let sh = self.lit_u32(shift_bits);
                    self.emit_expr(Expression::Binary {
                        op: BinaryOperator::ShiftRight,
                        left: u,
                        right: sh,
                    })
                } else {
                    u
                };
                let mask = self.lit_u32(0xFF);
                let byte_u = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: shifted,
                    right: mask,
                });
                let f = self.emit_expr(Expression::As {
                    expr: byte_u,
                    kind: ScalarKind::Float,
                    convert: Some(4),
                });
                let out = self.apply_float_out_mods(f, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_fract_f32 / v_trunc_f32 / v_ceil_f32 / v_rndne_f32 / v_floor_f32 /
            // v_exp_f32 / v_log_f32 / v_rsq_f32 / v_sqrt_f32
            0x20 | 0x21 | 0x22 | 0x23 | 0x24 | 0x25 | 0x27 | 0x2E | 0x33 => {
                let f = self.read_src_f32(src0, literal, abs0, neg0);
                let fun = match op {
                    0x20 => MathFunction::Fract,
                    0x21 => MathFunction::Trunc,
                    0x22 => MathFunction::Ceil,
                    0x23 => MathFunction::Round,
                    0x24 => MathFunction::Floor,
                    0x25 => MathFunction::Exp2,
                    0x27 => MathFunction::Log2,
                    0x2E => MathFunction::InverseSqrt,
                    _ => MathFunction::Sqrt,
                };
                let res = self.emit_expr(Expression::Math {
                    fun,
                    arg: f,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_rcp_f32 / v_rcp_iflag_f32
            0x2A | 0x2B => {
                let one = self.lit_f32(1.0);
                let f = self.read_src_f32(src0, literal, abs0, neg0);
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Divide,
                    left: one,
                    right: f,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_sin_f32 / v_cos_f32 (input is in turns: angle = x * 2*pi)
            0x35 | 0x36 => {
                let f = self.read_src_f32(src0, literal, abs0, neg0);
                let tau = self.lit_f32(std::f32::consts::TAU);
                let rad = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Multiply,
                    left: f,
                    right: tau,
                });
                let fun = if op == 0x35 {
                    MathFunction::Sin
                } else {
                    MathFunction::Cos
                };
                let res = self.emit_expr(Expression::Math {
                    fun,
                    arg: rad,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_not_b32
            0x37 => {
                let u = self.read_src_u32(src0, literal);
                let res = self.emit_expr(Expression::Unary {
                    op: UnaryOperator::BitwiseNot,
                    expr: u,
                });
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_bfrev_b32
            0x38 => {
                let u = self.read_src_u32(src0, literal);
                let res = self.emit_expr(Expression::Math {
                    fun: MathFunction::ReverseBits,
                    arg: u,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_ffbh_u32: count leading zeros from MSB; -1 (0xFFFFFFFF) when src0 == 0
            0x39 => {
                let u = self.read_src_u32(src0, literal);
                let clz = self.emit_expr(Expression::Math {
                    fun: MathFunction::CountLeadingZeros,
                    arg: u,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let zero = self.lit_u32(0);
                let is_zero = self.emit_bin(BinaryOperator::Equal, u, zero);
                let neg_one = self.lit_u32(0xFFFF_FFFF);
                let res = self.emit_select(is_zero, neg_one, clz);
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_ffbl_b32: find first 1 bit from LSB; -1 (0xFFFFFFFF) when src0 == 0
            0x3A => {
                let u = self.read_src_u32(src0, literal);
                let ctz = self.emit_expr(Expression::Math {
                    fun: MathFunction::CountTrailingZeros,
                    arg: u,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let zero = self.lit_u32(0);
                let is_zero = self.emit_bin(BinaryOperator::Equal, u, zero);
                let neg_one = self.lit_u32(0xFFFF_FFFF);
                let res = self.emit_select(is_zero, neg_one, ctz);
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_ffbh_i32: count leading bits matching MSB sign bit; -1 when 0 or -1
            0x3B => {
                let u = self.read_src_u32(src0, literal);
                let res = self.emit_ffbh_i32(u);
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_frexp_exp_i32_f32: signed IEEE-754 binary32 exponent (0 for 0/Inf/NaN)
            0x3F => {
                let f = self.read_src_f32(src0, literal, abs0, neg0);
                let exp_i = self.emit_frexp_exp_f32(f);
                self.store_vgpr_i32(vdst, exp_i);
                true
            }
            // v_frexp_mant_f32: IEEE-754 binary32 mantissa in (-1,-0.5] U [0.5,1)
            0x40 => {
                let f = self.read_src_f32(src0, literal, abs0, neg0);
                let mant = self.emit_frexp_mant_f32(f);
                let out = self.apply_float_out_mods(mant, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_cvt_f16_u16: unsigned low 16-bit int -> f16 in vdst[15:0]
            0x50 => {
                let raw = self.read_src_u32(src0, literal);
                let mask16 = self.lit_u32(0xFFFF);
                let u16_val = self.emit_bin(BinaryOperator::And, raw, mask16);
                let f = self.emit_expr(Expression::As {
                    expr: u16_val,
                    kind: ScalarKind::Float,
                    convert: Some(4),
                });
                let out = self.apply_float_out_mods(f, omod, clamp);
                self.store_vgpr_f16_lo(vdst, out);
                true
            }
            // v_cvt_f16_i16: signed low 16-bit int -> f16 in vdst[15:0]
            0x51 => {
                let raw = self.read_src_i32(src0, literal);
                let sh16 = self.lit_u32(16);
                let shl = self.emit_bin(BinaryOperator::ShiftLeft, raw, sh16);
                let i16_val = self.emit_bin(BinaryOperator::ShiftRight, shl, sh16);
                let f = self.emit_expr(Expression::As {
                    expr: i16_val,
                    kind: ScalarKind::Float,
                    convert: Some(4),
                });
                let out = self.apply_float_out_mods(f, omod, clamp);
                self.store_vgpr_f16_lo(vdst, out);
                true
            }
            // v_cvt_u16_f16: f16 in src0[15:0] -> u16 in vdst[15:0]
            0x52 => {
                let f = self.read_src_mixed_f16_or_f32(src0, literal, true, false, abs0, neg0);
                let lo = self.lit_f32(0.0);
                let hi = self.lit_f32(65535.0);
                let clamped = self.emit_expr(Expression::Math {
                    fun: MathFunction::Clamp,
                    arg: f,
                    arg1: Some(lo),
                    arg2: Some(hi),
                    arg3: None,
                });
                let u = self.emit_expr(Expression::As {
                    expr: clamped,
                    kind: ScalarKind::Uint,
                    convert: Some(4),
                });
                self.store_vgpr_u16_lo(vdst, u);
                true
            }
            // v_cvt_i16_f16: f16 in src0[15:0] -> i16 in vdst[15:0]
            0x53 => {
                let f = self.read_src_mixed_f16_or_f32(src0, literal, true, false, abs0, neg0);
                let lo = self.lit_f32(-32768.0);
                let hi = self.lit_f32(32767.0);
                let clamped = self.emit_expr(Expression::Math {
                    fun: MathFunction::Clamp,
                    arg: f,
                    arg1: Some(lo),
                    arg2: Some(hi),
                    arg3: None,
                });
                let i = self.emit_expr(Expression::As {
                    expr: clamped,
                    kind: ScalarKind::Sint,
                    convert: Some(4),
                });
                let u = self.bitcast_i32_to_u32(i);
                self.store_vgpr_u16_lo(vdst, u);
                true
            }
            // v_rcp_f16 (emulated via f32 + pack2x16float, zero `enable f16;`)
            0x54 => {
                let one = self.lit_f32(1.0);
                let f = self.read_src_mixed_f16_or_f32(src0, literal, true, false, abs0, neg0);
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Divide,
                    left: one,
                    right: f,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f16_lo(vdst, out);
                true
            }
            // v_sqrt_f16 / v_rsq_f16 / v_log_f16 / v_exp_f16 / v_floor_f16 / v_ceil_f16 /
            // v_trunc_f16 / v_rndne_f16 / v_fract_f16
            0x55 | 0x56 | 0x57 | 0x58 | 0x5B | 0x5C | 0x5D | 0x5E | 0x5F => {
                let f = self.read_src_mixed_f16_or_f32(src0, literal, true, false, abs0, neg0);
                let fun = match op {
                    0x55 => MathFunction::Sqrt,
                    0x56 => MathFunction::InverseSqrt,
                    0x57 => MathFunction::Log2,
                    0x58 => MathFunction::Exp2,
                    0x5B => MathFunction::Floor,
                    0x5C => MathFunction::Ceil,
                    0x5D => MathFunction::Trunc,
                    0x5E => MathFunction::Round,
                    _ => MathFunction::Fract,
                };
                let res = self.emit_expr(Expression::Math {
                    fun,
                    arg: f,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f16_lo(vdst, out);
                true
            }
            // v_frexp_mant_f16: f16 mantissa in (-1,-0.5] U [0.5,1) stored in vdst[15:0]
            0x59 => {
                let f = self.read_src_mixed_f16_or_f32(src0, literal, true, false, abs0, neg0);
                let mant = self.emit_frexp_mant_f32(f);
                let out = self.apply_float_out_mods(mant, omod, clamp);
                self.store_vgpr_f16_lo(vdst, out);
                true
            }
            // v_frexp_exp_i16_f16: signed f16 exponent stored in vdst[15:0]
            0x5A => {
                let f = self.read_src_mixed_f16_or_f32(src0, literal, true, false, abs0, neg0);
                let exp_i = self.emit_frexp_exp_f32(f);
                let exp_u = self.bitcast_i32_to_u32(exp_i);
                self.store_vgpr_u16_lo(vdst, exp_u);
                true
            }
            // v_sin_f16 / v_cos_f16 (input in turns: angle = x * 2*pi)
            0x60 | 0x61 => {
                let f = self.read_src_mixed_f16_or_f32(src0, literal, true, false, abs0, neg0);
                let tau = self.lit_f32(std::f32::consts::TAU);
                let rad = self.emit_bin(BinaryOperator::Multiply, f, tau);
                let fun = if op == 0x60 {
                    MathFunction::Sin
                } else {
                    MathFunction::Cos
                };
                let res = self.emit_expr(Expression::Math {
                    fun,
                    arg: rad,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f16_lo(vdst, out);
                true
            }
            // v_sat_pk_u8_i16: saturate 2 packed i16 lanes to [0, 255] and pack into vdst[15:0]
            0x62 => {
                let raw_i = self.read_src_i32(src0, literal);
                let sh16 = self.lit_u32(16);
                let lo_shl = self.emit_bin(BinaryOperator::ShiftLeft, raw_i, sh16);
                let lo_i = self.emit_bin(BinaryOperator::ShiftRight, lo_shl, sh16);
                let hi_i = self.emit_bin(BinaryOperator::ShiftRight, raw_i, sh16);
                let c0 = self.lit_i32(0);
                let c255 = self.lit_i32(255);
                let lo_cl = self.emit_expr(Expression::Math {
                    fun: MathFunction::Clamp,
                    arg: lo_i,
                    arg1: Some(c0),
                    arg2: Some(c255),
                    arg3: None,
                });
                let hi_cl = self.emit_expr(Expression::Math {
                    fun: MathFunction::Clamp,
                    arg: hi_i,
                    arg1: Some(c0),
                    arg2: Some(c255),
                    arg3: None,
                });
                let lo_u = self.bitcast_i32_to_u32(lo_cl);
                let hi_u = self.bitcast_i32_to_u32(hi_cl);
                let sh8 = self.lit_u32(8);
                let hi_sh = self.emit_bin(BinaryOperator::ShiftLeft, hi_u, sh8);
                let packed16 = self.emit_bin(BinaryOperator::InclusiveOr, lo_u, hi_sh);
                self.store_vgpr_u16_lo(vdst, packed16);
                true
            }
            // v_cvt_norm_i16_f16: round(clamp(f16, -1.0, 1.0) * 32767.0) -> i16 in vdst[15:0]
            0x63 => {
                let f = self.read_src_mixed_f16_or_f32(src0, literal, true, false, abs0, neg0);
                let lo = self.lit_f32(-1.0);
                let hi = self.lit_f32(1.0);
                let clamped = self.emit_expr(Expression::Math {
                    fun: MathFunction::Clamp,
                    arg: f,
                    arg1: Some(lo),
                    arg2: Some(hi),
                    arg3: None,
                });
                let scale = self.lit_f32(32767.0);
                let scaled = self.emit_bin(BinaryOperator::Multiply, clamped, scale);
                let rounded = self.emit_expr(Expression::Math {
                    fun: MathFunction::Round,
                    arg: scaled,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let i = self.emit_expr(Expression::As {
                    expr: rounded,
                    kind: ScalarKind::Sint,
                    convert: Some(4),
                });
                let u = self.bitcast_i32_to_u32(i);
                self.store_vgpr_u16_lo(vdst, u);
                true
            }
            // v_cvt_norm_u16_f16: round(clamp(f16, 0.0, 1.0) * 65535.0) -> u16 in vdst[15:0]
            0x64 => {
                let f = self.read_src_mixed_f16_or_f32(src0, literal, true, false, abs0, neg0);
                let lo = self.lit_f32(0.0);
                let hi = self.lit_f32(1.0);
                let clamped = self.emit_expr(Expression::Math {
                    fun: MathFunction::Clamp,
                    arg: f,
                    arg1: Some(lo),
                    arg2: Some(hi),
                    arg3: None,
                });
                let scale = self.lit_f32(65535.0);
                let scaled = self.emit_bin(BinaryOperator::Multiply, clamped, scale);
                let rounded = self.emit_expr(Expression::Math {
                    fun: MathFunction::Round,
                    arg: scaled,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let u = self.emit_expr(Expression::As {
                    expr: rounded,
                    kind: ScalarKind::Uint,
                    convert: Some(4),
                });
                self.store_vgpr_u16_lo(vdst, u);
                true
            }
            // v_swap_b32: atomically swap v[vdst] and v[vsrc0]
            0x65 => {
                if (256..=511).contains(&src0) {
                    let vsrc = (src0 - 256) as u8;
                    if vsrc != vdst {
                        let old_dst = self.load_vgpr_f32(vdst);
                        let old_src = self.load_vgpr_f32(vsrc);
                        self.store_vgpr_f32(vdst, old_src);
                        self.store_vgpr_f32(vsrc, old_dst);
                    }
                } else {
                    let val = self.read_src_f32(src0, literal, false, false);
                    self.store_vgpr_f32(vdst, val);
                }
                true
            }
            _ => false,
        }
    }

    /// Store the low 16 bits of `val_u32` into `v[reg][15:0]`, preserving `v[reg][31:16]`.
    fn store_vgpr_u16_lo(&mut self, reg: u8, val_u32: Handle<Expression>) {
        let mask_lo = self.lit_u32(0x0000_FFFF);
        let mask_hi = self.lit_u32(0xFFFF_0000);
        let new_lo = self.emit_bin(BinaryOperator::And, val_u32, mask_lo);
        let old_f = self.load_vgpr_f32(reg);
        let old_u = self.bitcast_f32_to_u32(old_f);
        let preserved_hi = self.emit_bin(BinaryOperator::And, old_u, mask_hi);
        let combined = self.emit_bin(BinaryOperator::InclusiveOr, preserved_hi, new_lo);
        self.store_vgpr_u32(reg, combined);
    }

    /// Store the low 16 bits of `val_u32` into `v[reg][31:16]`, preserving `v[reg][15:0]`.
    fn store_vgpr_u16_hi(&mut self, reg: u8, val_u32: Handle<Expression>) {
        let mask_lo = self.lit_u32(0x0000_FFFF);
        let sh16 = self.lit_u32(16);
        let new_hi = self.emit_bin(BinaryOperator::ShiftLeft, val_u32, sh16);
        let old_f = self.load_vgpr_f32(reg);
        let old_u = self.bitcast_f32_to_u32(old_f);
        let preserved_lo = self.emit_bin(BinaryOperator::And, old_u, mask_lo);
        let combined = self.emit_bin(BinaryOperator::InclusiveOr, preserved_lo, new_hi);
        self.store_vgpr_u32(reg, combined);
    }

    /// Count leading bits matching the MSB sign bit of a 32-bit word (`s_flbit_i32` / `v_ffbh_i32`).
    /// Returns `0xFFFF_FFFFu` (`-1`) when all 32 bits match (`0` or `-1`).
    fn emit_ffbh_i32(&mut self, u: Handle<Expression>) -> Handle<Expression> {
        let i = self.bitcast_u32_to_i32(u);
        let c31 = self.lit_u32(31);
        let sign_i = self.emit_bin(BinaryOperator::ShiftRight, i, c31);
        let sign_mask = self.bitcast_i32_to_u32(sign_i);
        let norm = self.emit_bin(BinaryOperator::ExclusiveOr, u, sign_mask);
        let clz = self.emit_expr(Expression::Math {
            fun: MathFunction::CountLeadingZeros,
            arg: norm,
            arg1: None,
            arg2: None,
            arg3: None,
        });
        let zero = self.lit_u32(0);
        let is_zero = self.emit_bin(BinaryOperator::Equal, norm, zero);
        let neg_one = self.lit_u32(0xFFFF_FFFF);
        self.emit_select(is_zero, neg_one, clz)
    }

    /// Signed 32-bit bitfield extract (`s_bfe_i32` / `v_bfe_i32`) with all WGSL shifts `< 32`.
    fn emit_bfe_i32(
        &mut self,
        src0_i: Handle<Expression>,
        offset: Handle<Expression>,
        width: Handle<Expression>,
    ) -> Handle<Expression> {
        let c32 = self.lit_u32(32);
        let mask31 = self.lit_u32(31);
        let zero_u = self.lit_u32(0);
        let zero_i = self.lit_i32(0);
        let sum = self.emit_bin(BinaryOperator::Add, offset, width);
        let is_wide = self.emit_bin(BinaryOperator::GreaterEqual, sum, c32);
        let is_zero = self.emit_bin(BinaryOperator::Equal, width, zero_u);
        let wide_val = self.emit_bin(BinaryOperator::ShiftRight, src0_i, offset);
        let lsh_raw = self.emit_bin(BinaryOperator::Subtract, c32, sum);
        let lsh = self.emit_bin(BinaryOperator::And, lsh_raw, mask31);
        let rsh_raw = self.emit_bin(BinaryOperator::Subtract, c32, width);
        let rsh = self.emit_bin(BinaryOperator::And, rsh_raw, mask31);
        let shl = self.emit_bin(BinaryOperator::ShiftLeft, src0_i, lsh);
        let narrow_val = self.emit_bin(BinaryOperator::ShiftRight, shl, rsh);
        let non_zero = self.emit_select(is_wide, wide_val, narrow_val);
        self.emit_select(is_zero, zero_i, non_zero)
    }

    /// IEEE-754 binary32 `frexp` exponent as `i32` (`0` for `0`, `Inf`, `NaN`; handles subnormals).
    fn emit_frexp_exp_f32(&mut self, f: Handle<Expression>) -> Handle<Expression> {
        let bits = self.bitcast_f32_to_u32(f);
        let s23 = self.lit_u32(23);
        let exp_mask = self.lit_u32(0xFF);
        let mant_mask = self.lit_u32(0x007F_FFFF);
        let zero_u = self.lit_u32(0);
        let zero_i = self.lit_i32(0);
        let exp_sh = self.emit_bin(BinaryOperator::ShiftRight, bits, s23);
        let exp = self.emit_bin(BinaryOperator::And, exp_sh, exp_mask);
        let mant = self.emit_bin(BinaryOperator::And, bits, mant_mask);
        let exp_is_zero = self.emit_bin(BinaryOperator::Equal, exp, zero_u);
        let exp_is_max = self.emit_bin(BinaryOperator::Equal, exp, exp_mask);
        let mant_is_zero = self.emit_bin(BinaryOperator::Equal, mant, zero_u);
        let mant_nonzero = self.emit_bin(BinaryOperator::NotEqual, mant, zero_u);
        let is_zero_val = self.emit_bin(BinaryOperator::LogicalAnd, exp_is_zero, mant_is_zero);
        let is_special = self.emit_bin(BinaryOperator::LogicalOr, exp_is_max, is_zero_val);
        let is_subnormal = self.emit_bin(BinaryOperator::LogicalAnd, exp_is_zero, mant_nonzero);

        let exp_i = self.bitcast_u32_to_i32(exp);
        let bias = self.lit_i32(126);
        let norm_exp = self.emit_bin(BinaryOperator::Subtract, exp_i, bias);

        let clz = self.emit_expr(Expression::Math {
            fun: MathFunction::CountLeadingZeros,
            arg: mant,
            arg1: None,
            arg2: None,
            arg3: None,
        });
        let clz_i = self.bitcast_u32_to_i32(clz);
        let sub_base = self.lit_i32(-117);
        let sub_exp = self.emit_bin(BinaryOperator::Subtract, sub_base, clz_i);

        let finite_exp = self.emit_select(is_subnormal, sub_exp, norm_exp);
        self.emit_select(is_special, zero_i, finite_exp)
    }

    /// IEEE-754 binary32 `frexp` mantissa as `f32` in `(-1, -0.5] U [0.5, 1)` (preserves `0/Inf/NaN`).
    fn emit_frexp_mant_f32(&mut self, f: Handle<Expression>) -> Handle<Expression> {
        let bits = self.bitcast_f32_to_u32(f);
        let s23 = self.lit_u32(23);
        let exp_mask = self.lit_u32(0xFF);
        let mant_mask = self.lit_u32(0x007F_FFFF);
        let sign_mask = self.lit_u32(0x8000_0000);
        let sign_mant_mask = self.lit_u32(0x807F_FFFF);
        let half_exp_bits = self.lit_u32(0x3F00_0000);
        let zero_u = self.lit_u32(0);
        let exp_sh = self.emit_bin(BinaryOperator::ShiftRight, bits, s23);
        let exp = self.emit_bin(BinaryOperator::And, exp_sh, exp_mask);
        let mant = self.emit_bin(BinaryOperator::And, bits, mant_mask);
        let exp_is_zero = self.emit_bin(BinaryOperator::Equal, exp, zero_u);
        let exp_is_max = self.emit_bin(BinaryOperator::Equal, exp, exp_mask);
        let mant_is_zero = self.emit_bin(BinaryOperator::Equal, mant, zero_u);
        let mant_nonzero = self.emit_bin(BinaryOperator::NotEqual, mant, zero_u);
        let is_zero_val = self.emit_bin(BinaryOperator::LogicalAnd, exp_is_zero, mant_is_zero);
        let is_special = self.emit_bin(BinaryOperator::LogicalOr, exp_is_max, is_zero_val);
        let is_subnormal = self.emit_bin(BinaryOperator::LogicalAnd, exp_is_zero, mant_nonzero);

        let norm_kept = self.emit_bin(BinaryOperator::And, bits, sign_mant_mask);
        let norm_bits = self.emit_bin(BinaryOperator::InclusiveOr, norm_kept, half_exp_bits);

        let clz = self.emit_expr(Expression::Math {
            fun: MathFunction::CountLeadingZeros,
            arg: mant,
            arg1: None,
            arg2: None,
            arg3: None,
        });
        let c8 = self.lit_u32(8);
        let mask31 = self.lit_u32(31);
        let sub_sh_raw = self.emit_bin(BinaryOperator::Subtract, clz, c8);
        let sub_sh = self.emit_bin(BinaryOperator::And, sub_sh_raw, mask31);
        let sub_m_sh = self.emit_bin(BinaryOperator::ShiftLeft, mant, sub_sh);
        let sub_m = self.emit_bin(BinaryOperator::And, sub_m_sh, mant_mask);
        let sign_bit = self.emit_bin(BinaryOperator::And, bits, sign_mask);
        let sub_s = self.emit_bin(BinaryOperator::InclusiveOr, sign_bit, half_exp_bits);
        let sub_bits = self.emit_bin(BinaryOperator::InclusiveOr, sub_s, sub_m);

        let finite_bits = self.emit_select(is_subnormal, sub_bits, norm_bits);
        let res_bits = self.emit_select(is_special, bits, finite_bits);
        self.bitcast_u32_to_f32(res_bits)
    }

    /// Evaluate any of the 16 IEEE-754 floating-point comparison condition codes (NaN-aware):
    ///   0=f, 1=lt, 2=eq, 3=le, 4=gt, 5=lg, 6=ge, 7=o,
    ///   8=u, 9=nge, 10=nlg, 11=ngt, 12=nle, 13=neq, 14=nlt, 15=tru
    fn emit_float_cmp(
        &mut self,
        cc: u8,
        l: Handle<Expression>,
        r: Handle<Expression>,
    ) -> Handle<Expression> {
        match cc {
            0 => self.lit_bool(false),
            1 => self.emit_bin(BinaryOperator::Less, l, r),
            2 => self.emit_bin(BinaryOperator::Equal, l, r),
            3 => self.emit_bin(BinaryOperator::LessEqual, l, r),
            4 => self.emit_bin(BinaryOperator::Greater, l, r),
            5 => {
                let lt = self.emit_bin(BinaryOperator::Less, l, r);
                let gt = self.emit_bin(BinaryOperator::Greater, l, r);
                self.emit_bin(BinaryOperator::LogicalOr, lt, gt)
            }
            6 => self.emit_bin(BinaryOperator::GreaterEqual, l, r),
            7 => {
                let lo = self.emit_bin(BinaryOperator::Equal, l, l);
                let ro = self.emit_bin(BinaryOperator::Equal, r, r);
                self.emit_bin(BinaryOperator::LogicalAnd, lo, ro)
            }
            8 => {
                let lu = self.emit_bin(BinaryOperator::NotEqual, l, l);
                let ru = self.emit_bin(BinaryOperator::NotEqual, r, r);
                self.emit_bin(BinaryOperator::LogicalOr, lu, ru)
            }
            9 => {
                // nge: !(l >= r) — true when l < r or either operand is NaN
                let ge = self.emit_bin(BinaryOperator::GreaterEqual, l, r);
                self.emit_expr(Expression::Unary {
                    op: UnaryOperator::LogicalNot,
                    expr: ge,
                })
            }
            10 => {
                // nlg: !(l < r || l > r) — true when l == r or either operand is NaN
                let lt = self.emit_bin(BinaryOperator::Less, l, r);
                let gt = self.emit_bin(BinaryOperator::Greater, l, r);
                let lg = self.emit_bin(BinaryOperator::LogicalOr, lt, gt);
                self.emit_expr(Expression::Unary {
                    op: UnaryOperator::LogicalNot,
                    expr: lg,
                })
            }
            11 => {
                // ngt: !(l > r) — true when l <= r or either operand is NaN
                let gt = self.emit_bin(BinaryOperator::Greater, l, r);
                self.emit_expr(Expression::Unary {
                    op: UnaryOperator::LogicalNot,
                    expr: gt,
                })
            }
            12 => {
                // nle: !(l <= r) — true when l > r or either operand is NaN
                let le = self.emit_bin(BinaryOperator::LessEqual, l, r);
                self.emit_expr(Expression::Unary {
                    op: UnaryOperator::LogicalNot,
                    expr: le,
                })
            }
            13 => self.emit_bin(BinaryOperator::NotEqual, l, r),
            14 => {
                // nlt: !(l < r) — true when l >= r or either operand is NaN
                let lt = self.emit_bin(BinaryOperator::Less, l, r);
                self.emit_expr(Expression::Unary {
                    op: UnaryOperator::LogicalNot,
                    expr: lt,
                })
            }
            _ => self.lit_bool(true),
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn translate_vopc(
        &mut self,
        op: u8,
        src0: u16,
        src1: u16,
        literal: Option<u32>,
        abs: u8,
        neg: u8,
        op_sel: u8,
        sdst_override: Option<u8>,
    ) -> bool {
        let cmp = match op {
            // f32 comparisons: 0x00..=0x0F (v_cmp_*_f32) and 0x10..=0x1F (v_cmpx_*_f32)
            0x00..=0x1F => {
                let cc = op & 0xF;
                let l = self.read_src_f32(src0, literal, (abs & 1) != 0, (neg & 1) != 0);
                let r = self.read_src_f32(src1, literal, (abs & 2) != 0, (neg & 2) != 0);
                self.emit_float_cmp(cc, l, r)
            }
            // f16 comparisons: GFX10.3 (0xC8..=0xCF, 0xD8..=0xDF, 0xE8..=0xEF, 0xF8..=0xFF)
            // plus legacy/compat 0x40..=0x5F
            0x40..=0x5F | 0xC8..=0xCF | 0xD8..=0xDF | 0xE8..=0xEF | 0xF8..=0xFF => {
                let cc = if op <= 0x5F {
                    op & 0xF
                } else if op >= 0xE8 {
                    8 + (op & 0x7)
                } else {
                    op & 0x7
                };
                let l = self.read_src_mixed_f16_or_f32(
                    src0,
                    literal,
                    true,
                    (op_sel & 1) != 0,
                    (abs & 1) != 0,
                    (neg & 1) != 0,
                );
                let r = self.read_src_mixed_f16_or_f32(
                    src1,
                    literal,
                    true,
                    (op_sel & 2) != 0,
                    (abs & 2) != 0,
                    (neg & 2) != 0,
                );
                self.emit_float_cmp(cc, l, r)
            }
            // i16 comparisons: GFX10.3 (0x89..=0x8E, 0x99..=0x9E) and compat (0x60..=0x67, 0x70..=0x77)
            0x60..=0x67 | 0x70..=0x77 | 0x89..=0x8E | 0x99..=0x9E => {
                let cc = op & 0x7;
                let s16 = self.lit_u32(16);
                let l_raw = self.read_src_i32(src0, literal);
                let l = if (op_sel & 1) != 0 {
                    self.emit_bin(BinaryOperator::ShiftRight, l_raw, s16)
                } else {
                    let shl = self.emit_bin(BinaryOperator::ShiftLeft, l_raw, s16);
                    self.emit_bin(BinaryOperator::ShiftRight, shl, s16)
                };
                let r_raw = self.read_src_i32(src1, literal);
                let r = if (op_sel & 2) != 0 {
                    self.emit_bin(BinaryOperator::ShiftRight, r_raw, s16)
                } else {
                    let shl = self.emit_bin(BinaryOperator::ShiftLeft, r_raw, s16);
                    self.emit_bin(BinaryOperator::ShiftRight, shl, s16)
                };
                self.emit_int_cmp(cc, l, r)
            }
            // u16 comparisons: GFX10.3 (0xA9..=0xAE, 0xB9..=0xBE) and compat (0x68..=0x6F, 0x78..=0x7F)
            0x68..=0x6F | 0x78..=0x7F | 0xA9..=0xAE | 0xB9..=0xBE => {
                let cc = op & 0x7;
                let s16 = self.lit_u32(16);
                let mask16 = self.lit_u32(0xFFFF);
                let l_raw = self.read_src_u32(src0, literal);
                let l = if (op_sel & 1) != 0 {
                    self.emit_bin(BinaryOperator::ShiftRight, l_raw, s16)
                } else {
                    self.emit_bin(BinaryOperator::And, l_raw, mask16)
                };
                let r_raw = self.read_src_u32(src1, literal);
                let r = if (op_sel & 2) != 0 {
                    self.emit_bin(BinaryOperator::ShiftRight, r_raw, s16)
                } else {
                    self.emit_bin(BinaryOperator::And, r_raw, mask16)
                };
                self.emit_int_cmp(cc, l, r)
            }
            // i32 comparisons: 0x80..=0x87 / 0x90..=0x97
            0x80..=0x87 | 0x90..=0x97 => {
                let cc = op & 0x7;
                let l = self.read_src_i32(src0, literal);
                let r = self.read_src_i32(src1, literal);
                self.emit_int_cmp(cc, l, r)
            }
            // u32 comparisons: 0xC0..=0xC7 / 0xD0..=0xD7
            0xC0..=0xC7 | 0xD0..=0xD7 => {
                let cc = op & 0x7;
                let l = self.read_src_u32(src0, literal);
                let r = self.read_src_u32(src1, literal);
                self.emit_int_cmp(cc, l, r)
            }
            // v_cmp_class_f32 / v_cmpx_class_f32: IEEE-754 class of src0 tested against the
            // src1 class mask (bits 0..9). Source modifiers act on the raw sign bit.
            0x88 | 0x98 => {
                let mut bits = self.read_src_u32(src0, literal);
                if (abs & 1) != 0 {
                    let clear_sign = self.lit_u32(0x7FFF_FFFF);
                    bits = self.emit_bin(BinaryOperator::And, bits, clear_sign);
                }
                if (neg & 1) != 0 {
                    let sign = self.lit_u32(0x8000_0000);
                    bits = self.emit_bin(BinaryOperator::ExclusiveOr, bits, sign);
                }
                let mask = self.read_src_u32(src1, literal);
                self.emit_f32_class_test(bits, mask)
            }
            // v_cmp_class_f16 / v_cmpx_class_f16: IEEE-754 binary16 class of src0 (respecting
            // op_sel[0], abs[0], neg[0]) tested against the 10-bit class mask in src1.
            0x8F | 0x9F => {
                let mut bits16 = if let Some(hbits) = Self::inline_f16_bits(src0) {
                    self.lit_u32(if (op_sel & 1) != 0 { 0 } else { hbits })
                } else {
                    let raw = self.read_src_u32(src0, literal);
                    if (op_sel & 1) != 0 {
                        let s16 = self.lit_u32(16);
                        self.emit_bin(BinaryOperator::ShiftRight, raw, s16)
                    } else {
                        let mask16 = self.lit_u32(0xFFFF);
                        self.emit_bin(BinaryOperator::And, raw, mask16)
                    }
                };
                if (abs & 1) != 0 {
                    let clear_sign = self.lit_u32(0x7FFF);
                    bits16 = self.emit_bin(BinaryOperator::And, bits16, clear_sign);
                }
                if (neg & 1) != 0 {
                    let sign = self.lit_u32(0x8000);
                    bits16 = self.emit_bin(BinaryOperator::ExclusiveOr, bits16, sign);
                }
                let mask = self.read_src_u32(src1, literal);
                self.emit_f16_class_test(bits16, mask)
            }
            _ => return false,
        };

        let is_cmpx = (op & 0x10) != 0;
        if is_cmpx {
            // GFX10.3 v_cmpx_* updates EXEC (single-lane model: exec_mask &= cmp_bit).
            if let Some(local) = self.exec_local {
                let old_exec = self.load_local(local);
                let cmp_bit = self.bool_to_u32(cmp);
                let new_exec = self.emit_bin(BinaryOperator::And, old_exec, cmp_bit);
                self.store_local(local, new_exec);
            }
            if let Some(sd) = sdst_override
                && (sd & 0x7F) <= 106
            {
                self.store_lane_mask(sd, cmp);
            }
        } else {
            match sdst_override {
                Some(sd) => self.store_lane_mask(sd, cmp),
                None => self.store_vcc(cmp),
            }
        }
        true
    }

    fn emit_int_cmp(
        &mut self,
        cc: u8,
        left: Handle<Expression>,
        right: Handle<Expression>,
    ) -> Handle<Expression> {
        match cc {
            0 => self.lit_bool(false),
            1 => self.emit_expr(Expression::Binary {
                op: BinaryOperator::Less,
                left,
                right,
            }),
            2 => self.emit_expr(Expression::Binary {
                op: BinaryOperator::Equal,
                left,
                right,
            }),
            3 => self.emit_expr(Expression::Binary {
                op: BinaryOperator::LessEqual,
                left,
                right,
            }),
            4 => self.emit_expr(Expression::Binary {
                op: BinaryOperator::Greater,
                left,
                right,
            }),
            5 => self.emit_expr(Expression::Binary {
                op: BinaryOperator::NotEqual,
                left,
                right,
            }),
            6 => self.emit_expr(Expression::Binary {
                op: BinaryOperator::GreaterEqual,
                left,
                right,
            }),
            _ => self.lit_bool(true),
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn translate_vop2(
        &mut self,
        op: u8,
        vdst: u8,
        src0: u16,
        src1: u16,
        cond_src: Option<u16>,
        literal: Option<u32>,
        omod: u8,
        clamp: bool,
        abs: u8,
        neg: u8,
        carry_sdst: Option<u8>,
    ) -> bool {
        let abs0 = (abs & 1) != 0;
        let neg0 = (neg & 1) != 0;
        let abs1 = (abs & 2) != 0;
        let neg1 = (neg & 2) != 0;

        match op {
            // v_cndmask_b32 vdst, src0, src1, cond (cond ? src1 : src0)
            // GFX10.3 VOP2 opcode 0x00 and 0x01 (and VOP3 0x100 / 0x101).
            0x00 | 0x01 => {
                let reject = self.read_src_f32(src0, literal, abs0, neg0);
                let accept = self.read_src_f32(src1, literal, abs1, neg1);
                let cond = match cond_src {
                    Some(106) | None => self.load_vcc(),
                    Some(csrc) if self.subgroups_active() => self.read_lane_mask_bit(csrc, literal),
                    Some(csrc) => {
                        let cu = self.read_src_u32(csrc, literal);
                        let zero = self.lit_u32(0);
                        self.emit_expr(Expression::Binary {
                            op: BinaryOperator::NotEqual,
                            left: cu,
                            right: zero,
                        })
                    }
                };
                let res = self.emit_expr(Expression::Select {
                    condition: cond,
                    accept,
                    reject,
                });
                self.store_vgpr_f32(vdst, res);
                true
            }
            // v_dot2c_f32_f16: vdst = dot(unpack(src0), unpack(src1)) + vdst
            0x02 => {
                let a = self.read_src_pk_f16(src0, literal, false, true, neg0, neg0);
                let b = self.read_src_pk_f16(src1, literal, false, true, neg1, neg1);
                let acc = self.load_vgpr_f32(vdst);
                let d = self.emit_expr(Expression::Math {
                    fun: MathFunction::Dot,
                    arg: a,
                    arg1: Some(b),
                    arg2: None,
                    arg3: None,
                });
                let sum = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Add,
                    left: d,
                    right: acc,
                });
                let out = self.apply_float_out_mods(sum, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_add_f32
            0x03 => {
                let l = self.read_src_f32(src0, literal, abs0, neg0);
                let r = self.read_src_f32(src1, literal, abs1, neg1);
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Add,
                    left: l,
                    right: r,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_sub_f32
            0x04 => {
                let l = self.read_src_f32(src0, literal, abs0, neg0);
                let r = self.read_src_f32(src1, literal, abs1, neg1);
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Subtract,
                    left: l,
                    right: r,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_subrev_f32: src1 - src0
            0x05 => {
                let l = self.read_src_f32(src0, literal, abs0, neg0);
                let r = self.read_src_f32(src1, literal, abs1, neg1);
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Subtract,
                    left: r,
                    right: l,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_fmac_legacy_f32 / v_fmac_f32: vdst = fma(src0, src1, vdst)
            0x06 | 0x2B => {
                let a = self.read_src_f32(src0, literal, abs0, neg0);
                let b = self.read_src_f32(src1, literal, abs1, neg1);
                let c = self.load_vgpr_f32(vdst);
                let res = self.emit_expr(Expression::Math {
                    fun: MathFunction::Fma,
                    arg: a,
                    arg1: Some(b),
                    arg2: Some(c),
                    arg3: None,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_mul_legacy_f32 / v_mul_f32
            0x07 | 0x08 => {
                let l = self.read_src_f32(src0, literal, abs0, neg0);
                let r = self.read_src_f32(src1, literal, abs1, neg1);
                let prod = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Multiply,
                    left: l,
                    right: r,
                });
                let res = if op == 0x07 {
                    let zero = self.lit_f32(0.0);
                    let l_zero = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::Equal,
                        left: l,
                        right: zero,
                    });
                    let r_zero = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::Equal,
                        left: r,
                        right: zero,
                    });
                    let either_zero = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::LogicalOr,
                        left: l_zero,
                        right: r_zero,
                    });
                    self.emit_expr(Expression::Select {
                        condition: either_zero,
                        accept: zero,
                        reject: prod,
                    })
                } else {
                    prod
                };
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_mul_i32_i24: sign-extend low 24 bits and multiply
            0x09 => {
                let l_raw = self.read_src_i32(src0, literal);
                let r_raw = self.read_src_i32(src1, literal);
                let sh8 = self.lit_u32(8);
                let l_sh = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftLeft,
                    left: l_raw,
                    right: sh8,
                });
                let l = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftRight,
                    left: l_sh,
                    right: sh8,
                });
                let r_sh = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftLeft,
                    left: r_raw,
                    right: sh8,
                });
                let r = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftRight,
                    left: r_sh,
                    right: sh8,
                });
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Multiply,
                    left: l,
                    right: r,
                });
                self.store_vgpr_i32(vdst, res);
                true
            }
            // v_mul_u32_u24: mask low 24 bits and multiply
            0x0B => {
                let l_raw = self.read_src_u32(src0, literal);
                let r_raw = self.read_src_u32(src1, literal);
                let mask24 = self.lit_u32(0x00FF_FFFF);
                let l = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: l_raw,
                    right: mask24,
                });
                let r = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: r_raw,
                    right: mask24,
                });
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Multiply,
                    left: l,
                    right: r,
                });
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_dot4c_i32_i8: vdst = sum_{k=0..4}(sext8(src0.b[k]) * sext8(src1.b[k])) + vdst
            0x0D => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let acc_f = self.load_vgpr_f32(vdst);
                let acc = self.bitcast_f32_to_i32(acc_f);
                let res = self.emit_dot4_i32_i8(a, b, acc, clamp);
                self.store_vgpr_i32(vdst, res);
                true
            }
            // v_dot8c_i32_i4: vdst = sum_{k=0..8}(sext4(src0.n[k]) * sext4(src1.n[k])) + vdst
            0x0E => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let acc_f = self.load_vgpr_f32(vdst);
                let acc = self.bitcast_f32_to_i32(acc_f);
                let res = self.emit_dot8_i32_i4(a, b, acc, clamp);
                self.store_vgpr_i32(vdst, res);
                true
            }
            // v_min_f32 / v_max_f32
            0x0F | 0x10 => {
                let l = self.read_src_f32(src0, literal, abs0, neg0);
                let r = self.read_src_f32(src1, literal, abs1, neg1);
                let fun = if op == 0x0F {
                    MathFunction::Min
                } else {
                    MathFunction::Max
                };
                let res = self.emit_expr(Expression::Math {
                    fun,
                    arg: l,
                    arg1: Some(r),
                    arg2: None,
                    arg3: None,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_min_i32 / v_max_i32
            0x11 | 0x12 => {
                let l = self.read_src_i32(src0, literal);
                let r = self.read_src_i32(src1, literal);
                let fun = if op == 0x11 {
                    MathFunction::Min
                } else {
                    MathFunction::Max
                };
                let res = self.emit_expr(Expression::Math {
                    fun,
                    arg: l,
                    arg1: Some(r),
                    arg2: None,
                    arg3: None,
                });
                self.store_vgpr_i32(vdst, res);
                true
            }
            // v_min_u32 / v_max_u32
            0x13 | 0x14 => {
                let l = self.read_src_u32(src0, literal);
                let r = self.read_src_u32(src1, literal);
                let fun = if op == 0x13 {
                    MathFunction::Min
                } else {
                    MathFunction::Max
                };
                let res = self.emit_expr(Expression::Math {
                    fun,
                    arg: l,
                    arg1: Some(r),
                    arg2: None,
                    arg3: None,
                });
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_mul_hi_i32_i24 / v_mul_hi_u32_u24: bits [47:32] of the 24x24-bit product
            0x0A | 0x0C => {
                let l_raw = self.read_src_u32(src0, literal);
                let r_raw = self.read_src_u32(src1, literal);
                let res = if op == 0x0C {
                    let mask24 = self.lit_u32(0x00FF_FFFF);
                    let l = self.emit_bin(BinaryOperator::And, l_raw, mask24);
                    let r = self.emit_bin(BinaryOperator::And, r_raw, mask24);
                    self.emit_mul_hi_u32(l, r)
                } else {
                    let sh8 = self.lit_u32(8);
                    let l_i = self.bitcast_u32_to_i32(l_raw);
                    let r_i = self.bitcast_u32_to_i32(r_raw);
                    let l_shl = self.emit_bin(BinaryOperator::ShiftLeft, l_i, sh8);
                    let r_shl = self.emit_bin(BinaryOperator::ShiftLeft, r_i, sh8);
                    let l_sext = self.emit_bin(BinaryOperator::ShiftRight, l_shl, sh8);
                    let r_sext = self.emit_bin(BinaryOperator::ShiftRight, r_shl, sh8);
                    let l = self.bitcast_i32_to_u32(l_sext);
                    let r = self.bitcast_i32_to_u32(r_sext);
                    self.emit_mul_hi_i32(l, r)
                };
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_lshrrev_b32 / v_lshlrev_b32: src1 >>/<< (src0 & 31)
            0x16 | 0x1A => {
                let sh_raw = self.read_src_u32(src0, literal);
                let val = self.read_src_u32(src1, literal);
                let mask = self.lit_u32(31);
                let sh = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: sh_raw,
                    right: mask,
                });
                let bin = if op == 0x16 {
                    BinaryOperator::ShiftRight
                } else {
                    BinaryOperator::ShiftLeft
                };
                let res = self.emit_expr(Expression::Binary {
                    op: bin,
                    left: val,
                    right: sh,
                });
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_ashrrev_i32: i32(src1) >> (src0 & 31)
            0x18 => {
                let sh_raw = self.read_src_u32(src0, literal);
                let val = self.read_src_i32(src1, literal);
                let mask = self.lit_u32(31);
                let sh = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: sh_raw,
                    right: mask,
                });
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftRight,
                    left: val,
                    right: sh,
                });
                self.store_vgpr_i32(vdst, res);
                true
            }
            // v_and_b32 / v_or_b32 / v_xor_b32
            0x1B..=0x1D => {
                let l = self.read_src_u32(src0, literal);
                let r = self.read_src_u32(src1, literal);
                let bin = match op {
                    0x1B => BinaryOperator::And,
                    0x1C => BinaryOperator::InclusiveOr,
                    _ => BinaryOperator::ExclusiveOr,
                };
                let res = self.emit_expr(Expression::Binary {
                    op: bin,
                    left: l,
                    right: r,
                });
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_xnor_b32: ~(src0 ^ src1)
            0x1E => {
                let l = self.read_src_u32(src0, literal);
                let r = self.read_src_u32(src1, literal);
                let x = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ExclusiveOr,
                    left: l,
                    right: r,
                });
                let res = self.emit_expr(Expression::Unary {
                    op: UnaryOperator::BitwiseNot,
                    expr: x,
                });
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_mac_f32 (GFX10.1): vdst = src0 * src1 + vdst (unfused)
            0x1F => {
                let a = self.read_src_f32(src0, literal, abs0, neg0);
                let b = self.read_src_f32(src1, literal, abs1, neg1);
                let c = self.load_vgpr_f32(vdst);
                let prod = self.emit_bin(BinaryOperator::Multiply, a, b);
                let res = self.emit_bin(BinaryOperator::Add, prod, c);
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_madmk_f32 (GFX10.1): vdst = src0 * K + src1 (unfused, mandatory K literal)
            // v_madak_f32 (GFX10.1): vdst = src0 * src1 + K (unfused, mandatory K literal)
            0x20 | 0x21 => {
                let a = self.read_src_f32(src0, None, abs0, neg0);
                let b = self.read_src_f32(src1, None, abs1, neg1);
                let k = self.lit_f32_from_bits(literal.unwrap_or(0));
                let res = if op == 0x20 {
                    let prod = self.emit_bin(BinaryOperator::Multiply, a, k);
                    self.emit_bin(BinaryOperator::Add, prod, b)
                } else {
                    let prod = self.emit_bin(BinaryOperator::Multiply, a, b);
                    self.emit_bin(BinaryOperator::Add, prod, k)
                };
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_add_co_ci_u32 / v_sub_co_ci_u32 / v_subrev_co_ci_u32:
            //   carry-in from VCC (VOP2) or src2 (VOP3B); carry/borrow-out to VCC or sdst.
            0x28..=0x2A => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let cin_bool = match cond_src {
                    Some(csrc) => self.read_lane_mask_bit(csrc, literal),
                    None => self.load_vcc(),
                };
                let cin = self.bool_to_u32(cin_bool);
                let (res, carry) = if op == 0x28 {
                    let s1 = self.emit_bin(BinaryOperator::Add, a, b);
                    let c1 = self.emit_bin(BinaryOperator::Less, s1, a);
                    let s2 = self.emit_bin(BinaryOperator::Add, s1, cin);
                    let c2 = self.emit_bin(BinaryOperator::Less, s2, s1);
                    let c = self.emit_bin(BinaryOperator::LogicalOr, c1, c2);
                    (s2, c)
                } else {
                    let (x, y) = if op == 0x29 { (a, b) } else { (b, a) };
                    let d1 = self.emit_bin(BinaryOperator::Subtract, x, y);
                    let b1 = self.emit_bin(BinaryOperator::Less, x, y);
                    let d2 = self.emit_bin(BinaryOperator::Subtract, d1, cin);
                    let b2 = self.emit_bin(BinaryOperator::Less, d1, cin);
                    let c = self.emit_bin(BinaryOperator::LogicalOr, b1, b2);
                    (d2, c)
                };
                self.store_vgpr_u32(vdst, res);
                self.store_lane_mask(carry_sdst.unwrap_or(106), carry);
                true
            }
            // v_add_nc_u32 / v_sub_nc_u32 / v_subrev_nc_u32
            0x25 | 0x26 | 0x27 => {
                let l = self.read_src_u32(src0, literal);
                let r = self.read_src_u32(src1, literal);
                let (left, right, bin) = match op {
                    0x25 => (l, r, BinaryOperator::Add),
                    0x26 => (l, r, BinaryOperator::Subtract),
                    _ => (r, l, BinaryOperator::Subtract),
                };
                let res = self.emit_expr(Expression::Binary {
                    op: bin,
                    left,
                    right,
                });
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_fmamk_f32: vdst = fma(src0, K, src1)
            0x2C => {
                let a = self.read_src_f32(src0, None, abs0, neg0);
                let k = self.lit_f32_from_bits(literal.unwrap_or(0));
                let c = self.read_src_f32(src1, None, abs1, neg1);
                let res = self.emit_expr(Expression::Math {
                    fun: MathFunction::Fma,
                    arg: a,
                    arg1: Some(k),
                    arg2: Some(c),
                    arg3: None,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_fmaak_f32: vdst = fma(src0, src1, K)
            0x2D => {
                let a = self.read_src_f32(src0, None, abs0, neg0);
                let b = self.read_src_f32(src1, None, abs1, neg1);
                let k = self.lit_f32_from_bits(literal.unwrap_or(0));
                let res = self.emit_expr(Expression::Math {
                    fun: MathFunction::Fma,
                    arg: a,
                    arg1: Some(b),
                    arg2: Some(k),
                    arg3: None,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_cvt_pkrtz_f16_f32: pack2x16float(vec2<f32>(src0, src1))
            0x2F => {
                let a_raw = self.read_src_f32(src0, literal, abs0, neg0);
                let b_raw = self.read_src_f32(src1, literal, abs1, neg1);
                let a = self.apply_float_out_mods(a_raw, omod, clamp);
                let b = self.apply_float_out_mods(b_raw, omod, clamp);
                let pair = self.emit_expr(Expression::Compose {
                    ty: self.types.vec2_f32_ty,
                    components: vec![a, b],
                });
                let packed = self.emit_expr(Expression::Math {
                    fun: MathFunction::Pack2x16float,
                    arg: pair,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                self.store_vgpr_u32(vdst, packed);
                true
            }
            // v_add_f16 / v_sub_f16 / v_subrev_f16 / v_mul_f16 (f32 math + pack2x16float, no `enable f16;`)
            0x32..=0x35 => {
                let a = self.read_src_mixed_f16_or_f32(src0, literal, true, false, abs0, neg0);
                let b = self.read_src_mixed_f16_or_f32(src1, literal, true, false, abs1, neg1);
                let (left, right, bin) = match op {
                    0x32 => (a, b, BinaryOperator::Add),
                    0x33 => (a, b, BinaryOperator::Subtract),
                    0x34 => (b, a, BinaryOperator::Subtract),
                    _ => (a, b, BinaryOperator::Multiply),
                };
                let res = self.emit_expr(Expression::Binary {
                    op: bin,
                    left,
                    right,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f16_lo(vdst, out);
                true
            }
            // v_fmac_f16: vdst.lo = fma(src0.lo, src1.lo, vdst.lo)
            0x36 => {
                let a = self.read_src_mixed_f16_or_f32(src0, literal, true, false, abs0, neg0);
                let b = self.read_src_mixed_f16_or_f32(src1, literal, true, false, abs1, neg1);
                let c = self.read_src_mixed_f16_or_f32(
                    256 + u16::from(vdst),
                    None,
                    true,
                    false,
                    false,
                    false,
                );
                let res = self.emit_expr(Expression::Math {
                    fun: MathFunction::Fma,
                    arg: a,
                    arg1: Some(b),
                    arg2: Some(c),
                    arg3: None,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f16_lo(vdst, out);
                true
            }
            // v_fmamk_f16: vdst.lo = fma(src0.lo, K_f16, src1.lo)
            0x37 => {
                let a = self.read_src_mixed_f16_or_f32(src0, None, true, false, abs0, neg0);
                let k = self.lit_f16_from_u32_lo(literal.unwrap_or(0));
                let c = self.read_src_mixed_f16_or_f32(src1, None, true, false, abs1, neg1);
                let res = self.emit_expr(Expression::Math {
                    fun: MathFunction::Fma,
                    arg: a,
                    arg1: Some(k),
                    arg2: Some(c),
                    arg3: None,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f16_lo(vdst, out);
                true
            }
            // v_fmaak_f16: vdst.lo = fma(src0.lo, src1.lo, K_f16)
            0x38 => {
                let a = self.read_src_mixed_f16_or_f32(src0, None, true, false, abs0, neg0);
                let b = self.read_src_mixed_f16_or_f32(src1, None, true, false, abs1, neg1);
                let k = self.lit_f16_from_u32_lo(literal.unwrap_or(0));
                let res = self.emit_expr(Expression::Math {
                    fun: MathFunction::Fma,
                    arg: a,
                    arg1: Some(b),
                    arg2: Some(k),
                    arg3: None,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f16_lo(vdst, out);
                true
            }
            // v_max_f16 / v_min_f16
            0x39 | 0x3A => {
                let a = self.read_src_mixed_f16_or_f32(src0, literal, true, false, abs0, neg0);
                let b = self.read_src_mixed_f16_or_f32(src1, literal, true, false, abs1, neg1);
                let fun = if op == 0x39 {
                    MathFunction::Max
                } else {
                    MathFunction::Min
                };
                let res = self.emit_expr(Expression::Math {
                    fun,
                    arg: a,
                    arg1: Some(b),
                    arg2: None,
                    arg3: None,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f16_lo(vdst, out);
                true
            }
            // v_ldexp_f16: vdst.lo = ldexp(f16(src0.lo), sext16(src1.lo))
            0x3B => {
                let mut a =
                    self.read_src_mixed_f16_or_f32(src0, literal, true, false, abs0, neg0);
                let exp_raw = self.read_src_i32(src1, literal);
                let sh16 = self.lit_u32(16);
                let exp_shl = self.emit_bin(BinaryOperator::ShiftLeft, exp_raw, sh16);
                let exp_i16 = self.emit_bin(BinaryOperator::ShiftRight, exp_shl, sh16);
                let lo_e = self.lit_i32(-64);
                let hi_e = self.lit_i32(64);
                let exp_clamped = self.emit_expr(Expression::Math {
                    fun: MathFunction::Clamp,
                    arg: exp_i16,
                    arg1: Some(lo_e),
                    arg2: Some(hi_e),
                    arg3: None,
                });
                if self.is_const_expr(a) && self.is_const_expr(exp_clamped) {
                    a = self.call_pg6_rt_f32(a);
                }
                let res = self.emit_expr(Expression::Math {
                    fun: MathFunction::Ldexp,
                    arg: a,
                    arg1: Some(exp_clamped),
                    arg2: None,
                    arg3: None,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f16_lo(vdst, out);
                true
            }
            // v_pk_fmac_f16: packed 2xf16 fma(src0, src1, vdst) via unpack2x16float/pack2x16float
            0x3C => {
                let a = self.read_src_pk_f16(src0, literal, false, true, neg0, neg0);
                let b = self.read_src_pk_f16(src1, literal, false, true, neg1, neg1);
                let c = self.read_src_pk_f16(
                    256 + u16::from(vdst),
                    None,
                    false,
                    true,
                    false,
                    false,
                );
                let mut res = self.emit_expr(Expression::Math {
                    fun: MathFunction::Fma,
                    arg: a,
                    arg1: Some(b),
                    arg2: Some(c),
                    arg3: None,
                });
                if clamp {
                    let z = self.lit_f32(0.0);
                    let o = self.lit_f32(1.0);
                    let lo = self.emit_expr(Expression::Splat {
                        size: VectorSize::Bi,
                        value: z,
                    });
                    let hi = self.emit_expr(Expression::Splat {
                        size: VectorSize::Bi,
                        value: o,
                    });
                    res = self.emit_expr(Expression::Math {
                        fun: MathFunction::Clamp,
                        arg: res,
                        arg1: Some(lo),
                        arg2: Some(hi),
                        arg3: None,
                    });
                }
                let packed = self.emit_expr(Expression::Math {
                    fun: MathFunction::Pack2x16float,
                    arg: res,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                self.store_vgpr_u32(vdst, packed);
                true
            }
            _ => false,
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn translate_vop3(
        &mut self,
        op: u16,
        vdst: u8,
        sdst: Option<u8>,
        src0: u16,
        src1: u16,
        src2: u16,
        clamp: bool,
        omod: u8,
        abs: u8,
        neg: u8,
        op_sel: u8,
        literal: Option<u32>,
    ) -> bool {
        // VOPC promoted to VOP3 (0x000..=0x0FF)
        if op <= 0x0FF {
            return self.translate_vopc(
                op as u8,
                src0,
                src1,
                literal,
                abs,
                neg,
                op_sel,
                Some(vdst),
            );
        }
        // VOP2 promoted to VOP3 (0x100..=0x13F)
        if (0x100..=0x13F).contains(&op) {
            let v2_op = (op - 0x100) as u8;
            if vop2_is_madk(v2_op) {
                // *mk*/*ak* forms are VOP2-only (inline K literal); no VOP3 encoding exists.
                return false;
            }
            let cond = if matches!(v2_op, 0x00 | 0x01) || vop2_is_co_ci(v2_op) {
                Some(src2)
            } else {
                None
            };
            return self.translate_vop2(
                v2_op, vdst, src0, src1, cond, literal, omod, clamp, abs, neg, sdst,
            );
        }
        // VOP1 promoted to VOP3 (0x180..=0x1FF)
        if (0x180..=0x1FF).contains(&op) {
            let v1_op = (op - 0x180) as u8;
            return self.translate_vop1(
                v1_op,
                vdst,
                src0,
                literal,
                omod,
                clamp,
                (abs & 1) != 0,
                (neg & 1) != 0,
            );
        }

        let abs0 = (abs & 1) != 0;
        let neg0 = (neg & 1) != 0;
        let abs1 = (abs & 2) != 0;
        let neg1 = (neg & 2) != 0;
        let abs2 = (abs & 4) != 0;
        let neg2 = (neg & 4) != 0;

        match op {
            // v_mad_legacy_f32 / v_mad_f32 / v_fma_f32
            0x140 | 0x141 | 0x14B => {
                let a = self.read_src_f32(src0, literal, abs0, neg0);
                let b = self.read_src_f32(src1, literal, abs1, neg1);
                let c = self.read_src_f32(src2, literal, abs2, neg2);
                let res = self.emit_expr(Expression::Math {
                    fun: MathFunction::Fma,
                    arg: a,
                    arg1: Some(b),
                    arg2: Some(c),
                    arg3: None,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_mad_i32_i24: sext24(src0) * sext24(src1) + src2
            0x142 => {
                let a_raw = self.read_src_i32(src0, literal);
                let b_raw = self.read_src_i32(src1, literal);
                let c = self.read_src_i32(src2, literal);
                let sh8 = self.lit_u32(8);
                let a_sh = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftLeft,
                    left: a_raw,
                    right: sh8,
                });
                let a = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftRight,
                    left: a_sh,
                    right: sh8,
                });
                let b_sh = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftLeft,
                    left: b_raw,
                    right: sh8,
                });
                let b = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftRight,
                    left: b_sh,
                    right: sh8,
                });
                let prod = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Multiply,
                    left: a,
                    right: b,
                });
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Add,
                    left: prod,
                    right: c,
                });
                self.store_vgpr_i32(vdst, res);
                true
            }
            // v_mad_u32_u24: (src0 & 0xFFFFFF) * (src1 & 0xFFFFFF) + src2
            0x143 => {
                let a_raw = self.read_src_u32(src0, literal);
                let b_raw = self.read_src_u32(src1, literal);
                let c = self.read_src_u32(src2, literal);
                let mask24 = self.lit_u32(0x00FF_FFFF);
                let a = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: a_raw,
                    right: mask24,
                });
                let b = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: b_raw,
                    right: mask24,
                });
                let prod = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Multiply,
                    left: a,
                    right: b,
                });
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Add,
                    left: prod,
                    right: c,
                });
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_cubeid_f32 (0x144), v_cubesc_f32 (0x145), v_cubetc_f32 (0x146), v_cubema_f32 (0x147):
            // Standard AMD GFX10.3 cubemap face/coordinate math on (x = src0, y = src1, z = src2).
            0x144..=0x147 => {
                let x = self.read_src_f32(src0, literal, abs0, neg0);
                let y = self.read_src_f32(src1, literal, abs1, neg1);
                let z = self.read_src_f32(src2, literal, abs2, neg2);
                let ax = self.emit_expr(Expression::Math {
                    fun: MathFunction::Abs,
                    arg: x,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let ay = self.emit_expr(Expression::Math {
                    fun: MathFunction::Abs,
                    arg: y,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let az = self.emit_expr(Expression::Math {
                    fun: MathFunction::Abs,
                    arg: z,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let az_ge_ax = self.emit_bin(BinaryOperator::GreaterEqual, az, ax);
                let az_ge_ay = self.emit_bin(BinaryOperator::GreaterEqual, az, ay);
                let z_major = self.emit_bin(BinaryOperator::LogicalAnd, az_ge_ax, az_ge_ay);
                let y_major = self.emit_bin(BinaryOperator::GreaterEqual, ay, ax);
                let zero = self.lit_f32(0.0);
                let res = match op {
                    // v_cubeid_f32: +X=0, -X=1, +Y=2, -Y=3, +Z=4, -Z=5
                    0x144 => {
                        let x_neg = self.emit_bin(BinaryOperator::Less, x, zero);
                        let y_neg = self.emit_bin(BinaryOperator::Less, y, zero);
                        let z_neg = self.emit_bin(BinaryOperator::Less, z, zero);
                        let f0 = self.lit_f32(0.0);
                        let f1 = self.lit_f32(1.0);
                        let f2 = self.lit_f32(2.0);
                        let f3 = self.lit_f32(3.0);
                        let f4 = self.lit_f32(4.0);
                        let f5 = self.lit_f32(5.0);
                        let x_id = self.emit_select(x_neg, f1, f0);
                        let y_id = self.emit_select(y_neg, f3, f2);
                        let z_id = self.emit_select(z_neg, f5, f4);
                        let xy_id = self.emit_select(y_major, y_id, x_id);
                        self.emit_select(z_major, z_id, xy_id)
                    }
                    // v_cubesc_f32: z_major -> (z<0 ? -x : x), y_major -> x, x_major -> (x<0 ? z : -z)
                    0x145 => {
                        let x_neg = self.emit_bin(BinaryOperator::Less, x, zero);
                        let z_neg = self.emit_bin(BinaryOperator::Less, z, zero);
                        let neg_x = self.emit_expr(Expression::Unary {
                            op: UnaryOperator::Negate,
                            expr: x,
                        });
                        let neg_z = self.emit_expr(Expression::Unary {
                            op: UnaryOperator::Negate,
                            expr: z,
                        });
                        let x_sc = self.emit_select(x_neg, z, neg_z);
                        let z_sc = self.emit_select(z_neg, neg_x, x);
                        let xy_sc = self.emit_select(y_major, x, x_sc);
                        self.emit_select(z_major, z_sc, xy_sc)
                    }
                    // v_cubetc_f32: z_major -> -y, y_major -> (y<0 ? -z : z), x_major -> -y
                    0x146 => {
                        let y_neg = self.emit_bin(BinaryOperator::Less, y, zero);
                        let neg_y = self.emit_expr(Expression::Unary {
                            op: UnaryOperator::Negate,
                            expr: y,
                        });
                        let neg_z = self.emit_expr(Expression::Unary {
                            op: UnaryOperator::Negate,
                            expr: z,
                        });
                        let y_tc = self.emit_select(y_neg, neg_z, z);
                        let xy_tc = self.emit_select(y_major, y_tc, neg_y);
                        self.emit_select(z_major, neg_y, xy_tc)
                    }
                    // v_cubema_f32: 2.0 * signed major axis
                    _ => {
                        let two = self.lit_f32(2.0);
                        let xy_ma = self.emit_select(y_major, y, x);
                        let ma = self.emit_select(z_major, z, xy_ma);
                        self.emit_bin(BinaryOperator::Multiply, two, ma)
                    }
                };
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_bfe_u32: unsigned bitfield extract (offset = src1[4:0], width = src2[4:0])
            0x148 => {
                let s0 = self.read_src_u32(src0, literal);
                let s1 = self.read_src_u32(src1, literal);
                let s2 = self.read_src_u32(src2, literal);
                let mask31 = self.lit_u32(31);
                let offset = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: s1,
                    right: mask31,
                });
                let width = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: s2,
                    right: mask31,
                });
                let shifted = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftRight,
                    left: s0,
                    right: offset,
                });
                let one = self.lit_u32(1);
                let one_shl = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftLeft,
                    left: one,
                    right: width,
                });
                let bit_mask = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Subtract,
                    left: one_shl,
                    right: one,
                });
                let extracted = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: shifted,
                    right: bit_mask,
                });
                let zero = self.lit_u32(0);
                let is_zero = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Equal,
                    left: width,
                    right: zero,
                });
                let res = self.emit_expr(Expression::Select {
                    condition: is_zero,
                    accept: zero,
                    reject: extracted,
                });
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_bfe_i32: signed bitfield extract (offset = src1[4:0], width = src2[4:0])
            0x149 => {
                let s0_i = self.read_src_i32(src0, literal);
                let s1 = self.read_src_u32(src1, literal);
                let s2 = self.read_src_u32(src2, literal);
                let mask31 = self.lit_u32(31);
                let offset = self.emit_bin(BinaryOperator::And, s1, mask31);
                let width = self.emit_bin(BinaryOperator::And, s2, mask31);
                let res_i = self.emit_bfe_i32(s0_i, offset, width);
                self.store_vgpr_i32(vdst, res_i);
                true
            }
            // v_bfi_b32: (src0 & src1) | (~src0 & src2)
            0x14A => {
                let mask = self.read_src_u32(src0, literal);
                let a = self.read_src_u32(src1, literal);
                let b = self.read_src_u32(src2, literal);
                let nmask = self.emit_expr(Expression::Unary {
                    op: UnaryOperator::BitwiseNot,
                    expr: mask,
                });
                let lhs = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: mask,
                    right: a,
                });
                let rhs = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: nmask,
                    right: b,
                });
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::InclusiveOr,
                    left: lhs,
                    right: rhs,
                });
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_lerp_u8: per-byte average ((src0.b[k] + src1.b[k] + (src2.b[k] & 1)) >> 1)
            0x14D => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let c = self.read_src_u32(src2, literal);
                let mask_ff = self.lit_u32(0xFF);
                let one = self.lit_u32(1);
                let mut res = self.lit_u32(0);
                for k in 0..4u32 {
                    let sh = self.lit_u32(k * 8);
                    let a_k = if k == 0 {
                        self.emit_bin(BinaryOperator::And, a, mask_ff)
                    } else {
                        let tmp = self.emit_bin(BinaryOperator::ShiftRight, a, sh);
                        self.emit_bin(BinaryOperator::And, tmp, mask_ff)
                    };
                    let b_k = if k == 0 {
                        self.emit_bin(BinaryOperator::And, b, mask_ff)
                    } else {
                        let tmp = self.emit_bin(BinaryOperator::ShiftRight, b, sh);
                        self.emit_bin(BinaryOperator::And, tmp, mask_ff)
                    };
                    let c_k = if k == 0 {
                        self.emit_bin(BinaryOperator::And, c, one)
                    } else {
                        let tmp = self.emit_bin(BinaryOperator::ShiftRight, c, sh);
                        self.emit_bin(BinaryOperator::And, tmp, one)
                    };
                    let ab = self.emit_bin(BinaryOperator::Add, a_k, b_k);
                    let abc = self.emit_bin(BinaryOperator::Add, ab, c_k);
                    let avg = self.emit_bin(BinaryOperator::ShiftRight, abc, one);
                    let byte_v = self.emit_bin(BinaryOperator::And, avg, mask_ff);
                    let placed = if k == 0 {
                        byte_v
                    } else {
                        self.emit_bin(BinaryOperator::ShiftLeft, byte_v, sh)
                    };
                    res = if k == 0 {
                        placed
                    } else {
                        self.emit_bin(BinaryOperator::InclusiveOr, res, placed)
                    };
                }
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_alignbit_b32 (0x14E) / v_alignbyte_b32 (0x14F):
            //   funnel shift right of (src0:src1) by (src2 & 31) bits or ((src2 & 3) * 8) bits
            0x14E | 0x14F => {
                let hi = self.read_src_u32(src0, literal);
                let lo = self.read_src_u32(src1, literal);
                let sh_raw = self.read_src_u32(src2, literal);
                let mask31 = self.lit_u32(31);
                let sh = if op == 0x14E {
                    self.emit_bin(BinaryOperator::And, sh_raw, mask31)
                } else {
                    let mask3 = self.lit_u32(3);
                    let sh3 = self.lit_u32(3);
                    let bytes = self.emit_bin(BinaryOperator::And, sh_raw, mask3);
                    self.emit_bin(BinaryOperator::ShiftLeft, bytes, sh3)
                };
                let zero = self.lit_u32(0);
                let is_zero = self.emit_bin(BinaryOperator::Equal, sh, zero);
                let c32 = self.lit_u32(32);
                let inv_sh_raw = self.emit_bin(BinaryOperator::Subtract, c32, sh);
                let inv_sh = self.emit_bin(BinaryOperator::And, inv_sh_raw, mask31);
                let hi_part = self.emit_bin(BinaryOperator::ShiftLeft, hi, inv_sh);
                let lo_part = self.emit_bin(BinaryOperator::ShiftRight, lo, sh);
                let shifted = self.emit_bin(BinaryOperator::InclusiveOr, hi_part, lo_part);
                let res = self.emit_select(is_zero, lo, shifted);
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_min3_f32 / v_max3_f32
            0x151 | 0x154 => {
                let a = self.read_src_f32(src0, literal, abs0, neg0);
                let b = self.read_src_f32(src1, literal, abs1, neg1);
                let c = self.read_src_f32(src2, literal, abs2, neg2);
                let fun = if op == 0x151 {
                    MathFunction::Min
                } else {
                    MathFunction::Max
                };
                let ab = self.emit_expr(Expression::Math {
                    fun,
                    arg: a,
                    arg1: Some(b),
                    arg2: None,
                    arg3: None,
                });
                let res = self.emit_expr(Expression::Math {
                    fun,
                    arg: ab,
                    arg1: Some(c),
                    arg2: None,
                    arg3: None,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_med3_f32: clamp(a, min(b, c), max(b, c))
            0x157 => {
                let a = self.read_src_f32(src0, literal, abs0, neg0);
                let b = self.read_src_f32(src1, literal, abs1, neg1);
                let c = self.read_src_f32(src2, literal, abs2, neg2);
                let lo = self.emit_expr(Expression::Math {
                    fun: MathFunction::Min,
                    arg: b,
                    arg1: Some(c),
                    arg2: None,
                    arg3: None,
                });
                let hi = self.emit_expr(Expression::Math {
                    fun: MathFunction::Max,
                    arg: b,
                    arg1: Some(c),
                    arg2: None,
                    arg3: None,
                });
                let res = self.emit_expr(Expression::Math {
                    fun: MathFunction::Clamp,
                    arg: a,
                    arg1: Some(lo),
                    arg2: Some(hi),
                    arg3: None,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_min3_i32 / v_max3_i32 / v_med3_i32
            0x152 | 0x155 | 0x158 => {
                let a = self.read_src_i32(src0, literal);
                let b = self.read_src_i32(src1, literal);
                let c = self.read_src_i32(src2, literal);
                let res = if op == 0x158 {
                    let lo = self.emit_expr(Expression::Math {
                        fun: MathFunction::Min,
                        arg: b,
                        arg1: Some(c),
                        arg2: None,
                        arg3: None,
                    });
                    let hi = self.emit_expr(Expression::Math {
                        fun: MathFunction::Max,
                        arg: b,
                        arg1: Some(c),
                        arg2: None,
                        arg3: None,
                    });
                    self.emit_expr(Expression::Math {
                        fun: MathFunction::Clamp,
                        arg: a,
                        arg1: Some(lo),
                        arg2: Some(hi),
                        arg3: None,
                    })
                } else {
                    let fun = if op == 0x152 {
                        MathFunction::Min
                    } else {
                        MathFunction::Max
                    };
                    let ab = self.emit_expr(Expression::Math {
                        fun,
                        arg: a,
                        arg1: Some(b),
                        arg2: None,
                        arg3: None,
                    });
                    self.emit_expr(Expression::Math {
                        fun,
                        arg: ab,
                        arg1: Some(c),
                        arg2: None,
                        arg3: None,
                    })
                };
                self.store_vgpr_i32(vdst, res);
                true
            }
            // v_min3_u32 / v_max3_u32 / v_med3_u32
            0x153 | 0x156 | 0x159 => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let c = self.read_src_u32(src2, literal);
                let res = if op == 0x159 {
                    let lo = self.emit_expr(Expression::Math {
                        fun: MathFunction::Min,
                        arg: b,
                        arg1: Some(c),
                        arg2: None,
                        arg3: None,
                    });
                    let hi = self.emit_expr(Expression::Math {
                        fun: MathFunction::Max,
                        arg: b,
                        arg1: Some(c),
                        arg2: None,
                        arg3: None,
                    });
                    self.emit_expr(Expression::Math {
                        fun: MathFunction::Clamp,
                        arg: a,
                        arg1: Some(lo),
                        arg2: Some(hi),
                        arg3: None,
                    })
                } else {
                    let fun = if op == 0x153 {
                        MathFunction::Min
                    } else {
                        MathFunction::Max
                    };
                    let ab = self.emit_expr(Expression::Math {
                        fun,
                        arg: a,
                        arg1: Some(b),
                        arg2: None,
                        arg3: None,
                    });
                    self.emit_expr(Expression::Math {
                        fun,
                        arg: ab,
                        arg1: Some(c),
                        arg2: None,
                        arg3: None,
                    })
                };
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_sad_u8 (0x15A) / v_sad_hi_u8 (0x15B) / v_msad_u8 (0x165):
            //   sum of absolute differences over 4 unsigned bytes + src2 (shifted <<16 for sad_hi)
            0x15A | 0x15B | 0x165 => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let c = self.read_src_u32(src2, literal);
                let mask_ff = self.lit_u32(0xFF);
                let zero = self.lit_u32(0);
                let mut acc = zero;
                for k in 0..4u32 {
                    let sh = self.lit_u32(k * 8);
                    let a_k = if k == 0 {
                        self.emit_bin(BinaryOperator::And, a, mask_ff)
                    } else {
                        let tmp = self.emit_bin(BinaryOperator::ShiftRight, a, sh);
                        self.emit_bin(BinaryOperator::And, tmp, mask_ff)
                    };
                    let b_k = if k == 0 {
                        self.emit_bin(BinaryOperator::And, b, mask_ff)
                    } else {
                        let tmp = self.emit_bin(BinaryOperator::ShiftRight, b, sh);
                        self.emit_bin(BinaryOperator::And, tmp, mask_ff)
                    };
                    let a_ge_b = self.emit_bin(BinaryOperator::GreaterEqual, a_k, b_k);
                    let ab = self.emit_bin(BinaryOperator::Subtract, a_k, b_k);
                    let ba = self.emit_bin(BinaryOperator::Subtract, b_k, a_k);
                    let diff = self.emit_select(a_ge_b, ab, ba);
                    let term = if op == 0x165 {
                        let b_zero = self.emit_bin(BinaryOperator::Equal, b_k, zero);
                        self.emit_select(b_zero, zero, diff)
                    } else {
                        diff
                    };
                    acc = if k == 0 {
                        term
                    } else {
                        self.emit_bin(BinaryOperator::Add, acc, term)
                    };
                }
                let sad = if op == 0x15B {
                    let sh16 = self.lit_u32(16);
                    self.emit_bin(BinaryOperator::ShiftLeft, acc, sh16)
                } else {
                    acc
                };
                let res = self.emit_add_sat_u32(sad, c, clamp);
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_sad_u16: |a.lo - b.lo| + |a.hi - b.hi| + c
            0x15C => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let c = self.read_src_u32(src2, literal);
                let mask16 = self.lit_u32(0xFFFF);
                let sh16 = self.lit_u32(16);
                let a0 = self.emit_bin(BinaryOperator::And, a, mask16);
                let b0 = self.emit_bin(BinaryOperator::And, b, mask16);
                let a1 = self.emit_bin(BinaryOperator::ShiftRight, a, sh16);
                let b1 = self.emit_bin(BinaryOperator::ShiftRight, b, sh16);
                let ge0 = self.emit_bin(BinaryOperator::GreaterEqual, a0, b0);
                let ab0 = self.emit_bin(BinaryOperator::Subtract, a0, b0);
                let ba0 = self.emit_bin(BinaryOperator::Subtract, b0, a0);
                let d0 = self.emit_select(ge0, ab0, ba0);
                let ge1 = self.emit_bin(BinaryOperator::GreaterEqual, a1, b1);
                let ab1 = self.emit_bin(BinaryOperator::Subtract, a1, b1);
                let ba1 = self.emit_bin(BinaryOperator::Subtract, b1, a1);
                let d1 = self.emit_select(ge1, ab1, ba1);
                let sad = self.emit_bin(BinaryOperator::Add, d0, d1);
                let res = self.emit_add_sat_u32(sad, c, clamp);
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_sad_u32: |src0 - src1| + src2
            0x15D => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let c = self.read_src_u32(src2, literal);
                let ge = self.emit_bin(BinaryOperator::GreaterEqual, a, b);
                let ab = self.emit_bin(BinaryOperator::Subtract, a, b);
                let ba = self.emit_bin(BinaryOperator::Subtract, b, a);
                let diff = self.emit_select(ge, ab, ba);
                let res = self.emit_add_sat_u32(diff, c, clamp);
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_cvt_pk_u8_f32: clamp f32 src0 to [0, 255], convert to u8, pack into byte (src1 & 3) of src2
            0x15E => {
                let f = self.read_src_f32(src0, literal, abs0, neg0);
                let lo = self.lit_f32(0.0);
                let hi = self.lit_f32(255.0);
                let clamped = self.emit_expr(Expression::Math {
                    fun: MathFunction::Clamp,
                    arg: f,
                    arg1: Some(lo),
                    arg2: Some(hi),
                    arg3: None,
                });
                let u_raw = self.emit_expr(Expression::As {
                    expr: clamped,
                    kind: ScalarKind::Uint,
                    convert: Some(4),
                });
                let mask_ff = self.lit_u32(0xFF);
                let byte_val = self.emit_bin(BinaryOperator::And, u_raw, mask_ff);
                let s1 = self.read_src_u32(src1, literal);
                let mask3 = self.lit_u32(3);
                let byte_idx = self.emit_bin(BinaryOperator::And, s1, mask3);
                let sh3 = self.lit_u32(3);
                let shift = self.emit_bin(BinaryOperator::ShiftLeft, byte_idx, sh3);
                let shifted_byte = self.emit_bin(BinaryOperator::ShiftLeft, byte_val, shift);
                let byte_mask = self.emit_bin(BinaryOperator::ShiftLeft, mask_ff, shift);
                let inv_mask = self.emit_bit_not(byte_mask);
                let s2 = self.read_src_u32(src2, literal);
                let cleared = self.emit_bin(BinaryOperator::And, s2, inv_mask);
                let res = self.emit_bin(BinaryOperator::InclusiveOr, cleared, shifted_byte);
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_div_fixup_f32: IEEE-754 float division completion (src0 = pre-quotient, src1 = den, src2 = num)
            0x15F => {
                let _q = self.read_src_f32(src0, literal, abs0, neg0);
                let den = self.read_src_f32(src1, literal, abs1, neg1);
                let num = self.read_src_f32(src2, literal, abs2, neg2);
                let res = self.emit_bin(BinaryOperator::Divide, num, den);
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_div_fmas_f32: fma(src0, src1, src2) * (vcc ? 2^32 : 1.0)
            0x163 => {
                let a = self.read_src_f32(src0, literal, abs0, neg0);
                let b = self.read_src_f32(src1, literal, abs1, neg1);
                let c = self.read_src_f32(src2, literal, abs2, neg2);
                let mut res = self.emit_expr(Expression::Math {
                    fun: MathFunction::Fma,
                    arg: a,
                    arg1: Some(b),
                    arg2: Some(c),
                    arg3: None,
                });
                if self.vcc_local.is_some() {
                    let vcc = self.load_vcc();
                    let scale_hi = self.lit_f32(4_294_967_296.0);
                    let scale_one = self.lit_f32(1.0);
                    let scale = self.emit_select(vcc, scale_hi, scale_one);
                    res = self.emit_bin(BinaryOperator::Multiply, res, scale);
                }
                let out = self.apply_float_out_mods(res, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_mul_lo_u32
            0x169 => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Multiply,
                    left: a,
                    right: b,
                });
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_div_scale_f32 (VOP3B): pass-through operand with unscaled carry flag (sdst = 0)
            0x16D => {
                let a = self.read_src_f32(src0, literal, abs0, neg0);
                self.store_vgpr_f32(vdst, a);
                if let Some(sd) = sdst {
                    let f = self.lit_bool(false);
                    self.store_lane_mask(sd, f);
                }
                true
            }
            // v_add_co_u32 / v_sub_co_u32 / v_subrev_co_u32 (VOP3B with carry-out in sdst)
            0x30F | 0x310 | 0x319 => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let (res, carry) = match op {
                    0x30F => {
                        let sum = self.emit_expr(Expression::Binary {
                            op: BinaryOperator::Add,
                            left: a,
                            right: b,
                        });
                        let c = self.emit_expr(Expression::Binary {
                            op: BinaryOperator::Less,
                            left: sum,
                            right: a,
                        });
                        (sum, c)
                    }
                    0x310 => {
                        let diff = self.emit_expr(Expression::Binary {
                            op: BinaryOperator::Subtract,
                            left: a,
                            right: b,
                        });
                        let c = self.emit_expr(Expression::Binary {
                            op: BinaryOperator::Less,
                            left: a,
                            right: b,
                        });
                        (diff, c)
                    }
                    _ => {
                        let diff = self.emit_expr(Expression::Binary {
                            op: BinaryOperator::Subtract,
                            left: b,
                            right: a,
                        });
                        let c = self.emit_expr(Expression::Binary {
                            op: BinaryOperator::Less,
                            left: b,
                            right: a,
                        });
                        (diff, c)
                    }
                };
                self.store_vgpr_u32(vdst, res);
                if let Some(sd) = sdst {
                    self.store_lane_mask(sd, carry);
                }
                true
            }
            // v_mul_hi_u32 / v_mul_hi_i32: exact high 32 bits of the 32x32 product (u32-only WGSL)
            0x16A | 0x16C => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let res = if op == 0x16A {
                    self.emit_mul_hi_u32(a, b)
                } else {
                    self.emit_mul_hi_i32(a, b)
                };
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_xor3_b32: src0 ^ src1 ^ src2 (GFX10.3 VOP3 0x178)
            0x178 => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let c = self.read_src_u32(src2, literal);
                let ab = self.emit_bin(BinaryOperator::ExclusiveOr, a, b);
                let res = self.emit_bin(BinaryOperator::ExclusiveOr, ab, c);
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_lshlrev_b64 / v_lshrrev_b64 / v_ashrrev_i64:
            //   vdst[0:1] = src1[0:1] <</>>/>>> (src0 & 63) on u32 register pairs
            0x2FF..=0x301 => {
                let amount = self.read_src_u32(src0, literal);
                let (lo, hi) = self.read_vsrc_pair(src1, literal);
                let kind = match op {
                    0x2FF => Shift64Kind::Left,
                    0x300 => Shift64Kind::LogicalRight,
                    _ => Shift64Kind::ArithmeticRight,
                };
                let (rlo, rhi) = self.emit_shift64(kind, lo, hi, amount);
                self.store_vgpr_u32(vdst, rlo);
                if vdst < 255 {
                    self.store_vgpr_u32(vdst + 1, rhi);
                }
                true
            }
            // v_mad_u16: u16(src0) * u16(src1) + u16(src2) with op_sel & optional u16 saturation clamp
            0x340 => {
                let a = self.read_src_u16_half(src0, literal, (op_sel & 1) != 0);
                let b = self.read_src_u16_half(src1, literal, (op_sel & 2) != 0);
                let c = self.read_src_u16_half(src2, literal, (op_sel & 4) != 0);
                let prod = self.emit_bin(BinaryOperator::Multiply, a, b);
                let mut res = self.emit_bin(BinaryOperator::Add, prod, c);
                if clamp {
                    let max_u16 = self.lit_u32(0xFFFF);
                    res = self.emit_expr(Expression::Math {
                        fun: MathFunction::Min,
                        arg: res,
                        arg1: Some(max_u16),
                        arg2: None,
                        arg3: None,
                    });
                }
                if (op_sel & 8) != 0 {
                    self.store_vgpr_u16_hi(vdst, res);
                } else {
                    self.store_vgpr_u16_lo(vdst, res);
                }
                true
            }
            // v_interp_p1ll_f16 (0x342), v_interp_p1lv_f16 (0x343), v_interp_p2_f16 (0x35A):
            // GFX10.3 VOP3 16-bit fragment attribute interpolation.
            // src0 packs {high[8], attrchan[7:6], attr[5:0]}; op_sel[3] selects dst lo/hi f16 half on p2.
            0x342 | 0x343 | 0x35A => {
                if self.stage != ShaderStage::Fragment {
                    return false;
                }
                let Some(arg_idx) = self.frag_in_arg else {
                    return false;
                };
                let (attr, attrchan, high) = decode_vop3_interp_attr(src0);
                let clamped_attr = attr % MAX_INTER_STAGE_LOCATIONS;
                let chan = attrchan & 0x3;
                let Some(&member_idx) = self.frag_attr_member_index.get(&clamped_attr) else {
                    return false;
                };
                let frag_in = self.raw_expr(Expression::FunctionArgument(arg_idx));
                let attr_vec = self.emit_expr(Expression::AccessIndex {
                    base: frag_in,
                    index: member_idx,
                });
                let comp = self.emit_expr(Expression::AccessIndex {
                    base: attr_vec,
                    index: u32::from(chan),
                });
                let val = if high {
                    let bits = self.bitcast_f32_to_u32(comp);
                    let pair = self.emit_expr(Expression::Math {
                        fun: MathFunction::Unpack2x16float,
                        arg: bits,
                        arg1: None,
                        arg2: None,
                        arg3: None,
                    });
                    self.emit_expr(Expression::AccessIndex {
                        base: pair,
                        index: 1,
                    })
                } else if self
                    .frag_attr_f16_high_channels
                    .contains(&(clamped_attr, chan))
                {
                    let bits = self.bitcast_f32_to_u32(comp);
                    let pair = self.emit_expr(Expression::Math {
                        fun: MathFunction::Unpack2x16float,
                        arg: bits,
                        arg1: None,
                        arg2: None,
                        arg3: None,
                    });
                    self.emit_expr(Expression::AccessIndex {
                        base: pair,
                        index: 0,
                    })
                } else {
                    comp
                };
                let out = self.apply_float_out_mods(val, omod, clamp);
                if op == 0x35A {
                    if (op_sel & 0x8) != 0 {
                        self.store_vgpr_f16_hi(vdst, out);
                    } else {
                        self.store_vgpr_f16_lo(vdst, out);
                    }
                } else {
                    self.store_vgpr_f32(vdst, out);
                }
                true
            }
            // v_perm_b32: byte permute over 8-byte concat (src0=bytes[4..7], src1=bytes[0..3]) via src2
            0x344 => {
                let s0 = self.read_src_u32(src0, literal);
                let s1 = self.read_src_u32(src1, literal);
                let s2 = self.read_src_u32(src2, literal);
                let res = if let (
                    Expression::Literal(Literal::U32(v0)),
                    Expression::Literal(Literal::U32(v1)),
                    Expression::Literal(Literal::U32(v2)),
                ) = (
                    &self.func.expressions[s0],
                    &self.func.expressions[s1],
                    &self.func.expressions[s2],
                ) {
                    let mut folded = 0u32;
                    for k in 0..4u32 {
                        let sel = (*v2 >> (k * 8)) & 0xFF;
                        let byte_v = if sel < 8 {
                            let src_word = if (sel & 4) != 0 { *v0 } else { *v1 };
                            (src_word >> ((sel & 3) * 8)) & 0xFF
                        } else if sel < 12 {
                            let sign_word = if (sel & 2) != 0 { *v0 } else { *v1 };
                            let sign_pos = if (sel & 1) != 0 { 31 } else { 15 };
                            if ((sign_word >> sign_pos) & 1) != 0 {
                                0xFF
                            } else {
                                0
                            }
                        } else if sel == 12 {
                            0
                        } else {
                            0xFF
                        };
                        folded |= byte_v << (k * 8);
                    }
                    self.lit_u32(folded)
                } else {
                    self.call_pg6_byte_perm(s0, s1, s2)
                };
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_xad_u32: (src0 ^ src1) + src2
            0x345 => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let c = self.read_src_u32(src2, literal);
                let x = self.emit_bin(BinaryOperator::ExclusiveOr, a, b);
                let res = self.emit_bin(BinaryOperator::Add, x, c);
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_lshl_add_u32: (src0 << (src1 & 31)) + src2
            0x346 => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let c = self.read_src_u32(src2, literal);
                let mask = self.lit_u32(31);
                let sh = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: b,
                    right: mask,
                });
                let shifted = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftLeft,
                    left: a,
                    right: sh,
                });
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Add,
                    left: shifted,
                    right: c,
                });
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_add_lshl_u32: (src0 + src1) << (src2 & 31)
            0x347 => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let c = self.read_src_u32(src2, literal);
                let sum = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Add,
                    left: a,
                    right: b,
                });
                let mask = self.lit_u32(31);
                let sh = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: c,
                    right: mask,
                });
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftLeft,
                    left: sum,
                    right: sh,
                });
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_fma_f16: vdst.{lo,hi} = fma(src0.{lo,hi}, src1.{lo,hi}, src2.{lo,hi}) per op_sel
            0x34B => {
                let a = self.read_src_mixed_f16_or_f32(
                    src0,
                    literal,
                    true,
                    (op_sel & 1) != 0,
                    abs0,
                    neg0,
                );
                let b = self.read_src_mixed_f16_or_f32(
                    src1,
                    literal,
                    true,
                    (op_sel & 2) != 0,
                    abs1,
                    neg1,
                );
                let c = self.read_src_mixed_f16_or_f32(
                    src2,
                    literal,
                    true,
                    (op_sel & 4) != 0,
                    abs2,
                    neg2,
                );
                let res = self.emit_expr(Expression::Math {
                    fun: MathFunction::Fma,
                    arg: a,
                    arg1: Some(b),
                    arg2: Some(c),
                    arg3: None,
                });
                let out = self.apply_float_out_mods(res, omod, clamp);
                if (op_sel & 8) != 0 {
                    self.store_vgpr_f16_hi(vdst, out);
                } else {
                    self.store_vgpr_f16_lo(vdst, out);
                }
                true
            }
            // v_mad_i16: i16(src0) * i16(src1) + i16(src2) with op_sel & optional i16 saturation clamp
            0x35E => {
                let a = self.read_src_i16_half(src0, literal, (op_sel & 1) != 0);
                let b = self.read_src_i16_half(src1, literal, (op_sel & 2) != 0);
                let c = self.read_src_i16_half(src2, literal, (op_sel & 4) != 0);
                let prod = self.emit_bin(BinaryOperator::Multiply, a, b);
                let mut res = self.emit_bin(BinaryOperator::Add, prod, c);
                if clamp {
                    let lo_i16 = self.lit_i32(-32768);
                    let hi_i16 = self.lit_i32(32767);
                    res = self.emit_expr(Expression::Math {
                        fun: MathFunction::Clamp,
                        arg: res,
                        arg1: Some(lo_i16),
                        arg2: Some(hi_i16),
                        arg3: None,
                    });
                }
                let res_u = self.bitcast_i32_to_u32(res);
                if (op_sel & 8) != 0 {
                    self.store_vgpr_u16_hi(vdst, res_u);
                } else {
                    self.store_vgpr_u16_lo(vdst, res_u);
                }
                true
            }
            // v_readlane_b32 sdst, vsrc0, ssrc1: read a lane of vsrc0 into scalar sdst.
            // Constant lanes read per-(vgpr, lane) spill locals when present (falling back to
            // hardware `subgroupShuffle` under `WaveEmulMode::Subgroups` or v[vsrc0]); dynamic
            // lanes select across known constant lane slots before subgroup/fallback read.
            0x360 => {
                let val = if (256..=511).contains(&src0) {
                    let vsrc = (src0 - 256) as u8;
                    if let Some(lane) = decode_const_lane_index(src1, literal) {
                        if let Some(&slot_local) = self.lane_spill_locals.get(&(vsrc, lane)) {
                            self.load_local(slot_local)
                        } else if self.subgroups_active() {
                            let src_val = self.read_src_u32(src0, literal);
                            let lane_lit = self.lit_u32(u32::from(lane));
                            self.emit_wave_shuffle(src_val, lane_lit)
                        } else {
                            self.read_src_u32(src0, literal)
                        }
                    } else if let Some(slots) = self.vgpr_lane_slots.get(&vsrc).cloned() {
                        let mut acc = self.read_src_u32(src0, literal);
                        let raw_lane = self.read_src_u32(src1, literal);
                        let mask63 = self.lit_u32(63);
                        let lane_idx = self.emit_bin(BinaryOperator::And, raw_lane, mask63);
                        for (slot_lane, slot_local) in slots {
                            let target = self.lit_u32(u32::from(slot_lane));
                            let is_match = self.emit_bin(BinaryOperator::Equal, lane_idx, target);
                            let slot_val = self.load_local(slot_local);
                            acc = self.emit_select(is_match, slot_val, acc);
                        }
                        acc
                    } else if self.subgroups_active() {
                        let src_val = self.read_src_u32(src0, literal);
                        let raw_lane = self.read_src_u32(src1, literal);
                        let mask63 = self.lit_u32(63);
                        let lane_idx = self.emit_bin(BinaryOperator::And, raw_lane, mask63);
                        self.emit_wave_shuffle(src_val, lane_idx)
                    } else {
                        self.read_src_u32(src0, literal)
                    }
                } else {
                    self.read_src_u32(src0, literal)
                };
                let sd = vdst & 0x7F;
                if sd == 106 {
                    let one = self.lit_u32(1);
                    let bit = self.emit_bin(BinaryOperator::And, val, one);
                    let zero = self.lit_u32(0);
                    let cond = self.emit_bin(BinaryOperator::NotEqual, bit, zero);
                    self.store_vcc(cond);
                } else {
                    self.store_sgpr_u32(sd, val);
                }
                true
            }
            // v_writelane_b32 vdst, ssrc0, ssrc1: write scalar data into a lane of vdst.
            // Constant lanes write dedicated per-(vgpr, lane) spill locals so multi-lane SGPR
            // spills into the same VGPR never clobber one another; lane 0 also mirrors to v[vdst].
            0x361 => {
                let val = self.read_src_u32(src0, literal);
                if let Some(lane) = decode_const_lane_index(src1, literal) {
                    if let Some(&slot_local) = self.lane_spill_locals.get(&(vdst, lane)) {
                        self.store_local(slot_local, val);
                    }
                    if lane == 0
                        && let Some(&v_local) = self.vgpr_locals.get(&vdst)
                    {
                        let f = self.bitcast_u32_to_f32(val);
                        self.store_local(v_local, f);
                    }
                } else if let Some(&v_local) = self.vgpr_locals.get(&vdst) {
                    let f = self.bitcast_u32_to_f32(val);
                    self.store_local(v_local, f);
                }
                true
            }
            // v_add_f64: f32-emulated addition into dst VGPR pair (low = f32 sum, high = 0)
            0x364 => {
                let a = self.read_src_f32(src0, literal, abs0, neg0);
                let b = self.read_src_f32(src1, literal, abs1, neg1);
                let sum = self.emit_bin(BinaryOperator::Add, a, b);
                let out = self.apply_float_out_mods(sum, omod, clamp);
                self.store_vgpr_f32(vdst, out);
                if vdst < 255 {
                    let zero = self.lit_u32(0);
                    self.store_vgpr_u32(vdst + 1, zero);
                }
                true
            }
            // v_mbcnt_lo_u32_b32 (0x365) / v_mbcnt_hi_u32_b32 (0x366):
            // Count set bits in `src0` for wave lanes strictly below this invocation's lane (`0..63`),
            // plus `src1` accumulator. Core RDNA2 mesh/compute wave-prefix-sum primitive.
            0x365 | 0x366 => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let mask63 = self.lit_u32(63);
                let mask31 = self.lit_u32(31);
                let c32 = self.lit_u32(32);
                let one = self.lit_u32(1);
                let zero = self.lit_u32(0);
                let all_ones = self.lit_u32(0xFFFF_FFFF);
                let lane = if self.subgroups_active() {
                    let sg_lane = self.emit_subgroup_invocation_id();
                    self.emit_bin(BinaryOperator::And, sg_lane, mask63)
                } else {
                    let local_idx = self.emit_compute_local_index();
                    self.emit_bin(BinaryOperator::And, local_idx, mask63)
                };
                let in_hi = self.emit_bin(BinaryOperator::GreaterEqual, lane, c32);
                let bit_mask = if op == 0x365 {
                    let sh = self.emit_bin(BinaryOperator::And, lane, mask31);
                    let sh_bit = self.emit_bin(BinaryOperator::ShiftLeft, one, sh);
                    let lo_mask = self.emit_bin(BinaryOperator::Subtract, sh_bit, one);
                    self.emit_select(in_hi, all_ones, lo_mask)
                } else {
                    let hi_lane = self.emit_bin(BinaryOperator::Subtract, lane, c32);
                    let sh = self.emit_bin(BinaryOperator::And, hi_lane, mask31);
                    let sh_bit = self.emit_bin(BinaryOperator::ShiftLeft, one, sh);
                    let hi_mask = self.emit_bin(BinaryOperator::Subtract, sh_bit, one);
                    self.emit_select(in_hi, hi_mask, zero)
                };
                let masked = self.emit_bin(BinaryOperator::And, a, bit_mask);
                let cnt = self.emit_expr(Expression::Math {
                    fun: MathFunction::CountOneBits,
                    arg: masked,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let res = self.emit_bin(BinaryOperator::Add, cnt, b);
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_add3_u32
            0x36D => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let c = self.read_src_u32(src2, literal);
                let ab = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Add,
                    left: a,
                    right: b,
                });
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Add,
                    left: ab,
                    right: c,
                });
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_lshl_or_b32: (src0 << (src1 & 31)) | src2
            0x36E => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let c = self.read_src_u32(src2, literal);
                let mask = self.lit_u32(31);
                let sh = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: b,
                    right: mask,
                });
                let shifted = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftLeft,
                    left: a,
                    right: sh,
                });
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::InclusiveOr,
                    left: shifted,
                    right: c,
                });
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_and_or_b32: (src0 & src1) | src2 (GFX10.3 VOP3 0x371; 0x36F retained for compat)
            0x36F | 0x371 => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let c = self.read_src_u32(src2, literal);
                let ab = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: a,
                    right: b,
                });
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::InclusiveOr,
                    left: ab,
                    right: c,
                });
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_or3_b32: src0 | src1 | src2 (GFX10.3 VOP3 0x372; 0x370 retained for compat)
            0x370 | 0x372 => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let c = self.read_src_u32(src2, literal);
                let ab = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::InclusiveOr,
                    left: a,
                    right: b,
                });
                let res = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::InclusiveOr,
                    left: ab,
                    right: c,
                });
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_permlane16_b32 (0x377) / v_permlanex16_b32 (0x378):
            // 16-lane row nibble-indexed cross-lane permute (`0x377` same 16-lane row, `0x378`
            // opposite 16-lane row in the same 32-lane half).
            0x377 | 0x378 => {
                let val = self.read_src_u32(src0, literal);
                let s1 = self.read_src_u32(src1, literal);
                let s2 = self.read_src_u32(src2, literal);
                let compute_permlane_src = |this: &mut Self, lane: Handle<Expression>| {
                    let mask15 = this.lit_u32(15);
                    let mask7 = this.lit_u32(7);
                    let c8 = this.lit_u32(8);
                    let sh2 = this.lit_u32(2);
                    let row_mask = this.lit_u32(0xFFFF_FFF0);
                    let row_lane = this.emit_bin(BinaryOperator::And, lane, mask15);
                    let in_hi_half = this.emit_bin(BinaryOperator::GreaterEqual, row_lane, c8);
                    let sel_word = this.emit_select(in_hi_half, s2, s1);
                    let idx_in_word = this.emit_bin(BinaryOperator::And, row_lane, mask7);
                    let bit_shift = this.emit_bin(BinaryOperator::ShiftLeft, idx_in_word, sh2);
                    let shifted = this.emit_bin(BinaryOperator::ShiftRight, sel_word, bit_shift);
                    let target_in_row = this.emit_bin(BinaryOperator::And, shifted, mask15);
                    let row_base_raw = this.emit_bin(BinaryOperator::And, lane, row_mask);
                    let row_base = if op == 0x378 {
                        let c16 = this.lit_u32(16);
                        this.emit_bin(BinaryOperator::ExclusiveOr, row_base_raw, c16)
                    } else {
                        row_base_raw
                    };
                    let mask63 = this.lit_u32(63);
                    let src_raw = this.emit_bin(BinaryOperator::InclusiveOr, row_base, target_in_row);
                    this.emit_bin(BinaryOperator::And, src_raw, mask63)
                };
                if self.subgroups_active() {
                    let sg_lane = self.emit_subgroup_invocation_id();
                    let src_lane = compute_permlane_src(self, sg_lane);
                    let res = self.emit_wave_shuffle(val, src_lane);
                    self.store_vgpr_u32(vdst, res);
                } else if !self.in_nonuniform_cf()
                    && let Some(wave_lds) = self.wave_lds_global
                {
                    let wave_ptr = self.raw_expr(Expression::GlobalVariable(wave_lds));
                    let local_idx = self.emit_compute_local_index();
                    let mask255 = self.lit_u32(255);
                    let mask63 = self.lit_u32(63);
                    let wave_base_mask = self.lit_u32(0xFFFF_FFC0);
                    let slot = self.emit_bin(BinaryOperator::And, local_idx, mask255);
                    let wave_base = self.emit_bin(BinaryOperator::And, slot, wave_base_mask);
                    let lane = self.emit_bin(BinaryOperator::And, slot, mask63);
                    let my_ptr = self.emit_expr(Expression::Access {
                        base: wave_ptr,
                        index: slot,
                    });
                    self.push_stmt(Statement::Store {
                        pointer: my_ptr,
                        value: val,
                    });
                    self.push_stmt(Statement::ControlBarrier(naga::Barrier::WORK_GROUP));
                    let src_lane = compute_permlane_src(self, lane);
                    let target_slot_raw =
                        self.emit_bin(BinaryOperator::InclusiveOr, wave_base, src_lane);
                    let target_slot = self.emit_bin(BinaryOperator::And, target_slot_raw, mask255);
                    let src_ptr = self.emit_expr(Expression::Access {
                        base: wave_ptr,
                        index: target_slot,
                    });
                    let res = self.emit_expr(Expression::Load { pointer: src_ptr });
                    self.push_stmt(Statement::ControlBarrier(naga::Barrier::WORK_GROUP));
                    self.store_vgpr_u32(vdst, res);
                } else {
                    self.store_vgpr_u32(vdst, val);
                }
                true
            }
            _ => false,
        }
    }

    /// Extract one unsigned 16-bit half (`hi_half == false` -> `[15:0]`, `true` -> `[31:16]`) as `u32`.
    fn read_src_u16_half(
        &mut self,
        src: u16,
        literal: Option<u32>,
        hi_half: bool,
    ) -> Handle<Expression> {
        let u = self.read_src_u32(src, literal);
        if hi_half {
            let sh16 = self.lit_u32(16);
            self.emit_bin(BinaryOperator::ShiftRight, u, sh16)
        } else {
            let mask16 = self.lit_u32(0xFFFF);
            self.emit_bin(BinaryOperator::And, u, mask16)
        }
    }

    /// Extract one signed 16-bit half (`hi_half == false` -> `[15:0]`, `true` -> `[31:16]`) as `i32`.
    fn read_src_i16_half(
        &mut self,
        src: u16,
        literal: Option<u32>,
        hi_half: bool,
    ) -> Handle<Expression> {
        let i = self.read_src_i32(src, literal);
        let sh16 = self.lit_u32(16);
        if hi_half {
            self.emit_bin(BinaryOperator::ShiftRight, i, sh16)
        } else {
            let shl = self.emit_bin(BinaryOperator::ShiftLeft, i, sh16);
            self.emit_bin(BinaryOperator::ShiftRight, shl, sh16)
        }
    }

    /// Extract packed 2x`u16` lanes as `(lo, hi)` `u32` values respecting `op_sel` / `op_sel_hi`.
    fn read_pk_u16_lanes(
        &mut self,
        src: u16,
        literal: Option<u32>,
        sel_lo: bool,
        sel_hi: bool,
    ) -> (Handle<Expression>, Handle<Expression>) {
        let u = self.read_src_u32(src, literal);
        let mask16 = self.lit_u32(0xFFFF);
        let sh16 = self.lit_u32(16);
        let lo_raw = self.emit_bin(BinaryOperator::And, u, mask16);
        let hi_raw = self.emit_bin(BinaryOperator::ShiftRight, u, sh16);
        (
            if sel_lo { hi_raw } else { lo_raw },
            if sel_hi { hi_raw } else { lo_raw },
        )
    }

    /// Extract packed 2x`i16` lanes as `(lo, hi)` sign-extended `i32` values respecting `op_sel` / `op_sel_hi`.
    fn read_pk_i16_lanes(
        &mut self,
        src: u16,
        literal: Option<u32>,
        sel_lo: bool,
        sel_hi: bool,
    ) -> (Handle<Expression>, Handle<Expression>) {
        let i = self.read_src_i32(src, literal);
        let sh16 = self.lit_u32(16);
        let lo_shl = self.emit_bin(BinaryOperator::ShiftLeft, i, sh16);
        let lo_raw = self.emit_bin(BinaryOperator::ShiftRight, lo_shl, sh16);
        let hi_raw = self.emit_bin(BinaryOperator::ShiftRight, i, sh16);
        (
            if sel_lo { hi_raw } else { lo_raw },
            if sel_hi { hi_raw } else { lo_raw },
        )
    }

    /// Pack two 16-bit lane values `(lo, hi)` (as `u32`) into a 32-bit VGPR.
    fn pack_u16_pair_and_store(
        &mut self,
        vdst: u8,
        lo: Handle<Expression>,
        hi: Handle<Expression>,
    ) {
        let mask16 = self.lit_u32(0xFFFF);
        let sh16 = self.lit_u32(16);
        let lo_m = self.emit_bin(BinaryOperator::And, lo, mask16);
        let hi_sh = self.emit_bin(BinaryOperator::ShiftLeft, hi, sh16);
        let packed = self.emit_bin(BinaryOperator::InclusiveOr, lo_m, hi_sh);
        self.store_vgpr_u32(vdst, packed);
    }

    /// Unsigned 32-bit addition with optional saturation to `u32::MAX` (`clamp`).
    fn emit_add_sat_u32(
        &mut self,
        a: Handle<Expression>,
        b: Handle<Expression>,
        clamp: bool,
    ) -> Handle<Expression> {
        let sum = self.emit_bin(BinaryOperator::Add, a, b);
        if !clamp {
            return sum;
        }
        let ovf = self.emit_bin(BinaryOperator::Less, sum, a);
        let max_u = self.lit_u32(u32::MAX);
        self.emit_select(ovf, max_u, sum)
    }

    /// Signed 32-bit addition with optional saturation to `[i32::MIN, i32::MAX]` (`clamp`).
    fn emit_add_sat_i32(
        &mut self,
        a: Handle<Expression>,
        b: Handle<Expression>,
        clamp: bool,
    ) -> Handle<Expression> {
        let sum = self.emit_bin(BinaryOperator::Add, a, b);
        if !clamp {
            return sum;
        }
        let zero = self.lit_i32(0);
        let a_pos = self.emit_bin(BinaryOperator::Greater, a, zero);
        let b_pos = self.emit_bin(BinaryOperator::Greater, b, zero);
        let sum_neg = self.emit_bin(BinaryOperator::Less, sum, zero);
        let ab_pos = self.emit_bin(BinaryOperator::LogicalAnd, a_pos, b_pos);
        let pos_ovf = self.emit_bin(BinaryOperator::LogicalAnd, ab_pos, sum_neg);

        let a_neg = self.emit_bin(BinaryOperator::Less, a, zero);
        let b_neg = self.emit_bin(BinaryOperator::Less, b, zero);
        let sum_ge0 = self.emit_bin(BinaryOperator::GreaterEqual, sum, zero);
        let ab_neg = self.emit_bin(BinaryOperator::LogicalAnd, a_neg, b_neg);
        let neg_ovf = self.emit_bin(BinaryOperator::LogicalAnd, ab_neg, sum_ge0);

        let max_i = self.lit_i32(i32::MAX);
        let min_u = self.lit_u32(0x8000_0000);
        let min_i = self.bitcast_u32_to_i32(min_u);
        let clamped_neg = self.emit_select(neg_ovf, min_i, sum);
        self.emit_select(pos_ovf, max_i, clamped_neg)
    }

    /// Signed 4x8-bit integer dot-product with `i32` accumulate (`v_dot4_i32_i8` / `v_dot4c_i32_i8`).
    fn emit_dot4_i32_i8(
        &mut self,
        a_u: Handle<Expression>,
        b_u: Handle<Expression>,
        acc: Handle<Expression>,
        clamp: bool,
    ) -> Handle<Expression> {
        let a_i = self.bitcast_u32_to_i32(a_u);
        let b_i = self.bitcast_u32_to_i32(b_u);
        let sh24 = self.lit_u32(24);
        let mut dot = self.lit_i32(0);
        for k in 0..4u32 {
            let lsh = 24 - k * 8;
            let ak = if lsh == 0 {
                self.emit_bin(BinaryOperator::ShiftRight, a_i, sh24)
            } else {
                let sh = self.lit_u32(lsh);
                let tmp = self.emit_bin(BinaryOperator::ShiftLeft, a_i, sh);
                self.emit_bin(BinaryOperator::ShiftRight, tmp, sh24)
            };
            let bk = if lsh == 0 {
                self.emit_bin(BinaryOperator::ShiftRight, b_i, sh24)
            } else {
                let sh = self.lit_u32(lsh);
                let tmp = self.emit_bin(BinaryOperator::ShiftLeft, b_i, sh);
                self.emit_bin(BinaryOperator::ShiftRight, tmp, sh24)
            };
            let prod = self.emit_bin(BinaryOperator::Multiply, ak, bk);
            dot = if k == 0 {
                prod
            } else {
                self.emit_bin(BinaryOperator::Add, dot, prod)
            };
        }
        self.emit_add_sat_i32(dot, acc, clamp)
    }

    /// Signed 8x4-bit integer dot-product with `i32` accumulate (`v_dot8_i32_i4` / `v_dot8c_i32_i4`).
    fn emit_dot8_i32_i4(
        &mut self,
        a_u: Handle<Expression>,
        b_u: Handle<Expression>,
        acc: Handle<Expression>,
        clamp: bool,
    ) -> Handle<Expression> {
        let a_i = self.bitcast_u32_to_i32(a_u);
        let b_i = self.bitcast_u32_to_i32(b_u);
        let sh28 = self.lit_u32(28);
        let mut dot = self.lit_i32(0);
        for k in 0..8u32 {
            let lsh = 28 - k * 4;
            let ak = if lsh == 0 {
                self.emit_bin(BinaryOperator::ShiftRight, a_i, sh28)
            } else {
                let sh = self.lit_u32(lsh);
                let tmp = self.emit_bin(BinaryOperator::ShiftLeft, a_i, sh);
                self.emit_bin(BinaryOperator::ShiftRight, tmp, sh28)
            };
            let bk = if lsh == 0 {
                self.emit_bin(BinaryOperator::ShiftRight, b_i, sh28)
            } else {
                let sh = self.lit_u32(lsh);
                let tmp = self.emit_bin(BinaryOperator::ShiftLeft, b_i, sh);
                self.emit_bin(BinaryOperator::ShiftRight, tmp, sh28)
            };
            let prod = self.emit_bin(BinaryOperator::Multiply, ak, bk);
            dot = if k == 0 {
                prod
            } else {
                self.emit_bin(BinaryOperator::Add, dot, prod)
            };
        }
        self.emit_add_sat_i32(dot, acc, clamp)
    }

    #[allow(clippy::too_many_arguments)]
    fn translate_vop3p(
        &mut self,
        op: u8,
        vdst: u8,
        src0: u16,
        src1: u16,
        src2: u16,
        clamp: bool,
        op_sel: u8,
        op_sel_hi: u8,
        neg_lo: u8,
        neg_hi: u8,
        literal: Option<u32>,
    ) -> bool {
        let read_pk = |this: &mut Self, s: u16, idx: u8| {
            let bit = 1u8 << idx;
            this.read_src_pk_f16(
                s,
                literal,
                (op_sel & bit) != 0,
                (op_sel_hi & bit) != 0,
                (neg_lo & bit) != 0,
                (neg_hi & bit) != 0,
            )
        };
        let pack_and_store = |this: &mut Self, mut vec2_val: Handle<Expression>| {
            if clamp {
                let z = this.lit_f32(0.0);
                let o = this.lit_f32(1.0);
                let lo = this.emit_expr(Expression::Splat {
                    size: VectorSize::Bi,
                    value: z,
                });
                let hi = this.emit_expr(Expression::Splat {
                    size: VectorSize::Bi,
                    value: o,
                });
                vec2_val = this.emit_expr(Expression::Math {
                    fun: MathFunction::Clamp,
                    arg: vec2_val,
                    arg1: Some(lo),
                    arg2: Some(hi),
                    arg3: None,
                });
            }
            let packed = this.emit_expr(Expression::Math {
                fun: MathFunction::Pack2x16float,
                arg: vec2_val,
                arg1: None,
                arg2: None,
                arg3: None,
            });
            this.store_vgpr_u32(vdst, packed);
        };

        match op {
            // v_pk_mad_i16: packed 2xi16 a * b + c (optional i16 clamp)
            0x00 => {
                let (a0, a1) =
                    self.read_pk_i16_lanes(src0, literal, (op_sel & 1) != 0, (op_sel_hi & 1) != 0);
                let (b0, b1) =
                    self.read_pk_i16_lanes(src1, literal, (op_sel & 2) != 0, (op_sel_hi & 2) != 0);
                let (c0, c1) =
                    self.read_pk_i16_lanes(src2, literal, (op_sel & 4) != 0, (op_sel_hi & 4) != 0);
                let p0 = self.emit_bin(BinaryOperator::Multiply, a0, b0);
                let p1 = self.emit_bin(BinaryOperator::Multiply, a1, b1);
                let mut r0 = self.emit_bin(BinaryOperator::Add, p0, c0);
                let mut r1 = self.emit_bin(BinaryOperator::Add, p1, c1);
                if clamp {
                    let lo_i16 = self.lit_i32(-32768);
                    let hi_i16 = self.lit_i32(32767);
                    r0 = self.emit_expr(Expression::Math {
                        fun: MathFunction::Clamp,
                        arg: r0,
                        arg1: Some(lo_i16),
                        arg2: Some(hi_i16),
                        arg3: None,
                    });
                    r1 = self.emit_expr(Expression::Math {
                        fun: MathFunction::Clamp,
                        arg: r1,
                        arg1: Some(lo_i16),
                        arg2: Some(hi_i16),
                        arg3: None,
                    });
                }
                let u0 = self.bitcast_i32_to_u32(r0);
                let u1 = self.bitcast_i32_to_u32(r1);
                self.pack_u16_pair_and_store(vdst, u0, u1);
                true
            }
            // v_pk_mul_lo_u16: packed 2xu16 (a * b) & 0xFFFF
            0x01 => {
                let (a0, a1) =
                    self.read_pk_u16_lanes(src0, literal, (op_sel & 1) != 0, (op_sel_hi & 1) != 0);
                let (b0, b1) =
                    self.read_pk_u16_lanes(src1, literal, (op_sel & 2) != 0, (op_sel_hi & 2) != 0);
                let r0 = self.emit_bin(BinaryOperator::Multiply, a0, b0);
                let r1 = self.emit_bin(BinaryOperator::Multiply, a1, b1);
                self.pack_u16_pair_and_store(vdst, r0, r1);
                true
            }
            // v_pk_add_i16 (0x02) / v_pk_sub_i16 (0x03): packed 2xi16 add/sub (optional i16 clamp)
            0x02 | 0x03 => {
                let (a0, a1) =
                    self.read_pk_i16_lanes(src0, literal, (op_sel & 1) != 0, (op_sel_hi & 1) != 0);
                let (b0, b1) =
                    self.read_pk_i16_lanes(src1, literal, (op_sel & 2) != 0, (op_sel_hi & 2) != 0);
                let bin = if op == 0x02 {
                    BinaryOperator::Add
                } else {
                    BinaryOperator::Subtract
                };
                let mut r0 = self.emit_bin(bin, a0, b0);
                let mut r1 = self.emit_bin(bin, a1, b1);
                if clamp {
                    let lo_i16 = self.lit_i32(-32768);
                    let hi_i16 = self.lit_i32(32767);
                    r0 = self.emit_expr(Expression::Math {
                        fun: MathFunction::Clamp,
                        arg: r0,
                        arg1: Some(lo_i16),
                        arg2: Some(hi_i16),
                        arg3: None,
                    });
                    r1 = self.emit_expr(Expression::Math {
                        fun: MathFunction::Clamp,
                        arg: r1,
                        arg1: Some(lo_i16),
                        arg2: Some(hi_i16),
                        arg3: None,
                    });
                }
                let u0 = self.bitcast_i32_to_u32(r0);
                let u1 = self.bitcast_i32_to_u32(r1);
                self.pack_u16_pair_and_store(vdst, u0, u1);
                true
            }
            // v_pk_lshlrev_b16 (0x04) / v_pk_lshrrev_b16 (0x05): packed 2xu16 src1 <</>> (src0 & 15)
            0x04 | 0x05 => {
                let (a0, a1) =
                    self.read_pk_u16_lanes(src0, literal, (op_sel & 1) != 0, (op_sel_hi & 1) != 0);
                let (b0, b1) =
                    self.read_pk_u16_lanes(src1, literal, (op_sel & 2) != 0, (op_sel_hi & 2) != 0);
                let mask15 = self.lit_u32(15);
                let sh0 = self.emit_bin(BinaryOperator::And, a0, mask15);
                let sh1 = self.emit_bin(BinaryOperator::And, a1, mask15);
                let bin = if op == 0x04 {
                    BinaryOperator::ShiftLeft
                } else {
                    BinaryOperator::ShiftRight
                };
                let r0 = self.emit_bin(bin, b0, sh0);
                let r1 = self.emit_bin(bin, b1, sh1);
                self.pack_u16_pair_and_store(vdst, r0, r1);
                true
            }
            // v_pk_ashrrev_i16: packed 2xi16 i16(src1) >> (src0 & 15)
            0x06 => {
                let (a0, a1) =
                    self.read_pk_u16_lanes(src0, literal, (op_sel & 1) != 0, (op_sel_hi & 1) != 0);
                let (b0, b1) =
                    self.read_pk_i16_lanes(src1, literal, (op_sel & 2) != 0, (op_sel_hi & 2) != 0);
                let mask15 = self.lit_u32(15);
                let sh0 = self.emit_bin(BinaryOperator::And, a0, mask15);
                let sh1 = self.emit_bin(BinaryOperator::And, a1, mask15);
                let r0 = self.emit_bin(BinaryOperator::ShiftRight, b0, sh0);
                let r1 = self.emit_bin(BinaryOperator::ShiftRight, b1, sh1);
                let u0 = self.bitcast_i32_to_u32(r0);
                let u1 = self.bitcast_i32_to_u32(r1);
                self.pack_u16_pair_and_store(vdst, u0, u1);
                true
            }
            // v_pk_max_i16 (0x07) / v_pk_min_i16 (0x08)
            0x07 | 0x08 => {
                let (a0, a1) =
                    self.read_pk_i16_lanes(src0, literal, (op_sel & 1) != 0, (op_sel_hi & 1) != 0);
                let (b0, b1) =
                    self.read_pk_i16_lanes(src1, literal, (op_sel & 2) != 0, (op_sel_hi & 2) != 0);
                let fun = if op == 0x07 {
                    MathFunction::Max
                } else {
                    MathFunction::Min
                };
                let r0 = self.emit_expr(Expression::Math {
                    fun,
                    arg: a0,
                    arg1: Some(b0),
                    arg2: None,
                    arg3: None,
                });
                let r1 = self.emit_expr(Expression::Math {
                    fun,
                    arg: a1,
                    arg1: Some(b1),
                    arg2: None,
                    arg3: None,
                });
                let u0 = self.bitcast_i32_to_u32(r0);
                let u1 = self.bitcast_i32_to_u32(r1);
                self.pack_u16_pair_and_store(vdst, u0, u1);
                true
            }
            // v_pk_mad_u16: packed 2xu16 a * b + c (optional u16 clamp)
            0x09 => {
                let (a0, a1) =
                    self.read_pk_u16_lanes(src0, literal, (op_sel & 1) != 0, (op_sel_hi & 1) != 0);
                let (b0, b1) =
                    self.read_pk_u16_lanes(src1, literal, (op_sel & 2) != 0, (op_sel_hi & 2) != 0);
                let (c0, c1) =
                    self.read_pk_u16_lanes(src2, literal, (op_sel & 4) != 0, (op_sel_hi & 4) != 0);
                let p0 = self.emit_bin(BinaryOperator::Multiply, a0, b0);
                let p1 = self.emit_bin(BinaryOperator::Multiply, a1, b1);
                let mut r0 = self.emit_bin(BinaryOperator::Add, p0, c0);
                let mut r1 = self.emit_bin(BinaryOperator::Add, p1, c1);
                if clamp {
                    let max_u16 = self.lit_u32(0xFFFF);
                    r0 = self.emit_expr(Expression::Math {
                        fun: MathFunction::Min,
                        arg: r0,
                        arg1: Some(max_u16),
                        arg2: None,
                        arg3: None,
                    });
                    r1 = self.emit_expr(Expression::Math {
                        fun: MathFunction::Min,
                        arg: r1,
                        arg1: Some(max_u16),
                        arg2: None,
                        arg3: None,
                    });
                }
                self.pack_u16_pair_and_store(vdst, r0, r1);
                true
            }
            // v_pk_add_u16 (0x0A) / v_pk_sub_u16 (0x0B): packed 2xu16 add/sub (optional u16 clamp)
            0x0A | 0x0B => {
                let (a0, a1) =
                    self.read_pk_u16_lanes(src0, literal, (op_sel & 1) != 0, (op_sel_hi & 1) != 0);
                let (b0, b1) =
                    self.read_pk_u16_lanes(src1, literal, (op_sel & 2) != 0, (op_sel_hi & 2) != 0);
                let (r0, r1) = if op == 0x0A {
                    let mut s0 = self.emit_bin(BinaryOperator::Add, a0, b0);
                    let mut s1 = self.emit_bin(BinaryOperator::Add, a1, b1);
                    if clamp {
                        let max_u16 = self.lit_u32(0xFFFF);
                        s0 = self.emit_expr(Expression::Math {
                            fun: MathFunction::Min,
                            arg: s0,
                            arg1: Some(max_u16),
                            arg2: None,
                            arg3: None,
                        });
                        s1 = self.emit_expr(Expression::Math {
                            fun: MathFunction::Min,
                            arg: s1,
                            arg1: Some(max_u16),
                            arg2: None,
                            arg3: None,
                        });
                    }
                    (s0, s1)
                } else if clamp {
                    let zero = self.lit_u32(0);
                    let d0 = self.emit_bin(BinaryOperator::Subtract, a0, b0);
                    let d1 = self.emit_bin(BinaryOperator::Subtract, a1, b1);
                    let lt0 = self.emit_bin(BinaryOperator::Less, a0, b0);
                    let lt1 = self.emit_bin(BinaryOperator::Less, a1, b1);
                    (
                        self.emit_select(lt0, zero, d0),
                        self.emit_select(lt1, zero, d1),
                    )
                } else {
                    (
                        self.emit_bin(BinaryOperator::Subtract, a0, b0),
                        self.emit_bin(BinaryOperator::Subtract, a1, b1),
                    )
                };
                self.pack_u16_pair_and_store(vdst, r0, r1);
                true
            }
            // v_pk_max_u16 (0x0C) / v_pk_min_u16 (0x0D)
            0x0C | 0x0D => {
                let (a0, a1) =
                    self.read_pk_u16_lanes(src0, literal, (op_sel & 1) != 0, (op_sel_hi & 1) != 0);
                let (b0, b1) =
                    self.read_pk_u16_lanes(src1, literal, (op_sel & 2) != 0, (op_sel_hi & 2) != 0);
                let fun = if op == 0x0C {
                    MathFunction::Max
                } else {
                    MathFunction::Min
                };
                let r0 = self.emit_expr(Expression::Math {
                    fun,
                    arg: a0,
                    arg1: Some(b0),
                    arg2: None,
                    arg3: None,
                });
                let r1 = self.emit_expr(Expression::Math {
                    fun,
                    arg: a1,
                    arg1: Some(b1),
                    arg2: None,
                    arg3: None,
                });
                self.pack_u16_pair_and_store(vdst, r0, r1);
                true
            }
            // v_pk_fma_f16
            0x0E => {
                let a = read_pk(self, src0, 0);
                let b = read_pk(self, src1, 1);
                let c = read_pk(self, src2, 2);
                let res = self.emit_expr(Expression::Math {
                    fun: MathFunction::Fma,
                    arg: a,
                    arg1: Some(b),
                    arg2: Some(c),
                    arg3: None,
                });
                pack_and_store(self, res);
                true
            }
            // v_pk_add_f16 / v_pk_mul_f16
            0x0F | 0x10 => {
                let a = read_pk(self, src0, 0);
                let b = read_pk(self, src1, 1);
                let bin = if op == 0x0F {
                    BinaryOperator::Add
                } else {
                    BinaryOperator::Multiply
                };
                let res = self.emit_expr(Expression::Binary {
                    op: bin,
                    left: a,
                    right: b,
                });
                pack_and_store(self, res);
                true
            }
            // v_pk_min_f16 / v_pk_max_f16
            0x11 | 0x12 => {
                let a = read_pk(self, src0, 0);
                let b = read_pk(self, src1, 1);
                let fun = if op == 0x11 {
                    MathFunction::Min
                } else {
                    MathFunction::Max
                };
                let res = self.emit_expr(Expression::Math {
                    fun,
                    arg: a,
                    arg1: Some(b),
                    arg2: None,
                    arg3: None,
                });
                pack_and_store(self, res);
                true
            }
            // v_dot2_f32_f16: dot(unpack(src0), unpack(src1)) + src2
            0x13 => {
                let a = read_pk(self, src0, 0);
                let b = read_pk(self, src1, 1);
                let c = self.read_src_f32(src2, literal, false, (neg_lo & 4) != 0);
                let d = self.emit_expr(Expression::Math {
                    fun: MathFunction::Dot,
                    arg: a,
                    arg1: Some(b),
                    arg2: None,
                    arg3: None,
                });
                let sum = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Add,
                    left: d,
                    right: c,
                });
                let out = self.apply_float_out_mods(sum, 0, clamp);
                self.store_vgpr_f32(vdst, out);
                true
            }
            // v_dot2_i32_i16: sext16(src0.lo)*sext16(src1.lo) + sext16(src0.hi)*sext16(src1.hi) + src2
            0x14 => {
                let (a0, a1) = self.read_pk_i16_lanes(src0, literal, false, true);
                let (b0, b1) = self.read_pk_i16_lanes(src1, literal, false, true);
                let c = self.read_src_i32(src2, literal);
                let p0 = self.emit_bin(BinaryOperator::Multiply, a0, b0);
                let p1 = self.emit_bin(BinaryOperator::Multiply, a1, b1);
                let dot = self.emit_add_sat_i32(p0, p1, clamp);
                let res = self.emit_add_sat_i32(dot, c, clamp);
                self.store_vgpr_i32(vdst, res);
                true
            }
            // v_dot2_u32_u16: zext16(src0.lo)*zext16(src1.lo) + zext16(src0.hi)*zext16(src1.hi) + src2
            0x15 => {
                let (a0, a1) = self.read_pk_u16_lanes(src0, literal, false, true);
                let (b0, b1) = self.read_pk_u16_lanes(src1, literal, false, true);
                let c = self.read_src_u32(src2, literal);
                let p0 = self.emit_bin(BinaryOperator::Multiply, a0, b0);
                let p1 = self.emit_bin(BinaryOperator::Multiply, a1, b1);
                let dot = self.emit_add_sat_u32(p0, p1, clamp);
                let res = self.emit_add_sat_u32(dot, c, clamp);
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_dot4_i32_i8: sum_{k=0..4}(sext8(src0.b[k]) * sext8(src1.b[k])) + src2
            0x16 => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let c = self.read_src_i32(src2, literal);
                let res = self.emit_dot4_i32_i8(a, b, c, clamp);
                self.store_vgpr_i32(vdst, res);
                true
            }
            // v_dot4_u32_u8: sum_{k=0..4}(zext8(src0.b[k]) * zext8(src1.b[k])) + src2
            0x17 => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let c = self.read_src_u32(src2, literal);
                let mask_ff = self.lit_u32(0xFF);
                let mut dot = self.lit_u32(0);
                for k in 0..4u32 {
                    let sh = self.lit_u32(k * 8);
                    let ak = if k == 0 {
                        self.emit_bin(BinaryOperator::And, a, mask_ff)
                    } else {
                        let tmp = self.emit_bin(BinaryOperator::ShiftRight, a, sh);
                        self.emit_bin(BinaryOperator::And, tmp, mask_ff)
                    };
                    let bk = if k == 0 {
                        self.emit_bin(BinaryOperator::And, b, mask_ff)
                    } else {
                        let tmp = self.emit_bin(BinaryOperator::ShiftRight, b, sh);
                        self.emit_bin(BinaryOperator::And, tmp, mask_ff)
                    };
                    let prod = self.emit_bin(BinaryOperator::Multiply, ak, bk);
                    dot = if k == 0 {
                        prod
                    } else {
                        self.emit_bin(BinaryOperator::Add, dot, prod)
                    };
                }
                let res = self.emit_add_sat_u32(dot, c, clamp);
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_dot8_i32_i4: sum_{k=0..8}(sext4(src0.n[k]) * sext4(src1.n[k])) + src2
            0x18 => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let c = self.read_src_i32(src2, literal);
                let res = self.emit_dot8_i32_i4(a, b, c, clamp);
                self.store_vgpr_i32(vdst, res);
                true
            }
            // v_dot8_u32_u4: sum_{k=0..8}(zext4(src0.n[k]) * zext4(src1.n[k])) + src2
            0x19 => {
                let a = self.read_src_u32(src0, literal);
                let b = self.read_src_u32(src1, literal);
                let c = self.read_src_u32(src2, literal);
                let mask_f = self.lit_u32(0xF);
                let mut dot = self.lit_u32(0);
                for k in 0..8u32 {
                    let sh = self.lit_u32(k * 4);
                    let ak = if k == 0 {
                        self.emit_bin(BinaryOperator::And, a, mask_f)
                    } else {
                        let tmp = self.emit_bin(BinaryOperator::ShiftRight, a, sh);
                        self.emit_bin(BinaryOperator::And, tmp, mask_f)
                    };
                    let bk = if k == 0 {
                        self.emit_bin(BinaryOperator::And, b, mask_f)
                    } else {
                        let tmp = self.emit_bin(BinaryOperator::ShiftRight, b, sh);
                        self.emit_bin(BinaryOperator::And, tmp, mask_f)
                    };
                    let prod = self.emit_bin(BinaryOperator::Multiply, ak, bk);
                    dot = if k == 0 {
                        prod
                    } else {
                        self.emit_bin(BinaryOperator::Add, dot, prod)
                    };
                }
                let res = self.emit_add_sat_u32(dot, c, clamp);
                self.store_vgpr_u32(vdst, res);
                true
            }
            // v_fma_mix_f32 (0x20), v_fma_mixlo_f16 (0x21), v_fma_mixhi_f16 (0x22):
            //   op_sel_hi[i]: 0 = f32 source, 1 = f16 source
            //   op_sel[i]:    when f16 source, 0 = lo 16 bits, 1 = hi 16 bits
            //   neg_hi[i]:    abs modifier
            //   neg_lo[i]:    neg modifier
            0x20..=0x22 => {
                let a = self.read_src_mixed_f16_or_f32(
                    src0,
                    literal,
                    (op_sel_hi & 1) != 0,
                    (op_sel & 1) != 0,
                    (neg_hi & 1) != 0,
                    (neg_lo & 1) != 0,
                );
                let b = self.read_src_mixed_f16_or_f32(
                    src1,
                    literal,
                    (op_sel_hi & 2) != 0,
                    (op_sel & 2) != 0,
                    (neg_hi & 2) != 0,
                    (neg_lo & 2) != 0,
                );
                let c = self.read_src_mixed_f16_or_f32(
                    src2,
                    literal,
                    (op_sel_hi & 4) != 0,
                    (op_sel & 4) != 0,
                    (neg_hi & 4) != 0,
                    (neg_lo & 4) != 0,
                );
                let fma_res = self.emit_expr(Expression::Math {
                    fun: MathFunction::Fma,
                    arg: a,
                    arg1: Some(b),
                    arg2: Some(c),
                    arg3: None,
                });
                let out = self.apply_float_out_mods(fma_res, 0, clamp);
                match op {
                    0x20 => self.store_vgpr_f32(vdst, out),
                    0x21 => self.store_vgpr_f16_lo(vdst, out),
                    _ => self.store_vgpr_f16_hi(vdst, out),
                }
                true
            }
            _ => false,
        }
    }

    // -- VINTRP (Fragment attribute interpolation) --

    fn translate_vintrp(&mut self, op: u8, vdst: u8, attr: u8, attrchan: u8) -> bool {
        if !matches!(op, 0..=2) || self.stage != ShaderStage::Fragment {
            return false;
        }
        let Some(arg_idx) = self.frag_in_arg else {
            return false;
        };
        let clamped_attr = attr % MAX_INTER_STAGE_LOCATIONS;
        let Some(&member_idx) = self.frag_attr_member_index.get(&clamped_attr) else {
            return false;
        };
        let frag_in = self.raw_expr(Expression::FunctionArgument(arg_idx));
        let attr_vec = self.emit_expr(Expression::AccessIndex {
            base: frag_in,
            index: member_idx,
        });
        let comp = self.emit_expr(Expression::AccessIndex {
            base: attr_vec,
            index: u32::from(attrchan & 0x3),
        });
        self.store_vgpr_f32(vdst, comp);
        true
    }

    // -- MIMG (2D / 2D-Array / Cube / Cube-Array / 3D sampling, gather4, load & store) --

    #[allow(clippy::too_many_arguments)]
    fn translate_mimg(
        &mut self,
        inst_idx: usize,
        op: u8,
        dmask: u8,
        dim: u8,
        d16: bool,
        nsize: u8,
        vaddr: u8,
        nsa_vaddrs: &[u8; 12],
        vdata: u8,
        srsrc: u8,
        ssamp: u8,
    ) -> bool {
        let Some(layout) = mimg_addr_layout(op) else {
            return false;
        };
        if layout.is_get_lod {
            // WGSL has no textureQueryLod builtin; emit safe mip 0.0 fallback into dst VGPRs per dmask.
            let eff_mask = if dmask == 0 { 0xF } else { dmask };
            let comp_cnt = eff_mask.count_ones();
            let reg_cnt = if d16 { comp_cnt.div_ceil(2) } else { comp_cnt } as u8;
            for dst_offset in 0..reg_cnt {
                let zero = self.lit_f32(0.0);
                self.store_vgpr_offset_f32(vdata, dst_offset, zero);
            }
            return true;
        }
        let inst_dim = if layout.is_store || layout.is_load {
            TexDim::from_storage_mimg_dim(dim)
        } else {
            TexDim::from_mimg_dim(dim)
        };
        let eff_mask = match dmask & 0xF {
            0 => 0xF,
            m => m,
        };
        let load_addr_f32 = |emitter: &mut Self, base_off: u8, delta: u8| -> Handle<Expression> {
            match base_off
                .checked_add(delta)
                .and_then(|idx| mimg_addr_vgpr(vaddr, nsize, nsa_vaddrs, idx))
            {
                Some(reg) => emitter.load_vgpr_f32(reg),
                None => emitter.lit_f32(0.0),
            }
        };

        if layout.is_store {
            if self.stage == ShaderStage::Vertex {
                return false;
            }
            let dispatch = self.inst_storage_tex_dispatches.get(&inst_idx).cloned();
            let first_key = match &dispatch {
                Some(StorageDispatch::TwoWayChoice { keys, .. }) => keys[0],
                Some(StorageDispatch::BoundedIndexed { keys, .. }) => {
                    keys.first().copied().unwrap_or(ResourceKey::RawSlot(srsrc))
                }
                None => self
                    .inst_storage_tex_keys
                    .get(&inst_idx)
                    .copied()
                    .unwrap_or(ResourceKey::RawSlot(srsrc)),
            };
            let Some(&(uav_tex_global, tex_dim)) = self.storage_tex_globals.get(&first_key) else {
                return false;
            };
            let ux = load_addr_f32(self, layout.uv_off, 0);
            let uy = load_addr_f32(self, layout.uv_off, 1);
            let ix = self.bitcast_f32_to_i32(ux);
            let iy = self.bitcast_f32_to_i32(uy);
            let (coord, array_index) = match tex_dim {
                TexDim::D3 => {
                    let iz = if inst_dim == TexDim::D3 {
                        let uz = load_addr_f32(self, layout.uv_off, 2);
                        self.bitcast_f32_to_i32(uz)
                    } else {
                        self.lit_i32(0)
                    };
                    (
                        self.emit_expr(Expression::Compose {
                            ty: self.types.vec3_i32_ty,
                            components: vec![ix, iy, iz],
                        }),
                        None,
                    )
                }
                TexDim::D2Array | TexDim::Cube | TexDim::CubeArray => {
                    let arr = if inst_dim == TexDim::D2Array {
                        let s = load_addr_f32(self, layout.uv_off, 2);
                        self.bitcast_f32_to_i32(s)
                    } else {
                        self.lit_i32(0)
                    };
                    (
                        self.emit_expr(Expression::Compose {
                            ty: self.types.vec2_i32_ty,
                            components: vec![ix, iy],
                        }),
                        Some(arr),
                    )
                }
                TexDim::D2 => (
                    self.emit_expr(Expression::Compose {
                        ty: self.types.vec2_i32_ty,
                        components: vec![ix, iy],
                    }),
                    None,
                ),
            };

            let mut src_offset = 0u8;
            let mut comps = Vec::with_capacity(4);
            let mut cached_d16_pair: Option<(u8, Handle<Expression>)> = None;
            for ch in 0..4u32 {
                if (eff_mask & (1 << ch)) != 0 {
                    if d16 {
                        let reg_off = src_offset / 2;
                        let lane = u32::from(src_offset % 2);
                        if checked_vgpr_reg(vdata, reg_off).is_some() {
                            let pair = match cached_d16_pair {
                                Some((cached_off, pair)) if cached_off == reg_off => pair,
                                _ => {
                                    let raw_f = self.load_vgpr_offset_f32(vdata, reg_off);
                                    let raw_u = self.bitcast_f32_to_u32(raw_f);
                                    let unpacked = self.emit_expr(Expression::Math {
                                        fun: MathFunction::Unpack2x16float,
                                        arg: raw_u,
                                        arg1: None,
                                        arg2: None,
                                        arg3: None,
                                    });
                                    cached_d16_pair = Some((reg_off, unpacked));
                                    unpacked
                                }
                            };
                            comps.push(self.emit_expr(Expression::AccessIndex {
                                base: pair,
                                index: lane,
                            }));
                        } else {
                            comps.push(self.lit_f32(0.0));
                        }
                    } else {
                        comps.push(self.load_vgpr_offset_f32(vdata, src_offset));
                    }
                    src_offset = src_offset.saturating_add(1);
                } else {
                    comps.push(self.lit_f32(if ch == 3 { 1.0 } else { 0.0 }));
                }
            }
            let val = self.emit_expr(Expression::Compose {
                ty: self.types.vec4_f32_ty,
                components: comps,
            });
            match dispatch {
                Some(StorageDispatch::TwoWayChoice { choice_id, keys })
                    if self.choice_sel_locals.get(choice_id).is_some()
                        && self.storage_tex_globals.contains_key(&keys[0])
                        && self.storage_tex_globals.contains_key(&keys[1]) =>
                {
                    let sel_local = self.choice_sel_locals[choice_id];
                    let sel = self.load_local(sel_local);
                    let zero = self.lit_u32(0);
                    let cond = self.emit_bin(BinaryOperator::Equal, sel, zero);
                    let g0 = self.storage_tex_globals[&keys[0]].0;
                    let g1 = self.storage_tex_globals[&keys[1]].0;
                    let img0 = self.raw_expr(Expression::GlobalVariable(g0));
                    let img1 = self.raw_expr(Expression::GlobalVariable(g1));
                    let mut accept = naga::Block::new();
                    accept.push(
                        Statement::ImageStore {
                            image: img0,
                            coordinate: coord,
                            array_index,
                            value: val,
                        },
                        Span::UNDEFINED,
                    );
                    let mut reject = naga::Block::new();
                    reject.push(
                        Statement::ImageStore {
                            image: img1,
                            coordinate: coord,
                            array_index,
                            value: val,
                        },
                        Span::UNDEFINED,
                    );
                    self.func.body.push(
                        Statement::If {
                            condition: cond,
                            accept,
                            reject,
                        },
                        Span::UNDEFINED,
                    );
                }
                Some(StorageDispatch::BoundedIndexed { choice_id, keys })
                    if self.choice_sel_locals.get(choice_id).is_some() && !keys.is_empty() =>
                {
                    let sel_local = self.choice_sel_locals[choice_id];
                    let selector = self.load_local(sel_local);
                    let mut cases = Vec::with_capacity(keys.len() + 1);
                    for (k, key) in keys.iter().enumerate() {
                        let mut case_body = naga::Block::new();
                        if let Some(&(g, _)) = self.storage_tex_globals.get(key) {
                            let img = self.raw_expr(Expression::GlobalVariable(g));
                            case_body.push(
                                Statement::ImageStore {
                                    image: img,
                                    coordinate: coord,
                                    array_index,
                                    value: val,
                                },
                                Span::UNDEFINED,
                            );
                        }
                        cases.push(SwitchCase {
                            value: SwitchValue::U32(k as u32),
                            body: case_body,
                            fall_through: false,
                        });
                    }
                    cases.push(SwitchCase {
                        value: SwitchValue::Default,
                        body: naga::Block::new(),
                        fall_through: false,
                    });
                    self.func.body.push(
                        Statement::Switch { selector, cases },
                        Span::UNDEFINED,
                    );
                }
                _ => {
                    let image = self.raw_expr(Expression::GlobalVariable(uav_tex_global));
                    self.func.body.push(
                        Statement::ImageStore {
                            image,
                            coordinate: coord,
                            array_index,
                            value: val,
                        },
                        Span::UNDEFINED,
                    );
                }
            }
            return true;
        }

        let key = self
            .inst_tex_keys
            .get(&inst_idx)
            .copied()
            .unwrap_or(ResourceKey::RawSlot(srsrc));
        let Some(&(tex_global, tex_dim, tex_is_depth)) = self.tex_globals.get(&key) else {
            return false;
        };
        let image = self.raw_expr(Expression::GlobalVariable(tex_global));
        let extra_grad_shift = if layout.grad_off.is_some() && inst_dim.has_3d_grad() {
            2u8
        } else {
            0u8
        };
        let lod_shift = extra_grad_shift.saturating_add(inst_dim.extra_coord_vgprs());

        let sampled = if layout.is_load {
            // image_load / image_load_mip: coordinate is vec2<i32> (2D/2DArray) or
            // vec3<i32> (3D), array_index is Some(i32) iff D2Array, and level is Some(i32).
            let ux = load_addr_f32(self, layout.uv_off, 0);
            let uy = load_addr_f32(self, layout.uv_off, 1);
            let ix = self.bitcast_f32_to_i32(ux);
            let iy = self.bitcast_f32_to_i32(uy);
            let (coord, array_index) = match tex_dim {
                TexDim::D3 => {
                    let iz = if inst_dim == TexDim::D3 {
                        let uz = load_addr_f32(self, layout.uv_off, 2);
                        self.bitcast_f32_to_i32(uz)
                    } else {
                        self.lit_i32(0)
                    };
                    (
                        self.emit_expr(Expression::Compose {
                            ty: self.types.vec3_i32_ty,
                            components: vec![ix, iy, iz],
                        }),
                        None,
                    )
                }
                TexDim::D2Array | TexDim::Cube | TexDim::CubeArray => {
                    let arr = if inst_dim == TexDim::D2Array {
                        let s = load_addr_f32(self, layout.uv_off, 2);
                        self.bitcast_f32_to_i32(s)
                    } else {
                        self.lit_i32(0)
                    };
                    (
                        self.emit_expr(Expression::Compose {
                            ty: self.types.vec2_i32_ty,
                            components: vec![ix, iy],
                        }),
                        Some(arr),
                    )
                }
                TexDim::D2 => (
                    self.emit_expr(Expression::Compose {
                        ty: self.types.vec2_i32_ty,
                        components: vec![ix, iy],
                    }),
                    None,
                ),
            };
            let level = if let Some(lod_off) = layout.lod_off {
                let ml = load_addr_f32(self, lod_off, lod_shift);
                Some(self.bitcast_f32_to_i32(ml))
            } else {
                Some(self.lit_i32(0))
            };
            let loaded = self.emit_expr(Expression::ImageLoad {
                image,
                coordinate: coord,
                array_index,
                sample: None,
                level,
            });
            if tex_is_depth {
                self.emit_expr(Expression::Splat {
                    size: VectorSize::Quad,
                    value: loaded,
                })
            } else {
                loaded
            }
        } else {
            // image_sample* / image_gather4* across 2D, 2D-Array, Cube, Cube-Array, and 3D
            let skey = self
                .inst_samp_keys
                .get(&inst_idx)
                .copied()
                .unwrap_or(ResourceKey::RawSlot(ssamp));
            let Some(&(samp_global, samp_is_cmp)) = self.samp_globals.get(&skey) else {
                return false;
            };
            let sampler = self.raw_expr(Expression::GlobalVariable(samp_global));
            // For 3D / Cube / CubeArray `image_sample_d*`, GFX10.3 packs 6 gradient VGPRs
            // (dudx,dvdx,dwdx,dudy,dvdy,dwdy) instead of 4 before coords, shifting `uv_off` by +2.
            let uv_base = layout.uv_off.checked_add(extra_grad_shift);
            let u = match uv_base {
                Some(base) => load_addr_f32(self, base, 0),
                None => self.lit_f32(0.0),
            };
            let v = match uv_base {
                Some(base) => load_addr_f32(self, base, 1),
                None => self.lit_f32(0.0),
            };
            let (mut coord, array_index) = match tex_dim {
                TexDim::D3 | TexDim::Cube => {
                    let w = if matches!(inst_dim, TexDim::D3 | TexDim::Cube | TexDim::CubeArray) {
                        match uv_base {
                            Some(base) => load_addr_f32(self, base, 2),
                            None => self.lit_f32(0.0),
                        }
                    } else {
                        self.lit_f32(0.0)
                    };
                    (
                        self.emit_expr(Expression::Compose {
                            ty: self.types.vec3_f32_ty,
                            components: vec![u, v, w],
                        }),
                        None,
                    )
                }
                TexDim::CubeArray => {
                    let w = if matches!(inst_dim, TexDim::D3 | TexDim::Cube | TexDim::CubeArray) {
                        match uv_base {
                            Some(base) => load_addr_f32(self, base, 2),
                            None => self.lit_f32(0.0),
                        }
                    } else {
                        self.lit_f32(0.0)
                    };
                    let arr = if inst_dim == TexDim::CubeArray {
                        let s = match uv_base {
                            Some(base) => load_addr_f32(self, base, 3),
                            None => self.lit_f32(0.0),
                        };
                        self.emit_expr(Expression::As {
                            expr: s,
                            kind: ScalarKind::Sint,
                            convert: Some(4),
                        })
                    } else {
                        self.lit_i32(0)
                    };
                    (
                        self.emit_expr(Expression::Compose {
                            ty: self.types.vec3_f32_ty,
                            components: vec![u, v, w],
                        }),
                        Some(arr),
                    )
                }
                TexDim::D2Array => {
                    let arr = if matches!(inst_dim, TexDim::D2Array | TexDim::D3 | TexDim::Cube) {
                        let s = match uv_base {
                            Some(base) => load_addr_f32(self, base, 2),
                            None => self.lit_f32(0.0),
                        };
                        self.emit_expr(Expression::As {
                            expr: s,
                            kind: ScalarKind::Sint,
                            convert: Some(4),
                        })
                    } else {
                        self.lit_i32(0)
                    };
                    (
                        self.emit_expr(Expression::Compose {
                            ty: self.types.vec2_f32_ty,
                            components: vec![u, v],
                        }),
                        Some(arr),
                    )
                }
                TexDim::D2 => (
                    self.emit_expr(Expression::Compose {
                        ty: self.types.vec2_f32_ty,
                        components: vec![u, v],
                    }),
                    None,
                ),
            };

            // Apply GFX10.3 packed 6-bit signed texel offsets (`_o` variants) via texel-space UV shift
            // (`coord + vecN<f32>(dx, dy[, dz]) / max(vecN<f32>(textureDimensions(tex)), 1.0)`),
            // which handles both constant and dynamic VGPR offsets cleanly under baseline WGSL.
            if let Some(off_idx) = layout.offset_off
                && tex_dim.supports_texel_offset()
            {
                let raw_off_f = load_addr_f32(self, off_idx, 0);
                let raw_off_u = self.bitcast_f32_to_u32(raw_off_f);
                let sh26 = self.lit_u32(26);
                let sh18 = self.lit_u32(18);
                let dx_l = self.emit_bin(BinaryOperator::ShiftLeft, raw_off_u, sh26);
                let dx_i = self.bitcast_u32_to_i32(dx_l);
                let dx_s = self.emit_bin(BinaryOperator::ShiftRight, dx_i, sh26);
                let dx_f = self.emit_expr(Expression::As {
                    expr: dx_s,
                    kind: ScalarKind::Float,
                    convert: Some(4),
                });
                let dy_l = self.emit_bin(BinaryOperator::ShiftLeft, raw_off_u, sh18);
                let dy_i = self.bitcast_u32_to_i32(dy_l);
                let dy_s = self.emit_bin(BinaryOperator::ShiftRight, dy_i, sh26);
                let dy_f = self.emit_expr(Expression::As {
                    expr: dy_s,
                    kind: ScalarKind::Float,
                    convert: Some(4),
                });
                let dims_u = self.emit_expr(Expression::ImageQuery {
                    image,
                    query: ImageQuery::Size { level: None },
                });
                let dims_f = self.emit_expr(Expression::As {
                    expr: dims_u,
                    kind: ScalarKind::Float,
                    convert: Some(4),
                });
                let one = self.lit_f32(1.0);
                let (off_vec, one_vec) = if tex_dim == TexDim::D3 {
                    let sh10 = self.lit_u32(10);
                    let dz_l = self.emit_bin(BinaryOperator::ShiftLeft, raw_off_u, sh10);
                    let dz_i = self.bitcast_u32_to_i32(dz_l);
                    let dz_s = self.emit_bin(BinaryOperator::ShiftRight, dz_i, sh26);
                    let dz_f = self.emit_expr(Expression::As {
                        expr: dz_s,
                        kind: ScalarKind::Float,
                        convert: Some(4),
                    });
                    (
                        self.emit_expr(Expression::Compose {
                            ty: self.types.vec3_f32_ty,
                            components: vec![dx_f, dy_f, dz_f],
                        }),
                        self.emit_expr(Expression::Splat {
                            size: VectorSize::Tri,
                            value: one,
                        }),
                    )
                } else {
                    (
                        self.emit_expr(Expression::Compose {
                            ty: self.types.vec2_f32_ty,
                            components: vec![dx_f, dy_f],
                        }),
                        self.emit_expr(Expression::Splat {
                            size: VectorSize::Bi,
                            value: one,
                        }),
                    )
                };
                let safe_dims = self.emit_expr(Expression::Math {
                    fun: MathFunction::Max,
                    arg: dims_f,
                    arg1: Some(one_vec),
                    arg2: None,
                    arg3: None,
                });
                let uv_delta = self.emit_bin(BinaryOperator::Divide, off_vec, safe_dims);
                coord = self.emit_bin(BinaryOperator::Add, coord, uv_delta);
            }

            let allow_implicit_deriv = self.stage == ShaderStage::Fragment && !self.in_nonuniform_cf();
            let hw_depth_compare = layout.compare_off.is_some() && tex_is_depth && samp_is_cmp;

            if layout.is_gather4 {
                let gather_comp = gather_component_from_dmask(dmask);
                if hw_depth_compare {
                    // Hardware depth comparison gather: `textureGatherCompare` -> vec4<f32>.
                    let z_ref = load_addr_f32(self, layout.compare_off.unwrap_or(0), 0);
                    self.emit_expr(Expression::ImageSample {
                        image,
                        sampler,
                        gather: Some(SwizzleComponent::X),
                        coordinate: coord,
                        array_index,
                        offset: None,
                        level: SampleLevel::Zero,
                        depth_ref: Some(z_ref),
                        clamp_to_edge: false,
                    })
                } else if tex_dim.supports_gather() {
                    // Regular `textureGather(component, tex, sampler, ...)` -> vec4<f32>.
                    let gathered = self.emit_expr(Expression::ImageSample {
                        image,
                        sampler,
                        gather: Some(gather_comp),
                        coordinate: coord,
                        array_index,
                        offset: None,
                        level: SampleLevel::Zero,
                        depth_ref: None,
                        clamp_to_edge: false,
                    });
                    if let Some(cmp_off) = layout.compare_off {
                        // Mixed-use texture/sampler fallback: compare all 4 gathered depth taps against z_ref.
                        let z_ref = load_addr_f32(self, cmp_off, 0);
                        let one = self.lit_f32(1.0);
                        let zero = self.lit_f32(0.0);
                        let mut cmp_comps = Vec::with_capacity(4);
                        for ch in 0..4u32 {
                            let tap = self.emit_expr(Expression::AccessIndex {
                                base: gathered,
                                index: ch,
                            });
                            let passed = self.emit_bin(BinaryOperator::LessEqual, z_ref, tap);
                            let res = self.emit_select(passed, one, zero);
                            cmp_comps.push(res);
                        }
                        self.emit_expr(Expression::Compose {
                            ty: self.types.vec4_f32_ty,
                            components: cmp_comps,
                        })
                    } else {
                        gathered
                    }
                } else {
                    // WGSL has no `textureGather` on `texture_3d`; fall back to `textureSampleLevel(..., 0.0)`
                    // and splat the selected component (or compare result) across 4 lanes.
                    let zero_lod = self.lit_f32(0.0);
                    let raw_sample = self.emit_expr(Expression::ImageSample {
                        image,
                        sampler,
                        gather: None,
                        coordinate: coord,
                        array_index: None,
                        offset: None,
                        level: SampleLevel::Exact(zero_lod),
                        depth_ref: None,
                        clamp_to_edge: false,
                    });
                    let ch_idx = match gather_comp {
                        SwizzleComponent::X => 0,
                        SwizzleComponent::Y => 1,
                        SwizzleComponent::Z => 2,
                        SwizzleComponent::W => 3,
                    };
                    let val = self.emit_expr(Expression::AccessIndex {
                        base: raw_sample,
                        index: ch_idx,
                    });
                    let lane_val = if let Some(cmp_off) = layout.compare_off {
                        let z_ref = load_addr_f32(self, cmp_off, 0);
                        let passed = self.emit_bin(BinaryOperator::LessEqual, z_ref, val);
                        let one = self.lit_f32(1.0);
                        let zero = self.lit_f32(0.0);
                        self.emit_select(passed, one, zero)
                    } else {
                        val
                    };
                    self.emit_expr(Expression::Splat {
                        size: VectorSize::Quad,
                        value: lane_val,
                    })
                }
            } else if hw_depth_compare {
                // Hardware shadow PCF on `texture_depth_*` + `sampler_comparison`:
                // WGSL allows `textureSampleCompare` (`Auto`, fragment uniform CF) or
                // `textureSampleCompareLevel` (`Zero`, all stages & non-uniform CF; no arbitrary lod/grad/bias).
                let z_ref = load_addr_f32(self, layout.compare_off.unwrap_or(0), 0);
                let cmp_level = if layout.is_zero_lod
                    || layout.lod_off.is_some()
                    || layout.grad_off.is_some()
                    || !allow_implicit_deriv
                {
                    SampleLevel::Zero
                } else {
                    SampleLevel::Auto
                };
                let cmp_f = self.emit_expr(Expression::ImageSample {
                    image,
                    sampler,
                    gather: None,
                    coordinate: coord,
                    array_index,
                    offset: None,
                    level: cmp_level,
                    depth_ref: Some(z_ref),
                    clamp_to_edge: false,
                });
                self.emit_expr(Expression::Splat {
                    size: VectorSize::Quad,
                    value: cmp_f,
                })
            } else {
                // Regular sampled texture (`2d`, `2d_array`, `3d`, `cube`, `cube_array`):
                // WGSL only permits implicit-derivative `textureSample` / `textureSampleBias`
                // in Fragment shaders within uniform control flow; Vertex, Compute, and non-uniform
                // Fragment branches must use explicit `textureSampleLevel` or `textureSampleGrad`.
                let level = if layout.is_zero_lod {
                    SampleLevel::Exact(self.lit_f32(0.0))
                } else if let Some(lod_off) = layout.lod_off {
                    let lod = load_addr_f32(self, lod_off, lod_shift);
                    SampleLevel::Exact(lod)
                } else if let Some(grad_off) = layout.grad_off {
                    let dy_base = if inst_dim.has_3d_grad() { 3u8 } else { 2u8 };
                    if tex_dim.has_3d_grad() {
                        let dudx = load_addr_f32(self, grad_off, 0);
                        let dvdx = load_addr_f32(self, grad_off, 1);
                        let dwdx = if inst_dim.has_3d_grad() {
                            load_addr_f32(self, grad_off, 2)
                        } else {
                            self.lit_f32(0.0)
                        };
                        let dudy = load_addr_f32(self, grad_off, dy_base);
                        let dvdy = load_addr_f32(self, grad_off, dy_base.saturating_add(1));
                        let dwdy = if inst_dim.has_3d_grad() {
                            load_addr_f32(self, grad_off, dy_base.saturating_add(2))
                        } else {
                            self.lit_f32(0.0)
                        };
                        let x = self.emit_expr(Expression::Compose {
                            ty: self.types.vec3_f32_ty,
                            components: vec![dudx, dvdx, dwdx],
                        });
                        let y = self.emit_expr(Expression::Compose {
                            ty: self.types.vec3_f32_ty,
                            components: vec![dudy, dvdy, dwdy],
                        });
                        SampleLevel::Gradient { x, y }
                    } else {
                        let dudx = load_addr_f32(self, grad_off, 0);
                        let dvdx = load_addr_f32(self, grad_off, 1);
                        let dudy = load_addr_f32(self, grad_off, dy_base);
                        let dvdy = load_addr_f32(self, grad_off, dy_base.saturating_add(1));
                        let x = self.emit_expr(Expression::Compose {
                            ty: self.types.vec2_f32_ty,
                            components: vec![dudx, dvdx],
                        });
                        let y = self.emit_expr(Expression::Compose {
                            ty: self.types.vec2_f32_ty,
                            components: vec![dudy, dvdy],
                        });
                        SampleLevel::Gradient { x, y }
                    }
                } else if let Some(bias_off) = layout.bias_off {
                    if allow_implicit_deriv {
                        let raw_bias = load_addr_f32(self, bias_off, 0);
                        // WGSL requires `textureSampleBias` bias within [-16.0, 15.99].
                        let bias_lo = self.lit_f32(-16.0);
                        let bias_hi = self.lit_f32(15.99);
                        let clamped_bias = self.emit_expr(Expression::Math {
                            fun: MathFunction::Clamp,
                            arg: raw_bias,
                            arg1: Some(bias_lo),
                            arg2: Some(bias_hi),
                            arg3: None,
                        });
                        SampleLevel::Bias(clamped_bias)
                    } else {
                        SampleLevel::Exact(self.lit_f32(0.0))
                    }
                } else if allow_implicit_deriv {
                    SampleLevel::Auto
                } else {
                    SampleLevel::Exact(self.lit_f32(0.0))
                };

                let raw_sample = self.emit_expr(Expression::ImageSample {
                    image,
                    sampler,
                    gather: None,
                    coordinate: coord,
                    array_index,
                    offset: None,
                    level,
                    depth_ref: None,
                    clamp_to_edge: false,
                });

                if let Some(cmp_off) = layout.compare_off {
                    // Mixed-use texture/sampler fallback: compare z_ref <= tex.x, splatted to vec4<f32>.
                    let z_ref = load_addr_f32(self, cmp_off, 0);
                    let depth_val = self.emit_expr(Expression::AccessIndex {
                        base: raw_sample,
                        index: 0,
                    });
                    let passed = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::LessEqual,
                        left: z_ref,
                        right: depth_val,
                    });
                    let one = self.lit_f32(1.0);
                    let zero = self.lit_f32(0.0);
                    let cmp_f = self.emit_expr(Expression::Select {
                        condition: passed,
                        accept: one,
                        reject: zero,
                    });
                    self.emit_expr(Expression::Splat {
                        size: VectorSize::Quad,
                        value: cmp_f,
                    })
                } else {
                    raw_sample
                }
            }
        };

        // For `image_gather4*`, `dmask` selects the gathered channel and hardware always writes all 4 taps.
        let out_mask = if layout.is_gather4 { 0xF } else { eff_mask };

        if d16 {
            // GFX10.3 packed 16-bit MIMG return: pack enabled output channels in LSB-to-MSB order
            // into consecutive 32-bit VGPRs (2 f16 channels per VGPR via WGSL `pack2x16float`).
            let mut selected_channels = [0u32; 4];
            let mut selected_len = 0usize;
            for ch in 0..4u32 {
                if (out_mask & (1 << ch)) != 0 {
                    selected_channels[selected_len] = ch;
                    selected_len += 1;
                }
            }
            for (pair_idx, chunk) in selected_channels[..selected_len].chunks(2).enumerate() {
                let dst_offset = pair_idx as u8;
                if checked_vgpr_reg(vdata, dst_offset).is_none() {
                    break;
                }
                let lo = self.emit_expr(Expression::AccessIndex {
                    base: sampled,
                    index: chunk[0],
                });
                let hi = if let Some(&hi_ch) = chunk.get(1) {
                    self.emit_expr(Expression::AccessIndex {
                        base: sampled,
                        index: hi_ch,
                    })
                } else {
                    self.lit_f32(0.0)
                };
                let pair = self.emit_expr(Expression::Compose {
                    ty: self.types.vec2_f32_ty,
                    components: vec![lo, hi],
                });
                let packed = self.emit_expr(Expression::Math {
                    fun: MathFunction::Pack2x16float,
                    arg: pair,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                self.store_vgpr_offset_u32(vdata, dst_offset, packed);
            }
        } else {
            let mut dst_offset = 0u8;
            for ch in 0..4u32 {
                if (out_mask & (1 << ch)) != 0 {
                    if checked_vgpr_reg(vdata, dst_offset).is_some() {
                        let comp = self.emit_expr(Expression::AccessIndex {
                            base: sampled,
                            index: ch,
                        });
                        self.store_vgpr_offset_f32(vdata, dst_offset, comp);
                    }
                    dst_offset = dst_offset.saturating_add(1);
                }
            }
        }
        true
    }

    // -- MUBUF / MTBUF vertex attribute fetch & storage buffer load/store helpers --

    #[allow(clippy::too_many_arguments)]
    fn translate_mubuf_or_mtbuf(
        &mut self,
        inst_idx: usize,
        is_mtbuf: bool,
        op: u8,
        format: u8,
        byte_offset: u16,
        offen: bool,
        idxen: bool,
        vaddr: u8,
        vdata: u8,
        srsrc: u8,
        soffset: u8,
    ) -> bool {
        if self.stage == ShaderStage::Vertex && !self.vertex_storage_buf_insts.contains(&inst_idx) {
            let vb_slot = self.vertex_fetch_vb_slots.get(&inst_idx).copied().unwrap_or(0);
            return self.translate_vertex_buf_fetch(
                vb_slot,
                is_mtbuf,
                op,
                format,
                byte_offset,
                vdata,
            );
        }
        self.translate_storage_buf_op(
            inst_idx,
            is_mtbuf,
            op,
            byte_offset,
            offen,
            idxen,
            vaddr,
            vdata,
            srsrc,
            soffset,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn translate_storage_buf_op(
        &mut self,
        inst_idx: usize,
        is_mtbuf: bool,
        op: u8,
        byte_offset: u16,
        offen: bool,
        idxen: bool,
        vaddr: u8,
        vdata: u8,
        srsrc: u8,
        soffset: u8,
    ) -> bool {
        let Some(buf_op) = (if is_mtbuf {
            mtbuf_storage_op(op)
        } else {
            mubuf_storage_op(op)
        }) else {
            return false;
        };
        let buf_dispatch = if buf_op.is_store() {
            self.inst_storage_buf_dispatches.get(&inst_idx).cloned()
        } else {
            None
        };
        let key = match &buf_dispatch {
            Some(StorageDispatch::TwoWayChoice { keys, .. }) => keys[0],
            Some(StorageDispatch::BoundedIndexed { keys, .. }) => {
                keys.first().copied().unwrap_or(ResourceKey::RawSlot(srsrc))
            }
            None => self
                .inst_storage_buf_keys
                .get(&inst_idx)
                .copied()
                .unwrap_or(ResourceKey::RawSlot(srsrc)),
        };
        let Some(&(buf_global, writable)) = self.storage_buf_globals.get(&key) else {
            return false;
        };
        if buf_op.is_store() && !writable {
            return false;
        }

        // Compute effective byte address: vaddr_contrib + soffset + imm_offset
        let mut byte_addr: Option<Handle<Expression>> = None;
        let stride = buf_op.elem_stride_bytes();
        if offen && idxen {
            let idx_f = self.load_vgpr_f32(vaddr);
            let idx_u = self.bitcast_f32_to_u32(idx_f);
            let stride_lit = self.lit_u32(stride);
            let idx_bytes = self.emit_expr(Expression::Binary {
                op: BinaryOperator::Multiply,
                left: idx_u,
                right: stride_lit,
            });
            let off_f = self.load_vgpr_offset_f32(vaddr, 1);
            let off_u = self.bitcast_f32_to_u32(off_f);
            let sum = self.emit_expr(Expression::Binary {
                op: BinaryOperator::Add,
                left: idx_bytes,
                right: off_u,
            });
            byte_addr = Some(sum);
        } else if offen {
            let off_f = self.load_vgpr_f32(vaddr);
            byte_addr = Some(self.bitcast_f32_to_u32(off_f));
        } else if idxen {
            let idx_f = self.load_vgpr_f32(vaddr);
            let idx_u = self.bitcast_f32_to_u32(idx_f);
            if stride == 1 {
                byte_addr = Some(idx_u);
            } else {
                let stride_lit = self.lit_u32(stride);
                byte_addr = Some(self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Multiply,
                    left: idx_u,
                    right: stride_lit,
                }));
            }
        }

        let soff_expr = if soffset <= 105 {
            Some(self.load_sgpr_u32(soffset))
        } else if (129..=208).contains(&soffset) {
            Some(self.read_src_u32(u16::from(soffset), None))
        } else {
            None
        };
        if let Some(se) = soff_expr {
            byte_addr = Some(match byte_addr {
                Some(cur) => self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Add,
                    left: cur,
                    right: se,
                }),
                None => se,
            });
        }

        if byte_offset != 0 {
            let imm = self.lit_u32(u32::from(byte_offset));
            byte_addr = Some(match byte_addr {
                Some(cur) => self.emit_expr(Expression::Binary {
                    op: BinaryOperator::Add,
                    left: cur,
                    right: imm,
                }),
                None => imm,
            });
        }

        let eff_byte_addr = byte_addr.unwrap_or_else(|| self.lit_u32(0));
        let two = self.lit_u32(2);
        let base_dword = self.emit_expr(Expression::Binary {
            op: BinaryOperator::ShiftRight,
            left: eff_byte_addr,
            right: two,
        });

        let buf_ptr = self.raw_expr(Expression::GlobalVariable(buf_global));
        let buf_len = self.emit_expr(Expression::ArrayLength(buf_ptr));
        let one = self.lit_u32(1);
        let clamped_len = self.emit_expr(Expression::Math {
            fun: MathFunction::Max,
            arg: buf_len,
            arg1: Some(one),
            arg2: None,
            arg3: None,
        });
        let max_idx = self.emit_expr(Expression::Binary {
            op: BinaryOperator::Subtract,
            left: clamped_len,
            right: one,
        });

        match buf_op {
            StorageBufOpKind::LoadUbyte | StorageBufOpKind::LoadSbyte => {
                let safe_idx = self.emit_expr(Expression::Math {
                    fun: MathFunction::Min,
                    arg: base_dword,
                    arg1: Some(max_idx),
                    arg2: None,
                    arg3: None,
                });
                let elem_ptr = self.emit_expr(Expression::Access {
                    base: buf_ptr,
                    index: safe_idx,
                });
                let word = self.emit_expr(Expression::Load { pointer: elem_ptr });
                let mask3 = self.lit_u32(3);
                let byte_lane = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: eff_byte_addr,
                    right: mask3,
                });
                let three = self.lit_u32(3);
                let bit_shift = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftLeft,
                    left: byte_lane,
                    right: three,
                });
                let shifted = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftRight,
                    left: word,
                    right: bit_shift,
                });
                if buf_op == StorageBufOpKind::LoadUbyte {
                    let mask_ff = self.lit_u32(0xFF);
                    let val = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::And,
                        left: shifted,
                        right: mask_ff,
                    });
                    self.store_vgpr_u32(vdata, val);
                } else {
                    let s_raw = self.bitcast_u32_to_i32(shifted);
                    let sh24 = self.lit_u32(24);
                    let shl = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::ShiftLeft,
                        left: s_raw,
                        right: sh24,
                    });
                    let sext = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::ShiftRight,
                        left: shl,
                        right: sh24,
                    });
                    self.store_vgpr_i32(vdata, sext);
                }
                true
            }
            StorageBufOpKind::LoadUshort | StorageBufOpKind::LoadSshort => {
                let safe_idx = self.emit_expr(Expression::Math {
                    fun: MathFunction::Min,
                    arg: base_dword,
                    arg1: Some(max_idx),
                    arg2: None,
                    arg3: None,
                });
                let elem_ptr = self.emit_expr(Expression::Access {
                    base: buf_ptr,
                    index: safe_idx,
                });
                let word = self.emit_expr(Expression::Load { pointer: elem_ptr });
                let mask2 = self.lit_u32(2);
                let half_lane = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::And,
                    left: eff_byte_addr,
                    right: mask2,
                });
                let three = self.lit_u32(3);
                let bit_shift = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftLeft,
                    left: half_lane,
                    right: three,
                });
                let shifted = self.emit_expr(Expression::Binary {
                    op: BinaryOperator::ShiftRight,
                    left: word,
                    right: bit_shift,
                });
                if buf_op == StorageBufOpKind::LoadUshort {
                    let mask_ffff = self.lit_u32(0xFFFF);
                    let val = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::And,
                        left: shifted,
                        right: mask_ffff,
                    });
                    self.store_vgpr_u32(vdata, val);
                } else {
                    let s_raw = self.bitcast_u32_to_i32(shifted);
                    let sh16 = self.lit_u32(16);
                    let shl = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::ShiftLeft,
                        left: s_raw,
                        right: sh16,
                    });
                    let sext = self.emit_expr(Expression::Binary {
                        op: BinaryOperator::ShiftRight,
                        left: shl,
                        right: sh16,
                    });
                    self.store_vgpr_i32(vdata, sext);
                }
                true
            }
            StorageBufOpKind::LoadDwords(comps) => {
                let mut loaded = Vec::with_capacity(usize::from(comps));
                for k in 0..comps {
                    let idx_k = if k == 0 {
                        base_dword
                    } else {
                        let k_lit = self.lit_u32(u32::from(k));
                        self.emit_expr(Expression::Binary {
                            op: BinaryOperator::Add,
                            left: base_dword,
                            right: k_lit,
                        })
                    };
                    let safe_idx = self.emit_expr(Expression::Math {
                        fun: MathFunction::Min,
                        arg: idx_k,
                        arg1: Some(max_idx),
                        arg2: None,
                        arg3: None,
                    });
                    let elem_ptr = self.emit_expr(Expression::Access {
                        base: buf_ptr,
                        index: safe_idx,
                    });
                    loaded.push(self.emit_expr(Expression::Load { pointer: elem_ptr }));
                }
                for (k, word) in loaded.into_iter().enumerate() {
                    self.store_vgpr_offset_u32(vdata, k as u8, word);
                }
                true
            }
            StorageBufOpKind::StoreDwords(comps) => {
                if let Some(StorageDispatch::TwoWayChoice { choice_id, keys }) = buf_dispatch
                    && let Some(&sel_local) = self.choice_sel_locals.get(choice_id)
                    && let (Some(&(g0, true)), Some(&(g1, true))) = (
                        self.storage_buf_globals.get(&keys[0]),
                        self.storage_buf_globals.get(&keys[1]),
                    )
                {
                    let mut vals = Vec::with_capacity(usize::from(comps));
                    for k in 0..comps {
                        let vf = self.load_vgpr_offset_f32(vdata, k);
                        vals.push(self.bitcast_f32_to_u32(vf));
                    }
                    let sel = self.load_local(sel_local);
                    let zero = self.lit_u32(0);
                    let cond = self.emit_bin(BinaryOperator::Equal, sel, zero);
                    let emit_arm = |s: &mut Self, g: Handle<GlobalVariable>| {
                        let ptr = s.raw_expr(Expression::GlobalVariable(g));
                        let len = s.emit_expr(Expression::ArrayLength(ptr));
                        let one_l = s.lit_u32(1);
                        let cl = s.emit_expr(Expression::Math {
                            fun: MathFunction::Max,
                            arg: len,
                            arg1: Some(one_l),
                            arg2: None,
                            arg3: None,
                        });
                        let max_i = s.emit_expr(Expression::Binary {
                            op: BinaryOperator::Subtract,
                            left: cl,
                            right: one_l,
                        });
                        for (k, &vu) in vals.iter().enumerate() {
                            let idx_k = if k == 0 {
                                base_dword
                            } else {
                                let k_lit = s.lit_u32(k as u32);
                                s.emit_expr(Expression::Binary {
                                    op: BinaryOperator::Add,
                                    left: base_dword,
                                    right: k_lit,
                                })
                            };
                            let safe_idx = s.emit_expr(Expression::Math {
                                fun: MathFunction::Min,
                                arg: idx_k,
                                arg1: Some(max_i),
                                arg2: None,
                                arg3: None,
                            });
                            let elem_ptr = s.emit_expr(Expression::Access {
                                base: ptr,
                                index: safe_idx,
                            });
                            s.func.body.push(
                                Statement::Store {
                                    pointer: elem_ptr,
                                    value: vu,
                                },
                                Span::UNDEFINED,
                            );
                        }
                    };
                    let accept = self.lower_nested(|s| emit_arm(s, g0));
                    let reject = self.lower_nested(|s| emit_arm(s, g1));
                    self.func.body.push(
                        Statement::If {
                            condition: cond,
                            accept,
                            reject,
                        },
                        Span::UNDEFINED,
                    );
                    return true;
                }
                for k in 0..comps {
                    let idx_k = if k == 0 {
                        base_dword
                    } else {
                        let k_lit = self.lit_u32(u32::from(k));
                        self.emit_expr(Expression::Binary {
                            op: BinaryOperator::Add,
                            left: base_dword,
                            right: k_lit,
                        })
                    };
                    let safe_idx = self.emit_expr(Expression::Math {
                        fun: MathFunction::Min,
                        arg: idx_k,
                        arg1: Some(max_idx),
                        arg2: None,
                        arg3: None,
                    });
                    let elem_ptr = self.emit_expr(Expression::Access {
                        base: buf_ptr,
                        index: safe_idx,
                    });
                    let vf = self.load_vgpr_offset_f32(vdata, k);
                    let vu = self.bitcast_f32_to_u32(vf);
                    self.func.body.push(
                        Statement::Store {
                            pointer: elem_ptr,
                            value: vu,
                        },
                        Span::UNDEFINED,
                    );
                }
                true
            }
        }
    }

    // -- DS (LDS Workgroup Shared Memory) --

    fn emit_compute_local_index(&mut self) -> Handle<Expression> {
        if self.stage != ShaderStage::Compute {
            return self.lit_u32(0);
        }
        if self.mesh_output.is_some() {
            return self.raw_expr(Expression::FunctionArgument(3));
        }
        let local_id = self.raw_expr(Expression::FunctionArgument(0));
        let lx = self.emit_expr(Expression::AccessIndex {
            base: local_id,
            index: 0,
        });
        let [wg_x, wg_y, _] = self.workgroup_size;
        if wg_y <= 1 && self.workgroup_size[2] <= 1 {
            return lx;
        }
        let ly = self.emit_expr(Expression::AccessIndex {
            base: local_id,
            index: 1,
        });
        let lz = self.emit_expr(Expression::AccessIndex {
            base: local_id,
            index: 2,
        });
        let wg_x_lit = self.lit_u32(wg_x.max(1));
        let wg_xy_lit = self.lit_u32(wg_x.max(1).saturating_mul(wg_y.max(1)));
        let y_part = self.emit_bin(BinaryOperator::Multiply, ly, wg_x_lit);
        let z_part = self.emit_bin(BinaryOperator::Multiply, lz, wg_xy_lit);
        let xy = self.emit_bin(BinaryOperator::Add, lx, y_part);
        self.emit_bin(BinaryOperator::Add, xy, z_part)
    }

    fn lds_masked_dword_index(
        &mut self,
        base_addr_u32: Handle<Expression>,
        byte_offset: u32,
    ) -> Handle<Expression> {
        let eff_addr = if byte_offset == 0 {
            base_addr_u32
        } else {
            let off_lit = self.lit_u32(byte_offset);
            self.emit_expr(Expression::Binary {
                op: BinaryOperator::Add,
                left: base_addr_u32,
                right: off_lit,
            })
        };
        let two = self.lit_u32(2);
        let dword_idx = self.emit_expr(Expression::Binary {
            op: BinaryOperator::ShiftRight,
            left: eff_addr,
            right: two,
        });
        let mask = self.lit_u32(LDS_WORKGROUP_INDEX_MASK);
        self.emit_expr(Expression::Binary {
            op: BinaryOperator::And,
            left: dword_idx,
            right: mask,
        })
    }

    fn translate_ds_wave_op(
        &mut self,
        lds_op: DsLdsOp,
        offset0: u8,
        offset1: u8,
        addr: u8,
        data0: u8,
        vdst: u8,
    ) -> bool {
        let fallback_val = match lds_op {
            DsLdsOp::Swizzle => {
                let f = self.load_vgpr_f32(addr);
                self.bitcast_f32_to_u32(f)
            }
            DsLdsOp::Permute | DsLdsOp::BPermute => {
                let f = self.load_vgpr_f32(data0);
                self.bitcast_f32_to_u32(f)
            }
            _ => return false,
        };

        // Hardware WebGPU `subgroups` fast path (`#2178`): zero `pg6_wave_lds`, zero barriers!
        // `DsLdsOp::Permute` (forward scatter with highest-lane-wins collision semantics) falls
        // through to the `pg6_wave_lds` path below.
        if self.subgroups_active() {
            match lds_op {
                DsLdsOp::Swizzle => {
                    let imm16 = u16::from(offset0) | (u16::from(offset1) << 8);
                    let res = match decode_ds_swizzle_offset(imm16) {
                        Rdna2SwizzleMode::BitMode {
                            and_mask: 0x1F,
                            or_mask: 0,
                            xor_mask,
                        } => {
                            if xor_mask == 0 {
                                fallback_val
                            } else {
                                let xor_lit = self.lit_u32(u32::from(xor_mask));
                                self.emit_wave_shuffle_xor(fallback_val, xor_lit)
                            }
                        }
                        Rdna2SwizzleMode::QuadPerm {
                            lanes: [0, 1, 2, 3],
                        } => fallback_val,
                        Rdna2SwizzleMode::QuadPerm {
                            lanes: [1, 0, 3, 2],
                        } => {
                            let m = self.lit_u32(1);
                            self.emit_wave_shuffle_xor(fallback_val, m)
                        }
                        Rdna2SwizzleMode::QuadPerm {
                            lanes: [2, 3, 0, 1],
                        } => {
                            let m = self.lit_u32(2);
                            self.emit_wave_shuffle_xor(fallback_val, m)
                        }
                        Rdna2SwizzleMode::QuadPerm {
                            lanes: [3, 2, 1, 0],
                        } => {
                            let m = self.lit_u32(3);
                            self.emit_wave_shuffle_xor(fallback_val, m)
                        }
                        Rdna2SwizzleMode::QuadPerm { lanes } => {
                            let sg_lane = self.emit_subgroup_invocation_id();
                            let mask63 = self.lit_u32(63);
                            let lane = self.emit_bin(BinaryOperator::And, sg_lane, mask63);
                            let mask60 = self.lit_u32(60);
                            let mask3 = self.lit_u32(3);
                            let quad_base = self.emit_bin(BinaryOperator::And, lane, mask60);
                            let quad_id = self.emit_bin(BinaryOperator::And, lane, mask3);
                            let mut picked = self.lit_u32(u32::from(lanes[0]));
                            for (q, &target) in lanes.iter().enumerate().skip(1) {
                                let q_lit = self.lit_u32(q as u32);
                                let is_q = self.emit_bin(BinaryOperator::Equal, quad_id, q_lit);
                                let t_lit = self.lit_u32(u32::from(target));
                                picked = self.emit_select(is_q, t_lit, picked);
                            }
                            let src_lane =
                                self.emit_bin(BinaryOperator::InclusiveOr, quad_base, picked);
                            self.emit_wave_shuffle(fallback_val, src_lane)
                        }
                        Rdna2SwizzleMode::BitMode {
                            and_mask,
                            or_mask,
                            xor_mask,
                        } => {
                            let sg_lane = self.emit_subgroup_invocation_id();
                            let mask63 = self.lit_u32(63);
                            let lane = self.emit_bin(BinaryOperator::And, sg_lane, mask63);
                            let c32 = self.lit_u32(32);
                            let mask31 = self.lit_u32(31);
                            let hi_bit = self.emit_bin(BinaryOperator::And, lane, c32);
                            let lo5 = self.emit_bin(BinaryOperator::And, lane, mask31);
                            let and_l = self.lit_u32(u32::from(and_mask));
                            let or_l = self.lit_u32(u32::from(or_mask));
                            let xor_l = self.lit_u32(u32::from(xor_mask));
                            let t0 = self.emit_bin(BinaryOperator::And, lo5, and_l);
                            let t1 = self.emit_bin(BinaryOperator::InclusiveOr, t0, or_l);
                            let t2 = self.emit_bin(BinaryOperator::ExclusiveOr, t1, xor_l);
                            let t2_clamped = self.emit_bin(BinaryOperator::And, t2, mask31);
                            let src_lane =
                                self.emit_bin(BinaryOperator::InclusiveOr, hi_bit, t2_clamped);
                            self.emit_wave_shuffle(fallback_val, src_lane)
                        }
                    };
                    self.store_vgpr_u32(vdst, res);
                    return true;
                }
                DsLdsOp::BPermute => {
                    let addr_f = self.load_vgpr_f32(addr);
                    let addr_u = self.bitcast_f32_to_u32(addr_f);
                    let two = self.lit_u32(2);
                    let mask63 = self.lit_u32(63);
                    let lane_raw = self.emit_bin(BinaryOperator::ShiftRight, addr_u, two);
                    let src_lane = self.emit_bin(BinaryOperator::And, lane_raw, mask63);
                    let res = self.emit_wave_shuffle(fallback_val, src_lane);
                    self.store_vgpr_u32(vdst, res);
                    return true;
                }
                _ => {}
            }
        }

        if self.in_nonuniform_cf() {
            self.store_vgpr_u32(vdst, fallback_val);
            return true;
        }
        let Some(wave_lds) = self.wave_lds_global else {
            self.store_vgpr_u32(vdst, fallback_val);
            return true;
        };

        let wave_ptr = self.raw_expr(Expression::GlobalVariable(wave_lds));
        let local_idx = self.emit_compute_local_index();
        let mask255 = self.lit_u32(255);
        let mask63 = self.lit_u32(63);
        let wave_base_mask = self.lit_u32(0xFFFF_FFC0);
        let slot = self.emit_bin(BinaryOperator::And, local_idx, mask255);
        let wave_base = self.emit_bin(BinaryOperator::And, slot, wave_base_mask);
        let lane = self.emit_bin(BinaryOperator::And, slot, mask63);

        match lds_op {
            DsLdsOp::Swizzle => {
                let my_ptr = self.emit_expr(Expression::Access {
                    base: wave_ptr,
                    index: slot,
                });
                self.push_stmt(Statement::Store {
                    pointer: my_ptr,
                    value: fallback_val,
                });
                self.push_stmt(Statement::ControlBarrier(naga::Barrier::WORK_GROUP));

                let imm16 = u16::from(offset0) | (u16::from(offset1) << 8);
                let src_lane = match decode_ds_swizzle_offset(imm16) {
                    Rdna2SwizzleMode::QuadPerm { lanes } => {
                        let mask60 = self.lit_u32(60);
                        let mask3 = self.lit_u32(3);
                        let quad_base = self.emit_bin(BinaryOperator::And, lane, mask60);
                        let quad_id = self.emit_bin(BinaryOperator::And, lane, mask3);
                        let mut picked = self.lit_u32(u32::from(lanes[0]));
                        for (q, &target) in lanes.iter().enumerate().skip(1) {
                            let q_lit = self.lit_u32(q as u32);
                            let is_q = self.emit_bin(BinaryOperator::Equal, quad_id, q_lit);
                            let t_lit = self.lit_u32(u32::from(target));
                            picked = self.emit_select(is_q, t_lit, picked);
                        }
                        self.emit_bin(BinaryOperator::InclusiveOr, quad_base, picked)
                    }
                    Rdna2SwizzleMode::BitMode {
                        and_mask,
                        or_mask,
                        xor_mask,
                    } => {
                        let c32 = self.lit_u32(32);
                        let mask31 = self.lit_u32(31);
                        let hi_bit = self.emit_bin(BinaryOperator::And, lane, c32);
                        let lo5 = self.emit_bin(BinaryOperator::And, lane, mask31);
                        let and_l = self.lit_u32(u32::from(and_mask));
                        let or_l = self.lit_u32(u32::from(or_mask));
                        let xor_l = self.lit_u32(u32::from(xor_mask));
                        let t0 = self.emit_bin(BinaryOperator::And, lo5, and_l);
                        let t1 = self.emit_bin(BinaryOperator::InclusiveOr, t0, or_l);
                        let t2 = self.emit_bin(BinaryOperator::ExclusiveOr, t1, xor_l);
                        let t2_clamped = self.emit_bin(BinaryOperator::And, t2, mask31);
                        self.emit_bin(BinaryOperator::InclusiveOr, hi_bit, t2_clamped)
                    }
                };
                let clamped_lane = self.emit_bin(BinaryOperator::And, src_lane, mask63);
                let target_slot_raw =
                    self.emit_bin(BinaryOperator::InclusiveOr, wave_base, clamped_lane);
                let target_slot = self.emit_bin(BinaryOperator::And, target_slot_raw, mask255);
                let src_ptr = self.emit_expr(Expression::Access {
                    base: wave_ptr,
                    index: target_slot,
                });
                let res = self.emit_expr(Expression::Load { pointer: src_ptr });
                self.push_stmt(Statement::ControlBarrier(naga::Barrier::WORK_GROUP));
                self.store_vgpr_u32(vdst, res);
                true
            }
            DsLdsOp::BPermute => {
                let my_ptr = self.emit_expr(Expression::Access {
                    base: wave_ptr,
                    index: slot,
                });
                self.push_stmt(Statement::Store {
                    pointer: my_ptr,
                    value: fallback_val,
                });
                self.push_stmt(Statement::ControlBarrier(naga::Barrier::WORK_GROUP));

                let addr_f = self.load_vgpr_f32(addr);
                let addr_u = self.bitcast_f32_to_u32(addr_f);
                let two = self.lit_u32(2);
                let lane_raw = self.emit_bin(BinaryOperator::ShiftRight, addr_u, two);
                let src_lane = self.emit_bin(BinaryOperator::And, lane_raw, mask63);
                let target_slot_raw = self.emit_bin(BinaryOperator::InclusiveOr, wave_base, src_lane);
                let target_slot = self.emit_bin(BinaryOperator::And, target_slot_raw, mask255);
                let src_ptr = self.emit_expr(Expression::Access {
                    base: wave_ptr,
                    index: target_slot,
                });
                let res = self.emit_expr(Expression::Load { pointer: src_ptr });
                self.push_stmt(Statement::ControlBarrier(naga::Barrier::WORK_GROUP));
                self.store_vgpr_u32(vdst, res);
                true
            }
            DsLdsOp::Permute => {
                let my_ptr = self.emit_expr(Expression::Access {
                    base: wave_ptr,
                    index: slot,
                });
                let zero = self.lit_u32(0);
                self.push_stmt(Statement::Store {
                    pointer: my_ptr,
                    value: zero,
                });
                self.push_stmt(Statement::ControlBarrier(naga::Barrier::WORK_GROUP));

                let addr_f = self.load_vgpr_f32(addr);
                let addr_u = self.bitcast_f32_to_u32(addr_f);
                let two = self.lit_u32(2);
                let lane_raw = self.emit_bin(BinaryOperator::ShiftRight, addr_u, two);
                let dst_lane = self.emit_bin(BinaryOperator::And, lane_raw, mask63);
                let target_slot_raw = self.emit_bin(BinaryOperator::InclusiveOr, wave_base, dst_lane);
                let target_slot = self.emit_bin(BinaryOperator::And, target_slot_raw, mask255);
                let dst_ptr = self.emit_expr(Expression::Access {
                    base: wave_ptr,
                    index: target_slot,
                });
                self.push_stmt(Statement::Store {
                    pointer: dst_ptr,
                    value: fallback_val,
                });
                self.push_stmt(Statement::ControlBarrier(naga::Barrier::WORK_GROUP));

                let res = self.emit_expr(Expression::Load { pointer: my_ptr });
                self.push_stmt(Statement::ControlBarrier(naga::Barrier::WORK_GROUP));
                self.store_vgpr_u32(vdst, res);
                true
            }
            _ => false,
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn translate_ds(
        &mut self,
        op: u8,
        offset0: u8,
        offset1: u8,
        addr: u8,
        data0: u8,
        data1: u8,
        vdst: u8,
    ) -> bool {
        let Some(lds_op) = ds_lds_op(op) else {
            return false;
        };
        if matches!(
            lds_op,
            DsLdsOp::Swizzle | DsLdsOp::Permute | DsLdsOp::BPermute
        ) {
            if self.stage == ShaderStage::Compute
                || (self.subgroups_active()
                    && matches!(lds_op, DsLdsOp::Swizzle | DsLdsOp::BPermute))
            {
                return self.translate_ds_wave_op(lds_op, offset0, offset1, addr, data0, vdst);
            }
            return false;
        }
        if self.stage != ShaderStage::Compute {
            return false;
        }
        let Some(lds_global) = self.lds_global else {
            return false;
        };

        let lds_ptr = self.raw_expr(Expression::GlobalVariable(lds_global));
        let addr_f = self.load_vgpr_f32(addr);
        let addr_u = self.bitcast_f32_to_u32(addr_f);

        // Sub-dword byte/short LDS reads & writes:
        //   0x39 ds_read_i8, 0x3A ds_read_u8, 0x3B ds_read_i16, 0x3C ds_read_u16
        //   0x1E ds_write_b8, 0x1F ds_write_b16
        if matches!(op, 0x1E | 0x1F | 0x39..=0x3C) {
            let imm16 = u32::from(offset0) | (u32::from(offset1) << 8);
            let eff_addr = if imm16 == 0 {
                addr_u
            } else {
                let off_lit = self.lit_u32(imm16);
                self.emit_bin(BinaryOperator::Add, addr_u, off_lit)
            };
            let idx = self.lds_masked_dword_index(addr_u, imm16);
            let elem_ptr = self.emit_expr(Expression::Access {
                base: lds_ptr,
                index: idx,
            });
            let mask3 = self.lit_u32(3);
            let sh3 = self.lit_u32(3);
            let byte_lane = self.emit_bin(BinaryOperator::And, eff_addr, mask3);
            let shift = self.emit_bin(BinaryOperator::ShiftLeft, byte_lane, sh3);
            let word = self.emit_expr(Expression::Load { pointer: elem_ptr });

            match op {
                0x39..=0x3C => {
                    let shifted = self.emit_bin(BinaryOperator::ShiftRight, word, shift);
                    match op {
                        0x3A => {
                            let m8 = self.lit_u32(0xFF);
                            let val = self.emit_bin(BinaryOperator::And, shifted, m8);
                            self.store_vgpr_u32(vdst, val);
                        }
                        0x39 => {
                            let s_i = self.bitcast_u32_to_i32(shifted);
                            let sh24 = self.lit_u32(24);
                            let shl = self.emit_bin(BinaryOperator::ShiftLeft, s_i, sh24);
                            let val = self.emit_bin(BinaryOperator::ShiftRight, shl, sh24);
                            self.store_vgpr_i32(vdst, val);
                        }
                        0x3C => {
                            let m16 = self.lit_u32(0xFFFF);
                            let val = self.emit_bin(BinaryOperator::And, shifted, m16);
                            self.store_vgpr_u32(vdst, val);
                        }
                        _ => {
                            let s_i = self.bitcast_u32_to_i32(shifted);
                            let sh16 = self.lit_u32(16);
                            let shl = self.emit_bin(BinaryOperator::ShiftLeft, s_i, sh16);
                            let val = self.emit_bin(BinaryOperator::ShiftRight, shl, sh16);
                            self.store_vgpr_i32(vdst, val);
                        }
                    }
                    return true;
                }
                _ => {
                    let width_mask = self.lit_u32(if op == 0x1E { 0xFF } else { 0xFFFF });
                    let vf = self.load_vgpr_f32(data0);
                    let vu = self.bitcast_f32_to_u32(vf);
                    let masked_val = self.emit_bin(BinaryOperator::And, vu, width_mask);
                    let placed = self.emit_bin(BinaryOperator::ShiftLeft, masked_val, shift);
                    let slot_mask = self.emit_bin(BinaryOperator::ShiftLeft, width_mask, shift);
                    let inv_mask = self.emit_bit_not(slot_mask);
                    let cleared = self.emit_bin(BinaryOperator::And, word, inv_mask);
                    let new_word = self.emit_bin(BinaryOperator::InclusiveOr, cleared, placed);
                    self.func.body.push(
                        Statement::Store {
                            pointer: elem_ptr,
                            value: new_word,
                        },
                        Span::UNDEFINED,
                    );
                    return true;
                }
            }
        }

        match lds_op {
            DsLdsOp::ReadContiguous(n) => {
                let imm16 = u32::from(offset0) | (u32::from(offset1) << 8);
                let mut loaded = Vec::with_capacity(usize::from(n));
                for k in 0..n {
                    let idx = self.lds_masked_dword_index(addr_u, imm16.saturating_add(u32::from(k) * 4));
                    let elem_ptr = self.emit_expr(Expression::Access {
                        base: lds_ptr,
                        index: idx,
                    });
                    loaded.push(self.emit_expr(Expression::Load { pointer: elem_ptr }));
                }
                for (k, word) in loaded.into_iter().enumerate() {
                    self.store_vgpr_offset_u32(vdst, k as u8, word);
                }
                true
            }
            DsLdsOp::WriteContiguous(n) => {
                let imm16 = u32::from(offset0) | (u32::from(offset1) << 8);
                for k in 0..n {
                    let idx = self.lds_masked_dword_index(addr_u, imm16.saturating_add(u32::from(k) * 4));
                    let elem_ptr = self.emit_expr(Expression::Access {
                        base: lds_ptr,
                        index: idx,
                    });
                    let vf = self.load_vgpr_offset_f32(data0, k);
                    let vu = self.bitcast_f32_to_u32(vf);
                    self.func.body.push(
                        Statement::Store {
                            pointer: elem_ptr,
                            value: vu,
                        },
                        Span::UNDEFINED,
                    );
                }
                true
            }
            DsLdsOp::Read2 { stride_bytes } => {
                let idx0 = self.lds_masked_dword_index(addr_u, u32::from(offset0) * stride_bytes);
                let ptr0 = self.emit_expr(Expression::Access {
                    base: lds_ptr,
                    index: idx0,
                });
                let w0 = self.emit_expr(Expression::Load { pointer: ptr0 });

                let idx1 = self.lds_masked_dword_index(addr_u, u32::from(offset1) * stride_bytes);
                let ptr1 = self.emit_expr(Expression::Access {
                    base: lds_ptr,
                    index: idx1,
                });
                let w1 = self.emit_expr(Expression::Load { pointer: ptr1 });

                self.store_vgpr_u32(vdst, w0);
                self.store_vgpr_offset_u32(vdst, 1, w1);
                true
            }
            DsLdsOp::Write2 { stride_bytes } => {
                let idx0 = self.lds_masked_dword_index(addr_u, u32::from(offset0) * stride_bytes);
                let ptr0 = self.emit_expr(Expression::Access {
                    base: lds_ptr,
                    index: idx0,
                });
                let vf0 = self.load_vgpr_f32(data0);
                let vu0 = self.bitcast_f32_to_u32(vf0);
                self.func.body.push(
                    Statement::Store {
                        pointer: ptr0,
                        value: vu0,
                    },
                    Span::UNDEFINED,
                );

                let idx1 = self.lds_masked_dword_index(addr_u, u32::from(offset1) * stride_bytes);
                let ptr1 = self.emit_expr(Expression::Access {
                    base: lds_ptr,
                    index: idx1,
                });
                let vf1 = self.load_vgpr_f32(data1);
                let vu1 = self.bitcast_f32_to_u32(vf1);
                self.func.body.push(
                    Statement::Store {
                        pointer: ptr1,
                        value: vu1,
                    },
                    Span::UNDEFINED,
                );
                true
            }
            DsLdsOp::Atomic {
                op: atomic_op,
                returns_value,
            } => {
                let imm16 = u32::from(offset0) | (u32::from(offset1) << 8);
                let idx = self.lds_masked_dword_index(addr_u, imm16);
                let elem_ptr = self.emit_expr(Expression::Access {
                    base: lds_ptr,
                    index: idx,
                });
                let val = match atomic_op {
                    DsAtomicOp::Inc | DsAtomicOp::Dec => self.lit_u32(1),
                    _ => {
                        let vf = self.load_vgpr_f32(data0);
                        self.bitcast_f32_to_u32(vf)
                    }
                };
                let fun = match atomic_op {
                    DsAtomicOp::Add | DsAtomicOp::Inc => AtomicFunction::Add,
                    DsAtomicOp::Sub | DsAtomicOp::Dec => AtomicFunction::Subtract,
                    DsAtomicOp::UMin => AtomicFunction::Min,
                    DsAtomicOp::UMax => AtomicFunction::Max,
                    DsAtomicOp::And => AtomicFunction::And,
                    DsAtomicOp::Or => AtomicFunction::InclusiveOr,
                    DsAtomicOp::Xor => AtomicFunction::ExclusiveOr,
                    DsAtomicOp::Swap => AtomicFunction::Exchange { compare: None },
                };
                let res = self.raw_expr(Expression::AtomicResult {
                    ty: self.types.u32_ty,
                    comparison: false,
                });
                self.push_stmt(Statement::Atomic {
                    pointer: elem_ptr,
                    fun,
                    value: val,
                    result: Some(res),
                });
                if returns_value {
                    self.store_vgpr_u32(vdst, res);
                }
                true
            }
            DsLdsOp::Swizzle | DsLdsOp::Permute | DsLdsOp::BPermute => unreachable!(),
        }
    }

    fn translate_vertex_buf_fetch(
        &mut self,
        vb_slot: u32,
        is_mtbuf: bool,
        op: u8,
        format: u8,
        byte_offset: u16,
        vdata: u8,
    ) -> bool {
        if self.stage != ShaderStage::Vertex
            || self.vertex_input_mode != VertexInputMode::Attributes
        {
            return false;
        }
        let Some(arg_idx) = self.vs_in_arg else {
            return false;
        };
        let Some(comps) = (if is_mtbuf {
            mtbuf_load_components(op)
        } else {
            mubuf_load_components(op)
        }) else {
            return false;
        };
        let (attr_offset, shift) = vertex_fetch_slot(is_mtbuf, op, format, byte_offset);
        let Some(&(member_idx, attr_comps, scalar_kind)) =
            self.vs_attr_by_offset.get(&(vb_slot, attr_offset))
        else {
            return false;
        };
        let vs_in = self.raw_expr(Expression::FunctionArgument(arg_idx));
        let attr_val = self.emit_expr(Expression::AccessIndex {
            base: vs_in,
            index: member_idx,
        });
        for c in 0..comps {
            let src_c = c.saturating_add(shift);
            if src_c < attr_comps {
                let elem = if attr_comps == 1 {
                    attr_val
                } else {
                    self.emit_expr(Expression::AccessIndex {
                        base: attr_val,
                        index: u32::from(src_c),
                    })
                };
                match scalar_kind {
                    ScalarKind::Uint => self.store_vgpr_offset_u32(vdata, c, elem),
                    ScalarKind::Sint => self.store_vgpr_offset_i32(vdata, c, elem),
                    _ => self.store_vgpr_offset_f32(vdata, c, elem),
                }
            } else {
                let fallback = match scalar_kind {
                    ScalarKind::Uint => self.lit_u32(if c == 3 { 1 } else { 0 }),
                    ScalarKind::Sint => self.lit_i32(if c == 3 { 1 } else { 0 }),
                    _ => self.lit_f32(if c == 3 { 1.0 } else { 0.0 }),
                };
                match scalar_kind {
                    ScalarKind::Uint => self.store_vgpr_offset_u32(vdata, c, fallback),
                    ScalarKind::Sint => self.store_vgpr_offset_i32(vdata, c, fallback),
                    _ => self.store_vgpr_offset_f32(vdata, c, fallback),
                }
            }
        }
        true
    }

    // -- EXP (Vertex position/param & Pixel MRT/depth exports) --

    fn build_export_vec4(
        &mut self,
        en: u8,
        compr: bool,
        vsrc: [u8; 4],
        default_w: f32,
    ) -> Handle<Expression> {
        if compr {
            // GFX10.3 compressed EXP (`compr = 1`): `en[0]` enables both R and G packed as fp16x2
            // in `vsrc[0]`; `en[2]` enables both B and A packed as fp16x2 in `vsrc[1]`.
            // `en[1]` and `en[3]` are ignored by hardware (standard RGBA export uses `en = 0x5`).
            let (c0, c1) = if (en & 0b0001) != 0 {
                let vf = self.load_vgpr_f32(vsrc[0]);
                let vu = self.bitcast_f32_to_u32(vf);
                let lo_vec = self.emit_expr(Expression::Math {
                    fun: MathFunction::Unpack2x16float,
                    arg: vu,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let c0 = self.emit_expr(Expression::AccessIndex {
                    base: lo_vec,
                    index: 0,
                });
                let c1 = self.emit_expr(Expression::AccessIndex {
                    base: lo_vec,
                    index: 1,
                });
                (c0, c1)
            } else {
                (self.lit_f32(0.0), self.lit_f32(0.0))
            };
            let (c2, c3) = if (en & 0b0100) != 0 {
                let vf = self.load_vgpr_f32(vsrc[1]);
                let vu = self.bitcast_f32_to_u32(vf);
                let hi_vec = self.emit_expr(Expression::Math {
                    fun: MathFunction::Unpack2x16float,
                    arg: vu,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                });
                let c2 = self.emit_expr(Expression::AccessIndex {
                    base: hi_vec,
                    index: 0,
                });
                let c3 = self.emit_expr(Expression::AccessIndex {
                    base: hi_vec,
                    index: 1,
                });
                (c2, c3)
            } else {
                (self.lit_f32(0.0), self.lit_f32(default_w))
            };
            self.emit_expr(Expression::Compose {
                ty: self.types.vec4_f32_ty,
                components: vec![c0, c1, c2, c3],
            })
        } else {
            let mut comps = Vec::with_capacity(4);
            for i in 0..4usize {
                if (en & (1 << i)) != 0 {
                    comps.push(self.load_vgpr_f32(vsrc[i]));
                } else {
                    comps.push(self.lit_f32(if i == 3 { default_w } else { 0.0 }));
                }
            }
            self.emit_expr(Expression::Compose {
                ty: self.types.vec4_f32_ty,
                components: comps,
            })
        }
    }

    fn mesh_record_base_and_ok(
        &mut self,
        layout: MeshOutputLayout,
        ms_global: Handle<GlobalVariable>,
    ) -> (Handle<Expression>, Handle<Expression>) {
        let wg_id = self.raw_expr(Expression::FunctionArgument(1));
        let group_x = self.emit_expr(Expression::AccessIndex {
            base: wg_id,
            index: 0,
        });
        let record_words = self.lit_u32(layout.group_record_words());
        let rec = self.emit_bin(BinaryOperator::Multiply, group_x, record_words);
        let rec_end = self.emit_bin(BinaryOperator::Add, rec, record_words);
        let buf_ptr = self.raw_expr(Expression::GlobalVariable(ms_global));
        let buf_len = self.emit_expr(Expression::ArrayLength(buf_ptr));
        let rec_ok = self.emit_bin(BinaryOperator::LessEqual, rec_end, buf_len);
        (rec, rec_ok)
    }

    fn emit_mesh_store_u32(
        &mut self,
        ms_global: Handle<GlobalVariable>,
        index: Handle<Expression>,
        value: Handle<Expression>,
    ) {
        let buf_ptr = self.raw_expr(Expression::GlobalVariable(ms_global));
        let elem_ptr = self.emit_expr(Expression::Access {
            base: buf_ptr,
            index,
        });
        self.push_stmt(Statement::Store {
            pointer: elem_ptr,
            value,
        });
    }

    fn mesh_lane_write_guard(
        &mut self,
        limit: u32,
        rec_ok: Handle<Expression>,
    ) -> (Handle<Expression>, Handle<Expression>) {
        let local_idx = self.raw_expr(Expression::FunctionArgument(3));
        let limit_lit = self.lit_u32(limit);
        let in_bounds = self.emit_bin(BinaryOperator::Less, local_idx, limit_lit);
        let mut guard = self.emit_bin(BinaryOperator::LogicalAnd, in_bounds, rec_ok);
        if self.exec_local.is_some() {
            let exec = self.load_exec();
            let zero = self.lit_u32(0);
            let active = self.emit_bin(BinaryOperator::NotEqual, exec, zero);
            guard = self.emit_bin(BinaryOperator::LogicalAnd, guard, active);
        }
        (local_idx, guard)
    }

    /// Emit `if (exec_mask == 0u) { discard; }` in fragment shaders that track `exec_mask`,
    /// marking subsequent control flow non-uniform per WGSL §16.4 so any later texture sample
    /// avoids implicit derivatives.
    fn emit_fragment_exec_discard(&mut self) {
        if self.stage != ShaderStage::Fragment || self.exec_local.is_none() {
            return;
        }
        let exec = self.load_exec();
        let zero = self.lit_u32(0);
        let killed = self.emit_bin(BinaryOperator::Equal, exec, zero);
        let mut accept = naga::Block::new();
        accept.push(Statement::Kill, Span::UNDEFINED);
        self.push_stmt(Statement::If {
            condition: killed,
            accept,
            reject: naga::Block::new(),
        });
        self.cf_nonuniform_return = true;
    }

    fn translate_exp(
        &mut self,
        target: Rdna2ExportTarget,
        en: u8,
        compr: bool,
        done: bool,
        vm: bool,
        vsrc: [u8; 4],
    ) -> bool {
        if let (Some(layout), Some(ms_global)) = (self.mesh_output, self.mesh_out_global) {
            return match target {
                Rdna2ExportTarget::Null | Rdna2ExportTarget::Pos(1..=4) => true,
                Rdna2ExportTarget::Pos(0) => {
                    let val = self.build_export_vec4(en, compr, vsrc, 1.0);
                    let (rec, rec_ok) = self.mesh_record_base_and_ok(layout, ms_global);
                    let (vert_idx, cond) =
                        self.mesh_lane_write_guard(layout.max_vertices, rec_ok);
                    let accept = self.lower_nested(|s| {
                        let c4 = s.lit_u32(4);
                        let vwords = s.lit_u32(layout.vertex_words);
                        let voff = s.emit_bin(BinaryOperator::Multiply, vert_idx, vwords);
                        let rec4 = s.emit_bin(BinaryOperator::Add, rec, c4);
                        let vbase = s.emit_bin(BinaryOperator::Add, rec4, voff);
                        for c in 0..4u32 {
                            let comp = s.emit_expr(Expression::AccessIndex {
                                base: val,
                                index: c,
                            });
                            let bits = s.bitcast_f32_to_u32(comp);
                            let coff = s.lit_u32(c);
                            let idx = s.emit_bin(BinaryOperator::Add, vbase, coff);
                            s.emit_mesh_store_u32(ms_global, idx, bits);
                        }
                    });
                    self.push_stmt(Statement::If {
                        condition: cond,
                        accept,
                        reject: naga::Block::new(),
                    });
                    true
                }
                Rdna2ExportTarget::Param(n) => {
                    let attr_idx = u32::from(n % MAX_INTER_STAGE_LOCATIONS);
                    if attr_idx >= layout.attribute_count() {
                        return true;
                    }
                    let val = self.build_export_vec4(en, compr, vsrc, 0.0);
                    let (rec, rec_ok) = self.mesh_record_base_and_ok(layout, ms_global);
                    let (vert_idx, cond) =
                        self.mesh_lane_write_guard(layout.max_vertices, rec_ok);
                    let attr_word_off = 4 + 4 * attr_idx;
                    let accept = self.lower_nested(|s| {
                        let c4 = s.lit_u32(4);
                        let vwords = s.lit_u32(layout.vertex_words);
                        let voff = s.emit_bin(BinaryOperator::Multiply, vert_idx, vwords);
                        let rec4 = s.emit_bin(BinaryOperator::Add, rec, c4);
                        let vbase = s.emit_bin(BinaryOperator::Add, rec4, voff);
                        let aoff = s.lit_u32(attr_word_off);
                        let abase = s.emit_bin(BinaryOperator::Add, vbase, aoff);
                        for c in 0..4u32 {
                            let comp = s.emit_expr(Expression::AccessIndex {
                                base: val,
                                index: c,
                            });
                            let bits = s.bitcast_f32_to_u32(comp);
                            let coff = s.lit_u32(c);
                            let idx = s.emit_bin(BinaryOperator::Add, abase, coff);
                            s.emit_mesh_store_u32(ms_global, idx, bits);
                        }
                    });
                    self.push_stmt(Statement::If {
                        condition: cond,
                        accept,
                        reject: naga::Block::new(),
                    });
                    true
                }
                Rdna2ExportTarget::Prim => {
                    let prim_word = if (en & 1) != 0 {
                        let f = self.load_vgpr_f32(vsrc[0]);
                        self.bitcast_f32_to_u32(f)
                    } else {
                        self.lit_u32(0)
                    };
                    let (rec, rec_ok) = self.mesh_record_base_and_ok(layout, ms_global);
                    let (prim_idx, cond) =
                        self.mesh_lane_write_guard(layout.max_primitives, rec_ok);
                    let accept = self.lower_nested(|s| {
                        let idx_base = s.lit_u32(layout.index_base_words());
                        let c3 = s.lit_u32(3);
                        let poff = s.emit_bin(BinaryOperator::Multiply, prim_idx, c3);
                        let base_plus = s.emit_bin(BinaryOperator::Add, rec, idx_base);
                        let pbase = s.emit_bin(BinaryOperator::Add, base_plus, poff);
                        let mask10 = s.lit_u32(0x3FF);
                        let sh10 = s.lit_u32(10);
                        let sh20 = s.lit_u32(20);
                        let i0 = s.emit_bin(BinaryOperator::And, prim_word, mask10);
                        let t1 = s.emit_bin(BinaryOperator::ShiftRight, prim_word, sh10);
                        let i1 = s.emit_bin(BinaryOperator::And, t1, mask10);
                        let t2 = s.emit_bin(BinaryOperator::ShiftRight, prim_word, sh20);
                        let i2 = s.emit_bin(BinaryOperator::And, t2, mask10);
                        for (c, idx_val) in [(0u32, i0), (1u32, i1), (2u32, i2)] {
                            let coff = s.lit_u32(c);
                            let dst = s.emit_bin(BinaryOperator::Add, pbase, coff);
                            s.emit_mesh_store_u32(ms_global, dst, idx_val);
                        }
                    });
                    self.push_stmt(Statement::If {
                        condition: cond,
                        accept,
                        reject: naga::Block::new(),
                    });
                    true
                }
                _ => false,
            };
        }
        match (self.stage, target) {
            (ShaderStage::Fragment, Rdna2ExportTarget::Null) => {
                if vm {
                    self.emit_fragment_exec_discard();
                    self.ps_pending_vm_discard = false;
                }
                true
            }
            (_, Rdna2ExportTarget::Null) => true,
            (ShaderStage::Vertex, Rdna2ExportTarget::Pos(0)) => {
                let Some(out_local) = self.vs_out_local else {
                    return false;
                };
                let val = self.build_export_vec4(en, compr, vsrc, 1.0);
                let base_ptr = self.raw_expr(Expression::LocalVariable(out_local));
                let field_ptr = self.emit_expr(Expression::AccessIndex {
                    base: base_ptr,
                    index: 0,
                });
                self.func.body.push(
                    Statement::Store {
                        pointer: field_ptr,
                        value: val,
                    },
                    Span::UNDEFINED,
                );
                true
            }
            (ShaderStage::Vertex, Rdna2ExportTarget::Param(n)) => {
                let Some(out_local) = self.vs_out_local else {
                    return false;
                };
                let clamped = n % MAX_INTER_STAGE_LOCATIONS;
                let Some(&member_idx) = self.vs_param_member_index.get(&clamped) else {
                    return false;
                };
                let val = self.build_export_vec4(en, compr, vsrc, 0.0);
                let base_ptr = self.raw_expr(Expression::LocalVariable(out_local));
                let field_ptr = self.emit_expr(Expression::AccessIndex {
                    base: base_ptr,
                    index: member_idx,
                });
                self.func.body.push(
                    Statement::Store {
                        pointer: field_ptr,
                        value: val,
                    },
                    Span::UNDEFINED,
                );
                true
            }
            (ShaderStage::Fragment, Rdna2ExportTarget::Mrt(n)) => {
                let Some(out_local) = self.ps_out_local else {
                    return false;
                };
                let Some(&member_idx) = self.ps_mrt_member_index.get(&n) else {
                    return false;
                };
                let val = self.build_export_vec4(en, compr, vsrc, 1.0);
                let base_ptr = self.raw_expr(Expression::LocalVariable(out_local));
                let field_ptr = self.emit_expr(Expression::AccessIndex {
                    base: base_ptr,
                    index: member_idx,
                });
                self.func.body.push(
                    Statement::Store {
                        pointer: field_ptr,
                        value: val,
                    },
                    Span::UNDEFINED,
                );
                if vm || (done && self.ps_pending_vm_discard) {
                    if done {
                        self.emit_fragment_exec_discard();
                        self.ps_pending_vm_discard = false;
                    } else {
                        self.ps_pending_vm_discard = true;
                    }
                }
                true
            }
            (ShaderStage::Fragment, Rdna2ExportTarget::MrtZ) => {
                let Some(out_local) = self.ps_out_local else {
                    return false;
                };
                let Some(member_idx) = self.ps_depth_member_index else {
                    return false;
                };
                let depth_val = if (en & 1) != 0 {
                    if compr {
                        let vf = self.load_vgpr_f32(vsrc[0]);
                        let vu = self.bitcast_f32_to_u32(vf);
                        let pair = self.emit_expr(Expression::Math {
                            fun: MathFunction::Unpack2x16float,
                            arg: vu,
                            arg1: None,
                            arg2: None,
                            arg3: None,
                        });
                        self.emit_expr(Expression::AccessIndex {
                            base: pair,
                            index: 0,
                        })
                    } else {
                        self.load_vgpr_f32(vsrc[0])
                    }
                } else {
                    self.lit_f32(0.0)
                };
                let base_ptr = self.raw_expr(Expression::LocalVariable(out_local));
                let field_ptr = self.emit_expr(Expression::AccessIndex {
                    base: base_ptr,
                    index: member_idx,
                });
                self.func.body.push(
                    Statement::Store {
                        pointer: field_ptr,
                        value: depth_val,
                    },
                    Span::UNDEFINED,
                );
                if vm || (done && self.ps_pending_vm_discard) {
                    if done {
                        self.emit_fragment_exec_discard();
                        self.ps_pending_vm_discard = false;
                    } else {
                        self.ps_pending_vm_discard = true;
                    }
                }
                true
            }
            _ => false,
        }
    }

    // -- Ray tracing BVH & FLAT/GLOBAL address-arena lowering (S65 / #1674) --

    fn vec2_u32_ty(&mut self) -> Handle<Type> {
        insert_type(
            &mut self.module,
            None,
            TypeInner::Vector {
                size: VectorSize::Bi,
                scalar: Scalar::U32,
            },
        )
    }

    fn vec4_u32_ty(&mut self) -> Handle<Type> {
        insert_type(
            &mut self.module,
            None,
            TypeInner::Vector {
                size: VectorSize::Quad,
                scalar: Scalar::U32,
            },
        )
    }

    fn ensure_pg6_load32_stub(&mut self) -> Handle<Function> {
        if let Some(h) = self.helper_pg6_load32 {
            return h;
        }
        let vec2_u32_ty = self.vec2_u32_ty();
        // Use a non-digit-ending name (`pg6_load32_stub`) so Naga's namer never appends a
        // disambiguating `_` suffix; `strip_rt_prelude_stubs` removes the stub definition and
        // rewrites calls to the runtime prelude's `pg6_load32(`.
        let mut f = Function {
            name: Some("pg6_load32_stub".to_string()),
            arguments: vec![FunctionArgument {
                name: Some("addr".to_string()),
                ty: vec2_u32_ty,
                binding: None,
            }],
            result: Some(FunctionResult {
                ty: self.types.u32_ty,
                binding: None,
            }),
            ..Function::default()
        };
        let zero = f
            .expressions
            .append(Expression::Literal(Literal::U32(0)), Span::UNDEFINED);
        f.body
            .push(Statement::Return { value: Some(zero) }, Span::UNDEFINED);
        let h = self.module.functions.append(f, Span::UNDEFINED);
        self.helper_pg6_load32 = Some(h);
        h
    }

    fn call_pg6_load32(&mut self, addr: Handle<Expression>) -> Handle<Expression> {
        let f = self.ensure_pg6_load32_stub();
        self.call_helper_1(f, addr)
    }

    fn ensure_pg6_bvh_intersect_stub(&mut self) -> Handle<Function> {
        if let Some(h) = self.helper_pg6_bvh_intersect {
            return h;
        }
        let vec4_u32_ty = self.vec4_u32_ty();
        let vec2_u32_ty = self.vec2_u32_ty();
        let mut f = Function {
            name: Some("pg6_bvh_intersect".to_string()),
            arguments: vec![
                FunctionArgument {
                    name: Some("desc".to_string()),
                    ty: vec4_u32_ty,
                    binding: None,
                },
                FunctionArgument {
                    name: Some("node".to_string()),
                    ty: vec2_u32_ty,
                    binding: None,
                },
                FunctionArgument {
                    name: Some("extent".to_string()),
                    ty: self.types.f32_ty,
                    binding: None,
                },
                FunctionArgument {
                    name: Some("origin".to_string()),
                    ty: self.types.vec3_f32_ty,
                    binding: None,
                },
                FunctionArgument {
                    name: Some("dir".to_string()),
                    ty: self.types.vec3_f32_ty,
                    binding: None,
                },
                FunctionArgument {
                    name: Some("inv_dir".to_string()),
                    ty: self.types.vec3_f32_ty,
                    binding: None,
                },
            ],
            result: Some(FunctionResult {
                ty: vec4_u32_ty,
                binding: None,
            }),
            ..Function::default()
        };
        let zero = f
            .expressions
            .append(Expression::ZeroValue(vec4_u32_ty), Span::UNDEFINED);
        f.body
            .push(Statement::Return { value: Some(zero) }, Span::UNDEFINED);
        let h = self.module.functions.append(f, Span::UNDEFINED);
        self.helper_pg6_bvh_intersect = Some(h);
        h
    }

    fn call_pg6_bvh_intersect(
        &mut self,
        desc: Handle<Expression>,
        node: Handle<Expression>,
        extent: Handle<Expression>,
        origin: Handle<Expression>,
        dir: Handle<Expression>,
        inv_dir: Handle<Expression>,
    ) -> Handle<Expression> {
        let f = self.ensure_pg6_bvh_intersect_stub();
        let res = self
            .func
            .expressions
            .append(Expression::CallResult(f), Span::UNDEFINED);
        self.func.body.push(
            Statement::Call {
                function: f,
                arguments: vec![desc, node, extent, origin, dir, inv_dir],
                result: Some(res),
            },
            Span::UNDEFINED,
        );
        res
    }

    fn emit_add_u64(
        &mut self,
        a_lo: Handle<Expression>,
        a_hi: Handle<Expression>,
        b_lo: Handle<Expression>,
        b_hi: Handle<Expression>,
    ) -> (Handle<Expression>, Handle<Expression>) {
        let sum_lo = self.emit_bin(BinaryOperator::Add, a_lo, b_lo);
        let overflow = self.emit_bin(BinaryOperator::Less, sum_lo, a_lo);
        let one = self.lit_u32(1);
        let zero = self.lit_u32(0);
        let carry = self.emit_select(overflow, one, zero);
        let sum_hi_0 = self.emit_bin(BinaryOperator::Add, a_hi, b_hi);
        let sum_hi = self.emit_bin(BinaryOperator::Add, sum_hi_0, carry);
        (sum_lo, sum_hi)
    }

    #[allow(clippy::too_many_arguments)]
    fn translate_bvh_intersect(
        &mut self,
        op: u8,
        a16: bool,
        nsize: u8,
        vaddr: u8,
        nsa_vaddrs: &[u8; 12],
        vdata: u8,
        srsrc: u8,
    ) -> bool {
        if self.stage == ShaderStage::Vertex || self.mesh_output.is_some() {
            return false;
        }
        let is_64 = match op {
            0xE6 => false,
            0xE7 => true,
            _ => return false,
        };

        let load_addr_f32 = |this: &mut Self, idx: u8| -> Handle<Expression> {
            match mimg_addr_vgpr(vaddr, nsize, nsa_vaddrs, idx) {
                Some(reg) => this.load_vgpr_f32(reg),
                None => this.lit_f32(0.0),
            }
        };
        let load_addr_u32 = |this: &mut Self, idx: u8| -> Handle<Expression> {
            match mimg_addr_vgpr(vaddr, nsize, nsa_vaddrs, idx) {
                Some(reg) => {
                    let vf = this.load_vgpr_f32(reg);
                    this.bitcast_f32_to_u32(vf)
                }
                None => this.lit_u32(0),
            }
        };

        let srsrc_base = srsrc.saturating_mul(4);
        let d0 = match checked_sgpr_reg(srsrc_base, 0) {
            Some(r) => self.load_sgpr_u32(r),
            None => self.lit_u32(0),
        };
        let d1 = match checked_sgpr_reg(srsrc_base, 1) {
            Some(r) => self.load_sgpr_u32(r),
            None => self.lit_u32(0),
        };
        let d2 = match checked_sgpr_reg(srsrc_base, 2) {
            Some(r) => self.load_sgpr_u32(r),
            None => self.lit_u32(0),
        };
        let d3 = match checked_sgpr_reg(srsrc_base, 3) {
            Some(r) => self.load_sgpr_u32(r),
            None => self.lit_u32(0),
        };
        let vec4_u32_ty = self.vec4_u32_ty();
        let desc = self.emit_expr(Expression::Compose {
            ty: vec4_u32_ty,
            components: vec![d0, d1, d2, d3],
        });

        let node_lo = load_addr_u32(self, 0);
        let (node_hi, base_idx) = if is_64 {
            (load_addr_u32(self, 1), 2u8)
        } else {
            (self.lit_u32(0), 1u8)
        };
        let vec2_u32_ty = self.vec2_u32_ty();
        let node = self.emit_expr(Expression::Compose {
            ty: vec2_u32_ty,
            components: vec![node_lo, node_hi],
        });

        let extent = load_addr_f32(self, base_idx);
        let ox = load_addr_f32(self, base_idx + 1);
        let oy = load_addr_f32(self, base_idx + 2);
        let oz = load_addr_f32(self, base_idx + 3);
        let origin = self.emit_expr(Expression::Compose {
            ty: self.types.vec3_f32_ty,
            components: vec![ox, oy, oz],
        });

        let dir_base = base_idx + 4;
        let (dir, inv_dir) = if !a16 {
            let dx = load_addr_f32(self, dir_base);
            let dy = load_addr_f32(self, dir_base + 1);
            let dz = load_addr_f32(self, dir_base + 2);
            let ix = load_addr_f32(self, dir_base + 3);
            let iy = load_addr_f32(self, dir_base + 4);
            let iz = load_addr_f32(self, dir_base + 5);
            let dir = self.emit_expr(Expression::Compose {
                ty: self.types.vec3_f32_ty,
                components: vec![dx, dy, dz],
            });
            let inv_dir = self.emit_expr(Expression::Compose {
                ty: self.types.vec3_f32_ty,
                components: vec![ix, iy, iz],
            });
            (dir, inv_dir)
        } else {
            let u0 = load_addr_u32(self, dir_base);
            let u1 = load_addr_u32(self, dir_base + 1);
            let u2 = load_addr_u32(self, dir_base + 2);
            let p0 = self.emit_expr(Expression::Math {
                fun: MathFunction::Unpack2x16float,
                arg: u0,
                arg1: None,
                arg2: None,
                arg3: None,
            });
            let p1 = self.emit_expr(Expression::Math {
                fun: MathFunction::Unpack2x16float,
                arg: u1,
                arg1: None,
                arg2: None,
                arg3: None,
            });
            let p2 = self.emit_expr(Expression::Math {
                fun: MathFunction::Unpack2x16float,
                arg: u2,
                arg1: None,
                arg2: None,
                arg3: None,
            });
            let dx = self.emit_expr(Expression::AccessIndex { base: p0, index: 0 });
            let dy = self.emit_expr(Expression::AccessIndex { base: p0, index: 1 });
            let dz = self.emit_expr(Expression::AccessIndex { base: p1, index: 0 });
            let ix = self.emit_expr(Expression::AccessIndex { base: p1, index: 1 });
            let iy = self.emit_expr(Expression::AccessIndex { base: p2, index: 0 });
            let iz = self.emit_expr(Expression::AccessIndex { base: p2, index: 1 });
            let dir = self.emit_expr(Expression::Compose {
                ty: self.types.vec3_f32_ty,
                components: vec![dx, dy, dz],
            });
            let inv_dir = self.emit_expr(Expression::Compose {
                ty: self.types.vec3_f32_ty,
                components: vec![ix, iy, iz],
            });
            (dir, inv_dir)
        };

        let res = self.call_pg6_bvh_intersect(desc, node, extent, origin, dir, inv_dir);
        for c in 0..4u8 {
            let comp = self.emit_expr(Expression::AccessIndex {
                base: res,
                index: u32::from(c),
            });
            self.store_vgpr_offset_u32(vdata, c, comp);
        }
        true
    }

    #[allow(clippy::too_many_arguments)]
    fn translate_flat(
        &mut self,
        seg: u8,
        op: u8,
        offset: i16,
        lds: bool,
        addr: u8,
        saddr: u8,
        vdst: u8,
    ) -> bool {
        if self.stage == ShaderStage::Vertex
            || self.mesh_output.is_some()
            || lds
            || !matches!(seg, 0 | 2)
        {
            return false;
        }
        if !matches!(op, 0x08..=0x0F) {
            return false;
        }

        let (mut cur_lo, mut cur_hi) = if seg == 2 && saddr != 0x7F {
            let base_lo = match checked_sgpr_reg(saddr, 0) {
                Some(r) => self.load_sgpr_u32(r),
                None => self.lit_u32(0),
            };
            let base_hi = match checked_sgpr_reg(saddr, 1) {
                Some(r) => self.load_sgpr_u32(r),
                None => self.lit_u32(0),
            };
            let v_off_f = self.load_vgpr_f32(addr);
            let v_off_lo = self.bitcast_f32_to_u32(v_off_f);
            let v_off_hi = self.lit_u32(0);
            self.emit_add_u64(base_lo, base_hi, v_off_lo, v_off_hi)
        } else {
            let lo_f = self.load_vgpr_f32(addr);
            let lo = self.bitcast_f32_to_u32(lo_f);
            let hi = match checked_vgpr_reg(addr, 1) {
                Some(r) => {
                    let f = self.load_vgpr_f32(r);
                    self.bitcast_f32_to_u32(f)
                }
                None => self.lit_u32(0),
            };
            (lo, hi)
        };

        if offset != 0 {
            let off64 = i64::from(offset) as u64;
            let off_lo = self.lit_u32(off64 as u32);
            let off_hi = self.lit_u32((off64 >> 32) as u32);
            (cur_lo, cur_hi) = self.emit_add_u64(cur_lo, cur_hi, off_lo, off_hi);
        }

        let vec2_u32_ty = self.vec2_u32_ty();
        match op {
            0x0C | 0x0D | 0x0E | 0x0F => {
                let count: u8 = match op {
                    0x0C => 1,
                    0x0D => 2,
                    0x0F => 3,
                    0x0E => 4,
                    _ => unreachable!(),
                };
                for k in 0..count {
                    let (w_lo, w_hi) = if k == 0 {
                        (cur_lo, cur_hi)
                    } else {
                        let delta_lo = self.lit_u32(u32::from(k) * 4);
                        let delta_hi = self.lit_u32(0);
                        self.emit_add_u64(cur_lo, cur_hi, delta_lo, delta_hi)
                    };
                    let addr_vec = self.emit_expr(Expression::Compose {
                        ty: vec2_u32_ty,
                        components: vec![w_lo, w_hi],
                    });
                    let loaded = self.call_pg6_load32(addr_vec);
                    self.store_vgpr_offset_u32(vdst, k, loaded);
                }
                true
            }
            0x08..=0x0B => {
                let align_mask = self.lit_u32(!3u32);
                let aligned_lo = self.emit_bin(BinaryOperator::And, cur_lo, align_mask);
                let addr_vec = self.emit_expr(Expression::Compose {
                    ty: vec2_u32_ty,
                    components: vec![aligned_lo, cur_hi],
                });
                let word = self.call_pg6_load32(addr_vec);
                let three = self.lit_u32(3);
                let byte_off = self.emit_bin(BinaryOperator::And, cur_lo, three);
                let three_shift = self.lit_u32(3);
                let bit_shift = self.emit_bin(BinaryOperator::ShiftLeft, byte_off, three_shift);
                let shifted = self.emit_bin(BinaryOperator::ShiftRight, word, bit_shift);
                match op {
                    0x08 => {
                        let mask = self.lit_u32(0xFF);
                        let val = self.emit_bin(BinaryOperator::And, shifted, mask);
                        self.store_vgpr_u32(vdst, val);
                    }
                    0x09 => {
                        let shifted_i = self.bitcast_u32_to_i32(shifted);
                        let s24_l = self.lit_u32(24);
                        let s24_r = self.lit_u32(24);
                        let hi = self.emit_bin(BinaryOperator::ShiftLeft, shifted_i, s24_l);
                        let sext = self.emit_bin(BinaryOperator::ShiftRight, hi, s24_r);
                        self.store_vgpr_i32(vdst, sext);
                    }
                    0x0A => {
                        let mask = self.lit_u32(0xFFFF);
                        let val = self.emit_bin(BinaryOperator::And, shifted, mask);
                        self.store_vgpr_u32(vdst, val);
                    }
                    0x0B => {
                        let shifted_i = self.bitcast_u32_to_i32(shifted);
                        let s16_l = self.lit_u32(16);
                        let s16_r = self.lit_u32(16);
                        let hi = self.emit_bin(BinaryOperator::ShiftLeft, shifted_i, s16_l);
                        let sext = self.emit_bin(BinaryOperator::ShiftRight, hi, s16_r);
                        self.store_vgpr_i32(vdst, sext);
                    }
                    _ => unreachable!(),
                }
                true
            }
            _ => false,
        }
    }

    // -- Exec mask (single-lane model) --

    /// `s_*_saveexec_b32/b64` and `s_andn{1,2}_wrexec_b32/b64` on the single-lane
    /// `exec_mask` (`0u` / `1u`): `exec_mask = op(src0 & 1u, exec_mask) & 1u`,
    /// `scc = (exec_mask != 0u)`; `sdst` receives the old mask (saveexec) or the new mask
    /// (wrexec), with a zero high dword for `_b64`.
    fn translate_exec_mask_write(
        &mut self,
        write: ExecMaskWrite,
        sdst: u8,
        ssrc0: u8,
        literal: Option<u32>,
    ) -> bool {
        let src = if write.wave64 {
            self.read_ssrc_pair(ssrc0, literal).0
        } else {
            self.read_src_u32(u16::from(ssrc0), literal)
        };
        let one = self.lit_u32(1);
        let s = self.emit_bin(BinaryOperator::And, src, one);
        let old = self.load_exec();
        let (bin, not_s, not_e, not_result) = match write.op {
            ExecMaskOp::AndSaveExec => (BinaryOperator::And, false, false, false),
            ExecMaskOp::OrSaveExec => (BinaryOperator::InclusiveOr, false, false, false),
            ExecMaskOp::XorSaveExec => (BinaryOperator::ExclusiveOr, false, false, false),
            ExecMaskOp::AndN2SaveExec | ExecMaskOp::AndN2WrExec => {
                (BinaryOperator::And, false, true, false)
            }
            ExecMaskOp::OrN2SaveExec => (BinaryOperator::InclusiveOr, false, true, false),
            ExecMaskOp::NandSaveExec => (BinaryOperator::And, false, false, true),
            ExecMaskOp::NorSaveExec => (BinaryOperator::InclusiveOr, false, false, true),
            ExecMaskOp::XnorSaveExec => (BinaryOperator::ExclusiveOr, false, false, true),
            ExecMaskOp::AndN1SaveExec | ExecMaskOp::AndN1WrExec => {
                (BinaryOperator::And, true, false, false)
            }
            ExecMaskOp::OrN1SaveExec => (BinaryOperator::InclusiveOr, true, false, false),
        };
        let lhs = if not_s { self.emit_bit_not(s) } else { s };
        let rhs = if not_e { self.emit_bit_not(old) } else { old };
        let raw = self.emit_bin(bin, lhs, rhs);
        let raw = if not_result {
            self.emit_bit_not(raw)
        } else {
            raw
        };
        let one = self.lit_u32(1);
        let new = self.emit_bin(BinaryOperator::And, raw, one);

        let saved = if matches!(write.op, ExecMaskOp::AndN1WrExec | ExecMaskOp::AndN2WrExec) {
            new
        } else {
            old
        };
        if write.wave64 {
            let zero = self.lit_u32(0);
            self.store_sdst_pair(sdst, saved, zero);
        } else if sdst == 106 {
            let zero = self.lit_u32(0);
            let cond = self.emit_bin(BinaryOperator::NotEqual, saved, zero);
            self.store_vcc(cond);
        } else {
            self.store_sgpr_u32(sdst, saved);
        }
        if let Some(local) = self.exec_local {
            self.store_local(local, new);
        }
        self.update_scc_nonzero(new);
        true
    }

    // -- Structured control flow (rdna2_cfg) --

    /// `true` while lowering code that WGSL uniformity analysis treats as non-uniform:
    /// any nested structured body, or code following a nested `return`, loop/dispatch exit,
    /// or non-uniform conditional `discard`.
    fn in_nonuniform_cf(&self) -> bool {
        (self.structured_cf && self.cf_depth > 0) || self.cf_nonuniform_return
    }

    /// `true` when the current block already ends in a control transfer, so further
    /// statements would be unreachable. Note: `Statement::Kill` (`discard;`) is NOT
    /// function-terminating in WGSL — a non-void fragment entry point must still `return`.
    fn body_terminated(&self) -> bool {
        matches!(
            self.func.body.last(),
            Some(Statement::Return { .. } | Statement::Break | Statement::Continue)
        )
    }

    fn push_stmt(&mut self, stmt: Statement) {
        self.func.body.push(stmt, Span::UNDEFINED);
    }

    /// Emit the stage-correct `return` (`return out;` for vertex/fragment, `return;` for
    /// compute), flushing any pending fragment `vm` export discard check beforehand.
    fn emit_stage_return(&mut self) {
        if self.stage == ShaderStage::Fragment && self.ps_pending_vm_discard {
            self.emit_fragment_exec_discard();
            self.ps_pending_vm_discard = false;
        }
        let out_local = match self.stage {
            ShaderStage::Vertex => self.vs_out_local,
            ShaderStage::Fragment => self.ps_out_local,
            ShaderStage::Compute => None,
        };
        let value = out_local.map(|local| self.load_local(local));
        self.push_stmt(Statement::Return { value });
        if self.cf_depth > 0 {
            self.cf_nonuniform_return = true;
        }
    }

    /// Lower `f` into a fresh nested block (one structured nesting level deeper).
    fn lower_nested(&mut self, f: impl FnOnce(&mut Self)) -> naga::Block {
        let saved = std::mem::replace(&mut self.func.body, naga::Block::new());
        let saved_pending_vm = self.ps_pending_vm_discard;
        self.cf_depth += 1;
        f(self);
        self.cf_depth -= 1;
        self.ps_pending_vm_discard = saved_pending_vm;
        std::mem::replace(&mut self.func.body, saved)
    }

    fn new_cf_local(&mut self, prefix: &str) -> Handle<LocalVariable> {
        let name = format!("{prefix}{}", self.cf_local_counter);
        self.cf_local_counter += 1;
        self.func.local_variables.append(
            LocalVariable {
                name: Some(name),
                ty: self.types.u32_ty,
                init: None,
            },
            Span::UNDEFINED,
        )
    }

    /// WGSL condition for "branch of `kind` is taken" (`scc`/`vcc` are `bool`,
    /// `exec_mask` is `u32`).
    fn branch_condition(&mut self, kind: BranchKind) -> Handle<Expression> {
        match kind {
            BranchKind::Unconditional => self.lit_bool(true),
            BranchKind::Scc1 => self.load_scc(),
            BranchKind::Vccnz => self.load_vcc(),
            BranchKind::Scc0 | BranchKind::Vccz => {
                let v = if kind == BranchKind::Scc0 {
                    self.load_scc()
                } else {
                    self.load_vcc()
                };
                self.emit_expr(Expression::Unary {
                    op: UnaryOperator::LogicalNot,
                    expr: v,
                })
            }
            BranchKind::Execz | BranchKind::Execnz => {
                let e = self.load_exec();
                let zero = self.lit_u32(0);
                let op = if kind == BranchKind::Execz {
                    BinaryOperator::Equal
                } else {
                    BinaryOperator::NotEqual
                };
                self.emit_bin(op, e, zero)
            }
        }
    }

    /// Translate every instruction of a basic block, including its trailing control
    /// instruction (branches count as translated: their control flow is structured).
    ///
    /// Register values never carry over between blocks as folded constants: every read
    /// re-loads the function-scope `var`, so values assigned on one path or loop iteration
    /// can never leak into a merge block or loop header.
    fn lower_basic_block(
        &mut self,
        id: BlockId,
        cfg: &ControlFlowGraph,
        insts: &[Rdna2Instruction],
    ) {
        let Some(block) = cfg.blocks.get(id) else {
            return;
        };
        for idx in block.instr_range.clone() {
            if self.body_terminated() {
                break;
            }
            if let Some(inst) = insts.get(idx) {
                self.translate_instruction(idx, inst);
            }
        }
    }

    /// Lower a structured control-flow tree from [`structure_cfg`] into naga IR.
    fn lower_structured(
        &mut self,
        node: &StructuredNode,
        cfg: &ControlFlowGraph,
        insts: &[Rdna2Instruction],
    ) {
        if self.body_terminated() {
            return;
        }
        match node {
            StructuredNode::Block(id) => self.lower_basic_block(*id, cfg, insts),
            StructuredNode::Seq(nodes) => {
                for n in nodes {
                    if self.body_terminated() {
                        break;
                    }
                    self.lower_structured(n, cfg, insts);
                }
            }
            StructuredNode::If {
                cond,
                then_branch,
                else_branch,
                ..
            } => {
                let condition = self.branch_condition(*cond);
                let accept = self.lower_nested(|s| s.lower_structured(then_branch, cfg, insts));
                let reject = match else_branch {
                    Some(e) => self.lower_nested(|s| s.lower_structured(e, cfg, insts)),
                    None => naga::Block::new(),
                };
                self.push_stmt(Statement::If {
                    condition,
                    accept,
                    reject,
                });
            }
            StructuredNode::Loop { body } => {
                let guard = self.new_cf_local("_pg6_loop");
                let zero = self.lit_u32(0);
                self.store_local(guard, zero);
                let body = self.lower_nested(|s| {
                    s.emit_iteration_guard(guard, STRUCTURED_LOOP_MAX_ITERATIONS);
                    s.lower_structured(body, cfg, insts);
                });
                self.push_stmt(Statement::Loop {
                    body,
                    continuing: naga::Block::new(),
                    break_if: None,
                });
                // WGSL uniformity analysis (§16.4): a structured RDNA2 loop exits on a conditional
                // `break` driven by mutable lane/scalar state, so `CF_after` is non-uniform.
                self.cf_nonuniform_return = true;
            }
            StructuredNode::Break => self.push_stmt(Statement::Break),
            StructuredNode::Continue => self.push_stmt(Statement::Continue),
            StructuredNode::Return => self.emit_stage_return(),
            StructuredNode::Dispatch {
                entry,
                blocks,
                max_iterations,
            } => {
                self.lower_dispatch(*entry, blocks, *max_iterations, cfg, insts);
                // Same WGSL §16.4 rule: dispatcher exits via conditional `if (pc == EXIT) { break; }`.
                self.cf_nonuniform_return = true;
            }
        }
    }

    /// `if (guard >= max) { break; } guard = guard + 1u;`
    fn emit_iteration_guard(&mut self, guard: Handle<LocalVariable>, max: u32) {
        let g = self.load_local(guard);
        let limit = self.lit_u32(max);
        let done = self.emit_bin(BinaryOperator::GreaterEqual, g, limit);
        let mut brk = naga::Block::new();
        brk.push(Statement::Break, Span::UNDEFINED);
        self.push_stmt(Statement::If {
            condition: done,
            accept: brk,
            reject: naga::Block::new(),
        });
        let one = self.lit_u32(1);
        let next = self.emit_bin(BinaryOperator::Add, g, one);
        self.store_local(guard, next);
    }

    /// Edge to `target` inside a dispatcher: program exit returns, member blocks set the
    /// program counter, anything else leaves the dispatcher.
    fn dispatch_transfer(
        &mut self,
        target: BlockId,
        members: &BTreeSet<BlockId>,
        pc: Handle<LocalVariable>,
        cfg: &ControlFlowGraph,
    ) {
        if Some(target) == cfg.exit_block {
            self.emit_stage_return();
        } else {
            let next = if members.contains(&target) {
                u32::try_from(target).unwrap_or(DISPATCH_EXIT_PC)
            } else {
                DISPATCH_EXIT_PC
            };
            let v = self.lit_u32(next);
            self.store_local(pc, v);
        }
    }

    /// Bounded `loop { switch (pc) { ... } }` fallback for irreducible regions.
    fn lower_dispatch(
        &mut self,
        entry: BlockId,
        blocks: &[BlockId],
        max_iterations: u32,
        cfg: &ControlFlowGraph,
        insts: &[Rdna2Instruction],
    ) {
        let members: BTreeSet<BlockId> = blocks
            .iter()
            .copied()
            .filter(|&b| {
                b < cfg.blocks.len() && u32::try_from(b).is_ok_and(|v| v != DISPATCH_EXIT_PC)
            })
            .collect();
        let pc = self.new_cf_local("_pg6_pc");
        let iter = self.new_cf_local("_pg6_iter");
        let entry_pc = if members.contains(&entry) {
            u32::try_from(entry).unwrap_or(DISPATCH_EXIT_PC)
        } else {
            DISPATCH_EXIT_PC
        };
        let v = self.lit_u32(entry_pc);
        self.store_local(pc, v);
        let zero = self.lit_u32(0);
        self.store_local(iter, zero);

        let body = self.lower_nested(|s| {
            s.emit_iteration_guard(iter, max_iterations);
            // if (pc == EXIT) { break; }
            let cur = s.load_local(pc);
            let exit = s.lit_u32(DISPATCH_EXIT_PC);
            let leave = s.emit_bin(BinaryOperator::Equal, cur, exit);
            let mut brk = naga::Block::new();
            brk.push(Statement::Break, Span::UNDEFINED);
            s.push_stmt(Statement::If {
                condition: leave,
                accept: brk,
                reject: naga::Block::new(),
            });

            let selector = s.load_local(pc);
            let mut cases = Vec::with_capacity(members.len() + 1);
            for &id in &members {
                let Some(block) = cfg.blocks.get(id) else {
                    continue;
                };
                let terminator = block.terminator;
                let case_body = s.lower_nested(|s| {
                    s.lower_basic_block(id, cfg, insts);
                    if s.body_terminated() {
                        return;
                    }
                    match terminator {
                        Terminator::End => s.emit_stage_return(),
                        Terminator::Fallthrough(t) | Terminator::Branch(t) => {
                            s.dispatch_transfer(t, &members, pc, cfg);
                        }
                        Terminator::CondBranch {
                            kind,
                            target,
                            fallthrough,
                        } => {
                            let condition = s.branch_condition(kind);
                            let accept =
                                s.lower_nested(|s| s.dispatch_transfer(target, &members, pc, cfg));
                            let reject = s.lower_nested(|s| {
                                s.dispatch_transfer(fallthrough, &members, pc, cfg);
                            });
                            s.push_stmt(Statement::If {
                                condition,
                                accept,
                                reject,
                            });
                        }
                    }
                });
                cases.push(SwitchCase {
                    value: SwitchValue::U32(u32::try_from(id).unwrap_or(DISPATCH_EXIT_PC)),
                    body: case_body,
                    fall_through: false,
                });
            }
            let mut default_body = naga::Block::new();
            let exit = s.lit_u32(DISPATCH_EXIT_PC);
            let ptr = s.raw_expr(Expression::LocalVariable(pc));
            default_body.push(
                Statement::Store {
                    pointer: ptr,
                    value: exit,
                },
                Span::UNDEFINED,
            );
            cases.push(SwitchCase {
                value: SwitchValue::Default,
                body: default_body,
                fall_through: false,
            });
            s.push_stmt(Statement::Switch { selector, cases });
        });
        self.push_stmt(Statement::Loop {
            body,
            continuing: naga::Block::new(),
            break_if: None,
        });
    }

    // -- Finalize function & module --

    fn finish(
        mut self,
        entry_name: String,
    ) -> (
        Module,
        usize,
        usize,
        Vec<String>,
        Vec<String>,
        Vec<WgslBindingInfo>,
        BTreeSet<(u32, u32)>,
        usize,
        usize,
    ) {
        // Emit stage return statement (unless structured lowering already ended the body
        // with one).
        if !self.body_terminated() {
            self.emit_stage_return();
        }

        let (naga_stage, workgroup_size) = match self.stage {
            ShaderStage::Vertex => (NagaStage::Vertex, [0, 0, 0]),
            ShaderStage::Fragment => (NagaStage::Fragment, [0, 0, 0]),
            ShaderStage::Compute => (NagaStage::Compute, self.workgroup_size),
        };

        self.module.entry_points.push(EntryPoint {
            name: entry_name,
            stage: naga_stage,
            early_depth_test: None,
            workgroup_size,
            workgroup_size_overrides: None,
            function: self.func,
            mesh_info: None,
            task_payload: None,
            incoming_ray_payload: None,
        });

        (
            self.module,
            self.translated_op_count,
            self.unsupported_op_count,
            self.unsupported_comments,
            self.note_comments,
            self.emitted_bindings,
            self.atomic_only_slots,
            self.cbv_merged_into_storage,
            self.uniform_promoted_to_storage,
        )
    }
}

/// Semantic-preserving post-Naga WGSL whitespace compaction:
/// - Normalizes `\r\n` / `\r` line endings to LF (`\n`).
/// - Strips leading and trailing horizontal whitespace (`' '` / `'\t'`) on every line
///   (removing Naga's 4-space-per-nesting-level indentation that accounts for ~40% of pack size).
/// - Drops empty/blank lines while preserving all `//` comments, intra-line token spacing
///   (`@group(0) @binding(N) var<...>`, `@compute @workgroup_size(...) fn`, etc.), and line
///   boundaries so every downstream C++/JS/Python parser and Dawn/Tint/Naga parses identically.
/// - Guarantees a single trailing LF on non-empty WGSL text.
pub fn compact_wgsl_whitespace(raw: &str) -> String {
    if raw.is_empty() {
        return String::new();
    }
    let mut out = String::with_capacity(raw.len());
    for line in raw.split('\n') {
        let line = line.strip_suffix('\r').unwrap_or(line);
        // Handle lone '\r' line breaks if any exist inside a chunk.
        for sub in line.split('\r') {
            let trimmed = sub.trim_matches(|c| c == ' ' || c == '\t');
            if !trimmed.is_empty() {
                out.push_str(trimmed);
                out.push('\n');
            }
        }
    }
    out
}

/// Skip WGSL whitespace, `//` line comments, and nested `/* ... */` block comments starting at `*i`.
fn skip_wgsl_ws_and_comments(bytes: &[u8], i: &mut usize) -> Result<(), Rdna2TranslateError> {
    let len = bytes.len();
    while *i < len {
        let b = bytes[*i];
        if b.is_ascii_whitespace() {
            *i += 1;
            continue;
        }
        if b == b'/' && *i + 1 < len && bytes[*i + 1] == b'/' {
            *i += 2;
            while *i < len && bytes[*i] != b'\n' {
                *i += 1;
            }
            continue;
        }
        if b == b'/' && *i + 1 < len && bytes[*i + 1] == b'*' {
            let mut depth = 1usize;
            *i += 2;
            while *i < len && depth > 0 {
                if bytes[*i] == b'/' && *i + 1 < len && bytes[*i + 1] == b'*' {
                    depth += 1;
                    *i += 2;
                } else if bytes[*i] == b'*' && *i + 1 < len && bytes[*i + 1] == b'/' {
                    depth -= 1;
                    *i += 2;
                } else {
                    *i += 1;
                }
            }
            if depth != 0 {
                return Err(Rdna2TranslateError::WgslParse(
                    "unterminated block comment in emitted WGSL".to_string(),
                ));
            }
            continue;
        }
        break;
    }
    Ok(())
}

/// Parse an unsigned integer attribute argument inside `( ... )`, e.g. `(0)`, `(0u)`, `(0x10)`.
fn parse_wgsl_attr_u32_arg(
    wgsl: &str,
    i: &mut usize,
    attr_name: &str,
) -> Result<u32, Rdna2TranslateError> {
    let bytes = wgsl.as_bytes();
    let len = bytes.len();
    skip_wgsl_ws_and_comments(bytes, i)?;
    if *i >= len || bytes[*i] != b'(' {
        return Err(Rdna2TranslateError::WgslParse(format!(
            "malformed @{attr_name} attribute: expected '(' in emitted WGSL"
        )));
    }
    *i += 1;
    skip_wgsl_ws_and_comments(bytes, i)?;
    let num_start = *i;
    let value = if *i + 2 <= len && bytes[*i] == b'0' && matches!(bytes[*i + 1], b'x' | b'X') {
        *i += 2;
        let hex_start = *i;
        while *i < len && bytes[*i].is_ascii_hexdigit() {
            *i += 1;
        }
        if *i == hex_start {
            return Err(Rdna2TranslateError::WgslParse(format!(
                "malformed @{attr_name} hex literal in emitted WGSL"
            )));
        }
        u32::from_str_radix(&wgsl[hex_start..*i], 16).map_err(|_| {
            Rdna2TranslateError::WgslParse(format!(
                "out-of-range @{attr_name} integer literal in emitted WGSL"
            ))
        })?
    } else {
        while *i < len && bytes[*i].is_ascii_digit() {
            *i += 1;
        }
        if *i == num_start {
            return Err(Rdna2TranslateError::WgslParse(format!(
                "malformed @{attr_name} attribute: expected non-negative integer in emitted WGSL"
            )));
        }
        wgsl[num_start..*i].parse::<u32>().map_err(|_| {
            Rdna2TranslateError::WgslParse(format!(
                "out-of-range @{attr_name} integer literal in emitted WGSL"
            ))
        })?
    };
    // Optional WGSL integer type suffix (`u` or `i`).
    if *i < len && matches!(bytes[*i], b'u' | b'i') {
        *i += 1;
    }
    skip_wgsl_ws_and_comments(bytes, i)?;
    // Optional trailing comma allowed by WGSL attribute grammar.
    if *i < len && bytes[*i] == b',' {
        *i += 1;
        skip_wgsl_ws_and_comments(bytes, i)?;
    }
    if *i >= len || bytes[*i] != b')' {
        return Err(Rdna2TranslateError::WgslParse(format!(
            "malformed @{attr_name} attribute: expected ')' in emitted WGSL"
        )));
    }
    *i += 1;
    Ok(value)
}

/// Commit a pending module-scope `@group(g) @binding(b)` pair into `seen_bindings`,
/// rejecting incomplete pairs or duplicate `(group, binding)` declarations.
fn commit_module_binding_pair(
    pending_group: &mut Option<u32>,
    pending_binding: &mut Option<u32>,
    seen_bindings: &mut BTreeSet<(u32, u32)>,
) -> Result<(), Rdna2TranslateError> {
    match (pending_group.take(), pending_binding.take()) {
        (Some(g), Some(b)) => {
            if !seen_bindings.insert((g, b)) {
                return Err(Rdna2TranslateError::WgslParse(format!(
                    "duplicate @group({g}) @binding({b}) declaration in emitted WGSL"
                )));
            }
            Ok(())
        }
        (Some(g), None) => Err(Rdna2TranslateError::WgslParse(format!(
            "@group({g}) declaration missing @binding attribute in emitted WGSL"
        ))),
        (None, Some(b)) => Err(Rdna2TranslateError::WgslParse(format!(
            "@binding({b}) declaration missing @group attribute in emitted WGSL"
        ))),
        (None, None) => Ok(()),
    }
}

/// Verify reflection metadata in `emitted_bindings` satisfies WebGPU invariants:
/// - Every `group < MAX_WEBGPU_BIND_GROUPS` (4)
/// - Every `(group, binding)` pair is unique
/// - Every `"uniform"` binding has a non-zero 16-byte-aligned `min_binding_size_bytes` and
///   consistent `highest_vec4_offset < min_binding_size_bytes / 16`
/// - Vertex shaders never declare writable `"storage"` or `"storage-texture"` bindings
fn validate_emitted_bindings(
    bindings: &[WgslBindingInfo],
    stage: ShaderStage,
) -> Result<(), Rdna2TranslateError> {
    let mut seen: BTreeSet<(u32, u32)> = BTreeSet::new();
    for b in bindings {
        if b.group >= MAX_WEBGPU_BIND_GROUPS {
            return Err(Rdna2TranslateError::WgslParse(format!(
                "binding `{}` uses @group({}) >= WebGPU baseline maxBindGroups ({MAX_WEBGPU_BIND_GROUPS})",
                b.name, b.group
            )));
        }
        if !seen.insert((b.group, b.binding)) {
            return Err(Rdna2TranslateError::WgslParse(format!(
                "duplicate reflection binding @group({}) @binding({}) (`{}`)",
                b.group, b.binding, b.name
            )));
        }
        if b.kind == "uniform" {
            let Some(min_bytes) = b.min_binding_size_bytes else {
                return Err(Rdna2TranslateError::WgslParse(format!(
                    "uniform binding `{}` missing min_binding_size_bytes",
                    b.name
                )));
            };
            if min_bytes == 0 || !min_bytes.is_multiple_of(16) {
                return Err(Rdna2TranslateError::WgslParse(format!(
                    "uniform binding `{}` has invalid non-16-byte-aligned size {min_bytes}",
                    b.name
                )));
            }
            let vec4_count = min_bytes / 16;
            let Some(highest) = b.highest_vec4_offset else {
                return Err(Rdna2TranslateError::WgslParse(format!(
                    "uniform binding `{}` missing highest_vec4_offset",
                    b.name
                )));
            };
            if highest >= vec4_count {
                return Err(Rdna2TranslateError::WgslParse(format!(
                    "uniform binding `{}` highest_vec4_offset ({highest}) >= vec4_count ({vec4_count})",
                    b.name
                )));
            }
        }
        if stage == ShaderStage::Vertex && matches!(b.kind, "storage" | "storage-texture") {
            return Err(Rdna2TranslateError::WgslParse(format!(
                "vertex stage illegally declares writable {} binding `{}`",
                b.kind, b.name
            )));
        }
    }
    Ok(())
}

/// Post-emit WGSL structural checks executed unconditionally after Naga emission:
/// - LF-only newlines (no `\r`)
/// - Balanced `{`/`}`, `(`/`)`, `[`/`]` delimiters and closed nested `/* ... */` comments
/// - No illegal module-scope `let` declarations
/// - No duplicate `@group(g) @binding(b)` pairs and no `@group(>= 4)`
/// - No disallowed module-scope `enable` directives (e.g. stray `enable f16;`)
/// - No non-finite float tokens (`nan`/`inf`/`infinity`) outside comments
/// - Present, non-empty entry point `fn <entry_point>(...) { ... }`
#[cfg(test)]
fn validate_emitted_wgsl_structure(
    wgsl: &str,
    entry_point: &str,
) -> Result<(), Rdna2TranslateError> {
    validate_emitted_wgsl_structure_with_options(wgsl, entry_point, false)
}

fn validate_emitted_wgsl_structure_with_options(
    wgsl: &str,
    entry_point: &str,
    allow_subgroups_enable: bool,
) -> Result<(), Rdna2TranslateError> {
    if wgsl.is_empty() {
        return Err(Rdna2TranslateError::WgslParse(
            "emitted WGSL output is empty".to_string(),
        ));
    }
    if wgsl.contains('\r') {
        return Err(Rdna2TranslateError::WgslParse(
            "emitted WGSL contains CR (\\r) newline characters".to_string(),
        ));
    }

    let bytes = wgsl.as_bytes();
    let len = bytes.len();
    let mut i = 0usize;
    let mut brace_depth: usize = 0;
    let mut paren_depth: usize = 0;
    let mut bracket_depth: usize = 0;
    let mut block_comment_depth: usize = 0;

    let mut pending_group: Option<u32> = None;
    let mut pending_binding: Option<u32> = None;
    let mut seen_bindings: BTreeSet<(u32, u32)> = BTreeSet::new();

    // Entry-point state machine:
    //   0 = idle at module scope
    //   1 = saw `fn` at module scope, expecting identifier
    //   2 = saw `fn <entry_point>`, waiting for opening `{` at depth 0 -> 1
    //   3 = inside entry point `{ ... }` body (brace_depth >= 1)
    let mut ep_state: u8 = 0;
    let mut ep_found = false;
    let mut ep_body_has_code = false;

    while i < len {
        let b = bytes[i];

        if block_comment_depth > 0 {
            if b == b'/' && i + 1 < len && bytes[i + 1] == b'*' {
                block_comment_depth += 1;
                i += 2;
            } else if b == b'*' && i + 1 < len && bytes[i + 1] == b'/' {
                block_comment_depth -= 1;
                i += 2;
            } else {
                i += 1;
            }
            continue;
        }

        if b == b'/' && i + 1 < len && bytes[i + 1] == b'/' {
            i += 2;
            while i < len && bytes[i] != b'\n' {
                i += 1;
            }
            continue;
        }

        if b == b'/' && i + 1 < len && bytes[i + 1] == b'*' {
            block_comment_depth = 1;
            i += 2;
            continue;
        }

        if b.is_ascii_whitespace() {
            i += 1;
            continue;
        }

        let at_module_scope = brace_depth == 0 && paren_depth == 0 && bracket_depth == 0;

        // Parse module-scope `@group(N)` and `@binding(M)` attributes to enforce uniqueness
        // and WebGPU baseline `maxBindGroups = 4`.
        if at_module_scope && b == b'@' {
            i += 1;
            skip_wgsl_ws_and_comments(bytes, &mut i)?;
            if i < len && (bytes[i].is_ascii_alphabetic() || bytes[i] == b'_') {
                let attr_start = i;
                i += 1;
                while i < len && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'_') {
                    i += 1;
                }
                let attr_name = &wgsl[attr_start..i];
                if attr_name == "group" {
                    let group_val = parse_wgsl_attr_u32_arg(wgsl, &mut i, "group")?;
                    if group_val >= MAX_WEBGPU_BIND_GROUPS {
                        return Err(Rdna2TranslateError::WgslParse(format!(
                            "@group({group_val}) exceeds WebGPU baseline maxBindGroups ({MAX_WEBGPU_BIND_GROUPS})"
                        )));
                    }
                    if pending_group.is_some() {
                        return Err(Rdna2TranslateError::WgslParse(
                            "duplicate @group attribute on single declaration in emitted WGSL"
                                .to_string(),
                        ));
                    }
                    pending_group = Some(group_val);
                } else if attr_name == "binding" {
                    let binding_val = parse_wgsl_attr_u32_arg(wgsl, &mut i, "binding")?;
                    if pending_binding.is_some() {
                        return Err(Rdna2TranslateError::WgslParse(
                            "duplicate @binding attribute on single declaration in emitted WGSL"
                                .to_string(),
                        ));
                    }
                    pending_binding = Some(binding_val);
                }
            }
            continue;
        }

        match b {
            b'{' => {
                if at_module_scope {
                    commit_module_binding_pair(
                        &mut pending_group,
                        &mut pending_binding,
                        &mut seen_bindings,
                    )?;
                }
                if ep_state == 3 {
                    ep_body_has_code = true;
                } else if ep_state == 2 && at_module_scope {
                    ep_state = 3;
                }
                brace_depth += 1;
                i += 1;
                continue;
            }
            b'}' => {
                if brace_depth == 0 {
                    return Err(Rdna2TranslateError::WgslParse(
                        "unbalanced closing '}' in emitted WGSL".to_string(),
                    ));
                }
                brace_depth -= 1;
                if ep_state == 3 && brace_depth == 0 {
                    ep_state = 0;
                }
                i += 1;
                continue;
            }
            b'(' => {
                if ep_state == 3 {
                    ep_body_has_code = true;
                }
                paren_depth += 1;
                i += 1;
                continue;
            }
            b')' => {
                if paren_depth == 0 {
                    return Err(Rdna2TranslateError::WgslParse(
                        "unbalanced closing ')' in emitted WGSL".to_string(),
                    ));
                }
                paren_depth -= 1;
                i += 1;
                continue;
            }
            b'[' => {
                if ep_state == 3 {
                    ep_body_has_code = true;
                }
                bracket_depth += 1;
                i += 1;
                continue;
            }
            b']' => {
                if bracket_depth == 0 {
                    return Err(Rdna2TranslateError::WgslParse(
                        "unbalanced closing ']' in emitted WGSL".to_string(),
                    ));
                }
                bracket_depth -= 1;
                i += 1;
                continue;
            }
            b';' if at_module_scope => {
                commit_module_binding_pair(
                    &mut pending_group,
                    &mut pending_binding,
                    &mut seen_bindings,
                )?;
                if ep_state == 1 || ep_state == 2 {
                    ep_state = 0;
                }
                i += 1;
                continue;
            }
            _ => {}
        }

        if ep_state == 3 {
            ep_body_has_code = true;
        }

        // Consume WGSL numeric literals (decimal, hex, float exponent, optional u/i/f/h suffix)
        // so numeric suffixes are never mis-tokenized as standalone identifiers.
        if b.is_ascii_digit() {
            if at_module_scope && ep_state == 1 {
                ep_state = 0;
            }
            let is_hex = b == b'0' && i + 1 < len && matches!(bytes[i + 1], b'x' | b'X');
            if is_hex {
                i += 2;
                while i < len && (bytes[i].is_ascii_hexdigit() || bytes[i] == b'.') {
                    i += 1;
                }
                if i < len && matches!(bytes[i], b'p' | b'P') {
                    i += 1;
                    if i < len && matches!(bytes[i], b'+' | b'-') {
                        i += 1;
                    }
                    while i < len && bytes[i].is_ascii_digit() {
                        i += 1;
                    }
                }
            } else {
                while i < len && (bytes[i].is_ascii_digit() || bytes[i] == b'.') {
                    i += 1;
                }
                if i < len && matches!(bytes[i], b'e' | b'E') {
                    i += 1;
                    if i < len && matches!(bytes[i], b'+' | b'-') {
                        i += 1;
                    }
                    while i < len && bytes[i].is_ascii_digit() {
                        i += 1;
                    }
                }
            }
            if i < len && matches!(bytes[i], b'u' | b'i' | b'f' | b'h') {
                i += 1;
            }
            continue;
        }

        if b.is_ascii_alphabetic() || b == b'_' {
            let start = i;
            i += 1;
            while i < len && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'_') {
                i += 1;
            }
            let ident = &wgsl[start..i];
            if ident.eq_ignore_ascii_case("nan")
                || ident.eq_ignore_ascii_case("inf")
                || ident.eq_ignore_ascii_case("infinity")
            {
                return Err(Rdna2TranslateError::WgslParse(format!(
                    "non-finite float token `{ident}` outside comments in emitted WGSL"
                )));
            }
            if at_module_scope {
                if ident == "let" {
                    return Err(Rdna2TranslateError::WgslParse(
                        "illegal module-scope `let` declaration in emitted WGSL".to_string(),
                    ));
                }
                if ident == "enable" {
                    if !allow_subgroups_enable {
                        return Err(Rdna2TranslateError::WgslParse(
                            "disallowed module-scope `enable` directive in baseline WebGPU WGSL"
                                .to_string(),
                        ));
                    }
                    skip_wgsl_ws_and_comments(bytes, &mut i)?;
                    if i >= len || !(bytes[i].is_ascii_alphabetic() || bytes[i] == b'_') {
                        return Err(Rdna2TranslateError::WgslParse(
                            "malformed `enable` directive in emitted WGSL".to_string(),
                        ));
                    }
                    let ext_start = i;
                    i += 1;
                    while i < len && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'_') {
                        i += 1;
                    }
                    let ext_ident = &wgsl[ext_start..i];
                    if ext_ident != "subgroups" {
                        return Err(Rdna2TranslateError::WgslParse(format!(
                            "disallowed module-scope `enable {ext_ident}` directive in emitted WGSL"
                        )));
                    }
                    skip_wgsl_ws_and_comments(bytes, &mut i)?;
                    if i >= len || bytes[i] != b';' {
                        return Err(Rdna2TranslateError::WgslParse(
                            "expected ';' after `enable subgroups` in emitted WGSL".to_string(),
                        ));
                    }
                    i += 1;
                    continue;
                }
                match ep_state {
                    0 if ident == "fn" => ep_state = 1,
                    1 => {
                        if ident == entry_point {
                            ep_found = true;
                            ep_state = 2;
                        } else {
                            ep_state = 0;
                        }
                    }
                    _ => {}
                }
            }
            continue;
        }

        if at_module_scope && ep_state == 1 {
            ep_state = 0;
        }
        i += 1;
    }

    commit_module_binding_pair(&mut pending_group, &mut pending_binding, &mut seen_bindings)?;

    if block_comment_depth != 0 {
        return Err(Rdna2TranslateError::WgslParse(
            "unterminated block comment in emitted WGSL".to_string(),
        ));
    }
    if brace_depth != 0 {
        return Err(Rdna2TranslateError::WgslParse(format!(
            "unbalanced opening '{{' in emitted WGSL (remaining depth {brace_depth})"
        )));
    }
    if paren_depth != 0 {
        return Err(Rdna2TranslateError::WgslParse(format!(
            "unbalanced opening '(' in emitted WGSL (remaining depth {paren_depth})"
        )));
    }
    if bracket_depth != 0 {
        return Err(Rdna2TranslateError::WgslParse(format!(
            "unbalanced opening '[' in emitted WGSL (remaining depth {bracket_depth})"
        )));
    }
    if !ep_found {
        return Err(Rdna2TranslateError::WgslParse(format!(
            "missing entry point `fn {entry_point}` in emitted WGSL"
        )));
    }
    if !ep_body_has_code {
        return Err(Rdna2TranslateError::WgslParse(format!(
            "entry point `{entry_point}` has an empty body in emitted WGSL"
        )));
    }

    Ok(())
}

/// Returns `true` when `module` contains any Naga subgroup statement or subgroup built-in.
fn module_uses_subgroups(module: &Module) -> bool {
    fn block_has_subgroup(block: &naga::Block) -> bool {
        block.iter().any(|stmt| match stmt {
            Statement::SubgroupBallot { .. }
            | Statement::SubgroupCollectiveOperation { .. }
            | Statement::SubgroupGather { .. } => true,
            Statement::Block(inner) => block_has_subgroup(inner),
            Statement::If { accept, reject, .. } => {
                block_has_subgroup(accept) || block_has_subgroup(reject)
            }
            Statement::Switch { cases, .. } => cases.iter().any(|c| block_has_subgroup(&c.body)),
            Statement::Loop {
                body, continuing, ..
            } => block_has_subgroup(body) || block_has_subgroup(continuing),
            _ => false,
        })
    }

    let has_builtin = module.entry_points.iter().any(|ep| {
        ep.function.arguments.iter().any(|arg| {
            matches!(
                arg.binding,
                Some(Binding::BuiltIn(
                    BuiltIn::SubgroupInvocationId
                        | BuiltIn::SubgroupSize
                        | BuiltIn::SubgroupId
                        | BuiltIn::NumSubgroups
                ))
            )
        })
    });
    has_builtin
        || module
            .entry_points
            .iter()
            .map(|ep| &ep.function)
            .chain(module.functions.iter().map(|(_, f)| f))
            .any(|f| block_has_subgroup(&f.body))
}

/// Baseline WebGPU capabilities permitted during Naga validation.
/// `SHADER_FLOAT16_IN_FLOAT32` enables core WGSL `pack2x16float`/`unpack2x16float`
/// built-ins (no `enable f16;` extension required in WebGPU), and `CUBE_ARRAY_TEXTURES`
/// enables core WebGPU 1.0 `texture_cube_array`/`texture_depth_cube_array` types.
const BASELINE_WEBGPU_CAPABILITIES: Capabilities =
    Capabilities::SHADER_FLOAT16_IN_FLOAT32.union(Capabilities::CUBE_ARRAY_TEXTURES);

/// Strip temporary Naga-validation stub definitions for runtime-owned RT prelude helpers
/// (`fn pg6_load32_stub(...) { ... }` and `fn pg6_bvh_intersect(...) { ... }`) from emitted WGSL
/// and rewrite `pg6_load32_stub(` call sites to `pg6_load32(`.
fn strip_rt_prelude_stubs(wgsl: &str) -> String {
    const STUB_PREFIXES: &[&str] = &["fn pg6_load32_stub(", "fn pg6_bvh_intersect("];
    let bytes = wgsl.as_bytes();
    let len = bytes.len();
    let mut out = String::with_capacity(len);
    let mut i = 0usize;
    let mut brace_depth = 0usize;
    let mut block_comment_depth = 0usize;

    while i < len {
        if block_comment_depth > 0 {
            if bytes[i] == b'/' && i + 1 < len && bytes[i + 1] == b'*' {
                block_comment_depth += 1;
                out.push_str("/*");
                i += 2;
            } else if bytes[i] == b'*' && i + 1 < len && bytes[i + 1] == b'/' {
                block_comment_depth -= 1;
                out.push_str("*/");
                i += 2;
            } else {
                let ch = wgsl[i..].chars().next().unwrap();
                out.push(ch);
                i += ch.len_utf8();
            }
            continue;
        }
        if bytes[i] == b'/' && i + 1 < len && bytes[i + 1] == b'/' {
            let start = i;
            i += 2;
            while i < len && bytes[i] != b'\n' {
                i += 1;
            }
            out.push_str(&wgsl[start..i]);
            continue;
        }
        if bytes[i] == b'/' && i + 1 < len && bytes[i + 1] == b'*' {
            block_comment_depth = 1;
            out.push_str("/*");
            i += 2;
            continue;
        }

        if brace_depth == 0
            && (i == 0
                || matches!(bytes[i - 1], b'\n' | b'\r' | b' ' | b'\t'))
            && STUB_PREFIXES.iter().any(|p| wgsl[i..].starts_with(p))
        {
            let mut j = i;
            while j < len && bytes[j] != b'{' {
                j += 1;
            }
            if j < len && bytes[j] == b'{' {
                let mut depth = 1usize;
                j += 1;
                while j < len && depth > 0 {
                    if bytes[j] == b'{' {
                        depth += 1;
                    } else if bytes[j] == b'}' {
                        depth -= 1;
                    }
                    j += 1;
                }
                while j < len && matches!(bytes[j], b'\r' | b'\n') {
                    j += 1;
                }
                i = j;
                continue;
            }
        }

        if bytes[i] == b'{' {
            brace_depth += 1;
        } else if bytes[i] == b'}' {
            brace_depth = brace_depth.saturating_sub(1);
        }
        let ch = wgsl[i..].chars().next().unwrap();
        out.push(ch);
        i += ch.len_utf8();
    }
    out.replace("pg6_load32_stub(", "pg6_load32(")
}

/// Translate a raw little-endian AMD RDNA2 (GFX10.3 / Scarlett) shader binary into
/// a complete, Naga-validated WebGPU WGSL module.
///
/// Never panics on empty, truncated, misaligned, or arbitrary input byte slices.
pub fn translate_rdna2_to_wgsl(
    bytes: &[u8],
    options: &Rdna2TranslateOptions,
) -> Result<Rdna2WgslOutput, Rdna2TranslateError> {
    let instructions = decode_program(bytes);
    let summary = analyze_instructions(bytes, &instructions);
    let plan = plan_program(&summary, &instructions, options);

    let mut emitter = IrEmitter::new(&plan);
    let active = &instructions[..plan.active_inst_count];
    let cfg = ControlFlowGraph::from_instructions(active);
    let real_block_count = cfg.blocks.iter().filter(|b| !b.synthetic_exit).count();
    let has_branch = active.iter().any(|inst| {
        matches!(inst.detail, Rdna2Detail::Sopp { op, .. } if BranchKind::from_sopp_op(op).is_some())
    });
    if real_block_count <= 1 && !has_branch {
        // Fast path: straight-line program.
        for (inst_idx, inst) in active.iter().enumerate() {
            emitter.translate_instruction(inst_idx, inst);
        }
    } else {
        // Lift SOPP branches into structured WGSL control flow (if / loop / bounded
        // dispatcher). Every register is a function-scope `var` declared up front.
        emitter.structured_cf = true;
        let tree = structure_cfg(&cfg);
        emitter.lower_structured(&tree, &cfg, active);
    }

    let entry_point = plan.entry_point.clone();
    let (
        mut module,
        translated_op_count,
        unsupported_op_count,
        unsupported_comments,
        note_comments,
        mut bindings,
        atomic_only_slots,
        cbv_merged_into_storage,
        uniform_promoted_to_storage,
    ) = emitter.finish(entry_point.clone());

    // Post-lowering binding compaction (#2110): prune unreferenced globals (e.g. unreachable CFG
    // branches or unused dispatch arms), fold any remaining duplicate canonical bindings, and keep
    // reflection metadata 100% synchronized with the emitted WGSL.
    let mut binding_pack = compact_module_bindings(
        &mut module,
        &mut bindings,
        plan.rt_arena,
        plan.mesh_output.is_some(),
        &atomic_only_slots,
        StageBindingLimits::webgpu_d3d12(),
    );
    binding_pack.duplicate_bindings_folded += plan.duplicate_bindings_folded;
    binding_pack.cbv_merged_into_storage += cbv_merged_into_storage;
    binding_pack.uniform_promoted_to_storage += uniform_promoted_to_storage;
    validate_emitted_bindings(&bindings, plan.stage)?;

    // Post-lowering Naga IR optimization (#2137, #2164, #2178): cancel identity/round-trip
    // bitcasts, fold pure constants/identities/dead branches, forward intra-block local loads,
    // CSE pure expressions and read-only global loads, and trim dead temps/emits prior to Naga
    // validation and WGSL emission.
    let ir_opt = optimize_module(&mut module);

    let uses_subgroups = module_uses_subgroups(&module);

    // Unconditional Naga validation against baseline WebGPU capabilities (plus `SUBGROUP` when
    // `WaveEmulMode::Subgroups` emitted hardware subgroup operations).
    let validation_caps = if uses_subgroups {
        BASELINE_WEBGPU_CAPABILITIES | Capabilities::SUBGROUP
    } else {
        BASELINE_WEBGPU_CAPABILITIES
    };
    let mut validator = Validator::new(ValidationFlags::all(), validation_caps);
    if uses_subgroups {
        validator
            .subgroup_stages(NagaShaderStages::COMPUTE | NagaShaderStages::FRAGMENT)
            .subgroup_operations(SubgroupOperationSet::all());
    }
    let module_info = validator
        .validate(&module)
        .map_err(|err| Rdna2TranslateError::NagaValidation(err.emit_to_string("")))?;

    let raw_wgsl_body = naga::back::wgsl::write_string(
        &module,
        &module_info,
        naga::back::wgsl::WriterFlags::empty(),
    )
    .map_err(|err| Rdna2TranslateError::WgslEmit(err.to_string()))?;
    let wgsl_body = if plan.rt_arena {
        strip_rt_prelude_stubs(&raw_wgsl_body)
    } else {
        raw_wgsl_body
    };

    // Prepend strictly sanitized WGSL header & graceful fallback opcode comments.
    let mut raw_wgsl = String::with_capacity(wgsl_body.len() + 256);
    let _ = writeln!(
        raw_wgsl,
        "// Translated from AMD RDNA2 (GFX10.3) by playgta6-shaders"
    );
    let _ = writeln!(
        raw_wgsl,
        "// hash: {} | stage: {} | translated_ops: {} | unsupported_ops: {}",
        format_shader_hash(summary.fnv1a_hash),
        plan.stage.as_str(),
        translated_op_count,
        unsupported_op_count
    );
    for comment in unsupported_comments.iter().chain(note_comments.iter()) {
        let single_line = comment.replace(['\r', '\n'], " ");
        let _ = writeln!(raw_wgsl, "{single_line}");
    }
    if uses_subgroups {
        raw_wgsl.push_str(WGSL_SUBGROUPS_ENABLE);
    }
    raw_wgsl.push('\n');
    raw_wgsl.push_str(&wgsl_body);

    // Compact post-Naga indentation/blank lines, normalize line endings to LF, and enforce
    // unconditional post-emit WGSL structural checks.
    let wgsl = compact_wgsl_whitespace(&raw_wgsl);
    validate_emitted_wgsl_structure_with_options(&wgsl, &entry_point, uses_subgroups)?;

    // When `naga/wgsl-in` is active (unit tests), additionally round-trip parse & validate the
    // final WGSL text (including comments) via `naga::front::wgsl::parse_str`. For `rt_arena`
    // shaders, prepend the runtime-owned v1 RT prelude before parsing, matching runtime behavior.
    #[cfg(test)]
    {
        const TEST_RT_PRELUDE_V1: &str = r#"// pg6 runtime prelude, version 1 (rt_bvh.h kPreludeVersion). Group 3, bindings 16-21: contract C3.
@group(3) @binding(16) var<storage, read_write> pg6_arena0: array<u32>;
@group(3) @binding(17) var<storage, read_write> pg6_arena1: array<u32>;
@group(3) @binding(18) var<storage, read_write> pg6_arena2: array<u32>;
@group(3) @binding(19) var<storage, read_write> pg6_arena3: array<u32>;
@group(3) @binding(20) var<storage, read> pg6_arena_dir: array<u32>;
@group(3) @binding(21) var<storage, read_write> pg6_rt_stats: array<atomic<u32>>;

fn pg6_load32(addr: vec2<u32>) -> u32 {
    let page = (addr.x >> 16u) | ((addr.y & 0xffu) << 16u);
    let t = pg6_arena_dir[page >> 12u];
    if (t == 0u) {
        atomicAdd(&pg6_rt_stats[0], 1u);
        return 0u;
    }
    let e = pg6_arena_dir[4096u + (t - 1u) * 4096u + (page & 0xfffu)];
    if ((e & 0x80000000u) == 0u) {
        atomicAdd(&pg6_rt_stats[0], 1u);
        return 0u;
    }
    let w = (e & 0x1fffffffu) * 16384u + ((addr.x & 0xffffu) >> 2u);
    switch ((e >> 29u) & 3u) {
        case 0u: { return pg6_arena0[w]; }
        case 1u: { return pg6_arena1[w]; }
        case 2u: { return pg6_arena2[w]; }
        default: { return pg6_arena3[w]; }
    }
}

fn pg6_add40(a: vec2<u32>, b: vec2<u32>) -> vec2<u32> {
    let lo = a.x + b.x;
    var carry = 0u;
    if (lo < a.x) { carry = 1u; }
    return vec2<u32>(lo, (a.y + b.y + carry) & 0xffu);
}

fn pg6_addr_off(a: vec2<u32>, off: u32) -> vec2<u32> {
    return pg6_add40(a, vec2<u32>(off, 0u));
}

fn pg6_f(a: vec2<u32>, off: u32) -> f32 {
    return bitcast<f32>(pg6_load32(pg6_addr_off(a, off)));
}

fn pg6_slab(mn: vec3<f32>, mx: vec3<f32>, o: vec3<f32>, inv: vec3<f32>, extent: f32) -> vec2<f32> {
    var lo = 0.0;
    var hi = extent;
    for (var a = 0u; a < 3u; a = a + 1u) {
        if (mn[a] > mx[a]) {
            return vec2<f32>(0.0, 0.0);
        }
        let t0 = (mn[a] - o[a]) * inv[a];
        let t1 = (mx[a] - o[a]) * inv[a];
        if (t0 != t0 || t1 != t1) {
            continue;
        }
        var a0 = t1;
        var a1 = t0;
        if (t0 < t1) {
            a0 = t0;
            a1 = t1;
        }
        if (a0 > lo) { lo = a0; }
        if (a1 < hi) { hi = a1; }
    }
    if (lo <= hi) {
        return vec2<f32>(1.0, lo);
    }
    return vec2<f32>(0.0, 0.0);
}

fn pg6_tri_miss() -> vec4<u32> {
    return vec4<u32>(0x7f800000u, 0x3f800000u, 0u, 0u);
}

fn pg6_vec_nan(v: vec3<f32>) -> bool {
    return v.x != v.x || v.y != v.y || v.z != v.z;
}

fn pg6_triangle(addr: vec2<u32>, kind: u32, o: vec3<f32>, d: vec3<f32>) -> vec4<u32> {
    var vi = vec3<u32>(0u, 1u, 2u);
    if (kind == 1u) { vi = vec3<u32>(1u, 3u, 2u); }
    if (kind == 2u) { vi = vec3<u32>(2u, 3u, 4u); }
    if (kind == 3u) { vi = vec3<u32>(2u, 4u, 0u); }
    var v: array<vec3<f32>, 3>;
    for (var i = 0u; i < 3u; i = i + 1u) {
        let b = vi[i] * 12u;
        v[i] = vec3<f32>(pg6_f(addr, b), pg6_f(addr, b + 4u), pg6_f(addr, b + 8u)) - o;
    }
    var kz = 0u;
    var az = abs(d.x);
    if (abs(d.y) > az) { kz = 1u; az = abs(d.y); }
    if (abs(d.z) > az) { kz = 2u; }
    let dz = d[kz];
    if (dz == 0.0) {
        return pg6_tri_miss();
    }
    var kx = (kz + 1u) % 3u;
    var ky = (kx + 1u) % 3u;
    if (dz < 0.0) {
        let t = kx;
        kx = ky;
        ky = t;
    }
    let sx = d[kx] / dz;
    let sy = d[ky] / dz;
    let sz = 1.0 / dz;
    var px: array<f32, 3>;
    var py: array<f32, 3>;
    var pz: array<f32, 3>;
    for (var i = 0u; i < 3u; i = i + 1u) {
        px[i] = v[i][kx] - sx * v[i][kz];
        py[i] = v[i][ky] - sy * v[i][kz];
        pz[i] = sz * v[i][kz];
    }
    let u = px[2] * py[1] - py[2] * px[1];
    let vv = px[0] * py[2] - py[0] * px[2];
    let w = px[1] * py[0] - py[1] * px[0];
    if ((u < 0.0 || vv < 0.0 || w < 0.0) && (u > 0.0 || vv > 0.0 || w > 0.0)) {
        return pg6_tri_miss();
    }
    let det = u + vv + w;
    let t_num = u * pz[0] + vv * pz[1] + w * pz[2];
    if (det == 0.0 || det != det || t_num != t_num || u != u || vv != vv || w != w) {
        return pg6_tri_miss();
    }
    let sel = (pg6_load32(pg6_addr_off(addr, 60u)) >> (8u * kind)) & 0xffu;
    var wt = array<f32, 4>(u, vv, w, 0.0);
    return vec4<u32>(bitcast<u32>(t_num), bitcast<u32>(det), bitcast<u32>(wt[sel & 3u]),
                     bitcast<u32>(wt[(sel >> 2u) & 3u]));
}

fn pg6_bvh_intersect(desc: vec4<u32>, node: vec2<u32>, extent: f32, origin: vec3<f32>, dir: vec3<f32>,
                     inv_dir: vec3<f32>) -> vec4<u32> {
    let kind = node.x & 7u;
    if (kind >= 6u) {
        return pg6_tri_miss();
    }
    let nan_ray = extent != extent || pg6_vec_nan(origin) || pg6_vec_nan(dir) || pg6_vec_nan(inv_dir);
    let base = vec2<u32>(desc.x << 8u, ((desc.y & 0xffu) << 8u) | (desc.x >> 24u));
    let idx = vec2<u32>((node.x >> 3u) | (node.y << 29u), node.y >> 3u);
    let off = vec2<u32>(idx.x << 6u, (idx.y << 6u) | (idx.x >> 26u));
    let addr = pg6_add40(base, off);
    if (kind < 4u) {
        if (nan_ray) {
            return pg6_tri_miss();
        }
        return pg6_triangle(addr, kind, origin, dir);
    }
    if (nan_ray) {
        return vec4<u32>(0xffffffffu);
    }
    var ptr: array<u32, 4>;
    var key: array<f32, 4>;
    var hit: array<bool, 4>;
    for (var i = 0u; i < 4u; i = i + 1u) {
        ptr[i] = pg6_load32(pg6_addr_off(addr, 4u * i));
        var mn: vec3<f32>;
        var mx: vec3<f32>;
        if (kind == 5u) {
            let b = 16u + 24u * i;
            mn = vec3<f32>(pg6_f(addr, b), pg6_f(addr, b + 4u), pg6_f(addr, b + 8u));
            mx = vec3<f32>(pg6_f(addr, b + 12u), pg6_f(addr, b + 16u), pg6_f(addr, b + 20u));
        } else {
            let b = 16u + 12u * i;
            let a = unpack2x16float(pg6_load32(pg6_addr_off(addr, b)));
            let bb = unpack2x16float(pg6_load32(pg6_addr_off(addr, b + 4u)));
            let c = unpack2x16float(pg6_load32(pg6_addr_off(addr, b + 8u)));
            mn = vec3<f32>(a.x, a.y, bb.x);
            mx = vec3<f32>(bb.y, c.x, c.y);
        }
        key[i] = 0.0;
        hit[i] = false;
        if (ptr[i] != 0xffffffffu) {
            let s = pg6_slab(mn, mx, origin, inv_dir, extent);
            hit[i] = s.x > 0.5;
            key[i] = s.y;
        }
    }
    var out = vec4<u32>(0xffffffffu);
    let sort = (desc.y >> 31u) != 0u;
    for (var i = 0u; i < 4u; i = i + 1u) {
        if (!hit[i]) {
            continue;
        }
        var rank = i;
        if (sort) {
            rank = 0u;
            for (var j = 0u; j < 4u; j = j + 1u) {
                if (hit[j] && (key[j] < key[i] || (key[j] == key[i] && j < i))) {
                    rank = rank + 1u;
                }
            }
        }
        out[rank] = ptr[i];
    }
    return out;
}
"#;
        let stripped: String;
        let wgsl_for_naga = if uses_subgroups {
            // Naga 30's WGSL frontend parses subgroup builtins directly but rejects the
            // `enable subgroups;` directive line; strip the directive solely for Naga round-trip.
            stripped = wgsl.replacen(WGSL_SUBGROUPS_ENABLE, "", 1);
            &stripped
        } else {
            &wgsl
        };
        let combined: String;
        let parse_src = if plan.rt_arena {
            combined = format!("{TEST_RT_PRELUDE_V1}\n{wgsl_for_naga}");
            &combined
        } else {
            wgsl_for_naga
        };
        let reparsed = naga::front::wgsl::parse_str(parse_src)
            .map_err(|err| Rdna2TranslateError::WgslParse(err.emit_to_string(parse_src)))?;
        let mut revalidator = Validator::new(ValidationFlags::all(), validation_caps);
        if uses_subgroups {
            revalidator
                .subgroup_stages(NagaShaderStages::COMPUTE | NagaShaderStages::FRAGMENT)
                .subgroup_operations(SubgroupOperationSet::all());
        }
        revalidator
            .validate(&reparsed)
            .map_err(|err| Rdna2TranslateError::NagaValidation(err.emit_to_string(parse_src)))?;
    }

    let output_locations: Vec<u32> = match plan.stage {
        ShaderStage::Vertex => plan.vs_params.iter().map(|&p| u32::from(p)).collect(),
        ShaderStage::Fragment => plan.ps_mrts.iter().map(|&m| u32::from(m)).collect(),
        ShaderStage::Compute => {
            if plan.mesh_output.is_some() {
                plan.vs_params.iter().map(|&p| u32::from(p)).collect()
            } else {
                Vec::new()
            }
        }
    };

    let surviving_cbv_vec4_count = bindings
        .iter()
        .filter(|b| b.kind == "uniform")
        .filter_map(|b| b.min_binding_size_bytes.map(|bytes| bytes / 16))
        .max()
        .unwrap_or(0);
    let binding_summary = Rdna2BindingSummary {
        has_cbv: bindings.iter().any(|b| b.kind == "uniform"),
        cbv_vec4_count: surviving_cbv_vec4_count,
        has_texture_2d: bindings.iter().any(|b| b.kind == "texture_2d"),
        has_sampler: bindings
            .iter()
            .any(|b| matches!(b.kind, "sampler" | "sampler_comparison")),
        has_storage_buffer: bindings
            .iter()
            .any(|b| matches!(b.kind, "storage" | "read-only-storage")),
        has_storage_texture: bindings.iter().any(|b| b.kind == "storage-texture"),
        has_lds: plan.uses_lds,
        vertex_input_mode: plan.vertex_input_mode.as_str().to_string(),
        fragment_input_locations: plan.frag_attrs.iter().map(|&a| u32::from(a)).collect(),
        output_locations,
        exports_position: plan.stage == ShaderStage::Vertex || plan.mesh_output.is_some(),
        exports_depth: plan.stage == ShaderStage::Fragment && plan.ps_exports_depth,
    };

    let mut vertex_inputs: Vec<WgslVertexInputInfo> = if plan.stage == ShaderStage::Vertex
        && plan.vertex_input_mode == VertexInputMode::Attributes
    {
        plan.vertex_attrs
            .iter()
            .filter_map(|attr| {
                attr.byte_offset.map(|byte_offset| WgslVertexInputInfo {
                    location: attr.location,
                    vb_slot: attr.vb_slot,
                    byte_offset: u32::from(byte_offset),
                    components: attr.components,
                    component_type: attr.component_type,
                    fetch_format: attr.fetch_format,
                })
            })
            .collect()
    } else {
        Vec::new()
    };
    vertex_inputs.sort_by_key(|v| (v.location, v.vb_slot, v.byte_offset));

    let vs_outputs = if plan.stage == ShaderStage::Vertex {
        options
            .fssm_meta
            .as_ref()
            .map(|m| m.vs_outputs.clone())
            .unwrap_or_default()
    } else {
        Vec::new()
    };
    let ps_inputs = if plan.stage == ShaderStage::Fragment {
        options
            .fssm_meta
            .as_ref()
            .map(|m| m.ps_inputs.clone())
            .unwrap_or_default()
    } else {
        Vec::new()
    };

    Ok(Rdna2WgslOutput {
        wgsl,
        stage: plan.stage,
        entry_point,
        hash_fnv1a64: summary.fnv1a_hash,
        translated_op_count,
        unsupported_op_count,
        naga_validated: true,
        bindings,
        vertex_inputs,
        vs_outputs,
        ps_inputs,
        mesh_output: plan.mesh_output,
        rt_arena: plan.rt_arena,
        rt_prelude_version: if plan.rt_arena {
            Some(RT_PRELUDE_VERSION)
        } else {
            None
        },
        bvh_ops: plan.bvh_ops,
        raw_address: plan.raw_address,
        atomic64: plan.atomic64,
        uses_subgroups,
        binding_summary,
        binding_pack,
        ir_opt,
    })
}

// ---------------------------------------------------------------------------
// Unit tests
